.CODE

; =============================================================================
; Phase3Initialize
; Initialize Phase-3 Agent Kernel
; 
; RCX = phase1_ctx (QWORD)
; RDX = phase2_ctx (QWORD)
; Returns: RAX = AGENT_CONTEXT* (NULL on error)
; =============================================================================
Phase3Initialize PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    ; Validate inputs
    test rcx, rcx
    jz init_null_p1
    test rdx, rdx
    jz init_null_p2
    
    mov rbx, rcx                ; rbx = phase1_ctx
    mov rsi, rdx                ; rsi = phase2_ctx
    
    ; Allocate AGENT_CONTEXT (round to 64-byte boundary)
    mov rcx, SIZEOF AGENT_CONTEXT + 63
    and rcx, NOT 63
    mov edx, MEM_COMMIT or MEM_RESERVE
    mov r8d, PAGE_READWRITE
    call VirtualAlloc
    test rax, rax
    jz init_alloc_failed
    
    mov rdi, rax                ; rdi = context
    
    ; Zero-initialize
    mov rcx, rdi
    mov rdx, SIZEOF AGENT_CONTEXT
    call RtlZeroMemory
    
    ; Set magic and version
    mov [rdi].AGENT_CONTEXT.magic, AGENT_MAGIC
    mov [rdi].AGENT_CONTEXT.version, AGENT_VERSION
    mov [rdi].AGENT_CONTEXT.phase1_ctx, rbx
    mov [rdi].AGENT_CONTEXT.phase2_ctx, rsi
    
    ; Allocate KV slots
    mov rcx, MAX_KV_SLOTS * SIZEOF KV_SLOT
    mov r8d, MEM_COMMIT or MEM_RESERVE
    mov r9d, PAGE_READWRITE
    call VirtualAlloc
    test rax, rax
    jz init_kv_failed
    
    mov [rdi].AGENT_CONTEXT.kv_slots, rax
    
    ; Zero-init KV slots
    mov rcx, rax
    mov rdx, MAX_KV_SLOTS * SIZEOF KV_SLOT
    call RtlZeroMemory
    
    ; Initialize KV lock
    lea rcx, [rdi].AGENT_CONTEXT.kv_cache_lock
    call InitializeCriticalSection
    
    ; Allocate tool registry
    mov rcx, MAX_TOOLS * SIZEOF TOOL_DEFINITION
    mov r8d, MEM_COMMIT or MEM_RESERVE
    mov r9d, PAGE_READWRITE
    call VirtualAlloc
    test rax, rax
    jz init_tool_failed
    
    mov [rdi].AGENT_CONTEXT.tool_registry, rax
    mov [rdi].AGENT_CONTEXT.tool_count, 0
    
    ; Zero-init tools
    mov rcx, rax
    mov rdx, MAX_TOOLS * SIZEOF TOOL_DEFINITION
    call RtlZeroMemory
    
    ; Initialize tool lock
    lea rcx, [rdi].AGENT_CONTEXT.tool_lock
    call InitializeCriticalSection
    
    ; Initialize inference buffers
    mov rcx, MAX_SEQ_LEN * 4    ; Token IDs
    mov r8d, MEM_COMMIT or MEM_RESERVE
    mov r9d, PAGE_READWRITE
    call VirtualAlloc
    test rax, rax
    jz init_buf_failed
    mov [rdi].AGENT_CONTEXT.ie_input_buffer, rax
    
    mov rcx, MAX_SEQ_LEN * 4    ; Logits
    mov r8d, MEM_COMMIT or MEM_RESERVE
    mov r9d, PAGE_READWRITE
    call VirtualAlloc
    test rax, rax
    jz init_buf_failed
    mov [rdi].AGENT_CONTEXT.ie_output_buffer, rax
    
    ; Default backend
    mov [rdi].AGENT_CONTEXT.ie_backend_type, BACKEND_CPU
    mov [rdi].AGENT_CONTEXT.ie_vocab_size, MAX_VOCAB_SIZE
    
    ; Mark initialized
    mov [rdi].AGENT_CONTEXT.is_initialized, 1
    
    mov rax, rdi
    add rsp, 32
    pop rdi
    pop rsi
    pop rbx
    ret
    
init_buf_failed:
init_tool_failed:
init_kv_failed:
init_alloc_failed:
init_null_p2:
init_null_p1:
    xor eax, eax
    add rsp, 32
    pop rdi
    pop rsi
    pop rbx
    ret
    
Phase3Initialize ENDP

; =============================================================================
; GenerateTokens
; Generate tokens from prompt
; 
; RCX = context (AGENT_CONTEXT*)
; RDX = prompt (const char*)
; R8 = params (GENERATION_PARAMS*) or NULL
; Returns: EAX = 1 on success, 0 on error
; =============================================================================
GenerateTokens PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    ; Validate
    test rcx, rcx
    jz gen_fail
    cmp [rcx].AGENT_CONTEXT.is_initialized, 1
    jne gen_fail
    
    mov rbx, rcx                ; context
    mov rsi, rdx                ; prompt
    mov rdi, r8                 ; params
    
    ; Use defaults if no params
    test rdi, rdi
    jnz gen_have_params
    lea rdi, g_default_params
    
gen_have_params:
    ; Copy params to gen context
    lea rcx, [rbx].AGENT_CONTEXT.gc_params
    mov rdx, rdi
    mov r8d, SIZEOF GENERATION_PARAMS
    call RtlCopyMemory
    
    ; Mark generating
    mov [rbx].AGENT_CONTEXT.gc_is_generating, 1
    mov [rbx].AGENT_CONTEXT.gc_generated_tokens, 0
    
    ; Get start time
    call GetTickCount64
    mov [rbx].AGENT_CONTEXT.gc_start_time, rax
    
    ; Placeholder: Run generation loop
    ; In production, this would:
    ; 1. Encode prompt to tokens
    ; 2. Allocate KV slot
    ; 3. Run inference loop
    ; 4. Sample tokens with callbacks
    
    ; Update metrics
    mov eax, [rbx].AGENT_CONTEXT.gc_generated_tokens
    add [rbx].AGENT_CONTEXT.m_tokens_generated, rax
    
    mov [rbx].AGENT_CONTEXT.gc_is_generating, 0
    
    mov eax, 1
    add rsp, 32
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
    
gen_fail:
    xor eax, eax
    add rsp, 32
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
    
GenerateTokens ENDP

; =============================================================================
; AllocateKVSlot
; Allocate or reuse KV cache slot
; 
; RCX = context (AGENT_CONTEXT*)
; RDX = sequence_id (QWORD)
; R8D = context_len (DWORD)
; Returns: EAX = slot_index (-1 on failure)
; =============================================================================
AllocateKVSlot PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    push r13
    .pushreg r13
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    mov rbx, rcx                ; context
    mov r12, rdx                ; sequence_id
    mov r13d, r8d               ; context_len
    
    ; Lock KV cache
    lea rcx, [rbx].AGENT_CONTEXT.kv_cache_lock
    call EnterCriticalSection
    
    ; Search for existing slot
    mov rsi, [rbx].AGENT_CONTEXT.kv_slots
    xor edi, edi                ; slot index = 0
    
kv_search_loop:
    cmp edi, MAX_KV_SLOTS
    jge kv_search_free
    
    cmp [rsi].KV_SLOT.is_occupied, 0
    je kv_search_next
    
    mov rax, [rsi].KV_SLOT.sequence_id
    cmp rax, r12
    je kv_found_slot
    
kv_search_next:
    add rsi, SIZEOF KV_SLOT
    inc edi
    jmp kv_search_loop
    
kv_found_slot:
    ; Update metrics (hit)
    inc [rbx].AGENT_CONTEXT.m_kv_hits
    
    ; Unlock and return
    lea rcx, [rbx].AGENT_CONTEXT.kv_cache_lock
    call LeaveCriticalSection
    
    mov eax, edi
    add rsp, 32
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
    
kv_search_free:
    ; Search for free slot
    mov rsi, [rbx].AGENT_CONTEXT.kv_slots
    xor edi, edi
    
kv_free_loop:
    cmp edi, MAX_KV_SLOTS
    jge kv_full
    
    cmp [rsi].KV_SLOT.is_occupied, 0
    je kv_alloc_slot
    
    add rsi, SIZEOF KV_SLOT
    inc edi
    jmp kv_free_loop
    
kv_alloc_slot:
    ; Initialize slot
    mov [rsi].KV_SLOT.sequence_id, r12
    mov [rsi].KV_SLOT.context_len, r13d
    mov [rsi].KV_SLOT.max_len, MAX_SEQ_LEN
    mov [rsi].KV_SLOT.is_occupied, 1
    
    ; Allocate K cache
    mov rcx, KV_CACHE_SIZE_BYTES
    mov r8d, MEM_COMMIT or MEM_RESERVE
    mov r9d, PAGE_READWRITE
    call VirtualAlloc
    test rax, rax
    jz kv_alloc_fail
    mov [rsi].KV_SLOT.k_cache, rax
    
    ; Allocate V cache
    mov rcx, KV_CACHE_SIZE_BYTES
    mov r8d, MEM_COMMIT or MEM_RESERVE
    mov r9d, PAGE_READWRITE
    call VirtualAlloc
    test rax, rax
    jz kv_alloc_fail
    mov [rsi].KV_SLOT.v_cache, rax
    
    ; Update metrics (miss)
    inc [rbx].AGENT_CONTEXT.m_kv_misses
    
    ; Unlock and return
    lea rcx, [rbx].AGENT_CONTEXT.kv_cache_lock
    call LeaveCriticalSection
    
    mov eax, edi
    add rsp, 32
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
    
kv_alloc_fail:
kv_full:
    ; Unlock
    lea rcx, [rbx].AGENT_CONTEXT.kv_cache_lock
    call LeaveCriticalSection
    
    mov eax, -1
    add rsp, 32
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
    
AllocateKVSlot ENDP

; =============================================================================
; RegisterTool
; Register an agentic tool
; 
; RCX = context (AGENT_CONTEXT*)
; EDX = tool_type (DWORD)
; R8 = tool_name (const char*)
; R9 = description (const char*)
; [RSP+40] = handler_func (QWORD)
; Returns: EAX = 1 on success, 0 on error
; =============================================================================
RegisterTool PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    mov rbx, rcx                ; context
    mov esi, edx                ; tool_type
    mov rdi, r8                 ; tool_name
    
    ; Validate type
    cmp esi, TOOL_TYPE_CUSTOM
    ja reg_fail
    
    ; Lock registry
    lea rcx, [rbx].AGENT_CONTEXT.tool_lock
    call EnterCriticalSection
    
    ; Check if full
    mov eax, [rbx].AGENT_CONTEXT.tool_count
    cmp eax, MAX_TOOLS
    jge reg_full
    
    ; Get next slot
    mov rcx, [rbx].AGENT_CONTEXT.tool_registry
    imul rax, rax, SIZEOF TOOL_DEFINITION
    add rcx, rax
    
    ; Set tool type
    mov [rcx].TOOL_DEFINITION.tool_type, esi
    
    ; Copy tool_name field (64 bytes max)
    ; Use manual offset: tool_type(4) = field offset 4
    lea r10, [rcx + 4]
    push rcx
    mov rcx, r10
    mov rdx, rdi
    call lstrcpyA
    pop rcx
    
    ; Copy description
    ; description starts after name (4 + 64 = 68)
    lea rax, [rcx + 68]
    push rcx
    mov rcx, rax
    mov rdx, r9
    call lstrcpyA
    pop rcx
    
    ; Set handler
    mov rax, [rsp + 32 + 32]
    mov [rcx].TOOL_DEFINITION.handler_func, rax
    
    ; Mark registered
    mov [rcx].TOOL_DEFINITION.is_registered, 1
    
    ; Increment count
    inc [rbx].AGENT_CONTEXT.tool_count
    
    ; Unlock
    lea rcx, [rbx].AGENT_CONTEXT.tool_lock
    call LeaveCriticalSection
    
    mov eax, 1
    add rsp, 32
    pop rdi
    pop rsi
    pop rbx
    ret
    
reg_full:
    lea rcx, [rbx].AGENT_CONTEXT.tool_lock
    call LeaveCriticalSection
    
reg_fail:
    xor eax, eax
    add rsp, 32
    pop rdi
    pop rsi
    pop rbx
    ret
    
RegisterTool ENDP

; =============================================================================
; ExportMetrics
; Export metrics in simple text format
; 
; RCX = context (AGENT_CONTEXT*)
; RDX = output_buffer (char*)
; R8D = buffer_size (DWORD)
; Returns: EAX = bytes written
; =============================================================================
EXTERN sprintf_s:PROC

ExportMetrics PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 64
    .allocstack 64
    .endprolog
    
    mov rbx, rcx                ; AGENT_CONTEXT*
    mov rdi, rdx                ; output_buffer
    mov esi, r8d                ; buffer_size
    
    ; sprintf_s(dest, cnt, szMetricsFmt, tokens, kv_hits, kv_misses, errors)
    mov rcx, rdi
    mov edx, esi
    lea r8, szMetricsFmt
    mov r9, [rbx].AGENT_CONTEXT.m_tokens_generated
    mov rax, [rbx].AGENT_CONTEXT.m_kv_hits
    mov [rsp+32], rax
    mov rax, [rbx].AGENT_CONTEXT.m_kv_misses
    mov [rsp+40], rax
    mov rax, [rbx].AGENT_CONTEXT.m_errors
    mov [rsp+48], rax
    call sprintf_s
    test eax, eax
    jns @@metrics_done
    xor eax, eax
@@metrics_done:
    
    add rsp, 64
    pop rdi
    pop rsi
    pop rbx
    ret
    
ExportMetrics ENDP

; =============================================================================
; Phase3Shutdown
; Clean up all Phase-3 resources
; 
; RCX = context (AGENT_CONTEXT*)
; Returns: (void)
; =============================================================================
Phase3Shutdown PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    test rcx, rcx
    jz shutdown_done
    
    mov rbx, rcx
    
    ; Free KV slots
    mov rcx, [rbx].AGENT_CONTEXT.kv_slots
    test rcx, rcx
    jz skip_free_kv
    
    ; Free individual K/V cache buffers (k_cache and v_cache) in each slot
    push r12
    push r13
    mov r12, rcx                            ; save kv_slots base pointer
    xor r13d, r13d                          ; slot index = 0
kv_slot_buf_loop:
    cmp r13d, MAX_KV_SLOTS
    jge kv_slot_buf_done

    mov eax, r13d
    imul eax, SIZEOF KV_SLOT
    mov rcx, (KV_SLOT PTR [r12 + rax]).k_cache
    test rcx, rcx
    jz kv_skip_k_slot
    mov rdx, MEM_RELEASE
    xor r8d, r8d
    call VirtualFree
kv_skip_k_slot:
    mov eax, r13d
    imul eax, SIZEOF KV_SLOT
    mov rcx, (KV_SLOT PTR [r12 + rax]).v_cache
    test rcx, rcx
    jz kv_skip_v_slot
    mov rdx, MEM_RELEASE
    xor r8d, r8d
    call VirtualFree
kv_skip_v_slot:
    inc r13d
    jmp kv_slot_buf_loop

kv_slot_buf_done:
    pop r13
    pop r12

    ; Free the kv_slots array itself
    mov rcx, [rbx].AGENT_CONTEXT.kv_slots
    mov rdx, MEM_RELEASE
    xor r8d, r8d
    call VirtualFree

skip_free_kv:
    ; Free tool registry
    mov rcx, [rbx].AGENT_CONTEXT.tool_registry
    test rcx, rcx
    jz skip_free_tools
    
    mov rdx, MEM_RELEASE
    xor r8d, r8d
    call VirtualFree
    
skip_free_tools:
    ; Free inference buffers
    mov rcx, [rbx].AGENT_CONTEXT.ie_input_buffer
    test rcx, rcx
    jz skip_free_input
    
    mov rdx, MEM_RELEASE
    xor r8d, r8d
    call VirtualFree
    
skip_free_input:
    mov rcx, [rbx].AGENT_CONTEXT.ie_output_buffer
    test rcx, rcx
    jz skip_free_output
    
    mov rdx, MEM_RELEASE
    xor r8d, r8d
    call VirtualFree
    
skip_free_output:
    ; Delete critical sections
    lea rcx, [rbx].AGENT_CONTEXT.kv_cache_lock
    call DeleteCriticalSection
    
    lea rcx, [rbx].AGENT_CONTEXT.tool_lock
    call DeleteCriticalSection
    
    ; Free context itself
    mov rcx, rbx
    mov rdx, MEM_RELEASE
    xor r8d, r8d
    call VirtualFree
    
shutdown_done:
    add rsp, 32
    pop rbx
    ret
    
Phase3Shutdown ENDP

END
 ; =============================================================================
; RawrXD_Absolutely_Complete.asm
; ZERO MISSING LOGIC - EVERY SINGLE INSTRUCTION EXPLICIT
; =============================================================================
; Architecture: x86-64 (AMD64)
; Purpose: Complete low-level system detection and control
; Build: ml64 /c /Zi /W3 /nologo RawrXD_Absolutely_Complete.asm
;        link /SUBSYSTEM:CONSOLE /MACHINE:X64 /DEBUG RawrXD_Absolutely_Complete.obj kernel32.lib user32.lib advapi32.lib ntdll.lib
; =============================================================================

OPTION CASEMAP:NONE
OPTION FRAME:AUTO

; =============================================================================
; COMPLETE EXTERNAL API IMPORTS
; =============================================================================

includelib kernel32.lib
includelib user32.lib
includelib advapi32.lib
includelib ntdll.lib

EXTERN GetModuleHandleA: PROC
EXTERN GetCurrentProcess: PROC
EXTERN GetCurrentThread: PROC
EXTERN GetCurrentProcessId: PROC
EXTERN GetCurrentThreadId: PROC
EXTERN GetSystemInfo: PROC
EXTERN GlobalMemoryStatusEx: PROC
EXTERN QueryPerformanceCounter: PROC
EXTERN QueryPerformanceFrequency: PROC
EXTERN GetProcessAffinityMask: PROC
EXTERN SetThreadAffinityMask: PROC
EXTERN GetPriorityClass: PROC
EXTERN SetThreadPriority: PROC
EXTERN GetSystemDirectoryW: PROC
EXTERN GetWindowsDirectoryW: PROC
EXTERN GetComputerNameW: PROC
EXTERN SetLastError: PROC
EXTERN GetLastError: PROC
EXTERN FormatMessageW: PROC
EXTERN ExitProcess: PROC
EXTERN Sleep: PROC
EXTERN CreateThread: PROC
EXTERN CloseHandle: PROC
EXTERN WaitForSingleObject: PROC
