    entries             DD  ?       ; Number of entries
    associativity       DD  ?       ; Associativity
    type                DD  ?       ; 0=Instruction, 1=Data, 2=Unified
    pad                 DD  ?       ; Padding
TLB_INFO ENDS

; NUMA node information
