.CODE

; =============================================================================
; UTILITY: Time_GetTicks - Get current timestamp counter
; =============================================================================
Time_GetTicks PROC
    rdtsc                               ; EDX:EAX = TSC
    shl rdx, 32
    or rax, rdx
    ret
Time_GetTicks ENDP

