    setc [r15].CPU_FEATURES.pcid
    bt r13d, 18
    setc [r15].CPU_FEATURES.dca
    bt r13d, 19
    setc [r15].CPU_FEATURES.sse41
    bt r13d, 20
    setc [r15].CPU_FEATURES.sse42
    bt r13d, 21
    setc [r15].CPU_FEATURES.x2apic
    bt r13d, 22
