    bt r13d, 31
    setc [r15].CPU_FEATURES.hypervisor
    
    ; === Extended Features (Leaf 7, Sub-leaf 0) ===
    mov eax, 7
    xor ecx, ecx
    cpuid
    
    mov r12d, ebx                       ; EBX extended features
    mov r13d, ecx                       ; ECX extended features
