.code

;==============================================================================
; SECTION 1: COMPILER ENGINE DESTRUCTION
;==============================================================================

CompilerEngine_Destroy PROC FRAME engine:QWORD
    LOCAL pEngine:QWORD
    LOCAL hHeap:QWORD
    LOCAL i:DWORD
    LOCAL pWorker:QWORD
    
    push rbx
    push rsi
    push rdi
    push r12
    sub rsp, 32
    
    .ENDPROLOG
    
    mov pEngine, rcx
    test rcx, rcx
    jz @@done
    
    mov rbx, pEngine
    mov rax, [rbx]
    mov hHeap, rax
    
    ; Signal cancellation
    mov DWORD PTR [rbx + 8], 1
    
    ; Shutdown workers
    xor esi, esi
@@shutdown_worker:
    cmp esi, DWORD PTR [rbx + 24]
    jge @@workers_done
    
    lea rdi, [rbx + 32]
    mov rax, [rdi + rsi * 8]
    test rax, rax
    jz @@next_worker
    
    mov pWorker, rax
    mov rcx, [rax + 16]
    call SetEvent
    
    mov rcx, [pWorker + 8]
    mov edx, 5000
    call WaitForSingleObject
    
    cmp eax, WAIT_TIMEOUT
    jne @@close_handles
    
    mov rcx, [pWorker + 8]
    mov edx, 1
    call TerminateThread
    
@@close_handles:
    mov rcx, [pWorker + 8]
    call CloseHandle
    mov rcx, [pWorker + 16]
    call CloseHandle
    mov rcx, [pWorker + 24]
    call CloseHandle
    mov rcx, [pWorker + 32]
    call CloseHandle
    
    mov rcx, hHeap
    xor edx, edx
    mov r8, pWorker
    call HeapFree
    
@@next_worker:
    inc esi
    jmp @@shutdown_worker
    
@@workers_done:
    ; Free engine structure
    mov rcx, hHeap
    xor edx, edx
    mov r8, pEngine
    call HeapFree
    
    mov rcx, hHeap
    call HeapDestroy
    
    mov g_pCompilerEngine, 0
    
@@done:
    mov eax, 1
    add rsp, 32
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
CompilerEngine_Destroy ENDP

;==============================================================================
; SECTION 2: OPTION VALIDATION
;==============================================================================

CompilerEngine_ValidateOptions PROC FRAME engine:QWORD, options:QWORD, result:QWORD
    LOCAL pEngine:QWORD
    LOCAL pOptions:QWORD
    LOCAL pResult:QWORD
    LOCAL valid:DWORD
    
    push rbx
    push rsi
    sub rsp, 40
    
    .ENDPROLOG
    
    mov pEngine, rcx
    mov pOptions, rdx
    mov pResult, r8
    
    mov valid, 1
    mov rbx, pOptions
    
    ; Check source path
    cmp BYTE PTR [rbx], 0
    jne @@check_exists
    
    mov valid, 0
    jmp @@done
    
@@check_exists:
    mov rcx, rbx
    call File_Exists
    test eax, eax
    jnz @@validate_arch
    
    mov valid, 0
    
@@validate_arch:
    mov eax, DWORD PTR [rbx + MAX_PATH + 4]
    cmp eax, TARGET_AUTO
    jle @@done
    
    mov valid, 0
    
@@done:
    mov eax, valid
    add rsp, 40
    pop rsi
    pop rbx
    ret
CompilerEngine_ValidateOptions ENDP

;==============================================================================
; SECTION 3: SYNCHRONOUS COMPILATION
;==============================================================================

CompilerEngine_CompileSync PROC FRAME engine:QWORD, options:QWORD, result:QWORD
    LOCAL pEngine:QWORD
    LOCAL pOptions:QWORD
    LOCAL pResult:QWORD
    
    push rbx
    push rsi
    sub rsp, 40
    
    .ENDPROLOG
    
    mov pEngine, rcx
    mov pOptions, rdx
    mov pResult, r8
    
    mov rbx, pResult
    mov DWORD PTR [rbx], 0
    
    ; Stage 1: Lexing
    mov rcx, pEngine
    mov rdx, pOptions
    mov r8, pResult
    call CompilerEngine_StageLexing
    test eax, eax
    jz @@failed
    
    ; Stage 2: Parsing
    mov rcx, pEngine
    mov rdx, pOptions
    mov r8, pResult
    call CompilerEngine_StageParsing
    test eax, eax
    jz @@failed
    
    ; Stage 3: Semantic
    mov rcx, pEngine
    mov rdx, pOptions
    mov r8, pResult
    call CompilerEngine_StageSemantic
    test eax, eax
    jz @@failed
    
    ; Stage 4: IR Generation
    mov rcx, pEngine
    mov rdx, pOptions
    mov r8, pResult
    call CompilerEngine_StageIRGen
    test eax, eax
    jz @@failed
    
    ; Stage 5: Optimization
    mov rcx, pEngine
    mov rdx, pOptions
    mov r8, pResult
    call CompilerEngine_StageOptimize
    
    ; Stage 6: Code Generation
    mov rcx, pEngine
    mov rdx, pOptions
    mov r8, pResult
    call CompilerEngine_StageCodegen
    test eax, eax
    jz @@failed
    
    ; Stage 7: Assembly
    mov rcx, pEngine
    mov rdx, pOptions
    mov r8, pResult
    call CompilerEngine_StageAssembly
    test eax, eax
    jz @@failed
    
    ; Stage 8: Linking
    mov rcx, pEngine
    mov rdx, pOptions
    mov r8, pResult
    call CompilerEngine_StageLinking
    test eax, eax
    jz @@failed
    
    mov DWORD PTR [rbx], 1
    mov DWORD PTR [rbx + 4], STAGE_COMPLETE
    mov eax, 1
    jmp @@done
    
@@failed:
    xor eax, eax
    
@@done:
    add rsp, 40
    pop rsi
    pop rbx
    ret
CompilerEngine_CompileSync ENDP

;==============================================================================
; SECTION 4: FILE I/O UTILITIES
;==============================================================================

File_ReadAllText PROC FRAME path:QWORD, pSize:QWORD, pOutSize:QWORD
    LOCAL szPath:QWORD
    LOCAL hFile:QWORD
    LOCAL fileSize:QWORD
    LOCAL pBuffer:QWORD
    LOCAL bytesRead:DWORD
    
    push rbx
    push rsi
    sub rsp, 40
    
    .ENDPROLOG
    
    mov szPath, rcx
    
    mov rcx, szPath
    mov edx, GENERIC_READ
    mov r8d, FILE_SHARE_READ
    xor r9d, r9d
    mov DWORD PTR [rsp + 32], OPEN_EXISTING
    call CreateFileA
    
    cmp rax, INVALID_HANDLE_VALUE
    je @@error
    mov hFile, rax
    
    lea rdx, fileSize
    mov rcx, hFile
    call GetFileSizeEx
    test eax, eax
    jz @@close_error
    
    mov rax, fileSize
    inc rax
    mov rcx, rax
    call GetProcessHeap
    mov rcx, rax
    xor edx, edx
    mov r8, fileSize
    inc r8
    call HeapAlloc
    test rax, rax
    jz @@close_error
    mov pBuffer, rax
    
    mov rcx, hFile
    mov rdx, pBuffer
    mov r8, fileSize
    lea r9, bytesRead
    xor eax, eax
    mov [rsp + 32], rax
    call ReadFile
    
    mov rcx, hFile
    call CloseHandle
    
    test eax, eax
    jz @@free_error
    
    mov rax, pBuffer
    jmp @@done
    
@@close_error:
    mov rcx, hFile
    call CloseHandle
    
@@free_error:
@@error:
    xor eax, eax
    
@@done:
    add rsp, 40
    pop rsi
    pop rbx
    ret
File_ReadAllText ENDP

File_WriteAllText PROC FRAME path:QWORD, pData:QWORD, size:QWORD
    LOCAL hFile:QWORD
    LOCAL bytesWritten:DWORD
    
    push rbx
    sub rsp, 32
    
    .ENDPROLOG
    
    mov rcx, path
    mov edx, GENERIC_WRITE
    xor r8d, r8d
    xor r9d, r9d
    mov DWORD PTR [rsp + 32], CREATE_ALWAYS
    call CreateFileA
    
    cmp rax, INVALID_HANDLE_VALUE
    je @@error
    mov hFile, rax
    
    mov rcx, hFile
    mov rdx, pData
    mov r8, size
    lea r9, bytesWritten
    xor eax, eax
    mov [rsp + 32], rax
    call WriteFile
    push rax
    
    mov rcx, hFile
    call CloseHandle
    pop rax
    
    jmp @@done
    
@@error:
    xor eax, eax
    
@@done:
    add rsp, 32
    pop rbx
    ret
File_WriteAllText ENDP

File_Exists PROC FRAME path:QWORD
    push rbx
    sub rsp, 32
    
    .ENDPROLOG
    
    mov rcx, path
    call GetFileAttributesA
    
    cmp eax, INVALID_FILE_ATTRIBUTES
    je @@not_found
    
    test eax, FILE_ATTRIBUTE_DIRECTORY
    jnz @@not_found
    
    mov eax, 1
    jmp @@done
    
@@not_found:
    xor eax, eax
    
@@done:
    add rsp, 32
    pop rbx
    ret
File_Exists ENDP

Directory_Create PROC FRAME path:QWORD
    push rbx
    sub rsp, 32
    
    .ENDPROLOG
    
    mov rcx, path
    xor edx, edx
    call CreateDirectoryA
    
    test eax, eax
    jnz @@success
    
    call GetLastError
    cmp eax, ERROR_ALREADY_EXISTS
    je @@success
    
    xor eax, eax
    jmp @@done
    
@@success:
    mov eax, 1
    
@@done:
    add rsp, 32
    pop rbx
    ret
Directory_Create ENDP

;==============================================================================
; SECTION 5: STRING UTILITIES
;==============================================================================

Str_Compare PROC FRAME s1:QWORD, s2:QWORD
    push rsi
    push rdi
    
    .ENDPROLOG
    
    mov rsi, rcx
    mov rdi, rdx
    
@@loop:
    movzx eax, BYTE PTR [rsi]
    movzx edx, BYTE PTR [rdi]
    
    cmp al, dl
    jne @@different
    
    test al, al
    jz @@equal
    
    inc rsi
    inc rdi
    jmp @@loop
    
@@equal:
    xor eax, eax
    jmp @@done
    
@@different:
    sub eax, edx
    
@@done:
    pop rdi
    pop rsi
    ret
Str_Compare ENDP

Str_Copy PROC FRAME dest:QWORD, src:QWORD, maxLen:QWORD
    push rsi
    push rdi
    
    .ENDPROLOG
    
    mov rdi, rcx
    mov rsi, rdx
    mov rcx, r8
    
@@loop:
    test rcx, rcx
    jz @@done
    
    movzx eax, BYTE PTR [rsi]
    mov [rdi], al
    
    test al, al
    jz @@done
    
    inc rsi
    inc rdi
    dec rcx
    jmp @@loop
    
@@done:
    mov BYTE PTR [rdi], 0
    
    pop rdi
    pop rsi
    ret
Str_Copy ENDP

Str_Length PROC FRAME s:QWORD
    push rbx
    
    .ENDPROLOG
    
    mov rbx, rcx
    xor rax, rax
    
@@loop:
    cmp BYTE PTR [rbx + rax], 0
    je @@done
    inc rax
    jmp @@loop
    
@@done:
    pop rbx
    ret
Str_Length ENDP

;==============================================================================
; SECTION 6: CACHE OPERATIONS
;==============================================================================

Cache_Store PROC FRAME engine:QWORD, key:QWORD, result:QWORD
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    sub rsp, 40
    .allocstack 40
    .endprolog

    mov rbx, rcx            ; COMPILER_ENGINE*
    mov rsi, rdx            ; key bytes (32)
    mov rdi, r8             ; COMPILE_RESULT*

    test rbx, rbx
    jz @@fail
    test rsi, rsi
    jz @@fail
    test rdi, rdi
    jz @@fail

    mov ecx, SIZEOF CACHE_ENTRY
    call malloc
    test rax, rax
    jz @@fail
    mov r12, rax            ; CACHE_ENTRY*

    ; Copy 32-byte key
    lea rdx, [r12].CACHE_ENTRY.key
    mov ecx, 32
@@copy_key:
    mov al, byte ptr [rsi]
    mov byte ptr [rdx], al
    inc rsi
    inc rdx
    dec ecx
    jnz @@copy_key

    ; Copy COMPILE_RESULT payload
    lea rdx, [r12].CACHE_ENTRY.result
    mov rax, rdi
    mov ecx, SIZEOF COMPILE_RESULT
@@copy_result:
    mov r10b, byte ptr [rax]
    mov byte ptr [rdx], r10b
    inc rax
    inc rdx
    dec ecx
    jnz @@copy_result

    mov byte ptr [r12].CACHE_ENTRY.valid, 1
    mov qword ptr [r12].CACHE_ENTRY.accessCount, 1
    mov qword ptr [r12].CACHE_ENTRY.timestamp, 0
    mov rax, [r12].CACHE_ENTRY.result.objectCodeSize
    mov [r12].CACHE_ENTRY.size, rax

    ; Insert at head
    mov rax, [rbx].COMPILER_ENGINE.cacheHead
    mov qword ptr [r12].CACHE_ENTRY.pPrev, 0
    mov [r12].CACHE_ENTRY.pNext, rax
    test rax, rax
    jz @@no_old_head
    mov [rax].CACHE_ENTRY.pPrev, r12
    jmp @@set_head
@@no_old_head:
    mov [rbx].COMPILER_ENGINE.cacheTail, r12
@@set_head:
    mov [rbx].COMPILER_ENGINE.cacheHead, r12
    inc dword ptr [rbx].COMPILER_ENGINE.cacheCount
    mov rax, [r12].CACHE_ENTRY.size
    add [rbx].COMPILER_ENGINE.cacheSize, rax

    ; Enforce cache capacity
    mov rax, [rbx].COMPILER_ENGINE.cacheSize
    cmp rax, [rbx].COMPILER_ENGINE.cacheMaxSize
    jbe @@ok
    mov rcx, rbx
    xor rdx, rdx
    call Cache_Evict
@@ok:
    mov eax, 1
    jmp @@done

@@fail:
    xor eax, eax
@@done:
    add rsp, 40
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
Cache_Store ENDP

Cache_MoveToFront PROC FRAME engine:QWORD, entry:QWORD
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    sub rsp, 40
    .allocstack 40
    .endprolog

    mov rbx, rcx            ; COMPILER_ENGINE*
    mov rsi, rdx            ; CACHE_ENTRY*
    test rbx, rbx
    jz @@mtf_fail
    test rsi, rsi
    jz @@mtf_fail

    mov rax, [rbx].COMPILER_ENGINE.cacheHead
    cmp rsi, rax
    je @@mtf_ok

    ; Detach from current position
    mov rax, [rsi].CACHE_ENTRY.pPrev
    mov rdx, [rsi].CACHE_ENTRY.pNext
    test rax, rax
    jz @@mtf_no_prev
    mov [rax].CACHE_ENTRY.pNext, rdx
    jmp @@mtf_prev_done
@@mtf_no_prev:
    mov [rbx].COMPILER_ENGINE.cacheHead, rdx
@@mtf_prev_done:
    test rdx, rdx
    jz @@mtf_no_next
    mov [rdx].CACHE_ENTRY.pPrev, rax
    jmp @@mtf_next_done
@@mtf_no_next:
    mov [rbx].COMPILER_ENGINE.cacheTail, rax
@@mtf_next_done:

    ; Insert at head
    mov rax, [rbx].COMPILER_ENGINE.cacheHead
    mov qword ptr [rsi].CACHE_ENTRY.pPrev, 0
    mov [rsi].CACHE_ENTRY.pNext, rax
    test rax, rax
    jz @@mtf_set_tail
    mov [rax].CACHE_ENTRY.pPrev, rsi
    jmp @@mtf_set_head
@@mtf_set_tail:
    mov [rbx].COMPILER_ENGINE.cacheTail, rsi
@@mtf_set_head:
    mov [rbx].COMPILER_ENGINE.cacheHead, rsi

@@mtf_ok:
    mov eax, 1
    jmp @@mtf_done
@@mtf_fail:
    xor eax, eax
@@mtf_done:
    add rsp, 32
    pop rsi
    pop rbx
    ret
Cache_MoveToFront ENDP

Cache_Evict PROC FRAME engine:QWORD, neededSize:QWORD
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 40
    .allocstack 40
    .endprolog

    mov rbx, rcx            ; COMPILER_ENGINE*
    mov rsi, rdx            ; needed size
    test rbx, rbx
    jz @@evict_fail

@@evict_loop:
    mov rax, [rbx].COMPILER_ENGINE.cacheSize
    add rax, rsi
    cmp rax, [rbx].COMPILER_ENGINE.cacheMaxSize
    jbe @@evict_ok

    mov rdi, [rbx].COMPILER_ENGINE.cacheTail
    test rdi, rdi
    jz @@evict_ok

    mov rax, [rdi].CACHE_ENTRY.pPrev
    mov [rbx].COMPILER_ENGINE.cacheTail, rax
    test rax, rax
    jz @@evict_last
    mov qword ptr [rax].CACHE_ENTRY.pNext, 0
    jmp @@evict_links_done
@@evict_last:
    mov qword ptr [rbx].COMPILER_ENGINE.cacheHead, 0
@@evict_links_done:

    cmp dword ptr [rbx].COMPILER_ENGINE.cacheCount, 0
    jle @@evict_count_done
    dec dword ptr [rbx].COMPILER_ENGINE.cacheCount
@@evict_count_done:

    mov rax, [rbx].COMPILER_ENGINE.cacheSize
    mov rdx, [rdi].CACHE_ENTRY.size
    cmp rax, rdx
    jae @@evict_sub_ok
    xor rax, rax
    jmp @@evict_store_size
@@evict_sub_ok:
    sub rax, rdx
@@evict_store_size:
    mov [rbx].COMPILER_ENGINE.cacheSize, rax

    mov rcx, rdi
    call free
    jmp @@evict_loop

@@evict_ok:
    mov eax, 1
    jmp @@evict_done
@@evict_fail:
    xor eax, eax
@@evict_done:
    add rsp, 32
    pop rdi
    pop rsi
    pop rbx
    ret
Cache_Evict ENDP

Cache_Cleanup PROC FRAME engine:QWORD
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 40
    .allocstack 40
    .endprolog

    mov rbx, rcx
    test rbx, rbx
    jz @@cleanup_fail

    mov rsi, [rbx].COMPILER_ENGINE.cacheHead
@@cleanup_loop:
    test rsi, rsi
    jz @@cleanup_done_loop
    mov rdi, [rsi].CACHE_ENTRY.pNext
    mov rcx, rsi
    call free
    mov rsi, rdi
    jmp @@cleanup_loop
@@cleanup_done_loop:

    mov qword ptr [rbx].COMPILER_ENGINE.cacheHead, 0
    mov qword ptr [rbx].COMPILER_ENGINE.cacheTail, 0
    mov dword ptr [rbx].COMPILER_ENGINE.cacheCount, 0
    mov qword ptr [rbx].COMPILER_ENGINE.cacheSize, 0

    mov eax, 1
    jmp @@cleanup_done
@@cleanup_fail:
    xor eax, eax
@@cleanup_done:
    add rsp, 32
    pop rdi
    pop rsi
    pop rbx
    ret
Cache_Cleanup ENDP

