AI_SetError ENDP

AI_GetError PROC FRAME pCode:QWORD, pFunction:QWORD, pLine:QWORD
    test rcx, rcx
    jz @@skip_code
    mov eax, g_LastErrorCode
    mov [rcx], eax
    
@@skip_code:
    test rdx, rdx
    jz @@skip_func
    mov rax, g_LastErrorFunction
    mov [rdx], rax
    
@@skip_func:
    test r8, r8
    jz @@done
    mov eax, g_LastErrorLine
    mov [r8], eax
    
@@done:
    mov eax, g_LastErrorCode
    ret
AI_GetError ENDP

