.686
.xmm
.model flat, c
OPTION CASEMAP:NONE
OPTION ALIGN:64

;------------------------------------------------------------------------------
; INCLUDES
;------------------------------------------------------------------------------
include \masm32\include\windows.inc
include \masm32\include\kernel32.inc
include \masm32\include\user32.inc
include \masm32\include\advapi32.inc
include \masm32\include\winhttp.inc

includelib \masm32\lib\kernel32.lib
includelib \masm32\lib\user32.lib
includelib \masm32\lib\advapi32.lib
includelib \masm32\lib\winhttp.lib

;------------------------------------------------------------------------------
; CONSTANTS
;------------------------------------------------------------------------------
CONFIG_MAGIC            EQU 'RWXD'
CONFIG_VERSION          EQU 0100h
MAX_DIAGNOSTICS         EQU 256
MAX_WORKERS             EQU 16
MAX_QUEUE_DEPTH         EQU 1024
RING_BUFFER_SIZE        EQU (128 * 1024 * 1024)  ; 128MB
TELEMETRY_QUEUE_SIZE    EQU 4096
TELEMETRY_BATCH_SIZE    EQU 32
TELEMETRY_FLUSH_INTERVAL EQU 30000  ; 30 seconds

; Compilation stages
STAGE_LEXING            EQU 0
STAGE_PARSING           EQU 1
STAGE_SEMANTIC          EQU 2
STAGE_IRGEN             EQU 3
STAGE_OPTIMIZE          EQU 4
STAGE_CODEGEN           EQU 5
STAGE_ASSEMBLY          EQU 6
STAGE_LINKING           EQU 7
STAGE_COMPLETE          EQU 8

; Error severity
SEV_INFO                EQU 0
SEV_WARNING             EQU 1
SEV_ERROR               EQU 2
SEV_FATAL               EQU 3

; Target architectures
TARGET_X86              EQU 0
TARGET_X64              EQU 1
TARGET_ARM              EQU 2
TARGET_ARM64            EQU 3
TARGET_AUTO             EQU 4

; Optimization levels
OPT_NONE                EQU 0
OPT_STANDARD            EQU 1
OPT_SIZE                EQU 2
OPT_SPEED               EQU 3

; Languages
LANG_ASM                EQU 0
LANG_C                  EQU 1
LANG_CPP                EQU 2
LANG_PYTHON             EQU 3
LANG_UNKNOWN            EQU 255

; Engine states
ENGINE_STATE_INIT       EQU 0
ENGINE_STATE_RUNNING    EQU 1
ENGINE_STATE_SHUTDOWN   EQU 2

; Titan magic
TITAN_MAGIC             EQU 'TITN'

