KVCache_ClearSequence ENDP

; Embedding_Lookup - Gather token embeddings
; RCX = embedding table, RDX = token IDs, R8D = count, R9 = output
Embedding_Lookup PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    mov rbx, rcx            ; embedding table
    mov rsi, rdx            ; tokens
    mov edi, r8d            ; count
    mov r10, r9             ; output
    
    xor ecx, ecx            ; i = 0
@@loop:
    cmp ecx, edi
    jge @@done
    
    ; Get token ID
    mov eax, [rsi + rcx*4]
    
    ; Lookup embedding: output[i] = table[token_id]
    ; embedding_dim typically 4096
    imul rax, 4096*4        ; offset = token_id * dim * sizeof(float)
    lea r8, [rbx + rax]     ; source
    
    mov r9d, ecx
    imul r9d, 4096*4        ; dest offset
    lea rdx, [r10 + r9]     ; dest
    
    ; Copy embedding (simplified - would use AVX in production)
    push rcx
    mov ecx, 4096
@@copy:
    mov eax, [r8]
    mov [rdx], eax
    add r8, 4
    add rdx, 4
    dec ecx
    jnz @@copy
    pop rcx
    
    inc ecx
    jmp @@loop
    
@@done:
    add rsp, 32
    pop rdi
    pop rsi
    pop rbx
    ret
Embedding_Lookup ENDP

; RMSNorm - Root Mean Square Layer Normalization
; RCX = input/output, EDX = length
RMSNorm PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    mov rbx, rcx
    mov r8d, edx
    
    ; Compute sum of squares
    xorps xmm0, xmm0        ; sum = 0
    xor ecx, ecx
@@sum_loop:
    cmp ecx, r8d
    jge @@compute_norm
    
    movss xmm1, [rbx + rcx*4]
    mulss xmm1, xmm1
    addss xmm0, xmm1
    
    inc ecx
    jmp @@sum_loop
    
@@compute_norm:
    ; rms = sqrt(sum / n + eps)
    cvtsi2ss xmm1, r8d
    divss xmm0, xmm1
    
    ; Add epsilon (1e-6)
    mov eax, 358637h        ; ~1e-6 in float
    movd xmm2, eax
    addss xmm0, xmm2
    
    sqrtss xmm0, xmm0
    
    ; Compute 1/rms
    mov eax, 3f800000h      ; 1.0f
    movd xmm1, eax
    divss xmm1, xmm0        ; scale = 1/rms
    
    ; Scale each element
    xor ecx, ecx
@@scale_loop:
    cmp ecx, r8d
    jge @@done
    
    movss xmm0, [rbx + rcx*4]
    mulss xmm0, xmm1
    movss [rbx + rcx*4], xmm0
    
    inc ecx
    jmp @@scale_loop
    
@@done:
    add rsp, 32
    pop rbx
    ret
RMSNorm ENDP

; Linear_Projection - Matrix multiply for output projection
; RCX = input, EDX = seq_len, R8 = weight matrix, R9 = output
