; CausalSelfAttention - Scaled dot-product attention with mask
; RCX = Q, RDX = K, R8 = V, R9D = seq_len
CausalSelfAttention PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    push r13
    .pushreg r13
