    mov r9d, r12d
    call MatMul_ScoresV
    
    ; Cleanup
    mov rcx, r13
    call free
    
    xor eax, eax
    jmp @@done
    
@@error:
    mov eax, -1
    
@@done:
    add rsp, 128
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
