    add rsp, 40
    ret
MatMul_QKTranspose ENDP

; ApplyCausalMask - Set upper triangle to -inf
; RCX = scores, EDX = seq_len
ApplyCausalMask PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    mov rbx, rcx
    mov esi, edx
    
    ; For i in range(seq_len):
    ;   For j in range(i+1, seq_len):
    ;     scores[i][j] = -inf
    
    xor ecx, ecx            ; i
@@row_loop:
    cmp ecx, esi
    jge @@done
    
    mov edx, ecx
    inc edx                 ; j = i + 1
    
@@col_loop:
    cmp edx, esi
    jge @@next_row
    
    ; Compute index: i * seq_len + j
    mov eax, ecx
    imul eax, esi
    add eax, edx
    
    ; Set to -inf (0xFF800000)
    mov dword ptr [rbx + rax*4], 0FF800000h
    
    inc edx
    jmp @@col_loop
    
@@next_row:
    inc ecx
    jmp @@row_loop
    
@@done:
    add rsp, 32
    pop rsi
    pop rbx
    ret
ApplyCausalMask ENDP

; SoftmaxRows - Apply softmax to each row
; RCX = matrix, EDX = size (both dims)
SoftmaxRows PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    mov rbx, rcx
    mov esi, edx
    
    xor edi, edi            ; row
@@row_loop:
    cmp edi, esi
    jge @@done
    
    ; Find max for numerical stability
    mov eax, edi
    imul eax, esi
    lea rcx, [rbx + rax*4]  ; row start
    
    ; max = -inf
    mov eax, 0FF800000h
    movd xmm0, eax
    
    xor edx, edx
@@max_loop:
    cmp edx, esi
    jge @@subtract_max
    
    movss xmm1, [rcx + rdx*4]
    maxss xmm0, xmm1
    
    inc edx
    jmp @@max_loop
    
@@subtract_max:
    ; Subtract max and compute exp, accumulate sum
    xorps xmm2, xmm2        ; sum = 0
    xor edx, edx
    
@@exp_loop:
    cmp edx, esi
    jge @@normalize
    
    movss xmm1, [rcx + rdx*4]
    subss xmm1, xmm0        ; x - max
    
    ; exp approximation (or call exp function)
    ; Simplified: store as-is for now
    movss [rcx + rdx*4], xmm1
    addss xmm2, xmm1
    
    inc edx
    jmp @@exp_loop
    
@@normalize:
    ; Divide by sum
    xor edx, edx
@@norm_loop:
    cmp edx, esi
    jge @@next_row
    
    movss xmm1, [rcx + rdx*4]
    divss xmm1, xmm2
    movss [rcx + rdx*4], xmm1
    
    inc edx
    jmp @@norm_loop
    
@@next_row:
    inc edi
    jmp @@row_loop
    
@@done:
    add rsp, 32
    pop rdi
    pop rsi
    pop rbx
    ret
SoftmaxRows ENDP

; MatMul_ScoresV - Multiply attention scores by V
MatMul_ScoresV PROC FRAME
    sub rsp, 40
    .allocstack 40
    .endprolog
    
    ; output = scores @ V
    ; Simplified implementation
    
    add rsp, 40
    ret
MatMul_ScoresV ENDP

; Softmax - Single vector softmax
; RCX = logits, EDX = vocab_size
Softmax PROC FRAME
    sub rsp, 40
    .allocstack 40
    .endprolog
    
    ; Similar to SoftmaxRows but for single vector
    
    add rsp, 40
    ret
Softmax ENDP

; ApplyTemperature - Scale logits by temperature
; RCX = logits, EDX = vocab_size (XMM2 already has temperature)
ApplyTemperature PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    mov rbx, rcx
    mov r8d, edx
    
    ; logits = logits / temperature
    xor ecx, ecx
@@loop:
    cmp ecx, r8d
    jge @@done
    
    movss xmm0, [rbx + rcx*4]
    divss xmm0, xmm2
    movss [rbx + rcx*4], xmm0
    
    inc ecx
    jmp @@loop
    
@@done:
    add rsp, 32
    pop rbx
    ret
ApplyTemperature ENDP

; TopPFilter - Nucleus sampling filter
; RCX = probs, EDX = vocab_size, XMM0 = top_p
TopPFilter PROC FRAME
    sub rsp, 40
    .allocstack 40
    .endprolog
    
    ; Sort probabilities descending
    ; Find smallest set with cumulative prob > top_p
    ; Zero out the rest
    
    add rsp, 40
    ret
TopPFilter ENDP

; MultinomialSample - Sample from probability distribution
; RCX = probs, EDX = vocab_size
; Returns: EAX = sampled token ID
MultinomialSample PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    mov rbx, rcx
    mov esi, edx
    
    ; Generate random number [0, 1)
    rdtsc
    and eax, 0FFFFh
    cvtsi2ss xmm0, eax
    mov eax, 47800000h      ; 65536.0f
    movd xmm1, eax
    divss xmm0, xmm1        ; random in [0, 1)
    
    ; Cumulative sum search
    xorps xmm1, xmm1        ; cumsum = 0
    xor ecx, ecx
    
@@search:
    cmp ecx, esi
    jge @@use_last
    
    movss xmm2, [rbx + rcx*4]
    addss xmm1, xmm2
    
    comiss xmm1, xmm0
    jae @@found
    
    inc ecx
    jmp @@search
    
@@use_last:
    dec ecx
    
@@found:
    mov eax, ecx
    
    add rsp, 32
    pop rsi
    pop rbx
    ret
MultinomialSample ENDP

; TransformerLayer_Attention - Multi-head attention for one layer
; RCX = hidden_states, EDX = seq_len, R8D = layer_idx
TransformerLayer_Attention PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    push r13
    .pushreg r13
    sub rsp, 96
    .allocstack 96
    .endprolog
    
    mov rsi, rcx            ; hidden_states
    mov edi, edx            ; seq_len
    mov ebx, r8d            ; layer_idx
    
    ; Load weights for this layer
    mov rcx, [g_transformer_weights]
    mov edx, ebx
    call GetLayerWeights
    mov r12, rax            ; LayerWeights*
    
    ; QKV projection
    mov rcx, rsi
    mov edx, edi
    mov r8, [r12].LayerWeights.qkv_proj
    lea r9, [rsp + 32]
    call Linear_Forward
    
    ; Apply rotary embeddings
    lea rcx, [rsp + 32]
    mov edx, edi
    call ApplyRotaryEmbeddings
    
    ; Self-attention
    lea rcx, [rsp + 32]             ; Q
    lea rdx, [rsp + 32]             ; K (same buffer, different offset in real impl)
    lea r8, [rsp + 32]              ; V
    mov r9d, edi
    call CausalSelfAttention
    
    ; Output projection
    lea rcx, [rsp + 32]
    mov edx, edi
    mov r8, [r12].LayerWeights.o_proj
    mov r9, rsi
    call Linear_Forward
    
    add rsp, 96
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
TransformerLayer_Attention ENDP

; TransformerLayer_FFN - Feed-forward network for one layer
; RCX = hidden_states, EDX = seq_len, R8D = layer_idx
TransformerLayer_FFN PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 64
    .allocstack 64
    .endprolog
    
    mov rsi, rcx
    mov edi, edx
    mov ebx, r8d
    
    ; Get layer weights
    mov rcx, [g_transformer_weights]
    mov edx, ebx
    call GetLayerWeights
    mov r8, rax
    
    ; FFN: x = x + FFN(norm(x))
    ; FFN = down_proj(act(gate_proj(x)) * up_proj(x))
    
    ; Simplified: just do linear transformations
    mov rcx, rsi
    mov edx, edi
    mov r8, [rax].LayerWeights.mlp_up
    lea r9, [rsp + 32]
    call Linear_Forward
    
    add rsp, 64
    pop rdi
    pop rsi
    pop rbx
    ret
TransformerLayer_FFN ENDP

; Transformer_ForwardPass - Full forward pass through all layers
; RCX = transformer, RDX = input tokens, R8D = token_count, R9 = output_logits
Transformer_ForwardPass PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    push r13
    .pushreg r13
    push r14
    .pushreg r14
    push r15
    .pushreg r15
    sub rsp, 64
    .allocstack 64
    .endprolog
    
    mov rbx, rcx            ; transformer
    mov rsi, rdx            ; tokens
    mov edi, r8d            ; token_count
    mov r12, r9             ; output_logits
    
    ; Get model dimensions
    mov r13d, [rbx].TransformerConfig.hidden_size
    mov r14d, [rbx].TransformerConfig.num_layers
    
    ; Allocate hidden states buffer
    mov ecx, edi
    imul ecx, r13d
    shl ecx, 2              ; * sizeof(float)
    call malloc
    mov r15, rax
    test rax, rax
    jz @@error
    
    ; Embedding lookup
    mov rcx, [rbx].TransformerWeights.token_embedding
    mov rdx, rsi
    mov r8d, edi
    mov r9, r15
    call Embedding_Lookup
    
    ; Process each layer
    xor ebx, ebx
@@layer_loop:
    cmp ebx, r14d
    jge @@final_norm
    
    ; Attention
    mov rcx, r15
    mov edx, edi
    mov r8d, ebx
    call TransformerLayer_Attention
    
    ; FFN
    mov rcx, r15
    mov edx, edi
    mov r8d, ebx
    call TransformerLayer_FFN
    
    inc ebx
    jmp @@layer_loop
    
@@final_norm:
    ; Final layer norm
    mov rcx, r15
    mov edx, edi
    call RMSNorm
    
    ; LM head projection
    mov rcx, r15
    mov edx, edi
    mov r8, [rbx].TransformerWeights.lm_head
    mov r9, r12
    call Linear_Projection
    
    ; Cleanup
    mov rcx, r15
    call free
    
    xor eax, eax
    jmp @@done
    
@@error:
    mov eax, -1
    
@@done:
    add rsp, 64
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
Transformer_ForwardPass ENDP

; SampleToken - Sample next token from logits
; XMM0 = temperature, XMM1 = top_p
; RCX = logits, EDX = vocab_size
; Returns: EAX = token ID
SampleToken PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 64
    .allocstack 64
    .endprolog
    
    mov rsi, rcx
    mov edi, edx
    movss [rsp+32], xmm0    ; save temperature
    movss [rsp+36], xmm1    ; save top_p
    
    ; Apply temperature
    movss xmm2, [rsp+32]
    mov rcx, rsi
    mov edx, edi
    call ApplyTemperature
    
    ; Softmax
    mov rcx, rsi
    mov edx, edi
    call Softmax
    
    ; Check if top_p < 1.0
    movss xmm1, [rsp+36]
    mov eax, 3f800000h      ; 1.0f
    movd xmm0, eax
    comiss xmm1, xmm0
    jae @@sample
    
    ; Top-p filtering
    mov rcx, rsi
    mov edx, edi
    movss xmm0, xmm1
    call TopPFilter
    
@@sample:
    ; Multinomial sample
    mov rcx, rsi
    mov edx, edi
    call MultinomialSample
    
    add rsp, 64
    pop rdi
    pop rsi
    pop rbx
    ret
SampleToken ENDP

; InferenceEngine_ProcessChat - Real chat processing (NOT echo)
; RCX = this, RDX = message (wchar_t*), R8 = response_buffer, R9 = buffer_size
InferenceEngine_ProcessChat PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    push r13
    .pushreg r13
    push r14
    .pushreg r14
    push r15
    .pushreg r15
    sub rsp, 192
    .allocstack 192
    .endprolog
    
    mov rbx, rcx            ; this
    mov rsi, rdx            ; input message
    mov rdi, r8             ; response buffer
    mov r15, r9             ; buffer size
    
    ; Validate inputs
    test rsi, rsi
    jz @@error_null_input
    test rdi, rdi
    jz @@error_null_buffer
    
    ; Acquire generation mutex
    mov rcx, [rbx].InferenceEngine.generation_mutex
    call EnterCriticalSection
    
    ;======================================================================
    ; STEP 1: Tokenize input message
    ;======================================================================
    lea r12, [rsp + 64]     ; Local token buffer
    mov rcx, [rbx].InferenceEngine.tokenizer
    mov rdx, rsi
    mov r8, r12
    mov r9d, 32             ; Max 32 input tokens
    call Tokenizer_Encode
    
    mov r13d, eax           ; input_token_count
    test eax, eax
    jz @@error_tokenization
    
    ;======================================================================
    ; STEP 2: Initialize generation
    ;======================================================================
    xor r14d, r14d          ; generated_token_count = 0
    mov ecx, [rbx].InferenceEngine.context_size
    shl ecx, 2              ; Max response tokens
    mov [rsp+56], ecx       ; max_tokens
    
    ; Clear KV cache
    mov rcx, [rbx].InferenceEngine.kv_cache
    call KVCache_ClearSequence
    
    ; Initialize response buffer
    mov word ptr [rdi], 0
    
    ;======================================================================
    ; STEP 3: Generation loop
    ;======================================================================
@@generation_loop:
    cmp r14d, [rsp+56]
    jge @@generation_complete
    
    ; Forward pass
    mov rcx, [rbx].InferenceEngine.transformer
    mov rdx, r12            ; tokens
    mov r8d, r13d           ; token count
    lea r9, [rsp + 128]     ; output logits
    call Transformer_ForwardPass
    
    ;======================================================================
    ; STEP 4: Sample next token
    ;======================================================================
    movss xmm0, [rbx].InferenceEngine.temperature
    movss xmm1, [rbx].InferenceEngine.top_p
    lea rcx, [rsp + 128]    ; logits
    mov edx, 32000          ; vocab size
    call SampleToken
    
    ; Check for EOS token
    cmp eax, 2
    je @@generation_complete
    
    ; Add token to sequence
    mov ecx, r13d
    mov [r12 + rcx*4], eax
    inc r13d
    inc r14d
    
    ; Decode token to text
    mov ecx, eax
    lea rdx, [rsp + 160]
    call Tokenizer_DecodeSingle
    
    ; Check buffer space
    mov rcx, rdi
    call wcslen
    cmp rax, r15
    jge @@generation_complete
    
    ; Append decoded token
    lea rcx, [rdi + rax*2]
    lea rdx, [rsp + 160]
    mov r8, r15
    sub r8, rax
    call wcscpy_s
    
    jmp @@generation_loop
    
@@generation_complete:
    ; Update statistics
    add [rbx].InferenceEngine.stats.tokens_generated, r14
    
    mov rcx, [rbx].InferenceEngine.generation_mutex
    call LeaveCriticalSection
    
    mov eax, 1
    jmp @@cleanup
    
@@error_null_input:
    mov ecx, ERROR_INVALID_PARAMETER
    call SetLastError
    xor eax, eax
    jmp @@cleanup
    
@@error_null_buffer:
    mov ecx, ERROR_INVALID_PARAMETER
    call SetLastError
    xor eax, eax
    jmp @@cleanup
    
@@error_tokenization:
    mov rcx, [rbx].InferenceEngine.generation_mutex
    call LeaveCriticalSection
    mov ecx, ERROR_INVALID_DATA
    call SetLastError
    xor eax, eax
    
@@cleanup:
    add rsp, 192
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
InferenceEngine_ProcessChat ENDP

