; FindSnapshotById - Locate snapshot by ID
; RCX = BackupManager*, RDX = snapshot_id
; Returns: RAX = SnapshotInfo* or NULL
FindSnapshotById PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    mov rbx, rcx
    mov rsi, rdx
    
    mov rcx, [rbx].BackupManager.snapshots
    mov edx, [rbx].BackupManager.snapshot_count
    xor eax, eax
    
@@loop:
    test edx, edx
    jz @@not_found
    
    cmp [rcx].SnapshotInfo.id, rsi
    je @@found
    
    add rcx, SIZEOF SnapshotInfo
    dec edx
    jmp @@loop
    
@@found:
    mov rax, rcx
    jmp @@done
    
@@not_found:
    xor eax, eax
    
@@done:
    add rsp, 32
    pop rsi
    pop rbx
    ret
FindSnapshotById ENDP

; BackupManager_CreateSnapshot - Create new backup snapshot
; RCX = this, RDX = source_path, R8 = snapshot_name
BackupManager_CreateSnapshot PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    push r13
    .pushreg r13
    push r14
    .pushreg r14
    push r15
    .pushreg r15
    sub rsp, 600
    .allocstack 600
    .endprolog
    
    mov rbx, rcx            ; this
    mov rsi, rdx            ; source_path
    mov rdi, r8             ; snapshot_name
    
    ; Validate
    test rsi, rsi
    jz @@error_invalid_path
    
    ; Acquire mutex
    mov rcx, [rbx].BackupManager.mutex
    call EnterCriticalSection
    
    ; Generate snapshot ID from current time
    lea rcx, [rsp + 64]
    call GetSystemTimeAsFileTime
    mov r12, [rsp + 64]     ; snapshot_id = timestamp
    
    ; Build snapshot path
    lea r13, [rsp + 128]    ; path buffer
    mov rcx, [rbx].BackupManager.backup_path
    mov rdx, r13
    mov r8d, 260
    call wcscpy_s
    
    ; Append backslash
    mov rcx, r13
    call wcslen
    cmp word ptr [r13 + rax*2 - 2], '\'
    je @@has_slash
    lea rcx, [r13 + rax*2]
    lea rdx, szBackslash
    mov r8d, 2
    call wcscpy_s
    
@@has_slash:
    ; Create directory
    mov rcx, r13
    call CreateDirectoryW
    test eax, eax
    jz @@error_create_dir
    
    ; Walk source directory
    xor r14d, r14d          ; file_count
    xor r15d, r15d          ; total_size
    
    ; Build search pattern: source\*
    lea rcx, [rsp + 400]
    mov rdx, rsi
    mov r8d, 260
    call wcscpy_s
    lea rcx, [rsp + 400]
    lea rdx, szAllFiles
    call wcscat_s
    
    ; FindFirstFile
    lea rcx, [rsp + 400]
    lea rdx, [rsp + 200]    ; WIN32_FIND_DATAW
    call FindFirstFileW
    cmp rax, INVALID_HANDLE_VALUE
    je @@error_find_file
    mov [rsp + 72], rax     ; hFind
    
@@file_loop:
    ; Skip . and ..
    lea rcx, [rsp + 200]
    add rcx, 44             ; Offset to cFileName
    cmp word ptr [rcx], '.'
    je @@next_file
    
    ; Check if directory
    mov eax, [rsp + 200]    ; dwFileAttributes
    test eax, FILE_ATTRIBUTE_DIRECTORY
    jnz @@next_file         ; Skip directories for now
    
    ; Add file size
    mov eax, [rsp + 200 + 32]   ; nFileSizeLow
    add r15d, eax
    inc r14d
    
    ; Copy file
    mov rcx, r13
    lea rdx, [rsp + 200 + 44]   ; filename
    call BackupFileWithCompression
    
@@next_file:
    mov rcx, [rsp + 72]
    lea rdx, [rsp + 200]
    call FindNextFileW
    test eax, eax
    jnz @@file_loop
    
    ; Close find handle
    mov rcx, [rsp + 72]
    call FindClose
    
    ; Create metadata file
    lea rcx, [rsp + 400]
    mov rdx, r13
    mov r8d, 260
    call wcscpy_s
    lea rcx, [rsp + 400]
    lea rdx, szMetadataFile
    call wcscat_s
    
    ; Write metadata JSON
    lea rcx, [rsp + 400]
    mov edx, GENERIC_WRITE
    xor r8d, r8d
    mov r9d, CREATE_ALWAYS
    mov qword ptr [rsp + 32], FILE_ATTRIBUTE_NORMAL
    mov qword ptr [rsp + 40], 0
    mov qword ptr [rsp + 48], 0
    call CreateFileW
    cmp rax, INVALID_HANDLE_VALUE
    je @@error_metadata
    mov [rsp + 80], rax     ; hFile
    
    ; Write JSON content
    ; ... (simplified)
    
    mov rcx, [rsp + 80]
    call CloseHandle
    
    ; Update registry
    mov rcx, rbx
    call AddSnapshotToRegistry
    
    ; Enforce limits
    mov rcx, rbx
    call EnforceSnapshotLimit
    
    ; Release mutex
    mov rcx, [rbx].BackupManager.mutex
    call LeaveCriticalSection
    
    mov rax, r12            ; Return snapshot ID
    jmp @@cleanup
    
@@error_invalid_path:
    mov ecx, ERROR_INVALID_PARAMETER
    call SetLastError
    xor eax, eax
    jmp @@cleanup
    
@@error_create_dir:
@@error_find_file:
@@error_metadata:
    mov rcx, [rbx].BackupManager.mutex
    call LeaveCriticalSection
    xor eax, eax
    
@@cleanup:
    add rsp, 600
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
BackupManager_CreateSnapshot ENDP

; BackupManager_RestoreSnapshot - Restore from snapshot
; RCX = this, RDX = snapshot_id, R8 = target_path
BackupManager_RestoreSnapshot PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    sub rsp, 1024
    .allocstack 1024
    .endprolog
    
    mov rbx, rcx
    mov rsi, rdx
    mov rdi, r8
    
    ; Find snapshot
    mov rcx, rbx
    mov rdx, rsi
    call FindSnapshotById
    test rax, rax
    jz @@error_not_found
    mov r12, rax
    
    ; Create target directory
    mov rcx, rdi
    call CreateDirectoryW
    
    ; Copy files from snapshot to target
    ; ... (similar to CreateSnapshot but reversed)
    
    mov eax, 1
    jmp @@cleanup
    
@@error_not_found:
    mov ecx, ERROR_FILE_NOT_FOUND
    call SetLastError
    xor eax, eax
    
@@cleanup:
    add rsp, 1024
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
BackupManager_RestoreSnapshot ENDP

