; LSP_SendRequest - Send JSON-RPC request
; RCX = LSPClient*, RDX = JSON message, R8 = callback
LSP_SendRequest PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    sub rsp, 264
    .allocstack 264
    .endprolog
    
    mov rbx, rcx
    mov rsi, rdx
    
    ; Get message length
    mov rcx, rsi
    call strlen
    
    ; Format Content-Length header
    lea rcx, [rsp + 64]
    mov edx, 256
    lea r8, szContentLengthHeader
    mov r9d, eax
    call sprintf_s
    
    ; Concatenate header + message
    lea rcx, [rsp + 64]
    mov rdx, rsi
    call strcat_s
    
    ; Write to pipe
    mov rcx, [rbx].LSPClient.stdin_write
    lea rdx, [rsp + 64]
    call lstrlenA
    mov r8d, eax
    lea r9, [rsp + 32]
    mov qword ptr [rsp + 32], 0
    call WriteFile
    
    add rsp, 264
    pop rsi
    pop rbx
    ret
LSP_SendRequest ENDP

; LSP_SendRequestSync - Send and wait for response
; RCX = LSPClient*, RDX = JSON message
LSP_SendRequestSync PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 40
    .allocstack 40
    .endprolog
    
    mov rbx, rcx
    
    ; Send request
    xor r8, r8
    call LSP_SendRequest
    
    ; Wait for response
    ; ... (read from stdout pipe)
    
    add rsp, 40
    pop rbx
    ret
LSP_SendRequestSync ENDP

