; LSP_MessageThread - Background message reading thread
; RCX = LSPClient*
LSP_MessageThread PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 40
    .allocstack 40
    .endprolog
    
    mov rbx, rcx
    
@@read_loop:
    ; Check shutdown flag
    cmp [rbx].LSPClient.shutdown_requested, 1
    je @@exit
    
    ; Read from stdout pipe
    mov rcx, [rbx].LSPClient.stdout_read
    mov rdx, [rbx].LSPClient.receive_buffer
    mov r8d, 4096
    lea r9, [rsp + 32]
    mov qword ptr [rsp + 32], 0
    call ReadFile
    
    ; Parse and dispatch
    mov rcx, [rbx].LSPClient.receive_buffer
    call ParseContentLength
    
    mov rcx, [rbx].LSPClient.receive_buffer
    call LSP_DispatchMessage
    
    jmp @@read_loop
    
@@exit:
    xor eax, eax
    add rsp, 40
    pop rbx
    ret
LSP_MessageThread ENDP

; LSPClient_Initialize - Initialize LSP client
; RCX = this, RDX = workspace_path
LSPClient_Initialize PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    sub rsp, 2056
    .allocstack 2056
    .endprolog
    
    mov rbx, rcx
    mov rsi, rdx
    
    ; Setup STARTUPINFO
    lea rcx, [rsp + 64]
    mov edx, SIZEOF STARTUPINFO
    xor eax, eax
@@zero_si:
    mov [rcx], al
    inc rcx
    dec edx
    jnz @@zero_si
    
    ; Create pipes
    lea r8, [rbx].LSPClient.stdin_write
    lea rdx, [rbx].LSPClient.stdout_read
    call CreateLSPPipes
    
    ; Build command line
    lea rcx, [rsp + 512]
    lea rdx, szClangdPath
    mov r8d, 1024
    call wcscpy_s
    
    lea rcx, [rsp + 512]
    lea rdx, szClangdArgs
    call wcscat_s
    
    ; Create process
    lea rcx, [rsp + 1024]
    lea rdx, [rsp + 64]
    lea r8, [rsp + 512]
    call CreateLSPProcess
    test eax, eax
    jz @@error
    
    ; Build initialize request
    lea rcx, [rsp + 256]
    mov edx, 1024
    lea r8, szInitializeRequest
    mov r9, rsi
    call swprintf_s
    
    ; Send request
    mov rcx, rbx
    lea rdx, [rsp + 256]
    xor r8d, r8d
    call LSP_SendRequest
    
    ; Start message thread
    mov rcx, rbx
    call LSP_StartMessageThread
    
    ; Wait for initialize response
    mov rcx, rbx
    mov edx, 5000
    call LSP_WaitForInitialize
    
    mov eax, 1
    jmp @@done
    
@@error:
    xor eax, eax
    
@@done:
    add rsp, 2056
    pop rsi
    pop rbx
    ret
LSPClient_Initialize ENDP

; LSPClient_Hover - Request hover information
; RCX = this, RDX = file_path, R8D = line, R9D = character
LSPClient_Hover PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    sub rsp, 1032
    .allocstack 1032
    .endprolog
    
    mov rbx, rcx
    mov rsi, rdx
    mov edi, r8d
    mov r12d, r9d
    
    ; Increment message ID
    inc [rbx].LSPClient.message_id
    
    ; Build hover request JSON
    lea rcx, [rsp + 64]
    mov edx, 512
    lea r8, szHoverRequest
    mov r9d, [rbx].LSPClient.message_id
    mov [rsp + 32], rsi
    mov [rsp + 40], edi
    mov [rsp + 48], r12d
    call sprintf_s
    
    ; Send and wait
    mov rcx, rbx
    lea rdx, [rsp + 64]
    call LSP_SendRequestSync
    
    ; Parse response
    mov rcx, rax
    call ParseHoverResponse
    
    add rsp, 1032
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
LSPClient_Hover ENDP

