; CppCompiler_Compile - Compile C++ source file
; RCX = this, RDX = source_file, R8 = output_path, R9 = options
CppCompiler_Compile PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 1032
    .allocstack 1032
    .endprolog
    
    mov rbx, rcx
    mov rsi, rdx            ; source
    mov rdi, r8             ; output
    mov [rsp+64], r9        ; options
    
    ; Build clang command line
    lea rcx, [rsp + 128]
    mov edx, 512
    lea r8, szClangCompile
    mov r9, rsi
    mov [rsp+32], rdi
    call swprintf_s
    
    ; Add optimization flags
    mov rax, [rsp+64]
    test rax, rax
    jz @@no_opts
    
    cmp [rax].CompileOptions.optimization, 3
    jl @@no_o3
    lea rcx, [rsp + 128]
    lea rdx, szFlagO3
    call wcscat_s
    
@@no_o3:
    ; Add include paths
    mov rax, [rsp+64]
    mov rcx, [rax].CompileOptions.include_paths
    test rcx, rcx
    jz @@no_opts
    
@@include_loop:
    mov rdx, [rcx]
    test rdx, rdx
    jz @@no_opts
    
    ; Append -I"path"
    push rcx
    lea rcx, [rsp + 136]
    lea r8, szIncludeFlag
    mov r9, rdx
    call swprintf_s
    pop rcx
    
    add rcx, 8
    jmp @@include_loop
    
@@no_opts:
    ; Execute compiler
    lea rcx, [rsp + 128]
    call _wsystem
    
    ; Check exit code
    test eax, eax
    setz al
    movzx eax, al
    
    add rsp, 1032
    pop rdi
    pop rsi
    pop rbx
    ret
CppCompiler_Compile ENDP

; AsmCompiler_Assemble - Assemble MASM source
; RCX = this, RDX = asm_file, R8 = obj_file
AsmCompiler_Assemble PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 520
    .allocstack 520
    .endprolog
    
    mov rbx, rcx
    mov rsi, rdx            ; asm file
    mov rdi, r8             ; obj file
    
    ; Build ml64.exe command
    lea rcx, [rsp + 64]
    mov edx, 256
    lea r8, szMl64Command
    mov r9, rdi             ; output
    mov [rsp+32], rsi       ; input
    call swprintf_s
    
    ; Add flags
    lea rcx, [rsp + 64]
    lea rdx, szMl64Flags
    call wcscat_s
    
    ; Execute
    lea rcx, [rsp + 64]
    call _wsystem
    
    ; Check for .obj file creation
    mov rcx, rdi
    call GetFileAttributesW
    cmp eax, INVALID_FILE_ATTRIBUTES
    setne al
    movzx eax, al
    
    add rsp, 520
    pop rdi
    pop rsi
    pop rbx
    ret
AsmCompiler_Assemble ENDP

