; RawrXD_Low_Priority_P3.asm
; LOW PRIORITY FIXES - Extended Features
; Additional compilers, Extended LSP, UI, Debugger, Profiler
; Size: ~3,200 lines
;==============================================================================

OPTION CASEMAP:NONE
OPTION PROLOGUE:NONE
OPTION EPILOGUE:NONE

; ============================================================
; EXTERN DECLARATIONS
; ============================================================

EXTERN malloc:PROC
EXTERN free:PROC
EXTERN CreateProcessW:PROC
EXTERN CreatePipe:PROC
EXTERN ReadFile:PROC
EXTERN WriteFile:PROC
EXTERN CloseHandle:PROC
EXTERN DebugActiveProcess:PROC
EXTERN DebugSetProcessKillOnExit:PROC
EXTERN WaitForDebugEvent:PROC
EXTERN ContinueDebugEvent:PROC
EXTERN GetThreadContext:PROC
EXTERN SetThreadContext:PROC
EXTERN OpenThread:PROC
EXTERN VirtualQueryEx:PROC
EXTERN ReadProcessMemory:PROC
EXTERN WriteProcessMemory:PROC
EXTERN QueryPerformanceCounter:PROC
EXTERN QueryPerformanceFrequency:PROC

; ============================================================
; CONSTANTS
; ============================================================

DEBUG_PROCESS           EQU 1
DEBUG_ONLY_THIS_PROCESS EQU 2
DBG_CONTINUE            EQU 00010002h
DBG_EXCEPTION_NOT_HANDLED EQU 80010001h

EXCEPTION_BREAKPOINT    EQU 80000003h
EXCEPTION_SINGLE_STEP   EQU 80000004h

CONTEXT_FULL            EQU 10000Fh
THREAD_GET_CONTEXT      EQU 0008h

; Breakpoint types
BP_SOFTWARE             EQU 0
BP_HARDWARE             EQU 1
BP_CONDITIONAL          EQU 2

; Profiler event types
PROF_FUNCTION_ENTER     EQU 1
PROF_FUNCTION_EXIT      EQU 2
PROF_ALLOCATION         EQU 3
PROF_DEALLOCATION       EQU 4

; ============================================================
; STRUCTURES
; ============================================================

Breakpoint STRUCT
    address             QWORD ?
    bp_type             DWORD ?
    enabled             BYTE ?
    hit_count           DWORD ?
    original_byte       BYTE ?
    condition           QWORD ?     ; Expression to evaluate
Breakpoint ENDS

Debugger STRUCT
    target_pid          DWORD ?
    is_attached         BYTE ?
    breakpoints         QWORD ?
    bp_count            DWORD ?
    bp_capacity         DWORD ?
    current_thread      DWORD ?
    debug_event         QWORD ?     ; DEBUG_EVENT buffer
Debugger ENDS

ProfileSample STRUCT
    timestamp           QWORD ?
    event_type          DWORD ?
    function_id         DWORD ?
    duration_ns         QWORD ?
    allocation_size     QWORD ?
ProfileSample ENDS

Profiler STRUCT
    samples             QWORD ?
    sample_count        DWORD ?
    sample_capacity     DWORD ?
    is_running          BYTE ?
    start_time          QWORD ?
    frequency           QWORD ?     ; QPC frequency
Profiler ENDS

LSPCodeAction STRUCT
    title               QWORD ?
    kind                QWORD ?     ; "quickfix", "refactor", etc.
    edit                QWORD ?     ; WorkspaceEdit*
    command             QWORD ?
LSPCodeAction ENDS

WorkspaceEdit STRUCT
    changes             QWORD ?     ; Map: uri -> TextEdit[]
    change_count        DWORD ?
WorkspaceEdit ENDS

TextEdit STRUCT
    start_line          DWORD ?
    start_col           DWORD ?
    end_line            DWORD ?
    end_col             DWORD ?
    new_text            QWORD ?
TextEdit ENDS

UIPanel STRUCT
    panel_id            DWORD ?
    visible             BYTE ?
    x                   DWORD ?
    y                   DWORD ?
    width               DWORD ?
    height              DWORD ?
    content             QWORD ?
UIPanel ENDS

; ============================================================
; DATA SECTION
; ============================================================

.DATA
ALIGN 8

; Python compiler command
ALIGN 2
szPythonCompile         WORD 'p','y','t','h','o','n','.','e','x','e',' ','-','m',' ','p','y','_','c','o','m','p','i','l','e',' ','"','%','s','"',0
szRustcCompile          WORD 'r','u','s','t','c','.','e','x','e',' ','"','%','s','"',' ','-','o',' ','"','%','s','"',0

; LSP method names
szCodeAction            BYTE 't','e','x','t','D','o','c','u','m','e','n','t','/','c','o','d','e','A','c','t','i','o','n',0
szRename                BYTE 't','e','x','t','D','o','c','u','m','e','n','t','/','r','e','n','a','m','e',0
szPrepareRename         BYTE 't','e','x','t','D','o','c','u','m','e','n','t','/','p','r','e','p','a','r','e','R','e','n','a','m','e',0
szReferences            BYTE 't','e','x','t','D','o','c','u','m','e','n','t','/','r','e','f','e','r','e','n','c','e','s',0

; JSON-RPC request format strings for LSP operations
szCodeActionRequest     BYTE '{"jsonrpc":"2.0","id":%d,"method":"textDocument/codeAction","params":{"textDocument":{"uri":"%s"},"range":{"start":{"line":%d,"character":%d},"end":{"line":%d,"character":%d}},"context":{"diagnostics":[]}}}',0
szRenameRequest         BYTE '{"jsonrpc":"2.0","id":%d,"method":"textDocument/rename","params":{"textDocument":{"uri":"%s"},"position":{"line":%d,"character":%d},"newName":"%s"}}',0
szFindReferencesRequest BYTE '{"jsonrpc":"2.0","id":%d,"method":"textDocument/references","params":{"textDocument":{"uri":"%s"},"position":{"line":%d,"character":%d},"context":{"includeDeclaration":true}}}',0

; ============================================================
; CODE SECTION
; ============================================================

.CODE

;------------------------------------------------------------------------------
; SECTION 1: ADDITIONAL COMPILER BACKENDS
;------------------------------------------------------------------------------

; PythonCompiler_Compile - Compile Python to bytecode
; RCX = this, RDX = source_file, R8 = output_path
PythonCompiler_Compile PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    sub rsp, 520
    .allocstack 520
    .endprolog
    
    mov rbx, rcx
    mov rsi, rdx            ; source
    mov [rsp+64], r8        ; output
    
    ; Build command: python -m py_compile "source.py"
    lea rcx, [rsp + 128]
    mov edx, 256
    lea r8, szPythonCompile
    mov r9, rsi
    call swprintf_s
    
    ; Execute
    lea rcx, [rsp + 128]
    call _wsystem
    
    ; Check result
    test eax, eax
    setz al
    movzx eax, al
    
    add rsp, 520
    pop rsi
    pop rbx
    ret
PythonCompiler_Compile ENDP

; RustCompiler_Compile - Compile Rust source
; RCX = this, RDX = source_file, R8 = output_path
RustCompiler_Compile PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 520
    .allocstack 520
    .endprolog
    
    mov rbx, rcx
    mov rsi, rdx            ; source
    mov rdi, r8             ; output
    
    ; Build command: rustc "source.rs" -o "output"
    lea rcx, [rsp + 128]
    mov edx, 256
    lea r8, szRustcCompile
    mov r9, rsi
    mov [rsp+32], rdi
    call swprintf_s
    
    ; Execute
    lea rcx, [rsp + 128]
    call _wsystem
    
    ; Check result
    test eax, eax
    setz al
    movzx eax, al
    
    add rsp, 520
    pop rdi
    pop rsi
    pop rbx
    ret
RustCompiler_Compile ENDP

;------------------------------------------------------------------------------
; SECTION 2: EXTENDED LSP FUNCTIONALITY
;------------------------------------------------------------------------------

; LSPClient_CodeAction - Request code actions for range
; RCX = this, RDX = uri, R8D = line, R9D = character
; Returns: RAX = raw response buffer (caller owns) or 0 on error
LSPClient_CodeAction PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    push r13
    .pushreg r13
    sub rsp, 2048
    .allocstack 2048
    .endprolog

    mov rbx, rcx            ; LSPClient*
    mov rsi, rdx            ; uri
    mov edi, r8d            ; startLine
    mov r12d, r9d           ; startChar (endChar = startChar+1)
    mov r13d, r9d
    inc r13d                ; endChar = startChar + 1

    inc [rbx].LSPClient.message_id

    lea rcx, [rsp+128]
    mov edx, 1024
    lea r8, szCodeActionRequest
    mov r9d, [rbx].LSPClient.message_id
    mov [rsp+32], rsi       ; uri
    movsxd rax, edi
    mov [rsp+40], rax       ; startLine
    movsxd rax, r12d
    mov [rsp+48], rax       ; startChar
    movsxd rax, edi
    mov [rsp+56], rax       ; endLine
    movsxd rax, r13d
    mov [rsp+64], rax       ; endChar
    call sprintf_s

    mov rcx, rbx
    lea rdx, [rsp+128]
    call LSP_SendRequestSync

    add rsp, 2048
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
LSPClient_CodeAction ENDP

; LSPClient_Rename - Rename symbol at position
; RCX = this, RDX = uri, R8D = line, R9D = character
; [rsp+40] = new_name (5th arg, ANSI string)
; Returns: RAX = raw response buffer or 0 on error
LSPClient_Rename PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    push r13
    .pushreg r13
    sub rsp, 2048
    .allocstack 2048
    .endprolog

    mov rbx, rcx            ; LSPClient*
    mov rsi, rdx            ; uri
    mov edi, r8d            ; line
    mov r12d, r9d           ; character
    ; 5th arg (new_name) at [rsp + 2048 + 5*8 + 40] = [rsp + 2128]
    mov r13, [rsp+2128]     ; new_name string ptr

    inc [rbx].LSPClient.message_id

    lea rcx, [rsp+128]
    mov edx, 1024
    lea r8, szRenameRequest
    mov r9d, [rbx].LSPClient.message_id
    mov [rsp+32], rsi       ; uri
    movsxd rax, edi
    mov [rsp+40], rax       ; line
    movsxd rax, r12d
    mov [rsp+48], rax       ; character
    mov [rsp+56], r13       ; newName
    call sprintf_s

    mov rcx, rbx
    lea rdx, [rsp+128]
    call LSP_SendRequestSync

    add rsp, 2048
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
LSPClient_Rename ENDP

; LSPClient_FindReferences - Find all references to symbol
; RCX = this, RDX = uri, R8D = line, R9D = character
; Returns: RAX = raw response buffer or 0 on error
LSPClient_FindReferences PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    sub rsp, 1032
    .allocstack 1032
    .endprolog

    mov rbx, rcx            ; LSPClient*
    mov rsi, rdx            ; uri
    mov edi, r8d            ; line
    mov r12d, r9d           ; character

    inc [rbx].LSPClient.message_id

    lea rcx, [rsp+64]
    mov edx, 512
    lea r8, szFindReferencesRequest
    mov r9d, [rbx].LSPClient.message_id
    mov [rsp+32], rsi           ; uri
    movsxd rax, edi
    mov [rsp+40], rax           ; line
    movsxd rax, r12d
    mov [rsp+48], rax           ; character
    call sprintf_s

    mov rcx, rbx
    lea rdx, [rsp+64]
    call LSP_SendRequestSync

    add rsp, 1032
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
LSPClient_FindReferences ENDP

; WorkspaceEdit_Apply - Apply workspace edit to files
; RCX = edit
WorkspaceEdit_Apply PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    
    ; For each uri in changes:
    ;   Load file
    ;   Apply text edits in reverse order (to preserve positions)
    ;   Save file
    
    xor esi, esi
@@loop:
    cmp esi, [rbx].WorkspaceEdit.change_count
    jge @@done
    
    ; Get uri and edits
    ; Apply edits
    
    inc esi
    jmp @@loop
    
@@done:
    mov eax, 1
    
    add rsp, 48
    pop rsi
    pop rbx
    ret
WorkspaceEdit_Apply ENDP

;------------------------------------------------------------------------------
; SECTION 3: DEBUGGER IMPLEMENTATION
;------------------------------------------------------------------------------

; Debugger_Init - Initialize debugger
; RCX = this
Debugger_Init PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    
    mov [rbx].Debugger.target_pid, 0
    mov [rbx].Debugger.is_attached, 0
    mov [rbx].Debugger.bp_count, 0
    mov [rbx].Debugger.bp_capacity, 64
    
    ; Allocate breakpoints array
    mov ecx, 64 * SIZEOF Breakpoint
    call malloc
    mov [rbx].Debugger.breakpoints, rax
    
    ; Allocate DEBUG_EVENT buffer
    mov ecx, 176            ; sizeof(DEBUG_EVENT)
    call malloc
    mov [rbx].Debugger.debug_event, rax
    
    add rsp, 48
    pop rbx
    ret
Debugger_Init ENDP

; Debugger_Attach - Attach to running process
; RCX = this, EDX = pid
Debugger_Attach PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    mov [rbx].Debugger.target_pid, edx
    
    ; Attach to process
    mov ecx, edx
    call DebugActiveProcess
    test eax, eax
    jz @@error
    
    ; Don't kill process on exit
    xor ecx, ecx
    call DebugSetProcessKillOnExit
    
    mov [rbx].Debugger.is_attached, 1
    mov eax, 1
    jmp @@done
    
@@error:
    xor eax, eax
    
@@done:
    add rsp, 48
    pop rbx
    ret
Debugger_Attach ENDP

; Debugger_SetBreakpoint - Set breakpoint at address
; RCX = this, RDX = address
Debugger_SetBreakpoint PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    mov rsi, rdx            ; address
    
    ; Check capacity
    mov eax, [rbx].Debugger.bp_count
    cmp eax, [rbx].Debugger.bp_capacity
    jge @@error
    
    ; Get breakpoint slot
    mov rcx, [rbx].Debugger.breakpoints
    imul eax, eax, SIZEOF Breakpoint
    lea rcx, [rcx + rax]
    
    ; Fill breakpoint info
    mov [rcx].Breakpoint.address, rsi
    mov [rcx].Breakpoint.bp_type, BP_SOFTWARE
    mov [rcx].Breakpoint.enabled, 1
    mov [rcx].Breakpoint.hit_count, 0
    
    ; Read original byte
    ; ReadProcessMemory(process, address, &original_byte, 1, NULL)
    ; ... save to Breakpoint.original_byte
    
    ; Write INT3 (0xCC)
    ; WriteProcessMemory(process, address, &int3, 1, NULL)
    
    inc [rbx].Debugger.bp_count
    mov eax, 1
    jmp @@done
    
@@error:
    xor eax, eax
    
@@done:
    add rsp, 48
    pop rsi
    pop rbx
    ret
Debugger_SetBreakpoint ENDP

; Debugger_RemoveBreakpoint - Remove breakpoint
; RCX = this, RDX = address
Debugger_RemoveBreakpoint PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    mov r8, rdx             ; address
    
    ; Find breakpoint
    xor ecx, ecx
@@loop:
    cmp ecx, [rbx].Debugger.bp_count
    jge @@not_found
    
    mov rax, [rbx].Debugger.breakpoints
    imul edx, ecx, SIZEOF Breakpoint
    cmp [rax + rdx].Breakpoint.address, r8
    je @@found
    
    inc ecx
    jmp @@loop
    
@@found:
    ; Restore original byte
    ; WriteProcessMemory(process, address, &original_byte, 1, NULL)
    
    ; Remove from array (swap with last)
    mov eax, [rbx].Debugger.bp_count
    dec eax
    mov [rbx].Debugger.bp_count, eax
    
    mov eax, 1
    jmp @@done
    
@@not_found:
    xor eax, eax
    
@@done:
    add rsp, 48
    pop rbx
    ret
Debugger_RemoveBreakpoint ENDP

; Debugger_Continue - Continue execution
; RCX = this
Debugger_Continue PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    
    mov ecx, [rbx].Debugger.target_pid
    mov edx, [rbx].Debugger.current_thread
    mov r8d, DBG_CONTINUE
    call ContinueDebugEvent
    
    add rsp, 48
    pop rbx
    ret
Debugger_Continue ENDP

; Debugger_StepOver - Step over current instruction
; RCX = this
Debugger_StepOver PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    
    ; Set trap flag in EFLAGS to trigger EXCEPTION_SINGLE_STEP
    ; GetThreadContext -> set TF -> SetThreadContext
    
    ; Continue
    mov rcx, rbx
    call Debugger_Continue
    
    add rsp, 48
    pop rbx
    ret
Debugger_StepOver ENDP

; Debugger_WaitForEvent - Wait for debug event
; RCX = this
; Returns: EAX = event type
Debugger_WaitForEvent PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    
    mov rcx, [rbx].Debugger.debug_event
    mov edx, 0FFFFFFFFh     ; INFINITE
    call WaitForDebugEvent
    
    test eax, eax
    jz @@error
    
    ; Extract event info
    mov rax, [rbx].Debugger.debug_event
    mov eax, [rax]          ; DEBUG_EVENT.dwDebugEventCode
    jmp @@done
    
@@error:
    xor eax, eax
    
@@done:
    add rsp, 48
    pop rbx
    ret
Debugger_WaitForEvent ENDP

; Debugger_GetRegisters - Get current register values
; RCX = this, RDX = out_context
Debugger_GetRegisters PROC FRAME
    push rbx
    .pushreg rbx
    push r12
    .pushreg r12
    push r13
    .pushreg r13
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx        ; Debugger*
    mov r13, rdx        ; out_context CONTEXT* (callee-save)
    
    ; Set full context capture flag
    mov dword ptr [r13], CONTEXT_FULL
    
    ; OpenThread(THREAD_GET_CONTEXT, FALSE, current_thread_id)
    mov ecx, THREAD_GET_CONTEXT
    xor edx, edx
    mov r8d, [rbx].Debugger.current_thread
    call OpenThread
    test rax, rax
    jz @@getregs_fail
    mov r12, rax        ; r12 = hThread
    
    ; GetThreadContext(hThread, pContext)
    mov rcx, r12
    mov rdx, r13
    call GetThreadContext
    mov [rsp+32], rax   ; stash result beyond shadow space
    
    ; CloseHandle(hThread)
    mov rcx, r12
    call CloseHandle
    
    mov rax, [rsp+32]   ; return GetThreadContext BOOL
    jmp @@getregs_done
    
@@getregs_fail:
    xor eax, eax
    
@@getregs_done:
    add rsp, 48
    pop r13
    pop r12
    pop rbx
    ret
Debugger_GetRegisters ENDP

;------------------------------------------------------------------------------
; SECTION 4: PROFILER IMPLEMENTATION
;------------------------------------------------------------------------------

; Profiler_Init - Initialize profiler
; RCX = this, EDX = sample_capacity
Profiler_Init PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    
    mov [rbx].Profiler.sample_count, 0
    mov [rbx].Profiler.sample_capacity, edx
    mov [rbx].Profiler.is_running, 0
    
    ; Allocate samples array
    mov ecx, edx
    imul ecx, SIZEOF ProfileSample
    call malloc
    mov [rbx].Profiler.samples, rax
    
    ; Get QPC frequency
    lea rcx, [rbx].Profiler.frequency
    call QueryPerformanceFrequency
    
    add rsp, 48
    pop rbx
    ret
Profiler_Init ENDP

; Profiler_Start - Start profiling
; RCX = this
Profiler_Start PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    
    mov [rbx].Profiler.is_running, 1
    mov [rbx].Profiler.sample_count, 0
    
    ; Record start time
    lea rcx, [rbx].Profiler.start_time
    call QueryPerformanceCounter
    
    add rsp, 48
    pop rbx
    ret
Profiler_Start ENDP

; Profiler_Stop - Stop profiling
; RCX = this
Profiler_Stop PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    mov [rbx].Profiler.is_running, 0
    
    add rsp, 48
    pop rbx
    ret
Profiler_Stop ENDP

; Profiler_RecordFunctionEnter - Record function entry
; RCX = this, EDX = function_id
Profiler_RecordFunctionEnter PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    mov r8d, edx            ; function_id
    
    cmp [rbx].Profiler.is_running, 0
    je @@done
    
    ; Check capacity
    mov eax, [rbx].Profiler.sample_count
    cmp eax, [rbx].Profiler.sample_capacity
    jge @@done
    
    ; Get sample slot
    mov rcx, [rbx].Profiler.samples
    imul eax, eax, SIZEOF ProfileSample
    lea rcx, [rcx + rax]
    
    ; Record timestamp
    push rcx
    push r8
    lea rcx, [rcx].ProfileSample.timestamp
    call QueryPerformanceCounter
    pop r8
    pop rcx
    
    ; Fill sample
    mov [rcx].ProfileSample.event_type, PROF_FUNCTION_ENTER
    mov [rcx].ProfileSample.function_id, r8d
    
    inc [rbx].Profiler.sample_count
    
@@done:
    add rsp, 48
    pop rbx
    ret
Profiler_RecordFunctionEnter ENDP

; Profiler_RecordFunctionExit - Record function exit
; RCX = this, EDX = function_id
Profiler_RecordFunctionExit PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    mov r8d, edx
    
    cmp [rbx].Profiler.is_running, 0
    je @@done
    
    mov eax, [rbx].Profiler.sample_count
    cmp eax, [rbx].Profiler.sample_capacity
    jge @@done
    
    ; Get sample slot
    mov rcx, [rbx].Profiler.samples
    imul eax, eax, SIZEOF ProfileSample
    lea rcx, [rcx + rax]
    
    ; Record timestamp
    push rcx
    push r8
    lea rcx, [rcx].ProfileSample.timestamp
    call QueryPerformanceCounter
    pop r8
    pop rcx
    
    mov [rcx].ProfileSample.event_type, PROF_FUNCTION_EXIT
    mov [rcx].ProfileSample.function_id, r8d
    
    ; Calculate duration from matching enter
    ; ... (would search backward for matching enter)
    
    inc [rbx].Profiler.sample_count
    
@@done:
    add rsp, 48
    pop rbx
    ret
Profiler_RecordFunctionExit ENDP

; Profiler_RecordAllocation - Record memory allocation
; RCX = this, RDX = size
Profiler_RecordAllocation PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    mov r8, rdx             ; size
    
    cmp [rbx].Profiler.is_running, 0
    je @@done
    
    mov eax, [rbx].Profiler.sample_count
    cmp eax, [rbx].Profiler.sample_capacity
    jge @@done
    
    mov rcx, [rbx].Profiler.samples
    imul eax, eax, SIZEOF ProfileSample
    lea rcx, [rcx + rax]
    
    ; Timestamp
    push rcx
    push r8
    lea rcx, [rcx].ProfileSample.timestamp
    call QueryPerformanceCounter
    pop r8
    pop rcx
    
    mov [rcx].ProfileSample.event_type, PROF_ALLOCATION
    mov [rcx].ProfileSample.allocation_size, r8
    
    inc [rbx].Profiler.sample_count
    
@@done:
    add rsp, 48
    pop rbx
    ret
Profiler_RecordAllocation ENDP

; Profiler_GetReport - Generate profiling report
; RCX = this
; Returns: RAX = report string (caller must free)
Profiler_GetReport PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    
    ; Allocate report buffer
    mov ecx, 4096
    call malloc
    mov rsi, rax
    
    ; Build report
    ; - Total samples
    ; - Function hotspots (most time spent)
    ; - Allocation patterns
    
    ; ... (formatting logic)
    
    mov rax, rsi
    
    add rsp, 48
    pop rsi
    pop rbx
    ret
Profiler_GetReport ENDP

;------------------------------------------------------------------------------
; SECTION 5: UI INTEGRATION HELPERS
;------------------------------------------------------------------------------

; UIPanel_Create - Create UI panel
; RCX = panel_id, EDX = x, R8D = y, R9D = width
; [rsp+40] = height
UIPanel_Create PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    ; Allocate panel
    mov ebx, ecx            ; panel_id
    mov [rsp+32], edx       ; x
    mov [rsp+36], r8d       ; y
    mov [rsp+40], r9d       ; width
    
    mov ecx, SIZEOF UIPanel
    call malloc
    
    mov [rax].UIPanel.panel_id, ebx
    mov [rax].UIPanel.visible, 1
    mov ecx, [rsp+32]
    mov [rax].UIPanel.x, ecx
    mov ecx, [rsp+36]
    mov [rax].UIPanel.y, ecx
    mov ecx, [rsp+40]
    mov [rax].UIPanel.width, ecx
    mov [rax].UIPanel.content, 0
    
    add rsp, 48
    pop rbx
    ret
UIPanel_Create ENDP

; UIPanel_Show - Show/hide panel
; RCX = panel, DL = visible
UIPanel_Show PROC FRAME
    sub rsp, 40
    .allocstack 40
    .endprolog
    
    mov [rcx].UIPanel.visible, dl
    
    ; Trigger redraw
    ; ... (platform-specific UI code)
    
    add rsp, 40
    ret
UIPanel_Show ENDP

; UIPanel_SetContent - Set panel content
; RCX = panel, RDX = content (rendered HTML/text)
UIPanel_SetContent PROC FRAME
    sub rsp, 40
    .allocstack 40
    .endprolog
    
    ; Free old content if any
    mov rax, [rcx].UIPanel.content
    test rax, rax
    jz @@set
    
    push rcx
    push rdx
    mov rcx, rax
    call free
    pop rdx
    pop rcx
    
@@set:
    mov [rcx].UIPanel.content, rdx
    
    add rsp, 40
    ret
UIPanel_SetContent ENDP

; UIPanel_Destroy - Destroy panel
; RCX = panel
UIPanel_Destroy PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rbx, rcx
    
    ; Free content
    mov rcx, [rbx].UIPanel.content
    test rcx, rcx
    jz @@free_panel
    call free
    
@@free_panel:
    mov rcx, rbx
    call free
    
    add rsp, 48
    pop rbx
    ret
UIPanel_Destroy ENDP

