    mov eax, edx
    shl eax, 3
    add eax, r8d
    mov rax, [rcx].ModelRouter.task_scores
    addss xmm0, [rax + eax*4]
    movss [rax + eax*4], xmm0
    
    add rsp, 40
    ret
ModelRouter_UpdateScore ENDP

