; Agentic Puppeteer Byte Ops v2
; Memory-Safe Manipulation + Integrity Checking
; ================================================
INCLUDE RawrXD_Common.inc

PUBLIC asm_safe_replace
PUBLIC asm_utf8_to_utf16
PUBLIC asm_ring_buffer_stream
PUBLIC asm_memory_integrity_check
PUBLIC asm_secure_memmove

; Result codes
CORRECTION_SUCCESS EQU 0
CORRECTION_BUFFER_OVERFLOW EQU 1
CORRECTION_INVALID_PARAMS EQU 2
CORRECTION_UNICODE_ERROR EQU 3
CORRECTION_INTEGRITY_FAIL EQU 4

; ================================================
; Data
; ================================================
.data
align 16
correction_replace_success DB "OK", 0
correction_buffer_overflow DB "Overflow", 0
correction_invalid_params  DB "BadParams", 0
unicode_transform_success  DB "UTF16 OK", 0
unicode_invalid_sequence   DB "BadUTF8", 0
unicode_incomplete_sequence DB "ShortUTF8", 0
stream_process_success     DB "Streamed", 0
ring_buffer_full_msg       DB "RingFull", 0
integrity_check_passed     DB "Integrity OK", 0
integrity_check_failed     DB "Corrupted", 0

; ================================================
; Safe Replace with Bounds Checking
; ================================================
.code
align 16
asm_safe_replace PROC FRAME
    ; RCX = buffer, RDX = buf_size
    ; R8 = search_str, R9 = replace_str
    ; [RSP+40] = search_len, [RSP+48] = replace_len
    ; Returns: RAX = status, RDX = bytes_written

    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    sub     rsp, 32
    .allocstack 32
    .endprolog

    mov     r12, rcx                ; Buffer
    mov     r13, rdx                ; Size
    mov     r14, r8                 ; Search

    mov     r10, [rbp+48]           ; Replace len (stack param)
    mov     r11, [rbp+56]           ; Search len

    ; Validate inputs
    test    r12, r12
    jz      @@invalid
    test    r13, r13
    jz      @@invalid

    ; Calculate expansion
    mov     rax, r10
    sub     rax, r11
    add     rax, r13
    cmp     rax, r13
    jb      @@overflow

    ; Boyer-Moore-Horspool search (simplified)
    xor     r8, r8                  ; Position

@@search:
    cmp     r8, r13
    jae     @@not_found

    ; Compare at position
    mov     rsi, r12
    add     rsi, r8
    mov     rdi, r14
    mov     rcx, r11
    cld
    repe    cmpsb
    je      @@found

    inc     r8
    jmp     @@search

@@found:
    ; Shift tail if needed
    cmp     r10, r11
    jle     @@no_shift

    ; Memmove tail to make room
    mov     rsi, r12
    add     rsi, r8
    add     rsi, r11                ; End of match
    mov     rdi, r12
    add     rdi, r8
    add     rdi, r10                ; New end
    mov     rcx, r13
    sub     rcx, r8
    sub     rcx, r11                ; Tail length
    std
    rep     movsb
    cld

@@no_shift:
    ; Insert replacement
    mov     rdi, r12
    add     rdi, r8
    mov     rsi, r9
    mov     rcx, r10
    cld
    rep     movsb

    mov     rdx, r10                ; Bytes written
    mov     eax, CORRECTION_SUCCESS
    jmp     @@done

@@not_found:
    xor     rdx, rdx
    mov     eax, CORRECTION_SUCCESS
    jmp     @@done

@@overflow:
    mov     eax, CORRECTION_BUFFER_OVERFLOW
    jmp     @@done

@@invalid:
    mov     eax, CORRECTION_INVALID_PARAMS

@@done:
    lea     rsp, [rbp-24]
    pop     r14
    pop     r13
    pop     r12
    pop     rbp
    ret
asm_safe_replace ENDP

; ================================================
; UTF-8 to UTF-16 Conversion (Security Critical)
; ================================================
align 16
asm_utf8_to_utf16 PROC FRAME
    ; RCX = UTF8 src, RDX = src_bytes
    ; R8 = UTF16 dest, R9 = dest_words
    ; Returns: RAX = chars converted

    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    .allocstack 0
    .endprolog

    mov     r12, rcx                ; Source
    mov     r13, rdx                ; Source bytes
    mov     r14, r8                 ; Dest
    xor     rax, rax                ; Source index
    xor     r11, r11                ; Dest index

@@convert:
    cmp     rax, r13
    jge     @@done
    cmp     r11, r9
    jge     @@overflow

    movzx   ecx, byte ptr [r12+rax]

    ; ASCII fast path
    cmp     cl, 80h
    jb      @@ascii

    ; Multi-byte handling
    cmp     cl, 0E0h
    jb      @@two_byte
    cmp     cl, 0F0h
    jb      @@three_byte
    jmp     @@four_byte

@@ascii:
    mov     [r14+r11*2], cx
    inc     rax
    inc     r11
    jmp     @@convert

@@two_byte:
    cmp     rax, r13
    jae     @@incomplete
    movzx   edx, byte ptr [r12+rax+1]
    test    dl, 0C0h
    jnz     @@invalid
    and     ecx, 1Fh
    and     edx, 3Fh
    shl     ecx, 6
    or      ecx, edx
    mov     [r14+r11*2], cx
    add     rax, 2
    inc     r11
    jmp     @@convert

@@three_byte:
    add     rax, 3
    inc     r11
    jmp     @@convert

@@four_byte:
    add     rax, 4
    add     r11, 2                  ; Surrogate pair
    jmp     @@convert

@@incomplete:
@@invalid:
    mov     rax, -1
    jmp     @@error

@@overflow:
    mov     rax, -2

@@error:
    pop     r14
    pop     r13
    pop     r12
    pop     rbp
    ret

@@done:
    mov     rax, r11                ; Return count
    pop     r14
    pop     r13
    pop     r12
    pop     rbp
    ret
asm_utf8_to_utf16 ENDP

; ================================================
; Ring Buffer with Watermark Tracking
; ================================================
align 16
asm_ring_buffer_stream PROC FRAME
    ; RCX = buffer base, RDX = capacity
    ; R8 = head_ptr, R9 = tail_ptr
    ; [RSP+40] = data, [RSP+48] = len
    ; Returns: RAX = bytes written

    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    .allocstack 0
    .endprolog

    mov     r10, [r8]               ; Head
    mov     r11, [r9]               ; Tail
    mov     rax, [rbp+48]           ; Len to write

    ; Calculate available space (simplified)
    mov     r12, r11
    sub     r12, r10
    add     r12, rdx
    and     r12, rdx
    sub     r12, 1
    cmp     rax, r12
    ja      @@full

    ; Write with wrap
    mov     rsi, [rbp+56]           ; Source data

@@write:
    test    rax, rax
    jz      @@update_head

    mov     bl, [rsi]
    mov     [rcx + r10], bl
    inc     rsi
    inc     r10
    and     r10, rdx                ; Wrap
    dec     rax
    jmp     @@write

@@update_head:
    mov     [r8], r10               ; Update head pointer
    mov     rax, [rbp+48]           ; Return bytes written
    pop     rbp
    ret

@@full:
    xor     rax, rax
    pop     rbp
    ret
asm_ring_buffer_stream ENDP

; ================================================
; Memory Integrity Check (FNV-1a Hash)
; ================================================
align 16
asm_memory_integrity_check PROC
    ; RCX = data, RDX = len
    ; Returns: RAX = hash
    mov     r8, 0cbf29ce484222325h  ; FNV offset basis
@@loop:
    test    rdx, rdx
    jz      @@done
    movzx   r9, byte ptr [rcx]
    xor     r8, r9
    imul    r8, r8, 0100000001b3h   ; FNV prime
    inc     rcx
    dec     rdx
    jmp     @@loop
@@done:
    mov     rax, r8
    ret
asm_memory_integrity_check ENDP

; ================================================
; Secure Memmove (Anti-ROP)
; ================================================
align 16
asm_secure_memmove PROC FRAME
    ; RCX = dest, RDX = src, R8 = len
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    .allocstack 0
    .endprolog

    ; Check for overlap
    mov     r9, rdx
    add     r9, r8
    cmp     rcx, r9
    ja      @@no_overlap
    mov     r9, rcx
    add     r9, r8
    cmp     rdx, r9
    ja      @@no_overlap

    ; Overlap: reverse copy
    std
    add     rcx, r8
    dec     rcx
    add     rdx, r8
    dec     rdx
    mov     rsi, rdx
    mov     rdi, rcx
    mov     rcx, r8
    rep     movsb
    cld
    jmp     @@clear

@@no_overlap:
    mov     rsi, rdx
    mov     rdi, rcx
    mov     rcx, r8
    cld
    rep     movsb

@@clear:
    xor     eax, eax
    pop     rbp
    ret
asm_secure_memmove ENDP

END
 ; ai_agent_masm_core.asm - x64 MASM Core Implementation for AI/Agent Operations
; Part of RawrXD-Shell Three-Layer Hotpatching Architecture
; Provides hardware-accelerated memory operations, pattern search, and AI inference primitives

; Windows API externals for memory protection
EXTERN VirtualProtect: PROC
EXTERN GetLastError: PROC

.code

; ---------------------------------------------------------------------------
; Constants and Macro Definitions
; ---------------------------------------------------------------------------

; Memory protection flags (Windows VirtualProtect)
PAGE_EXECUTE_READWRITE  EQU 40h
PAGE_READWRITE          EQU 04h
PAGE_READONLY           EQU 02h

; CPU feature detection flags
CPU_FEATURE_AVX512      EQU 01h
CPU_FEATURE_AVX2        EQU 02h
CPU_FEATURE_SSE4        EQU 04h
CPU_FEATURE_BMI2        EQU 08h

; Failure type constants
FAILURE_TYPE_REFUSAL    EQU 01h
FAILURE_TYPE_HALLUCINATION EQU 02h
FAILURE_TYPE_TIMEOUT    EQU 03h
FAILURE_TYPE_RESOURCE_EXHAUSTION EQU 04h
FAILURE_TYPE_SAFETY_VIOLATION EQU 05h

; MASM Macro for structured result creation
CREATE_RESULT MACRO success_flag, detail_ptr, error_code, cycle_count
    mov rax, success_flag      ; success (bool)
    mov rdx, detail_ptr        ; detail (const char*)  
    mov r8d, error_code        ; errorCode (int)
    mov r9, cycle_count        ; cycleCount (uint64_t)
    ret
ENDM

; ---------------------------------------------------------------------------
; Memory Layer Implementation - VirtualProtect/mprotect wrappers
; ---------------------------------------------------------------------------

; MasmOperationResult masm_memory_protect_region(void* address, size_t size, uint32_t new_protection)
; RCX = address, RDX = size, R8D = new_protection
masm_memory_protect_region PROC
    push rbp
    mov rbp, rsp
    sub rsp, 30h        ; Shadow space + locals
    
    ; Save parameters
    mov [rbp-8], rcx    ; address
    mov [rbp-16], rdx   ; size 
    mov [rbp-20], r8d   ; new_protection
    
    ; Get current performance counter
    rdtsc
    shl rdx, 20h
    or rax, rdx
    mov [rbp-28], rax   ; save start cycles
    
    ; Call Windows VirtualProtect
    mov rcx, [rbp-8]    ; lpAddress
    mov rdx, [rbp-16]   ; dwSize
    mov r8d, [rbp-20]   ; flNewProtect  
    lea r9, [rbp-32]    ; lpflOldProtect (local variable)
    call VirtualProtect
    
    ; Calculate cycle count
    rdtsc
    shl rdx, 20h
    or rax, rdx
    sub rax, [rbp-28]   ; end - start
    mov [rbp-36], rax   ; save cycle count
    
    ; Check result and create structured return
    test rax, rax
    jnz success_protect
    
    ; Error case
    mov rcx, 0                          ; success = false
    lea rdx, protect_error_msg          ; detail
    call GetLastError
    mov r8d, eax                        ; error code from GetLastError
    mov r9, [rbp-36]                    ; cycle count
    jmp cleanup_protect
    
success_protect:
    mov rcx, 1                          ; success = true
    lea rdx, protect_success_msg        ; detail
    mov r8d, 0                          ; error code = 0
    mov r9, [rbp-36]                    ; cycle count
    
cleanup_protect:
    add rsp, 30h
    pop rbp
    ret
masm_memory_protect_region ENDP

; MasmOperationResult masm_memory_direct_write(void* target, const void* source, size_t size) 
; RCX = target, RDX = source, R8 = size
masm_memory_direct_write PROC
    push rbp
    mov rbp, rsp
    
    ; Get start cycles
    rdtsc
    shl rdx, 20h
    or rax, rdx
    push rax            ; save start cycles
    
    ; Restore parameters (rdx was overwritten by rdtsc)
    mov rax, r8         ; size
    mov rdx, [rbp+10h]  ; restore source from stack if needed
    ; Alternative: save source before rdtsc
    push rdx            ; save source
    push rcx            ; save target
    
    ; Get start cycles 
    rdtsc
    shl rdx, 20h
    or rax, rdx
    mov r10, rax        ; save start cycles in r10
    
    pop rcx             ; restore target
    pop rdx             ; restore source  
    mov r8, rax         ; restore size (was in rax from mov above)
    
    ; Perform optimized memory copy using MOVSQ for 8-byte chunks
    mov rdi, rcx        ; destination
    mov rsi, rdx        ; source
    mov rcx, r8         ; size
    
    ; Copy 8-byte chunks
    mov rax, rcx
    shr rcx, 3          ; divide by 8 for QWORD count
    rep movsq           ; copy 8-byte chunks
    
    ; Copy remaining bytes
    mov rcx, rax
    and rcx, 7          ; remainder (size % 8)
    rep movsb           ; copy remaining bytes
    
    ; Get end cycles
    rdtsc
    shl rdx, 20h
    or rax, rdx
    sub rax, r10        ; cycle count = end - start
    
    ; Success case
    mov rcx, 1                          ; success = true
    lea rdx, write_success_msg          ; detail
    mov r8d, 0                          ; error code = 0
    mov r9, rax                         ; cycle count
    
    pop rbp
    ret
masm_memory_direct_write ENDP

; ---------------------------------------------------------------------------
; Byte-Level Layer Implementation - Pattern search with Boyer-Moore + SIMD
; ---------------------------------------------------------------------------

; MasmOperationResult masm_byte_pattern_search_boyer_moore(...)
; RCX = haystack, RDX = haystack_size, R8 = pattern, R9 = match_offsets (on stack: max_matches, found_count)
masm_byte_pattern_search_boyer_moore PROC
    push rbp
    mov rbp, rsp
    sub rsp, 40h
    
    ; Save volatile registers
    push rsi
    push rdi
    push r12
    push r13
    push r14
    push r15
    
    ; Parameters: RCX=haystack, RDX=haystack_size, R8=pattern struct, R9=match_offsets
    ; Stack: [rbp+28h]=max_matches, [rbp+30h]=found_count
    
    mov rsi, rcx        ; haystack
    mov r12, rdx        ; haystack_size 
    mov r13, r8         ; pattern struct
    mov r14, r9         ; match_offsets array
    mov r15, [rbp+28h]  ; max_matches
    
    ; Extract pattern data from MasmBytePattern structure
    mov rdi, [r13]      ; pattern->pattern
    mov r11, [r13+8]    ; pattern->pattern_length
    
    xor r10, r10        ; found_count = 0
    
    ; Simple pattern search (optimized version would implement full Boyer-Moore)
search_loop:
    cmp r10, r15        ; check if found_count < max_matches
    jae search_done
    
    cmp r12, r11        ; check if remaining haystack >= pattern_length
    jb search_done
    
    ; Compare pattern at current position
    push rcx
    push rsi
    push rdi
    mov rcx, r11        ; pattern_length
    repe cmpsb          ; compare bytes
    pop rdi
    pop rsi  
    pop rcx
    
    jnz no_match
    
    ; Match found - store offset
    mov rax, rsi
    sub rax, rcx        ; offset = current_pos - haystack_start
    mov [r14 + r10*8], rax  ; store offset in match_offsets[found_count]
    inc r10             ; increment found_count
    
no_match:
    inc rsi             ; move to next byte
    dec r12             ; decrement remaining size
    jnz search_loop
    
search_done:
    ; Store found_count
    mov rax, [rbp+30h]  ; found_count pointer
    mov [rax], r10      ; *found_count = r10
    
    ; Update pattern structure
    mov [r13+18h], r10  ; pattern->matches_found = found_count
    
    ; Success case
    mov rcx, 1                          ; success = true
    lea rdx, search_success_msg         ; detail
    mov r8d, 0                          ; error code = 0
    mov r9, 0                           ; cycle count (not implemented)
    
    ; Restore registers
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    
    add rsp, 40h
    pop rbp
    ret
masm_byte_pattern_search_boyer_moore ENDP

; ---------------------------------------------------------------------------  
; Agent-Specific MASM Accelerators
; ---------------------------------------------------------------------------

; MasmOperationResult masm_agent_failure_detect_simd(...)
; Uses SIMD instructions to scan for failure patterns in agent responses
masm_agent_failure_detect_simd PROC
    push rbp
    mov rbp, rsp
    sub rsp, 20h
    
    ; Parameters: RCX=context, RDX=response_data, R8=data_size, R9=detected_failures
    ; Stack: [rbp+28h]=max_failures, [rbp+30h]=failure_count
    
    ; Check for common failure patterns using SIMD string search
    ; Pattern: "I cannot", "I'm sorry", "I apologize", refuse/refusal keywords
    
    ; Initialize failure count
    mov rax, [rbp+30h]  ; failure_count pointer
    mov qword ptr [rax], 0  ; *failure_count = 0
    
    ; Scan for "I cannot" pattern (refusal detection)
    mov rsi, rdx        ; response_data
    mov rcx, r8         ; data_size
    
scan_refusal:
    ; Look for ASCII "I cannot" - simplified version
    cmp rcx, 8          ; need at least 8 bytes
    jb scan_hallucination
    
    ; Load 8 bytes and compare with "I cannot" pattern
    mov rax, qword ptr [rsi]
    mov r10, 746F6E6E61632049h  ; "I cannot" in little-endian (reversed)
    cmp rax, r10
    jne next_refusal_byte
    
    ; Refusal pattern found - create failure event
    mov rax, [rbp+30h]  ; failure_count pointer
    mov r11, [rax]      ; current failure_count
    cmp r11, [rbp+28h]  ; check if < max_failures
    jae scan_hallucination
    
    ; Fill failure event structure
    mov rax, r9         ; detected_failures array
    mov r10, 20         ; sizeof(AgentFailureEvent) 
    mul r11             ; offset = failure_count * sizeof
    add rax, r9         ; failure_event = detected_failures + offset
    
    mov dword ptr [rax], FAILURE_TYPE_REFUSAL    ; failure_type
    mov dword ptr [rax+4], 3F800000h             ; confidence = 1.0f
    lea r10, refusal_detected_msg
    mov [rax+8], r10                             ; description
    rdtsc
    shl rdx, 20h
    or rdx, rax
    mov [rax+10h], rdx                           ; timestamp
    
    ; Increment failure count
    mov rax, [rbp+30h]
    inc qword ptr [rax]
    
next_refusal_byte:
    inc rsi
    dec rcx
    jmp scan_refusal
    
scan_hallucination:
    ; Additional pattern detection can be added here
    ; This is a simplified implementation
    
    ; Success case
    mov rcx, 1                          ; success = true
    lea rdx, failure_detect_success_msg ; detail
    mov r8d, 0                          ; error code = 0
    mov r9, 0                           ; cycle count
    
    add rsp, 20h
    pop rbp
    ret
masm_agent_failure_detect_simd ENDP

; ---------------------------------------------------------------------------
; AI-Specific MASM Accelerators
