; quantum_beaconism_backend.asm — MASM x64 kernels for beacon fusion backend
; =============================================================================
; Exports:
;   qb_masm_normalize_qubit(float* alpha, float* beta)
;   qb_masm_weighted_fitness(const float* values, const float* weights, uint32_t count)
;   qb_masm_entangle_pair(float* betaA, float* betaB, float strength, uint32_t antiCorrelated)
;   qb_masm_abs_dot2_ptr(const float* lhs2, const float* rhs2)
; =============================================================================

PUBLIC qb_masm_normalize_qubit
PUBLIC qb_masm_weighted_fitness
PUBLIC qb_masm_entangle_pair
PUBLIC qb_masm_abs_dot2_ptr

.data
ALIGN 16
qb_one          REAL4 1.0
qb_zero         REAL4 0.0
qb_point_one    REAL4 0.1
qb_inv_sqrt2    REAL4 0.70710678
qb_abs_mask     DWORD 07FFFFFFFh,07FFFFFFFh,07FFFFFFFh,07FFFFFFFh

.code

; void qb_masm_normalize_qubit(float* alpha, float* beta)
; RCX = alpha, RDX = beta
qb_masm_normalize_qubit PROC FRAME
    .endprolog

    test    rcx, rcx
    jz      short @@done
    test    rdx, rdx
    jz      short @@done

    movss   xmm0, DWORD PTR [rcx]
    movss   xmm1, DWORD PTR [rdx]
    mulss   xmm0, xmm0
    mulss   xmm1, xmm1
    addss   xmm0, xmm1
    sqrtss  xmm0, xmm0

    movss   xmm1, DWORD PTR [qb_zero]
    ucomiss xmm0, xmm1
    jbe     short @@fallback

    movss   xmm1, DWORD PTR [rcx]
    divss   xmm1, xmm0
    movss   DWORD PTR [rcx], xmm1

    movss   xmm1, DWORD PTR [rdx]
    divss   xmm1, xmm0
    movss   DWORD PTR [rdx], xmm1
    jmp     short @@done

@@fallback:
    movss   xmm0, DWORD PTR [qb_inv_sqrt2]
    movss   DWORD PTR [rcx], xmm0
    movss   DWORD PTR [rdx], xmm0

@@done:
    ret
qb_masm_normalize_qubit ENDP

; float qb_masm_weighted_fitness(const float* values, const float* weights, uint32_t count)
; RCX = values, RDX = weights, R8D = count
; Returns XMM0 = weighted average
qb_masm_weighted_fitness PROC FRAME
    .endprolog

    xorps   xmm0, xmm0    ; weighted sum
    xorps   xmm1, xmm1    ; weight sum

    test    rcx, rcx
    jz      short @@ret_zero
    test    rdx, rdx
    jz      short @@ret_zero
    test    r8d, r8d
    jz      short @@ret_zero

    xor     r9d, r9d
@@loop:
    cmp     r9d, r8d
    jae     short @@finish

    movss   xmm2, DWORD PTR [rcx + r9*4]
    movss   xmm3, DWORD PTR [rdx + r9*4]
    mulss   xmm2, xmm3
    addss   xmm0, xmm2
    addss   xmm1, xmm3

    inc     r9d
    jmp     short @@loop

@@finish:
    movss   xmm2, DWORD PTR [qb_zero]
    ucomiss xmm1, xmm2
    jbe     short @@ret_zero

    divss   xmm0, xmm1
    ret

@@ret_zero:
    xorps   xmm0, xmm0
    ret
qb_masm_weighted_fitness ENDP

; void qb_masm_entangle_pair(float* betaA, float* betaB, float strength, uint32_t antiCorrelated)
; RCX = betaA, RDX = betaB, XMM2 = strength, R9D = antiCorrelated
qb_masm_entangle_pair PROC FRAME
    .endprolog

    test    rcx, rcx
    jz      short @@done
    test    rdx, rdx
    jz      short @@done

    movss   xmm0, DWORD PTR [rcx]    ; betaA
    movss   xmm1, DWORD PTR [rdx]    ; betaB

    movss   xmm3, DWORD PTR [qb_point_one]
    mulss   xmm2, xmm3               ; strength *= 0.1

    test    r9d, r9d
    jz      short @@correlated

    movss   xmm4, DWORD PTR [qb_one]
    subss   xmm4, xmm1               ; (1 - betaB)
    subss   xmm4, xmm0               ; (1 - betaB) - betaA
    jmp     short @@delta

@@correlated:
    movss   xmm4, xmm1
    subss   xmm4, xmm0               ; betaB - betaA

@@delta:
    mulss   xmm4, xmm2               ; delta
    addss   xmm0, xmm4               ; betaA += delta
    subss   xmm1, xmm4               ; betaB -= delta

    maxss   xmm0, DWORD PTR [qb_zero]
    minss   xmm0, DWORD PTR [qb_one]
    maxss   xmm1, DWORD PTR [qb_zero]
    minss   xmm1, DWORD PTR [qb_one]

    movss   DWORD PTR [rcx], xmm0
    movss   DWORD PTR [rdx], xmm1

@@done:
    ret
qb_masm_entangle_pair ENDP

; float qb_masm_abs_dot2_ptr(const float* lhs2, const float* rhs2)
; RCX = lhs2[2], RDX = rhs2[2]
; Returns XMM0 = abs(lhs2[0]*rhs2[0] + lhs2[1]*rhs2[1])
qb_masm_abs_dot2_ptr PROC FRAME
    .endprolog

    xorps   xmm0, xmm0
    test    rcx, rcx
    jz      short @@done
    test    rdx, rdx
    jz      short @@done

    movss   xmm0, DWORD PTR [rcx]
    movss   xmm1, DWORD PTR [rdx]
    mulss   xmm0, xmm1

    movss   xmm2, DWORD PTR [rcx + 4]
    movss   xmm3, DWORD PTR [rdx + 4]
    mulss   xmm2, xmm3

    addss   xmm0, xmm2
    andps   xmm0, XMMWORD PTR [qb_abs_mask]

@@done:
    ret
qb_masm_abs_dot2_ptr ENDP

END
 ; =============================================================================
; RawrCodex.asm - Pure MASM64 Binary Analysis Engine
; Zero STL, Pure Win32 API Implementation
; Part of RawrXD-Shell Reverse Engineering Suite
;
; Features:
;   - Dynamic array management (no STL containers)
;   - PE32/PE64 parser (IDT, EDT, ILT/IAT, sections, symbols)
;   - ELF32/ELF64 parser (sections, symbols, string tables)
;   - x64 instruction decoder (REX, ModR/M, SIB, two-byte 0F)
;   - Pattern scanner (Boyer-Moore style with wildcard support)
;   - String extraction (ASCII, UTF-16)
;   - IDA Pro script export
;   - RVA-to-file-offset conversion
;   - Control flow graph (CFG) construction with edge linking
;   - Cross-reference (XREF) builder
;   - Function boundary recovery (prologue scan + CALL harvest)
;   - SSA lifting (register→SSA variable renaming with PHI nodes)
;   - Recursive descent disassembler (CFG-guided, avoids inline data)
;   - Type recovery via data flow analysis (Phase 17)
;   - Def-use chain construction
;   - Control flow structuring (dominator tree, edge classification, Phase 18)
;   - Semantic pseudocode emission (C-like output with type annotations, Phase 18)
;
; Build: ml64 /c /Fo RawrCodex.obj RawrCodex.asm
;        link RawrCodex.obj /SUBSYSTEM:CONSOLE kernel32.lib
;
; Calling Convention: Microsoft x64 ABI (RCX, RDX, R8, R9, stack)
; =============================================================================

OPTION CASEMAP:NONE

; =============================================================================
; Windows API Imports
; =============================================================================

EXTERN GetProcessHeap:PROC
EXTERN HeapAlloc:PROC
EXTERN HeapFree:PROC
EXTERN HeapReAlloc:PROC
EXTERN CreateFileA:PROC
EXTERN ReadFile:PROC
EXTERN WriteFile:PROC
EXTERN CloseHandle:PROC
EXTERN GetFileSize:PROC
EXTERN CreateFileMappingA:PROC
EXTERN MapViewOfFile:PROC
EXTERN UnmapViewOfFile:PROC
EXTERN GetLastError:PROC
EXTERN VirtualProtect:PROC
EXTERN lstrlenA:PROC
EXTERN lstrcpyA:PROC
EXTERN lstrcmpA:PROC
EXTERN wsprintfA:PROC

; =============================================================================
; Constants
; =============================================================================

; Heap flags
HEAP_ZERO_MEMORY            EQU 00000008h

; File access
GENERIC_READ                EQU 80000000h
GENERIC_WRITE               EQU 40000000h
FILE_SHARE_READ             EQU 00000001h
OPEN_EXISTING               EQU 3
CREATE_ALWAYS               EQU 2
INVALID_HANDLE_VALUE        EQU -1

; Memory mapping
PAGE_READONLY               EQU 002h
