; ELF Signatures
ELF_MAGIC                   EQU 464C457Fh   ; 0x7F 'ELF'
ELFCLASS32                  EQU 1
ELFCLASS64                  EQU 2
ELFDATA2LSB                 EQU 1

; ELF Section types
SHT_NULL                    EQU 0
SHT_PROGBITS                EQU 1
