@@check_alu_rm_r:
    ; ADD/OR/ADC/SBB/AND/SUB/XOR/CMP r/m, r (even opcodes: 01,09,11,19,21,29,31,39)
    ; These are: base = op/8, direction = op & 2, size = op & 1
    ; op & 0xC7 == 0x01 → ALU rm,r 32/64-bit
    mov edx, eax
    and edx, 0C7h
    cmp edx, 01h
    jne @@check_alu_r_rm
