    shl ecx, 3                      ; * 8 bytes per entry
    push rax
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea r11, aluGroupMn
    lea rdx, [r11 + rcx]
    call lstrcpyA
    pop rax
    ; Skip ModR/M + SIB + disp
    movzx eax, BYTE PTR [rsi + r15]
    inc r15d
    mov ecx, eax
    shr ecx, 6
    mov edx, eax
    and edx, 7
    cmp ecx, 3
    je @@decode_done
    cmp edx, 4
    jne @@alu01_nosib
