    and edx, 0C7h
    cmp edx, 03h
    jne @@check_grp1_imm
    mov ecx, eax
    shr ecx, 3
    and ecx, 7
    shl ecx, 3
    push rax
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea r11, aluGroupMn
    lea rdx, [r11 + rcx]
    call lstrcpyA
    pop rax
    movzx eax, BYTE PTR [rsi + r15]
    inc r15d
    mov ecx, eax
    shr ecx, 6
    mov edx, eax
    and edx, 7
    cmp ecx, 3
    je @@decode_done
    cmp edx, 4
    jne @@alu03_nosib
