    add r15d, 4
    jmp @@decode_done

@@check_grp1_imm:
    ; Group 1: 0x81 = ALU r/m, imm32   0x83 = ALU r/m, imm8
    cmp al, 81h
    je @@grp1_imm32
    cmp al, 83h
    je @@grp1_imm8
    jmp @@check_grp2

@@grp1_imm32:
    ; 0x81 /reg: ALU r/m32/64, imm32
    movzx eax, BYTE PTR [rsi + r15]
    mov ecx, eax
    shr ecx, 3
    and ecx, 7                      ; ALU operation index
    shl ecx, 3
    push rax
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea r11, aluGroupMn
    lea rdx, [r11 + rcx]
    call lstrcpyA
    pop rax
    ; Skip ModR/M
    inc r15d
    mov ecx, eax
    shr ecx, 6
    mov edx, eax
    and edx, 7
    cmp ecx, 3
    jne @@grp1_32_mem
    add r15d, 4                     ; imm32
    jmp @@decode_done
@@grp1_32_mem:
    cmp edx, 4
    jne @@grp1_32_nosib
    inc r15d
@@grp1_32_nosib:
    cmp ecx, 0
    jne @@grp1_32_disp
    cmp edx, 5
    jne @@grp1_32_disp
    add r15d, 4
@@grp1_32_disp:
    cmp ecx, 1
    jne @@grp1_32_d32
    inc r15d
    jmp @@grp1_32_addimm
@@grp1_32_d32:
