    mov ecx, eax
    shr ecx, 3
    and ecx, 7
    shl ecx, 3
    push rax
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea r11, aluGroupMn
    lea rdx, [r11 + rcx]
    call lstrcpyA
    pop rax
