    jne @@grp1_8_nosib
    inc r15d
@@grp1_8_nosib:
    cmp ecx, 0
    jne @@grp1_8_disp
    cmp edx, 5
    jne @@grp1_8_disp
    add r15d, 4
@@grp1_8_disp:
    cmp ecx, 1
    jne @@grp1_8_d32
    inc r15d
    jmp @@grp1_8_addimm
@@grp1_8_d32:
    cmp ecx, 2
    jne @@grp1_8_addimm
    add r15d, 4
@@grp1_8_addimm:
    inc r15d                        ; imm8
    jmp @@decode_done

@@check_grp2:
    ; Group 2 shift/rotate: 0xC1 = shift r/m, imm8   0xD1 = shift r/m, 1   0xD3 = shift r/m, CL
    cmp al, 0C1h
    je @@grp2_imm8
    cmp al, 0D1h
    je @@grp2_one
    cmp al, 0D3h
    je @@grp2_cl
