@@grp2_imm8:
    ; 0xC1 /reg: shift r/m32/64, imm8
    movzx eax, BYTE PTR [rsi + r15]
    mov ecx, eax
    shr ecx, 3
    and ecx, 7
    shl ecx, 3
    push rax
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea r11, shiftGroupMn
    lea rdx, [r11 + rcx]
    call lstrcpyA
    pop rax
    inc r15d                        ; ModR/M
    mov ecx, eax
    shr ecx, 6
    cmp ecx, 3
    je @@grp2_c1_reg
    mov edx, eax
    and edx, 7
    cmp edx, 4
    jne @@grp2_c1_nosib
    inc r15d
@@grp2_c1_nosib:
    cmp ecx, 0
    jne @@grp2_c1_disp
    cmp edx, 5
    jne @@grp2_c1_disp
    add r15d, 4
@@grp2_c1_disp:
    cmp ecx, 1
    jne @@grp2_c1_d32
    inc r15d
    jmp @@grp2_c1_reg
@@grp2_c1_d32:
    cmp ecx, 2
    jne @@grp2_c1_reg
    add r15d, 4
@@grp2_c1_reg:
    inc r15d                        ; imm8
    jmp @@decode_done

@@grp2_one:
    ; 0xD1: shift r/m, 1
    movzx eax, BYTE PTR [rsi + r15]
    mov ecx, eax
    shr ecx, 3
    and ecx, 7
    shl ecx, 3
    push rax
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea r11, shiftGroupMn
    lea rdx, [r11 + rcx]
    call lstrcpyA
    pop rax
    inc r15d                        ; ModR/M
    mov ecx, eax
    shr ecx, 6
    cmp ecx, 3
    je @@decode_done
    mov edx, eax
    and edx, 7
    cmp edx, 4
    jne @@grp2_d1_nosib
    inc r15d
@@grp2_d1_nosib:
    cmp ecx, 0
    jne @@grp2_d1_disp
    cmp edx, 5
    jne @@grp2_d1_disp
    add r15d, 4
    jmp @@decode_done
@@grp2_d1_disp:
    cmp ecx, 1
    jne @@grp2_d1_d32
    inc r15d
    jmp @@decode_done
@@grp2_d1_d32:
    cmp ecx, 2
    jne @@decode_done
    add r15d, 4
    jmp @@decode_done

@@grp2_cl:
    ; 0xD3: shift r/m, CL
    movzx eax, BYTE PTR [rsi + r15]
    mov ecx, eax
    shr ecx, 3
    and ecx, 7
    shl ecx, 3
    push rax
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea r11, shiftGroupMn
    lea rdx, [r11 + rcx]
    call lstrcpyA
    pop rax
    inc r15d
    mov ecx, eax
    shr ecx, 6
    cmp ecx, 3
    je @@decode_done
    mov edx, eax
    and edx, 7
    cmp edx, 4
    jne @@grp2_d3_nosib
