@@grp2_d3_nosib:
    cmp ecx, 0
    jne @@grp2_d3_disp
    cmp edx, 5
    jne @@grp2_d3_disp
    add r15d, 4
    jmp @@decode_done
@@grp2_d3_disp:
    cmp ecx, 1
    jne @@grp2_d3_d32
    inc r15d
    jmp @@decode_done
@@grp2_d3_d32:
