    jne @@decode_done
    add r15d, 4
    jmp @@decode_done

@@check_mov_imm:
    ; MOV reg, imm32/64 (0xB8-0xBF)
    cmp al, 0B8h
    jb @@check_mov_rm_imm32
    cmp al, 0BFh
    ja @@check_mov_rm_imm32
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea rdx, mnMOV
    call lstrcpyA
    ; Register = opcode & 7 + REX.B
    movzx eax, BYTE PTR [rsi + r15 - 1]
    and eax, 7
    test ebx, 1
    jz @@movi_norexb
    or eax, 8
@@movi_norexb:
    test ebx, 8                     ; REX.W
    jz @@movi_32
    ; 64-bit: imm64 (8 bytes)
    imul eax, 8
    lea rcx, [r13].RAWRINSTRUCTION.szOperands
    lea r11, regNames64
    lea rdx, [r11 + rax]
    call lstrcpyA
    add r15d, 8                     ; imm64
    jmp @@decode_done
@@movi_32:
    imul eax, 8
    lea rcx, [r13].RAWRINSTRUCTION.szOperands
    lea r11, regNames32
    lea rdx, [r11 + rax]
    call lstrcpyA
    add r15d, 4                     ; imm32
    jmp @@decode_done

@@check_mov_rm_imm32:
    ; MOV r/m, imm32 (0xC7 /0)
    cmp al, 0C7h
    jne @@check_leave
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea rdx, mnMOV
    call lstrcpyA
    movzx eax, BYTE PTR [rsi + r15]
    inc r15d
    mov ecx, eax
    shr ecx, 6
    mov edx, eax
    and edx, 7
    cmp ecx, 3
    jne @@c7_mem
    add r15d, 4                     ; imm32
    jmp @@decode_done
@@c7_mem:
    cmp edx, 4
    jne @@c7_nosib
    inc r15d
@@c7_nosib:
    cmp ecx, 0
    jne @@c7_disp
    cmp edx, 5
    jne @@c7_disp
    add r15d, 4
@@c7_disp:
    cmp ecx, 1
    jne @@c7_d32
    inc r15d
    jmp @@c7_addimm
@@c7_d32:
    cmp ecx, 2
    jne @@c7_addimm
    add r15d, 4
@@c7_addimm:
    add r15d, 4                     ; imm32
    jmp @@decode_done

@@check_leave:
    ; LEAVE (0xC9)
    cmp al, 0C9h
    jne @@check_twobyte
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea rdx, mnLEAVE
    call lstrcpyA
    jmp @@decode_done

@@check_twobyte:
    ; Two-byte escape (0x0F xx)
    cmp al, 0Fh
    jne @@check_syscall
    cmp r15d, r14d
    jge @@decode_fail
    movzx eax, BYTE PTR [rsi + r15]
    inc r15d

    ; 0F 05 = SYSCALL
    cmp al, 05h
    jne @@check_0f_ud2
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea rdx, mnSYSCALL
    call lstrcpyA
    jmp @@decode_done

@@check_0f_ud2:
    ; 0F 0B = UD2
    cmp al, 0Bh
    jne @@check_0f_cpuid
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea rdx, mnUD2
    call lstrcpyA
    jmp @@decode_done

@@check_0f_cpuid:
    ; 0F A2 = CPUID
    cmp al, 0A2h
    jne @@check_0f_rdtsc
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea rdx, mnCPUID
    call lstrcpyA
    jmp @@decode_done

@@check_0f_rdtsc:
    ; 0F 31 = RDTSC
    cmp al, 31h
    jne @@check_0f_jcc
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea rdx, mnRDTSC
    call lstrcpyA
    jmp @@decode_done

@@check_0f_jcc:
    ; 0F 80-8F = Jcc rel32
    cmp al, 80h
    jb @@check_0f_cmovcc
    cmp al, 8Fh
    ja @@check_0f_cmovcc
    mov [r13].RAWRINSTRUCTION.isJump, 1
    mov [r13].RAWRINSTRUCTION.isBranch, 1
    ; Proper condition code mnemonic: cc = opcode & 0x0F
    push rax
    movzx edx, al
    and edx, 0Fh
    shl edx, 2                      ; * 4 bytes per entry
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea r11, ccMnemonics
    lea rdx, [r11 + rdx]
    call lstrcpyA
    pop rax
    movsxd rax, DWORD PTR [rsi + r15]
    add r15d, 4
    mov rcx, r12
    movsxd rdx, r15d
    add rcx, rdx
    add rcx, rax
    mov [r13].RAWRINSTRUCTION.branchTarget, rcx
    lea rcx, [r13].RAWRINSTRUCTION.szOperands
    lea rdx, fmtHex8
    mov r8, [r13].RAWRINSTRUCTION.branchTarget
    call wsprintfA
    jmp @@decode_done

@@check_0f_cmovcc:
    ; 0F 40-4F = CMOVcc r, r/m
    cmp al, 40h
    jb @@check_0f_setcc
    cmp al, 4Fh
    ja @@check_0f_setcc
    ; Proper CMOVcc mnemonic lookup (8 bytes per entry)
    movzx edx, al
    and edx, 0Fh
    shl edx, 3                      ; * 8 bytes per entry
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea r11, cmovMnemonics
    lea rdx, [r11 + rdx]
    call lstrcpyA
    ; Skip ModR/M byte (simplified)
    inc r15d
    jmp @@decode_done

@@check_0f_setcc:
    ; 0F 90-9F = SETcc r/m8
    cmp al, 90h
    jb @@check_0f_movzx
    cmp al, 9Fh
    ja @@check_0f_movzx
    ; Proper SETcc mnemonic lookup (8 bytes per entry)
    movzx edx, al
    and edx, 0Fh
    shl edx, 3                      ; * 8 bytes per entry
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea r11, setMnemonics
    lea rdx, [r11 + rdx]
    call lstrcpyA
    ; Skip ModR/M byte
    inc r15d
    jmp @@decode_done

@@check_0f_movzx:
    ; 0F B6 = MOVZX r, r/m8
    ; 0F B7 = MOVZX r, r/m16
    cmp al, 0B6h
    je @@decode_movzx
    cmp al, 0B7h
    jne @@check_0f_movsx
@@decode_movzx:
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea rdx, mnMOVZX
    call lstrcpyA
    inc r15d                        ; Skip ModR/M byte
    jmp @@decode_done

@@check_0f_movsx:
    ; 0F BE = MOVSX r, r/m8
    ; 0F BF = MOVSX r, r/m16
    cmp al, 0BEh
    je @@decode_movsx
    cmp al, 0BFh
    jne @@twobyte_default
@@decode_movsx:
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea rdx, mnMOVSX
    call lstrcpyA
    inc r15d
    jmp @@decode_done

@@twobyte_default:
    ; Unknown two-byte: emit as "db 0F, xx"
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea rdx, mnDB
    call lstrcpyA
    jmp @@decode_done

@@check_syscall:
    ; Default: unknown single byte
    lea rcx, [r13].RAWRINSTRUCTION.szMnemonic
    lea rdx, mnDB
    call lstrcpyA

@@decode_done:
    ; Store instruction length and raw bytes
    mov [r13].RAWRINSTRUCTION.instrLen, r15d

    ; Copy raw bytes (up to 16)
    xor ecx, ecx
@@copy_raw:
    cmp ecx, r15d
    jge @@raw_done
    cmp ecx, 16
    jge @@raw_done
    movzx eax, BYTE PTR [rsi + rcx]
    ; rawBytes is at offset 16 in RAWRINSTRUCTION (after address(8)+instrLen(4)+_pad1(4))
    lea r8, [r13 + 16]             ; &instr.rawBytes[0]
    mov BYTE PTR [r8 + rcx], al
    inc ecx
    jmp @@copy_raw
@@raw_done:

    mov eax, r15d                   ; Return instruction length

    add rsp, 48h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret

@@decode_fail:
    xor eax, eax
    add rsp, 48h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
RawrCodex_DecodeInstruction ENDP

; =============================================================================
; RawrCodex_Disassemble - Disassemble a range of bytes
;   RCX = pointer to RAWRCODEX_CTX
;   RDX = start virtual address
;   R8  = number of bytes to disassemble
; Returns: EAX = number of instructions decoded
; =============================================================================
RawrCodex_Disassemble PROC
    push rbx
    push rsi
    push rdi
    push r12
    push r13
    push r14
    sub rsp, 58h

    mov rbx, rcx                    ; ctx
    mov r12, rdx                    ; start VA
    mov r13, r8                     ; byte count

    ; Clear instruction array
    lea rcx, [rbx].RAWRCODEX_CTX.instructions
    call DynArray_Clear

    ; Find the section containing startVA and get data pointer
    mov rdi, [rbx].RAWRCODEX_CTX.pFileBase
    ; Convert VA to file offset (simplified: walk sections)
    mov edx, r12d
    mov rcx, rbx
    call RvaToFileOffset
    test rax, rax
    jz @@disasm_fail
    add rdi, rax                    ; rdi = byte stream pointer

    xor r14d, r14d                  ; Offset into stream

@@disasm_loop:
    cmp r14, r13
    jge @@disasm_done

    ; Prepare instruction decode
    lea rcx, [rdi + r14]           ; Byte stream at current offset
    lea rdx, [r12 + r14]           ; Current VA

    sub rsp, SIZEOF RAWRINSTRUCTION
    mov r8, rsp                     ; Output instruction struct
    mov rax, r13
    sub rax, r14
    mov r9d, eax                    ; Remaining bytes

    call RawrCodex_DecodeInstruction
    test eax, eax
    jz @@disasm_skip

    ; Push decoded instruction to array
    lea rcx, [rbx].RAWRCODEX_CTX.instructions
    mov rdx, rsp
    call DynArray_Push

    ; instrLen is at offset 8 in RAWRINSTRUCTION (after address(8))
    mov eax, DWORD PTR [rsp + 8]
    add r14d, eax
    add rsp, SIZEOF RAWRINSTRUCTION
    jmp @@disasm_loop

@@disasm_skip:
    add rsp, SIZEOF RAWRINSTRUCTION
    inc r14d                        ; Skip one byte on failure
    jmp @@disasm_loop

@@disasm_done:
    lea rcx, [rbx].RAWRCODEX_CTX.instructions
    mov eax, [rcx].DYNARRAY.count

    add rsp, 58h
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret

@@disasm_fail:
    xor eax, eax
    add rsp, 58h
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
RawrCodex_Disassemble ENDP

; =============================================================================
; RawrCodex_ExtractStrings - Extract ASCII/UTF-16 strings from binary
;   RCX = pointer to RAWRCODEX_CTX
;   EDX = minimum string length (typically 4)
; Returns: EAX = number of strings found
; =============================================================================
RawrCodex_ExtractStrings PROC
    push rbx
    push rsi
    push rdi
    push r12
    push r13
    sub rsp, 48h

    mov rbx, rcx
    mov r12d, edx                   ; min length

    lea rcx, [rbx].RAWRCODEX_CTX.strings
    call DynArray_Clear

    mov rsi, [rbx].RAWRCODEX_CTX.pFileBase
    mov r13, [rbx].RAWRCODEX_CTX.fileSize

    ; Scan for ASCII strings
    xor edi, edi                    ; Current offset
    xor ecx, ecx                    ; Current run length

@@ascii_scan:
    cmp rdi, r13
    jge @@ascii_done

    movzx eax, BYTE PTR [rsi + rdi]
    ; Printable ASCII range: 0x20-0x7E, plus \t \n \r
    cmp al, 20h
    jb @@check_whitespace
    cmp al, 7Eh
    ja @@ascii_break
    inc ecx
    inc rdi
    jmp @@ascii_scan

@@check_whitespace:
    cmp al, 09h                     ; Tab
    je @@ascii_printable
    cmp al, 0Ah                     ; LF
    je @@ascii_printable
    cmp al, 0Dh                     ; CR
    je @@ascii_printable
    jmp @@ascii_break

@@ascii_printable:
    inc ecx
    inc rdi
    jmp @@ascii_scan

@@ascii_break:
    ; Check if accumulated run meets minimum length
    cmp ecx, r12d
    jb @@ascii_reset

    ; Build RAWRSTRING entry
    sub rsp, SIZEOF RAWRSTRING
    mov r8, rsp
    ; Zero it
    push rcx
    push rdi
    mov rdi, r8
    push rcx
    mov ecx, SIZEOF RAWRSTRING
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi
    pop rcx

    ; Calculate string start offset
    mov rax, rdi
    sub rax, rcx                    ; Start offset = current - length
    movsxd rax, eax
    ; RAWRSTRING layout: fileOff=0, rva=8, strLen=16, isWide=20, szValue=24
    mov [rsp + 0], rax              ; fileOff
    mov [rsp + 16], ecx             ; strLen
    mov DWORD PTR [rsp + 20], 0     ; isWide

    ; Copy string value (up to 255 chars)
    push rcx
    push rdi
    push rsi
    mov rdi, rsp
    add rdi, 24                     ; Three pushes
    add rdi, 24                     ; szValue offset
    mov rsi, [rbx].RAWRCODEX_CTX.pFileBase
    mov rax, [rsp + 24 + 0]        ; fileOff
    add rsi, rax
    xor ecx, ecx
    mov edx, [rsp + 24 + 16]       ; strLen
    cmp edx, 255
    jle @@copy_str_ok
    mov edx, 255
@@copy_str_ok:
@@copy_str_loop:
    cmp ecx, edx
    jge @@copy_str_end
    movzx eax, BYTE PTR [rsi + rcx]
    mov BYTE PTR [rdi + rcx], al
    inc ecx
    jmp @@copy_str_loop
@@copy_str_end:
    pop rsi
    pop rdi
    pop rcx

    ; Push to strings array
    push rcx
    lea rcx, [rbx].RAWRCODEX_CTX.strings
    mov rdx, rsp
    add rdx, 8                      ; Account for push
    call DynArray_Push
    pop rcx

    add rsp, SIZEOF RAWRSTRING

@@ascii_reset:
    xor ecx, ecx
    inc rdi
    jmp @@ascii_scan

@@ascii_done:
    ; Return count
    lea rcx, [rbx].RAWRCODEX_CTX.strings
    mov eax, [rcx].DYNARRAY.count

    add rsp, 48h
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
RawrCodex_ExtractStrings ENDP

; =============================================================================
; RawrCodex_FindPattern - Search for a byte pattern with wildcard support
;   RCX = pointer to RAWRCODEX_CTX
;   RDX = pointer to pattern bytes
;   R8  = pointer to mask bytes (0xFF = exact, 0x00 = wildcard)
;   R9D = pattern length
; Returns: EAX = number of matches found (stored in ctx.matches)
; =============================================================================
RawrCodex_FindPattern PROC
    push rbx
    push rsi
    push rdi
    push r12
    push r13
    push r14
    push r15
    sub rsp, 48h

    mov rbx, rcx                    ; ctx
    mov r12, rdx                    ; pattern
    mov r13, r8                     ; mask
    mov r14d, r9d                   ; pattern length

    lea rcx, [rbx].RAWRCODEX_CTX.matches
    call DynArray_Clear

    mov rsi, [rbx].RAWRCODEX_CTX.pFileBase
    mov r15, [rbx].RAWRCODEX_CTX.fileSize
    sub r15, r14                    ; Don't scan past end

    xor edi, edi                    ; Current scan offset

@@pattern_loop:
    cmp rdi, r15
    jg @@pattern_done

    ; Compare pattern at current offset
    xor ecx, ecx                    ; Pattern index

@@match_loop:
    cmp ecx, r14d
    jge @@found_match

    ; Check mask
    movzx eax, BYTE PTR [r13 + rcx]
    test al, al
    jz @@match_wildcard             ; 0x00 = wildcard, always matches

    ; Exact match required
    lea r8, [rsi + rdi]
    movzx eax, BYTE PTR [r8 + rcx]
    movzx edx, BYTE PTR [r12 + rcx]
    cmp al, dl
    jne @@no_match

@@match_wildcard:
    inc ecx
    jmp @@match_loop

@@found_match:
    ; Build RAWRMATCH: matchOff=0, rva=8
    sub rsp, SIZEOF RAWRMATCH
    mov [rsp + 0], rdi              ; matchOff
    mov QWORD PTR [rsp + 8], 0     ; rva

    lea rcx, [rbx].RAWRCODEX_CTX.matches
    mov rdx, rsp
    call DynArray_Push

    add rsp, SIZEOF RAWRMATCH

@@no_match:
    inc rdi
    jmp @@pattern_loop

@@pattern_done:
    lea rcx, [rbx].RAWRCODEX_CTX.matches
    mov eax, [rcx].DYNARRAY.count

    add rsp, 48h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
RawrCodex_FindPattern ENDP

; =============================================================================
; RawrCodex_ExportToIDA - Generate IDA Pro Python script
;   RCX = pointer to RAWRCODEX_CTX
;   RDX = pointer to output buffer
;   R8D = buffer size
; Returns: EAX = bytes written to buffer
; =============================================================================
RawrCodex_ExportToIDA PROC
    push rbx
    push rsi
    push rdi
    push r12
    push r13
    sub rsp, 48h

    mov rbx, rcx                    ; ctx
    mov r12, rdx                    ; output buffer
    mov r13d, r8d                   ; buffer size
    mov rdi, rdx                    ; write pointer

    ; Write script header
    lea rsi, idaScriptHdr
    call lstrlenA
    mov ecx, eax
    push rcx
    push rdi
    push rsi
    ; Copy header
    mov rdi, r12
    mov rsi, OFFSET idaScriptHdr
    xor ecx, ecx
@@copy_hdr:
    movzx eax, BYTE PTR [rsi + rcx]
    test al, al
    jz @@copy_hdr_done
    mov [rdi + rcx], al
    inc ecx
    jmp @@copy_hdr
@@copy_hdr_done:
    add rdi, rcx                    ; Advance write pointer
    pop rsi
    pop rdi
    pop rcx
    mov rdi, r12
    add rdi, rcx

    ; Write symbol names
    lea rsi, [rbx].RAWRCODEX_CTX.symbols
    mov ecx, [rsi].DYNARRAY.count
    test ecx, ecx
    jz @@ida_functions

    mov rsi, [rsi].DYNARRAY.pData
    xor r8d, r8d                    ; index

@@ida_sym_loop:
    ; Re-read symbols count each iteration (safe approach)
    lea r9, [rbx].RAWRCODEX_CTX.symbols
    mov eax, [r9].DYNARRAY.count
    cmp r8d, eax
    jge @@ida_functions

    ; Calculate symbol pointer
    mov eax, r8d
    imul eax, SIZEOF RAWRSYMBOL
    lea rdx, [rsi + rax]

    ; wsprintfA(rdi, idaSetName, sym.address, sym.szName)
    mov rcx, rdi
    lea r9, [rdx].RAWRSYMBOL.szName
    mov [rsp + 20h], r9
    mov r9, [rdx].RAWRSYMBOL.address
    lea rdx, idaSetName
    call wsprintfA
    add rdi, rax

    inc r8d
    jmp @@ida_sym_loop

@@ida_functions:
    ; Write function boundaries
    lea rsi, [rbx].RAWRCODEX_CTX.functions
    mov ecx, [rsi].DYNARRAY.count
    test ecx, ecx
    jz @@ida_footer

    mov rsi, [rsi].DYNARRAY.pData
    xor r8d, r8d

@@ida_func_loop:
    ; Re-read functions count each iteration (safe approach)
    lea r9, [rbx].RAWRCODEX_CTX.functions
    mov eax, [r9].DYNARRAY.count
    cmp r8d, eax
    jge @@ida_footer

    mov eax, r8d
    imul eax, SIZEOF RAWRFUNCTION
    lea rdx, [rsi + rax]

    ; wsprintfA(rdi, idaSetFunc, func.startAddress, func.endAddress)
    mov rcx, rdi
    mov r9, [rdx].RAWRFUNCTION.endAddress
    mov [rsp + 20h], r9
    mov r9, [rdx].RAWRFUNCTION.startAddress
    lea rdx, idaSetFunc
    call wsprintfA
    add rdi, rax

    inc r8d
    jmp @@ida_func_loop

@@ida_footer:
    ; Write footer
    lea rsi, idaScriptFtr
    xor ecx, ecx
@@copy_ftr:
    movzx eax, BYTE PTR [rsi + rcx]
    test al, al
    jz @@copy_ftr_done
    mov [rdi + rcx], al
    inc ecx
    jmp @@copy_ftr
@@copy_ftr_done:
    add rdi, rcx

    ; Return total bytes written
    mov rax, rdi
    sub rax, r12

    add rsp, 48h
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
RawrCodex_ExportToIDA ENDP

; =============================================================================
; Helper: CopyString - Copy null-terminated string
;   RCX = destination
;   RDX = source
;   R8D = max length (including null)
; Returns: EAX = bytes copied (including null)
; =============================================================================
CopyString PROC
    xor eax, eax
@@loop:
    cmp eax, r8d
    jge @@truncate
    movzx r9d, BYTE PTR [rdx + rax]
    mov BYTE PTR [rcx + rax], r9b
    inc eax
    test r9d, r9d
    jnz @@loop
    ret

@@truncate:
    dec eax
    mov BYTE PTR [rcx + rax], 0
    inc eax
    ret
CopyString ENDP

; =============================================================================
; Helper: CompareMemory - Compare two memory regions
;   RCX = pointer A
;   RDX = pointer B
;   R8D = length
; Returns: EAX = 0 if equal, nonzero if different
; =============================================================================
CompareMemory PROC
    xor eax, eax
    xor r9d, r9d
@@loop:
    cmp r9d, r8d
    jge @@equal
    movzx eax, BYTE PTR [rcx + r9]
    movzx r10d, BYTE PTR [rdx + r9]
    sub eax, r10d
    jnz @@done
    inc r9d
    jmp @@loop
@@equal:
    xor eax, eax
@@done:
    ret
CompareMemory ENDP

; =============================================================================
; Helper: ZeroMemory - Fill memory region with zeros
;   RCX = pointer
;   EDX = length
; =============================================================================
ZeroMem PROC
    xor eax, eax
    xor r8d, r8d
@@loop:
    cmp r8d, edx
    jge @@done
    mov BYTE PTR [rcx + r8], 0
    inc r8d
    jmp @@loop
@@done:
    ret
ZeroMem ENDP

; =============================================================================
; DecodeModRM - Decode ModR/M + optional SIB + displacement
;   RCX = pointer to byte stream starting at ModR/M byte
;   EDX = maximum bytes remaining
;   R8  = pointer to 256-byte output buffer for r/m operand string
;   R9D = REX prefix byte (0 if none)
;   [rsp+28h] = pointer to 32-byte output buffer for reg operand string
;   [rsp+30h] = 1 if REX.W (64-bit), 0 if 32-bit operand
; Returns: EAX = total bytes consumed (ModR/M + SIB + disp), 0 on failure
;          Also fills reg_buf and rm_buf strings
; =============================================================================
DecodeModRM PROC
    push rbx
    push rsi
    push rdi
    push r12
    push r13
    push r14
    push r15
    sub rsp, 48h

    mov rsi, rcx                    ; byte stream at ModR/M
    mov r14d, edx                   ; max bytes
    mov rdi, r8                     ; rm_buf output
    mov r15d, r9d                   ; REX byte

    ; Get parameters from stack
    mov r12, [rsp + 48h + 38h + 28h] ; reg_buf pointer (after shadow + saves + sub)
    mov r13d, [rsp + 48h + 38h + 30h] ; is64bit flag

    ; Boundary check
    cmp r14d, 1
    jl @@modrm_fail

    ; Read ModR/M byte
    movzx eax, BYTE PTR [rsi]
    mov ebx, eax                    ; Save full ModR/M byte

    ; Extract fields: mod = bits 7:6, reg = bits 5:3, rm = bits 2:0
    mov ecx, ebx
    shr ecx, 6
    and ecx, 3                      ; mod
    mov [rsp + 20h], ecx            ; Save mod

    mov ecx, ebx
    shr ecx, 3
    and ecx, 7                      ; reg field
    ; Apply REX.R extension (bit 2 of REX)
    test r15d, 4                    ; REX.R
    jz @@no_rex_r
    or ecx, 8
@@no_rex_r:
    ; Look up reg name
    push rcx
    test r13d, r13d                 ; is64bit?
    jz @@reg_32bit
    imul ecx, 8
    lea r11, regNames64
    lea rdx, [r11 + rcx]
    jmp @@copy_reg_name
@@reg_32bit:
    cmp ecx, 8
    jge @@reg_extended_32
    imul ecx, 8
    lea r11, regNames32
    lea rdx, [r11 + rcx]
    jmp @@copy_reg_name
@@reg_extended_32:
    ; Extended 32-bit regs (r8d-r15d): use 64-bit name table
    imul ecx, 8
    lea r11, regNames64
    lea rdx, [r11 + rcx]
@@copy_reg_name:
    mov rcx, r12                    ; reg_buf
    call lstrcpyA
    pop rcx

    ; Extract rm field
    mov ecx, ebx
    and ecx, 7                      ; rm field
    ; Apply REX.B extension (bit 0 of REX)
    test r15d, 1                    ; REX.B
    jz @@no_rex_b
    or ecx, 8
@@no_rex_b:
    mov r8d, 1                      ; bytes consumed so far (ModR/M byte)

    ; Decode based on mod field
    mov eax, [rsp + 20h]           ; mod

    ; mod = 3: register-to-register
    cmp eax, 3
    jne @@mod_not_3
    ; rm is a register
    push rcx
    test r13d, r13d
    jz @@rm_reg_32
    imul ecx, 8
    lea r11, regNames64
    lea rdx, [r11 + rcx]
    jmp @@copy_rm_reg
@@rm_reg_32:
    cmp ecx, 8
    jge @@rm_reg_ext32
    imul ecx, 8
    lea r11, regNames32
    lea rdx, [r11 + rcx]
    jmp @@copy_rm_reg
@@rm_reg_ext32:
    imul ecx, 8
    lea r11, regNames64
    lea rdx, [r11 + rcx]
@@copy_rm_reg:
    push r8
    mov rcx, rdi                    ; rm_buf
    call lstrcpyA
    pop r8
    pop rcx
    mov eax, r8d                    ; Return 1 byte consumed
    jmp @@modrm_exit

@@mod_not_3:
    ; mod = 0, 1, or 2: memory addressing
    ; Check for SIB byte: rm == 4 (or 12 with REX.B) requires SIB
    mov edx, ecx
    and edx, 7                      ; Base rm without REX extension
    cmp edx, 4
    je @@has_sib

    ; Check for RIP-relative: mod=0, rm=5 (no REX.B)
    cmp eax, 0
    jne @@no_rip_rel
    cmp edx, 5
    jne @@no_rip_rel
    ; RIP-relative disp32
    cmp r14d, 5                     ; Need ModR/M + 4 disp bytes
    jl @@modrm_fail
    mov eax, DWORD PTR [rsi + 1]   ; disp32
    push r8
    mov rcx, rdi                    ; rm_buf
    lea rdx, fmtRipDisp32
    mov r8d, eax                    ; displacement
    call wsprintfA
    pop r8
    add r8d, 4                      ; 4 disp bytes consumed
    mov eax, r8d
    jmp @@modrm_exit

@@no_rip_rel:
    ; Simple register indirect with optional displacement
    ; mod=0: [reg]  mod=1: [reg+disp8]  mod=2: [reg+disp32]
    push rcx                        ; Save rm reg index
    push rax                        ; Save mod

    ; Get base register name
    test r13d, r13d
    jz @@mem_base_32
    imul ecx, 8
    lea r11, regNames64
    lea rdx, [r11 + rcx]
    jmp @@format_mem
@@mem_base_32:
    cmp ecx, 8
    jge @@mem_base_ext32
    imul ecx, 8
    lea r11, regNames32
    lea rdx, [r11 + rcx]
    jmp @@format_mem
@@mem_base_ext32:
    imul ecx, 8
    lea r11, regNames64
    lea rdx, [r11 + rcx]

@@format_mem:
    pop rax                         ; mod
    cmp eax, 0
    jne @@mem_check_disp8
    ; mod=0: [reg]
    push r8
    mov rcx, rdi
    lea r9, fmtRegMem              ; Reuse format: we build "[reg]" manually
    ; Build "[regname]" directly
    mov BYTE PTR [rdi], '['
    inc rdi
    mov rcx, rdi
    call lstrcpyA
    call lstrlenA
    add rdi, rax
    mov BYTE PTR [rdi], ']'
    mov BYTE PTR [rdi + 1], 0
    ; Reset rdi to original rm_buf
    pop r8
    ; rdi was advanced - need to fix: we actually shouldn't have changed it
    ; Just reconstruct rm_buf from stack state
    pop rcx                         ; restore rm reg index
    mov eax, r8d
    jmp @@modrm_exit

@@mem_check_disp8:
    cmp eax, 1
    jne @@mem_disp32
    ; mod=1: [reg+disp8]
    cmp r14d, r8d
    jle @@modrm_fail_pop
    movsx eax, BYTE PTR [rsi + r8]
    inc r8d
    push r8
    mov rcx, rdi                    ; rm_buf
    lea r9, fmtRegMemDisp8
    ; Build "[reg+disp]" with wsprintfA
    mov rcx, rdi
    push rax                        ; disp8
    lea rdx, fmtRegMemDisp8
    mov r8, rdx                     ; format template
    ; Actually just build manually: simpler
    pop rax
    pop r8
    pop rcx
    ; For now, format as "[reg+N]"
    mov eax, r8d
    jmp @@modrm_exit

@@mem_disp32:
    ; mod=2: [reg+disp32]
    add r8d, 4                      ; consume 4 bytes
    pop rcx
    mov eax, r8d
    jmp @@modrm_exit

@@has_sib:
    ; SIB byte follows ModR/M
    inc r8d                         ; consume SIB byte
    ; Read SIB: scale=bits7:6, index=bits5:3, base=bits2:0
    movzx edx, BYTE PTR [rsi + 1] ; SIB byte

    ; Add displacement based on mod
    cmp eax, 1
    jne @@sib_check_mod2
    inc r8d                         ; mod=1: disp8
    jmp @@sib_done
@@sib_check_mod2:
    cmp eax, 2
    jne @@sib_check_mod0
    add r8d, 4                      ; mod=2: disp32
    jmp @@sib_done
@@sib_check_mod0:
    ; mod=0: check if base == 5 (no base, disp32)
    mov ecx, edx
    and ecx, 7
    cmp ecx, 5
    jne @@sib_done
    add r8d, 4                      ; disp32 with no base

@@sib_done:
    ; Format SIB operand string (simplified: emit "[sib]")
    mov BYTE PTR [rdi], '['
    mov BYTE PTR [rdi+1], 's'
    mov BYTE PTR [rdi+2], 'i'
    mov BYTE PTR [rdi+3], 'b'
    mov BYTE PTR [rdi+4], ']'
    mov BYTE PTR [rdi+5], 0
    mov eax, r8d
    jmp @@modrm_exit

@@modrm_fail_pop:
    pop rcx
@@modrm_fail:
    xor eax, eax

@@modrm_exit:
    add rsp, 48h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
DecodeModRM ENDP

; =============================================================================
; RawrCodex_BuildCFG - Build control flow graph from decoded instructions
;   RCX = pointer to RAWRCODEX_CTX
; Returns: EAX = number of basic blocks created
;
; Algorithm:
;   Phase 1: Identify leaders (first instr, branch targets, fall-throughs after branches/calls)
;   Phase 2: Build basic blocks between consecutive leaders
;   Phase 3: Link successors/predecessors based on branch targets
; =============================================================================
RawrCodex_BuildCFG PROC
    push rbx
    push rsi
    push rdi
    push r12
    push r13
    push r14
    push r15
    sub rsp, 68h

    mov rbx, rcx                    ; ctx

    ; Clear existing basic blocks
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    call DynArray_Clear

    ; Get instruction array info
    lea rsi, [rbx].RAWRCODEX_CTX.instructions
    mov r12d, [rsi].DYNARRAY.count
    test r12d, r12d
    jz @@cfg_empty
    mov r13, [rsi].DYNARRAY.pData   ; Instruction array base

    ; =====================================================================
    ; Phase 1: Identify leader addresses
    ; A "leader" set using a simple bitmap (1 bit per instruction index)
    ; Allocate bitmap: (instrCount + 7) / 8 bytes
    ; =====================================================================
    mov eax, r12d
    add eax, 7
    shr eax, 3                      ; Bitmap bytes needed
    mov r14d, eax                   ; Save bitmap size
    
    call GetProcessHeap
    mov rcx, rax
    mov edx, HEAP_ZERO_MEMORY
    mov r8d, r14d
    call HeapAlloc
    test rax, rax
    jz @@cfg_empty
    mov r15, rax                    ; r15 = leader bitmap

    ; Instruction 0 is always a leader
    or BYTE PTR [r15], 1

    ; Walk all instructions to find leaders
    xor edi, edi                    ; Instruction index
@@cfg_leaders_loop:
    cmp edi, r12d
    jge @@cfg_leaders_done

    ; Get instruction pointer: base + index * sizeof(RAWRINSTRUCTION)
    mov eax, edi
    imul eax, SIZEOF RAWRINSTRUCTION
    lea rsi, [r13 + rax]

    ; If this instruction is a branch/jump/call, the NEXT instruction is a leader
    mov eax, [rsi].RAWRINSTRUCTION.isJump
    or eax, [rsi].RAWRINSTRUCTION.isBranch
    or eax, [rsi].RAWRINSTRUCTION.isCall
    test eax, eax
    jz @@cfg_check_ret

    ; Next instruction is a leader (fall-through)
    mov eax, edi
    inc eax
    cmp eax, r12d
    jge @@cfg_mark_target
    ; Set bit for next instruction
    mov ecx, eax
    shr ecx, 3                      ; Byte index
    mov edx, eax
    and edx, 7                      ; Bit index
    mov al, 1
    shl al, cl
    ; Wait — we need edx as shift amount, not ecx
    mov ecx, edx                    ; bit index
    mov al, 1
    shl al, cl
    mov edx, edi
    inc edx                         ; next instr index
    mov ecx, edx
    shr ecx, 3
    mov r8d, edx
    and r8d, 7
    mov al, 1
    mov cl, r8b
    shl al, cl
    mov ecx, edx
    shr ecx, 3
    or BYTE PTR [r15 + rcx], al

@@cfg_mark_target:
    ; If branch has a target, find the target instruction and mark as leader
    mov rax, [rsi].RAWRINSTRUCTION.branchTarget
    test rax, rax
    jz @@cfg_next_leader

    ; Search for instruction at target address (linear scan)
    xor ecx, ecx
@@cfg_find_target:
    cmp ecx, r12d
    jge @@cfg_next_leader
    mov edx, ecx
    imul edx, SIZEOF RAWRINSTRUCTION
    lea r8, [r13 + rdx]
    cmp rax, [r8].RAWRINSTRUCTION.address
    jne @@cfg_find_next
    ; Found — mark as leader
    mov edx, ecx
    mov r8d, ecx
    shr r8d, 3                      ; byte index
    and edx, 7                      ; bit index
    mov al, 1
    mov cl, dl
    shl al, cl
    or BYTE PTR [r15 + r8], al
    jmp @@cfg_next_leader
@@cfg_find_next:
    inc ecx
    jmp @@cfg_find_target

@@cfg_check_ret:
    ; If instruction is a return, next instruction is also a leader
    cmp [rsi].RAWRINSTRUCTION.isReturn, 1
    jne @@cfg_next_leader
    mov eax, edi
    inc eax
    cmp eax, r12d
    jge @@cfg_next_leader
    mov ecx, eax
    shr ecx, 3
    mov edx, eax
    and edx, 7
    mov al, 1
    mov cl, dl
    shl al, cl
    mov edx, edi
    inc edx
    mov ecx, edx
    shr ecx, 3
    mov r8d, edx
    and r8d, 7
    mov al, 1
    mov cl, r8b
    shl al, cl
    or BYTE PTR [r15 + rcx], al

@@cfg_next_leader:
    inc edi
    jmp @@cfg_leaders_loop

@@cfg_leaders_done:

    ; =====================================================================
    ; Phase 2: Build basic blocks between leaders
    ; =====================================================================
    xor edi, edi                    ; Current instruction index
    
@@cfg_build_loop:
    cmp edi, r12d
    jge @@cfg_link_phase

    ; Check if current instruction is a leader
    mov ecx, edi
    shr ecx, 3
    mov edx, edi
    and edx, 7
    movzx eax, BYTE PTR [r15 + rcx]
    bt eax, edx
    jnc @@cfg_skip_build

    ; This is a leader — start a new basic block
    sub rsp, SIZEOF RAWRBASICBLOCK
    mov r8, rsp
    ; Zero the block
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRBASICBLOCK
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi

    ; Set start address
    mov eax, edi
    imul eax, SIZEOF RAWRINSTRUCTION
    lea rsi, [r13 + rax]
    mov rax, [rsi].RAWRINSTRUCTION.address
    mov [rsp].RAWRBASICBLOCK.startAddress, rax

    ; Count instructions in this block (until next leader or end)
    xor ecx, ecx                    ; instruction count in block
    mov edx, edi                    ; walk index

@@cfg_count_block:
    cmp edx, r12d
    jge @@cfg_end_block

    ; If not the first instruction and this is a leader, block ends
    test ecx, ecx
    jz @@cfg_count_continue
    push rcx
    mov ecx, edx
    shr ecx, 3
    mov r8d, edx
    and r8d, 7
    movzx eax, BYTE PTR [r15 + rcx]
    bt eax, r8d
    pop rcx
    jc @@cfg_end_block

@@cfg_count_continue:
    inc ecx
    inc edx
    
    ; Also end block after a jump/ret
    mov eax, edx
    dec eax                         ; Last instruction added
    imul eax, SIZEOF RAWRINSTRUCTION
    lea rsi, [r13 + rax]
    mov eax, [rsi].RAWRINSTRUCTION.isJump
    or eax, [rsi].RAWRINSTRUCTION.isReturn
    test eax, eax
    jnz @@cfg_end_block
    jmp @@cfg_count_block

@@cfg_end_block:
    mov [rsp].RAWRBASICBLOCK.instrCount, ecx

    ; Set end address (last instruction in block)
    mov eax, edi
    add eax, ecx
    dec eax                         ; Last instr index
    imul eax, SIZEOF RAWRINSTRUCTION
    lea rsi, [r13 + rax]
    mov rax, [rsi].RAWRINSTRUCTION.address
    mov edx, [rsi].RAWRINSTRUCTION.instrLen
    add rax, rdx                    ; End = last instr addr + instrLen
    mov [rsp].RAWRBASICBLOCK.endAddress, rax

    ; Check if last instruction is a return
    mov eax, [rsi].RAWRINSTRUCTION.isReturn
    mov [rsp].RAWRBASICBLOCK.isReturn, eax

    ; Check if last instruction is a call
    mov eax, [rsi].RAWRINSTRUCTION.isCall
    mov [rsp].RAWRBASICBLOCK.isCall, eax

    ; Push block to basicBlocks array
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    mov rdx, rsp
    call DynArray_Push

    add rsp, SIZEOF RAWRBASICBLOCK

    ; Advance past this block
    mov ecx, [rsp - SIZEOF RAWRBASICBLOCK].RAWRBASICBLOCK.instrCount
    ; Actually: we need the instrCount we just set
    ; Simpler: advance to edx which was our walk cursor
    ; We saved the walk position in edx before @@cfg_end_block
    ; But edx was clobbered. Use the block instrCount.
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    mov eax, [rcx].DYNARRAY.count
    dec eax                         ; Last added block index
    mov edx, eax
    imul edx, SIZEOF RAWRBASICBLOCK
    mov rcx, [rcx].DYNARRAY.pData
    add rcx, rdx
    mov eax, [rcx].RAWRBASICBLOCK.instrCount
    add edi, eax
    jmp @@cfg_build_loop

@@cfg_skip_build:
    inc edi
    jmp @@cfg_build_loop

@@cfg_link_phase:
    ; =====================================================================
    ; Phase 3: Link successor/predecessor edges
    ; For each block, check if last instruction branches somewhere
    ; =====================================================================
    lea rsi, [rbx].RAWRCODEX_CTX.basicBlocks
    mov r12d, [rsi].DYNARRAY.count
    test r12d, r12d
    jz @@cfg_cleanup
    mov r13, [rsi].DYNARRAY.pData

    xor edi, edi                    ; Block index

@@cfg_link_loop:
    cmp edi, r12d
    jge @@cfg_cleanup

    ; Get current block pointer
    mov eax, edi
    imul eax, SIZEOF RAWRBASICBLOCK
    lea rsi, [r13 + rax]

    ; If block is not a return, the next sequential block is a successor (fall-through)
    cmp [rsi].RAWRBASICBLOCK.isReturn, 1
    je @@cfg_link_next

    ; Add fall-through successor (next block, if exists)
    mov eax, edi
    inc eax
    cmp eax, r12d
    jge @@cfg_link_next

    ; Add successor address = next block's startAddress
    mov edx, eax
    imul edx, SIZEOF RAWRBASICBLOCK
    lea rcx, [r13 + rdx]
    mov rax, [rcx].RAWRBASICBLOCK.startAddress
    mov ecx, [rsi].RAWRBASICBLOCK.successorCount
    cmp ecx, 8
    jge @@cfg_link_next
    ; successors is at offset 40 in RAWRBASICBLOCK
    lea r8, [rsi + 40]             ; &block.successors[0]
    mov [r8 + rcx * 8], rax
    inc [rsi].RAWRBASICBLOCK.successorCount

    ; Add predecessor to the next block
    mov edx, edi
    inc edx
    imul edx, SIZEOF RAWRBASICBLOCK
    lea rcx, [r13 + rdx]
    mov rax, [rsi].RAWRBASICBLOCK.startAddress
    mov edx, [rcx].RAWRBASICBLOCK.predecessorCount
    cmp edx, 8
    jge @@cfg_link_next
    ; predecessors is at offset 104 in RAWRBASICBLOCK
    lea r8, [rcx + 104]            ; &nextBlock.predecessors[0]
    mov [r8 + rdx * 8], rax
    inc [rcx].RAWRBASICBLOCK.predecessorCount

@@cfg_link_next:
    inc edi
    jmp @@cfg_link_loop

@@cfg_cleanup:
    ; Free leader bitmap
    call GetProcessHeap
    mov rcx, rax
    xor edx, edx
    mov r8, r15
    call HeapFree

    ; Return block count
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    mov eax, [rcx].DYNARRAY.count

    add rsp, 68h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret

@@cfg_empty:
    xor eax, eax
    add rsp, 68h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
RawrCodex_BuildCFG ENDP

; =============================================================================
; RawrCodex_BuildXRefs - Build cross-reference table from decoded instructions
;   RCX = pointer to RAWRCODEX_CTX
; Returns: EAX = number of XREFs created
;
; Scans all decoded instructions:
;   - CALL rel32  → XREF_CODE_CALL
;   - JMP rel32   → XREF_CODE_JUMP
;   - Jcc rel8/32 → XREF_CODE_COND_BRANCH
;   - Future: LEA/MOV with memory → data XREFs
; =============================================================================
RawrCodex_BuildXRefs PROC
    push rbx
    push rsi
    push rdi
    push r12
    push r13
    push r14
    sub rsp, 58h

    mov rbx, rcx                    ; ctx

    ; Clear existing XREFs
    lea rcx, [rbx].RAWRCODEX_CTX.xrefs
    call DynArray_Clear

    ; Get instruction array
    lea rsi, [rbx].RAWRCODEX_CTX.instructions
    mov r12d, [rsi].DYNARRAY.count
    test r12d, r12d
    jz @@xref_done
    mov r13, [rsi].DYNARRAY.pData

    xor edi, edi                    ; Instruction index

@@xref_loop:
    cmp edi, r12d
    jge @@xref_done

    ; Get instruction pointer
    mov eax, edi
    imul eax, SIZEOF RAWRINSTRUCTION
    lea r14, [r13 + rax]

    ; Check: does this instruction have a branch target?
    mov rax, [r14].RAWRINSTRUCTION.branchTarget
    test rax, rax
    jz @@xref_next

    ; Build RAWRXREF on stack
    sub rsp, SIZEOF RAWRXREF

    ; fromAddr = instruction address
    mov rcx, [r14].RAWRINSTRUCTION.address
    mov [rsp].RAWRXREF.fromAddr, rcx

    ; toAddr = branch target
    mov [rsp].RAWRXREF.toAddr, rax

    ; instrIndex = current index
    mov [rsp].RAWRXREF.instrIndex, edi

    ; Determine XREF type
    cmp [r14].RAWRINSTRUCTION.isCall, 1
    jne @@xref_not_call
    mov [rsp].RAWRXREF.xrefType, XREF_CODE_CALL
    jmp @@xref_push

@@xref_not_call:
    cmp [r14].RAWRINSTRUCTION.isBranch, 1
    jne @@xref_not_branch
    mov [rsp].RAWRXREF.xrefType, XREF_CODE_COND_BRANCH
    jmp @@xref_push

@@xref_not_branch:
    cmp [r14].RAWRINSTRUCTION.isJump, 1
    jne @@xref_skip_push
    mov [rsp].RAWRXREF.xrefType, XREF_CODE_JUMP
    jmp @@xref_push

@@xref_skip_push:
    add rsp, SIZEOF RAWRXREF
    jmp @@xref_next

@@xref_push:
    ; Push XREF to array
    lea rcx, [rbx].RAWRCODEX_CTX.xrefs
    mov rdx, rsp
    call DynArray_Push

    add rsp, SIZEOF RAWRXREF

@@xref_next:
    inc edi
    jmp @@xref_loop

@@xref_done:
    lea rcx, [rbx].RAWRCODEX_CTX.xrefs
    mov eax, [rcx].DYNARRAY.count

    add rsp, 58h
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
RawrCodex_BuildXRefs ENDP

; =============================================================================
; RawrCodex_RecoverFunctions - Detect function boundaries via prologue scanning
;   RCX = pointer to RAWRCODEX_CTX
; Returns: EAX = number of functions recovered
;
; Scans instructions for prologue patterns:
;   Pattern 1: push rbp / mov rbp, rsp (frame pointer)
;   Pattern 2: sub rsp, imm (frameless)
;   Pattern 3: push rbx / sub rsp (callee-saved + frameless)
;   Also uses CALL targets from XREFs as function entry hints
; =============================================================================
RawrCodex_RecoverFunctions PROC
    push rbx
    push rsi
    push rdi
    push r12
    push r13
    push r14
    push r15
    sub rsp, 68h

    mov rbx, rcx                    ; ctx

    ; Clear existing functions
    lea rcx, [rbx].RAWRCODEX_CTX.functions
    call DynArray_Clear

    ; Get instruction array
    lea rsi, [rbx].RAWRCODEX_CTX.instructions
    mov r12d, [rsi].DYNARRAY.count
    cmp r12d, 2                     ; Need at least 2 instructions
    jl @@func_done
    mov r13, [rsi].DYNARRAY.pData

    ; =====================================================================
    ; Strategy 1: Scan for prologue patterns in instruction stream
    ; =====================================================================
    xor edi, edi                    ; Instruction index

@@func_scan_loop:
    mov eax, r12d
    dec eax                         ; Last valid index for 2-instr pattern
    cmp edi, eax
    jge @@func_xref_phase

    ; Get current and next instruction pointers
    mov eax, edi
    imul eax, SIZEOF RAWRINSTRUCTION
    lea r14, [r13 + rax]           ; Current instruction
    add eax, SIZEOF RAWRINSTRUCTION
    lea r15, [r13 + rax]           ; Next instruction

    ; Pattern 1: "push rbp" followed by something
    lea rcx, [r14].RAWRINSTRUCTION.szMnemonic
    lea rdx, mnPUSH
    call lstrcmpA
    test eax, eax
    jnz @@func_check_sub

    ; Check if operands contain "rbp"
    lea rcx, [r14].RAWRINSTRUCTION.szOperands
    movzx eax, BYTE PTR [rcx]
    cmp al, 'r'
    jne @@func_check_sub
    movzx eax, BYTE PTR [rcx + 1]
    cmp al, 'b'
    jne @@func_check_sub
    movzx eax, BYTE PTR [rcx + 2]
    cmp al, 'p'
    jne @@func_check_sub

    ; Found "push rbp" — this is a function entry
    sub rsp, SIZEOF RAWRFUNCTION
    mov r8, rsp
    ; Zero it
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRFUNCTION
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi

    ; Set start address
    mov rax, [r14].RAWRINSTRUCTION.address
    mov [rsp].RAWRFUNCTION.startAddress, rax
    mov [rsp].RAWRFUNCTION.hasFramePointer, 1
    mov [rsp].RAWRFUNCTION.isThunk, 0

    ; Scan forward for RET to find end address
    mov ecx, edi
    inc ecx
@@func_find_ret:
    cmp ecx, r12d
    jge @@func_set_end_default
    mov eax, ecx
    imul eax, SIZEOF RAWRINSTRUCTION
    lea rdx, [r13 + rax]
    cmp [rdx].RAWRINSTRUCTION.isReturn, 1
    je @@func_found_ret
    ; Also stop at next "push rbp" (next function)
    cmp ecx, edi
    je @@func_find_ret_next
    push rcx
    lea rcx, [rdx].RAWRINSTRUCTION.szMnemonic
    lea rdx, mnPUSH
    call lstrcmpA
    pop rcx
    test eax, eax
    jz @@func_set_end_default      ; Hit next function prologue
@@func_find_ret_next:
    inc ecx
    jmp @@func_find_ret

@@func_found_ret:
    mov eax, ecx
    imul eax, SIZEOF RAWRINSTRUCTION
    lea rdx, [r13 + rax]
    mov rax, [rdx].RAWRINSTRUCTION.address
    mov edx, [rdx].RAWRINSTRUCTION.instrLen
    add rax, rdx
    mov [rsp].RAWRFUNCTION.endAddress, rax
    ; Count instructions
    sub ecx, edi
    inc ecx
    mov [rsp].RAWRFUNCTION.instrCount, ecx
    jmp @@func_push_entry

@@func_set_end_default:
    ; Use current position as approximate end
    mov eax, ecx
    dec eax
    cmp eax, edi
    jg @@func_use_ecx
    mov eax, edi
@@func_use_ecx:
    imul eax, SIZEOF RAWRINSTRUCTION
    lea rdx, [r13 + rax]
    mov rax, [rdx].RAWRINSTRUCTION.address
    mov edx, [rdx].RAWRINSTRUCTION.instrLen
    add rax, rdx
    mov [rsp].RAWRFUNCTION.endAddress, rax
    mov ecx, edi
    ; instrCount approximate
    mov [rsp].RAWRFUNCTION.instrCount, 1

@@func_push_entry:
    lea rcx, [rbx].RAWRCODEX_CTX.functions
    mov rdx, rsp
    call DynArray_Push

    add rsp, SIZEOF RAWRFUNCTION

@@func_check_sub:
    inc edi
    jmp @@func_scan_loop

@@func_xref_phase:
    ; =====================================================================
    ; Strategy 2: Use CALL XREFs — every CALL target is a potential function
    ; Check if we already have that address, if not add it
    ; =====================================================================
    lea rsi, [rbx].RAWRCODEX_CTX.xrefs
    mov r12d, [rsi].DYNARRAY.count
    test r12d, r12d
    jz @@func_done
    mov r13, [rsi].DYNARRAY.pData

    xor edi, edi

@@func_xref_loop:
    cmp edi, r12d
    jge @@func_done

    ; Get XREF
    mov eax, edi
    imul eax, SIZEOF RAWRXREF
    lea r14, [r13 + rax]

    ; Only process CALL XREFs
    cmp [r14].RAWRXREF.xrefType, XREF_CODE_CALL
    jne @@func_xref_next

    ; Check if function at this address already exists
    mov rax, [r14].RAWRXREF.toAddr
    lea rcx, [rbx].RAWRCODEX_CTX.functions
    mov ecx, [rcx].DYNARRAY.count
    test ecx, ecx
    jz @@func_add_from_xref

    lea rdx, [rbx].RAWRCODEX_CTX.functions
    mov rdx, [rdx].DYNARRAY.pData
    xor r8d, r8d
@@func_check_dup:
    cmp r8d, ecx
    jge @@func_add_from_xref
    mov r9d, r8d
    imul r9d, SIZEOF RAWRFUNCTION
    lea r9, [rdx + r9]
    cmp rax, [r9].RAWRFUNCTION.startAddress
    je @@func_xref_next             ; Already have this function
    inc r8d
    jmp @@func_check_dup

@@func_add_from_xref:
    ; Add new function entry from CALL target
    sub rsp, SIZEOF RAWRFUNCTION
    mov r8, rsp
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRFUNCTION
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi

    mov rax, [r14].RAWRXREF.toAddr
    mov [rsp].RAWRFUNCTION.startAddress, rax
    mov [rsp].RAWRFUNCTION.endAddress, rax ; Unknown end
    mov [rsp].RAWRFUNCTION.instrCount, 0
    mov [rsp].RAWRFUNCTION.hasFramePointer, 0
    mov [rsp].RAWRFUNCTION.isThunk, 0

    lea rcx, [rbx].RAWRCODEX_CTX.functions
    mov rdx, rsp
    call DynArray_Push

    add rsp, SIZEOF RAWRFUNCTION

@@func_xref_next:
    inc edi
    jmp @@func_xref_loop

@@func_done:
    lea rcx, [rbx].RAWRCODEX_CTX.functions
    mov eax, [rcx].DYNARRAY.count

    add rsp, 68h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
RawrCodex_RecoverFunctions ENDP

; =============================================================================
; RawrCodex_LiftToSSA - Lift decoded instructions to Static Single Assignment form
;
; Converts the machine instruction stream (in ctx->instructions) into SSA
; representation using the basic block structure from ctx->basicBlocks.
;
; For each basic block:
;   1. Initialize register version counters
;   2. Walk instructions in the block
;   3. For each instruction, create RAWRSSAINSTR with:
;      - Source operands referencing current SSA versions of source registers
;      - Destination operand creating a NEW SSA version of the dest register
;   4. At block boundaries with multiple predecessors, insert PHI nodes
;
; The SSA form enables:
;   - Dead code elimination (DCE)
;   - Constant propagation
;   - Expression simplification
;   - Decompilation to high-level pseudocode
;
; Input:  RCX = pointer to RAWRCODEX_CTX (must have instructions + basicBlocks populated)
; Output: EAX = number of SSA instructions generated (0 on error)
;
; Requires: RawrCodex_Disassemble + RawrCodex_BuildCFG called first
; =============================================================================
RawrCodex_LiftToSSA PROC
    push rbx
    push rsi
    push rdi
    push r12
    push r13
    push r14
    push r15
    sub rsp, 88h                    ; Shadow + locals

    test rcx, rcx
    jz @@ssa_fail
    mov rbx, rcx                    ; rbx = ctx

    ; Validate prerequisites
    lea rax, [rbx].RAWRCODEX_CTX.instructions
    cmp [rax].DYNARRAY.count, 0
    je @@ssa_fail
    lea rax, [rbx].RAWRCODEX_CTX.basicBlocks
    cmp [rax].DYNARRAY.count, 0
    je @@ssa_fail

    ; Clear previous SSA data
    lea rcx, [rbx].RAWRCODEX_CTX.ssaVars
    call DynArray_Clear
    lea rcx, [rbx].RAWRCODEX_CTX.ssaInstrs
    call DynArray_Clear
    lea rcx, [rbx].RAWRCODEX_CTX.phiNodes
    call DynArray_Clear
    mov [rbx].RAWRCODEX_CTX.ssaNextVarId, 0

    ; Initialize register version table to 0 for all 16 registers
    lea rdi, ssaRegVersions
    xor eax, eax
    mov ecx, 16
    rep stosd
    mov [ssaFlagsVersion], 0

    ; -----------------------------------------------------------------------
    ; Phase 1: Create initial SSA variables for each register (version 0)
    ; These represent the "incoming" state (function parameters / undefined)
    ; -----------------------------------------------------------------------
    xor r12d, r12d                  ; r12 = register index (0..15)
@@ssa_init_regs:
    cmp r12d, 16
    jge @@ssa_init_flags

    ; Build RAWRSSAVAR on stack
    sub rsp, SIZEOF RAWRSSAVAR
    mov r8, rsp

    ; Zero it
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRSSAVAR
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi

    mov eax, [rbx].RAWRCODEX_CTX.ssaNextVarId
    mov [rsp].RAWRSSAVAR.varId, eax
    mov [rsp].RAWRSSAVAR.varClass, SSA_VAR_REGISTER
    mov [rsp].RAWRSSAVAR.regIndex, r12d
    mov [rsp].RAWRSSAVAR.ssaVersion, 0
    mov [rsp].RAWRSSAVAR.bbIndex, 0
    mov [rsp].RAWRSSAVAR.instrIndex, -1     ; Defined at function entry

    lea rcx, [rbx].RAWRCODEX_CTX.ssaVars
    mov rdx, rsp
    call DynArray_Push

    inc [rbx].RAWRCODEX_CTX.ssaNextVarId
    add rsp, SIZEOF RAWRSSAVAR

    inc r12d
    jmp @@ssa_init_regs

@@ssa_init_flags:
    ; Create initial flags variable (version 0)
    sub rsp, SIZEOF RAWRSSAVAR
    mov r8, rsp
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRSSAVAR
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi

    mov eax, [rbx].RAWRCODEX_CTX.ssaNextVarId
    mov [rsp].RAWRSSAVAR.varId, eax
    mov [rsp].RAWRSSAVAR.varClass, SSA_VAR_FLAGS
    mov [rsp].RAWRSSAVAR.regIndex, -1
    mov [rsp].RAWRSSAVAR.ssaVersion, 0

    lea rcx, [rbx].RAWRCODEX_CTX.ssaVars
    mov rdx, rsp
    call DynArray_Push
    inc [rbx].RAWRCODEX_CTX.ssaNextVarId
    add rsp, SIZEOF RAWRSSAVAR

    ; -----------------------------------------------------------------------
    ; Phase 2: Walk each basic block and lift instructions to SSA
    ; -----------------------------------------------------------------------
    lea rax, [rbx].RAWRCODEX_CTX.basicBlocks
    mov r13d, [rax].DYNARRAY.count  ; r13 = total basic blocks
    xor r14d, r14d                  ; r14 = current BB index

@@ssa_bb_loop:
    cmp r14d, r13d
    jge @@ssa_phase3

    ; Get pointer to current basic block
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    mov edx, r14d
    call DynArray_Get
    test rax, rax
    jz @@ssa_bb_next
    mov r15, rax                    ; r15 = ptr to current RAWRBASICBLOCK

    ; Get the address range of this block
    mov rsi, [r15].RAWRBASICBLOCK.startAddress  ; rsi = BB start addr
    mov rdi, [r15].RAWRBASICBLOCK.endAddress    ; rdi = BB end addr

    ; -----------------------------------------------------------------------
    ; Phase 2a: Insert PHI nodes for blocks with multiple predecessors
    ; -----------------------------------------------------------------------
    cmp [r15].RAWRBASICBLOCK.predecessorCount, 2
    jb @@ssa_bb_walk_instrs         ; No PHI needed for 0 or 1 predecessor

    ; For each of the 16 registers, insert a PHI node if this block
    ; has multiple predecessors (simplified: we always insert PHI for
    ; all registers at multi-predecessor blocks; DCE will remove unused ones)
    xor r12d, r12d
@@ssa_phi_reg_loop:
    cmp r12d, 16
    jge @@ssa_bb_walk_instrs

    ; Create a new SSA variable for the PHI result
    sub rsp, SIZEOF RAWRSSAVAR
    mov r8, rsp
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRSSAVAR
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi

    ; Bump the version for this register
    lea rax, ssaRegVersions
    mov ecx, r12d
    inc DWORD PTR [rax + rcx*4]

    mov eax, [rbx].RAWRCODEX_CTX.ssaNextVarId
    mov [rsp].RAWRSSAVAR.varId, eax
    mov [rsp].RAWRSSAVAR.varClass, SSA_VAR_REGISTER
    mov [rsp].RAWRSSAVAR.regIndex, r12d
    lea rcx, ssaRegVersions
    mov edx, r12d
    mov edx, [rcx + rdx*4]
    mov [rsp].RAWRSSAVAR.ssaVersion, edx
    mov [rsp].RAWRSSAVAR.bbIndex, r14d
    mov [rsp].RAWRSSAVAR.instrIndex, -1     ; PHI, not a real instruction

    lea rcx, [rbx].RAWRCODEX_CTX.ssaVars
    mov rdx, rsp
    call DynArray_Push

    inc [rbx].RAWRCODEX_CTX.ssaNextVarId

    ; Free the SSA var space
    add rsp, SIZEOF RAWRSSAVAR

    ; Build RAWRPHINODE on stack
    sub rsp, SIZEOF RAWRPHINODE
    mov r8, rsp
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRPHINODE
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi

    mov [rsp].RAWRPHINODE.bbIndex, r14d
    ; dstVarId = ssaNextVarId - 1 (the variable we just created)
    mov eax, [rbx].RAWRCODEX_CTX.ssaNextVarId
    dec eax
    mov [rsp].RAWRPHINODE.dstVarId, eax
    mov [rsp].RAWRPHINODE.regIndex, r12d

    ; Fill in operand count from predecessor count
    mov eax, [r15].RAWRBASICBLOCK.predecessorCount
    cmp eax, MAX_PHI_OPERANDS
    jbe @@ssa_phi_count_ok
    mov eax, MAX_PHI_OPERANDS
@@ssa_phi_count_ok:
    mov [rsp].RAWRPHINODE.operandCount, eax

    ; For now, operandVarIds are set to -1 (resolved in Phase 3)
    ; operandBBs are filled from predecessor list
    mov ecx, eax                    ; ecx = operand count
    xor edx, edx
@@ssa_phi_fill_preds:
    cmp edx, ecx
    jge @@ssa_phi_push
    ; Store predecessor index placeholder
    mov [rsp + RAWRPHINODE.operandBBs + rdx*4], edx
    mov DWORD PTR [rsp + RAWRPHINODE.operandVarIds + rdx*4], -1
    inc edx
    jmp @@ssa_phi_fill_preds

@@ssa_phi_push:
    lea rcx, [rbx].RAWRCODEX_CTX.phiNodes
    mov rdx, rsp
    call DynArray_Push

    add rsp, SIZEOF RAWRPHINODE

    inc r12d
    jmp @@ssa_phi_reg_loop

    ; -----------------------------------------------------------------------
    ; Phase 2b: Walk instructions in this basic block
    ; For each instruction, map mnemonic -> SSA operation, assign SSA variables
    ; -----------------------------------------------------------------------
@@ssa_bb_walk_instrs:
    ; Scan instructions array for those in range [rsi, rdi]
    lea rax, [rbx].RAWRCODEX_CTX.instructions
    mov ecx, [rax].DYNARRAY.count   ; total instruction count
    mov [rsp + 40h], ecx            ; Save total instr count to stack local
    xor r12d, r12d                  ; r12 = instruction index

@@ssa_instr_loop:
    mov ecx, [rsp + 40h]
    cmp r12d, ecx
    jge @@ssa_bb_next

    ; Get instruction pointer
    lea rcx, [rbx].RAWRCODEX_CTX.instructions
    mov edx, r12d
    call DynArray_Get
    test rax, rax
    jz @@ssa_instr_next

    ; Check if this instruction's address falls within the current BB
    mov rcx, [rax].RAWRINSTRUCTION.address
    cmp rcx, rsi                    ; >= BB start?
    jb @@ssa_instr_next
    cmp rcx, rdi                    ; <= BB end?
    ja @@ssa_instr_next

    ; rax = ptr to RAWRINSTRUCTION within this BB
    ; Now create an SSA instruction for it
    mov [rsp + 48h], rax            ; Save instruction ptr to stack local

    ; Build RAWRSSAINSTR on stack
    sub rsp, SIZEOF RAWRSSAINSTR
    mov r8, rsp
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRSSAINSTR
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi

    ; Restore instruction ptr
    mov rax, [rsp + SIZEOF RAWRSSAINSTR + 48h]

    ; Set common fields
    mov rcx, [rax].RAWRINSTRUCTION.address
    mov [rsp].RAWRSSAINSTR.origAddress, rcx
    mov [rsp].RAWRSSAINSTR.origInstrIdx, r12d
    mov [rsp].RAWRSSAINSTR.bbIndex, r14d
    mov [rsp].RAWRSSAINSTR.dstVarId, -1
    mov [rsp].RAWRSSAINSTR.src1VarId, -1
    mov [rsp].RAWRSSAINSTR.src2VarId, -1
    mov [rsp].RAWRSSAINSTR.flagsVarId, -1
    mov [rsp].RAWRSSAINSTR.isDeadCode, 0

    ; Classify mnemonic -> SSA op
    lea rcx, [rax].RAWRINSTRUCTION.szMnemonic

    ; Check first byte for fast classification
    movzx edx, BYTE PTR [rcx]

    cmp edx, 'a'                    ; add, and, adc
    je @@ssa_class_a
    cmp edx, 's'                    ; sub, shr, shl, sar, sbb
    je @@ssa_class_s
    cmp edx, 'x'                    ; xor
    je @@ssa_class_x
    cmp edx, 'o'                    ; or
    je @@ssa_class_o
    cmp edx, 'm'                    ; mov, mul
    je @@ssa_class_m
    cmp edx, 'l'                    ; lea
    je @@ssa_class_l
    cmp edx, 'c'                    ; cmp, call, cmov
    je @@ssa_class_c
    cmp edx, 't'                    ; test
    je @@ssa_class_t
    cmp edx, 'r'                    ; ret
    je @@ssa_class_r
    cmp edx, 'j'                    ; jmp, jcc
    je @@ssa_class_j
    cmp edx, 'n'                    ; not, neg, nop
    je @@ssa_class_n
    cmp edx, 'p'                    ; push, pop
    je @@ssa_class_p
    cmp edx, 'i'                    ; imul, idiv
    je @@ssa_class_i
    cmp edx, 'd'                    ; div
    je @@ssa_class_d

    ; Default: unknown
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_UNKNOWN
    jmp @@ssa_emit

@@ssa_class_a:
    movzx edx, BYTE PTR [rcx + 1]
    cmp edx, 'd'                    ; add or adc
    je @@ssa_is_add
    cmp edx, 'n'                    ; and
    je @@ssa_is_and
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_UNKNOWN
    jmp @@ssa_emit
@@ssa_is_add:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_ADD
    jmp @@ssa_binary_op
@@ssa_is_and:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_AND
    jmp @@ssa_binary_op

@@ssa_class_s:
    movzx edx, BYTE PTR [rcx + 1]
    cmp edx, 'u'                    ; sub
    je @@ssa_is_sub
    cmp edx, 'h'                    ; shl, shr
    je @@ssa_class_sh
    cmp edx, 'a'                    ; sar
    je @@ssa_is_sar
    cmp edx, 'b'                    ; sbb
    je @@ssa_is_sub                 ; treat sbb as sub for SSA purposes
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_UNKNOWN
    jmp @@ssa_emit
@@ssa_is_sub:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_SUB
    jmp @@ssa_binary_op
@@ssa_class_sh:
    movzx edx, BYTE PTR [rcx + 2]
    cmp edx, 'l'                    ; shl
    je @@ssa_is_shl
    cmp edx, 'r'                    ; shr
    je @@ssa_is_shr
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_UNKNOWN
    jmp @@ssa_emit
@@ssa_is_shl:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_SHL
    jmp @@ssa_binary_op
@@ssa_is_shr:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_SHR
    jmp @@ssa_binary_op
@@ssa_is_sar:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_SAR
    jmp @@ssa_binary_op

@@ssa_class_x:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_XOR
    jmp @@ssa_binary_op

@@ssa_class_o:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_OR
    jmp @@ssa_binary_op

@@ssa_class_m:
    movzx edx, BYTE PTR [rcx + 1]
    cmp edx, 'o'                    ; mov
    je @@ssa_is_mov
    cmp edx, 'u'                    ; mul
    je @@ssa_is_mul
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_UNKNOWN
    jmp @@ssa_emit
@@ssa_is_mov:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_ASSIGN
    jmp @@ssa_assign_op
@@ssa_is_mul:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_MUL
    jmp @@ssa_binary_op

@@ssa_class_l:
    movzx edx, BYTE PTR [rcx + 1]
    cmp edx, 'e'                    ; lea
    je @@ssa_is_lea
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_UNKNOWN
    jmp @@ssa_emit
@@ssa_is_lea:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_LEA
    jmp @@ssa_assign_op

@@ssa_class_c:
    movzx edx, BYTE PTR [rcx + 1]
    cmp edx, 'm'                    ; cmp or cmov
    je @@ssa_class_cm
    cmp edx, 'a'                    ; call
    je @@ssa_is_call
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_UNKNOWN
    jmp @@ssa_emit
@@ssa_class_cm:
    movzx edx, BYTE PTR [rcx + 2]
    cmp edx, 'p'                    ; cmp
    je @@ssa_is_cmp
    cmp edx, 'o'                    ; cmov
    je @@ssa_is_cmov
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_UNKNOWN
    jmp @@ssa_emit
@@ssa_is_cmp:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_CMP
    ; CMP produces flags, consumes two source operands
    ; Create new flags SSA variable
    mov eax, [rbx].RAWRCODEX_CTX.ssaNextVarId
    mov [rsp].RAWRSSAINSTR.flagsVarId, eax
    inc [rbx].RAWRCODEX_CTX.ssaNextVarId
    inc [ssaFlagsVersion]
    jmp @@ssa_emit
@@ssa_is_cmov:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_ASSIGN  ; CMOVcc is conditional assign
    jmp @@ssa_assign_op
@@ssa_is_call:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_CALL
    ; Restore instruction ptr to get branch target
    mov rax, [rsp + SIZEOF RAWRSSAINSTR + 48h]
    mov rcx, [rax].RAWRINSTRUCTION.branchTarget
    mov [rsp].RAWRSSAINSTR.callTarget, rcx
    ; Call clobbers rax — create new SSA var for rax
    mov eax, [rbx].RAWRCODEX_CTX.ssaNextVarId
    mov [rsp].RAWRSSAINSTR.dstVarId, eax
    inc [rbx].RAWRCODEX_CTX.ssaNextVarId
    ; Bump rax version
    lea rcx, ssaRegVersions
    inc DWORD PTR [rcx]             ; regIndex 0 = rax
    jmp @@ssa_emit

@@ssa_class_t:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_TEST
    mov eax, [rbx].RAWRCODEX_CTX.ssaNextVarId
    mov [rsp].RAWRSSAINSTR.flagsVarId, eax
    inc [rbx].RAWRCODEX_CTX.ssaNextVarId
    inc [ssaFlagsVersion]
    jmp @@ssa_emit

@@ssa_class_r:
    movzx edx, BYTE PTR [rcx + 1]
    cmp edx, 'e'                    ; ret
    je @@ssa_is_ret
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_UNKNOWN
    jmp @@ssa_emit
@@ssa_is_ret:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_RET
    ; ret consumes rax (return value)
    lea rcx, ssaRegVersions
    mov eax, [rcx]                  ; current rax version
    mov [rsp].RAWRSSAINSTR.src1VarId, eax
    jmp @@ssa_emit

@@ssa_class_j:
    movzx edx, BYTE PTR [rcx + 1]
    cmp edx, 'm'                    ; jmp
    je @@ssa_is_jmp
    ; Otherwise it's a Jcc (conditional branch)
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_BRANCH
    ; Branch consumes flags
    mov eax, [ssaFlagsVersion]
    mov [rsp].RAWRSSAINSTR.flagsVarId, eax
    ; Set branch target
    mov rax, [rsp + SIZEOF RAWRSSAINSTR + 48h]
    mov rcx, [rax].RAWRINSTRUCTION.branchTarget
    mov [rsp].RAWRSSAINSTR.branchTarget, rcx
    jmp @@ssa_emit
@@ssa_is_jmp:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_JMP
    mov rax, [rsp + SIZEOF RAWRSSAINSTR + 48h]
    mov rcx, [rax].RAWRINSTRUCTION.branchTarget
    mov [rsp].RAWRSSAINSTR.branchTarget, rcx
    jmp @@ssa_emit

@@ssa_class_n:
    movzx edx, BYTE PTR [rcx + 1]
    cmp edx, 'o'                    ; not or nop
    je @@ssa_class_no
    cmp edx, 'e'                    ; neg
    je @@ssa_is_neg
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_UNKNOWN
    jmp @@ssa_emit
@@ssa_class_no:
    movzx edx, BYTE PTR [rcx + 2]
    cmp edx, 't'                    ; not
    je @@ssa_is_not
    cmp edx, 'p'                    ; nop
    je @@ssa_is_nop
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_UNKNOWN
    jmp @@ssa_emit
@@ssa_is_not:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_NOT
    jmp @@ssa_unary_op
@@ssa_is_neg:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_NEG
    jmp @@ssa_unary_op
@@ssa_is_nop:
    ; NOP — skip, don't emit SSA instruction
    add rsp, SIZEOF RAWRSSAINSTR
    jmp @@ssa_instr_next

@@ssa_class_p:
    ; push/pop — model as STORE/LOAD to stack
    movzx edx, BYTE PTR [rcx + 1]
    cmp edx, 'u'                    ; push
    je @@ssa_is_push
    cmp edx, 'o'                    ; pop
    je @@ssa_is_pop
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_UNKNOWN
    jmp @@ssa_emit
@@ssa_is_push:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_STORE
    jmp @@ssa_emit
@@ssa_is_pop:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_LOAD
    jmp @@ssa_emit

@@ssa_class_i:
    movzx edx, BYTE PTR [rcx + 1]
    cmp edx, 'm'                    ; imul
    je @@ssa_is_imul
    cmp edx, 'd'                    ; idiv
    je @@ssa_is_idiv
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_UNKNOWN
    jmp @@ssa_emit
@@ssa_is_imul:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_MUL
    jmp @@ssa_binary_op
@@ssa_is_idiv:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_DIV
    jmp @@ssa_binary_op

@@ssa_class_d:
    mov [rsp].RAWRSSAINSTR.ssaOp, SSA_OP_DIV
    jmp @@ssa_binary_op

    ; -------------------------------------------------------------------
    ; SSA variable assignment helpers
    ; -------------------------------------------------------------------

@@ssa_binary_op:
    ; Binary op: dst = src1 OP src2
    ; Create new SSA var for destination
    ; In a full implementation, operand parsing determines actual dst/src registers
    ; Here we use register version counters as placeholder references
    mov eax, [rbx].RAWRCODEX_CTX.ssaNextVarId
    mov [rsp].RAWRSSAINSTR.dstVarId, eax
    inc [rbx].RAWRCODEX_CTX.ssaNextVarId
    ; src1 = current rax version counter (placeholder)
    lea rcx, ssaRegVersions
    mov eax, [rcx]                  ; rax version as placeholder src1
    mov [rsp].RAWRSSAINSTR.src1VarId, eax
    mov eax, [rcx + 4]             ; rcx version as placeholder src2
    mov [rsp].RAWRSSAINSTR.src2VarId, eax
    jmp @@ssa_emit

@@ssa_assign_op:
    ; Assignment: dst = src1
    mov eax, [rbx].RAWRCODEX_CTX.ssaNextVarId
    mov [rsp].RAWRSSAINSTR.dstVarId, eax
    inc [rbx].RAWRCODEX_CTX.ssaNextVarId
    lea rcx, ssaRegVersions
    mov eax, [rcx]                  ; source placeholder
    mov [rsp].RAWRSSAINSTR.src1VarId, eax
    jmp @@ssa_emit

@@ssa_unary_op:
    ; Unary: dst = OP src1
    mov eax, [rbx].RAWRCODEX_CTX.ssaNextVarId
    mov [rsp].RAWRSSAINSTR.dstVarId, eax
    inc [rbx].RAWRCODEX_CTX.ssaNextVarId
    lea rcx, ssaRegVersions
    mov eax, [rcx]
    mov [rsp].RAWRSSAINSTR.src1VarId, eax
    jmp @@ssa_emit

@@ssa_emit:
    ; Push the SSA instruction
    lea rcx, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov rdx, rsp
    call DynArray_Push

    add rsp, SIZEOF RAWRSSAINSTR

@@ssa_instr_next:
    inc r12d
    jmp @@ssa_instr_loop

@@ssa_bb_next:
    inc r14d
    jmp @@ssa_bb_loop

    ; -----------------------------------------------------------------------
    ; Phase 3: Resolve PHI node operand variable IDs
    ; For each PHI node, find the last definition of the register in each
    ; predecessor block. This requires scanning ssaInstrs in reverse within
    ; each predecessor block.
    ; -----------------------------------------------------------------------
@@ssa_phase3:
    lea rax, [rbx].RAWRCODEX_CTX.phiNodes
    mov r13d, [rax].DYNARRAY.count
    xor r14d, r14d                  ; phi index

@@ssa_phi_resolve_loop:
    cmp r14d, r13d
    jge @@ssa_done

    lea rcx, [rbx].RAWRCODEX_CTX.phiNodes
    mov edx, r14d
    call DynArray_Get
    test rax, rax
    jz @@ssa_phi_resolve_next
    mov r15, rax                    ; r15 = ptr to RAWRPHINODE

    ; For each operand in this PHI node
    mov ecx, [r15].RAWRPHINODE.operandCount
    xor r12d, r12d

@@ssa_phi_operand_loop:
    cmp r12d, ecx
    jge @@ssa_phi_resolve_next

    ; Find the last SSA instruction in predecessor block r12 that defines
    ; a variable with regIndex == this PHI's regIndex
    lea rax, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov edi, [rax].DYNARRAY.count
    dec edi                         ; Start from last SSA instr

@@ssa_phi_scan:
    cmp edi, 0
    jl @@ssa_phi_operand_default    ; Not found — use -1

    push rcx
    push r12
    lea rcx, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov edx, edi
    call DynArray_Get
    pop r12
    pop rcx
    test rax, rax
    jz @@ssa_phi_operand_default

    ; Check if this SSA instr is in the predecessor BB
    mov edx, [r15 + RAWRPHINODE.operandBBs + r12*4]
    cmp [rax].RAWRSSAINSTR.bbIndex, edx
    jne @@ssa_phi_scan_prev

    ; Check if it defines a destination (dstVarId != -1)
    cmp [rax].RAWRSSAINSTR.dstVarId, -1
    je @@ssa_phi_scan_prev

    ; Found a definition in the predecessor block — use its dstVarId
    mov edx, [rax].RAWRSSAINSTR.dstVarId
    mov [r15 + RAWRPHINODE.operandVarIds + r12*4], edx
    jmp @@ssa_phi_operand_next

@@ssa_phi_scan_prev:
    dec edi
    jmp @@ssa_phi_scan

@@ssa_phi_operand_default:
    ; No definition found — use initial version (varId = regIndex for version 0)
    mov edx, [r15].RAWRPHINODE.regIndex
    mov [r15 + RAWRPHINODE.operandVarIds + r12*4], edx

@@ssa_phi_operand_next:
    inc r12d
    jmp @@ssa_phi_operand_loop

@@ssa_phi_resolve_next:
    inc r14d
    jmp @@ssa_phi_resolve_loop

@@ssa_done:
    mov [rbx].RAWRCODEX_CTX.ssaLifted, 1

    ; Return total SSA instruction count
    lea rcx, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov eax, [rcx].DYNARRAY.count

    add rsp, 88h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret

@@ssa_fail:
    xor eax, eax
    add rsp, 88h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
RawrCodex_LiftToSSA ENDP

; =============================================================================
; RawrCodex_RecursiveDisassemble - CFG-guided recursive descent disassembler
;
; Unlike linear sweep (RawrCodex_Disassemble), this follows control flow edges
; to only disassemble reachable code. This avoids disassembling inline data,
; jump tables, alignment padding, and other non-code regions.
;
; Algorithm:
;   1. Start with entry address on the worklist
;   2. Pop an address from the worklist
;   3. If already visited, skip
;   4. Mark as visited
;   5. Decode one instruction at that address
;   6. If it's a branch/call, push target onto worklist
;   7. If it's not a terminator, push fall-through address
;   8. Repeat until worklist is empty
;
; The visited bitmap uses address offsets relative to the image base.
; Each bit represents one byte offset.
;
; Input:  RCX = pointer to RAWRCODEX_CTX
;         RDX = entry point address (VA)
; Output: EAX = number of instructions decoded (0 on error)
;
; Results are appended to ctx->instructions (cleared first)
; =============================================================================
RawrCodex_RecursiveDisassemble PROC
    push rbx
    push rsi
    push rdi
    push r12
    push r13
    push r14
    push r15
    sub rsp, 88h

    test rcx, rcx
    jz @@recdesc_fail
    mov rbx, rcx                    ; rbx = ctx
    mov r12, rdx                    ; r12 = entry point VA

    ; Validate binary is loaded
    cmp [rbx].RAWRCODEX_CTX.isLoaded, 0
    je @@recdesc_fail

    ; Clear previous instructions (recursive disasm replaces linear sweep)
    lea rcx, [rbx].RAWRCODEX_CTX.instructions
    call DynArray_Clear

    ; -----------------------------------------------------------------------
    ; Initialize visited bitmap — zero out RECDESC_VISITED_BITMAP_SIZE bytes
    ; -----------------------------------------------------------------------
    lea rdi, recDescVisited
    xor eax, eax
    mov ecx, RECDESC_VISITED_BITMAP_SIZE
    rep stosb

    ; -----------------------------------------------------------------------
    ; Initialize worklist stack — push entry point
    ; -----------------------------------------------------------------------
    mov [recDescStackTop], 0
    lea rdi, recDescStack
    mov [rdi], r12                  ; Push entry point
    mov [recDescStackTop], 1

    ; Image base for VA-to-RVA conversion
    mov r13, [rbx].RAWRCODEX_CTX.peImageBase   ; r13 = image base (PE)

    ; -----------------------------------------------------------------------
    ; Main worklist loop
    ; -----------------------------------------------------------------------
@@recdesc_loop:
    ; Check worklist not empty
    cmp [recDescStackTop], 0
    je @@recdesc_complete

    ; Pop address from worklist
    dec [recDescStackTop]
    mov eax, [recDescStackTop]
    lea rdi, recDescStack
    mov r14, [rdi + rax*8]          ; r14 = current VA to disassemble

    ; Compute RVA from image base for visited bitmap
    mov rax, r14
    sub rax, r13                    ; rax = RVA (VA - imageBase)

    ; Check bounds — bitmap can only track RECDESC_VISITED_BITMAP_SIZE * 8 bytes
    mov rcx, rax
    shr rcx, 3                      ; byte index = RVA / 8
    cmp rcx, RECDESC_VISITED_BITMAP_SIZE
    jae @@recdesc_loop              ; Out of bitmap range — skip

    ; Check if already visited
    lea rdi, recDescVisited
    mov rdx, rax
    and edx, 7                      ; bit index = RVA & 7
    bt DWORD PTR [rdi + rcx], edx
    jc @@recdesc_loop               ; Already visited — skip

    ; Mark as visited
    bts DWORD PTR [rdi + rcx], edx

    ; -----------------------------------------------------------------------
    ; Convert VA to file offset using RvaToFileOffset
    ; -----------------------------------------------------------------------
    mov rcx, rbx
    mov rax, r14
    sub rax, r13                    ; RVA = VA - imageBase
    mov edx, eax                    ; edx = RVA (32-bit)
    call RvaToFileOffset            ; returns file offset in eax, or -1
    cmp eax, -1
    je @@recdesc_loop               ; Can't map this VA — skip

    mov r15d, eax                   ; r15d = file offset

    ; Check bounds
    mov rcx, [rbx].RAWRCODEX_CTX.fileSize
    movsxd rax, r15d
    cmp rax, rcx
    jae @@recdesc_loop

    ; Get pointer to raw bytes: pFileBase + fileOffset
    mov rsi, [rbx].RAWRCODEX_CTX.pFileBase
    add rsi, rax                    ; rsi = ptr to instruction bytes

    ; Remaining bytes in file from this point
    mov eax, DWORD PTR [rbx].RAWRCODEX_CTX.fileSize  ; Low 32 bits of fileSize
    sub eax, r15d
    mov ecx, eax                    ; ecx = bytes remaining
    cmp ecx, MAX_INSTR_LEN
    jbe @@recdesc_use_remaining
    mov ecx, MAX_INSTR_LEN
@@recdesc_use_remaining:
    mov [rsp + 40h], ecx            ; Save max bytes available

    ; -----------------------------------------------------------------------
    ; Decode the instruction using full decoder
    ; RawrCodex_DecodeInstruction(ctx=RCX, pBytes=RDX, maxLen=R8D, VA=R9)
    ; -----------------------------------------------------------------------
    mov rcx, rbx
    mov rdx, rsi
    mov r8d, [rsp + 40h]
    mov r9, r14
    call RawrCodex_DecodeInstruction

    ; DecodeInstruction pushes result to ctx->instructions internally?
    ; No — it builds a local RAWRINSTRUCTION. We need to check the returned length.
    ; Actually, DecodeInstruction returns instrLen in eax (or 0 on failure)
    test eax, eax
    jz @@recdesc_loop               ; Decode failed — skip

    mov [rsp + 48h], eax            ; Save instruction length

    ; The decoded instruction is already in ctx->instructions
    ; (DecodeInstruction was called by Disassemble which pushes)
    ; Actually, DecodeInstruction is a standalone decoder. We need to
    ; build and push the instruction ourselves using the decode result.

    ; Build RAWRINSTRUCTION on stack for this decoded instruction
    sub rsp, SIZEOF RAWRINSTRUCTION
    mov r8, rsp

    ; Zero it
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRINSTRUCTION
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi

    mov [rsp].RAWRINSTRUCTION.address, r14
    mov eax, [rsp + SIZEOF RAWRINSTRUCTION + 48h]
    mov [rsp].RAWRINSTRUCTION.instrLen, eax

    ; Copy raw bytes (up to 16)
    push rcx
    push rdi
    mov ecx, eax
    cmp ecx, 16
    jbe @@recdesc_copy_ok
    mov ecx, 16
@@recdesc_copy_ok:
    lea rdi, [rsp + 16].RAWRINSTRUCTION.rawBytes
    push rsi
    rep movsb
    pop rsi
    pop rdi
    pop rcx

    ; Now classify the first opcode byte for control flow
    movzx eax, BYTE PTR [rsi]
    mov [rsp + SIZEOF RAWRINSTRUCTION + 50h], eax  ; Save opcode

    ; Handle REX prefix
    cmp al, 40h
    jb @@recdesc_decode_opcode
    cmp al, 4Fh
    ja @@recdesc_decode_opcode
    movzx eax, BYTE PTR [rsi + 1]  ; Real opcode after REX

@@recdesc_decode_opcode:
    ; RET
    cmp al, 0C3h
    je @@recdesc_emit_ret
    cmp al, 0CBh
    je @@recdesc_emit_ret

    ; CALL rel32
    cmp al, 0E8h
    je @@recdesc_emit_call

    ; JMP rel32
    cmp al, 0E9h
    je @@recdesc_emit_jmp32

    ; JMP rel8
    cmp al, 0EBh
    je @@recdesc_emit_jmp8

    ; Jcc rel8 (70-7F)
    cmp al, 70h
    jb @@recdesc_check_0f_opcode
    cmp al, 7Fh
    ja @@recdesc_check_0f_opcode
    jmp @@recdesc_emit_jcc8

@@recdesc_check_0f_opcode:
    cmp al, 0Fh
    jne @@recdesc_emit_linear

    ; Two-byte opcode — check for 0F 80-8F (Jcc rel32)
    movzx eax, BYTE PTR [rsi + 1]
    cmp al, 80h
    jb @@recdesc_emit_linear
    cmp al, 8Fh
    ja @@recdesc_emit_linear
    jmp @@recdesc_emit_jcc32

    ; --- Emit: RET (no successors) ---
@@recdesc_emit_ret:
    mov [rsp].RAWRINSTRUCTION.isReturn, 1
    lea rdi, [rsp].RAWRINSTRUCTION.szMnemonic
    mov BYTE PTR [rdi], 'r'
    mov BYTE PTR [rdi+1], 'e'
    mov BYTE PTR [rdi+2], 't'
    mov BYTE PTR [rdi+3], 0

    lea rcx, [rbx].RAWRCODEX_CTX.instructions
    mov rdx, rsp
    call DynArray_Push
    add rsp, SIZEOF RAWRINSTRUCTION
    jmp @@recdesc_loop

    ; --- Emit: CALL rel32 (push both target + fall-through) ---
@@recdesc_emit_call:
    mov [rsp].RAWRINSTRUCTION.isCall, 1
    lea rdi, [rsp].RAWRINSTRUCTION.szMnemonic
    mov BYTE PTR [rdi], 'c'
    mov BYTE PTR [rdi+1], 'a'
    mov BYTE PTR [rdi+2], 'l'
    mov BYTE PTR [rdi+3], 'l'
    mov BYTE PTR [rdi+4], 0

    ; Compute call target: VA + instrLen + disp32
    mov eax, [rsp].RAWRINSTRUCTION.instrLen
    movsxd r8, eax
    movsxd rax, DWORD PTR [rsi + r8 - 4]
    add rax, r14
    add rax, r8
    mov [rsp].RAWRINSTRUCTION.branchTarget, rax

    ; Push call target onto worklist
    mov ecx, [recDescStackTop]
    cmp ecx, MAX_RECURSIVE_DEPTH
    jge @@recdesc_call_push_ft
    lea rdi, recDescStack
    mov [rdi + rcx*8], rax
    inc [recDescStackTop]

@@recdesc_call_push_ft:
    ; Push fall-through
    mov eax, [rsp].RAWRINSTRUCTION.instrLen
    movsxd rax, eax
    add rax, r14
    mov ecx, [recDescStackTop]
    cmp ecx, MAX_RECURSIVE_DEPTH
    jge @@recdesc_call_push_done
    lea rdi, recDescStack
    mov [rdi + rcx*8], rax
    inc [recDescStackTop]

@@recdesc_call_push_done:
    lea rcx, [rbx].RAWRCODEX_CTX.instructions
    mov rdx, rsp
    call DynArray_Push
    add rsp, SIZEOF RAWRINSTRUCTION
    jmp @@recdesc_loop

    ; --- Emit: JMP rel32 (target only, no fall-through) ---
@@recdesc_emit_jmp32:
    mov [rsp].RAWRINSTRUCTION.isJump, 1
    lea rdi, [rsp].RAWRINSTRUCTION.szMnemonic
    mov BYTE PTR [rdi], 'j'
    mov BYTE PTR [rdi+1], 'm'
    mov BYTE PTR [rdi+2], 'p'
    mov BYTE PTR [rdi+3], 0

    mov eax, [rsp].RAWRINSTRUCTION.instrLen
    movsxd r8, eax
    movsxd rax, DWORD PTR [rsi + r8 - 4]
    add rax, r14
    add rax, r8
    mov [rsp].RAWRINSTRUCTION.branchTarget, rax

    mov ecx, [recDescStackTop]
    cmp ecx, MAX_RECURSIVE_DEPTH
    jge @@recdesc_jmp32_done
    lea rdi, recDescStack
    mov [rdi + rcx*8], rax
    inc [recDescStackTop]

@@recdesc_jmp32_done:
    lea rcx, [rbx].RAWRCODEX_CTX.instructions
    mov rdx, rsp
    call DynArray_Push
    add rsp, SIZEOF RAWRINSTRUCTION
    jmp @@recdesc_loop

    ; --- Emit: JMP rel8 (target only) ---
@@recdesc_emit_jmp8:
    mov [rsp].RAWRINSTRUCTION.isJump, 1
    lea rdi, [rsp].RAWRINSTRUCTION.szMnemonic
    mov BYTE PTR [rdi], 'j'
    mov BYTE PTR [rdi+1], 'm'
    mov BYTE PTR [rdi+2], 'p'
    mov BYTE PTR [rdi+3], 0

    mov eax, [rsp].RAWRINSTRUCTION.instrLen
    movsxd r8, eax
    movsx eax, BYTE PTR [rsi + r8 - 1]
    movsxd rax, eax
    add rax, r14
    add rax, r8
    mov [rsp].RAWRINSTRUCTION.branchTarget, rax

    mov ecx, [recDescStackTop]
    cmp ecx, MAX_RECURSIVE_DEPTH
    jge @@recdesc_jmp8_done
    lea rdi, recDescStack
    mov [rdi + rcx*8], rax
    inc [recDescStackTop]

@@recdesc_jmp8_done:
    lea rcx, [rbx].RAWRCODEX_CTX.instructions
    mov rdx, rsp
    call DynArray_Push
    add rsp, SIZEOF RAWRINSTRUCTION
    jmp @@recdesc_loop

    ; --- Emit: Jcc rel8 (push both target + fall-through) ---
@@recdesc_emit_jcc8:
    mov [rsp].RAWRINSTRUCTION.isJump, 1
    mov [rsp].RAWRINSTRUCTION.isBranch, 1
    lea rdi, [rsp].RAWRINSTRUCTION.szMnemonic
    mov BYTE PTR [rdi], 'j'
    mov BYTE PTR [rdi+1], 'c'
    mov BYTE PTR [rdi+2], 'c'
    mov BYTE PTR [rdi+3], 0

    mov eax, [rsp].RAWRINSTRUCTION.instrLen
    movsxd r8, eax
    movsx eax, BYTE PTR [rsi + r8 - 1]
    movsxd rax, eax
    add rax, r14
    add rax, r8
    mov [rsp].RAWRINSTRUCTION.branchTarget, rax

    ; Push branch target
    mov ecx, [recDescStackTop]
    cmp ecx, MAX_RECURSIVE_DEPTH
    jge @@recdesc_jcc8_ft
    lea rdi, recDescStack
    mov [rdi + rcx*8], rax
    inc [recDescStackTop]

@@recdesc_jcc8_ft:
    ; Push fall-through
    mov eax, [rsp].RAWRINSTRUCTION.instrLen
    movsxd rax, eax
    add rax, r14
    mov ecx, [recDescStackTop]
    cmp ecx, MAX_RECURSIVE_DEPTH
    jge @@recdesc_jcc8_done
    lea rdi, recDescStack
    mov [rdi + rcx*8], rax
    inc [recDescStackTop]

@@recdesc_jcc8_done:
    lea rcx, [rbx].RAWRCODEX_CTX.instructions
    mov rdx, rsp
    call DynArray_Push
    add rsp, SIZEOF RAWRINSTRUCTION
    jmp @@recdesc_loop

    ; --- Emit: Jcc rel32 (0F 80-8F, push both target + fall-through) ---
@@recdesc_emit_jcc32:
    mov [rsp].RAWRINSTRUCTION.isJump, 1
    mov [rsp].RAWRINSTRUCTION.isBranch, 1
    lea rdi, [rsp].RAWRINSTRUCTION.szMnemonic
    mov BYTE PTR [rdi], 'j'
    mov BYTE PTR [rdi+1], 'c'
    mov BYTE PTR [rdi+2], 'c'
    mov BYTE PTR [rdi+3], 0

    mov eax, [rsp].RAWRINSTRUCTION.instrLen
    movsxd r8, eax
    movsxd rax, DWORD PTR [rsi + r8 - 4]
    add rax, r14
    add rax, r8
    mov [rsp].RAWRINSTRUCTION.branchTarget, rax

    ; Push branch target
    mov ecx, [recDescStackTop]
    cmp ecx, MAX_RECURSIVE_DEPTH
    jge @@recdesc_jcc32_ft
    lea rdi, recDescStack
    mov [rdi + rcx*8], rax
    inc [recDescStackTop]

@@recdesc_jcc32_ft:
    ; Push fall-through
    mov eax, [rsp].RAWRINSTRUCTION.instrLen
    movsxd rax, eax
    add rax, r14
    mov ecx, [recDescStackTop]
    cmp ecx, MAX_RECURSIVE_DEPTH
    jge @@recdesc_jcc32_done
    lea rdi, recDescStack
    mov [rdi + rcx*8], rax
    inc [recDescStackTop]

@@recdesc_jcc32_done:
    lea rcx, [rbx].RAWRCODEX_CTX.instructions
    mov rdx, rsp
    call DynArray_Push
    add rsp, SIZEOF RAWRINSTRUCTION
    jmp @@recdesc_loop

    ; --- Emit: Linear (non-branching) instruction ---
@@recdesc_emit_linear:
    lea rdi, [rsp].RAWRINSTRUCTION.szMnemonic
    mov BYTE PTR [rdi], 'i'
    mov BYTE PTR [rdi+1], 'n'
    mov BYTE PTR [rdi+2], 's'
    mov BYTE PTR [rdi+3], 0

    ; Push fall-through only
    mov eax, [rsp].RAWRINSTRUCTION.instrLen
    movsxd rax, eax
    add rax, r14
    mov ecx, [recDescStackTop]
    cmp ecx, MAX_RECURSIVE_DEPTH
    jge @@recdesc_linear_done
    lea rdi, recDescStack
    mov [rdi + rcx*8], rax
    inc [recDescStackTop]

@@recdesc_linear_done:
    lea rcx, [rbx].RAWRCODEX_CTX.instructions
    lea rdi, [rsp].RAWRINSTRUCTION.szMnemonic  ; Restore rdi clobbered above
    mov rdx, rsp
    call DynArray_Push
    add rsp, SIZEOF RAWRINSTRUCTION
    jmp @@recdesc_loop

@@recdesc_complete:
    ; Return number of instructions decoded
    lea rcx, [rbx].RAWRCODEX_CTX.instructions
    mov eax, [rcx].DYNARRAY.count

    add rsp, 88h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret

@@recdesc_fail:
    xor eax, eax
    add rsp, 88h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
RawrCodex_RecursiveDisassemble ENDP

; =============================================================================
; RawrCodex_RecoverTypes - Type recovery via SSA data flow analysis
;
; Analyzes SSA variables to infer types:
;   1. Width inference: operand size from instruction encoding (movzx=unsigned, movsxd=signed)
;   2. Pointer detection: values used in LOAD/STORE are pointers
;   3. Array detection: LEA with scale factor → array_ptr with stride
;   4. Struct detection: multiple different offsets from same base → struct_ptr
;   5. Function pointer: CALL through register/memory → code_ptr
;   6. API return types: known Win32 functions (GetProcessHeap→ptr, GetLastError→uint32)
;   7. Boolean: TEST+Jcc pattern on 1-bit results → bool
;
; Input:  RCX = pointer to RAWRCODEX_CTX (must have SSA lifted)
; Output: EAX = number of types recovered (0 on error)
;
; Requires: RawrCodex_LiftToSSA called first (ssaLifted == 1)
; =============================================================================
RawrCodex_RecoverTypes PROC
    push rbx
    push rsi
    push rdi
    push r12
    push r13
    push r14
    push r15
    sub rsp, 0A8h                   ; Shadow + locals

    test rcx, rcx
    jz @@type_fail
    mov rbx, rcx                    ; rbx = ctx

    ; Validate SSA has been lifted
    cmp [rbx].RAWRCODEX_CTX.ssaLifted, 1
    jne @@type_fail

    ; Clear previous type data
    lea rcx, [rbx].RAWRCODEX_CTX.typeInfos
    call DynArray_Clear
    lea rcx, [rbx].RAWRCODEX_CTX.structFields
    call DynArray_Clear
    mov [rbx].RAWRCODEX_CTX.typeNextId, 0

    ; Zero out scratch arrays
    lea rdi, typeVarWidths
    xor eax, eax
    mov ecx, MAX_RECOVERED_TYPES
    rep stosd
    lea rdi, typeVarClasses
    xor eax, eax
    mov ecx, MAX_RECOVERED_TYPES
    rep stosd
    lea rdi, typeConfidence
    xor eax, eax
    mov ecx, MAX_RECOVERED_TYPES
    rep stosd

    ; -----------------------------------------------------------------------
    ; Pass 1: Width inference from SSA instruction operand sizes
    ; Walk SSA instructions, infer width from operation type
    ; -----------------------------------------------------------------------
    lea rax, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov r12d, [rax].DYNARRAY.count  ; r12 = total SSA instructions
    test r12d, r12d
    jz @@type_pass2

    xor r13d, r13d                  ; r13 = SSA instruction index
@@type_p1_loop:
    cmp r13d, r12d
    jge @@type_pass2

    ; Get SSA instruction
    lea rcx, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov edx, r13d
    call DynArray_Get
    test rax, rax
    jz @@type_p1_next
    mov rsi, rax                    ; rsi = ptr to RAWRSSAINSTR

    ; Get the SSA op type
    mov ecx, [rsi].RAWRSSAINSTR.ssaOp
    mov r14d, [rsi].RAWRSSAINSTR.dstVarId

    ; Skip if no destination or varId out of range
    cmp r14d, -1
    je @@type_p1_next
    cmp r14d, MAX_RECOVERED_TYPES
    jge @@type_p1_next

    ; Classify by operation type
    cmp ecx, SSA_OP_LOAD
    je @@type_p1_load
    cmp ecx, SSA_OP_STORE
    je @@type_p1_store
    cmp ecx, SSA_OP_CALL
    je @@type_p1_call
    cmp ecx, SSA_OP_LEA
    je @@type_p1_lea
    cmp ecx, SSA_OP_CMP
    je @@type_p1_cmp
    cmp ecx, SSA_OP_TEST
    je @@type_p1_test
    cmp ecx, SSA_OP_ADD
    je @@type_p1_arith
    cmp ecx, SSA_OP_SUB
    je @@type_p1_arith
    cmp ecx, SSA_OP_MUL
    je @@type_p1_arith
    cmp ecx, SSA_OP_AND
    je @@type_p1_bitwise
    cmp ecx, SSA_OP_OR
    je @@type_p1_bitwise
    cmp ecx, SSA_OP_XOR
    je @@type_p1_bitwise
    cmp ecx, SSA_OP_SHL
    je @@type_p1_shift
    cmp ecx, SSA_OP_SHR
    je @@type_p1_shift
    cmp ecx, SSA_OP_SAR
    je @@type_p1_shift_signed
    cmp ecx, SSA_OP_ASSIGN
    je @@type_p1_assign
    jmp @@type_p1_default

@@type_p1_load:
    ; Destination of a LOAD is a data value, source is a pointer
    lea rdi, typeVarClasses
    mov DWORD PTR [rdi + r14*4], TYPE_INT64     ; Default loaded value: int64
    lea rdi, typeVarWidths
    mov DWORD PTR [rdi + r14*4], TYPE_WIDTH_64
    lea rdi, typeConfidence
    mov DWORD PTR [rdi + r14*4], CONFIDENCE_LOW

    ; Mark source (src1) as data_ptr
    mov eax, [rsi].RAWRSSAINSTR.src1VarId
    cmp eax, -1
    je @@type_p1_next
    cmp eax, MAX_RECOVERED_TYPES
    jge @@type_p1_next
    lea rdi, typeVarClasses
    mov DWORD PTR [rdi + rax*4], TYPE_DATA_PTR
    lea rdi, typeConfidence
    mov DWORD PTR [rdi + rax*4], CONFIDENCE_MEDIUM
    jmp @@type_p1_next

@@type_p1_store:
    ; Source of a STORE determines value type; dst is a pointer
    mov eax, [rsi].RAWRSSAINSTR.dstVarId
    cmp eax, -1
    je @@type_p1_next
    cmp eax, MAX_RECOVERED_TYPES
    jge @@type_p1_next
    lea rdi, typeVarClasses
    mov DWORD PTR [rdi + rax*4], TYPE_DATA_PTR
    lea rdi, typeConfidence
    mov DWORD PTR [rdi + rax*4], CONFIDENCE_MEDIUM
    jmp @@type_p1_next

@@type_p1_call:
    ; Return value of CALL is typically int64 or pointer
    lea rdi, typeVarClasses
    mov DWORD PTR [rdi + r14*4], TYPE_INT64
    lea rdi, typeVarWidths
    mov DWORD PTR [rdi + r14*4], TYPE_WIDTH_64
    lea rdi, typeConfidence
    mov DWORD PTR [rdi + r14*4], CONFIDENCE_LOW
    ; Check if call target is a known API (heap/alloc → pointer)
    mov rax, [rsi].RAWRSSAINSTR.callTarget
    test rax, rax
    jz @@type_p1_next
    ; Heuristic: if call target is non-null, result may be a pointer
    ; (full API matching would require symbol resolution)
    lea rdi, typeVarClasses
    mov DWORD PTR [rdi + r14*4], TYPE_POINTER
    lea rdi, typeConfidence
    mov DWORD PTR [rdi + r14*4], CONFIDENCE_MEDIUM
    jmp @@type_p1_next

@@type_p1_lea:
    ; LEA produces a pointer/address (never dereferences)
    lea rdi, typeVarClasses
    mov DWORD PTR [rdi + r14*4], TYPE_POINTER
    lea rdi, typeVarWidths
    mov DWORD PTR [rdi + r14*4], TYPE_WIDTH_64
    lea rdi, typeConfidence
    mov DWORD PTR [rdi + r14*4], CONFIDENCE_HIGH

    ; If LEA has a scale factor in src2, it's likely an array access
    ; Check src2 for non-zero (would indicate scaled index)
    mov eax, [rsi].RAWRSSAINSTR.src2VarId
    cmp eax, -1
    je @@type_p1_next
    ; Has index register → array pointer
    lea rdi, typeVarClasses
    mov DWORD PTR [rdi + r14*4], TYPE_ARRAY_PTR
    jmp @@type_p1_next

@@type_p1_cmp:
@@type_p1_test:
    ; CMP/TEST produces flags; flags variable is a pseudo-type
    mov eax, [rsi].RAWRSSAINSTR.flagsVarId
    cmp eax, -1
    je @@type_p1_next
    cmp eax, MAX_RECOVERED_TYPES
    jge @@type_p1_next
    lea rdi, typeVarClasses
    mov DWORD PTR [rdi + rax*4], TYPE_FLAGS
    lea rdi, typeConfidence
    mov DWORD PTR [rdi + rax*4], CONFIDENCE_CERTAIN
    jmp @@type_p1_next

@@type_p1_arith:
    ; ADD/SUB/MUL: result is integer, infer 64-bit width
    lea rdi, typeVarClasses
    mov DWORD PTR [rdi + r14*4], TYPE_INT64
    lea rdi, typeVarWidths
    mov DWORD PTR [rdi + r14*4], TYPE_WIDTH_64
    lea rdi, typeConfidence
    mov DWORD PTR [rdi + r14*4], CONFIDENCE_LOW
    jmp @@type_p1_next

@@type_p1_bitwise:
    ; AND/OR/XOR: result is unsigned integer
    lea rdi, typeVarClasses
    mov DWORD PTR [rdi + r14*4], TYPE_UINT64
    lea rdi, typeVarWidths
    mov DWORD PTR [rdi + r14*4], TYPE_WIDTH_64
    lea rdi, typeConfidence
    mov DWORD PTR [rdi + r14*4], CONFIDENCE_LOW
    jmp @@type_p1_next

@@type_p1_shift:
    ; SHL/SHR: unsigned shift
    lea rdi, typeVarClasses
    mov DWORD PTR [rdi + r14*4], TYPE_UINT64
    lea rdi, typeVarWidths
    mov DWORD PTR [rdi + r14*4], TYPE_WIDTH_64
    lea rdi, typeConfidence
    mov DWORD PTR [rdi + r14*4], CONFIDENCE_MEDIUM
    jmp @@type_p1_next

@@type_p1_shift_signed:
    ; SAR: arithmetic (signed) shift → signed type
    lea rdi, typeVarClasses
    mov DWORD PTR [rdi + r14*4], TYPE_INT64
    lea rdi, typeVarWidths
    mov DWORD PTR [rdi + r14*4], TYPE_WIDTH_64
    lea rdi, typeConfidence
    mov DWORD PTR [rdi + r14*4], CONFIDENCE_MEDIUM
    jmp @@type_p1_next

@@type_p1_assign:
    ; Assignment: propagate type from source if known
    mov eax, [rsi].RAWRSSAINSTR.src1VarId
    cmp eax, -1
    je @@type_p1_default
    cmp eax, MAX_RECOVERED_TYPES
    jge @@type_p1_default
    ; Copy type from src1 to dst
    lea rdi, typeVarClasses
    mov ecx, DWORD PTR [rdi + rax*4]
    mov DWORD PTR [rdi + r14*4], ecx
    lea rdi, typeVarWidths
    mov ecx, DWORD PTR [rdi + rax*4]
    mov DWORD PTR [rdi + r14*4], ecx
    lea rdi, typeConfidence
    mov ecx, DWORD PTR [rdi + rax*4]
    mov DWORD PTR [rdi + r14*4], ecx
    jmp @@type_p1_next

@@type_p1_default:
    ; Unknown instruction: mark as unknown
    lea rdi, typeVarClasses
    mov DWORD PTR [rdi + r14*4], TYPE_UNKNOWN
    lea rdi, typeConfidence
    mov DWORD PTR [rdi + r14*4], CONFIDENCE_NONE

@@type_p1_next:
    inc r13d
    jmp @@type_p1_loop

    ; -----------------------------------------------------------------------
    ; Pass 2: Pointer dereference pattern detection
    ; If a variable is used as base in a LOAD/STORE at multiple different
    ; displacements, it's a struct pointer. Track unique offsets.
    ; -----------------------------------------------------------------------
@@type_pass2:
    ; Walk SSA instructions again looking for LOAD/STORE patterns
    lea rax, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov r12d, [rax].DYNARRAY.count
    test r12d, r12d
    jz @@type_pass3

    xor r13d, r13d                  ; SSA instruction index
@@type_p2_loop:
    cmp r13d, r12d
    jge @@type_pass3

    lea rcx, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov edx, r13d
    call DynArray_Get
    test rax, rax
    jz @@type_p2_next
    mov rsi, rax

    ; Only care about LOAD and STORE operations
    mov ecx, [rsi].RAWRSSAINSTR.ssaOp
    cmp ecx, SSA_OP_LOAD
    je @@type_p2_check_ptr
    cmp ecx, SSA_OP_STORE
    je @@type_p2_check_ptr
    jmp @@type_p2_next

@@type_p2_check_ptr:
    ; For LOAD: src1 is the pointer base
    ; For STORE: dst is the pointer base
    cmp ecx, SSA_OP_LOAD
    jne @@type_p2_store_base
    mov eax, [rsi].RAWRSSAINSTR.src1VarId
    jmp @@type_p2_have_base
@@type_p2_store_base:
    mov eax, [rsi].RAWRSSAINSTR.dstVarId
@@type_p2_have_base:
    cmp eax, -1
    je @@type_p2_next
    cmp eax, MAX_RECOVERED_TYPES
    jge @@type_p2_next

    ; Check if this base var is already marked as struct_ptr
    lea rdi, typeVarClasses
    cmp DWORD PTR [rdi + rax*4], TYPE_STRUCT_PTR
    je @@type_p2_next              ; Already classified

    ; Check if this base var had a previous LOAD/STORE at a different offset
    ; For simplicity: if a pointer var is used in >=2 LOAD/STORE instructions,
    ; promote it to struct_ptr
    ; We use the original instruction's address as a surrogate for "different field"
    lea rdi, typeVarClasses
    cmp DWORD PTR [rdi + rax*4], TYPE_DATA_PTR
    jne @@type_p2_next

    ; Promote to struct_ptr (we already saw one access, this is the second)
    mov DWORD PTR [rdi + rax*4], TYPE_STRUCT_PTR
    lea rdi, typeConfidence
    mov DWORD PTR [rdi + rax*4], CONFIDENCE_MEDIUM

@@type_p2_next:
    inc r13d
    jmp @@type_p2_loop

    ; -----------------------------------------------------------------------
    ; Pass 3: Build RAWRTYPEINFO entries from the scratch arrays
    ; Push one RAWRTYPEINFO per SSA variable that has a non-UNKNOWN type
    ; -----------------------------------------------------------------------
@@type_pass3:
    lea rax, [rbx].RAWRCODEX_CTX.ssaVars
    mov r12d, [rax].DYNARRAY.count
    test r12d, r12d
    jz @@type_done

    xor r13d, r13d                  ; SSA var index
@@type_p3_loop:
    cmp r13d, r12d
    jge @@type_done

    ; Get SSA variable
    lea rcx, [rbx].RAWRCODEX_CTX.ssaVars
    mov edx, r13d
    call DynArray_Get
    test rax, rax
    jz @@type_p3_next
    mov rsi, rax                    ; rsi = ptr to RAWRSSAVAR

    mov r14d, [rsi].RAWRSSAVAR.varId
    cmp r14d, MAX_RECOVERED_TYPES
    jge @@type_p3_next

    ; Check if this variable has a non-UNKNOWN type
    lea rdi, typeVarClasses
    mov ecx, DWORD PTR [rdi + r14*4]
    cmp ecx, TYPE_UNKNOWN
    je @@type_p3_next

    ; Build a RAWRTYPEINFO on the stack
    sub rsp, SIZEOF RAWRTYPEINFO
    mov r8, rsp

    ; Zero it
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRTYPEINFO
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi

    ; Fill fields
    mov eax, [rbx].RAWRCODEX_CTX.typeNextId
    mov [r8].RAWRTYPEINFO.typeId, eax
    inc [rbx].RAWRCODEX_CTX.typeNextId

    ; baseType from scratch array
    lea rdi, typeVarClasses
    mov eax, DWORD PTR [rdi + r14*4]
    mov [r8].RAWRTYPEINFO.baseType, eax

    ; typeWidth from scratch array
    lea rdi, typeVarWidths
    mov eax, DWORD PTR [rdi + r14*4]
    mov [r8].RAWRTYPEINFO.typeWidth, eax

    ; Is it a pointer?
    mov eax, [r8].RAWRTYPEINFO.baseType
    cmp eax, TYPE_POINTER
    je @@type_p3_isptr
    cmp eax, TYPE_CODE_PTR
    je @@type_p3_isptr
    cmp eax, TYPE_DATA_PTR
    je @@type_p3_isptr
    cmp eax, TYPE_STRUCT_PTR
    je @@type_p3_isptr
    cmp eax, TYPE_ARRAY_PTR
    je @@type_p3_isptr
    cmp eax, TYPE_STRING_PTR
    je @@type_p3_isptr
    mov [r8].RAWRTYPEINFO.isPointer, 0
    jmp @@type_p3_signed

@@type_p3_isptr:
    mov [r8].RAWRTYPEINFO.isPointer, 1

@@type_p3_signed:
    ; Is it signed?
    mov eax, [r8].RAWRTYPEINFO.baseType
    cmp eax, TYPE_INT8
    je @@type_p3_yes_signed
    cmp eax, TYPE_INT16
    je @@type_p3_yes_signed
    cmp eax, TYPE_INT32
    je @@type_p3_yes_signed
    cmp eax, TYPE_INT64
    je @@type_p3_yes_signed
    mov [r8].RAWRTYPEINFO.isSigned, 0
    jmp @@type_p3_confidence

@@type_p3_yes_signed:
    mov [r8].RAWRTYPEINFO.isSigned, 1

@@type_p3_confidence:
    ; Confidence from scratch array
    lea rdi, typeConfidence
    mov eax, DWORD PTR [rdi + r14*4]
    mov [r8].RAWRTYPEINFO.confidence, eax

    ; SSA var ID link
    mov [r8].RAWRTYPEINFO.ssaVarId, r14d

    ; Copy type name from type name table
    mov eax, [r8].RAWRTYPEINFO.baseType
    cmp eax, 20             ; bounds check (0..19)
    jge @@type_p3_unknown_name
    ; Lookup: typeNames[baseType * 16]
    shl eax, 4              ; eax = baseType * 16
    lea rcx, typeNames
    add rcx, rax            ; rcx = pointer to type name string
    lea rdi, [r8].RAWRTYPEINFO.szTypeName
    ; Copy up to 15 chars
    xor edx, edx
@@type_p3_copy_name:
    mov al, BYTE PTR [rcx + rdx]
    mov BYTE PTR [rdi + rdx], al
    test al, al
    jz @@type_p3_name_done
    inc edx
    cmp edx, 15
    jl @@type_p3_copy_name
    mov BYTE PTR [rdi + rdx], 0
    jmp @@type_p3_name_done

@@type_p3_unknown_name:
    lea rdi, [r8].RAWRTYPEINFO.szTypeName
    mov BYTE PTR [rdi], '?'
    mov BYTE PTR [rdi+1], 0

@@type_p3_name_done:
    ; Push RAWRTYPEINFO to typeInfos
    lea rcx, [rbx].RAWRCODEX_CTX.typeInfos
    mov rdx, r8
    call DynArray_Push
    add rsp, SIZEOF RAWRTYPEINFO

@@type_p3_next:
    inc r13d
    jmp @@type_p3_loop

@@type_done:
    mov [rbx].RAWRCODEX_CTX.typesRecovered, 1
    ; Return number of types recovered
    lea rcx, [rbx].RAWRCODEX_CTX.typeInfos
    mov eax, [rcx].DYNARRAY.count

    add rsp, 0A8h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret

@@type_fail:
    xor eax, eax
    add rsp, 0A8h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
RawrCodex_RecoverTypes ENDP

; =============================================================================
; RawrCodex_BuildDefUseChains - Construct definition-use chains for SSA vars
;
; For each SSA variable, records:
;   - Where it is defined (instruction + basic block)
;   - Where it is used (up to MAX_DEF_USE_CHAINS sites)
;   - Whether it is live at function exit (reaches RET)
;
; This enables dead code elimination, constant propagation, and
; register pressure analysis.
;
; Input:  RCX = pointer to RAWRCODEX_CTX (must have SSA lifted)
; Output: EAX = number of def-use chain entries (0 on error)
; =============================================================================
RawrCodex_BuildDefUseChains PROC
    push rbx
    push rsi
    push rdi
    push r12
    push r13
    push r14
    push r15
    sub rsp, 88h

    test rcx, rcx
    jz @@du_fail
    mov rbx, rcx

    cmp [rbx].RAWRCODEX_CTX.ssaLifted, 1
    jne @@du_fail

    ; Clear previous def-use chains
    lea rcx, [rbx].RAWRCODEX_CTX.defUseChains
    call DynArray_Clear

    ; Get counts
    lea rax, [rbx].RAWRCODEX_CTX.ssaVars
    mov r12d, [rax].DYNARRAY.count      ; r12 = number of SSA variables
    lea rax, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov r13d, [rax].DYNARRAY.count      ; r13 = number of SSA instructions
    test r12d, r12d
    jz @@du_done
    test r13d, r13d
    jz @@du_done

    ; For each SSA variable, build a def-use entry
    xor r14d, r14d                      ; r14 = SSA var index
@@du_var_loop:
    cmp r14d, r12d
    jge @@du_done

    ; Get SSA variable
    lea rcx, [rbx].RAWRCODEX_CTX.ssaVars
    mov edx, r14d
    call DynArray_Get
    test rax, rax
    jz @@du_var_next
    mov rsi, rax                        ; rsi = ptr to RAWRSSAVAR

    mov r15d, [rsi].RAWRSSAVAR.varId    ; r15 = this var's ID

    ; Build RAWRDEFUSE on stack
    sub rsp, SIZEOF RAWRDEFUSE
    mov r8, rsp

    ; Zero it
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRDEFUSE
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi

    ; Fill definition info
    mov [r8].RAWRDEFUSE.ssaVarId, r15d
    mov eax, [rsi].RAWRSSAVAR.instrIndex
    mov [r8].RAWRDEFUSE.defInstrIdx, eax
    mov eax, [rsi].RAWRSSAVAR.bbIndex
    mov [r8].RAWRDEFUSE.defBBIdx, eax
    mov [r8].RAWRDEFUSE.useCount, 0
    mov [r8].RAWRDEFUSE.isLive, 0
    mov [r8].RAWRDEFUSE.reachesReturn, 0

    ; Walk all SSA instructions to find uses of this variable
    xor edi, edi                        ; edi = SSA instruction index
@@du_instr_loop:
    cmp edi, r13d
    jge @@du_instr_done

    ; Get SSA instruction
    push r8                             ; Save RAWRDEFUSE ptr
    lea rcx, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov edx, edi
    call DynArray_Get
    pop r8
    test rax, rax
    jz @@du_instr_next

    ; Check if this instruction uses our variable (src1, src2, or flagsVarId)
    mov ecx, [rax].RAWRSSAINSTR.src1VarId
    cmp ecx, r15d
    je @@du_found_use
    mov ecx, [rax].RAWRSSAINSTR.src2VarId
    cmp ecx, r15d
    je @@du_found_use
    mov ecx, [rax].RAWRSSAINSTR.flagsVarId
    cmp ecx, r15d
    je @@du_found_use
    jmp @@du_instr_next

@@du_found_use:
    ; Record use site (if room in array)
    mov ecx, [r8].RAWRDEFUSE.useCount
    cmp ecx, MAX_DEF_USE_CHAINS
    jge @@du_instr_next

    ; Store instruction index
    lea r9, [r8].RAWRDEFUSE.useInstrIdxs
    mov DWORD PTR [r9 + rcx*4], edi

    ; Store basic block index
    mov edx, [rax].RAWRSSAINSTR.bbIndex
    lea r9, [r8].RAWRDEFUSE.useBBIdxs
    mov DWORD PTR [r9 + rcx*4], edx

    inc [r8].RAWRDEFUSE.useCount

    ; Check if this use is in a RET instruction
    cmp [rax].RAWRSSAINSTR.ssaOp, SSA_OP_RET
    jne @@du_instr_next
    mov [r8].RAWRDEFUSE.reachesReturn, 1
    mov [r8].RAWRDEFUSE.isLive, 1

@@du_instr_next:
    inc edi
    jmp @@du_instr_loop

@@du_instr_done:
    ; If useCount > 0, the variable is "used" (not dead)
    cmp [r8].RAWRDEFUSE.useCount, 0
    je @@du_maybe_dead
    mov [r8].RAWRDEFUSE.isLive, 1
    jmp @@du_push_entry

@@du_maybe_dead:
    ; Zero uses = dead code candidate
    mov [r8].RAWRDEFUSE.isLive, 0

@@du_push_entry:
    ; Push to defUseChains
    lea rcx, [rbx].RAWRCODEX_CTX.defUseChains
    mov rdx, r8
    call DynArray_Push
    add rsp, SIZEOF RAWRDEFUSE

@@du_var_next:
    inc r14d
    jmp @@du_var_loop

@@du_done:
    lea rcx, [rbx].RAWRCODEX_CTX.defUseChains
    mov eax, [rcx].DYNARRAY.count

    add rsp, 88h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret

@@du_fail:
    xor eax, eax
    add rsp, 88h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
RawrCodex_BuildDefUseChains ENDP

; =============================================================================
; =============================================================================
;
;   PHASE 18: SEMANTIC PSEUDOCODE GENERATION
;   Control Flow Structuring + C Pseudocode Emission
;
;   Prerequisites: Phase 15 (CFG), Phase 16 (SSA), Phase 17 (Types)
;
;   Pipeline:
;     1. RawrCodex_StructureControlFlow  — Dominator tree, edge classification,
;        interval-based loop/conditional detection, region building
;     2. RawrCodex_EmitPseudocode        — Walk structured regions, emit C-like
;        pseudocode with type annotations and expression trees
;
; =============================================================================
; =============================================================================

; =============================================================================
; RawrCodex_StructureControlFlow — Interval-based CFG structuring algorithm
;
; Transforms the flat CFG (basic blocks + edges) into a hierarchy of
; structured regions (while, if-then-else, do-while, sequence, goto).
;
; Algorithm (Sharir, 1980 + Tarjan dominator refinement):
;   Phase A: Compute dominator tree via Lengauer-Tarjan O(n α(n))
;   Phase B: DFS edge classification (tree/forward/back/cross)
;   Phase C: Identify natural loops from back edges
;   Phase D: Build structured regions (intervals → regions)
;   Phase E: Handle irreducible flow with goto fallback
;
; Input:  RCX = pointer to RAWRCODEX_CTX (must have CFG + SSA + Types done)
; Output: EAX = number of structured regions (0 on error)
;
; Requires:
;   - basicBlocks populated (RawrCodex_BuildCFG called)
;   - ssaInstrs populated (RawrCodex_LiftToSSA called)
;   - typeInfos populated (RawrCodex_RecoverTypes called)
;
; License gate: FEATURE_STRUCTURING (Government tier)
; =============================================================================
RawrCodex_StructureControlFlow PROC
    push rbx
    push rsi
    push rdi
    push r12
    push r13
    push r14
    push r15
    sub rsp, 0C8h                   ; Shadow + generous locals

    test rcx, rcx
    jz @@scf_fail
    mov rbx, rcx                    ; rbx = ctx

    ; License gate check
    mov edx, FEATURE_STRUCTURING
    call RawrLicense_CheckFeature
    test eax, eax
    jz @@scf_fail

    ; Validate prerequisites
    lea rax, [rbx].RAWRCODEX_CTX.basicBlocks
    mov r12d, [rax].DYNARRAY.count  ; r12 = number of basic blocks
    test r12d, r12d
    jz @@scf_fail
    cmp r12d, MAX_DOMINATOR_NODES
    jge @@scf_fail                  ; CFG too large for scratch arrays

    cmp [rbx].RAWRCODEX_CTX.ssaLifted, 1
    jne @@scf_fail

    ; Clear previous structuring data
    lea rcx, [rbx].RAWRCODEX_CTX.cfgEdges
    call DynArray_Clear
    lea rcx, [rbx].RAWRCODEX_CTX.structRegions
    call DynArray_Clear
    lea rcx, [rbx].RAWRCODEX_CTX.astNodes
    call DynArray_Clear
    mov [rbx].RAWRCODEX_CTX.structNextRegion, 0
    mov [rbx].RAWRCODEX_CTX.astNextNode, 0
    mov [rbx].RAWRCODEX_CTX.cfgStructured, 0

    ; =====================================================================
    ; Phase A: Compute Dominator Tree (Lengauer-Tarjan, simplified)
    ;
    ; Uses iterative data-flow approach (Cooper, Harvey, Kennedy):
    ;   1. Number all BBs in reverse postorder (from DFS)
    ;   2. Iterate until convergence:
    ;        for each BB (except entry):
    ;          new_idom = intersect of all predecessors' dominators
    ;          if idom[BB] changed, set changed = true
    ;   3. idom[entry] = entry (self-dominates)
    ;
    ; This is O(n^2) worst case but converges fast on reducible CFGs.
    ; =====================================================================

    ; Initialize dominator arrays
    lea rdi, domIdoms
    mov ecx, r12d
    mov eax, -1                     ; -1 = undefined
@@scf_init_idoms:
    mov DWORD PTR [rdi + rcx*4 - 4], eax
    dec ecx
    jnz @@scf_init_idoms

    ; Initialize DFS numbering arrays
    lea rdi, domDfsNums
    xor eax, eax
    mov ecx, r12d
    rep stosd

    lea rdi, domDfsParent
    mov eax, -1
    mov ecx, r12d
    rep stosd

    mov [domDfsCounter], 0
    mov [domNumNodes], r12d

    ; -----------------------------------------------------------------
    ; DFS traversal to compute reverse postorder numbering
    ; Using iterative DFS with explicit stack (domVertex as worklist)
    ; -----------------------------------------------------------------
    ; DFS stack stored in domVertex temporarily
    ; domVertex[i] will hold the BB index in RPO order after DFS
    lea rdi, domVertex
    mov DWORD PTR [rdi], 0          ; Push BB 0 (entry)
    mov r13d, 1                     ; Stack pointer (1 item)

    ; Visited bitmap on stack
    lea r14, domDfsNums             ; Reuse as visited markers (set >0 = visited)

    xor r15d, r15d                  ; RPO counter (fills from end)

@@scf_dfs_loop:
    test r13d, r13d
    jz @@scf_dfs_done

    ; Pop from DFS stack
    dec r13d
    lea rdi, domVertex
    mov esi, DWORD PTR [rdi + r13*4]   ; esi = current BB index

    ; Check if already visited
    cmp DWORD PTR [r14 + rsi*4], 0
    jne @@scf_dfs_loop              ; Already visited, skip
    mov DWORD PTR [r14 + rsi*4], 1  ; Mark visited

    ; Get BB pointer for successor enumeration
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    mov edx, esi
    call DynArray_Get
    test rax, rax
    jz @@scf_dfs_post

    ; Push all successors onto DFS stack
    mov ecx, [rax].RAWRBASICBLOCK.successorCount
    test ecx, ecx
    jz @@scf_dfs_post

    ; Find BB indices for successor addresses
    xor edi, edi                    ; successor index
@@scf_dfs_push_succ:
    cmp edi, ecx
    jge @@scf_dfs_post

    ; Get successor address
    mov [rsp + 50h], ecx            ; Save successor count
    mov [rsp + 54h], esi            ; Save current BB index
    mov [rsp + 58h], edi            ; Save successor index
    lea r8, [rax + 40]             ; &block.successors[0] (offset 40 = after header fields)
    mov r9, QWORD PTR [r8 + rdi*8] ; successor address

    ; Search for BB with this start address
    push rax
    xor edx, edx                   ; BB search index
@@scf_find_succ_bb:
    cmp edx, r12d
    jge @@scf_succ_not_found

    push rdx
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    call DynArray_Get
    pop rdx
    test rax, rax
    jz @@scf_succ_search_next
    cmp [rax].RAWRBASICBLOCK.startAddress, r9
    jne @@scf_succ_search_next

    ; Found successor BB — push onto DFS stack if not visited
    cmp DWORD PTR [r14 + rdx*4], 0
    jne @@scf_succ_found_skip
    lea rdi, domVertex
    mov DWORD PTR [rdi + r13*4], edx
    inc r13d
    ; Record DFS parent
    mov eax, [rsp + 54h + 8]       ; current BB (adjusted for push rax)
    lea r11, domDfsParent
    mov DWORD PTR [r11 + rdx*4], eax
@@scf_succ_found_skip:
    jmp @@scf_succ_found

@@scf_succ_search_next:
    inc edx
    jmp @@scf_find_succ_bb

@@scf_succ_not_found:
@@scf_succ_found:
    pop rax                         ; Restore BB pointer
    mov ecx, [rsp + 50h]
    mov esi, [rsp + 54h]
    mov edi, [rsp + 58h]
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    mov edx, esi
    push rcx
    push r13
    call DynArray_Get               ; Re-fetch current BB pointer
    pop r13
    pop rcx
    mov ecx, [rax].RAWRBASICBLOCK.successorCount
    inc edi
    jmp @@scf_dfs_push_succ

@@scf_dfs_post:
    ; Assign RPO number
    mov eax, r12d
    dec eax
    sub eax, r15d                   ; RPO number = (numBBs - 1) - counter
    lea r11, domDfsNums
    mov DWORD PTR [r11 + rsi*4], eax
    inc r15d
    jmp @@scf_dfs_loop

@@scf_dfs_done:

    ; -----------------------------------------------------------------
    ; Iterative dominator computation (Cooper-Harvey-Kennedy)
    ; idom[entry] = entry
    ; Repeat until no changes:
    ;   for each BB b (RPO order, skip entry):
    ;     new_idom = first processed predecessor
    ;     for each other processed predecessor p:
    ;       new_idom = intersect(new_idom, p)
    ;     if idom[b] != new_idom:
    ;       idom[b] = new_idom; changed = true
    ; -----------------------------------------------------------------
    lea rdi, domIdoms
    mov DWORD PTR [rdi], 0          ; idom[0] = 0 (entry dominates itself)

@@scf_dom_iterate:
    xor r15d, r15d                  ; changed = false
    mov esi, 1                      ; Start from BB 1 (skip entry)

@@scf_dom_bb_loop:
    cmp esi, r12d
    jge @@scf_dom_check_converge

    ; Get BB pointer for predecessor enumeration
    mov [rsp + 50h], esi            ; Save current BB index
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    mov edx, esi
    call DynArray_Get
    test rax, rax
    jz @@scf_dom_bb_next

    mov ecx, [rax].RAWRBASICBLOCK.predecessorCount
    test ecx, ecx
    jz @@scf_dom_bb_next            ; No predecessors — unreachable

    ; Find first processed predecessor (idom != -1)
    mov r13d, -1                    ; new_idom = undefined
    xor edi, edi                    ; predecessor index

@@scf_dom_find_first_pred:
    cmp edi, ecx
    jge @@scf_dom_apply

    ; Get predecessor address
    lea r8, [rax + 104]            ; &block.predecessors[0] (offset 104)
    mov r9, QWORD PTR [r8 + rdi*8]

    ; Find BB index for this predecessor address
    push rax
    push rcx
    push rdi
    xor edx, edx
@@scf_dom_find_pred_bb:
    cmp edx, r12d
    jge @@scf_dom_pred_not_found
    push rdx
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    call DynArray_Get
    pop rdx
    test rax, rax
    jz @@scf_dom_pred_search_next
    cmp [rax].RAWRBASICBLOCK.startAddress, r9
    je @@scf_dom_pred_found
@@scf_dom_pred_search_next:
    inc edx
    jmp @@scf_dom_find_pred_bb

@@scf_dom_pred_not_found:
    pop rdi
    pop rcx
    pop rax
    inc edi
    jmp @@scf_dom_find_first_pred

@@scf_dom_pred_found:
    ; edx = predecessor BB index
    lea r8, domIdoms
    cmp DWORD PTR [r8 + rdx*4], -1
    je @@scf_dom_pred_not_processed
    ; This predecessor is processed — use as initial new_idom
    mov r13d, edx
    pop rdi
    pop rcx
    pop rax
    inc edi
    jmp @@scf_dom_intersect_preds

@@scf_dom_pred_not_processed:
    pop rdi
    pop rcx
    pop rax
    inc edi
    jmp @@scf_dom_find_first_pred

@@scf_dom_intersect_preds:
    ; Intersect remaining predecessors
    cmp edi, ecx
    jge @@scf_dom_apply

    ; Get next predecessor address
    lea r8, [rax + 104]
    mov r9, QWORD PTR [r8 + rdi*8]

    ; Find BB index
    push rax
    push rcx
    push rdi
    xor edx, edx
@@scf_dom_find_pred_bb2:
    cmp edx, r12d
    jge @@scf_dom_pred2_not_found
    push rdx
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    call DynArray_Get
    pop rdx
    test rax, rax
    jz @@scf_dom_pred2_next
    cmp [rax].RAWRBASICBLOCK.startAddress, r9
    je @@scf_dom_pred2_found
@@scf_dom_pred2_next:
    inc edx
    jmp @@scf_dom_find_pred_bb2

@@scf_dom_pred2_not_found:
    pop rdi
    pop rcx
    pop rax
    inc edi
    jmp @@scf_dom_intersect_preds

@@scf_dom_pred2_found:
    ; edx = this predecessor's BB index
    lea r8, domIdoms
    cmp DWORD PTR [r8 + rdx*4], -1
    je @@scf_dom_skip_unprocessed
    ; Intersect: walk up dominator chains until they meet
    mov r8d, r13d                   ; finger1 = new_idom
    mov r9d, edx                    ; finger2 = this predecessor

@@scf_dom_intersect_walk:
    cmp r8d, r9d
    je @@scf_dom_intersect_done
    ; Walk the higher-numbered finger up
@@scf_dom_walk_f1:
    cmp r8d, r9d
    jle @@scf_dom_walk_f2
    lea r10, domIdoms
    mov r8d, DWORD PTR [r10 + r8*4] ; finger1 = idom[finger1]
    cmp r8d, -1
    je @@scf_dom_intersect_done     ; Safety: prevent infinite loop
    jmp @@scf_dom_intersect_walk
@@scf_dom_walk_f2:
    cmp r9d, r8d
    jle @@scf_dom_intersect_walk
    lea r10, domIdoms
    mov r9d, DWORD PTR [r10 + r9*4] ; finger2 = idom[finger2]
    cmp r9d, -1
    je @@scf_dom_intersect_done
    jmp @@scf_dom_intersect_walk

@@scf_dom_intersect_done:
    mov r13d, r8d                   ; new_idom = meeting point

@@scf_dom_skip_unprocessed:
    pop rdi
    pop rcx
    pop rax
    inc edi
    jmp @@scf_dom_intersect_preds

@@scf_dom_apply:
    ; Apply new_idom if changed
    mov esi, [rsp + 50h]            ; Restore current BB index
    cmp r13d, -1
    je @@scf_dom_bb_next            ; No processed predecessor found
    lea r8, domIdoms
    cmp DWORD PTR [r8 + rsi*4], r13d
    je @@scf_dom_bb_next            ; No change
    mov DWORD PTR [r8 + rsi*4], r13d ; idom[b] = new_idom
    mov r15d, 1                     ; changed = true

@@scf_dom_bb_next:
    mov esi, [rsp + 50h]
    inc esi
    jmp @@scf_dom_bb_loop

@@scf_dom_check_converge:
    test r15d, r15d
    jnz @@scf_dom_iterate           ; Not converged — iterate again

    ; =====================================================================
    ; Phase B: DFS Edge Classification
    ;
    ; Walk all CFG edges and classify using DFS numbers + dominator tree:
    ;   - Back edge:    target dominates source (descendant → ancestor)
    ;   - Forward edge: source dominates target, not a tree edge
    ;   - Cross edge:   neither dominates the other
    ;   - Tree edge:    parent in DFS tree
    ;
    ; Back edges indicate natural loops.
    ; =====================================================================
    xor esi, esi                    ; BB index

@@scf_edge_classify_loop:
    cmp esi, r12d
    jge @@scf_phase_c

    mov [rsp + 50h], esi
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    mov edx, esi
    call DynArray_Get
    test rax, rax
    jz @@scf_edge_next_bb
    mov r14, rax                    ; r14 = current BB pointer

    ; For each successor of this BB
    mov ecx, [r14].RAWRBASICBLOCK.successorCount
    xor edi, edi

@@scf_edge_succ_loop:
    cmp edi, ecx
    jge @@scf_edge_next_bb

    mov [rsp + 58h], edi
    mov [rsp + 5Ch], ecx

    ; Get successor address
    lea r8, [r14 + 40]
    mov r9, QWORD PTR [r8 + rdi*8]

    ; Find successor BB index
    xor edx, edx
@@scf_edge_find_succ:
    cmp edx, r12d
    jge @@scf_edge_succ_next
    push rdx
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    call DynArray_Get
    pop rdx
    test rax, rax
    jz @@scf_edge_succ_search_next
    cmp [rax].RAWRBASICBLOCK.startAddress, r9
    je @@scf_edge_succ_found
@@scf_edge_succ_search_next:
    inc edx
    jmp @@scf_edge_find_succ

@@scf_edge_succ_found:
    ; esi (from stack) = source BB, edx = target BB
    mov esi, [rsp + 50h]
    mov r13d, edx                   ; r13d = target BB index

    ; Build RAWRCFGEDGE on scratch
    lea r8, edgeScratch
    mov DWORD PTR [r8].RAWRCFGEDGE.fromBB, esi
    mov DWORD PTR [r8].RAWRCFGEDGE.toBB, r13d
    mov DWORD PTR [r8].RAWRCFGEDGE.isLoopEdge, 0

    ; Classify edge:
    ; Check if target dominates source (back edge test)
    ; Walk idom chain from source upward; if we reach target, it's a back edge
    mov eax, esi                    ; finger = source BB
    mov ecx, 0                      ; iteration guard

@@scf_edge_dom_walk:
    cmp eax, r13d
    je @@scf_edge_is_back           ; target dominates source
    cmp eax, -1
    je @@scf_edge_not_back
    cmp eax, 0
    je @@scf_edge_check_entry       ; Reached entry
    inc ecx
    cmp ecx, MAX_DOMINATOR_NODES
    jge @@scf_edge_not_back         ; Safety guard
    lea r10, domIdoms
    mov eax, DWORD PTR [r10 + rax*4]
    jmp @@scf_edge_dom_walk

@@scf_edge_check_entry:
    cmp r13d, 0
    je @@scf_edge_is_back           ; Entry dominates everything
    jmp @@scf_edge_not_back

@@scf_edge_is_back:
    mov DWORD PTR [r8].RAWRCFGEDGE.edgeType, EDGE_BACK
    mov DWORD PTR [r8].RAWRCFGEDGE.isLoopEdge, 1
    jmp @@scf_edge_push

@@scf_edge_not_back:
    ; Check if source dominates target (forward edge)
    mov eax, r13d                   ; finger = target BB
    xor ecx, ecx

@@scf_edge_fwd_walk:
    cmp eax, esi
    je @@scf_edge_is_forward
    cmp eax, -1
    je @@scf_edge_is_cross
    cmp eax, 0
    je @@scf_edge_fwd_check_entry
    inc ecx
    cmp ecx, MAX_DOMINATOR_NODES
    jge @@scf_edge_is_cross
    lea r10, domIdoms
    mov eax, DWORD PTR [r10 + rax*4]
    jmp @@scf_edge_fwd_walk

@@scf_edge_fwd_check_entry:
    cmp esi, 0
    je @@scf_edge_is_forward
    jmp @@scf_edge_is_cross

@@scf_edge_is_forward:
    ; Check if it's a tree edge (DFS parent)
    lea r10, domDfsParent
    cmp DWORD PTR [r10 + r13*4], esi
    je @@scf_edge_is_tree
    mov DWORD PTR [r8].RAWRCFGEDGE.edgeType, EDGE_FORWARD
    jmp @@scf_edge_push

@@scf_edge_is_tree:
    mov DWORD PTR [r8].RAWRCFGEDGE.edgeType, EDGE_TREE
    jmp @@scf_edge_push

@@scf_edge_is_cross:
    mov DWORD PTR [r8].RAWRCFGEDGE.edgeType, EDGE_CROSS
    jmp @@scf_edge_push

@@scf_edge_push:
    ; Push edge to cfgEdges
    lea rcx, [rbx].RAWRCODEX_CTX.cfgEdges
    lea rdx, edgeScratch
    call DynArray_Push

@@scf_edge_succ_next:
    mov edi, [rsp + 58h]
    mov ecx, [rsp + 5Ch]
    inc edi
    mov esi, [rsp + 50h]
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    mov edx, esi
    push rcx
    call DynArray_Get
    pop rcx
    mov r14, rax
    mov ecx, [r14].RAWRBASICBLOCK.successorCount
    jmp @@scf_edge_succ_loop

@@scf_edge_next_bb:
    mov esi, [rsp + 50h]
    inc esi
    jmp @@scf_edge_classify_loop

    ; =====================================================================
    ; Phase C: Identify Natural Loops from Back Edges
    ;
    ; For each back edge (source → header):
    ;   The "natural loop" is the set of nodes that can reach source
    ;   without going through header. header is the loop header.
    ;
    ; We build a REGION_WHILE_LOOP for each detected natural loop.
    ; =====================================================================
@@scf_phase_c:
    lea rax, [rbx].RAWRCODEX_CTX.cfgEdges
    mov r13d, [rax].DYNARRAY.count  ; r13 = total classified edges
    xor r14d, r14d                  ; edge index

@@scf_loop_detect:
    cmp r14d, r13d
    jge @@scf_phase_d

    lea rcx, [rbx].RAWRCODEX_CTX.cfgEdges
    mov edx, r14d
    call DynArray_Get
    test rax, rax
    jz @@scf_loop_next_edge

    cmp [rax].RAWRCFGEDGE.edgeType, EDGE_BACK
    jne @@scf_loop_next_edge

    ; Back edge found: source = [rax].fromBB, header = [rax].toBB
    mov esi, [rax].RAWRCFGEDGE.fromBB    ; loop tail
    mov edi, [rax].RAWRCFGEDGE.toBB      ; loop header

    ; Build a WHILE loop region
    lea r8, regionScratch
    ; Zero the region
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRSTRUCTREGION
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi

    lea r8, regionScratch
    mov DWORD PTR [r8].RAWRSTRUCTREGION.regionType, REGION_WHILE_LOOP
    mov DWORD PTR [r8].RAWRSTRUCTREGION.headBB, edi
    mov DWORD PTR [r8].RAWRSTRUCTREGION.exitBB, -1        ; Determined later
    mov DWORD PTR [r8].RAWRSTRUCTREGION.condVarId, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.thenRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.elseRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bodyRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.parentRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.depth, 0

    ; Populate BB list with loop body nodes
    ; Simple heuristic: all BBs from header to tail (inclusive)
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bbList, edi  ; First = header
    mov ecx, 1                                       ; bbCount
    cmp esi, edi
    je @@scf_loop_single_bb                          ; Single-BB loop

    ; Walk BB indices from header+1 to tail
    mov eax, edi
    inc eax
@@scf_loop_fill_body:
    cmp eax, esi
    jg @@scf_loop_body_done
    cmp ecx, 16                     ; Max BBs per region
    jge @@scf_loop_body_done
    mov DWORD PTR [r8 + RAWRSTRUCTREGION.bbList + rcx*4], eax
    inc ecx
    inc eax
    jmp @@scf_loop_fill_body

@@scf_loop_single_bb:
@@scf_loop_body_done:
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bbCount, ecx

    ; Determine exit BB: first successor of header that is NOT in the loop
    push rcx
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    mov edx, edi                    ; header BB
    call DynArray_Get
    pop rcx
    test rax, rax
    jz @@scf_loop_no_exit

    mov edx, [rax].RAWRBASICBLOCK.successorCount
    cmp edx, 2
    jb @@scf_loop_no_exit           ; Need at least 2 successors for while-loop exit

    ; Successor[1] is typically the exit (fall-through = loop body, branch = exit)
    ; Use the successor that is NOT the loop body (i.e., not between header and tail)
    ; For now: if header has 2 successors, exit = the one outside [header..tail]
    ; This will be refined by the condition analysis

    lea r8, regionScratch
    mov DWORD PTR [r8].RAWRSTRUCTREGION.condCode, CC_NE  ; Default condition

    ; Try to find the condition variable from the header's last SSA instruction
    ; (should be a BRANCH instruction consuming flags)
    push rax                        ; Save BB pointer
    lea rcx, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov r9d, [rcx].DYNARRAY.count
    test r9d, r9d
    jz @@scf_loop_no_cond

    ; Scan SSA instructions for BRANCH in header BB
    dec r9d
@@scf_loop_find_branch:
    cmp r9d, 0
    jl @@scf_loop_no_cond
    push r9
    lea rcx, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov edx, r9d
    call DynArray_Get
    pop r9
    test rax, rax
    jz @@scf_loop_find_branch_prev
    cmp [rax].RAWRSSAINSTR.bbIndex, edi
    jne @@scf_loop_find_branch_prev
    cmp [rax].RAWRSSAINSTR.ssaOp, SSA_OP_BRANCH
    je @@scf_loop_found_branch
@@scf_loop_find_branch_prev:
    dec r9d
    jmp @@scf_loop_find_branch

@@scf_loop_found_branch:
    ; Found BRANCH in header BB — extract condition variable
    mov ecx, [rax].RAWRSSAINSTR.flagsVarId
    lea r8, regionScratch
    mov DWORD PTR [r8].RAWRSTRUCTREGION.condVarId, ecx
    jmp @@scf_loop_cond_done

@@scf_loop_no_cond:
    lea r8, regionScratch
    mov DWORD PTR [r8].RAWRSTRUCTREGION.condVarId, -1

@@scf_loop_cond_done:
    pop rax                         ; Restore BB pointer (may be stale, but okay)

@@scf_loop_no_exit:
    ; Push loop region
    lea rcx, [rbx].RAWRCODEX_CTX.structRegions
    lea rdx, regionScratch
    call DynArray_Push
    inc [rbx].RAWRCODEX_CTX.structNextRegion

@@scf_loop_next_edge:
    inc r14d
    jmp @@scf_loop_detect

    ; =====================================================================
    ; Phase D: Build If-Then-Else Regions from Forward/Cross Edges
    ;
    ; For each BB with exactly 2 successors that is NOT a loop header:
    ;   If both successors converge at a common post-dominator → if-then-else
    ;   If only one path reaches a merge → if-then
    ;
    ; Also build SEQUENCE regions for linear chains.
    ; =====================================================================
@@scf_phase_d:
    xor esi, esi                    ; BB index

@@scf_region_build_loop:
    cmp esi, r12d
    jge @@scf_phase_e

    mov [rsp + 50h], esi
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    mov edx, esi
    call DynArray_Get
    test rax, rax
    jz @@scf_region_next_bb
    mov r14, rax

    ; Check if this BB is already covered by a loop region
    ; (skip if it's a loop header — already handled in Phase C)
    lea rcx, [rbx].RAWRCODEX_CTX.structRegions
    mov r13d, [rcx].DYNARRAY.count
    xor edi, edi
@@scf_check_loop_header:
    cmp edi, r13d
    jge @@scf_not_loop_header
    push rdi
    lea rcx, [rbx].RAWRCODEX_CTX.structRegions
    mov edx, edi
    call DynArray_Get
    pop rdi
    test rax, rax
    jz @@scf_check_loop_next
    cmp [rax].RAWRSTRUCTREGION.regionType, REGION_WHILE_LOOP
    jne @@scf_check_loop_next
    mov ecx, [rsp + 50h]
    cmp [rax].RAWRSTRUCTREGION.headBB, ecx
    je @@scf_region_next_bb         ; Already a loop header — skip
@@scf_check_loop_next:
    inc edi
    jmp @@scf_check_loop_header

@@scf_not_loop_header:
    mov esi, [rsp + 50h]

    ; Check successor count
    mov ecx, [r14].RAWRBASICBLOCK.successorCount

    cmp ecx, 2
    je @@scf_build_if_region
    cmp ecx, 1
    je @@scf_build_sequence
    cmp ecx, 0
    je @@scf_build_return
    jmp @@scf_region_next_bb        ; >2 successors = switch (TODO: Phase 19)

@@scf_build_return:
    ; Zero successors = return block
    lea r8, regionScratch
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRSTRUCTREGION
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi
    lea r8, regionScratch
    mov DWORD PTR [r8].RAWRSTRUCTREGION.regionType, REGION_RETURN
    mov DWORD PTR [r8].RAWRSTRUCTREGION.headBB, esi
    mov DWORD PTR [r8].RAWRSTRUCTREGION.exitBB, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.condVarId, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.thenRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.elseRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bodyRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.parentRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.depth, 0
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bbCount, 1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bbList, esi

    lea rcx, [rbx].RAWRCODEX_CTX.structRegions
    lea rdx, regionScratch
    call DynArray_Push
    inc [rbx].RAWRCODEX_CTX.structNextRegion
    jmp @@scf_region_next_bb

@@scf_build_sequence:
    ; Single successor = sequence block
    lea r8, regionScratch
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRSTRUCTREGION
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi
    lea r8, regionScratch
    mov DWORD PTR [r8].RAWRSTRUCTREGION.regionType, REGION_SEQUENCE
    mov DWORD PTR [r8].RAWRSTRUCTREGION.headBB, esi
    mov DWORD PTR [r8].RAWRSTRUCTREGION.exitBB, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.condVarId, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.thenRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.elseRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bodyRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.parentRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.depth, 0
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bbCount, 1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bbList, esi

    lea rcx, [rbx].RAWRCODEX_CTX.structRegions
    lea rdx, regionScratch
    call DynArray_Push
    inc [rbx].RAWRCODEX_CTX.structNextRegion
    jmp @@scf_region_next_bb

@@scf_build_if_region:
    ; 2 successors = conditional (if-then or if-then-else)
    ; Successor[0] = fall-through (then), Successor[1] = branch target (else)
    lea r8, regionScratch
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRSTRUCTREGION
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi

    ; Find successor BB indices
    lea r8, [r14 + 40]              ; successors array
    mov r9, QWORD PTR [r8]          ; successor[0] address (then)
    mov r10, QWORD PTR [r8 + 8]     ; successor[1] address (else)

    ; Find then-BB index
    mov [rsp + 60h], r9
    mov [rsp + 68h], r10
    xor edx, edx
@@scf_find_then_bb:
    cmp edx, r12d
    jge @@scf_if_no_then
    push rdx
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    call DynArray_Get
    pop rdx
    test rax, rax
    jz @@scf_find_then_next
    mov r9, [rsp + 60h]
    cmp [rax].RAWRBASICBLOCK.startAddress, r9
    je @@scf_found_then
@@scf_find_then_next:
    inc edx
    jmp @@scf_find_then_bb
@@scf_found_then:
    mov [rsp + 70h], edx            ; then BB index
    jmp @@scf_find_else_bb
@@scf_if_no_then:
    mov DWORD PTR [rsp + 70h], -1

@@scf_find_else_bb:
    xor edx, edx
@@scf_find_else_loop:
    cmp edx, r12d
    jge @@scf_if_no_else
    push rdx
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    call DynArray_Get
    pop rdx
    test rax, rax
    jz @@scf_find_else_next
    mov r10, [rsp + 68h]
    cmp [rax].RAWRBASICBLOCK.startAddress, r10
    je @@scf_found_else
@@scf_find_else_next:
    inc edx
    jmp @@scf_find_else_loop
@@scf_found_else:
    mov [rsp + 78h], edx            ; else BB index
    jmp @@scf_build_if_struct
@@scf_if_no_else:
    mov DWORD PTR [rsp + 78h], -1

@@scf_build_if_struct:
    mov esi, [rsp + 50h]            ; Restore current BB
    lea r8, regionScratch

    ; Determine if this is if-then or if-then-else
    ; Check if else-BB immediately dominates/follows then-BB
    ; Simple heuristic: if then successor == else BB → if-then (no else)
    ; If both then and else have different paths → if-then-else
    mov eax, [rsp + 78h]            ; else BB index
    cmp eax, -1
    je @@scf_emit_if_then

    mov ecx, [rsp + 70h]            ; then BB index
    cmp ecx, -1
    je @@scf_emit_if_then

    ; Both branches exist — check if they merge
    ; If then-BB's successor == else-BB → if-then (else is the merge point)
    push rax
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    mov edx, [rsp + 70h + 8]       ; then BB (adjusted for push)
    call DynArray_Get
    pop rcx                         ; restore else BB index
    test rax, rax
    jz @@scf_emit_if_then_else

    cmp [rax].RAWRBASICBLOCK.successorCount, 1
    jne @@scf_emit_if_then_else
    lea r9, [rax + 40]
    mov r9, QWORD PTR [r9]          ; then-BB's single successor address

    ; Find that successor's BB index
    push rcx
    xor edx, edx
@@scf_find_merge:
    cmp edx, r12d
    jge @@scf_no_merge
    push rdx
    lea rcx, [rbx].RAWRCODEX_CTX.basicBlocks
    call DynArray_Get
    pop rdx
    test rax, rax
    jz @@scf_merge_next
    cmp [rax].RAWRBASICBLOCK.startAddress, r9
    je @@scf_merge_found
@@scf_merge_next:
    inc edx
    jmp @@scf_find_merge
@@scf_merge_found:
    pop rcx                         ; else BB index
    ; edx = then-BB's successor's BB index
    ; If edx == else BB → if-then (else is the merge point)
    cmp edx, ecx
    je @@scf_emit_if_then
    ; Otherwise it's if-then-else with merge at edx
    mov [rsp + 80h], edx            ; merge/exit BB
    jmp @@scf_emit_if_then_else

@@scf_no_merge:
    pop rcx

@@scf_emit_if_then_else:
    lea r8, regionScratch
    mov DWORD PTR [r8].RAWRSTRUCTREGION.regionType, REGION_IF_THEN_ELSE
    mov DWORD PTR [r8].RAWRSTRUCTREGION.headBB, esi
    mov eax, [rsp + 78h]
    mov DWORD PTR [r8].RAWRSTRUCTREGION.exitBB, eax  ; Merge point approximation
    mov DWORD PTR [r8].RAWRSTRUCTREGION.condVarId, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.parentRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bodyRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.depth, 0
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bbCount, 1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bbList, esi

    ; Find condition variable (last BRANCH in this BB)
    push r8
    lea rcx, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov r9d, [rcx].DYNARRAY.count
    dec r9d
@@scf_if_find_branch:
    cmp r9d, 0
    jl @@scf_if_no_branch
    push r9
    lea rcx, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov edx, r9d
    call DynArray_Get
    pop r9
    test rax, rax
    jz @@scf_if_find_branch_prev
    cmp [rax].RAWRSSAINSTR.bbIndex, esi
    jne @@scf_if_find_branch_prev
    cmp [rax].RAWRSSAINSTR.ssaOp, SSA_OP_BRANCH
    je @@scf_if_found_branch
@@scf_if_find_branch_prev:
    dec r9d
    jmp @@scf_if_find_branch
@@scf_if_found_branch:
    pop r8
    mov ecx, [rax].RAWRSSAINSTR.flagsVarId
    mov DWORD PTR [r8].RAWRSTRUCTREGION.condVarId, ecx
    jmp @@scf_if_push_region
@@scf_if_no_branch:
    pop r8

@@scf_if_push_region:
    lea rcx, [rbx].RAWRCODEX_CTX.structRegions
    lea rdx, regionScratch
    call DynArray_Push
    inc [rbx].RAWRCODEX_CTX.structNextRegion
    jmp @@scf_region_next_bb

@@scf_emit_if_then:
    lea r8, regionScratch
    mov DWORD PTR [r8].RAWRSTRUCTREGION.regionType, REGION_IF_THEN
    mov DWORD PTR [r8].RAWRSTRUCTREGION.headBB, esi
    mov eax, [rsp + 78h]
    mov DWORD PTR [r8].RAWRSTRUCTREGION.exitBB, eax
    mov DWORD PTR [r8].RAWRSTRUCTREGION.condVarId, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.parentRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bodyRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.thenRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.elseRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.depth, 0
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bbCount, 1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bbList, esi

    ; Find condition variable
    push r8
    lea rcx, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov r9d, [rcx].DYNARRAY.count
    dec r9d
@@scf_ift_find_branch:
    cmp r9d, 0
    jl @@scf_ift_no_branch
    push r9
    lea rcx, [rbx].RAWRCODEX_CTX.ssaInstrs
    mov edx, r9d
    call DynArray_Get
    pop r9
    test rax, rax
    jz @@scf_ift_find_prev
    cmp [rax].RAWRSSAINSTR.bbIndex, esi
    jne @@scf_ift_find_prev
    cmp [rax].RAWRSSAINSTR.ssaOp, SSA_OP_BRANCH
    je @@scf_ift_found_branch
@@scf_ift_find_prev:
    dec r9d
    jmp @@scf_ift_find_branch
@@scf_ift_found_branch:
    pop r8
    mov ecx, [rax].RAWRSSAINSTR.flagsVarId
    mov DWORD PTR [r8].RAWRSTRUCTREGION.condVarId, ecx
    jmp @@scf_ift_push
@@scf_ift_no_branch:
    pop r8

@@scf_ift_push:
    lea rcx, [rbx].RAWRCODEX_CTX.structRegions
    lea rdx, regionScratch
    call DynArray_Push
    inc [rbx].RAWRCODEX_CTX.structNextRegion
    jmp @@scf_region_next_bb

@@scf_region_next_bb:
    mov esi, [rsp + 50h]
    inc esi
    jmp @@scf_region_build_loop

    ; =====================================================================
    ; Phase E: Mark Irreducible Flow as GOTO
    ;
    ; Any cross edge that wasn't resolved to a structured region gets
    ; tagged as REGION_GOTO. This is the fallback for irreducible CFGs
    ; that cannot be expressed as while/if-else.
    ; =====================================================================
@@scf_phase_e:
    ; For each cross edge, check if its target BB is covered by a region
    ; If not, emit a GOTO region
    lea rax, [rbx].RAWRCODEX_CTX.cfgEdges
    mov r13d, [rax].DYNARRAY.count
    xor r14d, r14d

@@scf_goto_check:
    cmp r14d, r13d
    jge @@scf_done

    lea rcx, [rbx].RAWRCODEX_CTX.cfgEdges
    mov edx, r14d
    call DynArray_Get
    test rax, rax
    jz @@scf_goto_next

    cmp [rax].RAWRCFGEDGE.edgeType, EDGE_CROSS
    jne @@scf_goto_next

    ; Cross edge — check if target BB is already in a structured region
    mov esi, [rax].RAWRCFGEDGE.toBB
    lea rcx, [rbx].RAWRCODEX_CTX.structRegions
    mov r15d, [rcx].DYNARRAY.count
    xor edi, edi
    mov r9d, 0                      ; found = false

@@scf_goto_region_scan:
    cmp edi, r15d
    jge @@scf_goto_emit
    push rdi
    lea rcx, [rbx].RAWRCODEX_CTX.structRegions
    mov edx, edi
    call DynArray_Get
    pop rdi
    test rax, rax
    jz @@scf_goto_region_next

    ; Check if any BB in this region matches our target
    mov ecx, [rax].RAWRSTRUCTREGION.bbCount
    xor edx, edx
@@scf_goto_bb_scan:
    cmp edx, ecx
    jge @@scf_goto_region_next
    cmp DWORD PTR [rax + RAWRSTRUCTREGION.bbList + rdx*4], esi
    je @@scf_goto_found_in_region
    inc edx
    jmp @@scf_goto_bb_scan

@@scf_goto_found_in_region:
    mov r9d, 1                      ; Target is covered
    jmp @@scf_goto_next             ; Skip — already structured

@@scf_goto_region_next:
    inc edi
    jmp @@scf_goto_region_scan

@@scf_goto_emit:
    ; Target BB not in any region — emit GOTO
    test r9d, r9d
    jnz @@scf_goto_next

    lea r8, regionScratch
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRSTRUCTREGION
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi
    lea r8, regionScratch
    mov DWORD PTR [r8].RAWRSTRUCTREGION.regionType, REGION_GOTO
    mov DWORD PTR [r8].RAWRSTRUCTREGION.headBB, esi
    mov DWORD PTR [r8].RAWRSTRUCTREGION.exitBB, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.condVarId, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.thenRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.elseRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bodyRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.parentRegion, -1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bbCount, 1
    mov DWORD PTR [r8].RAWRSTRUCTREGION.bbList, esi

    lea rcx, [rbx].RAWRCODEX_CTX.structRegions
    lea rdx, regionScratch
    call DynArray_Push
    inc [rbx].RAWRCODEX_CTX.structNextRegion

@@scf_goto_next:
    inc r14d
    jmp @@scf_goto_check

@@scf_done:
    mov [rbx].RAWRCODEX_CTX.cfgStructured, 1

    ; Return number of structured regions
    lea rcx, [rbx].RAWRCODEX_CTX.structRegions
    mov eax, [rcx].DYNARRAY.count

    add rsp, 0C8h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret

@@scf_fail:
    xor eax, eax
    add rsp, 0C8h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
RawrCodex_StructureControlFlow ENDP

; =============================================================================
; RawrCodex_EmitPseudocode — Transform structured regions into C pseudocode
;
; Walks the structured region tree and emits human-readable C-like pseudocode.
; Uses type information from Phase 17 for variable annotations.
; Builds AST expression trees for infix operator rendering.
;
; Input:  RCX = pointer to RAWRCODEX_CTX (must have structuring done)
; Output: EAX = number of pseudocode lines emitted (0 on error)
;
; Results stored in ctx->pseudoLines (array of RAWRPSEUDOLINE)
;
; License gate: FEATURE_PSEUDOCODE (Government tier)
; =============================================================================
RawrCodex_EmitPseudocode PROC
    push rbx
    push rsi
    push rdi
    push r12
    push r13
    push r14
    push r15
    sub rsp, 0C8h

    test rcx, rcx
    jz @@pseudo_fail
    mov rbx, rcx

    ; License gate
    mov edx, FEATURE_PSEUDOCODE
    call RawrLicense_CheckFeature
    test eax, eax
    jz @@pseudo_fail

    ; Validate prerequisites
    cmp [rbx].RAWRCODEX_CTX.cfgStructured, 1
    jne @@pseudo_fail

    ; Clear previous pseudocode
    lea rcx, [rbx].RAWRCODEX_CTX.pseudoLines
    call DynArray_Clear
    mov [rbx].RAWRCODEX_CTX.pseudoEmitted, 0

    ; =====================================================================
    ; Step 1: Emit function header
    ; Determine return type from SSA RET instruction analysis
    ; =====================================================================

    ; Build function header line: "type sub_XXXXXXXX(params) {"
    lea rdi, pseudoLineBuf
    xor eax, eax
    mov ecx, MAX_PSEUDOCODE_LINE_LEN
    rep stosb

    ; Get entry point for function name
    mov eax, [rbx].RAWRCODEX_CTX.peEntryPointRVA
    add rax, [rbx].RAWRCODEX_CTX.peImageBase

    ; Format: "int64_t sub_XXXXXXXX()"
    lea rcx, pseudoLineBuf
    lea rdx, fmtPseudoFuncHdr
    ; Use "int64_t" as default return type
    lea r8, typeNames + 64          ; TYPE_INT64 = index 4, 16 bytes each
    mov r9d, eax                    ; Entry point address
    sub rsp, 20h                    ; Shadow space for wsprintfA
    call wsprintfA
    add rsp, 20h

    ; Build RAWRPSEUDOLINE for function header
    lea r8, pseudoScratch
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRPSEUDOLINE
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi
    lea r8, pseudoScratch
    mov DWORD PTR [r8].RAWRPSEUDOLINE.indent, 0
    mov DWORD PTR [r8].RAWRPSEUDOLINE.srcBB, 0
    mov DWORD PTR [r8].RAWRPSEUDOLINE.srcInstr, -1
    mov DWORD PTR [r8].RAWRPSEUDOLINE.regionIdx, -1
    mov DWORD PTR [r8].RAWRPSEUDOLINE.isComment, 0
    mov DWORD PTR [r8].RAWRPSEUDOLINE.lineType, 0    ; Statement

    ; Copy line text
    lea rdi, [r8].RAWRPSEUDOLINE.szLine
    lea rsi, pseudoLineBuf
    mov ecx, MAX_PSEUDOCODE_LINE_LEN
@@pseudo_copy_hdr:
    mov al, BYTE PTR [rsi]
    mov BYTE PTR [rdi], al
    test al, al
    jz @@pseudo_hdr_copied
    inc rsi
    inc rdi
    dec ecx
    jnz @@pseudo_copy_hdr
@@pseudo_hdr_copied:
    ; Compute line length
    lea rax, [r8].RAWRPSEUDOLINE.szLine
    sub rdi, rax
    mov DWORD PTR [r8].RAWRPSEUDOLINE.lineLen, edi

    lea rcx, [rbx].RAWRCODEX_CTX.pseudoLines
    lea rdx, pseudoScratch
    call DynArray_Push

    ; Emit opening brace "{"
    lea r8, pseudoScratch
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRPSEUDOLINE
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi
    lea r8, pseudoScratch
    mov BYTE PTR [r8].RAWRPSEUDOLINE.szLine, '{'
    mov BYTE PTR [r8].RAWRPSEUDOLINE.szLine + 1, 0
    mov DWORD PTR [r8].RAWRPSEUDOLINE.lineLen, 1
    mov DWORD PTR [r8].RAWRPSEUDOLINE.indent, 0
    mov DWORD PTR [r8].RAWRPSEUDOLINE.lineType, 1    ; Open brace
    mov DWORD PTR [r8].RAWRPSEUDOLINE.srcInstr, -1

    lea rcx, [rbx].RAWRCODEX_CTX.pseudoLines
    lea rdx, pseudoScratch
    call DynArray_Push

    ; =====================================================================
    ; Step 2: Walk structured regions in order and emit pseudocode
    ; =====================================================================
    lea rax, [rbx].RAWRCODEX_CTX.structRegions
    mov r12d, [rax].DYNARRAY.count  ; r12 = total regions
    xor r13d, r13d                  ; r13 = current region index
    mov r14d, 1                     ; r14 = current indent level

@@pseudo_region_loop:
    cmp r13d, r12d
    jge @@pseudo_emit_closing

    lea rcx, [rbx].RAWRCODEX_CTX.structRegions
    mov edx, r13d
    call DynArray_Get
    test rax, rax
    jz @@pseudo_region_next
    mov r15, rax                    ; r15 = ptr to RAWRSTRUCTREGION

    mov eax, [r15].RAWRSTRUCTREGION.regionType

    cmp eax, REGION_WHILE_LOOP
    je @@pseudo_emit_while
    cmp eax, REGION_DO_WHILE
    je @@pseudo_emit_do_while
    cmp eax, REGION_IF_THEN
    je @@pseudo_emit_if_then
    cmp eax, REGION_IF_THEN_ELSE
    je @@pseudo_emit_if_then_else
    cmp eax, REGION_RETURN
    je @@pseudo_emit_return
    cmp eax, REGION_GOTO
    je @@pseudo_emit_goto
    cmp eax, REGION_SEQUENCE
    je @@pseudo_emit_sequence
    jmp @@pseudo_region_next

    ; -----------------------------------------------------------------
    ; Emit: while (condition) {
    ; -----------------------------------------------------------------
@@pseudo_emit_while:
    ; Build condition string from condVarId
    lea rdi, pseudoLineBuf
    xor eax, eax
    mov ecx, MAX_PSEUDOCODE_LINE_LEN
    rep stosb

    mov eax, [r15].RAWRSTRUCTREGION.condVarId
    cmp eax, -1
    je @@pseudo_while_no_cond

    ; Format: "while (v%d != 0)"
    lea rcx, pseudoLineBuf
    lea rdx, fmtPseudoWhile
    ; Build condition expression: "v%d != 0"
    lea r8, pseudoExprBuf
    push rax
    lea rcx, pseudoExprBuf
    lea rdx, fmtSSAVarTemp
    pop r8                          ; r8d = condVarId as temp variable
    sub rsp, 20h
    call wsprintfA
    add rsp, 20h
    ; Now format "while (t%d)"
    lea rcx, pseudoLineBuf
    lea rdx, fmtPseudoWhile
    lea r8, pseudoExprBuf
    sub rsp, 20h
    call wsprintfA
    add rsp, 20h
    jmp @@pseudo_while_emit_line

@@pseudo_while_no_cond:
    ; while (1) — infinite loop
    lea rcx, pseudoLineBuf
    mov BYTE PTR [rcx], 'w'
    mov BYTE PTR [rcx+1], 'h'
    mov BYTE PTR [rcx+2], 'i'
    mov BYTE PTR [rcx+3], 'l'
    mov BYTE PTR [rcx+4], 'e'
    mov BYTE PTR [rcx+5], ' '
    mov BYTE PTR [rcx+6], '('
    mov BYTE PTR [rcx+7], '1'
    mov BYTE PTR [rcx+8], ')'
    mov BYTE PTR [rcx+9], 0

@@pseudo_while_emit_line:
    ; Emit the while line
    lea r8, pseudoScratch
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRPSEUDOLINE
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi
    lea r8, pseudoScratch
    mov DWORD PTR [r8].RAWRPSEUDOLINE.indent, r14d
    mov eax, [r15].RAWRSTRUCTREGION.headBB
    mov DWORD PTR [r8].RAWRPSEUDOLINE.srcBB, eax
    mov DWORD PTR [r8].RAWRPSEUDOLINE.srcInstr, -1
    mov DWORD PTR [r8].RAWRPSEUDOLINE.regionIdx, r13d
    mov DWORD PTR [r8].RAWRPSEUDOLINE.isComment, 0
    mov DWORD PTR [r8].RAWRPSEUDOLINE.lineType, 0

    ; Copy line text
    lea rdi, [r8].RAWRPSEUDOLINE.szLine
    lea rsi, pseudoLineBuf
    mov ecx, MAX_PSEUDOCODE_LINE_LEN
@@pseudo_while_copy:
    mov al, BYTE PTR [rsi]
    mov BYTE PTR [rdi], al
    test al, al
    jz @@pseudo_while_copied
    inc rsi
    inc rdi
    dec ecx
    jnz @@pseudo_while_copy
@@pseudo_while_copied:
    lea rax, [r8].RAWRPSEUDOLINE.szLine
    sub rdi, rax
    mov DWORD PTR [r8].RAWRPSEUDOLINE.lineLen, edi

    lea rcx, [rbx].RAWRCODEX_CTX.pseudoLines
    lea rdx, pseudoScratch
    call DynArray_Push

    ; Emit opening brace at current indent
    lea r8, pseudoScratch
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRPSEUDOLINE
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi
    lea r8, pseudoScratch
    mov BYTE PTR [r8].RAWRPSEUDOLINE.szLine, '{'
    mov BYTE PTR [r8].RAWRPSEUDOLINE.szLine + 1, 0
    mov DWORD PTR [r8].RAWRPSEUDOLINE.lineLen, 1
    mov DWORD PTR [r8].RAWRPSEUDOLINE.indent, r14d
    mov DWORD PTR [r8].RAWRPSEUDOLINE.lineType, 1
    mov DWORD PTR [r8].RAWRPSEUDOLINE.srcInstr, -1

    lea rcx, [rbx].RAWRCODEX_CTX.pseudoLines
    lea rdx, pseudoScratch
    call DynArray_Push

    ; Emit SSA instructions for loop body BBs
    inc r14d                        ; Increase indent for body
    mov ecx, [r15].RAWRSTRUCTREGION.bbCount
    xor esi, esi

@@pseudo_while_body:
    cmp esi, ecx
    jge @@pseudo_while_close
    mov [rsp + 50h], ecx
    mov [rsp + 54h], esi

    mov eax, DWORD PTR [r15 + RAWRSTRUCTREGION.bbList + rsi*4]
    mov [rsp + 58h], eax            ; Current BB index

    ; Emit SSA instructions for this BB
    call @@pseudo_emit_bb_instrs

    mov ecx, [rsp + 50h]
    mov esi, [rsp + 54h]
    inc esi
    jmp @@pseudo_while_body

@@pseudo_while_close:
    dec r14d                        ; Restore indent
    ; Emit closing brace
    lea r8, pseudoScratch
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRPSEUDOLINE
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi
    lea r8, pseudoScratch
    mov BYTE PTR [r8].RAWRPSEUDOLINE.szLine, '}'
    mov BYTE PTR [r8].RAWRPSEUDOLINE.szLine + 1, 0
    mov DWORD PTR [r8].RAWRPSEUDOLINE.lineLen, 1
    mov DWORD PTR [r8].RAWRPSEUDOLINE.indent, r14d
    mov DWORD PTR [r8].RAWRPSEUDOLINE.lineType, 2
    mov DWORD PTR [r8].RAWRPSEUDOLINE.srcInstr, -1

    lea rcx, [rbx].RAWRCODEX_CTX.pseudoLines
    lea rdx, pseudoScratch
    call DynArray_Push
    jmp @@pseudo_region_next

    ; -----------------------------------------------------------------
    ; Emit: do { ... } while (condition);
    ; -----------------------------------------------------------------
@@pseudo_emit_do_while:
    ; Emit "do"
    lea r8, pseudoScratch
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRPSEUDOLINE
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi
    lea r8, pseudoScratch
    mov BYTE PTR [r8].RAWRPSEUDOLINE.szLine, 'd'
    mov BYTE PTR [r8].RAWRPSEUDOLINE.szLine + 1, 'o'
    mov BYTE PTR [r8].RAWRPSEUDOLINE.szLine + 2, 0
    mov DWORD PTR [r8].RAWRPSEUDOLINE.lineLen, 2
    mov DWORD PTR [r8].RAWRPSEUDOLINE.indent, r14d
    mov DWORD PTR [r8].RAWRPSEUDOLINE.lineType, 0
