    cmp r9d, SSA_OP_TEST
    je @@pseudo_bb_instr_next       ; TEST produces flags, not a statement
    cmp r9d, SSA_OP_UNKNOWN
    je @@pseudo_bb_instr_next       ; Skip unknown ops

    ; Binary/unary operation: "v%d = v%d OP v%d;"
    jmp @@pseudo_bb_binop

@@pseudo_bb_assign:
    ; "v%d = v%d;"
    mov rax, [rsp + 98h]
    lea rcx, pseudoLineBuf
    lea rdx, fmtPseudoAssign
    mov r8d, [rax].RAWRSSAINSTR.dstVarId
    ; Build expression for src: just "v%d" for simple assign
    lea rcx, pseudoExprBuf
    lea rdx, fmtSSAVarTemp
    mov r8d, [rax].RAWRSSAINSTR.src1VarId
    sub rsp, 20h
    call wsprintfA
    add rsp, 20h
    mov rax, [rsp + 98h]
    lea rcx, pseudoLineBuf
    lea rdx, fmtPseudoAssign
    mov r8d, [rax].RAWRSSAINSTR.dstVarId
    lea r9, pseudoExprBuf
    sub rsp, 20h
    call wsprintfA
    add rsp, 20h
    jmp @@pseudo_bb_emit_line

@@pseudo_bb_call:
    ; "v%d = sub_XXXXXXXX();"
    mov rax, [rsp + 98h]
    lea rcx, pseudoLineBuf
    lea rdx, fmtPseudoCall
    mov r8d, [rax].RAWRSSAINSTR.dstVarId
    mov r9d, DWORD PTR [rax].RAWRSSAINSTR.callTarget  ; Low 32 bits
    sub rsp, 20h
    call wsprintfA
    add rsp, 20h
    jmp @@pseudo_bb_emit_line

@@pseudo_bb_ret:
    ; "return v%d;"
    mov rax, [rsp + 98h]
    mov r8d, [rax].RAWRSSAINSTR.src1VarId
    cmp r8d, -1
    je @@pseudo_bb_ret_void
    lea rcx, pseudoLineBuf
    lea rdx, fmtPseudoReturn
    sub rsp, 20h
    call wsprintfA
    add rsp, 20h
    jmp @@pseudo_bb_emit_line
@@pseudo_bb_ret_void:
    lea rcx, pseudoLineBuf
    lea rdx, fmtPseudoRetVoid
    sub rsp, 20h
    call wsprintfA
    add rsp, 20h
    jmp @@pseudo_bb_emit_line

@@pseudo_bb_store:
    ; "*v%d = v%d;"
    mov rax, [rsp + 98h]
    lea rcx, pseudoLineBuf
    lea rdx, fmtPseudoStore
    mov r8d, [rax].RAWRSSAINSTR.dstVarId
    mov r9d, [rax].RAWRSSAINSTR.src1VarId
    sub rsp, 20h
    call wsprintfA
    add rsp, 20h
    jmp @@pseudo_bb_emit_line

@@pseudo_bb_load:
    ; "v%d = *v%d;"
    mov rax, [rsp + 98h]
    lea rcx, pseudoLineBuf
    lea rdx, fmtPseudoLoad
    mov r8d, [rax].RAWRSSAINSTR.dstVarId
    mov r9d, [rax].RAWRSSAINSTR.src1VarId
    sub rsp, 20h
    call wsprintfA
    add rsp, 20h
    jmp @@pseudo_bb_emit_line

@@pseudo_bb_binop:
    ; "v%d = v%d OP v%d;"
    ; Get C operator string
    mov rax, [rsp + 98h]
    mov r9d, [rax].RAWRSSAINSTR.ssaOp
    cmp r9d, 12                     ; Ensure within range of ssaOpToC table
    ja @@pseudo_bb_instr_next       ; Out of range — skip

    ; Format: "v%d = v%d + v%d;"
    ; Use wsprintfA with SSA instruction format
    lea rcx, pseudoLineBuf
    lea rdx, fmtSSAInstr
    mov r8d, [rax].RAWRSSAINSTR.dstVarId
    ; Get operator name from ssaOpNames
    mov eax, r9d
    shl eax, 3                      ; * 8 bytes per entry
    lea r9, ssaOpNames
    add r9, rax                     ; r9 -> operator name
    mov rax, [rsp + 98h]
    ; Need to push extra params for %d, %d after the string
    mov ecx, [rax].RAWRSSAINSTR.src2VarId
    push rcx                        ; 6th param: src2 var id
    mov ecx, [rax].RAWRSSAINSTR.src1VarId
    push rcx                        ; 5th param: src1 var id
    lea rcx, pseudoLineBuf
    lea rdx, fmtSSAInstr
    mov r8d, [rax].RAWRSSAINSTR.dstVarId
    sub rsp, 20h
    call wsprintfA
    add rsp, 20h + 10h             ; Clean shadow + 2 pushed params

    ; Append semicolon
    lea rcx, pseudoLineBuf
    call lstrlenA
    lea rcx, pseudoLineBuf
    mov BYTE PTR [rcx + rax], ';'
    mov BYTE PTR [rcx + rax + 1], 0
    jmp @@pseudo_bb_emit_line

@@pseudo_bb_emit_line:
    ; Build and push pseudocode line
    lea r8, pseudoScratch
    push rdi
    push rcx
    mov rdi, r8
    mov ecx, SIZEOF RAWRPSEUDOLINE
    xor eax, eax
    rep stosb
    pop rcx
    pop rdi
    lea r8, pseudoScratch
    mov DWORD PTR [r8].RAWRPSEUDOLINE.indent, r14d
    mov eax, [rsp + 58h]
    mov DWORD PTR [r8].RAWRPSEUDOLINE.srcBB, eax
    mov eax, [rsp + 94h]
    mov DWORD PTR [r8].RAWRPSEUDOLINE.srcInstr, eax
    mov DWORD PTR [r8].RAWRPSEUDOLINE.lineType, 0
    mov DWORD PTR [r8].RAWRPSEUDOLINE.isComment, 0

    ; Copy pseudoLineBuf into szLine
    lea rdi, [r8].RAWRPSEUDOLINE.szLine
    lea rsi, pseudoLineBuf
    mov ecx, MAX_PSEUDOCODE_LINE_LEN
@@pseudo_bb_copy:
    mov al, [rsi]
    mov [rdi], al
    test al, al
    jz @@pseudo_bb_copied
    inc rsi
    inc rdi
    dec ecx
    jnz @@pseudo_bb_copy
@@pseudo_bb_copied:
    lea rax, [r8].RAWRPSEUDOLINE.szLine
    sub rdi, rax
    mov DWORD PTR [r8].RAWRPSEUDOLINE.lineLen, edi

    lea rcx, [rbx].RAWRCODEX_CTX.pseudoLines
    lea rdx, pseudoScratch
    call DynArray_Push

@@pseudo_bb_instr_next:
    mov esi, [rsp + 94h]
    inc esi
    jmp @@pseudo_bb_instr_loop

@@pseudo_bb_done:
    ret

@@pseudo_fail:
    xor eax, eax
    add rsp, 0C8h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
RawrCodex_EmitPseudocode ENDP

; =============================================================================
; RawrLicense_CheckFeature - Check if a feature is enabled in the license
;
; Input:  RCX = pointer to RAWRCODEX_CTX
;         EDX = feature bit number (FEATURE_* constant)
; Output: EAX = 1 if feature is allowed, 0 if denied
;
; License enforcement is air-gap compatible: no network calls.
; The feature mask is validated at context creation from the license key.
; =============================================================================
RawrLicense_CheckFeature PROC
    test rcx, rcx
    jz @@license_deny

    ; Load feature mask from license context
    mov rax, [rcx].RAWRCODEX_CTX.license.featureMask

    ; Check if license is valid at all
    cmp [rcx].RAWRCODEX_CTX.license.isValid, 1
    jne @@license_deny

    ; Test the requested feature bit
    bt rax, rdx
    jnc @@license_deny

    mov eax, 1
    ret

@@license_deny:
    xor eax, eax
    ret
RawrLicense_CheckFeature ENDP

; =============================================================================
; RawrLicense_SetTier - Set the license tier and feature mask
;
; Input:  RCX = pointer to RAWRCODEX_CTX
;         EDX = tier (0=Community, 1=Pro, 2=Enterprise, 3=Government)
; Output: EAX = 1 on success, 0 on invalid tier
;
; This is called during initialization or when a license key is loaded.
; In production, the tier would be derived from RSA-4096 signed license key.
; =============================================================================
RawrLicense_SetTier PROC
    test rcx, rcx
    jz @@tier_fail

    cmp edx, 0
    je @@tier_community
    cmp edx, 1
    je @@tier_pro
    cmp edx, 2
    je @@tier_enterprise
    cmp edx, 3
    je @@tier_government
    jmp @@tier_fail

@@tier_community:
    mov [rcx].RAWRCODEX_CTX.license.featureMask, FEATURE_LICENSE_MASK_COMMUNITY
    mov [rcx].RAWRCODEX_CTX.license.tier, 0
    jmp @@tier_ok

@@tier_pro:
    mov [rcx].RAWRCODEX_CTX.license.featureMask, FEATURE_LICENSE_MASK_PRO
    mov [rcx].RAWRCODEX_CTX.license.tier, 1
    jmp @@tier_ok

@@tier_enterprise:
    mov [rcx].RAWRCODEX_CTX.license.featureMask, FEATURE_LICENSE_MASK_ENTERPRISE
    mov [rcx].RAWRCODEX_CTX.license.tier, 2
    jmp @@tier_ok

@@tier_government:
    mov [rcx].RAWRCODEX_CTX.license.featureMask, FEATURE_LICENSE_MASK_GOVERNMENT
    mov [rcx].RAWRCODEX_CTX.license.tier, 3

@@tier_ok:
    mov [rcx].RAWRCODEX_CTX.license.isValid, 1
    mov [rcx].RAWRCODEX_CTX.license.isAirgapped, 1
    mov eax, 1
    ret

@@tier_fail:
    xor eax, eax
    ret
RawrLicense_SetTier ENDP

END
 ; =============================================================================
; RawrXD_AgenticOrchestrator.asm — Central Agentic Dispatch Kernel
; =============================================================================
;
; The central nervous system wiring all 23 enterprise handlers to real
; subsystem implementations via a lock-free task queue and VTable dispatch.
; Replaces the C++ stub layer with sub-microsecond MASM dispatch.
;
; Capabilities:
;   - VTable-based dispatch for 23 handler opcodes (7001–9700)
;   - Lock-free SPSC task queue (1024 entries, 64-byte cache-line aligned)
;   - Telemetry ring integration (fire-and-forget event posting)
;   - Atomic metrics counters (dispatches, latency, errors per handler)
;   - Opcode → VTable index mapping with gap-aware lookup table
;   - Pre/Post dispatch hooks for observability pipeline
;   - NUMA-aware task pool allocation via VirtualAllocExNuma
;
; Active Exports (used by C++ CommandRegistry bridge):
;   asm_orchestrator_init           — Initialize subsystem VTable + task queue
;   asm_orchestrator_dispatch       — Dispatch opcode to subsystem handler
;   asm_orchestrator_shutdown       — Drain queue, release resources
;   asm_orchestrator_get_metrics    — Read atomic dispatch counters
;   asm_orchestrator_register_hook  — Register pre/post dispatch callback
;   asm_orchestrator_set_vtable     — Hot-swap a VTable slot (runtime binding)
;   asm_orchestrator_queue_async    — Enqueue async task to SPSC ring
;   asm_orchestrator_drain_queue    — Process all pending async tasks
;
; Architecture: x64 MASM64 | Windows x64 ABI | No CRT | No exceptions
; Build: ml64.exe /c /Zi /Zd /Fo RawrXD_AgenticOrchestrator.obj
; Rule: NO SOURCE FILE IS TO BE SIMPLIFIED
; =============================================================================

INCLUDE RawrXD_Common.inc

option casemap:none

; =============================================================================
;                    ORCHESTRATOR CONSTANTS
; =============================================================================

; Handler opcode ranges (must match command_registry.hpp COMMAND_TABLE)
OP_UNREAL_INIT          EQU     7001
OP_UNREAL_ATTACH        EQU     7002
OP_UNITY_INIT           EQU     7003
OP_UNITY_ATTACH         EQU     7004
OP_REVENG_DISASM        EQU     8100
OP_REVENG_DECOMP        EQU     8101
OP_REVENG_VULN          EQU     8102
OP_MODEL_LIST           EQU     9001
OP_MODEL_LOAD           EQU     9002
OP_MODEL_UNLOAD         EQU     9003
OP_MODEL_QUANTIZE       EQU     9004
OP_MODEL_FINETUNE       EQU     9005
OP_DISK_LIST            EQU     9200
OP_DISK_SCAN            EQU     9201
OP_GOVERNOR_STATUS      EQU     9300
OP_GOVERNOR_POWER       EQU     9301
OP_MARKET_LIST          EQU     9400
OP_MARKET_INSTALL       EQU     9401
OP_EMBED_ENCODE         EQU     9500
OP_VISION_ANALYZE       EQU     9600
OP_PROMPT_CLASSIFY      EQU     9700
OP_LSP_AI_SYNC          EQU     9800        ; v14.2.1: SymbolIndex↔ContextAnalyzer bridge
OP_HEALTH_CHECK         EQU     9900        ; v14.2.1: Full-stack health diagnostics

; VTable geometry
VTABLE_SLOT_COUNT       EQU     23          ; 23 handler slots
VTABLE_SIZE_BYTES       EQU     VTABLE_SLOT_COUNT * 8

; Task queue geometry (SPSC ring buffer)
TASK_QUEUE_CAPACITY     EQU     1024
TASK_QUEUE_MASK         EQU     TASK_QUEUE_CAPACITY - 1
TASK_ENTRY_SIZE         EQU     64          ; Cache-line aligned

; Hook types
HOOK_PRE_DISPATCH       EQU     0
HOOK_POST_DISPATCH      EQU     1
MAX_HOOKS               EQU     16

; Orchestrator status
ORCH_OK                 EQU     0
ORCH_ERR_NOT_INIT       EQU     1
ORCH_ERR_INVALID_OP     EQU     2
ORCH_ERR_NOT_IMPL       EQU     3
ORCH_ERR_QUEUE_FULL     EQU     4
ORCH_ERR_ALLOC          EQU     5
ORCH_ERR_ALREADY_INIT   EQU     6
ORCH_ERR_VPROTECT       EQU     7

; Telemetry event IDs
TELEM_ORCH_INIT         EQU     1000h
TELEM_ORCH_DISPATCH     EQU     2000h
TELEM_ORCH_SHUTDOWN     EQU     3000h
TELEM_ORCH_ERROR        EQU     4000h

; =============================================================================
;                    STRUCTURES
; =============================================================================

; Opcode-to-index lookup entry
OPCODE_MAP_ENTRY STRUCT
    opcode          DD      ?               ; Command ID (7001, 8100, etc.)
    vtable_index    DD      ?               ; Index into g_vtable [0..22]
OPCODE_MAP_ENTRY ENDS

; Async task entry (64 bytes = 1 cache line)
TASK_ENTRY STRUCT 8
    opcode          DD      ?               ; Command ID
    flags           DD      ?               ; Priority, cancellable, etc.
    context_ptr     DQ      ?               ; CommandContext*
    result_ptr      DQ      ?               ; CommandResult*
    callback_ptr    DQ      ?               ; Completion callback
    timestamp       DQ      ?               ; QPC enqueue time
    user_data       DQ      ?               ; Opaque caller data
    _pad0           DQ      ?               ; Pad to 64 bytes
TASK_ENTRY ENDS

; Per-handler metrics
HANDLER_METRICS STRUCT
    dispatch_count  DQ      ?               ; Total dispatches
    error_count     DQ      ?               ; Total errors
    total_cycles    DQ      ?               ; Accumulated RDTSC cycles
    min_cycles      DQ      ?               ; Fastest dispatch
    max_cycles      DQ      ?               ; Slowest dispatch
    last_status     DD      ?               ; Last HRESULT
    _pad0           DD      ?
HANDLER_METRICS ENDS

; Dispatch hook entry
HOOK_ENTRY STRUCT
    hook_type       DD      ?               ; PRE or POST
    _pad0           DD      ?
    callback_ptr    DQ      ?               ; void (*hook)(opcode, ctx, result)
HOOK_ENTRY ENDS

; Orchestrator global context
ORCH_CONTEXT STRUCT
    initialized     DD      ?
    shutting_down    DD      ?
    vtable_ptr      DQ      ?               ; -> g_vtable
    queue_ptr       DQ      ?               ; -> g_task_queue
    queue_head      DD      ?               ; Producer index (atomic)
    queue_tail      DD      ?               ; Consumer index (atomic)
    metrics_ptr     DQ      ?               ; -> g_handler_metrics
    hooks_ptr       DQ      ?               ; -> g_hooks
    hook_count      DD      ?
    _pad0           DD      ?
    telem_ring      DQ      ?               ; Telemetry ring buffer (optional)
    total_dispatches DQ     ?               ; Global counter
    total_errors    DQ      ?
    total_async     DQ      ?
ORCH_CONTEXT ENDS

; =============================================================================
;                    DATA SECTION
; =============================================================================
.data

; === Orchestrator context ===
ALIGN 16
g_orch_ctx      ORCH_CONTEXT <>

; === VTable: 23 function pointers (subsystem handlers) ===
ALIGN 16
g_vtable        DQ      VTABLE_SLOT_COUNT DUP(0)

; === Opcode-to-index lookup table (23 entries) ===
ALIGN 16
g_opcode_map    OPCODE_MAP_ENTRY <7001,  0>     ; Unreal Init
                OPCODE_MAP_ENTRY <7002,  1>     ; Unreal Attach
                OPCODE_MAP_ENTRY <7003,  2>     ; Unity Init
                OPCODE_MAP_ENTRY <7004,  3>     ; Unity Attach
                OPCODE_MAP_ENTRY <8100,  4>     ; Reveng Disasm
                OPCODE_MAP_ENTRY <8101,  5>     ; Reveng Decomp
                OPCODE_MAP_ENTRY <8102,  6>     ; Reveng VulnScan
                OPCODE_MAP_ENTRY <9001,  7>     ; Model List
                OPCODE_MAP_ENTRY <9002,  8>     ; Model Load
                OPCODE_MAP_ENTRY <9003,  9>     ; Model Unload
                OPCODE_MAP_ENTRY <9004, 10>     ; Model Quantize
                OPCODE_MAP_ENTRY <9005, 11>     ; Model Finetune
                OPCODE_MAP_ENTRY <9200, 12>     ; Disk List
                OPCODE_MAP_ENTRY <9201, 13>     ; Disk Scan
                OPCODE_MAP_ENTRY <9300, 14>     ; Governor Status
                OPCODE_MAP_ENTRY <9301, 15>     ; Governor SetPower
                OPCODE_MAP_ENTRY <9400, 16>     ; Market List
                OPCODE_MAP_ENTRY <9401, 17>     ; Market Install
                OPCODE_MAP_ENTRY <9500, 18>     ; Embed Encode
                OPCODE_MAP_ENTRY <9600, 19>     ; Vision Analyze
                OPCODE_MAP_ENTRY <9700, 20>     ; Prompt Classify
                OPCODE_MAP_ENTRY <9800, 21>     ; LSP AI Sync (v14.2.1)
                OPCODE_MAP_ENTRY <9900, 22>     ; Health Check (v14.2.1)
g_opcode_count  DD      23                      ; Valid entries (v14.2.1: was 21)

; === Per-handler metrics array ===
ALIGN 16
g_handler_metrics HANDLER_METRICS VTABLE_SLOT_COUNT DUP(<>)

; === Hooks array ===
ALIGN 16
g_hooks         HOOK_ENTRY MAX_HOOKS DUP(<>)

; === SPSC task queue ring buffer (allocated dynamically) ===
g_task_queue    DQ      0

; === Critical section for non-atomic operations ===
ALIGN 16
g_orch_cs       CRITICAL_SECTION <>

; === Status strings ===
szOrchInit      DB "AgenticOrchestrator: subsystem initialized", 0
szOrchShutdown  DB "AgenticOrchestrator: shutdown complete", 0
szOrchDispatch  DB "AgenticOrchestrator: dispatch ", 0
szOrchError     DB "AgenticOrchestrator: dispatch error", 0
szOrchNotImpl   DB "AgenticOrchestrator: handler not implemented", 0
szOrchQueueFull DB "AgenticOrchestrator: async queue full", 0

; =============================================================================
;                    EXPORTS
; =============================================================================
PUBLIC asm_orchestrator_init
PUBLIC asm_orchestrator_dispatch
PUBLIC asm_orchestrator_shutdown
PUBLIC asm_orchestrator_get_metrics
PUBLIC asm_orchestrator_register_hook
PUBLIC asm_orchestrator_set_vtable
PUBLIC asm_orchestrator_queue_async
PUBLIC asm_orchestrator_drain_queue
PUBLIC asm_orchestrator_lsp_sync

; =============================================================================
;                    EXTERNAL IMPORTS
; =============================================================================
EXTERN QueryPerformanceCounter: PROC
EXTERN GetCurrentProcessorNumber: PROC

; =============================================================================
;                    CODE SECTION
; =============================================================================
.code

; =============================================================================
; map_opcode_to_index — Internal: linear scan of opcode lookup table
; ECX = opcode
; Returns: EAX = vtable index, or -1 if not found
; =============================================================================
map_opcode_to_index PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    sub     rsp, 8
    .allocstack 8
    .endprolog

    mov     ebx, ecx                        ; opcode to find
    lea     rsi, g_opcode_map
    mov     ecx, DWORD PTR [g_opcode_count]
    xor     eax, eax                        ; i = 0

@@scan_loop:
    cmp     eax, ecx
    jge     @@not_found
    cmp     DWORD PTR [rsi].OPCODE_MAP_ENTRY.opcode, ebx
    je      @@found
    add     rsi, SIZEOF OPCODE_MAP_ENTRY
    inc     eax
    jmp     @@scan_loop

@@found:
    mov     eax, DWORD PTR [rsi].OPCODE_MAP_ENTRY.vtable_index
    jmp     @@exit

@@not_found:
    mov     eax, -1

@@exit:
    add     rsp, 8
    pop     rsi
    pop     rbx
    ret
map_opcode_to_index ENDP

; =============================================================================
; fire_hooks — Internal: invoke all hooks of a given type
; ECX = hook_type (HOOK_PRE_DISPATCH or HOOK_POST_DISPATCH)
; RDX = opcode (in low 32 bits)
; R8  = CommandContext*
; R9  = CommandResult*
; =============================================================================
fire_hooks PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    sub     rsp, 48
    .allocstack 48
    .endprolog

    mov     ebx, ecx                        ; hook_type
    mov     r12d, edx                       ; opcode
    mov     r13, r8                         ; context
    mov     r14, r9                         ; result

    lea     rsi, g_hooks
    mov     edi, DWORD PTR [g_orch_ctx.hook_count]
    xor     ecx, ecx                        ; i = 0

@@hook_loop:
    cmp     ecx, edi
    jge     @@hook_done
    cmp     DWORD PTR [rsi].HOOK_ENTRY.hook_type, ebx
    jne     @@hook_next

    ; Found matching hook — invoke it
    mov     rax, QWORD PTR [rsi].HOOK_ENTRY.callback_ptr
    test    rax, rax
    jz      @@hook_next

    ; Call hook(opcode, context, result)
    push    rcx                             ; Save loop counter
    mov     ecx, r12d                       ; Arg 1: opcode
    mov     rdx, r13                        ; Arg 2: context
    mov     r8, r14                         ; Arg 3: result
    call    rax
    pop     rcx

@@hook_next:
    add     rsi, SIZEOF HOOK_ENTRY
    inc     ecx
    jmp     @@hook_loop

@@hook_done:
    add     rsp, 48
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
fire_hooks ENDP

; =============================================================================
; asm_orchestrator_init
; Initialize the Agentic Orchestrator: VTable, task queue, metrics, hooks.
; RCX = Telemetry ring pointer (optional, 0 to skip)
; Returns: RAX = 0 success, ORCH_ERR_* on failure
; =============================================================================
asm_orchestrator_init PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    sub     rsp, 48
    .allocstack 48
    .endprolog

    mov     r12, rcx                        ; Telemetry ring

    ; Check double-init
    cmp     DWORD PTR [g_orch_ctx.initialized], 1
    je      @@already_init

    ; Initialize critical section
    lea     rcx, g_orch_cs
    call    InitializeCriticalSection

    ; Zero metrics array
    lea     rdi, g_handler_metrics
    xor     eax, eax
    mov     ecx, VTABLE_SLOT_COUNT * (SIZEOF HANDLER_METRICS)
    rep     stosb

    ; Initialize min_cycles to max value
    lea     rsi, g_handler_metrics
    mov     ecx, VTABLE_SLOT_COUNT
@@init_min_loop:
    mov     QWORD PTR [rsi].HANDLER_METRICS.min_cycles, 0FFFFFFFFFFFFFFFFh
    add     rsi, SIZEOF HANDLER_METRICS
    dec     ecx
    jnz     @@init_min_loop

    ; Zero hooks
    lea     rdi, g_hooks
    xor     eax, eax
    mov     ecx, MAX_HOOKS * (SIZEOF HOOK_ENTRY)
    rep     stosb
    mov     DWORD PTR [g_orch_ctx.hook_count], 0

    ; Allocate SPSC task queue: 1024 * 64 = 64KB, page-aligned
    xor     ecx, ecx                        ; lpAddress = NULL
    mov     edx, TASK_QUEUE_CAPACITY * TASK_ENTRY_SIZE
    mov     r8d, MEM_COMMIT OR MEM_RESERVE
    mov     r9d, PAGE_READWRITE
    call    VirtualAlloc
    test    rax, rax
    jz      @@alloc_fail
    mov     QWORD PTR [g_task_queue], rax

    ; Zero the queue
    mov     rdi, rax
    xor     eax, eax
    mov     ecx, TASK_QUEUE_CAPACITY * TASK_ENTRY_SIZE
    rep     stosb

    ; Populate context
    lea     rax, g_vtable
    mov     QWORD PTR [g_orch_ctx.vtable_ptr], rax
    mov     rax, QWORD PTR [g_task_queue]
    mov     QWORD PTR [g_orch_ctx.queue_ptr], rax
    mov     DWORD PTR [g_orch_ctx.queue_head], 0
    mov     DWORD PTR [g_orch_ctx.queue_tail], 0
    lea     rax, g_handler_metrics
    mov     QWORD PTR [g_orch_ctx.metrics_ptr], rax
    lea     rax, g_hooks
    mov     QWORD PTR [g_orch_ctx.hooks_ptr], rax
    mov     QWORD PTR [g_orch_ctx.telem_ring], r12
    mov     QWORD PTR [g_orch_ctx.total_dispatches], 0
    mov     QWORD PTR [g_orch_ctx.total_errors], 0
    mov     QWORD PTR [g_orch_ctx.total_async], 0
    mov     DWORD PTR [g_orch_ctx.shutting_down], 0

    ; Mark initialized (must be last)
    mov     DWORD PTR [g_orch_ctx.initialized], 1

    ; Debug trace
    lea     rcx, szOrchInit
    call    OutputDebugStringA

    xor     eax, eax                        ; SUCCESS
    jmp     @@exit

@@already_init:
    mov     eax, ORCH_ERR_ALREADY_INIT
    jmp     @@exit

@@alloc_fail:
    mov     eax, ORCH_ERR_ALLOC

@@exit:
    add     rsp, 48
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
asm_orchestrator_init ENDP

; =============================================================================
; asm_orchestrator_dispatch
; Synchronous dispatch: opcode → VTable lookup → handler call → metrics.
; ECX = opcode (7001–9700)
; RDX = CommandContext*
; R8  = CommandResult*
; Returns: RAX = handler HRESULT, or ORCH_ERR_* if dispatch fails
; =============================================================================
asm_orchestrator_dispatch PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 56
    .allocstack 56
    .endprolog

    ; Check initialized
    cmp     DWORD PTR [g_orch_ctx.initialized], 1
    jne     @@not_init

    mov     r12d, ecx                       ; opcode
    mov     r13, rdx                        ; CommandContext*
    mov     r14, r8                         ; CommandResult*

    ; ---- RDTSC start ----
    rdtsc
    shl     rdx, 32
    or      rax, rdx
    mov     r15, rax                        ; start_cycles

    ; ---- Map opcode → VTable index ----
    mov     ecx, r12d
    call    map_opcode_to_index
    cmp     eax, -1
    je      @@invalid_op
    mov     ebx, eax                        ; vtable_index

    ; ---- Load handler from VTable ----
    lea     rsi, g_vtable
    mov     rax, QWORD PTR [rsi + rbx*8]
    test    rax, rax
    jz      @@not_impl
    mov     rdi, rax                        ; handler function pointer

    ; ---- Fire pre-dispatch hooks ----
    mov     ecx, HOOK_PRE_DISPATCH
    mov     edx, r12d
    mov     r8, r13
    mov     r9, r14
    call    fire_hooks

    ; ---- Call handler(CommandContext*, CommandResult*) ----
    mov     rcx, r13                        ; Arg 1: context
    mov     rdx, r14                        ; Arg 2: result
    call    rdi
    mov     rsi, rax                        ; Save handler return value

    ; ---- Fire post-dispatch hooks ----
    push    rsi
    mov     ecx, HOOK_POST_DISPATCH
    mov     edx, r12d
    mov     r8, r13
    mov     r9, r14
    call    fire_hooks
    pop     rsi

    ; ---- RDTSC end + metrics update ----
    rdtsc
    shl     rdx, 32
    or      rax, rdx
    sub     rax, r15                        ; elapsed_cycles

    ; Load metrics slot (atomic updates)
    lea     rdi, g_handler_metrics
    imul    rcx, rbx, SIZEOF HANDLER_METRICS
    add     rdi, rcx                        ; -> metrics[vtable_index]

    lock inc QWORD PTR [rdi].HANDLER_METRICS.dispatch_count
    lock add QWORD PTR [rdi].HANDLER_METRICS.total_cycles, rax

    ; Update min_cycles (lock cmpxchg loop)
    mov     rcx, rax                        ; elapsed
@@cmpxchg_min:
    mov     rax, QWORD PTR [rdi].HANDLER_METRICS.min_cycles
    cmp     rcx, rax
    jge     @@check_max
    lock cmpxchg QWORD PTR [rdi].HANDLER_METRICS.min_cycles, rcx
    jne     @@cmpxchg_min

@@check_max:
    ; Update max_cycles (lock cmpxchg loop)
    mov     rcx, rax                        ; Use elapsed from rdtsc
    rdtsc
    shl     rdx, 32
    or      rax, rdx
    sub     rax, r15                        ; Re-read elapsed (for max)
    mov     rcx, rax
@@cmpxchg_max:
    mov     rax, QWORD PTR [rdi].HANDLER_METRICS.max_cycles
    cmp     rcx, rax
    jle     @@metrics_done
    lock cmpxchg QWORD PTR [rdi].HANDLER_METRICS.max_cycles, rcx
    jne     @@cmpxchg_max

@@metrics_done:
    mov     DWORD PTR [rdi].HANDLER_METRICS.last_status, esi

    ; Check for error (HRESULT < 0)
    test    esi, esi
    jns     @@no_error
    lock inc QWORD PTR [rdi].HANDLER_METRICS.error_count
    lock inc QWORD PTR [g_orch_ctx.total_errors]
@@no_error:
    lock inc QWORD PTR [g_orch_ctx.total_dispatches]

    mov     eax, esi                        ; Return handler HRESULT
    jmp     @@exit

@@not_init:
    mov     eax, ORCH_ERR_NOT_INIT
    jmp     @@exit

@@invalid_op:
    lea     rcx, szOrchError
    call    OutputDebugStringA
    mov     eax, ORCH_ERR_INVALID_OP
    jmp     @@exit

@@not_impl:
    lea     rcx, szOrchNotImpl
    call    OutputDebugStringA
    mov     eax, ORCH_ERR_NOT_IMPL

@@exit:
    add     rsp, 56
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
asm_orchestrator_dispatch ENDP

; =============================================================================
; asm_orchestrator_set_vtable
; Hot-swap a handler slot in the VTable for runtime subsystem binding.
; ECX = opcode (7001–9700)
; RDX = new handler function pointer
; Returns: RAX = previous handler pointer (for chaining), or 0 on error
; =============================================================================
asm_orchestrator_set_vtable PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    sub     rsp, 40
    .allocstack 40
    .endprolog

    cmp     DWORD PTR [g_orch_ctx.initialized], 1
    jne     @@err

    mov     rsi, rdx                        ; new handler

    ; Map opcode → index
    call    map_opcode_to_index
    cmp     eax, -1
    je      @@err

    ; Atomic swap
    lea     rbx, g_vtable
    mov     rcx, rsi
    xchg    QWORD PTR [rbx + rax*8], rcx
    mov     rax, rcx                        ; return old handler
    jmp     @@exit

@@err:
    xor     eax, eax

@@exit:
    add     rsp, 40
    pop     rsi
    pop     rbx
    ret
asm_orchestrator_set_vtable ENDP

; =============================================================================
; asm_orchestrator_queue_async
; Enqueue a task into the SPSC ring buffer for deferred dispatch.
; ECX = opcode
; RDX = CommandContext*
; R8  = CommandResult*
; R9  = Completion callback (void (*)(CommandResult*))
; Returns: RAX = 0 success, ORCH_ERR_QUEUE_FULL if ring is full
; =============================================================================
asm_orchestrator_queue_async PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    sub     rsp, 40
    .allocstack 40
    .endprolog

    cmp     DWORD PTR [g_orch_ctx.initialized], 1
    jne     @@not_init_async

    mov     ebx, ecx                        ; opcode
    mov     rsi, rdx                        ; context
    mov     rdi, r8                         ; result
    ; r9 = callback (already in register)

    ; Lock-free SPSC enqueue
    mov     eax, DWORD PTR [g_orch_ctx.queue_head]
@@retry:
    mov     ecx, eax
    inc     ecx
    and     ecx, TASK_QUEUE_MASK            ; wrap

    ; Check full: new_head == tail?
    cmp     ecx, DWORD PTR [g_orch_ctx.queue_tail]
    je      @@queue_full

    lock cmpxchg DWORD PTR [g_orch_ctx.queue_head], ecx
    jne     @@retry

    ; EAX = claimed slot index (pre-increment value)
    imul    rdx, rax, TASK_ENTRY_SIZE
    add     rdx, QWORD PTR [g_task_queue]   ; -> slot

    ; Write task entry
    mov     DWORD PTR [rdx].TASK_ENTRY.opcode, ebx
    mov     DWORD PTR [rdx].TASK_ENTRY.flags, 0
    mov     QWORD PTR [rdx].TASK_ENTRY.context_ptr, rsi
    mov     QWORD PTR [rdx].TASK_ENTRY.result_ptr, rdi
    mov     QWORD PTR [rdx].TASK_ENTRY.callback_ptr, r9

    ; Timestamp via QPC
    lea     rcx, [rdx].TASK_ENTRY.timestamp
    call    QueryPerformanceCounter

    lock inc QWORD PTR [g_orch_ctx.total_async]

    xor     eax, eax                        ; SUCCESS
    jmp     @@exit_async

@@not_init_async:
    mov     eax, ORCH_ERR_NOT_INIT
    jmp     @@exit_async

@@queue_full:
    lea     rcx, szOrchQueueFull
    call    OutputDebugStringA
    mov     eax, ORCH_ERR_QUEUE_FULL

@@exit_async:
    add     rsp, 40
    pop     rdi
    pop     rsi
    pop     rbx
    ret
asm_orchestrator_queue_async ENDP

; =============================================================================
; asm_orchestrator_drain_queue
; Process all pending tasks in the SPSC queue via synchronous dispatch.
; No parameters.
; Returns: RAX = number of tasks processed
; =============================================================================
asm_orchestrator_drain_queue PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    sub     rsp, 48
    .allocstack 48
    .endprolog

    cmp     DWORD PTR [g_orch_ctx.initialized], 1
    jne     @@drain_exit

    xor     r12d, r12d                      ; processed count

@@drain_loop:
    ; Check empty: tail == head?
    mov     eax, DWORD PTR [g_orch_ctx.queue_tail]
    cmp     eax, DWORD PTR [g_orch_ctx.queue_head]
    je      @@drain_done

    ; Read task at tail
    imul    rdx, rax, TASK_ENTRY_SIZE
    add     rdx, QWORD PTR [g_task_queue]
    mov     rsi, rdx                        ; -> task entry

    ; Dispatch synchronously
    mov     ecx, DWORD PTR [rsi].TASK_ENTRY.opcode
    mov     rdx, QWORD PTR [rsi].TASK_ENTRY.context_ptr
    mov     r8,  QWORD PTR [rsi].TASK_ENTRY.result_ptr
    call    asm_orchestrator_dispatch

    ; Call completion callback if set
    mov     rdi, QWORD PTR [rsi].TASK_ENTRY.callback_ptr
    test    rdi, rdi
    jz      @@no_callback

    mov     rcx, QWORD PTR [rsi].TASK_ENTRY.result_ptr
    call    rdi

@@no_callback:
    ; Advance tail (release the slot)
    mov     eax, DWORD PTR [g_orch_ctx.queue_tail]
    inc     eax
    and     eax, TASK_QUEUE_MASK
    mov     DWORD PTR [g_orch_ctx.queue_tail], eax

    inc     r12d
    jmp     @@drain_loop

@@drain_done:
    mov     eax, r12d

@@drain_exit:
    add     rsp, 48
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
asm_orchestrator_drain_queue ENDP

; =============================================================================
; asm_orchestrator_register_hook
; Register a pre- or post-dispatch callback.
; ECX = hook_type (HOOK_PRE_DISPATCH or HOOK_POST_DISPATCH)
; RDX = callback function pointer
; Returns: RAX = hook index (>= 0), or -1 on failure
; =============================================================================
asm_orchestrator_register_hook PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    sub     rsp, 40
    .allocstack 40
    .endprolog

    lea     rcx, g_orch_cs
    call    EnterCriticalSection

    mov     eax, DWORD PTR [g_orch_ctx.hook_count]
    cmp     eax, MAX_HOOKS
    jge     @@hooks_full

    ; Write hook entry
    lea     rsi, g_hooks
    imul    rbx, rax, SIZEOF HOOK_ENTRY
    add     rsi, rbx

    mov     DWORD PTR [rsi].HOOK_ENTRY.hook_type, ecx
    mov     QWORD PTR [rsi].HOOK_ENTRY.callback_ptr, rdx

    mov     ebx, eax                        ; save index
    inc     eax
    mov     DWORD PTR [g_orch_ctx.hook_count], eax

    lea     rcx, g_orch_cs
    call    LeaveCriticalSection

    mov     eax, ebx                        ; return hook index
    jmp     @@exit_hook

@@hooks_full:
    lea     rcx, g_orch_cs
    call    LeaveCriticalSection
    mov     eax, -1

@@exit_hook:
    add     rsp, 40
    pop     rsi
    pop     rbx
    ret
asm_orchestrator_register_hook ENDP

; =============================================================================
; asm_orchestrator_get_metrics
; Copy metrics for a given handler slot.
; ECX = opcode (7001–9700)
; RDX = output HANDLER_METRICS*
; Returns: RAX = 0 success, or ORCH_ERR_INVALID_OP
; =============================================================================
asm_orchestrator_get_metrics PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     rdi, rdx                        ; output ptr

    ; Map opcode
    call    map_opcode_to_index
    cmp     eax, -1
    je      @@metrics_invalid

    ; Copy metrics struct
    lea     rsi, g_handler_metrics
    imul    rax, rax, SIZEOF HANDLER_METRICS
    add     rsi, rax

    mov     rcx, rdi                        ; dest
    mov     rdx, rsi                        ; src
    mov     r8d, SIZEOF HANDLER_METRICS     ; size
    call    memcpy

    xor     eax, eax
    jmp     @@exit_metrics

@@metrics_invalid:
    mov     eax, ORCH_ERR_INVALID_OP

@@exit_metrics:
    add     rsp, 40
    pop     rdi
    pop     rsi
    pop     rbx
    ret
asm_orchestrator_get_metrics ENDP

; =============================================================================
; asm_orchestrator_shutdown
; Drain remaining tasks, release task queue memory, destroy critical section.
; No parameters.
; Returns: RAX = 0 success
; =============================================================================
asm_orchestrator_shutdown PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 48
    .allocstack 48
    .endprolog

    cmp     DWORD PTR [g_orch_ctx.initialized], 1
    jne     @@shutdown_exit

    ; Set shutdown flag
    mov     DWORD PTR [g_orch_ctx.shutting_down], 1

    ; Drain any remaining tasks
    call    asm_orchestrator_drain_queue

    ; Free task queue
    mov     rcx, QWORD PTR [g_task_queue]
    test    rcx, rcx
    jz      @@skip_free
    xor     edx, edx                        ; dwSize = 0
    mov     r8d, MEM_RELEASE
    call    VirtualFree
    mov     QWORD PTR [g_task_queue], 0

@@skip_free:
    ; Destroy critical section
    lea     rcx, g_orch_cs
    call    DeleteCriticalSection

    ; Clear context
    lea     rdi, g_orch_ctx
    xor     eax, eax
    mov     ecx, SIZEOF ORCH_CONTEXT
    rep     stosb

    lea     rcx, szOrchShutdown
    call    OutputDebugStringA

@@shutdown_exit:
    xor     eax, eax
    add     rsp, 48
    pop     rbx
    ret
asm_orchestrator_shutdown ENDP

; =============================================================================
; asm_orchestrator_lsp_sync
; v14.2.1 Cathedral Build: Direct bridge between SymbolIndex and
; ContextAnalyzer via the LSP-AI Bridge module. Dispatches through the
; VTable at slot 21 (OP_LSP_AI_SYNC = 9800) with deep sync mode.
;
; RCX = SYMBOL_ENTRY* array (from LSP SymbolIndex snapshot)
; EDX = symbol count
; R8D = sync mode (0=SHALLOW, 1=DEEP, 2=FULL_SEMANTIC)
; Returns: RAX = 0 success, error code otherwise
; =============================================================================
asm_orchestrator_lsp_sync PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    sub     rsp, 56
    .allocstack 56
    .endprolog

    cmp     DWORD PTR [g_orch_ctx.initialized], 1
    jne     @@lsp_not_init

    mov     r12, rcx                        ; SYMBOL_ENTRY*
    mov     r13d, edx                       ; count
    mov     ebx, r8d                        ; mode

    ; Verify OP_LSP_AI_SYNC handler is registered (VTable slot 21)
    lea     rsi, g_vtable
    mov     rax, QWORD PTR [rsi + 21*8]
    test    rax, rax
    jz      @@lsp_not_impl
    mov     rdi, rax                        ; handler

    ; ---- RDTSC start ----
    rdtsc
    shl     rdx, 32
    or      rax, rdx
    push    rax                             ; save start_cycles

    ; Fire pre-dispatch hooks
    mov     ecx, HOOK_PRE_DISPATCH
    mov     edx, OP_LSP_AI_SYNC
    mov     r8, r12
    xor     r9d, r9d
    call    fire_hooks

    ; Call LSP-AI bridge handler: (symbols, count, mode)
    mov     rcx, r12                        ; SYMBOL_ENTRY*
    mov     edx, r13d                       ; count
    mov     r8d, ebx                        ; mode
    call    rdi
    mov     esi, eax                        ; save result

    ; Fire post-dispatch hooks
    push    rsi
    mov     ecx, HOOK_POST_DISPATCH
    mov     edx, OP_LSP_AI_SYNC
    mov     r8, r12
    xor     r9d, r9d
    call    fire_hooks
    pop     rsi

    ; ---- Metrics for slot 21 ----
    rdtsc
    shl     rdx, 32
    or      rax, rdx
    pop     rcx                             ; start_cycles
    sub     rax, rcx                        ; elapsed

    lea     rdi, g_handler_metrics
    add     rdi, 21 * (SIZEOF HANDLER_METRICS)
    lock inc QWORD PTR [rdi].HANDLER_METRICS.dispatch_count
    lock add QWORD PTR [rdi].HANDLER_METRICS.total_cycles, rax
    mov     DWORD PTR [rdi].HANDLER_METRICS.last_status, esi
    lock inc QWORD PTR [g_orch_ctx.total_dispatches]

    test    esi, esi
    jns     @@lsp_no_error
    lock inc QWORD PTR [rdi].HANDLER_METRICS.error_count
    lock inc QWORD PTR [g_orch_ctx.total_errors]
@@lsp_no_error:

    mov     eax, esi
    jmp     @@lsp_exit

@@lsp_not_init:
    mov     eax, ORCH_ERR_NOT_INIT
    jmp     @@lsp_exit
@@lsp_not_impl:
    mov     eax, ORCH_ERR_NOT_IMPL

@@lsp_exit:
    add     rsp, 56
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
asm_orchestrator_lsp_sync ENDP

END
 ; =============================================================================
; RawrXD_AgenticShellBridge.asm — AI-Native Terminal Intelligence Layer
; Production bridge between ShellIntegration and Local LLM Inference
; =============================================================================
;
; Architecture:
;   - Consumes ShellInteg output ring buffer (lock-free consumer)
;   - Maintains rolling context window (last 4KB of terminal I/O)
;   - Async Ollama inference trigger on command failure (exit != 0)
;   - Command suggestion generator (natural language -> shell command)
;   - Auto-fix pipeline: failed command -> AI explanation -> suggested fix
;
; Protocol:
;   Context Ring: [Command][Output][ExitCode] x 32 slots (circular)
;   AI Triggers:
;     - ExitCode != 0  ->  Explain error + suggest fix
;     - "?" prefix     ->  Natural language query mode
;     - "@fix"         ->  Explicit fix request for last failure
;     - Idle > 2s      ->  Proactive suggestion based on CWD/git status
;
; Exports:
;   AgenticShell_Init           — Bind to ShellInteg instance, spawn AI worker
;   AgenticShell_Shutdown       — Drain context, terminate AI thread
;   AgenticShell_OnCommandEnd   — Called by ShellInteg post-execution (async AI)
;   AgenticShell_GetSuggestion  — Retrieve AI-generated command suggestion
;   AgenticShell_AcceptFix      — Apply AI-suggested fix to ShellInteg
;   AgenticShell_SetMode        — Toggle: 0=passive, 1=active, 2=aggressive
;   AgenticShell_GetStats       — Return AI subsystem performance counters
;   AgenticShell_SetModel       — Configure LLM model name for inference
;
; Pattern: PatchResult (RAX=0 success, RAX=NTSTATUS-style error on failure)
;          RDX = detail pointer or supplemental data
; Rule:    NO CRT, NO Qt, NO std::, NO exceptions, NO HEAP ALLOCATIONS
;          Lock-free context ring (SPSC: Shell produces, AI consumes)
;          NO SOURCE FILE IS TO BE SIMPLIFIED
; Build:   ml64.exe /c /Zi /Zd /Fo RawrXD_AgenticShellBridge.obj RawrXD_AgenticShellBridge.asm
; Link:    link RawrXD_ShellIntegration.obj RawrXD_AgenticShellBridge.obj kernel32.lib wininet.lib
; =============================================================================

include RawrXD_Common.inc

; =============================================================================
; External Imports (from ShellIntegration module)
; =============================================================================
EXTERNDEF ShellInteg_GetCommandHistory:PROC
EXTERNDEF ShellInteg_GetStats:PROC
EXTERNDEF ShellInteg_IsAlive:PROC
EXTERNDEF ShellInteg_ExecuteCommand:PROC
EXTERNDEF ShellInteg_CompleteCommand:PROC

; =============================================================================
; Win32 API Imports (not in Common.inc)
; =============================================================================
EXTERNDEF CreateThread:PROC
EXTERNDEF WaitForSingleObject:PROC
EXTERNDEF CreateEventA:PROC
EXTERNDEF SetEvent:PROC
EXTERNDEF ResetEvent:PROC
EXTERNDEF InternetOpenA:PROC
EXTERNDEF InternetConnectA:PROC
EXTERNDEF HttpOpenRequestA:PROC
EXTERNDEF HttpSendRequestA:PROC
EXTERNDEF InternetReadFile:PROC
EXTERNDEF InternetCloseHandle:PROC
EXTERNDEF lstrlenA:PROC

; =============================================================================
; Constants
; =============================================================================

; Context Ring Configuration
CTX_RING_SLOTS          EQU 32
CTX_SLOT_SIZE           EQU 4096          ; 4KB per context entry
CTX_MASK                EQU (CTX_RING_SLOTS - 1)
CTX_CMD_MAX             EQU 512           ; Max command length within slot
CTX_OUT_MAX             EQU 3520          ; Remaining for output (4096-512-64 header)

; AI Trigger Modes
AI_MODE_PASSIVE         EQU 0             ; Only on explicit request
AI_MODE_ACTIVE          EQU 1             ; On non-zero exit codes
AI_MODE_AGGRESSIVE      EQU 2             ; Proactive suggestions

; Context Slot Flags
CTX_FLAG_NORMAL         EQU 0             ; No AI action
CTX_FLAG_FAILED         EQU 1             ; Command failed (exit != 0)
CTX_FLAG_AI_PENDING     EQU 2             ; Queued for AI processing
CTX_FLAG_AI_COMPLETE    EQU 3             ; AI has produced a suggestion
CTX_FLAG_AI_ERROR       EQU 4             ; AI inference failed

; HTTP/Ollama Configuration
INTERNET_OPEN_TYPE_DIRECT   EQU 1
INTERNET_SERVICE_HTTP       EQU 3
INTERNET_FLAG_RELOAD        EQU 80000000h
OLLAMA_PORT             EQU 11434
HTTP_TIMEOUT_MS         EQU 5000

; Buffer sizes
MAX_JSON_PAYLOAD        EQU 8192
MAX_SUGGESTION_LEN      EQU 512
MAX_MODEL_NAME_LEN      EQU 64
MAX_PROMPT_CONTEXT      EQU 2048          ; Max context sent to LLM

; WaitForSingleObject
WAIT_OBJECT_0           EQU 0
WAIT_TIMEOUT_VAL        EQU 00000102h
INFINITE_WAIT           EQU 0FFFFFFFFh

; Status Codes
AGENTSHELL_SUCCESS              EQU 0
AGENTSHELL_ERR_NOT_INIT         EQU 0C0000200h
AGENTSHELL_ERR_ALREADY_INIT     EQU 0C0000201h
AGENTSHELL_ERR_THREAD_FAIL      EQU 0C0000202h
AGENTSHELL_ERR_NET_FAIL         EQU 0C0000203h
AGENTSHELL_ERR_CONTEXT_FULL     EQU 0C0000204h
AGENTSHELL_ERR_INVALID_MODE     EQU 0C0000205h
AGENTSHELL_ERR_NULL_PARAM       EQU 0C0000206h
AGENTSHELL_ERR_NO_SUGGESTION    EQU 0C0000207h

; Context Slot Offsets (within 4096-byte slot)
CTX_OFF_CMD             EQU 0             ; [0-511]:   Command text (null-padded)
CTX_OFF_EXITCODE        EQU 512           ; [512-515]: Exit code (DWORD)
CTX_OFF_FLAGS           EQU 516           ; [516-519]: Flags (DWORD)
CTX_OFF_TIMESTAMP       EQU 520           ; [520-527]: Timestamp (QWORD)
CTX_OFF_OUTLEN          EQU 528           ; [528-531]: Output length (DWORD)
CTX_OFF_DURATION        EQU 532           ; [532-535]: Duration ms (DWORD)
CTX_OFF_PADDING         EQU 536           ; [536-575]: Reserved
CTX_OFF_OUTPUT          EQU 576           ; [576-4095]: Output text

; =============================================================================
;              Cache-Line Padded Counters Segment
; =============================================================================

AGENTSHELL_CL SEGMENT ALIGN(16) 'DATA'

    PUBLIC g_AS_MetricStart
    g_AS_MetricStart        dq 04147454E544149h     ; "AGENTAI" sentinel
                            db 56 dup(0)

    PUBLIC g_AS_Counter_CtxCaptured
    g_AS_Counter_CtxCaptured    dq 0
                                db 56 dup(0)

    PUBLIC g_AS_Counter_AIRequests
    g_AS_Counter_AIRequests     dq 0
                                db 56 dup(0)

    PUBLIC g_AS_Counter_AISuccess
    g_AS_Counter_AISuccess      dq 0
                                db 56 dup(0)

    PUBLIC g_AS_Counter_AIFailures
    g_AS_Counter_AIFailures     dq 0
                                db 56 dup(0)

    PUBLIC g_AS_Counter_BytesSentToAI
    g_AS_Counter_BytesSentToAI  dq 0
                                db 56 dup(0)

    PUBLIC g_AS_Counter_BytesFromAI
    g_AS_Counter_BytesFromAI    dq 0
                                db 56 dup(0)

    PUBLIC g_AS_Counter_CtxDropped
    g_AS_Counter_CtxDropped     dq 0
                                db 56 dup(0)

    PUBLIC g_AS_Counter_LocalStubHits
    g_AS_Counter_LocalStubHits  dq 0
                                db 56 dup(0)

    PUBLIC g_AS_MetricEnd
    g_AS_MetricEnd          dq 0454E44414745h       ; "ENDAGE" sentinel
                            db 56 dup(0)

AGENTSHELL_CL ENDS

; =============================================================================
;                          Data Segment
; =============================================================================
.data

    ; =========================================================================
    ; Initialization state
    ; =========================================================================
    ALIGN 8
    g_AS_Initialized        dq  0
    g_AS_ShutdownRequested  dq  0       ; Signal AI thread to exit
    g_AS_Mode               dd  AI_MODE_ACTIVE
    g_AS_ModePad            dd  0

    ; =========================================================================
    ; Thread handles
    ; =========================================================================
    ALIGN 8
    g_AS_hAIThread          dq  0
    g_AS_hEvent             dq  0       ; Manual-reset event for new data

    ; =========================================================================
    ; Context Ring Buffer (SPSC: Shell produces at head, AI consumes at tail)
    ; =========================================================================
    ALIGN 16
    g_ContextRing           db (CTX_RING_SLOTS * CTX_SLOT_SIZE) dup(0)

    ALIGN 8
    g_ContextHead           dq  0       ; Write index (atomic xadd by producer)
    g_ContextTail           dq  0       ; Read index (AI consumer only)

    ; =========================================================================
    ; AI suggestion output (double-buffered: write slot + read slot)
    ; =========================================================================
    ALIGN 8
    g_AS_SuggestionReady    dq  0       ; 1 = suggestion available for read
    g_AS_SuggestionBufA     db MAX_SUGGESTION_LEN dup(0)
    g_AS_SuggestionBufB     db MAX_SUGGESTION_LEN dup(0)
    g_AS_ActiveBuf          dq  0       ; 0 = A is readable, 1 = B is readable

    ; =========================================================================
    ; JSON payload scratch (only used by AI thread — no concurrency concern)
    ; =========================================================================
    ALIGN 8
    g_AS_JsonPayload        db MAX_JSON_PAYLOAD dup(0)

    ; =========================================================================
    ; HTTP response scratch (only used by AI thread)
    ; =========================================================================
    ALIGN 8
    g_AS_HttpResponse       db MAX_JSON_PAYLOAD dup(0)

    ; =========================================================================
    ; Model configuration
    ; =========================================================================
    ALIGN 8
    g_AS_ModelName          db "phi3", 0
                            db (MAX_MODEL_NAME_LEN - 5) dup(0)

    ; =========================================================================
    ; WinInet handles (AI thread only)
    ; =========================================================================
    ALIGN 8
    g_AS_hInternet          dq  0
    g_AS_hConnect           dq  0

    ; =========================================================================
    ; String Constants
    ; =========================================================================

    ; Ollama endpoint
    szAS_OllamaHost         db "127.0.0.1", 0
    szAS_UserAgent          db "RawrXD-AgenticShell/1.0", 0
    szAS_ApiPath            db "/api/generate", 0
    szAS_HttpVerb           db "POST", 0
    szAS_ContentType        db "Content-Type: application/json", 0Dh, 0Ah, 0

    ; JSON template fragments (built manually — no CRT sprintf)
    szAS_JsonModelOpen      db '{"model":"', 0
    szAS_JsonPromptOpen     db '","prompt":"', 0
    szAS_JsonStreamFalse    db '","stream":false}', 0

    ; Prompt prefixes
    szAS_PromptExplain      db "Explain this shell error concisely and show the corrected command. "
                            db "Command: ", 0
    szAS_PromptExplainOut   db " Output: ", 0
    szAS_PromptExplainExit  db " ExitCode: ", 0
    szAS_PromptSuggest      db "Suggest a shell command for: ", 0
    szAS_PromptFix          db "Fix this command: ", 0

    ; Log/status strings
    szAS_InitOk             db "[AgenticShell] AI subsystem initialized", 0Dh, 0Ah, 0
    szAS_ShutdownOk         db "[AgenticShell] AI subsystem shutdown", 0Dh, 0Ah, 0
    szAS_AIQuerySent        db "[AgenticShell] AI query dispatched", 0Dh, 0Ah, 0
    szAS_AIQueryFail        db "[AgenticShell] AI query failed", 0Dh, 0Ah, 0
    szAS_CtxCaptured        db "[AgenticShell] Context captured for AI", 0Dh, 0Ah, 0

    ; Scratch for integer-to-ascii
    g_AS_ItoBuf             db 32 dup(0)

    ; =========================================================================
    ; Local inference stub mode (0=HTTP/Ollama, 1=deterministic local stub)
    ; =========================================================================
    ALIGN 8
    g_AS_UseLocalStub       dd  0
    g_AS_LocalStubPad       dd  0

    ; =========================================================================
    ; Deterministic stub response templates
    ; =========================================================================
    szAS_StubExitCode1      db "General failure. Check command syntax and arguments.", 0
    szAS_StubExitCode2      db "File or directory not found. Verify path exists with 'dir' or 'ls'.", 0
    szAS_StubExitCode5      db "Access denied. Run with elevated privileges or check permissions.", 0
    szAS_StubExitCode127    db "Command not found. Verify it is installed and in PATH.", 0
    szAS_StubExitCode9009   db "Command not recognized. Verify it is installed and in PATH.", 0
    szAS_StubExitCode128    db "Process terminated by signal. Check for OOM or external kill.", 0
    szAS_StubDefault        db "Command failed. Review the output above for specific error details.", 0
    szAS_StubSugPrefix      db " Suggested fix: ", 0
    szAS_StubSugRetry       db "Retry with corrected syntax.", 0

; =============================================================================
;                           Code Segment
; =============================================================================
.code

; =============================================================================
; AgenticShell_Init — Initialize AI shell bridge
;
; Spawns background worker thread, prepares context ring, opens WinInet.
;
; RCX = Mode (AI_MODE_PASSIVE/ACTIVE/AGGRESSIVE)
; RDX = Model name string (NULL = default "phi3")
; Returns: RAX = 0 on success, AGENTSHELL_ERR_* on failure
; =============================================================================
PUBLIC AgenticShell_Init
AgenticShell_Init PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    sub     rsp, 192
    .allocstack 192
    .endprolog

    ; Guard: already initialized?
    cmp     qword ptr [g_AS_Initialized], 1
    jne     @as_init_go
    mov     eax, AGENTSHELL_ERR_ALREADY_INIT
    jmp     @as_init_exit
@as_init_go:

    ; Validate mode
    cmp     ecx, AI_MODE_AGGRESSIVE
    ja      @as_init_bad_mode
    mov     dword ptr [g_AS_Mode], ecx

    ; Clear shutdown flag
    mov     qword ptr [g_AS_ShutdownRequested], 0

    ; Set model if provided
    test    rdx, rdx
    jz      @as_init_default_model
    mov     rsi, rdx
    lea     rdi, g_AS_ModelName
    mov     ecx, MAX_MODEL_NAME_LEN - 1
@as_copy_model:
    lodsb
    stosb
    test    al, al
    jz      @as_model_done
    loop    @as_copy_model
    mov     byte ptr [rdi], 0       ; Force null terminate
@as_model_done:
@as_init_default_model:

    ; Zero context ring head/tail
    mov     qword ptr [g_ContextHead], 0
    mov     qword ptr [g_ContextTail], 0
    mov     qword ptr [g_AS_SuggestionReady], 0

    ; Zero performance counters
    mov     qword ptr [g_AS_Counter_CtxCaptured], 0
    mov     qword ptr [g_AS_Counter_AIRequests], 0
    mov     qword ptr [g_AS_Counter_AISuccess], 0
    mov     qword ptr [g_AS_Counter_AIFailures], 0
    mov     qword ptr [g_AS_Counter_BytesSentToAI], 0
    mov     qword ptr [g_AS_Counter_BytesFromAI], 0
    mov     qword ptr [g_AS_Counter_CtxDropped], 0
    mov     qword ptr [g_AS_Counter_LocalStubHits], 0

    ; ---- Create manual-reset event for signaling AI thread ----
    xor     ecx, ecx                ; lpEventAttributes = NULL
    mov     edx, 1                  ; bManualReset = TRUE
    xor     r8d, r8d                ; bInitialState = FALSE
    xor     r9d, r9d                ; lpName = NULL
    sub     rsp, 32
    call    CreateEventA
    add     rsp, 32
    test    rax, rax
    jz      @as_init_fail
    mov     qword ptr [g_AS_hEvent], rax

    ; ---- Open WinInet session (persistent for thread lifetime) ----
    lea     rcx, szAS_UserAgent
    mov     edx, INTERNET_OPEN_TYPE_DIRECT
    xor     r8, r8                  ; lpszProxy
    xor     r9, r9                  ; lpszProxyBypass
    sub     rsp, 40
    mov     qword ptr [rsp + 32], 0 ; dwFlags
    call    InternetOpenA
    add     rsp, 40
    test    rax, rax
    jz      @as_init_fail_event
    mov     qword ptr [g_AS_hInternet], rax

    ; ---- InternetConnect to Ollama ----
    ; InternetConnectA takes 8 params: hInternet, server, port, user,
    ;   password, service, dwFlags, dwContext
    mov     rcx, rax                ; hInternet
    lea     rdx, szAS_OllamaHost
    mov     r8d, OLLAMA_PORT
    xor     r9, r9                  ; lpszUserName
    sub     rsp, 64
    mov     qword ptr [rsp + 32], 0             ; lpszPassword
    mov     qword ptr [rsp + 40], INTERNET_SERVICE_HTTP
    mov     qword ptr [rsp + 48], 0             ; dwFlags
    mov     qword ptr [rsp + 56], 0             ; dwContext
    call    InternetConnectA
    add     rsp, 64
    test    rax, rax
    jz      @as_init_fail_inet
    mov     qword ptr [g_AS_hConnect], rax

    ; ---- Spawn AI worker thread ----
    xor     ecx, ecx                ; lpThreadAttributes
    xor     edx, edx                ; dwStackSize (default 1MB)
    lea     r8, as_AIWorkerThread   ; lpStartAddress
    xor     r9, r9                  ; lpParameter
    sub     rsp, 48
    mov     qword ptr [rsp + 32], 0 ; dwCreationFlags
    mov     qword ptr [rsp + 40], 0 ; lpThreadId
    call    CreateThread
    add     rsp, 48
    test    rax, rax
    jz      @as_init_fail_connect
    mov     qword ptr [g_AS_hAIThread], rax

    ; ---- Mark initialized ----
    mov     qword ptr [g_AS_Initialized], 1

    ; Debug log
    lea     rcx, szAS_InitOk
    sub     rsp, 32
    call    OutputDebugStringA
    add     rsp, 32

    xor     eax, eax
    jmp     @as_init_exit

@as_init_bad_mode:
    mov     eax, AGENTSHELL_ERR_INVALID_MODE
    jmp     @as_init_exit

@as_init_fail_connect:
    mov     rcx, qword ptr [g_AS_hConnect]
    sub     rsp, 32
    call    InternetCloseHandle
    add     rsp, 32
    mov     qword ptr [g_AS_hConnect], 0

@as_init_fail_inet:
    mov     rcx, qword ptr [g_AS_hInternet]
    sub     rsp, 32
    call    InternetCloseHandle
    add     rsp, 32
    mov     qword ptr [g_AS_hInternet], 0

@as_init_fail_event:
    mov     rcx, qword ptr [g_AS_hEvent]
    sub     rsp, 32
    call    CloseHandle
    add     rsp, 32
    mov     qword ptr [g_AS_hEvent], 0

@as_init_fail:
    mov     eax, AGENTSHELL_ERR_THREAD_FAIL

@as_init_exit:
    lea     rsp, [rbp]
    pop     rbp
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
AgenticShell_Init ENDP

; =============================================================================
; AgenticShell_Shutdown — Tear down AI shell bridge
;
; Signals worker thread to exit, waits 3 seconds, closes all handles.
;
; Returns: RAX = 0 on success
; =============================================================================
PUBLIC AgenticShell_Shutdown
AgenticShell_Shutdown PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 64
    .allocstack 64
    .endprolog

    cmp     qword ptr [g_AS_Initialized], 0
    je      @as_shut_not_init

    ; Signal shutdown
    mov     qword ptr [g_AS_ShutdownRequested], 1

    ; Wake the AI thread
    mov     rcx, qword ptr [g_AS_hEvent]
    test    rcx, rcx
    jz      @as_shut_no_event
    sub     rsp, 32
    call    SetEvent
    add     rsp, 32
@as_shut_no_event:

    ; Wait for AI thread to exit (3 seconds)
    mov     rcx, qword ptr [g_AS_hAIThread]
    test    rcx, rcx
    jz      @as_shut_close_inet
    mov     edx, 3000
    sub     rsp, 32
    call    WaitForSingleObject
    add     rsp, 32

    ; Close thread handle
    mov     rcx, qword ptr [g_AS_hAIThread]
    sub     rsp, 32
    call    CloseHandle
    add     rsp, 32
    mov     qword ptr [g_AS_hAIThread], 0

@as_shut_close_inet:
    ; Close WinInet handles
    mov     rcx, qword ptr [g_AS_hConnect]
    test    rcx, rcx
    jz      @as_shut_close_inet2
    sub     rsp, 32
    call    InternetCloseHandle
    add     rsp, 32
    mov     qword ptr [g_AS_hConnect], 0

@as_shut_close_inet2:
    mov     rcx, qword ptr [g_AS_hInternet]
    test    rcx, rcx
    jz      @as_shut_close_event
    sub     rsp, 32
    call    InternetCloseHandle
    add     rsp, 32
    mov     qword ptr [g_AS_hInternet], 0

@as_shut_close_event:
    mov     rcx, qword ptr [g_AS_hEvent]
    test    rcx, rcx
    jz      @as_shut_done
    sub     rsp, 32
    call    CloseHandle
    add     rsp, 32
    mov     qword ptr [g_AS_hEvent], 0

@as_shut_done:
    mov     qword ptr [g_AS_Initialized], 0

    lea     rcx, szAS_ShutdownOk
    sub     rsp, 32
    call    OutputDebugStringA
    add     rsp, 32

    xor     eax, eax
    jmp     @as_shut_exit

@as_shut_not_init:
    mov     eax, AGENTSHELL_ERR_NOT_INIT

@as_shut_exit:
    add     rsp, 64
    pop     rbx
    ret
AgenticShell_Shutdown ENDP

; =============================================================================
; AgenticShell_OnCommandEnd — Called when a command completes
;
; Captures command + output + exit code into the context ring.
; If mode >= ACTIVE and exit code != 0, signals AI thread.
;
; RCX = Exit code (DWORD, zero-extended)
; RDX = Pointer to output buffer
; R8  = Output length (bytes)
; R9  = Pointer to command string (null-terminated)
; Returns: RAX = 0
; =============================================================================
PUBLIC AgenticShell_OnCommandEnd
AgenticShell_OnCommandEnd PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    sub     rsp, 128
    .allocstack 128
    .endprolog

    ; Guard: initialized?
    cmp     qword ptr [g_AS_Initialized], 0
    je      @as_oce_exit_ok

    mov     r12d, ecx               ; r12d = exit code
    mov     r13, rdx                ; r13 = output ptr
    mov     r14, r8                 ; r14 = output len
    mov     r15, r9                 ; r15 = command ptr

    ; ---- SPSC ring-full guard ----
    ; If (head - tail) >= CTX_RING_SLOTS, producer overrun: drop context
    mov     rax, qword ptr [g_ContextHead]
    sub     rax, qword ptr [g_ContextTail]
    cmp     rax, CTX_RING_SLOTS
    jb      @as_oce_ring_ok
    ; Ring full — drop this context capture
    lock inc qword ptr [g_AS_Counter_CtxDropped]
    xor     eax, eax
    jmp     @as_oce_exit_ok

@as_oce_ring_ok:
    ; ---- Acquire context slot (atomic increment) ----
    mov     rax, 1
    lock xadd qword ptr [g_ContextHead], rax
    ; rax = old head value = our reserved slot index
    and     eax, CTX_MASK
    mov     ebx, eax                ; ebx = slot index

    ; Calculate slot address
    mov     ecx, CTX_SLOT_SIZE
    imul    rax, rcx                ; rax = slot offset
    lea     rdi, g_ContextRing
    add     rdi, rax                ; rdi = slot base pointer
    mov     rbx, rdi                ; rbx = save slot base

    ; ---- Zero the entire slot ----
    push    rdi
    xor     eax, eax
    mov     ecx, CTX_SLOT_SIZE
    rep stosb
    pop     rdi

    ; ---- Fill command text ----
    test    r15, r15
    jz      @as_oce_no_cmd
    push    rdi
    mov     rsi, r15
    mov     ecx, CTX_CMD_MAX - 1
@as_oce_copy_cmd:
    lodsb
    test    al, al
    jz      @as_oce_cmd_done
    stosb
    loop    @as_oce_copy_cmd
@as_oce_cmd_done:
    mov     byte ptr [rdi], 0       ; Null-terminate
    pop     rdi
@as_oce_no_cmd:

    ; ---- Fill exit code ----
    mov     dword ptr [rbx + CTX_OFF_EXITCODE], r12d

    ; ---- Fill timestamp ----
    sub     rsp, 32
    call    GetTickCount64
    add     rsp, 32
    mov     qword ptr [rbx + CTX_OFF_TIMESTAMP], rax

    ; ---- Fill output (truncated to CTX_OUT_MAX) ----
    test    r13, r13
    jz      @as_oce_no_output
    mov     rsi, r13
    lea     rdi, [rbx + CTX_OFF_OUTPUT]
    mov     rcx, r14
    cmp     rcx, CTX_OUT_MAX - 1
    jbe     @as_oce_out_fits
    mov     rcx, CTX_OUT_MAX - 1
@as_oce_out_fits:
    mov     dword ptr [rbx + CTX_OFF_OUTLEN], ecx
    rep movsb
    mov     byte ptr [rdi], 0       ; Null-terminate
@as_oce_no_output:

    ; ---- SPSC release fence ----
    ; Ensure all slot data writes (command, output, exitcode, timestamp)
    ; are globally visible BEFORE the availability flag is set.
    ; On x86 TSO, regular stores are ordered, but sfence provides
    ; defense-in-depth against streaming store reordering.
    sfence

    ; ---- Set flags based on exit code and mode ----
    cmp     dword ptr [g_AS_Mode], AI_MODE_PASSIVE
    je      @as_oce_passive

    test    r12d, r12d              ; Exit code == 0?
    jz      @as_oce_passive

    ; Non-zero exit + ACTIVE or AGGRESSIVE mode: mark for AI
    mov     dword ptr [rbx + CTX_OFF_FLAGS], CTX_FLAG_AI_PENDING
    lock inc qword ptr [g_AS_Counter_CtxCaptured]

    ; Debug log
    lea     rcx, szAS_CtxCaptured
    sub     rsp, 32
    call    OutputDebugStringA
    add     rsp, 32

    ; Signal AI thread
    mov     rcx, qword ptr [g_AS_hEvent]
    test    rcx, rcx
    jz      @as_oce_exit_ok
    sub     rsp, 32
    call    SetEvent
    add     rsp, 32
    jmp     @as_oce_exit_ok

@as_oce_passive:
    mov     dword ptr [rbx + CTX_OFF_FLAGS], CTX_FLAG_NORMAL

@as_oce_exit_ok:
    xor     eax, eax

    lea     rsp, [rbp]
    pop     rbp
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
AgenticShell_OnCommandEnd ENDP

; =============================================================================
; AgenticShell_GetSuggestion — Retrieve AI-generated suggestion
;
; RCX = Output buffer pointer (at least MAX_SUGGESTION_LEN bytes)
; RDX = Buffer capacity
; Returns: RAX = string length (0 if no suggestion), or error code
; =============================================================================
PUBLIC AgenticShell_GetSuggestion
AgenticShell_GetSuggestion PROC FRAME
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    sub     rsp, 32
    .allocstack 32
    .endprolog

    cmp     qword ptr [g_AS_Initialized], 0
    je      @as_gs_not_init

    test    rcx, rcx
    jz      @as_gs_null
    test    rdx, rdx
    jz      @as_gs_null

    ; Check if a suggestion is ready (atomic test-and-clear)
    ; cmpxchg: if [SuggestionReady] == RAX(1), store R8(0) → atomically consume
    ;          if [SuggestionReady] != RAX(1), load current into RAX → no modify
    mov     rax, 1                  ; Expected: ready (1)
    xor     r8d, r8d                ; Desired: consumed (0)
    lock cmpxchg qword ptr [g_AS_SuggestionReady], r8
    ; If cmpxchg failed (was not 1), no suggestion available
    cmp     eax, 1
    jne     @as_gs_none

    ; Determine which buffer is readable
    mov     rax, qword ptr [g_AS_ActiveBuf]
    test    rax, rax
    jz      @as_gs_use_A
    lea     rsi, g_AS_SuggestionBufB
    jmp     @as_gs_copy
@as_gs_use_A:
    lea     rsi, g_AS_SuggestionBufA

@as_gs_copy:
    mov     rdi, rcx                ; Output buffer
    ; Find suggestion length (manual strlen)
    xor     eax, eax
    mov     r8, rsi
@as_gs_len:
    cmp     byte ptr [r8 + rax], 0
    je      @as_gs_len_done
    inc     eax
    cmp     eax, edx                ; Don't exceed capacity
    jb      @as_gs_len
@as_gs_len_done:
    mov     ecx, eax                ; ecx = bytes to copy
    push    rax                     ; save length
    rep movsb
    mov     byte ptr [rdi], 0       ; Null-terminate
    pop     rax

    ; Flag was atomically cleared by cmpxchg above — no redundant clear needed

    jmp     @as_gs_exit

@as_gs_none:
    xor     eax, eax                ; No suggestion
    jmp     @as_gs_exit

@as_gs_not_init:
    mov     eax, AGENTSHELL_ERR_NOT_INIT
    jmp     @as_gs_exit

@as_gs_null:
    mov     eax, AGENTSHELL_ERR_NULL_PARAM

@as_gs_exit:
    add     rsp, 32
    pop     rdi
    pop     rsi
    ret
AgenticShell_GetSuggestion ENDP

; =============================================================================
; AgenticShell_AcceptFix — Apply AI-suggested fix by submitting to shell
;
; Reads the current suggestion and passes it to ShellInteg_ExecuteCommand.
;
; Returns: RAX = 0 on success, error if no suggestion or not init
; =============================================================================
PUBLIC AgenticShell_AcceptFix
AgenticShell_AcceptFix PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 48
    .allocstack 48
    .endprolog

    cmp     qword ptr [g_AS_Initialized], 0
    je      @as_af_not_init

    ; Check which buffer has the suggestion
    mov     rax, qword ptr [g_AS_ActiveBuf]
    test    rax, rax
    jz      @as_af_buf_A
    lea     rcx, g_AS_SuggestionBufB
    jmp     @as_af_check_empty
@as_af_buf_A:
    lea     rcx, g_AS_SuggestionBufA

@as_af_check_empty:
    cmp     byte ptr [rcx], 0
    je      @as_af_no_sugg

    ; Submit to ShellInteg
    xor     edx, edx                ; auto-detect length
    sub     rsp, 32
    call    ShellInteg_ExecuteCommand
    add     rsp, 32
    ; Return whatever ShellInteg returns
    jmp     @as_af_exit

@as_af_no_sugg:
    mov     eax, AGENTSHELL_ERR_NO_SUGGESTION
    jmp     @as_af_exit

@as_af_not_init:
    mov     eax, AGENTSHELL_ERR_NOT_INIT

@as_af_exit:
    add     rsp, 48
    pop     rbx
    ret
AgenticShell_AcceptFix ENDP

; =============================================================================
; AgenticShell_SetMode — Change AI trigger mode
;
; ECX = New mode (AI_MODE_PASSIVE/ACTIVE/AGGRESSIVE)
; Returns: RAX = 0 on success
; =============================================================================
PUBLIC AgenticShell_SetMode
AgenticShell_SetMode PROC
    cmp     ecx, AI_MODE_AGGRESSIVE
    ja      @as_sm_fail
    mov     dword ptr [g_AS_Mode], ecx
    xor     eax, eax
    ret
@as_sm_fail:
    mov     eax, AGENTSHELL_ERR_INVALID_MODE
    ret
AgenticShell_SetMode ENDP

; =============================================================================
; AgenticShell_SetModel — Configure LLM model name
;
; RCX = Model name string pointer (null-terminated)
; Returns: RAX = 0 on success
; =============================================================================
PUBLIC AgenticShell_SetModel
AgenticShell_SetModel PROC FRAME
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    sub     rsp, 32
    .allocstack 32
    .endprolog

    test    rcx, rcx
    jz      @as_smod_null
    cmp     byte ptr [rcx], 0
    je      @as_smod_null

    mov     rsi, rcx
    lea     rdi, g_AS_ModelName
    mov     ecx, MAX_MODEL_NAME_LEN - 1
@as_smod_copy:
    lodsb
    stosb
    test    al, al
    jz      @as_smod_done
    loop    @as_smod_copy
    mov     byte ptr [rdi], 0       ; Force null
@as_smod_done:
    xor     eax, eax
    jmp     @as_smod_exit

@as_smod_null:
    mov     eax, AGENTSHELL_ERR_NULL_PARAM

@as_smod_exit:
    add     rsp, 32
    pop     rdi
    pop     rsi
    ret
AgenticShell_SetModel ENDP

; =============================================================================
; AgenticShell_GetStats — Return AI subsystem performance counters
;
; RCX = Output buffer (9 QWORDs = 72 bytes minimum)
;   [0] = CtxCaptured
;   [1] = AIRequests
;   [2] = AISuccess
;   [3] = AIFailures
;   [4] = BytesSentToAI
;   [5] = BytesFromAI
;   [6] = CurrentMode
;   [7] = CtxDropped         (SPSC ring-full drops)
;   [8] = LocalStubHits      (deterministic stub invocations)
; Returns: RAX = 0
; =============================================================================
PUBLIC AgenticShell_GetStats
AgenticShell_GetStats PROC
    test    rcx, rcx
    jz      @as_gst_null

    mov     rax, qword ptr [g_AS_Counter_CtxCaptured]
    mov     qword ptr [rcx], rax
    mov     rax, qword ptr [g_AS_Counter_AIRequests]
    mov     qword ptr [rcx + 8], rax
    mov     rax, qword ptr [g_AS_Counter_AISuccess]
    mov     qword ptr [rcx + 16], rax
    mov     rax, qword ptr [g_AS_Counter_AIFailures]
    mov     qword ptr [rcx + 24], rax
    mov     rax, qword ptr [g_AS_Counter_BytesSentToAI]
    mov     qword ptr [rcx + 32], rax
    mov     rax, qword ptr [g_AS_Counter_BytesFromAI]
    mov     qword ptr [rcx + 40], rax
    mov     eax, dword ptr [g_AS_Mode]
    mov     qword ptr [rcx + 48], rax
    mov     rax, qword ptr [g_AS_Counter_CtxDropped]
    mov     qword ptr [rcx + 56], rax
    mov     rax, qword ptr [g_AS_Counter_LocalStubHits]
    mov     qword ptr [rcx + 64], rax

    xor     eax, eax
    ret

@as_gst_null:
    mov     eax, AGENTSHELL_ERR_NULL_PARAM
    ret
AgenticShell_GetStats ENDP

; =============================================================================
;                     Internal: AI Worker Thread
; =============================================================================

; -----------------------------------------------------------------------------
; as_AIWorkerThread — Background thread for Ollama inference
;
; Loop:
;   1. WaitForSingleObject on event (2s timeout for proactive checks)
;   2. Scan context ring for AI_PENDING slots
;   3. Build JSON prompt, POST to Ollama /api/generate
;   4. Parse response, store suggestion
;   5. Mark slot as AI_COMPLETE
;
; Terminates when g_AS_ShutdownRequested != 0
; -----------------------------------------------------------------------------
as_AIWorkerThread PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    sub     rsp, 640
    .allocstack 640
    .endprolog

@ai_worker_loop:
    ; ---- Check shutdown ----
    cmp     qword ptr [g_AS_ShutdownRequested], 0
    jne     @ai_worker_exit

    ; ---- Wait for event or 2-second timeout ----
    mov     rcx, qword ptr [g_AS_hEvent]
    mov     edx, 2000               ; 2s timeout (for proactive mode)
    sub     rsp, 32
    call    WaitForSingleObject
    add     rsp, 32

    ; Check shutdown again after wake
    cmp     qword ptr [g_AS_ShutdownRequested], 0
    jne     @ai_worker_exit

    ; Reset event if it was signaled
    cmp     eax, WAIT_OBJECT_0
    jne     @ai_scan_slots
    mov     rcx, qword ptr [g_AS_hEvent]
    sub     rsp, 32
    call    ResetEvent
    add     rsp, 32

@ai_scan_slots:
    ; ---- Scan from tail to head for pending slots ----
    mov     rax, qword ptr [g_ContextTail]
    mov     rcx, qword ptr [g_ContextHead]
    cmp     rax, rcx
    jae     @ai_worker_loop         ; Tail caught up to head — no work

@ai_process_slot:
    ; Load slot address
    mov     rax, qword ptr [g_ContextTail]
    and     eax, CTX_MASK
    mov     ecx, CTX_SLOT_SIZE
    imul    rax, rcx
    lea     rsi, g_ContextRing
    add     rsi, rax                ; rsi = slot base

    ; Check if AI_PENDING
    cmp     dword ptr [rsi + CTX_OFF_FLAGS], CTX_FLAG_AI_PENDING
    jne     @ai_advance_tail

    ; ---- SPSC acquire fence ----
    ; Ensure the flag read completes before any slot data reads.
    ; Pairs with sfence in producer (OnCommandEnd).
    lfence

    ; ---- Build error explanation prompt ----
    ; Target: inactive suggestion buffer (write to opposite of g_AS_ActiveBuf)
    mov     rax, qword ptr [g_AS_ActiveBuf]
    test    rax, rax
    jz      @ai_write_B
    lea     r12, g_AS_SuggestionBufA
    jmp     @ai_have_write_buf
@ai_write_B:
    lea     r12, g_AS_SuggestionBufB
@ai_have_write_buf:

    ; Build JSON payload into g_AS_JsonPayload
    lea     rdi, g_AS_JsonPayload
    call    as_BuildPromptJson      ; rsi = slot, rdi = output JSON buf
    ; Returns: rdi = past-end of JSON, rax = JSON string length
    mov     r13, rax                ; r13 = JSON payload length

    ; Count AI request
    lock inc qword ptr [g_AS_Counter_AIRequests]

    ; ---- Inference dispatch: HTTP (Ollama) or deterministic local stub ----
    cmp     dword ptr [g_AS_UseLocalStub], 0
    jne     @ai_use_local_stub

    ; HTTP POST to Ollama
    lea     rcx, g_AS_JsonPayload   ; Payload pointer
    mov     rdx, r13                ; Payload length
    mov     r8, r12                 ; Output suggestion buffer
    mov     r9d, MAX_SUGGESTION_LEN ; Output capacity
    call    as_PostToOllama
    jmp     @ai_check_infer_result

@ai_use_local_stub:
    ; Deterministic local inference (no network, no Ollama dependency)
    mov     rcx, rsi                ; Slot pointer (ContextSlot base)
    mov     rdx, r12                ; Output suggestion buffer
    mov     r8d, MAX_SUGGESTION_LEN ; Capacity
    call    as_LocalInferenceStub
    lock inc qword ptr [g_AS_Counter_LocalStubHits]

@ai_check_infer_result:
    test    eax, eax
    jnz     @ai_query_failed

    ; ---- Success: flip active buffer, mark ready ----
    mov     rax, qword ptr [g_AS_ActiveBuf]
    xor     rax, 1                  ; Flip 0<->1
    mov     qword ptr [g_AS_ActiveBuf], rax
    mov     qword ptr [g_AS_SuggestionReady], 1

    ; Mark slot as AI_COMPLETE
    mov     dword ptr [rsi + CTX_OFF_FLAGS], CTX_FLAG_AI_COMPLETE
    lock inc qword ptr [g_AS_Counter_AISuccess]

    lea     rcx, szAS_AIQuerySent
    sub     rsp, 32
    call    OutputDebugStringA
    add     rsp, 32
    jmp     @ai_advance_tail

@ai_query_failed:
    mov     dword ptr [rsi + CTX_OFF_FLAGS], CTX_FLAG_AI_ERROR
    lock inc qword ptr [g_AS_Counter_AIFailures]

    lea     rcx, szAS_AIQueryFail
    sub     rsp, 32
    call    OutputDebugStringA
    add     rsp, 32

@ai_advance_tail:
    inc     qword ptr [g_ContextTail]

    ; Check if more to process
    mov     rax, qword ptr [g_ContextTail]
    cmp     rax, qword ptr [g_ContextHead]
    jb      @ai_process_slot

    jmp     @ai_worker_loop

@ai_worker_exit:
    xor     eax, eax
    lea     rsp, [rbp]
    pop     rbp
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
as_AIWorkerThread ENDP

; =============================================================================
; as_BuildPromptJson — Construct JSON payload for Ollama /api/generate
;
; Input:
;   RSI = ContextSlot pointer (read-only)
;   RDI = Output buffer (g_AS_JsonPayload, MAX_JSON_PAYLOAD)
; Output:
;   RDI = past-end of JSON string
;   RAX = total JSON length
; Clobbers: RCX, RDX, R8, R9
;
; Produces: {"model":"<model>","prompt":"<context>","stream":false}
; =============================================================================
as_BuildPromptJson PROC FRAME
    push    rbx
    .pushreg rbx
    push    r12
    .pushreg r12
    sub     rsp, 32
    .allocstack 32
    .endprolog

    mov     r12, rdi                ; r12 = start of output

    ; ---- {"model":" ----
    lea     rbx, szAS_JsonModelOpen
    call    as_strcpy_advance       ; Copies string, advances rdi

    ; ---- model name ----
    lea     rbx, g_AS_ModelName
    call    as_strcpy_advance

    ; ---- ","prompt":" ----
    lea     rbx, szAS_JsonPromptOpen
    call    as_strcpy_advance

    ; ---- Prompt prefix: error explanation ----
    lea     rbx, szAS_PromptExplain
    call    as_json_escape_copy

    ; ---- Command text from slot [rsi + CTX_OFF_CMD] ----
    lea     rbx, [rsi + CTX_OFF_CMD]
    call    as_json_escape_copy

    ; ---- Output label ----
    lea     rbx, szAS_PromptExplainOut
    call    as_json_escape_copy

    ; ---- Output text from slot ----
    ; Bounds safety: cap output copy to both MAX_PROMPT_CONTEXT and
    ; remaining JSON buffer capacity (reserve 128 bytes for closing JSON)
    mov     rax, rdi
    sub     rax, r12                ; rax = bytes written so far
    mov     ecx, MAX_JSON_PAYLOAD - 128
    sub     ecx, eax                ; ecx = remaining capacity for output
    jle     @bp_skip_output         ; No room left — skip output body

    mov     eax, dword ptr [rsi + CTX_OFF_OUTLEN]
    cmp     eax, MAX_PROMPT_CONTEXT
    jbe     @bp_outlen_ok
    mov     eax, MAX_PROMPT_CONTEXT
@bp_outlen_ok:
    cmp     ecx, eax
    jbe     @bp_out_cap_ok          ; capacity < outLen: use capacity
    mov     ecx, eax                ; outLen < capacity: use outLen
@bp_out_cap_ok:
    lea     rbx, [rsi + CTX_OFF_OUTPUT]
    call    as_json_escape_copy_n
@bp_skip_output:

    ; ---- Exit code label ----
    lea     rbx, szAS_PromptExplainExit
    call    as_json_escape_copy

    ; ---- Exit code as decimal ----
    mov     eax, dword ptr [rsi + CTX_OFF_EXITCODE]
    call    as_uint32_to_buf        ; Writes decimal into rdi, advances rdi

    ; ---- ","stream":false} ----
    lea     rbx, szAS_JsonStreamFalse
    call    as_strcpy_advance

    ; Calculate total length
    mov     rax, rdi
    sub     rax, r12                ; rax = total JSON length

    ; Track bytes sent
    lock add qword ptr [g_AS_Counter_BytesSentToAI], rax

    add     rsp, 32
    pop     r12
    pop     rbx
    ret
as_BuildPromptJson ENDP

; =============================================================================
; as_PostToOllama — HTTP POST JSON payload, read response into suggestion buf
;
; RCX = JSON payload pointer
; RDX = JSON payload length
; R8  = Suggestion output buffer pointer
; R9  = Suggestion output capacity
; Returns: EAX = 0 on success, non-zero on failure
; =============================================================================
as_PostToOllama PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    sub     rsp, 256
    .allocstack 256
    .endprolog

    mov     r12, rcx                ; r12 = payload
    mov     r13, rdx                ; r13 = payload length
    mov     r14, r8                 ; r14 = suggestion buffer
    mov     r15, r9                 ; r15 = suggestion capacity

    ; ---- HttpOpenRequest (POST to /api/generate) ----
    mov     rcx, qword ptr [g_AS_hConnect]
    test    rcx, rcx
    jz      @po_fail

    lea     rdx, szAS_HttpVerb      ; "POST"
    lea     r8, szAS_ApiPath        ; "/api/generate"
    xor     r9, r9                  ; lpszVersion (HTTP/1.1)
    sub     rsp, 64
    mov     qword ptr [rsp + 32], 0         ; lpszReferer
    mov     qword ptr [rsp + 40], 0         ; lpszAcceptTypes
    mov     dword ptr [rsp + 48], INTERNET_FLAG_RELOAD
    mov     dword ptr [rsp + 52], 0         ; padding
    mov     qword ptr [rsp + 56], 0         ; dwContext
    call    HttpOpenRequestA
    add     rsp, 64
    test    rax, rax
    jz      @po_fail
    mov     rbx, rax                ; rbx = hRequest

    ; ---- HttpSendRequest with JSON body ----
    mov     rcx, rbx                ; hRequest
    lea     rdx, szAS_ContentType   ; Headers
    mov     r8, -1                  ; Auto-detect header length
    mov     r9, r12                 ; lpOptional = JSON payload
    sub     rsp, 40
    mov     qword ptr [rsp + 32], r13   ; dwOptionalLength
    call    HttpSendRequestA
    add     rsp, 40
    test    eax, eax
    jz      @po_fail_close

    ; ---- Read response into g_AS_HttpResponse ----
    lea     rdi, g_AS_HttpResponse
    xor     r13, r13                ; Total bytes read

@po_read_loop:
    mov     rcx, rbx                ; hRequest
    mov     rdx, rdi                ; Buffer
    mov     r8d, 4096               ; Chunk size
    lea     r9, [rbp - 16]          ; &bytesRead (fixed stack slot)
    mov     dword ptr [rbp - 16], 0
    sub     rsp, 32
    call    InternetReadFile
    add     rsp, 32
    test    eax, eax
    jz      @po_read_done           ; Error or done

    mov     eax, dword ptr [rbp - 16]
    test    eax, eax
    jz      @po_read_done           ; EOF

    add     rdi, rax
    add     r13, rax

    ; Bounds check: don't overflow g_AS_HttpResponse
    cmp     r13, MAX_JSON_PAYLOAD - 1
    jae     @po_read_done
    jmp     @po_read_loop

@po_read_done:
    mov     byte ptr [rdi], 0       ; Null-terminate response

    ; Track bytes received
    lock add qword ptr [g_AS_Counter_BytesFromAI], r13

    ; ---- Parse "response":"..." from JSON into suggestion buffer ----
    lea     rsi, g_AS_HttpResponse
    mov     rdi, r14                ; Suggestion output buffer
    mov     rcx, r15                ; Capacity
    call    as_ParseOllamaResponse

    ; ---- Close request handle ----
    mov     rcx, rbx
    sub     rsp, 32
    call    InternetCloseHandle
    add     rsp, 32

    xor     eax, eax                ; Success
    jmp     @po_exit

@po_fail_close:
    mov     rcx, rbx
    sub     rsp, 32
    call    InternetCloseHandle
    add     rsp, 32

@po_fail:
    mov     eax, 1

@po_exit:
    lea     rsp, [rbp]
    pop     rbp
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
as_PostToOllama ENDP

; =============================================================================
; as_ParseOllamaResponse — Extract "response" field value from JSON
;
; Scans for "response":"<value>" pattern and copies <value> into output buffer.
; Handles JSON escapes: \n -> newline, \\ -> backslash, \" -> quote.
;
; RSI = Input JSON string (null-terminated)
; RDI = Output buffer
; RCX = Output capacity
; Returns: RAX = output length (0 if field not found)
; =============================================================================
as_ParseOllamaResponse PROC
    push    rbx
    push    r12
    push    r13

    mov     r12, rdi                ; r12 = output start
    mov     r13, rcx                ; r13 = capacity
    xor     ebx, ebx                ; ebx = output length

    ; Scan for "response" key
@opr_scan:
    lodsb
    test    al, al
    jz      @opr_not_found

    cmp     al, '"'
    jne     @opr_scan

    ; Check if next chars are: response"
    cmp     byte ptr [rsi], 'r'
    jne     @opr_scan
    cmp     byte ptr [rsi + 1], 'e'
    jne     @opr_scan
    cmp     byte ptr [rsi + 2], 's'
    jne     @opr_scan
    cmp     byte ptr [rsi + 3], 'p'
    jne     @opr_scan
    cmp     byte ptr [rsi + 4], 'o'
    jne     @opr_scan
    cmp     byte ptr [rsi + 5], 'n'
    jne     @opr_scan
    cmp     byte ptr [rsi + 6], 's'
    jne     @opr_scan
    cmp     byte ptr [rsi + 7], 'e'
    jne     @opr_scan
    add     rsi, 8                  ; Skip "response"

    ; Skip ":" and whitespace to opening quote
@opr_find_colon:
    lodsb
    cmp     al, '"'
    je      @opr_copy_value
    test    al, al
    jz      @opr_not_found
    jmp     @opr_find_colon

    ; Copy value, handling JSON escape sequences
@opr_copy_value:
    cmp     ebx, r13d
    jae     @opr_truncated          ; Output full

    lodsb
    test    al, al
    jz      @opr_done

    cmp     al, '"'                 ; Unescaped quote = end of value
    je      @opr_done

    cmp     al, '\'
    jne     @opr_literal

    ; Handle escape sequence
    lodsb
    cmp     al, 'n'
    je      @opr_esc_newline
    cmp     al, '\'
    je      @opr_literal
    cmp     al, '"'
    je      @opr_literal
    cmp     al, 't'
    je      @opr_esc_tab
    ; Unknown escape: emit backslash + char
    mov     byte ptr [rdi], '\'
    inc     rdi
    inc     ebx
    jmp     @opr_literal

@opr_esc_newline:
    mov     al, 0Ah
    jmp     @opr_literal
@opr_esc_tab:
    mov     al, 09h

@opr_literal:
    mov     byte ptr [rdi], al
    inc     rdi
    inc     ebx
    jmp     @opr_copy_value

@opr_truncated:
@opr_done:
    mov     byte ptr [rdi], 0       ; Null-terminate
    mov     eax, ebx
    jmp     @opr_exit

@opr_not_found:
    mov     byte ptr [r12], 0       ; Empty output
    xor     eax, eax

@opr_exit:
    pop     r13
    pop     r12
    pop     rbx
    ret
as_ParseOllamaResponse ENDP

; =============================================================================
;                    Internal String Helpers (Zero CRT)
; =============================================================================

; -----------------------------------------------------------------------------
; as_strcpy_advance — Copy null-terminated string from [rbx] to [rdi]
;                     Advances rdi past the last written byte (before null)
;                     Does NOT write null terminator
; Preserves: rsi, r12-r15
; -----------------------------------------------------------------------------
as_strcpy_advance PROC
    push    rax
    push    rcx
    mov     rcx, rbx
@sa_loop:
    mov     al, byte ptr [rcx]
    test    al, al
    jz      @sa_done
    mov     byte ptr [rdi], al
    inc     rcx
    inc     rdi
    jmp     @sa_loop
@sa_done:
    pop     rcx
    pop     rax
    ret
as_strcpy_advance ENDP

; -----------------------------------------------------------------------------
; as_json_escape_copy — Copy string from [rbx] to [rdi] with JSON escaping
;                       Escapes: " -> \", \ -> \\, \n -> \\n, \r -> \\r
;                       Advances rdi
; Preserves: rsi, r12-r15
; -----------------------------------------------------------------------------
as_json_escape_copy PROC
    push    rax
    push    rcx
    mov     rcx, rbx
@jec_loop:
    mov     al, byte ptr [rcx]
    test    al, al
    jz      @jec_done

    cmp     al, '"'
    je      @jec_esc_quote
    cmp     al, '\'
    je      @jec_esc_backslash
    cmp     al, 0Ah                 ; \n
    je      @jec_esc_newline
    cmp     al, 0Dh                 ; \r
    je      @jec_esc_cr
    cmp     al, 09h                 ; \t
    je      @jec_esc_tab

    ; Normal character
    mov     byte ptr [rdi], al
    inc     rdi
    inc     rcx
    jmp     @jec_loop

@jec_esc_quote:
    mov     byte ptr [rdi], '\'
    mov     byte ptr [rdi + 1], '"'
    add     rdi, 2
    inc     rcx
    jmp     @jec_loop

@jec_esc_backslash:
    mov     byte ptr [rdi], '\'
    mov     byte ptr [rdi + 1], '\'
    add     rdi, 2
    inc     rcx
    jmp     @jec_loop

@jec_esc_newline:
    mov     byte ptr [rdi], '\'
    mov     byte ptr [rdi + 1], 'n'
    add     rdi, 2
    inc     rcx
    jmp     @jec_loop

@jec_esc_cr:
    mov     byte ptr [rdi], '\'
    mov     byte ptr [rdi + 1], 'r'
    add     rdi, 2
    inc     rcx
    jmp     @jec_loop

@jec_esc_tab:
    mov     byte ptr [rdi], '\'
    mov     byte ptr [rdi + 1], 't'
    add     rdi, 2
    inc     rcx
    jmp     @jec_loop

@jec_done:
    pop     rcx
    pop     rax
    ret
as_json_escape_copy ENDP

; -----------------------------------------------------------------------------
; as_json_escape_copy_n — Same as above but limited to ECX bytes
; RBX = source, RDI = dest, ECX = max bytes to read
; -----------------------------------------------------------------------------
as_json_escape_copy_n PROC
    push    rax
    push    rdx
    mov     edx, ecx                ; edx = remaining count
    mov     rcx, rbx                ; rcx = source ptr
@jecn_loop:
    test    edx, edx
    jz      @jecn_done

    mov     al, byte ptr [rcx]
    test    al, al
    jz      @jecn_done

    cmp     al, '"'
    je      @jecn_esc_q
    cmp     al, '\'
    je      @jecn_esc_bs
    cmp     al, 0Ah
    je      @jecn_esc_nl
    cmp     al, 0Dh
    je      @jecn_esc_cr
    cmp     al, 09h                 ; \t (tab)
    je      @jecn_esc_tab

    mov     byte ptr [rdi], al
    inc     rdi
    inc     rcx
    dec     edx
    jmp     @jecn_loop

@jecn_esc_q:
    mov     word ptr [rdi], 225Ch   ; '\"' little-endian
    add     rdi, 2
    inc     rcx
    dec     edx
    jmp     @jecn_loop

@jecn_esc_bs:
    mov     word ptr [rdi], 5C5Ch   ; '\\' little-endian
    add     rdi, 2
    inc     rcx
    dec     edx
    jmp     @jecn_loop

@jecn_esc_nl:
    mov     byte ptr [rdi], '\'
    mov     byte ptr [rdi + 1], 'n'
    add     rdi, 2
    inc     rcx
    dec     edx
    jmp     @jecn_loop

@jecn_esc_cr:
    mov     byte ptr [rdi], '\'
    mov     byte ptr [rdi + 1], 'r'
    add     rdi, 2
    inc     rcx
    dec     edx
    jmp     @jecn_loop

@jecn_esc_tab:
    mov     byte ptr [rdi], '\'
    mov     byte ptr [rdi + 1], 't'
    add     rdi, 2
    inc     rcx
    dec     edx
    jmp     @jecn_loop

@jecn_done:
    pop     rdx
    pop     rax
    ret
as_json_escape_copy_n ENDP

; -----------------------------------------------------------------------------
; as_uint32_to_buf — Convert unsigned 32-bit integer in EAX to decimal ASCII
;                    Writes directly into [rdi], advances rdi
; Preserves: rsi, rbx, r12-r15
; Clobbers: rax, rcx, rdx, r8
; -----------------------------------------------------------------------------
as_uint32_to_buf PROC
    push    rbx

    ; Handle zero case
    test    eax, eax
    jnz     @u2b_nonzero
    mov     byte ptr [rdi], '0'
    inc     rdi
    pop     rbx
    ret

@u2b_nonzero:
    ; Convert digits in reverse into static scratch buffer.
    ; Uses g_AS_ItoBuf (AI thread only — no concurrency concern).
    ; Avoids push/pop digit reversal which corrupts SEH unwind state
    ; in a non-FRAME leaf procedure.
    mov     ebx, eax                ; save value
    lea     r8, g_AS_ItoBuf
    add     r8, 20                  ; r8 = past-end of scratch area
    xor     ecx, ecx                ; digit count

@u2b_loop:
    test    ebx, ebx
    jz      @u2b_emit

    mov     eax, ebx
    xor     edx, edx
    mov     r9d, 10
    div     r9d                     ; eax = quotient, edx = remainder
    mov     ebx, eax
    add     dl, '0'

    ; Store digit in reverse (decrementing scratch pointer)
    dec     r8
    mov     byte ptr [r8], dl
    inc     ecx
    jmp     @u2b_loop

@u2b_emit:
    ; Copy digits from scratch to output [rdi] in correct order
    ; r8 = start of digit string, ecx = digit count
@u2b_copy:
    test    ecx, ecx
    jz      @u2b_done
    mov     al, byte ptr [r8]
    mov     byte ptr [rdi], al
    inc     r8
    inc     rdi
    dec     ecx
    jmp     @u2b_copy

@u2b_done:
    pop     rbx
    ret
as_uint32_to_buf ENDP

; =============================================================================
; AgenticShell_SetLocalMode — Toggle between HTTP/Ollama and local stub
;
; ECX = 0: Use HTTP (Ollama) inference (default)
; ECX = 1: Use deterministic local inference stub (no network)
; Returns: RAX = 0 on success
; =============================================================================
PUBLIC AgenticShell_SetLocalMode
AgenticShell_SetLocalMode PROC
    cmp     ecx, 1
    ja      @as_slm_fail
    mov     dword ptr [g_AS_UseLocalStub], ecx
    xor     eax, eax
    ret
@as_slm_fail:
    mov     eax, AGENTSHELL_ERR_INVALID_MODE
    ret
AgenticShell_SetLocalMode ENDP

; =============================================================================
; as_LocalInferenceStub — Deterministic local inference (no HTTP/Ollama)
;
; Generates a canned error explanation + suggestion based on exit code.
; Used for offline testing, CI environments, or as fallback when Ollama
; is unavailable.
;
; RCX = Slot pointer (ContextSlot base — read exit code + command)
; RDX = Output suggestion buffer
; R8  = Output capacity
; Returns: EAX = 0 on success
; =============================================================================
as_LocalInferenceStub PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    sub     rsp, 32
    .allocstack 32
    .endprolog

    mov     rsi, rcx                ; rsi = slot pointer
    mov     rdi, rdx                ; rdi = output write cursor
    mov     r12d, r8d               ; r12d = capacity
    mov     r13, rdx                ; r13 = output start

    ; Reserve 1 byte for null terminator
    sub     r12d, 1
    jle     @ls_fail                ; Capacity too small

    ; ---- Select error template based on exit code ----
    mov     eax, dword ptr [rsi + CTX_OFF_EXITCODE]

    lea     rbx, szAS_StubDefault   ; Default template
    cmp     eax, 1
    jne     @ls_not1
    lea     rbx, szAS_StubExitCode1
@ls_not1:
    cmp     eax, 2
    jne     @ls_not2
    lea     rbx, szAS_StubExitCode2
@ls_not2:
    cmp     eax, 5
    jne     @ls_not5
    lea     rbx, szAS_StubExitCode5
@ls_not5:
    cmp     eax, 127
    jne     @ls_not127
    lea     rbx, szAS_StubExitCode127
@ls_not127:
    cmp     eax, 9009
    jne     @ls_not9009
    lea     rbx, szAS_StubExitCode9009
@ls_not9009:
    ; Check for signal-killed processes (exit codes 128+)
    cmp     eax, 128
    jb      @ls_template_selected
    cmp     eax, 192
    ja      @ls_template_selected
    lea     rbx, szAS_StubExitCode128
@ls_template_selected:

    ; ---- Copy error template to output (bounded) ----
    xor     ecx, ecx                ; ecx = bytes written
@ls_copy_msg:
    cmp     ecx, r12d
    jae     @ls_finish
    mov     al, byte ptr [rbx]
    test    al, al
    jz      @ls_msg_done
    mov     byte ptr [rdi], al
    inc     rbx
    inc     rdi
    inc     ecx
    jmp     @ls_copy_msg

@ls_msg_done:
    ; ---- Append suggestion suffix ----
    lea     rbx, szAS_StubSugPrefix
@ls_copy_sug:
    cmp     ecx, r12d
    jae     @ls_finish
    mov     al, byte ptr [rbx]
    test    al, al
    jz      @ls_sug_done
    mov     byte ptr [rdi], al
    inc     rbx
    inc     rdi
    inc     ecx
    jmp     @ls_copy_sug

@ls_sug_done:
    lea     rbx, szAS_StubSugRetry
@ls_copy_retry:
    cmp     ecx, r12d
    jae     @ls_finish
    mov     al, byte ptr [rbx]
    test    al, al
    jz      @ls_finish
    mov     byte ptr [rdi], al
    inc     rbx
    inc     rdi
    inc     ecx
    jmp     @ls_copy_retry

@ls_finish:
    mov     byte ptr [rdi], 0       ; Null-terminate
    xor     eax, eax                ; Success
    jmp     @ls_exit

@ls_fail:
    mov     eax, 1                  ; Failure (capacity exhausted)

@ls_exit:
    add     rsp, 32
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
as_LocalInferenceStub ENDP

END
 ; =============================================================================
; RawrXD_AgentToolExecutor.asm
; Agentic Tool Executor — CLI + Win32 GUI Recovery Bridge
; Decides between CLI (remote terminal) and GUI (local desktop) modes
; Spawns background worker thread, routes events to UI or stdout
;
; Features:
;   - CLI Mode: Synchronous recovery with stdout telemetry
;   - GUI Mode: Win32 window class, progress bar, abort button, PostMessage
;   - Thread-safe: Worker thread + UI thread via DISK_RECOVERY_CONTEXT
;   - Agent Integration: C-callable exports for AgenticOrchestrator
;   - Volatile abort: movzx-based memory barrier for AbortSignal
;
; Build (standalone CLI):
;   ml64.exe /c /Zi /Zd RawrXD_AgentToolExecutor.asm
;   link.exe RawrXD_AgentToolExecutor.obj RawrXD_DiskRecoveryAgent.obj
;          RawrXD_DiskKernel.obj /subsystem:console /entry:AgentTool_CLIMain
;          kernel32.lib user32.lib gdi32.lib ntdll.lib
;
; Build (standalone GUI):
;   ml64.exe /c /Zi /Zd RawrXD_AgentToolExecutor.asm
;   link.exe RawrXD_AgentToolExecutor.obj RawrXD_DiskRecoveryAgent.obj
;          RawrXD_DiskKernel.obj /subsystem:windows /entry:AgentTool_GUIMain
;          kernel32.lib user32.lib gdi32.lib comctl32.lib ntdll.lib
;
; Build (library — linked into RawrXD-Shell):
;   Included in CMakeLists.txt ASM_KERNEL_SOURCES — exports C-callable procs.
;
; Pattern: PatchResult (RAX=0 success, RAX=NTSTATUS on error, RDX=detail)
; Rule:    NO SOURCE FILE IS TO BE SIMPLIFIED.
; =============================================================================

option casemap:none

include RawrXD_Common.inc

