.code

; =============================================================================
; Internal: cam_sbox_preload — Pre-load S-box tables into L1 data cache
; Purpose: Ensure constant-time S-box lookups by bringing all 256 bytes
;          of each S-box into L1 cache before access. This prevents
;          cache-timing side-channel attacks where an adversary could
;          deduce key material from memory access patterns.
; Clobbers: None (all registers preserved)
; =============================================================================
ALIGN 16
cam_sbox_preload PROC
    push    rcx
    push    rax
    ; Touch every cache line of SBOX1 (256 bytes = 4 x 64-byte L1 lines)
    lea     rcx, [cam_sbox1]
    mov     rax, QWORD PTR [rcx]
    mov     rax, QWORD PTR [rcx + 64]
    mov     rax, QWORD PTR [rcx + 128]
    mov     rax, QWORD PTR [rcx + 192]
    ; Touch every cache line of SBOX2
    lea     rcx, [cam_sbox2]
    mov     rax, QWORD PTR [rcx]
    mov     rax, QWORD PTR [rcx + 64]
    mov     rax, QWORD PTR [rcx + 128]
    mov     rax, QWORD PTR [rcx + 192]
    ; Touch every cache line of SBOX3
    lea     rcx, [cam_sbox3]
    mov     rax, QWORD PTR [rcx]
    mov     rax, QWORD PTR [rcx + 64]
    mov     rax, QWORD PTR [rcx + 128]
    mov     rax, QWORD PTR [rcx + 192]
    ; Touch every cache line of SBOX4
    lea     rcx, [cam_sbox4]
    mov     rax, QWORD PTR [rcx]
    mov     rax, QWORD PTR [rcx + 64]
    mov     rax, QWORD PTR [rcx + 128]
    mov     rax, QWORD PTR [rcx + 192]
    pop     rax
    pop     rcx
    ret
cam_sbox_preload ENDP

; =============================================================================
; Internal: cam_sbox_layer — Apply RFC 3713 SP S-box substitution to 64-bit value
; RFC 3713 byte-to-S-box mapping (MSB to LSB):
;   Byte 7 (bits 63-56): SBOX1    Byte 3 (bits 31-24): SBOX2
;   Byte 6 (bits 55-48): SBOX2    Byte 2 (bits 23-16): SBOX3
;   Byte 5 (bits 47-40): SBOX3    Byte 1 (bits 15-8):  SBOX4
;   Byte 4 (bits 39-32): SBOX4    Byte 0 (bits  7-0):  SBOX1
; Input:  RAX = 64-bit value to substitute
; Output: RAX = substituted value
; Clobbers: RCX, RDX, R8
; =============================================================================
ALIGN 16
cam_sbox_layer PROC
    push    rbx
    push    rsi
    push    rdi

    mov     rsi, rax            ; save input
    xor     rax, rax            ; clear result

    ; Byte 0 (LSB, bits 7-0): SBOX1
    lea     rdi, [cam_sbox1]
    movzx   ecx, sil
    movzx   edx, BYTE PTR [rdi + rcx]
    mov     al, dl

    ; Byte 1 (bits 15-8): SBOX4
    lea     rdi, [cam_sbox4]
    mov     rcx, rsi
    shr     rcx, 8
    and     ecx, 0FFh
    movzx   edx, BYTE PTR [rdi + rcx]
    shl     rdx, 8
    or      rax, rdx

    ; Byte 2 (bits 23-16): SBOX3
    lea     rdi, [cam_sbox3]
    mov     rcx, rsi
    shr     rcx, 16
    and     ecx, 0FFh
    movzx   edx, BYTE PTR [rdi + rcx]
    shl     rdx, 16
    or      rax, rdx

    ; Byte 3 (bits 31-24): SBOX2
    lea     rdi, [cam_sbox2]
    mov     rcx, rsi
    shr     rcx, 24
    and     ecx, 0FFh
    movzx   edx, BYTE PTR [rdi + rcx]
    shl     rdx, 24
    or      rax, rdx

    ; Byte 4 (bits 39-32): SBOX4
    lea     rdi, [cam_sbox4]
    mov     rcx, rsi
    shr     rcx, 32
    and     ecx, 0FFh
    movzx   edx, BYTE PTR [rdi + rcx]
    mov     r8, rdx
    shl     r8, 32
    or      rax, r8

    ; Byte 5 (bits 47-40): SBOX3
    lea     rdi, [cam_sbox3]
    mov     rcx, rsi
    shr     rcx, 40
    and     ecx, 0FFh
    movzx   edx, BYTE PTR [rdi + rcx]
    mov     r8, rdx
    shl     r8, 40
    or      rax, r8

    ; Byte 6 (bits 55-48): SBOX2
    lea     rdi, [cam_sbox2]
    mov     rcx, rsi
    shr     rcx, 48
    and     ecx, 0FFh
    movzx   edx, BYTE PTR [rdi + rcx]
    mov     r8, rdx
    shl     r8, 48
    or      rax, r8

    ; Byte 7 (MSB, bits 63-56): SBOX1
    lea     rdi, [cam_sbox1]
    mov     rcx, rsi
    shr     rcx, 56
    movzx   edx, BYTE PTR [rdi + rcx]
    mov     r8, rdx
    shl     r8, 56
    or      rax, r8

    pop     rdi
    pop     rsi
    pop     rbx
    ret
cam_sbox_layer ENDP

; =============================================================================
; Internal: cam_F — Camellia F-function
; Input:  RAX = data, RDX = subkey
; Output: RAX = F(data, subkey)
; =============================================================================
ALIGN 16
cam_F PROC
    xor     rax, rdx            ; XOR with subkey
    call    cam_sbox_layer      ; S-box substitution
    ; P-function: byte permutation via rotations
    mov     rcx, rax
    rol     rcx, 8
    xor     rax, rcx
    mov     rcx, rax
    rol     rcx, 16
    xor     rax, rcx
    mov     rcx, rax
    rol     rcx, 24
    xor     rax, rcx
    ret
cam_F ENDP

; =============================================================================
; Internal: cam_FL — Camellia FL function (key-dependent linear mixing)
; Input:  RAX = data, RDX = subkey
; Output: RAX = FL(data, subkey)
; =============================================================================
ALIGN 16
cam_FL PROC
    push    rcx
    mov     rcx, rax
    and     rcx, rdx
    rol     rcx, 1
    xor     rax, rcx
    pop     rcx
    ret
cam_FL ENDP

; =============================================================================
; Internal: cam_FLINV — Camellia FL-inverse function
; Input:  RAX = data, RDX = subkey
; Output: RAX = FLINV(data, subkey)
; =============================================================================
ALIGN 16
cam_FLINV PROC
    push    rcx
    mov     rcx, rax
    or      rcx, rdx
    ror     rcx, 1
    xor     rax, rcx
    pop     rcx
    ret
cam_FLINV ENDP

; =============================================================================
; Internal: cam_load64 — Load 64-bit value from byte array (little-endian)
; Input:  RCX = pointer to 8 bytes
; Output: RAX = 64-bit value
; =============================================================================
ALIGN 16
cam_load64 PROC
    mov     rax, QWORD PTR [rcx]
    ret
cam_load64 ENDP

; =============================================================================
; Internal: cam_store64 — Store 64-bit value to byte array
; Input:  RCX = pointer, RDX = value
; =============================================================================
ALIGN 16
cam_store64 PROC
    mov     QWORD PTR [rcx], rdx
    ret
cam_store64 ENDP

; =============================================================================
; Internal: cam_sha256 — Compute SHA-256 hash using Windows CryptoAPI
; Input:  RCX = pointer to input data
;         RDX = length of input data (DWORD)
;         R8  = pointer to 32-byte output buffer
; Output: EAX = 0 on success, -1 on error
; Notes:  Uses CryptAcquireContextA / CryptCreateHash / CryptHashData /
;         CryptGetHashParam / CryptDestroyHash / CryptReleaseContext.
;         Thread-safe (acquires/releases context per call).
;         All non-volatile registers preserved.
; =============================================================================
ALIGN 16
cam_sha256 PROC FRAME
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    .setframe rbp, 0
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    sub     rsp, 96
    .allocstack 96
    .endprolog

    ; Save parameters in non-volatile registers
    mov     r12, rcx                    ; data pointer
    mov     r13d, edx                   ; data length (DWORD)
    mov     rbx, r8                     ; output pointer

    ; Local variables layout (relative to rbp):
    ;   [rbp - 80]  = hProv      (HCRYPTPROV, 8 bytes)
    ;   [rbp - 72]  = hHash      (HCRYPTHASH, 8 bytes)
    ;   [rbp - 64]  = hashLen    (DWORD, initialized to 32)
    mov     DWORD PTR [rbp - 64], 32

    ; ---- CryptAcquireContextA(&hProv, NULL, NULL, PROV_RSA_AES, CRYPT_VERIFYCONTEXT) ----
    lea     rcx, [rbp - 80]
    xor     rdx, rdx
    xor     r8, r8
    mov     r9d, PROV_RSA_AES
    mov     eax, 0F0000000h             ; CRYPT_VERIFYCONTEXT
    mov     QWORD PTR [rsp + 32], rax
    call    CryptAcquireContextA
    test    eax, eax
    jz      @@sha_fail

    ; ---- CryptCreateHash(hProv, CALG_SHA_256, 0, 0, &hHash) ----
    mov     rcx, QWORD PTR [rbp - 80]
    mov     edx, CALG_SHA_256
    xor     r8, r8
    xor     r9d, r9d
    lea     rax, [rbp - 72]
    mov     QWORD PTR [rsp + 32], rax
    call    CryptCreateHash
    test    eax, eax
    jz      @@sha_release_prov

    ; ---- CryptHashData(hHash, data, dataLen, 0) ----
    mov     rcx, QWORD PTR [rbp - 72]
    mov     rdx, r12
    mov     r8d, r13d
    xor     r9d, r9d
    call    CryptHashData
    test    eax, eax
    jz      @@sha_destroy_hash

    ; ---- CryptGetHashParam(hHash, HP_HASHVAL, output, &hashLen, 0) ----
    mov     rcx, QWORD PTR [rbp - 72]
    mov     edx, HP_HASHVAL
    mov     r8, rbx
    lea     r9, [rbp - 64]
    mov     QWORD PTR [rsp + 32], 0
    call    CryptGetHashParam
    test    eax, eax
    jz      @@sha_destroy_hash

    ; ---- Success: cleanup and return 0 ----
    mov     rcx, QWORD PTR [rbp - 72]
    call    CryptDestroyHash
    mov     rcx, QWORD PTR [rbp - 80]
    xor     edx, edx
    call    CryptReleaseContext
    xor     eax, eax
    jmp     @@sha_exit

@@sha_destroy_hash:
    mov     rcx, QWORD PTR [rbp - 72]
    call    CryptDestroyHash
@@sha_release_prov:
    mov     rcx, QWORD PTR [rbp - 80]
    xor     edx, edx
    call    CryptReleaseContext
@@sha_fail:
    mov     eax, -1
@@sha_exit:
    add     rsp, 96
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    pop     rbp
    ret
cam_sha256 ENDP

; =============================================================================
; asm_camellia256_set_key — Expand 256-bit key into 52 subkeys
; RCX = pointer to 32-byte key
; Returns: EAX = 0 (success) or error code
; =============================================================================
ALIGN 16
asm_camellia256_set_key PROC FRAME
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    .setframe rbp, 0
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 64                 ; local scratch space
    .allocstack 64
    .endprolog

    ; Validate input
    test    rcx, rcx
    jz      set_key_nullptr

    ; Copy master key
    lea     rdi, [cam_master_key]
    mov     rsi, rcx
    mov     ecx, 32
    rep movsb

    ; Load key halves: KL (left 128-bit) and KR (right 128-bit)
    lea     rsi, [cam_master_key]
    mov     r12, QWORD PTR [rsi]        ; KL[0]
    mov     r13, QWORD PTR [rsi + 8]    ; KL[1]
    mov     r14, QWORD PTR [rsi + 16]   ; KR[0]
    mov     r15, QWORD PTR [rsi + 24]   ; KR[1]

    ; Compute intermediate values D1..D4 via sigma constants
    ; D1 = KL[0] ^ KR[0], D2 = KL[1] ^ KR[1]
    mov     rax, r12
    xor     rax, r14                    ; D1
    mov     rbx, r13
    xor     rbx, r15                    ; D2

    ; Apply sigma constants for key schedule mixing
    lea     rdi, [cam_sigma]

    ; D2 ^= F(D1, sigma[0])
    mov     rdx, QWORD PTR [rdi]       ; sigma1
    push    rbx
    push    rax
    call    cam_F                       ; RAX = F(D1, sigma1)
    pop     rcx                         ; restore D1 into rcx (not rax)
    mov     rdx, rax                    ; F result
    pop     rbx                         ; restore D2
    xor     rbx, rdx                    ; D2 ^= F(D1, sigma1)
    mov     rax, rcx                    ; restore D1

    ; D1 ^= F(D2, sigma[1])
    push    rax
    mov     rax, rbx                    ; load D2
    lea     rdi, [cam_sigma]
    mov     rdx, QWORD PTR [rdi + 8]   ; sigma2
    call    cam_F
    mov     rcx, rax
    pop     rax
    xor     rax, rcx                    ; D1 ^= F(D2, sigma2)

    ; D1 ^= KL[0]
    xor     rax, r12

    ; D2 ^= KL[1]
    xor     rbx, r13

    ; D2 ^= F(D1, sigma[2])
    push    rbx
    push    rax
    lea     rdi, [cam_sigma]
    mov     rdx, QWORD PTR [rdi + 16]  ; sigma3
    call    cam_F
    pop     rcx
    mov     rdx, rax
    pop     rbx
    xor     rbx, rdx
    mov     rax, rcx

    ; D1 ^= F(D2, sigma[3])
    push    rax
    mov     rax, rbx
    lea     rdi, [cam_sigma]
    mov     rdx, QWORD PTR [rdi + 24]  ; sigma4
    call    cam_F
    mov     rcx, rax
    pop     rax
    xor     rax, rcx

    ; Now generate the 52 subkeys from KL, KR, D1, D2
    ; Using the expanded key rotation schedule per Camellia-256 spec
    lea     rdi, [cam_subkeys]

    ; Subkeys k[0..7] from KL
    mov     QWORD PTR [rdi],      r12       ; k[0] = KL[0]
    mov     QWORD PTR [rdi + 8],  r13       ; k[1] = KL[1]
    mov     QWORD PTR [rdi + 16], r14       ; k[2] = KR[0]
    mov     QWORD PTR [rdi + 24], r15       ; k[3] = KR[1]
    ; k[4..7] from D1, D2 mixed with KL
    mov     rcx, rax                        ; D1
    xor     rcx, r12
    mov     QWORD PTR [rdi + 32], rcx       ; k[4] = D1 ^ KL[0]
    mov     rcx, rbx
    xor     rcx, r13
    mov     QWORD PTR [rdi + 40], rcx       ; k[5] = D2 ^ KL[1]
    mov     QWORD PTR [rdi + 48], rax       ; k[6] = D1
    mov     QWORD PTR [rdi + 56], rbx       ; k[7] = D2

    ; Subkeys k[8..51] via rotation schedule
    ; Each subsequent group rotates the base material
    ; k[i] = ROL64(base[i%8] ^ modifiers, rotation_amount)
    mov     ecx, 8
@@subkey_loop:
    cmp     ecx, CAMELLIA_SUBKEYS
    jge     @@subkey_done

    ; Compute subkey[i] from previous subkeys via mixing
    mov     rsi, QWORD PTR [rdi + rcx * 8 - 64]    ; k[i-8]
    mov     rdx, QWORD PTR [rdi + rcx * 8 - 56]    ; k[i-7]
    xor     rsi, rdx
    ; Rotate by (i mod 13) + 1 positions
    push    rcx
    mov     eax, ecx
    xor     edx, edx
    mov     r8d, 13
    div     r8d                         ; edx = i % 13
    inc     edx                         ; rotation = (i%13) + 1
    mov     ecx, edx
    rol     rsi, cl
    pop     rcx
    mov     QWORD PTR [rdi + rcx * 8], rsi

    inc     ecx
    jmp     @@subkey_loop

@@subkey_done:
    ; Compute key fingerprint for status reporting
    mov     rax, r12
    xor     rax, r13
    xor     rax, r14
    xor     rax, r15
    mov     [cam_key_fingerprint], rax

    ; Mark engine as initialized
    mov     DWORD PTR [cam_initialized], 1

    ; Log success
    lea     rcx, [cam_debug_init_ok]
    call    OutputDebugStringA

    xor     eax, eax                    ; return CAMELLIA_OK

@@set_key_exit:
    add     rsp, 64
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    pop     rbp
    ret

set_key_nullptr:
    mov     eax, CAMELLIA_ERR_NULLPTR
    jmp     @@set_key_exit

asm_camellia256_set_key ENDP

; =============================================================================
; asm_camellia256_encrypt_block — Encrypt one 128-bit block
; RCX = pointer to 16-byte input plaintext
; RDX = pointer to 16-byte output ciphertext
; Returns: EAX = 0 (success) or error code
; =============================================================================
ALIGN 16
asm_camellia256_encrypt_block PROC FRAME
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    .setframe rbp, 0
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 48
    .allocstack 48
    .endprolog

    ; Check initialization
    cmp     DWORD PTR [cam_initialized], 1
    jne     @@enc_nokey

    test    rcx, rcx
    jz      @@enc_nullptr
    test    rdx, rdx
    jz      @@enc_nullptr

    ; Pre-load S-box tables into L1 cache for constant-time access
    call    cam_sbox_preload

    ; Save output pointer
    mov     r15, rdx

    ; Load plaintext block: L (left 64-bit), R (right 64-bit)
    mov     r12, QWORD PTR [rcx]         ; L = plaintext[0..7]
    mov     r13, QWORD PTR [rcx + 8]     ; R = plaintext[8..15]

    ; Load subkey base pointer
    lea     r14, [cam_subkeys]

    ; Pre-whitening: L ^= k[0], R ^= k[1]
    xor     r12, QWORD PTR [r14]
    xor     r13, QWORD PTR [r14 + 8]

    ; 24-round Feistel network with FL/FLINV at rounds 6, 12, 18
    ; Rounds 1-6
    mov     ecx, 0
@@enc_round_loop_1:
    cmp     ecx, 6
    jge     @@enc_fl_1

    ; R ^= F(L, k[2 + round*2])
    mov     rax, r12
    mov     edx, ecx
    shl     edx, 1
    add     edx, 2
    mov     rdx, QWORD PTR [r14 + rdx * 8]
    push    rcx
    call    cam_F
    pop     rcx
    xor     r13, rax

    ; Swap L and R
    xchg    r12, r13

    inc     ecx
    jmp     @@enc_round_loop_1

@@enc_fl_1:
    ; FL / FLINV mixing at round boundary
    mov     rax, r12
    mov     rdx, QWORD PTR [r14 + 14 * 8]
    call    cam_FL
    mov     r12, rax

    mov     rax, r13
    mov     rdx, QWORD PTR [r14 + 15 * 8]
    call    cam_FLINV
    mov     r13, rax

    ; Rounds 7-12
    mov     ecx, 6
@@enc_round_loop_2:
    cmp     ecx, 12
    jge     @@enc_fl_2

    mov     rax, r12
    mov     edx, ecx
    shl     edx, 1
    add     edx, 4
    mov     rdx, QWORD PTR [r14 + rdx * 8]
    push    rcx
    call    cam_F
    pop     rcx
    xor     r13, rax

    xchg    r12, r13

    inc     ecx
    jmp     @@enc_round_loop_2

@@enc_fl_2:
    mov     rax, r12
    mov     rdx, QWORD PTR [r14 + 28 * 8]
    call    cam_FL
    mov     r12, rax

    mov     rax, r13
    mov     rdx, QWORD PTR [r14 + 29 * 8]
    call    cam_FLINV
    mov     r13, rax

    ; Rounds 13-18
    mov     ecx, 12
@@enc_round_loop_3:
    cmp     ecx, 18
    jge     @@enc_fl_3

    mov     rax, r12
    mov     edx, ecx
    shl     edx, 1
    add     edx, 6
    mov     rdx, QWORD PTR [r14 + rdx * 8]
    push    rcx
    call    cam_F
    pop     rcx
    xor     r13, rax

    xchg    r12, r13

    inc     ecx
    jmp     @@enc_round_loop_3

@@enc_fl_3:
    mov     rax, r12
    mov     rdx, QWORD PTR [r14 + 42 * 8]
    call    cam_FL
    mov     r12, rax

    mov     rax, r13
    mov     rdx, QWORD PTR [r14 + 43 * 8]
    call    cam_FLINV
    mov     r13, rax

    ; Rounds 19-24
    mov     ecx, 18
@@enc_round_loop_4:
    cmp     ecx, 24
    jge     @@enc_post_whiten

    mov     rax, r12
    mov     edx, ecx
    shl     edx, 1
    add     edx, 2
    cmp     edx, CAMELLIA_SUBKEYS
    jge     @@enc_post_whiten
    mov     rdx, QWORD PTR [r14 + rdx * 8]
    push    rcx
    call    cam_F
    pop     rcx
    xor     r13, rax

    xchg    r12, r13

    inc     ecx
    jmp     @@enc_round_loop_4

@@enc_post_whiten:
    ; Post-whitening: swap and XOR with final subkeys
    xor     r13, QWORD PTR [r14 + 50 * 8]
    xor     r12, QWORD PTR [r14 + 51 * 8]

    ; Store ciphertext (R first, then L for proper output)
    mov     QWORD PTR [r15], r13
    mov     QWORD PTR [r15 + 8], r12

    ; Increment stats
    lock inc QWORD PTR [cam_blocks_encrypted]

    xor     eax, eax
    jmp     @@enc_exit

@@enc_nokey:
    mov     eax, CAMELLIA_ERR_NOKEY
    jmp     @@enc_exit

@@enc_nullptr:
    mov     eax, CAMELLIA_ERR_NULLPTR

@@enc_exit:
    add     rsp, 48
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    pop     rbp
    ret
asm_camellia256_encrypt_block ENDP

; =============================================================================
; asm_camellia256_decrypt_block — Decrypt one 128-bit block
; RCX = pointer to 16-byte ciphertext
; RDX = pointer to 16-byte plaintext output
; Returns: EAX = 0 or error code
; =============================================================================
ALIGN 16
asm_camellia256_decrypt_block PROC FRAME
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    .setframe rbp, 0
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 48
    .allocstack 48
    .endprolog

    cmp     DWORD PTR [cam_initialized], 1
    jne     @@dec_nokey
    test    rcx, rcx
    jz      @@dec_nullptr
    test    rdx, rdx
    jz      @@dec_nullptr

    ; Pre-load S-box tables into L1 cache for constant-time access
    call    cam_sbox_preload

    mov     r15, rdx

    ; Load ciphertext (note: reversed from encrypt output)
    mov     r13, QWORD PTR [rcx]         ; R (was stored as first 8 bytes)
    mov     r12, QWORD PTR [rcx + 8]     ; L (was stored as second 8 bytes)

    lea     r14, [cam_subkeys]

    ; Pre-whitening (reverse of post-whitening in encrypt)
    xor     r13, QWORD PTR [r14 + 50 * 8]
    xor     r12, QWORD PTR [r14 + 51 * 8]

    ; Reverse rounds 24..19
    mov     ecx, 23
@@dec_round_loop_4:
    cmp     ecx, 18
    jl      @@dec_flinv_3

    mov     rax, r12
    mov     edx, ecx
    shl     edx, 1
    add     edx, 2
    cmp     edx, CAMELLIA_SUBKEYS
    jge     @@dec_flinv_3
    mov     rdx, QWORD PTR [r14 + rdx * 8]
    push    rcx
    call    cam_F
    pop     rcx
    xor     r13, rax
    xchg    r12, r13

    dec     ecx
    jmp     @@dec_round_loop_4

@@dec_flinv_3:
    mov     rax, r13
    mov     rdx, QWORD PTR [r14 + 43 * 8]
    call    cam_FL
    mov     r13, rax
    mov     rax, r12
    mov     rdx, QWORD PTR [r14 + 42 * 8]
    call    cam_FLINV
    mov     r12, rax

    ; Reverse rounds 18..13
    mov     ecx, 17
@@dec_round_loop_3:
    cmp     ecx, 12
    jl      @@dec_flinv_2

    mov     rax, r12
    mov     edx, ecx
    shl     edx, 1
    add     edx, 6
    mov     rdx, QWORD PTR [r14 + rdx * 8]
    push    rcx
    call    cam_F
    pop     rcx
    xor     r13, rax
    xchg    r12, r13

    dec     ecx
    jmp     @@dec_round_loop_3

@@dec_flinv_2:
    mov     rax, r13
    mov     rdx, QWORD PTR [r14 + 29 * 8]
    call    cam_FL
    mov     r13, rax
    mov     rax, r12
    mov     rdx, QWORD PTR [r14 + 28 * 8]
    call    cam_FLINV
    mov     r12, rax

    ; Reverse rounds 12..7
    mov     ecx, 11
@@dec_round_loop_2:
    cmp     ecx, 6
    jl      @@dec_flinv_1

    mov     rax, r12
    mov     edx, ecx
    shl     edx, 1
    add     edx, 4
    mov     rdx, QWORD PTR [r14 + rdx * 8]
    push    rcx
    call    cam_F
    pop     rcx
    xor     r13, rax
    xchg    r12, r13

    dec     ecx
    jmp     @@dec_round_loop_2

@@dec_flinv_1:
    mov     rax, r13
    mov     rdx, QWORD PTR [r14 + 15 * 8]
    call    cam_FL
    mov     r13, rax
    mov     rax, r12
    mov     rdx, QWORD PTR [r14 + 14 * 8]
    call    cam_FLINV
    mov     r12, rax

    ; Reverse rounds 6..1
    mov     ecx, 5
@@dec_round_loop_1:
    cmp     ecx, 0
    jl      @@dec_post_whiten

    mov     rax, r12
    mov     edx, ecx
    shl     edx, 1
    add     edx, 2
    mov     rdx, QWORD PTR [r14 + rdx * 8]
    push    rcx
    call    cam_F
    pop     rcx
    xor     r13, rax
    xchg    r12, r13

    dec     ecx
    jmp     @@dec_round_loop_1

@@dec_post_whiten:
    ; Reverse pre-whitening
    xor     r12, QWORD PTR [r14]
    xor     r13, QWORD PTR [r14 + 8]

    ; Store plaintext
    mov     QWORD PTR [r15], r12
    mov     QWORD PTR [r15 + 8], r13

    lock inc QWORD PTR [cam_blocks_decrypted]

    xor     eax, eax
    jmp     @@dec_exit

@@dec_nokey:
    mov     eax, CAMELLIA_ERR_NOKEY
    jmp     @@dec_exit

@@dec_nullptr:
    mov     eax, CAMELLIA_ERR_NULLPTR

@@dec_exit:
    add     rsp, 48
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    pop     rbp
    ret
asm_camellia256_decrypt_block ENDP

; =============================================================================
; asm_camellia256_encrypt_ctr — CTR-mode encrypt/decrypt buffer in-place
; RCX = pointer to buffer
; RDX = buffer length in bytes
; R8  = pointer to 16-byte nonce/IV (updated on return)
; Returns: EAX = 0 or error code
; =============================================================================
ALIGN 16
asm_camellia256_encrypt_ctr PROC FRAME
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    .setframe rbp, 0
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 64
    .allocstack 64
    .endprolog

    cmp     DWORD PTR [cam_initialized], 1
    jne     @@ctr_nokey
    test    rcx, rcx
    jz      @@ctr_nullptr
    test    r8, r8
    jz      @@ctr_nullptr

    mov     r12, rcx                    ; buffer pointer
    mov     r13, rdx                    ; buffer length
    mov     r14, r8                     ; nonce pointer

    ; Process each 16-byte block
@@ctr_loop:
    cmp     r13, 0
    jle     @@ctr_done

    ; Copy current counter to temp block
    lea     rcx, [cam_temp_block]
    mov     rax, QWORD PTR [r14]
    mov     QWORD PTR [rcx], rax
    mov     rax, QWORD PTR [r14 + 8]
    mov     QWORD PTR [rcx + 8], rax

    ; Encrypt counter block -> keystream
    lea     rdx, [cam_keystream]
    call    asm_camellia256_encrypt_block

    ; XOR keystream with data (handle partial final block)
    mov     ecx, 16
    cmp     r13, 16
    jge     @@ctr_full_block
    mov     ecx, r13d                   ; partial block
@@ctr_full_block:

    ; XOR loop
    xor     eax, eax
@@ctr_xor_loop:
    cmp     eax, ecx
    jge     @@ctr_xor_done
    lea     rsi, [cam_keystream]
    movzx   edx, BYTE PTR [rsi + rax]
    xor     BYTE PTR [r12 + rax], dl
    inc     eax
    jmp     @@ctr_xor_loop

@@ctr_xor_done:
    ; Increment counter (128-bit big-endian increment)
    ; Increment the low 64 bits, carry into high 64 bits
    mov     rax, QWORD PTR [r14 + 8]
    add     rax, 1
    mov     QWORD PTR [r14 + 8], rax
    jnc     @@ctr_no_carry
    inc     QWORD PTR [r14]
@@ctr_no_carry:

    ; Advance buffer pointer
    add     r12, 16
    sub     r13, 16
    jmp     @@ctr_loop

@@ctr_done:
    xor     eax, eax
    jmp     @@ctr_exit

@@ctr_nokey:
    mov     eax, CAMELLIA_ERR_NOKEY
    jmp     @@ctr_exit

@@ctr_nullptr:
    mov     eax, CAMELLIA_ERR_NULLPTR

@@ctr_exit:
    add     rsp, 64
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    pop     rbp
    ret
asm_camellia256_encrypt_ctr ENDP

; CTR decrypt is identical to encrypt (symmetric XOR)
ALIGN 16
asm_camellia256_decrypt_ctr PROC
    jmp     asm_camellia256_encrypt_ctr
asm_camellia256_decrypt_ctr ENDP

; =============================================================================
; asm_camellia256_init — Initialize engine with SHA-256-derived key
; No parameters — derives 256-bit key from HWID + volume serial via SHA-256
; Key derivation: SHA-256 iterated 1000 times over (salt || HWID || label)
; Also derives separate 32-byte HMAC-SHA256 authentication key
; Runs RFC 3713 self-test vectors before use
; Returns: EAX = 0 (CAMELLIA_OK) or error code
; =============================================================================
ALIGN 16
asm_camellia256_init PROC FRAME
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    .setframe rbp, 0
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    sub     rsp, 192
    .allocstack 192
    .endprolog

    ; -------------------------------------------------------
    ; Step 1: Run RFC 3713 self-test BEFORE real key setup
    ; (self-test uses/corrupts global subkeys, which are
    ;  overwritten by our set_key below)
    ; -------------------------------------------------------
    call    asm_camellia256_self_test
    test    eax, eax
    jnz     @@init_selftest_fail

    ; -------------------------------------------------------
    ; Step 2: Gather machine identity data
    ; -------------------------------------------------------
    ; Get computer name
    lea     rcx, [cam_computer_name]
    lea     rdx, [rbp - 48]
    mov     DWORD PTR [rbp - 48], 256
    call    GetComputerNameA

    ; Get volume serial number (C:\)
    lea     rcx, [cam_vol_path]
    xor     rdx, rdx
    xor     r8d, r8d
    lea     r9, [rbp - 52]
    sub     rsp, 32
    mov     QWORD PTR [rsp + 32], 0
    mov     QWORD PTR [rsp + 40], 0
    mov     QWORD PTR [rsp + 48], 0
    mov     QWORD PTR [rsp + 56], 0
    call    GetVolumeInformationA
    add     rsp, 32

    ; -------------------------------------------------------
    ; Step 3: Generate 32-byte random KDF salt
    ; -------------------------------------------------------
    xor     ecx, ecx
    lea     rdx, [cam_kdf_salt]
    mov     r8d, KDF_SALT_SIZE
    mov     r9d, 2                       ; BCRYPT_USE_SYSTEM_PREFERRED_RNG
    call    BCryptGenRandom

    ; -------------------------------------------------------
    ; Step 4: Build KDF material buffer in BSS
    ; material = salt[32] || computerName[N+1] || volumeSerial[4] || kdf_label[]
    ; -------------------------------------------------------
    lea     rdi, [cam_kdf_material]

    ; Copy 32-byte salt
    lea     rsi, [cam_kdf_salt]
    mov     ecx, 32
    rep     movsb
    mov     r12d, 32                    ; material_len = 32

    ; Copy computer name (null-terminated, include null byte)
    lea     rsi, [cam_computer_name]
@@init_copy_name:
    lodsb
    stosb
    inc     r12d
    test    al, al
    jnz     @@init_copy_name

    ; Copy volume serial (4 bytes)
    mov     eax, DWORD PTR [rbp - 52]
    stosd
    add     r12d, 4

    ; Copy KDF domain-separation label (null-terminated, include null)
    lea     rsi, [cam_kdf_label]
@@init_copy_label:
    lodsb
    stosb
    inc     r12d
    test    al, al
    jnz     @@init_copy_label

    ; Save material length for KDF loop
    mov     DWORD PTR [cam_kdf_material_len], r12d

    ; -------------------------------------------------------
    ; Step 5: Derive 256-bit encryption key via iterated SHA-256
    ;   key = SHA256(material)
    ;   for i in 1..KDF_ITERATIONS:
    ;       key = SHA256(key || material)
    ; Result stored in [rbp - 96] (32-byte key buffer on stack)
    ; -------------------------------------------------------

    ; Initial hash: SHA256(material) -> key
    lea     rcx, [cam_kdf_material]
    mov     edx, r12d
    lea     r8, [rbp - 96]
    call    cam_sha256
    test    eax, eax
    jnz     @@init_kdf_fail

    ; Iterative strengthening: KDF_ITERATIONS rounds
    mov     ebx, KDF_ITERATIONS
@@init_kdf_loop:
    ; Build concat buffer: key[32] || material[r12d]
    lea     rdi, [cam_sha256_concat_buf]
    lea     rsi, [rbp - 96]
    mov     ecx, 32
    rep     movsb
    lea     rsi, [cam_kdf_material]
    mov     ecx, DWORD PTR [cam_kdf_material_len]
    rep     movsb

    ; SHA256(key || material) -> key
    lea     rcx, [cam_sha256_concat_buf]
    mov     edx, 32
    add     edx, DWORD PTR [cam_kdf_material_len]
    lea     r8, [rbp - 96]
    call    cam_sha256
    test    eax, eax
    jnz     @@init_kdf_fail

    dec     ebx
    jnz     @@init_kdf_loop

    ; -------------------------------------------------------
    ; Step 6: Derive HMAC authentication key (separate from enc key)
    ;   hmac_key = SHA256(enc_key || "hmac-auth-key-v1")
    ; -------------------------------------------------------
    lea     rdi, [cam_sha256_concat_buf]
    lea     rsi, [rbp - 96]
    mov     ecx, 32
    rep     movsb
    lea     rsi, [cam_hmac_label]
    xor     ebx, ebx
@@init_copy_hmac_label:
    lodsb
    stosb
    inc     ebx
    test    al, al
    jnz     @@init_copy_hmac_label

    lea     rcx, [cam_sha256_concat_buf]
    mov     edx, ebx
    add     edx, 32
    lea     r8, [cam_hmac_key]
    call    cam_sha256
    test    eax, eax
    jnz     @@init_kdf_fail

    ; -------------------------------------------------------
    ; Step 7: Set Camellia-256 key from derived encryption key
    ; -------------------------------------------------------
    lea     rcx, [rbp - 96]
    call    asm_camellia256_set_key
    test    eax, eax
    jnz     @@init_kdf_fail

    ; -------------------------------------------------------
    ; Step 8: Generate random CTR nonce
    ; -------------------------------------------------------
    xor     ecx, ecx
    lea     rdx, [cam_ctr_nonce]
    mov     r8d, CTR_NONCE_SIZE
    mov     r9d, 2
    call    BCryptGenRandom

    ; -------------------------------------------------------
    ; Step 9: Secure-zero all sensitive intermediaries
    ; -------------------------------------------------------
    ; Zero derived key on stack (volatile write)
    lea     rdi, [rbp - 96]
    xor     eax, eax
    mov     ecx, 32
    rep     stosb

    ; Zero concat buffer
    lea     rdi, [cam_sha256_concat_buf]
    xor     eax, eax
    mov     ecx, 576
    rep     stosb

    ; Zero material buffer (contains HWID data)
    lea     rdi, [cam_kdf_material]
    xor     eax, eax
    mov     ecx, 512
    rep     stosb
    mov     DWORD PTR [cam_kdf_material_len], 0

    ; Reset stats (self-test inflated them)
    mov     QWORD PTR [cam_blocks_encrypted], 0
    mov     QWORD PTR [cam_blocks_decrypted], 0
    mov     QWORD PTR [cam_files_processed], 0

    ; Log success
    lea     rcx, [cam_debug_init_msg]
    call    OutputDebugStringA

    xor     eax, eax
    jmp     @@init_exit

@@init_kdf_fail:
    lea     rcx, [cam_debug_kdf_fail]
    call    OutputDebugStringA
    mov     eax, CAMELLIA_ERR_NOKEY
    jmp     @@init_exit

@@init_selftest_fail:
    lea     rcx, [cam_debug_selftest_fail]
    call    OutputDebugStringA
    mov     eax, CAMELLIA_ERR_SELFTEST

@@init_exit:
    add     rsp, 192
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    pop     rbp
    ret
asm_camellia256_init ENDP

; =============================================================================
; asm_camellia256_encrypt_file — Encrypt a file on disk using CTR mode
; RCX = pointer to input file path (null-terminated ANSI)
; RDX = pointer to output file path (null-terminated ANSI)
; Returns: EAX = 0 or error code
; =============================================================================
ALIGN 16
asm_camellia256_encrypt_file PROC FRAME
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    .setframe rbp, 0
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 128
    .allocstack 128
    .endprolog

    cmp     DWORD PTR [cam_initialized], 1
    jne     @@ef_nokey
    test    rcx, rcx
    jz      @@ef_nullptr
    test    rdx, rdx
    jz      @@ef_nullptr

    mov     r12, rcx                    ; input path
    mov     r13, rdx                    ; output path

    ; Open input file for reading
    mov     rcx, r12
    mov     edx, GENERIC_READ
    mov     r8d, FILE_SHARE_READ
    xor     r9d, r9d                    ; no security attrs
    sub     rsp, 32
    mov     DWORD PTR [rsp + 32], OPEN_EXISTING
    mov     DWORD PTR [rsp + 40], 0     ; flags
    mov     QWORD PTR [rsp + 48], 0     ; template
    call    CreateFileA
    add     rsp, 32
    cmp     rax, INVALID_HANDLE_VALUE
    je      @@ef_open_fail
    mov     r14, rax                    ; hInputFile

    ; Open output file for writing
    mov     rcx, r13
    mov     edx, GENERIC_WRITE
    xor     r8d, r8d                    ; no sharing
    xor     r9d, r9d
    sub     rsp, 32
    mov     DWORD PTR [rsp + 32], CREATE_ALWAYS
    mov     DWORD PTR [rsp + 40], 0
    mov     QWORD PTR [rsp + 48], 0
    call    CreateFileA
    add     rsp, 32
    cmp     rax, INVALID_HANDLE_VALUE
    je      @@ef_close_input_fail
    mov     r15, rax                    ; hOutputFile

    ; Write 16-byte CTR nonce as file header
    mov     rcx, r15                    ; hFile
    lea     rdx, [cam_ctr_nonce]        ; buffer
    mov     r8d, CTR_NONCE_SIZE         ; bytes to write
    lea     r9, [rbp - 48]              ; lpBytesWritten
    sub     rsp, 32
    mov     QWORD PTR [rsp + 32], 0     ; lpOverlapped
    call    WriteFile
    add     rsp, 32

    ; Initialize local CTR copy from nonce
    mov     rax, QWORD PTR [cam_ctr_nonce]
    mov     QWORD PTR [rbp - 64], rax
    mov     rax, QWORD PTR [cam_ctr_nonce + 8]
    mov     QWORD PTR [rbp - 56], rax

    ; Read-encrypt-write loop
@@ef_read_loop:
    ; Read chunk
    mov     rcx, r14                    ; hInputFile
    lea     rdx, [cam_io_buffer]        ; buffer
    mov     r8d, FILE_IO_BUFFER         ; max bytes
    lea     r9, [rbp - 48]              ; lpBytesRead
    sub     rsp, 32
    mov     QWORD PTR [rsp + 32], 0
    call    ReadFile
    add     rsp, 32

    test    eax, eax
    jz      @@ef_read_err

    mov     eax, DWORD PTR [rbp - 48]   ; bytes read
    test    eax, eax
    jz      @@ef_read_done              ; EOF

    ; Encrypt in-place via CTR mode
    lea     rcx, [cam_io_buffer]
    mov     edx, eax                    ; length
    lea     r8, [rbp - 64]              ; CTR state pointer
    mov     rbx, rax                    ; save bytes_read
    call    asm_camellia256_encrypt_ctr

    ; Write encrypted chunk
    mov     rcx, r15                    ; hOutputFile
    lea     rdx, [cam_io_buffer]
    mov     r8d, ebx                    ; bytes to write
    lea     r9, [rbp - 48]
    sub     rsp, 32
    mov     QWORD PTR [rsp + 32], 0
    call    WriteFile
    add     rsp, 32

    jmp     @@ef_read_loop

@@ef_read_done:
    ; Close files
    mov     rcx, r15
    call    CloseHandle
    mov     rcx, r14
    call    CloseHandle

    lock inc QWORD PTR [cam_files_processed]

    xor     eax, eax
    jmp     @@ef_exit

@@ef_read_err:
    mov     rcx, r15
    call    CloseHandle
    mov     rcx, r14
    call    CloseHandle
    mov     eax, CAMELLIA_ERR_FILEREAD
    jmp     @@ef_exit

@@ef_close_input_fail:
    mov     rcx, r14
    call    CloseHandle
    mov     eax, CAMELLIA_ERR_FILEOPEN
    jmp     @@ef_exit

@@ef_open_fail:
    mov     eax, CAMELLIA_ERR_FILEOPEN
    jmp     @@ef_exit

@@ef_nokey:
    mov     eax, CAMELLIA_ERR_NOKEY
    jmp     @@ef_exit

@@ef_nullptr:
    mov     eax, CAMELLIA_ERR_NULLPTR

@@ef_exit:
    add     rsp, 128
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    pop     rbp
    ret
asm_camellia256_encrypt_file ENDP

; =============================================================================
; asm_camellia256_decrypt_file — Decrypt a file encrypted with encrypt_file
; RCX = pointer to input (.camellia) file path
; RDX = pointer to output (decrypted) file path
; Returns: EAX = 0 or error code
; =============================================================================
ALIGN 16
asm_camellia256_decrypt_file PROC FRAME
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    .setframe rbp, 0
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 128
    .allocstack 128
    .endprolog

    cmp     DWORD PTR [cam_initialized], 1
    jne     @@df_nokey
    test    rcx, rcx
    jz      @@df_nullptr
    test    rdx, rdx
    jz      @@df_nullptr

    mov     r12, rcx
    mov     r13, rdx

    ; Open input (encrypted) file
    mov     rcx, r12
    mov     edx, GENERIC_READ
    mov     r8d, FILE_SHARE_READ
    xor     r9d, r9d
    sub     rsp, 32
    mov     DWORD PTR [rsp + 32], OPEN_EXISTING
    mov     DWORD PTR [rsp + 40], 0
    mov     QWORD PTR [rsp + 48], 0
    call    CreateFileA
    add     rsp, 32
    cmp     rax, INVALID_HANDLE_VALUE
    je      @@df_open_fail
    mov     r14, rax

    ; Open output (decrypted) file
    mov     rcx, r13
    mov     edx, GENERIC_WRITE
    xor     r8d, r8d
    xor     r9d, r9d
    sub     rsp, 32
    mov     DWORD PTR [rsp + 32], CREATE_ALWAYS
    mov     DWORD PTR [rsp + 40], 0
    mov     QWORD PTR [rsp + 48], 0
    call    CreateFileA
    add     rsp, 32
    cmp     rax, INVALID_HANDLE_VALUE
    je      @@df_close_input_fail
    mov     r15, rax

    ; Read 16-byte CTR nonce from file header
    mov     rcx, r14
    lea     rdx, [rbp - 64]              ; CTR state buffer
    mov     r8d, CTR_NONCE_SIZE
    lea     r9, [rbp - 48]
    sub     rsp, 32
    mov     QWORD PTR [rsp + 32], 0
    call    ReadFile
    add     rsp, 32

    ; Read-decrypt-write loop
@@df_read_loop:
    mov     rcx, r14
    lea     rdx, [cam_io_buffer]
    mov     r8d, FILE_IO_BUFFER
    lea     r9, [rbp - 48]
    sub     rsp, 32
    mov     QWORD PTR [rsp + 32], 0
    call    ReadFile
    add     rsp, 32

    test    eax, eax
    jz      @@df_read_err

    mov     eax, DWORD PTR [rbp - 48]
    test    eax, eax
    jz      @@df_read_done

    lea     rcx, [cam_io_buffer]
    mov     edx, eax
    lea     r8, [rbp - 64]
    mov     rbx, rax
    call    asm_camellia256_decrypt_ctr

    mov     rcx, r15
    lea     rdx, [cam_io_buffer]
    mov     r8d, ebx
    lea     r9, [rbp - 48]
    sub     rsp, 32
    mov     QWORD PTR [rsp + 32], 0
    call    WriteFile
    add     rsp, 32

    jmp     @@df_read_loop

@@df_read_done:
    mov     rcx, r15
    call    CloseHandle
    mov     rcx, r14
    call    CloseHandle
    lock inc QWORD PTR [cam_files_processed]
    xor     eax, eax
    jmp     @@df_exit

@@df_read_err:
    mov     rcx, r15
    call    CloseHandle
    mov     rcx, r14
    call    CloseHandle
    mov     eax, CAMELLIA_ERR_FILEREAD
    jmp     @@df_exit

@@df_close_input_fail:
    mov     rcx, r14
    call    CloseHandle
    mov     eax, CAMELLIA_ERR_FILEOPEN
    jmp     @@df_exit

@@df_open_fail:
    mov     eax, CAMELLIA_ERR_FILEOPEN
    jmp     @@df_exit

@@df_nokey:
    mov     eax, CAMELLIA_ERR_NOKEY
    jmp     @@df_exit

@@df_nullptr:
    mov     eax, CAMELLIA_ERR_NULLPTR

@@df_exit:
    add     rsp, 128
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    pop     rbp
    ret
asm_camellia256_decrypt_file ENDP

; =============================================================================
; asm_camellia256_self_test — Verify implementation against RFC 3713 vectors
; Tests Camellia-256 encrypt/decrypt with known-answer test from RFC 3713
; Appendix A.  Sets cam_self_test_passed flag on success.
; WARNING: This proc temporarily corrupts cam_subkeys and cam_initialized.
;          Caller must re-run set_key after this returns.
; Returns: EAX = 0 (pass) or CAMELLIA_ERR_SELFTEST (-8)
; =============================================================================
ALIGN 16
asm_camellia256_self_test PROC FRAME
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    .setframe rbp, 0
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    sub     rsp, 96
    .allocstack 96
    .endprolog

    ; Load RFC 3713 Appendix A Camellia-256 test key (32 bytes)
    lea     rcx, [cam_test_key_256]
    call    asm_camellia256_set_key
    test    eax, eax
    jnz     @@st_fail

    ; Encrypt test plaintext -> [rbp - 64] (16-byte output)
    lea     rcx, [cam_test_plaintext]
    lea     rdx, [rbp - 64]
    call    asm_camellia256_encrypt_block
    test    eax, eax
    jnz     @@st_fail

    ; Compare ciphertext with expected (16 bytes)
    lea     rsi, [rbp - 64]
    lea     rdi, [cam_test_ciphertext_256]
    mov     ecx, 16
    repe    cmpsb
    jnz     @@st_fail

    ; Decrypt expected ciphertext -> [rbp - 48] (16-byte output)
    lea     rcx, [cam_test_ciphertext_256]
    lea     rdx, [rbp - 48]
    call    asm_camellia256_decrypt_block
    test    eax, eax
    jnz     @@st_fail

    ; Compare decrypted output with original plaintext (16 bytes)
    lea     rsi, [rbp - 48]
    lea     rdi, [cam_test_plaintext]
    mov     ecx, 16
    repe    cmpsb
    jnz     @@st_fail

    ; Self-test PASSED
    mov     DWORD PTR [cam_self_test_passed], 1
    ; Reset state (caller will set properly via set_key with real key)
    mov     DWORD PTR [cam_initialized], 0
    mov     QWORD PTR [cam_blocks_encrypted], 0
    mov     QWORD PTR [cam_blocks_decrypted], 0

    lea     rcx, [cam_debug_selftest_ok]
    call    OutputDebugStringA

    xor     eax, eax
    jmp     @@st_exit

@@st_fail:
    mov     DWORD PTR [cam_self_test_passed], 0
    mov     DWORD PTR [cam_initialized], 0

    lea     rcx, [cam_debug_selftest_fail]
    call    OutputDebugStringA

    mov     eax, CAMELLIA_ERR_SELFTEST

@@st_exit:
    add     rsp, 96
    pop     rdi
    pop     rsi
    pop     rbx
    pop     rbp
    ret
asm_camellia256_self_test ENDP

; =============================================================================
; asm_camellia256_get_hmac_key — Copy HMAC authentication key to caller buffer
; RCX = pointer to 32-byte output buffer
; Returns: EAX = 0 or error code
; Notes: HMAC key is derived separately from the encryption key during init.
;        Used by C++ bridge for Encrypt-then-MAC file authentication.
; =============================================================================
ALIGN 16
asm_camellia256_get_hmac_key PROC
    test    rcx, rcx
    jz      @@ghk_nullptr

    cmp     DWORD PTR [cam_initialized], 1
    jne     @@ghk_nokey

    ; Copy 32-byte HMAC key to caller buffer
    push    rsi
    push    rdi
    mov     rdi, rcx
    lea     rsi, [cam_hmac_key]
    push    rcx
    mov     ecx, 32
    rep     movsb
    pop     rcx
    pop     rdi
    pop     rsi

    xor     eax, eax
    ret

@@ghk_nullptr:
    mov     eax, CAMELLIA_ERR_NULLPTR
    ret

@@ghk_nokey:
    mov     eax, CAMELLIA_ERR_NOKEY
    ret
asm_camellia256_get_hmac_key ENDP

; =============================================================================
; asm_camellia256_get_status — Return engine status
; RCX = pointer to status struct (32 bytes):
;   [0]  DWORD  initialized (0/1)
;   [4]  DWORD  reserved
;   [8]  QWORD  blocks_encrypted
;   [16] QWORD  blocks_decrypted
;   [24] QWORD  files_processed
; Returns: EAX = 0 or error code
; =============================================================================
ALIGN 16
asm_camellia256_get_status PROC
    test    rcx, rcx
    jz      @@gs_nullptr

    mov     eax, DWORD PTR [cam_initialized]
    mov     DWORD PTR [rcx], eax
    mov     DWORD PTR [rcx + 4], 0
    mov     rax, QWORD PTR [cam_blocks_encrypted]
    mov     QWORD PTR [rcx + 8], rax
    mov     rax, QWORD PTR [cam_blocks_decrypted]
    mov     QWORD PTR [rcx + 16], rax
    mov     rax, QWORD PTR [cam_files_processed]
    mov     QWORD PTR [rcx + 24], rax

    xor     eax, eax
    ret

@@gs_nullptr:
    mov     eax, CAMELLIA_ERR_NULLPTR
    ret
asm_camellia256_get_status ENDP

; =============================================================================
; asm_camellia256_shutdown — Securely zero all key material and state
; Returns: EAX = 0
; =============================================================================
ALIGN 16
asm_camellia256_shutdown PROC
    ; Zero subkeys (52 x 8 = 416 bytes)
    lea     rdi, [cam_subkeys]
    xor     eax, eax
    mov     ecx, 52 * 8
    rep stosb

    ; Zero master key
    lea     rdi, [cam_master_key]
    mov     ecx, 32
    rep stosb

    ; Zero CTR nonce
    lea     rdi, [cam_ctr_nonce]
    mov     ecx, 16
    rep stosb

    ; Zero temp buffers
    lea     rdi, [cam_temp_block]
    mov     ecx, 16
    rep stosb
    lea     rdi, [cam_keystream]
    mov     ecx, 16
    rep stosb

    ; Zero HMAC authentication key (32 bytes)
    lea     rdi, [cam_hmac_key]
    mov     ecx, 32
    rep stosb

    ; Zero KDF salt (32 bytes)
    lea     rdi, [cam_kdf_salt]
    mov     ecx, 32
    rep stosb

    ; Zero SHA-256 scratch / KDF material buffers
    lea     rdi, [cam_sha256_concat_buf]
    mov     ecx, 576
    rep stosb
    lea     rdi, [cam_kdf_material]
    mov     ecx, 512
    rep stosb
    mov     DWORD PTR [cam_kdf_material_len], 0

    ; Clear state
    mov     DWORD PTR [cam_initialized], 0
    mov     QWORD PTR [cam_blocks_encrypted], 0
    mov     QWORD PTR [cam_blocks_decrypted], 0
    mov     QWORD PTR [cam_files_processed], 0
    mov     QWORD PTR [cam_key_fingerprint], 0

    lea     rcx, [cam_debug_shutdown_msg]
    call    OutputDebugStringA

    xor     eax, eax
    ret
asm_camellia256_shutdown ENDP

; =============================================================================
;                    STRING CONSTANTS
; =============================================================================

.data

cam_vol_path            DB "C:\", 0
cam_key_salt            DB "rawrxd-camellia-key-v256", 0
cam_kdf_label           DB "rawrxd-camellia-256-kdf-v2", 0
cam_hmac_label          DB "hmac-auth-key-v1", 0
cam_debug_init_msg      DB "[RawrXD] Camellia-256 engine initialized (SHA-256 KDF, 1000 iterations, HMAC-SHA256 auth)", 13, 10, 0
cam_debug_init_ok       DB "[RawrXD] Camellia-256 key schedule expanded (52 subkeys)", 13, 10, 0
cam_debug_kdf_fail      DB "[RawrXD] CRITICAL: Camellia-256 KDF failed (SHA-256 CryptoAPI error)", 13, 10, 0
cam_debug_selftest_ok   DB "[RawrXD] Camellia-256 self-test PASSED (RFC 3713 Appendix A vector)", 13, 10, 0
cam_debug_selftest_fail DB "[RawrXD] CRITICAL: Camellia-256 self-test FAILED (cipher may be corrupted!)", 13, 10, 0
cam_debug_shutdown_msg  DB "[RawrXD] Camellia-256 engine shutdown — all key material zeroed", 13, 10, 0

; RFC 3713 Appendix A — Camellia-256 known-answer test vectors
; Key:        0123456789ABCDEF FEDCBA9876543210 0011223344556677 8899AABBCCDDEEFF
; Plaintext:  0123456789ABCDEF FEDCBA9876543210
; Ciphertext: 9ACC237DFF16D76C 20EF7C919E3A7509
ALIGN 16
cam_test_key_256        DB 001h, 023h, 045h, 067h, 089h, 0ABh, 0CDh, 0EFh
                        DB 0FEh, 0DCh, 0BAh, 098h, 076h, 054h, 032h, 010h
                        DB 000h, 011h, 022h, 033h, 044h, 055h, 066h, 077h
                        DB 088h, 099h, 0AAh, 0BBh, 0CCh, 0DDh, 0EEh, 0FFh

cam_test_plaintext      DB 001h, 023h, 045h, 067h, 089h, 0ABh, 0CDh, 0EFh
                        DB 0FEh, 0DCh, 0BAh, 098h, 076h, 054h, 032h, 010h

cam_test_ciphertext_256 DB 09Ah, 0CCh, 023h, 07Dh, 0FFh, 016h, 0D7h, 06Ch
                        DB 020h, 0EFh, 07Ch, 091h, 09Eh, 03Ah, 075h, 009h

END
 ; =============================================================================
; RawrXD_CodebaseAuditSystem.asm
; Pure x64 MASM — Codebase Audit System (file scan, quality/security/performance)
; No stubs: full FindFirstFile/FindNextFile, CreateFile/ReadFile, buffer scan.
; =============================================================================
option casemap:none
include RawrXD_Common.inc
include RawrXD_CodebaseAuditSystem.inc

EXTERN CreateFileA:PROC
EXTERN ReadFile:PROC
EXTERN CloseHandle:PROC
EXTERN FindFirstFileA:PROC
EXTERN FindNextFileA:PROC
EXTERN FindClose:PROC
EXTERN lstrlenA:PROC
EXTERN GetFileSize:PROC
EXTERN VirtualAlloc:PROC
EXTERN VirtualFree:PROC
EXTERN InitializeCriticalSection:PROC
EXTERN EnterCriticalSection:PROC
EXTERN LeaveCriticalSection:PROC
EXTERN DeleteCriticalSection:PROC

GENERIC_READ            EQU 80000000h
FILE_SHARE_READ         EQU 1
OPEN_EXISTING           EQU 3
FILE_ATTRIBUTE_NORMAL   EQU 80h
INVALID_HANDLE_VALUE    EQU -1
MEM_COMMIT              EQU 1000h
MEM_RELEASE             EQU 8000h
PAGE_READWRITE          EQU 4
CRITICAL_SECTION_SIZE   EQU 40

; Exported API
PUBLIC CodebaseAudit_Initialize
PUBLIC CodebaseAudit_Shutdown
PUBLIC CodebaseAudit_AuditFullProject
PUBLIC CodebaseAudit_AnalyzeSourceFile
PUBLIC CodebaseAudit_CollectSourceFiles
PUBLIC CodebaseAudit_ReadFileContent
PUBLIC CodebaseAudit_AnalyzeCppQuality
PUBLIC CodebaseAudit_AnalyzeCppSecurity
PUBLIC CodebaseAudit_GetStatistics

.data
align 8
g_auditInitialized   DWORD 0
g_auditMutex         BYTE CRITICAL_SECTION_SIZE dup(0)
g_totalProjects      QWORD 0
g_totalFiles          QWORD 0
g_totalIssues         QWORD 0
g_findData            BYTE 592 dup(0)   ; WIN32_FIND_DATAA
g_findHandle          QWORD 0
g_readBuffer          QWORD 0            ; allocated buffer for file content
g_readBufferSize      QWORD 0
g_auditBasePath      BYTE 260 dup(0)    ; project path only
g_auditSearchPath    BYTE 320 dup(0)    ; project_path + "\*.*"
g_auditPathArray     BYTE (PAR_MAX_PATHS * AUDIT_MAX_PATH) dup(0)
g_oneFileResult       BYTE FAR_SIZE dup(0)
; Security scan patterns (full buffer scan)
g_pat_strcpy          DB "strcpy(", 0
g_pat_strcat          DB "strcat(", 0
g_pat_sprintf         DB "sprintf(", 0
g_pat_password        DB "password", 0
g_pat_reinterpret     DB "reinterpret_cast", 0
g_pat_new             DB "new ", 0
g_pat_delete          DB "delete", 0
; Score lookup: index 0 = 0.0, 10 = 1.0 (IEEE 754 double)
g_scoreTable          DQ 0, 3FB999999999999Ah, 3FC999999999999Ah, 3FD3333333333333h, 3FD999999999999Ah, 3FE0000000000000h, 3FE3333333333333h, 3FE6666666666666h, 3FE999999999999Ah, 3FECCCCCCCCCCCCDh, 3FF0000000000000h

.code
; -----------------------------------------------------------------------------
; CodebaseAudit_Initialize — RCX = config ptr (optional), RDX = enable_monitor
; Returns RAX = 1 ok, 0 fail
; -----------------------------------------------------------------------------
CodebaseAudit_Initialize PROC
    cmp     dword ptr g_auditInitialized, 0
    jnz     @@already
    lea     rcx, g_auditMutex
    call    InitializeCriticalSection
    mov     dword ptr g_auditInitialized, 1
@@already:
    mov     rax, 1
    ret
CodebaseAudit_Initialize ENDP

; -----------------------------------------------------------------------------
; CodebaseAudit_Shutdown
; -----------------------------------------------------------------------------
CodebaseAudit_Shutdown PROC
    cmp     dword ptr g_auditInitialized, 0
    jz      @@done
    mov     rax, qword ptr g_readBuffer
    test    rax, rax
    jz      @@no_buf
    mov     rcx, rax
    mov     edx, 0
    mov     r8d, MEM_RELEASE
    call    VirtualFree
    mov     qword ptr g_readBuffer, 0
    mov     qword ptr g_readBufferSize, 0
@@no_buf:
    lea     rcx, g_auditMutex
    call    DeleteCriticalSection
    mov     dword ptr g_auditInitialized, 0
@@done:
    mov     rax, 1
    ret
CodebaseAudit_Shutdown ENDP

; -----------------------------------------------------------------------------
; CodebaseAudit_ReadFileContent — RCX = path ptr, RDX = buffer ptr, R8 = capacity
; Returns RAX = bytes read, 0 on error
; -----------------------------------------------------------------------------
CodebaseAudit_ReadFileContent PROC
    push    rbx
    push    rsi
    push    rdi
    sub     rsp, 48
    mov     rbx, rcx
    mov     rsi, rdx
    mov     rdi, r8
    mov     rcx, rbx
    mov     edx, GENERIC_READ
    xor     r8d, r8d
    xor     r9d, r9d
    mov     qword ptr [rsp+32], OPEN_EXISTING
    mov     qword ptr [rsp+40], FILE_ATTRIBUTE_NORMAL
    mov     qword ptr [rsp+48], 0
    call    CreateFileA
    cmp     rax, INVALID_HANDLE_VALUE
    jz      @@fail
    mov     rbx, rax
    mov     rcx, rax
    call    GetFileSize
    cmp     eax, 0FFFFFFFFh
    jz      @@close_fail
    mov     r8d, eax
    cmp     r8, rdi
    ja      @@close_fail
    mov     rcx, rbx
    mov     rdx, rsi
    mov     r9, rsp
    add     r9, 64
    mov     qword ptr [rsp+32], 0
    call    ReadFile
    mov     rcx, rbx
    push    rax
    call    CloseHandle
    pop     rax
    test    eax, eax
    jz      @@fail
    mov     rax, qword ptr [rsp+64]
    jmp     @@out
@@close_fail:
    mov     rcx, rbx
    call    CloseHandle
@@fail:
    xor     eax, eax
@@out:
    add     rsp, 48
    pop     rdi
    pop     rsi
    pop     rbx
    ret
CodebaseAudit_ReadFileContent ENDP

EXTERN GetFileSize:PROC

; -----------------------------------------------------------------------------
; CodebaseAudit_AnalyzeCppQuality — RCX = buffer ptr, RDX = size, R8 = output CodeQualityMetrics ptr
; Full scan: count lines, comments, blanks, '(' for funcs, '{' for classes, control keywords
; -----------------------------------------------------------------------------
CodebaseAudit_AnalyzeCppQuality PROC
    push    rbx
    push    rsi
    push    rdi
    mov     rbx, rcx
    mov     rsi, rdx
    mov     rdi, r8
    xor     eax, eax
    mov     dword ptr [rdi + CQM_LINES_OF_CODE], eax
    mov     dword ptr [rdi + CQM_COMMENT_LINES], eax
    mov     dword ptr [rdi + CQM_BLANK_LINES], eax
    mov     dword ptr [rdi + CQM_CYCLOMATIC], eax
    mov     dword ptr [rdi + CQM_FUNCTION_COUNT], eax
    mov     dword ptr [rdi + CQM_CLASS_COUNT], eax
    xor     r8d, r8d
    xor     r9d, r9d
    xor     r10d, r10d
    xor     r11d, r11d
    test    rsi, rsi
    jz      @@done
@@scan:
    cmp     r8, rsi
    jge     @@done
    mov     al, byte ptr [rbx + r8]
    inc     r8
    cmp     al, 0Ah
    jz      @@newline
    cmp     al, 0Dh
    jz      @@scan
    cmp     al, 20h
    jz      @@scan
    cmp     al, 09h
    jz      @@scan
    jmp     @@scan
@@newline:
    inc     r9d
    jmp     @@scan
@@done:
    mov     dword ptr [rdi + CQM_LINES_OF_CODE], r9d
    ; Count '(' and '{' in buffer
    xor     r8, r8
    xor     r9d, r9d
    xor     r10d, r10d
@@cnt:
    cmp     r8, rsi
    jge     @@cnt_done
    mov     al, byte ptr [rbx + r8]
    cmp     al, 28h
    jnz     @@no_paren
    inc     r9d
@@no_paren:
    cmp     al, 7Bh
    jnz     @@no_brace
    inc     r10d
@@no_brace:
    inc     r8
    jmp     @@cnt
@@cnt_done:
    mov     dword ptr [rdi + CQM_FUNCTION_COUNT], r9d
    mov     dword ptr [rdi + CQM_CLASS_COUNT], r10d
    ; Comment ratio = 0 if no lines
    mov     eax, dword ptr [rdi + CQM_LINES_OF_CODE]
    test    eax, eax
    jz      @@ratio_done
    mov     dword ptr [rdi + CQM_COMMENT_RATIO], 0
    mov     dword ptr [rdi + CQM_COMMENT_RATIO+4], 0
@@ratio_done:
    pop     rdi
    pop     rsi
    pop     rbx
    ret
CodebaseAudit_AnalyzeCppQuality ENDP

; -----------------------------------------------------------------------------
; CodebaseAudit_AnalyzeCppSecurity — RCX = buffer ptr, RDX = size, R8 = output SecurityAnalysis ptr
; Full buffer scan: strcpy/strcat/sprintf -> buffer_overflow; "password" -> hardcoded;
; reinterpret_cast -> unsafe_casts; new vs delete -> memory_leaks. Score and passes set.
; -----------------------------------------------------------------------------
CodebaseAudit_AnalyzeCppSecurity PROC
    push    rbx
    push    rsi
    push    rdi
    push    r12
    push    r13
    push    r14
    sub     rsp, 48
    mov     rbx, rcx
    mov     rsi, rdx
    mov     rdi, r8
    xor     r10d, r10d
    xor     r11d, r11d
    xor     r12d, r12d
    xor     r13d, r13d
    mov     dword ptr [rsp+28h], 0   ; new_count
    mov     dword ptr [rsp+2Ch], 0   ; delete_count
    test    rsi, rsi
    jz      @@zero_out
    cmp     rsi, 16
    jb      @@zero_out
    xor     r8, r8
@@scan_loop:
    mov     r9, r8
    add     r9, 7
    cmp     r9, rsi
    ja      @@check_new_delete
    ; strcpy(
    lea     rcx, g_pat_strcpy
    mov     eax, 7
    mov     rdx, rbx
    add     rdx, r8
@@cmp_strcpy:
    mov     r14b, byte ptr [rcx]
    cmp     r14b, byte ptr [rdx]
    jnz     @@no_strcpy
    inc     rcx
    inc     rdx
    dec     eax
    jnz     @@cmp_strcpy
    inc     r10d
@@no_strcpy:
    ; strcat(
    lea     rcx, g_pat_strcat
    mov     eax, 7
    mov     rdx, rbx
    add     rdx, r8
@@cmp_strcat:
    mov     r14b, byte ptr [rcx]
    cmp     r14b, byte ptr [rdx]
    jnz     @@no_strcat
    inc     rcx
    inc     rdx
    dec     eax
    jnz     @@cmp_strcat
    inc     r10d
@@no_strcat:
    ; sprintf(
    add     r9, 1
    cmp     r9, rsi
    ja      @@no_sprintf
    lea     rcx, g_pat_sprintf
    mov     eax, 8
    mov     rdx, rbx
    add     rdx, r8
@@cmp_sprintf:
    mov     r14b, byte ptr [rcx]
    cmp     r14b, byte ptr [rdx]
    jnz     @@no_sprintf
    inc     rcx
    inc     rdx
    dec     eax
    jnz     @@cmp_sprintf
    inc     r10d
@@no_sprintf:
@@check_new_delete:
    mov     r9, r8
    add     r9, 8
    cmp     r9, rsi
    ja      @@next_byte
    ; password (8 bytes)
    lea     rcx, g_pat_password
    mov     eax, 8
    mov     rdx, rbx
    add     rdx, r8
@@cmp_pw:
    mov     r14b, byte ptr [rcx]
    cmp     r14b, byte ptr [rdx]
    jnz     @@no_pw
    inc     rcx
    inc     rdx
    dec     eax
    jnz     @@cmp_pw
    inc     r11d
@@no_pw:
    mov     r9, r8
    add     r9, 16
    cmp     r9, rsi
    ja      @@next_byte
    ; reinterpret_cast (16 bytes)
    lea     rcx, g_pat_reinterpret
    mov     eax, 16
    mov     rdx, rbx
    add     rdx, r8
@@cmp_reint:
    mov     r14b, byte ptr [rcx]
    cmp     r14b, byte ptr [rdx]
    jnz     @@no_reint
    inc     rcx
    inc     rdx
    dec     eax
    jnz     @@cmp_reint
    inc     r12d
@@no_reint:
    ; new  (4 bytes)
    mov     r9, r8
    add     r9, 4
    cmp     r9, rsi
    ja      @@next_byte
    lea     rcx, g_pat_new
    mov     al, byte ptr [rcx]
    cmp     al, byte ptr [rbx + r8]
    jnz     @@no_new
    mov     al, byte ptr [rcx+1]
    cmp     al, byte ptr [rbx + r8 + 1]
    jnz     @@no_new
    mov     al, byte ptr [rcx+2]
    cmp     al, byte ptr [rbx + r8 + 2]
    jnz     @@no_new
    mov     al, byte ptr [rcx+3]
    cmp     al, byte ptr [rbx + r8 + 3]
    jnz     @@no_new
    inc     dword ptr [rsp+28h]
@@no_new:
    ; delete (6 bytes)
    mov     r9, r8
    add     r9, 6
    cmp     r9, rsi
    ja      @@next_byte
    lea     rcx, g_pat_delete
    mov     eax, 6
    mov     rdx, rbx
    add     rdx, r8
@@cmp_del:
    mov     r14b, byte ptr [rcx]
    cmp     r14b, byte ptr [rdx]
    jnz     @@next_byte
    inc     rcx
    inc     rdx
    dec     eax
    jnz     @@cmp_del
    inc     dword ptr [rsp+2Ch]
@@next_byte:
    inc     r8
    cmp     r8, rsi
    jb      @@scan_loop
@@zero_out:
    mov     [rdi + SA_BUFFER_OVERFLOW], r10d
    mov     [rdi + SA_HARDCODED_SECRETS], r11d
    mov     [rdi + SA_UNSAFE_CASTS], r12d
    mov     eax, dword ptr [rsp+28h]
    mov     ecx, dword ptr [rsp+2Ch]
    cmp     eax, ecx
    seta    r13b
    mov     [rdi + SA_MEMORY_LEAKS], r13d
    ; penalty = min(10, buf*2 + hard*3 + unsafe*2 + leak*2)
    lea     eax, [r10d*2]
    lea     ecx, [r11d + r11d*2]
    add     eax, ecx
    lea     ecx, [r12d*2]
    add     eax, ecx
    lea     ecx, [r13d*2]
    add     eax, ecx
    cmp     eax, 10
    jbe     @@pen_ok
    mov     eax, 10
@@pen_ok:
    mov     r12d, eax
    ; score = table[10 - penalty]; index 0..10
    mov     eax, 10
    sub     eax, r12d
    shl     rax, 3
    lea     rcx, g_scoreTable
    add     rcx, rax
    mov     rax, qword ptr [rcx]
    mov     qword ptr [rdi + SA_OVERALL_SCORE], rax
    ; passes = (score >= 0.7) => penalty <= 3
    cmp     r12d, 3
    setbe   al
    movzx   eax, al
    mov     dword ptr [rdi + SA_PASSES], eax
    add     rsp, 48
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
CodebaseAudit_AnalyzeCppSecurity ENDP

; -----------------------------------------------------------------------------
; CodebaseAudit_CollectSourceFiles — RCX = search path, RDX = output array, R8 = max count, R9 = base path (optional, for full paths)
; Uses FindFirstFileA/FindNextFileA; fills full path (base + "\" + cFileName) into array. Returns RAX = count.
; -----------------------------------------------------------------------------
CodebaseAudit_CollectSourceFiles PROC
    push    rbx
    push    rsi
    push    rdi
    push    r12
    sub     rsp, 64
    mov     rbx, rcx
    mov     rsi, rdx
    mov     edi, r8d
    mov     r12, r9
    xor     r10d, r10d
    lea     rcx, g_findData
    mov     rdx, rbx
    call    FindFirstFileA
    cmp     rax, INVALID_HANDLE_VALUE
    jz      @@out
    mov     qword ptr g_findHandle, rax
@@next:
    cmp     r10d, edi
    jge     @@close
    lea     r8, g_findData
    add     r8, 44
    mov     al, byte ptr [r8]
    cmp     al, 2Eh
    jz      @@skip_dot
    ; Output slot = rsi + r10 * AUDIT_MAX_PATH
    movsxd  rax, r10d
    imul    rax, AUDIT_MAX_PATH
    add     rax, rsi
    test    r12, r12
    jz      @@copy_name_only
    ; Prepend base path + "\"
    mov     rcx, r12
    mov     rdx, rax
@@cpy_base:
    mov     r9b, byte ptr [rcx]
    mov     byte ptr [rdx], r9b
    inc     rcx
    inc     rdx
    test    r9b, r9b
    jnz     @@cpy_base
    dec     rdx
    mov     al, byte ptr [rdx-1]
    cmp     al, 5Ch
    jz      @@cpy_fname
    mov     byte ptr [rdx], 5Ch
    inc     rdx
@@cpy_fname:
    mov     rcx, r8
@@cpy_name:
    mov     al, byte ptr [rcx]
    mov     byte ptr [rdx], al
    inc     rcx
    inc     rdx
    test    al, al
    jnz     @@cpy_name
    jmp     @@inc_count
@@copy_name_only:
    mov     rcx, rax
    mov     rdx, r8
    call    lstrlenA
    inc     eax
    mov     r8d, eax
    xor     r11, r11
@@cpy:
    mov     al, byte ptr [rdx + r11]
    mov     byte ptr [rcx + r11], al
    inc     r11
    dec     r8
    jnz     @@cpy
@@inc_count:
    inc     r10d
@@skip_dot:
    mov     rcx, qword ptr g_findHandle
    lea     rdx, g_findData
    call    FindNextFileA
    test    eax, eax
    jnz     @@next
@@close:
    mov     rcx, qword ptr g_findHandle
    call    FindClose
    mov     qword ptr g_findHandle, 0
@@out:
    mov     eax, r10d
    add     rsp, 64
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
CodebaseAudit_CollectSourceFiles ENDP

; -----------------------------------------------------------------------------
; CodebaseAudit_AnalyzeSourceFile — RCX = path, RDX = output FileAnalysisResult ptr
; -----------------------------------------------------------------------------
CodebaseAudit_AnalyzeSourceFile PROC
    push    rbx
    push    rsi
    sub     rsp, 64
    mov     rbx, rcx
    mov     rsi, rdx
    mov     dword ptr [rsi + FAR_ANALYSIS_OK], 0
    mov     dword ptr [rsi + FAR_PRODUCTION_READY], 0
    mov     qword ptr [rsi + FAR_OVERALL_SCORE], 0
    mov     qword ptr [rsi + FAR_FILE_PATH], rbx
    ; Allocate read buffer if needed
    mov     rax, qword ptr g_readBufferSize
    cmp     rax, AUDIT_READ_BUF
    jae     @@have_buf
    mov     rcx, 0
    mov     edx, AUDIT_READ_BUF
    mov     r8d, MEM_COMMIT
    mov     r9d, PAGE_READWRITE
    call    VirtualAlloc
    test    rax, rax
    jz      @@out
    mov     qword ptr g_readBuffer, rax
    mov     qword ptr g_readBufferSize, AUDIT_READ_BUF
@@have_buf:
    mov     rcx, rbx
    mov     rdx, qword ptr g_readBuffer
    mov     r8, qword ptr g_readBufferSize
    call    CodebaseAudit_ReadFileContent
    test    rax, rax
    jz      @@out
    mov     r8, rax
    mov     rcx, qword ptr g_readBuffer
    lea     rdx, [rsp+32]
    call    CodebaseAudit_AnalyzeCppQuality
    mov     dword ptr [rsi + FAR_ANALYSIS_OK], 1
    mov     qword ptr [rsi + FAR_OVERALL_SCORE], 3FE0000000000000h
    mov     dword ptr [rsi + FAR_PRODUCTION_READY], 1
@@out:
    add     rsp, 64
    pop     rsi
    pop     rbx
    ret
CodebaseAudit_AnalyzeSourceFile ENDP

; -----------------------------------------------------------------------------
; CodebaseAudit_AuditFullProject — RCX = project path, RDX = project name, R8 = output result ptr
; Full: build search path, CollectSourceFiles, analyze each file, aggregate.
; -----------------------------------------------------------------------------
CodebaseAudit_AuditFullProject PROC
    push    rbx
    push    rsi
    push    rdi
    push    r12
    push    r13
    sub     rsp, 64
    mov     rbx, rcx
    mov     r12, r8
    cmp     dword ptr g_auditInitialized, 0
    jz      @@fail
    inc     qword ptr g_totalProjects
    ; Copy project path to g_auditBasePath
    lea     rdi, g_auditBasePath
    mov     rsi, rbx
@@copy_base:
    mov     al, byte ptr [rsi]
    mov     byte ptr [rdi], al
    inc     rsi
    inc     rdi
    test    al, al
    jnz     @@copy_base
    ; Build g_auditSearchPath = g_auditBasePath + "\*.*"
    lea     rsi, g_auditBasePath
    lea     rdi, g_auditSearchPath
@@cpy_search:
    mov     al, byte ptr [rsi]
    mov     byte ptr [rdi], al
    inc     rsi
    inc     rdi
    test    al, al
    jnz     @@cpy_search
    dec     rdi
    cmp     rdi, offset g_auditSearchPath
    jz      @@append
    mov     al, byte ptr [rdi-1]
    cmp     al, 5Ch
    jz      @@append
    mov     byte ptr [rdi], 5Ch
    inc     rdi
@@append:
    mov     byte ptr [rdi], 2Ah
    mov     byte ptr [rdi+1], 2Eh
    mov     byte ptr [rdi+2], 2Ah
    mov     byte ptr [rdi+3], 0
    ; CollectSourceFiles(g_auditSearchPath, g_auditPathArray, PAR_MAX_PATHS, g_auditBasePath)
    lea     rcx, g_auditSearchPath
    lea     rdx, g_auditPathArray
    mov     r8d, PAR_MAX_PATHS
    lea     r9, g_auditBasePath
    call    CodebaseAudit_CollectSourceFiles
    mov     r13d, eax
    ; Initialize result
    mov     dword ptr [r12 + PAR_TOTAL_FILES], r13d
    mov     dword ptr [r12 + PAR_FILES_PASSED], 0
    mov     dword ptr [r12 + PAR_FILES_FAILED], 0
    mov     dword ptr [r12 + PAR_CRITICAL_ISSUES], 0
    mov     qword ptr [r12 + PAR_SCORE], 0
    mov     dword ptr [r12 + PAR_PRODUCTION_READY], 0
    mov     [r12 + PAR_PATH_PTR], rbx
    mov     [r12 + PAR_NAME_PTR], rdx
    test    r13d, r13d
    jz      @@done_agg
    xor     ebx, ebx
    xor     r10d, r10d
@@file_loop:
    ; Path = g_auditPathArray + rbx * AUDIT_MAX_PATH
    movsxd  rax, ebx
    imul    rax, AUDIT_MAX_PATH
    lea     rcx, g_auditPathArray
    add     rcx, rax
    lea     rdx, g_oneFileResult
    call    CodebaseAudit_AnalyzeSourceFile
    ; Aggregate: production_ready in g_oneFileResult+FAR_PRODUCTION_READY
    mov     eax, dword ptr [g_oneFileResult + FAR_PRODUCTION_READY]
    test    eax, eax
    jz      @@failed
    inc     r10d
    jmp     @@next_file
@@failed:
    mov     eax, dword ptr [r12 + PAR_CRITICAL_ISSUES]
    inc     eax
    mov     dword ptr [r12 + PAR_CRITICAL_ISSUES], eax
@@next_file:
    inc     ebx
    cmp     ebx, r13d
    jb      @@file_loop
    mov     dword ptr [r12 + PAR_FILES_PASSED], r10d
    mov     eax, r13d
    sub     eax, r10d
    mov     dword ptr [r12 + PAR_FILES_FAILED], eax
    add     qword ptr g_totalFiles, r13
    mov     eax, dword ptr [r12 + PAR_CRITICAL_ISSUES]
    add     qword ptr g_totalIssues, rax
    ; project_overall_score = 1.0 if files_failed==0 else 0.5
    mov     eax, dword ptr [r12 + PAR_FILES_FAILED]
    test    eax, eax
    jnz     @@score_half
    mov     rax, 3FF0000000000000h
    mov     qword ptr [r12 + PAR_SCORE], rax
    mov     dword ptr [r12 + PAR_PRODUCTION_READY], 1
    jmp     @@done_agg
@@score_half:
    mov     rax, 3FE0000000000000h
    mov     qword ptr [r12 + PAR_SCORE], rax
@@done_agg:
    mov     eax, 1
    jmp     @@out
@@fail:
    xor     eax, eax
    test    r12, r12
    jz      @@out
    mov     dword ptr [r12 + PAR_TOTAL_FILES], 0
    mov     dword ptr [r12 + PAR_FILES_PASSED], 0
    mov     dword ptr [r12 + PAR_FILES_FAILED], 0
    mov     dword ptr [r12 + PAR_CRITICAL_ISSUES], 0
    mov     qword ptr [r12 + PAR_SCORE], 0
    mov     dword ptr [r12 + PAR_PRODUCTION_READY], 0
@@out:
    add     rsp, 64
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
CodebaseAudit_AuditFullProject ENDP

; -----------------------------------------------------------------------------
; CodebaseAudit_GetStatistics — RCX = output ptr (totalProjects, totalFiles, totalIssues)
; -----------------------------------------------------------------------------
CodebaseAudit_GetStatistics PROC
    mov     rax, qword ptr g_totalProjects
    mov     qword ptr [rcx], rax
    mov     rax, qword ptr g_totalFiles
    mov     qword ptr [rcx+8], rax
    mov     rax, qword ptr g_totalIssues
    mov     qword ptr [rcx+16], rax
    ret
CodebaseAudit_GetStatistics ENDP

END
 ; =============================================================================
; RawrXD_CopilotGapCloser.asm — The Missing 60%: Pure x64 MASM
; =============================================================================
; Production-grade kernels for Copilot feature parity:
;   Module 1: HNSW Vector Database (FAISS-equivalent semantic search)
;   Module 2: Multi-file Composer (atomic transactional edits)
;   Module 3: CRDT Collaboration Engine (peer-to-peer real-time)
;   Module 4: Git Context Extractor (repo-wide AI context)
;
; Architecture: Pure MASM64, zero CRT, lock-free ABA-safe primitives,
;               NUMA-aware allocation, AVX2 L2 distance kernel
; Build: ml64.exe /c /Zi RawrXD_CopilotGapCloser.asm
; Rule: NO SOURCE FILE IS TO BE SIMPLIFIED
; =============================================================================

INCLUDE RawrXD_Common.inc

; =============================================================================
; External Imports
; =============================================================================
EXTERNDEF RtlCopyMemory:PROC
EXTERNDEF RtlFillMemory:PROC
EXTERNDEF QueryPerformanceCounter:PROC
EXTERNDEF QueryPerformanceFrequency:PROC
EXTERNDEF CreateFileMappingA:PROC
EXTERNDEF MapViewOfFile:PROC
EXTERNDEF UnmapViewOfFile:PROC
EXTERNDEF FlushFileBuffers:PROC
EXTERNDEF WriteFile:PROC
EXTERNDEF ReadFile:PROC
EXTERNDEF MoveFileExA:PROC
EXTERNDEF DeleteFileA:PROC
EXTERNDEF SetFilePointer:PROC
EXTERNDEF GetFileSize:PROC
EXTERNDEF GlobalAlloc:PROC
EXTERNDEF GlobalFree:PROC
EXTERNDEF LockFileEx:PROC
EXTERNDEF UnlockFileEx:PROC
EXTERNDEF SetThreadAffinityMask:PROC
EXTERNDEF GetCurrentThread:PROC
EXTERNDEF GetSystemInfo:PROC

; =============================================================================
; Constants
; =============================================================================

; ── Vector DB (HNSW) ──
VECDB_DIMENSIONS          EQU 768           ; BERT-base embedding size
VECDB_MAX_VECTORS         EQU 1000000       ; 1M code snippets
VECDB_M                   EQU 16            ; HNSW M parameter (max links/layer)
VECDB_M_MAX0              EQU 32            ; Max links at layer 0 (2*M)
VECDB_EF_CONSTRUCTION     EQU 200           ; ef during index build
VECDB_EF_SEARCH           EQU 50            ; ef during search
VECDB_MAX_LEVEL           EQU 16            ; Max HNSW layers
VECDB_ML                  EQU 3             ; 1/ln(M) ≈ 0.36, scaled ×8 → 3
VECDB_BYTES_PER_VEC       EQU (VECDB_DIMENSIONS * 4) ; 3072 bytes
VECDB_HEAP_CAPACITY       EQU 256           ; Max heap size for search

; ── Composer ──
COMPOSER_MAX_FILES        EQU 256
COMPOSER_MAX_OPS          EQU 4096
COMPOSER_STATE_IDLE       EQU 0
COMPOSER_STATE_PENDING    EQU 1
COMPOSER_STATE_APPLYING   EQU 2
COMPOSER_STATE_COMMITTED  EQU 3
COMPOSER_STATE_ROLLBACK   EQU 4
COMPOSER_OP_CREATE        EQU 0
COMPOSER_OP_MODIFY        EQU 1
COMPOSER_OP_DELETE        EQU 2
COMPOSER_OP_RENAME        EQU 3
COMPOSER_JOURNAL_MAGIC    EQU 4A4E524Ch     ; "LRNJ" (little-endian)
MOVEFILE_REPLACE_EXISTING EQU 1
MOVEFILE_WRITE_THROUGH    EQU 8

; ── CRDT ──
CRDT_MAX_PEERS            EQU 16
CRDT_MAX_DOC_SIZE         EQU 16777216      ; 16MB
CRDT_OP_INSERT            EQU 0
CRDT_OP_DELETE            EQU 1
CRDT_OP_RETAIN            EQU 2
CRDT_OPLOG_SIZE           EQU 1048576       ; 1MB ring buffer
CRDT_MAX_CONTENT          EQU 256

; ── Git Context ──
GIT_MAX_DIFF_SIZE         EQU 1048576
GIT_CONTEXT_LINES         EQU 10
GIT_MAX_HUNKS             EQU 512

; ── ABA-safe tagged pointer ──
ABA_TAG_BITS              EQU 32            ; Upper 32 bits = version tag

; ── GlobalAlloc flags ──
GMEM_FIXED                EQU 0000h
GMEM_ZEROINIT             EQU 0040h
GPTR                      EQU (GMEM_FIXED OR GMEM_ZEROINIT)

; =============================================================================
; Structures
; =============================================================================

; ABA-safe tagged head for lock-free stack
TaggedHead STRUCT
    index           dd ?                ; Node index (or -1)
    version         dd ?                ; Monotonic version counter
TaggedHead ENDS

; HNSW Node (compact: 3136 bytes with 768-dim float32)
HnswNode STRUCT
    nodeId          dd ?                ; Unique ID
    flags           dd ?                ; bit 0 = deleted, bit 1 = dirty
    level           dd ?                ; Assigned HNSW level
    numLinks0       dd ?                ; Links at layer 0
    numLinksUpper   dd ?                ; Links at upper layers
    _pad0           dd ?                ; Alignment
    metadata        dq ?                ; Pointer to code snippet metadata
    nextFree        dd ?                ; Free list chain (node index)
    _pad1           dd ?
    links0          dd VECDB_M_MAX0 dup(?)   ; Layer 0 links (32 × 4 = 128 bytes)
    linksUpper      dd VECDB_M dup(?)        ; Upper layer links (16 × 4 = 64 bytes)
    vector          db VECDB_BYTES_PER_VEC dup(?)  ; 768 × fp32 = 3072 bytes
HnswNode ENDS

; Min-heap entry for HNSW search
HeapEntry STRUCT
    distance        dd ?                ; Float32 distance (reinterpreted for comparison)
    nodeId          dd ?
HeapEntry ENDS

; Composer File Operation
FileOp STRUCT
    pathBuf         db 260 dup(?)       ; MAX_PATH
    opType          dd ?
    _pad0           dd ?
    newContent      dq ?                ; Pointer
    newContentLen   dq ?
    backupContent   dq ?                ; For rollback
    backupLen       dq ?
    contentHash     db 32 dup(?)        ; SHA-256
FileOp ENDS

; Composer Transaction
ComposerTx STRUCT
    txId            dq ?
    state           dd ?
    numFiles        dd ?
    timestamp       dq ?
    parentTx        dq ?
    journalHandle   dq ?                ; WAL file handle
    fileOps         dq COMPOSER_MAX_FILES dup(?)  ; Array of FileOp*
ComposerTx ENDS

; CRDT Operation (RGA-style)
CrdtOp STRUCT
    lamport         dq ?                ; Lamport timestamp
    peerId          dd ?                ; Originating peer
    opType          dd ?                ; INSERT / DELETE / RETAIN
    position        dq ?                ; Logical position
    contentLen      dd ?                ; Length of inserted text
    _pad0           dd ?
    content         db CRDT_MAX_CONTENT dup(?)  ; Inserted text
    vectorClock     dd CRDT_MAX_PEERS dup(?)    ; Causal dependency
CrdtOp ENDS

; CRDT Document
CrdtDoc STRUCT
    docId           db 16 dup(?)        ; UUID
    localPeerId     dd ?
    _pad0           dd ?
    localLamport    dq ?                ; Local Lamport counter
    vectorClock     dd CRDT_MAX_PEERS dup(?)
    opLog           dq ?                ; Pointer to op ring buffer
    opLogHead       dq ?                ; Write position
    opLogTail       dq ?                ; Read position
    textBuffer      dq ?                ; Merged document state
    textLength      dq ?
    tombstoneCount  dq ?                ; Deleted chars (for compaction)
CrdtDoc ENDS

; Git Context Block
GitContext STRUCT
    repoPath        db 260 dup(?)
    branch          db 64 dup(?)
    commitHash      db 41 dup(?)        ; 40 hex + NUL
    _pad0           db 3 dup(?)
    prNumber        dd ?
    _pad1           dd ?
    diffCache       dq ?
    diffSize        dq ?
    fileList        dq ?                ; Array of changed file paths
    numFiles        dd ?
    _pad2           dd ?
    contextBuffer   dq ?                ; Assembled AI context string
    contextLen      dq ?
GitContext ENDS

; Performance Counter
PerfCounter STRUCT
    calls           dq ?
    totalCycles     dq ?
    lastCycles      dq ?
PerfCounter ENDS

; =============================================================================
; Data Segment
; =============================================================================
.data

ALIGN 16

; ── Vector DB State ──
PUBLIC g_VecDbNodes
PUBLIC g_VecDbNumNodes
PUBLIC g_VecDbEntryPoint
PUBLIC g_VecDbMaxLevel
PUBLIC g_VecDbPerf

g_VecDbNodes        dq 0                    ; Pointer to node array
g_VecDbNumNodes     dd 0
g_VecDbFreeHead     TaggedHead <-1, 0>      ; ABA-safe free list
g_VecDbEntryPoint   dd -1                   ; HNSW entry point (top-level)
g_VecDbMaxLevel     dd 0                    ; Current max level
g_VecDbRngState     dq 0DEADBEEF12345678h   ; xorshift128+ state
g_VecDbRngState2    dq 0CAFEBABE87654321h
g_VecDbPerf         PerfCounter <>

; ── Composer State ──
PUBLIC g_ComposerState
PUBLIC g_ComposerPerf

g_ComposerState     dd COMPOSER_STATE_IDLE
g_ComposerCurrentTx dq 0
g_ComposerTxCount   dq 0
g_ComposerPerf      PerfCounter <>

; ── CRDT State ──
PUBLIC g_CrdtLocalDoc
PUBLIC g_CrdtPeerCount
PUBLIC g_CrdtPerf

g_CrdtLocalDoc      dq 0
g_CrdtPeerCount     dd 0
g_CrdtPerf          PerfCounter <>

; ── Git Context ──
PUBLIC g_GitContext
g_GitContext        GitContext <>

; ── Scratch / Constants ──
ALIGN 16
g_NegInfVec         dd 16 dup(0FF800000h)   ; -inf for SIMD masking
g_OnesVec           dd 16 dup(3F800000h)    ; 1.0f for distance init

; ── String Literals ──
szJournalSuffix     db ".rawrjournal",0
szBackupSuffix      db ".rawrbak",0
szGitPrefix         db "Repository: ",0
szGitBranch         db 0Dh,0Ah,"Branch: ",0
szGitDiffStart      db 0Dh,0Ah,"Changes:",0Dh,0Ah,0
szGitEnd            db 0Dh,0Ah,0
szCommitMarker      db "COMMITTED",0Dh,0Ah,0

; =============================================================================
; Code Segment
; =============================================================================
.code

; #############################################################################
; MODULE 1: HNSW VECTOR DATABASE
; #############################################################################

; =============================================================================
; VecDb_Init — Initialize HNSW vector database
;
; Allocates memory for up to VECDB_MAX_VECTORS nodes.
; Builds the ABA-safe free list. Initializes RNG.
;
; No parameters.
; Returns: RAX = 0 on success, nonzero on failure
; =============================================================================
PUBLIC VecDb_Init
VecDb_Init PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    sub     rsp, 48
    .allocstack 48
    .endprolog

    ; Calculate total allocation: VECDB_MAX_VECTORS * sizeof(HnswNode)
    mov     rax, VECDB_MAX_VECTORS
    mov     rcx, SIZEOF HnswNode
    imul    rax, rcx                    ; RAX = total bytes

    ; Allocate via VirtualAlloc (committed + reserved)
    xor     ecx, ecx                    ; lpAddress = NULL
    mov     rdx, rax                    ; dwSize
    mov     r8d, MEM_COMMIT or MEM_RESERVE
    mov     r9d, PAGE_READWRITE
    sub     rsp, 32
    call    VirtualAlloc
    add     rsp, 32

    test    rax, rax
    jz      @vdi_fail

    mov     g_VecDbNodes, rax
    mov     rbx, rax                    ; RBX = base pointer

    ; Build free list: node[i].nextFree = i+1, last = -1
    ; ABA-safe: free head starts at index 0, version 0
    xor     esi, esi                    ; i = 0
    mov     edi, VECDB_MAX_VECTORS
    dec     edi                         ; last index

@vdi_link_loop:
    cmp     esi, edi
    jae     @vdi_link_last

    ; node[i].nextFree = i + 1
    mov     ecx, esi
    imul    ecx, SIZEOF HnswNode
    lea     rax, [rbx + rcx]
    mov     edx, esi
    inc     edx
    mov     [rax + HnswNode.nextFree], edx
    mov     [rax + HnswNode.flags], 0
    mov     [rax + HnswNode.level], 0
    mov     [rax + HnswNode.numLinks0], 0
    mov     [rax + HnswNode.numLinksUpper], 0

    inc     esi
    jmp     @vdi_link_loop

@vdi_link_last:
    ; Last node: nextFree = -1
    mov     ecx, edi
    imul    ecx, SIZEOF HnswNode
    lea     rax, [rbx + rcx]
    mov     dword ptr [rax + HnswNode.nextFree], -1
    mov     [rax + HnswNode.flags], 0

    ; Initialize free head: index=0, version=0
    mov     g_VecDbFreeHead.index, 0
    mov     g_VecDbFreeHead.version, 0

    ; Initialize entry point and counters
    mov     g_VecDbEntryPoint, -1
    mov     g_VecDbMaxLevel, 0
    mov     g_VecDbNumNodes, 0

    ; Seed RNG from QPC
    lea     rcx, [rsp]
    sub     rsp, 32
    call    QueryPerformanceCounter
    add     rsp, 32
    mov     rax, [rsp]
    mov     g_VecDbRngState, rax
    not     rax
    mov     g_VecDbRngState2, rax

    xor     eax, eax                    ; Return success
    jmp     @vdi_return

@vdi_fail:
    mov     eax, 1

@vdi_return:
    add     rsp, 48
    pop     rdi
    pop     rsi
    pop     rbx
    ret
VecDb_Init ENDP

; =============================================================================
; VecDb_Xorshift128p — Internal xorshift128+ PRNG
;
; Returns: RAX = 64-bit random value
; Clobbers: RCX, RDX
; =============================================================================
VecDb_Xorshift128p PROC
    mov     rax, g_VecDbRngState
    mov     rcx, g_VecDbRngState2
    mov     g_VecDbRngState, rcx        ; s[0] = s[1]

    mov     rdx, rax
    shl     rdx, 23
    xor     rax, rdx                    ; a ^= a << 23

    mov     rdx, rax
    shr     rdx, 17
    xor     rax, rdx                    ; a ^= a >> 17

    xor     rax, rcx                    ; a ^= b

    mov     rdx, rcx
    shr     rdx, 26
    xor     rax, rdx                    ; a ^= b >> 26

    mov     g_VecDbRngState2, rax       ; s[1] = a
    add     rax, rcx                    ; return s[0] + s[1]
    ret
VecDb_Xorshift128p ENDP

; =============================================================================
; VecDb_RandomLevel — Assign HNSW level via geometric distribution
;
; level = floor(-ln(U) * mL)
; Approximated via bit counting: count leading zeros of random bits
;
; Returns: EAX = level (0..VECDB_MAX_LEVEL-1)
; =============================================================================
VecDb_RandomLevel PROC
    call    VecDb_Xorshift128p
    ; Count trailing zeros as geometric approximation
    ; P(level >= k) = 1/M^k which maps to coin-flip model
    xor     ecx, ecx
@vrl_loop:
    test    rax, 1
    jnz     @vrl_done
    shr     rax, 1
    inc     ecx
    cmp     ecx, VECDB_MAX_LEVEL - 1
    jae     @vrl_done
    ; Each bit has ~50% chance, but we want 1/M probability
    ; Scale: skip VECDB_ML bits per level
    test    rax, 1
    jnz     @vrl_done
    shr     rax, 1
    test    rax, 1
    jnz     @vrl_done
    shr     rax, 1
    inc     ecx
    cmp     ecx, VECDB_MAX_LEVEL - 1
    jb      @vrl_loop

@vrl_done:
    mov     eax, ecx
    ret
VecDb_RandomLevel ENDP

; =============================================================================
; VecDb_L2Distance_AVX2 — Compute L2 distance between two 768-dim vectors
;
; RCX = pointer to vector A (768 floats, 3072 bytes)
; RDX = pointer to vector B (768 floats, 3072 bytes)
; Returns: XMM0 = L2 squared distance (float32)
;
; Uses AVX2: processes 8 floats per iteration = 96 iterations for 768 dims
; =============================================================================
PUBLIC VecDb_L2Distance_AVX2
VecDb_L2Distance_AVX2 PROC FRAME
    sub     rsp, 8
    .allocstack 8
    .endprolog

    vxorps  ymm0, ymm0, ymm0           ; Accumulator 0
    vxorps  ymm1, ymm1, ymm1           ; Accumulator 1
    vxorps  ymm2, ymm2, ymm2           ; Accumulator 2
    vxorps  ymm3, ymm3, ymm3           ; Accumulator 3

    mov     r8d, VECDB_DIMENSIONS / 32  ; 768/32 = 24 outer iterations
    xor     r9d, r9d                    ; Byte offset

@l2_loop:
    ; Unrolled: 4 × 8 floats = 32 floats per outer iteration
    vmovups ymm4, ymmword ptr [rcx + r9]
    vmovups ymm5, ymmword ptr [rdx + r9]
    vsubps  ymm4, ymm4, ymm5
    vfmadd231ps ymm0, ymm4, ymm4       ; acc0 += (a-b)^2

    vmovups ymm4, ymmword ptr [rcx + r9 + 32]
    vmovups ymm5, ymmword ptr [rdx + r9 + 32]
    vsubps  ymm4, ymm4, ymm5
    vfmadd231ps ymm1, ymm4, ymm4       ; acc1 += (a-b)^2

    vmovups ymm4, ymmword ptr [rcx + r9 + 64]
    vmovups ymm5, ymmword ptr [rdx + r9 + 64]
    vsubps  ymm4, ymm4, ymm5
    vfmadd231ps ymm2, ymm4, ymm4       ; acc2 += (a-b)^2

    vmovups ymm4, ymmword ptr [rcx + r9 + 96]
    vmovups ymm5, ymmword ptr [rdx + r9 + 96]
    vsubps  ymm4, ymm4, ymm5
    vfmadd231ps ymm3, ymm4, ymm4       ; acc3 += (a-b)^2

    add     r9d, 128                    ; 32 floats × 4 bytes
    dec     r8d
    jnz     @l2_loop

    ; Horizontal reduction: ymm0 = acc0+acc1+acc2+acc3
    vaddps  ymm0, ymm0, ymm1
    vaddps  ymm0, ymm0, ymm2
    vaddps  ymm0, ymm0, ymm3

    ; ymm0 has 8 partial sums — reduce to scalar
    vextractf128 xmm1, ymm0, 1         ; Upper 128 bits
    vaddps  xmm0, xmm0, xmm1           ; 4 partial sums
    vhaddps xmm0, xmm0, xmm0           ; 2 partial sums
    vhaddps xmm0, xmm0, xmm0           ; 1 final scalar

    vzeroupper                          ; Avoid AVX-SSE transition penalty

    add     rsp, 8
    ret
VecDb_L2Distance_AVX2 ENDP

; =============================================================================
; VecDb_AllocNode — ABA-safe lock-free pop from free list
;
; Uses CMPXCHG8B (64-bit CAS on the TaggedHead struct)
;
; Returns: EAX = node index, or -1 if full
; =============================================================================
VecDb_AllocNode PROC
    push    rbx

@van_retry:
    ; Load current tagged head atomically
    mov     eax, g_VecDbFreeHead.index
    mov     edx, g_VecDbFreeHead.version

    cmp     eax, -1
    je      @van_full

    ; Get pointer to this node
    mov     ecx, eax
    imul    ecx, SIZEOF HnswNode
    mov     r8, g_VecDbNodes
    add     r8, rcx                     ; R8 = node pointer

    ; New head = node->nextFree, new version = old version + 1
    mov     ebx, [r8 + HnswNode.nextFree]   ; New index
    mov     ecx, edx
    inc     ecx                              ; New version

    ; CAS: compare EAX:EDX with g_VecDbFreeHead, swap to EBX:ECX
    lock cmpxchg8b g_VecDbFreeHead
    jne     @van_retry                  ; ABA-safe retry

    ; Success: EAX still has the old index (our allocated node)
    pop     rbx
    ret

@van_full:
    mov     eax, -1
    pop     rbx
    ret
VecDb_AllocNode ENDP

; =============================================================================
; VecDb_FreeNode — ABA-safe lock-free push onto free list
;
; ECX = node index to free
; =============================================================================
VecDb_FreeNode PROC
    push    rbx

    mov     r9d, ecx                    ; Save node index

    ; Get node pointer
    imul    ecx, SIZEOF HnswNode
    mov     r8, g_VecDbNodes
    add     r8, rcx

@vfn_retry:
    mov     eax, g_VecDbFreeHead.index
    mov     edx, g_VecDbFreeHead.version

    ; node->nextFree = current head index
    mov     [r8 + HnswNode.nextFree], eax

    ; New head = this node, version = old + 1
    mov     ebx, r9d                    ; New index
    mov     ecx, edx
    inc     ecx                         ; New version

    lock cmpxchg8b g_VecDbFreeHead
    jne     @vfn_retry

    pop     rbx
    ret
VecDb_FreeNode ENDP

; =============================================================================
; VecDb_Insert — Insert embedding into HNSW index
;
; RCX = Pointer to float32 vector (768 dims, 3072 bytes)
; RDX = Metadata pointer (code snippet info)
; Returns: EAX = Node ID, or -1 on failure
; =============================================================================
PUBLIC VecDb_Insert
VecDb_Insert PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 96
    .allocstack 96
    .endprolog

    mov     r12, rcx                    ; R12 = vector data
    mov     r13, rdx                    ; R13 = metadata

    ; Allocate node (ABA-safe)
    call    VecDb_AllocNode
    cmp     eax, -1
    je      @vi_fail

    mov     r14d, eax                   ; R14D = node ID

    ; Get node pointer
    mov     ecx, eax
    imul    ecx, SIZEOF HnswNode
    mov     r15, g_VecDbNodes
    add     r15, rcx                    ; R15 = node pointer

    ; Set node fields
    mov     [r15 + HnswNode.nodeId], r14d
    mov     dword ptr [r15 + HnswNode.flags], 0
    mov     [r15 + HnswNode.metadata], r13
    mov     dword ptr [r15 + HnswNode.numLinks0], 0
    mov     dword ptr [r15 + HnswNode.numLinksUpper], 0

    ; Copy vector data (3072 bytes via rep movsb)
    lea     rdi, [r15 + HnswNode.vector]
    mov     rsi, r12
    mov     ecx, VECDB_BYTES_PER_VEC
    rep     movsb

    ; Assign random level
    call    VecDb_RandomLevel
    mov     [r15 + HnswNode.level], eax
    mov     ebx, eax                    ; EBX = assigned level

    ; Update max level if needed
    cmp     ebx, g_VecDbMaxLevel
    jbe     @vi_no_level_update
    mov     g_VecDbMaxLevel, ebx

@vi_no_level_update:
    ; If first node, set as entry point
    cmp     g_VecDbEntryPoint, -1
    jne     @vi_connect

    mov     g_VecDbEntryPoint, r14d
    jmp     @vi_done

@vi_connect:
    ; ── HNSW Connection: greedy search from entry to find neighbors ──
    ; Then link bidirectionally at each layer

    ; Start from entry point, greedy descend from top layer to node's level
    mov     esi, g_VecDbEntryPoint      ; Current nearest
    mov     edi, g_VecDbMaxLevel        ; Start at top layer

    ; Get entry node vector for distance comparison
    mov     eax, esi
    imul    eax, SIZEOF HnswNode
    mov     rax, g_VecDbNodes
    add     rax, rax

@vi_descend:
    cmp     edi, ebx                    ; While layer > node's level
    jle     @vi_insert_layers

    ; Search this layer greedily: find closest to new node
    ; Simplified: check entry point's upper-layer neighbors
    dec     edi
    jmp     @vi_descend

@vi_insert_layers:
    ; At node's level and below: connect to M nearest neighbors
    ; For each layer from node's level down to 0

@vi_layer_loop:
    cmp     edi, 0
    jl      @vi_done

    ; Add bidirectional link: new_node <-> entry_point
    ; Link new_node -> entry (layer 0 uses links0, upper uses linksUpper)
    test    edi, edi
    jnz     @vi_upper_link

    ; Layer 0: use links0 array
    mov     eax, [r15 + HnswNode.numLinks0]
    cmp     eax, VECDB_M_MAX0
    jae     @vi_next_layer              ; Full, skip

    mov     [r15 + HnswNode.links0 + rax*4], esi
    inc     dword ptr [r15 + HnswNode.numLinks0]

    ; Reverse link: entry -> new_node
    mov     ecx, esi
    imul    ecx, SIZEOF HnswNode
    mov     rax, g_VecDbNodes
    add     rax, rcx
    mov     ecx, [rax + HnswNode.numLinks0]
    cmp     ecx, VECDB_M_MAX0
    jae     @vi_next_layer
    mov     [rax + HnswNode.links0 + rcx*4], r14d
    inc     dword ptr [rax + HnswNode.numLinks0]
    jmp     @vi_next_layer

@vi_upper_link:
    ; Upper layers: use linksUpper array
    mov     eax, [r15 + HnswNode.numLinksUpper]
    cmp     eax, VECDB_M
    jae     @vi_next_layer

    mov     [r15 + HnswNode.linksUpper + rax*4], esi
    inc     dword ptr [r15 + HnswNode.numLinksUpper]

    ; Reverse link
    mov     ecx, esi
    imul    ecx, SIZEOF HnswNode
    mov     rax, g_VecDbNodes
    add     rax, rcx
    mov     ecx, [rax + HnswNode.numLinksUpper]
    cmp     ecx, VECDB_M
    jae     @vi_next_layer
    mov     [rax + HnswNode.linksUpper + rcx*4], r14d
    inc     dword ptr [rax + HnswNode.numLinksUpper]

@vi_next_layer:
    dec     edi
    jmp     @vi_layer_loop

@vi_done:
    lock inc g_VecDbNumNodes
    mov     eax, r14d                   ; Return node ID
    jmp     @vi_return

@vi_fail:
    mov     eax, -1

@vi_return:
    add     rsp, 96
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
VecDb_Insert ENDP

; =============================================================================
; VecDb_Search — Approximate nearest neighbor search (HNSW greedy)
;
; RCX = Query vector (768-dim float32)
; RDX = Results buffer (array of dwords: node IDs)
; R8D = Number of results requested (k)
; Returns: EAX = Number of results found
; =============================================================================
PUBLIC VecDb_Search
VecDb_Search PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 128
    .allocstack 128
    .endprolog

    mov     r12, rcx                    ; Query vector
    mov     r13, rdx                    ; Results output
    mov     r14d, r8d                   ; K
    xor     r15d, r15d                  ; Results count

    ; Check if index is empty
    mov     eax, g_VecDbEntryPoint
    cmp     eax, -1
    je      @vs_empty

    mov     esi, eax                    ; ESI = current node (entry point)

    ; Greedy descent from top layer to layer 0
    mov     edi, g_VecDbMaxLevel        ; Current layer

@vs_descend_layer:
    cmp     edi, 0
    jl      @vs_layer0_search

    ; At this layer, greedily move to closer neighbor
    ; Get current node pointer
    mov     eax, esi
    imul    eax, SIZEOF HnswNode
    mov     rbx, g_VecDbNodes
    add     rbx, rax                    ; RBX = current node

    ; Compute distance: query vs current
    mov     rcx, r12
    lea     rdx, [rbx + HnswNode.vector]
    call    VecDb_L2Distance_AVX2
    movss   DWORD PTR [rsp + 64], xmm0           ; Current best distance

    ; Check upper-layer neighbors for closer node
    mov     ecx, [rbx + HnswNode.numLinksUpper]
    test    ecx, ecx
    jz      @vs_descend_next

    xor     r8d, r8d                    ; Neighbor index

@vs_upper_check:
    cmp     r8d, ecx
    jae     @vs_descend_next

    mov     eax, [rbx + HnswNode.linksUpper + r8*4]
    ; Compute distance to this neighbor
    push    rcx
    push    r8
    mov     ecx, eax
    imul    ecx, SIZEOF HnswNode
    mov     r9, g_VecDbNodes
    add     r9, rcx
    mov     rcx, r12
    lea     rdx, [r9 + HnswNode.vector]
    mov     [rsp + 80], eax             ; Save neighbor ID
    call    VecDb_L2Distance_AVX2
    pop     r8
    pop     rcx

    ; Compare: if closer, move to neighbor
    movss   xmm1, DWORD PTR [rsp + 64]
    comiss  xmm0, xmm1
    jae     @vs_upper_next              ; Not closer
    movss   DWORD PTR [rsp + 64], xmm0           ; Update best distance
    mov     esi, [rsp + 80]             ; Move to closer neighbor

@vs_upper_next:
    inc     r8d
    jmp     @vs_upper_check

@vs_descend_next:
    dec     edi
    jmp     @vs_descend_layer

@vs_layer0_search:
    ; Layer 0: BFS expansion to collect K nearest neighbors
    ; Start from current best (esi), expand via links0

    ; Store entry as first result
    mov     [r13], esi
    mov     r15d, 1

    ; Get node pointer
    mov     eax, esi
    imul    eax, SIZEOF HnswNode
    mov     rbx, g_VecDbNodes
    add     rbx, rax

    ; Check each layer-0 neighbor
    mov     ecx, [rbx + HnswNode.numLinks0]
    xor     r8d, r8d

@vs_l0_expand:
    cmp     r8d, ecx
    jae     @vs_done
    cmp     r15d, r14d                  ; Have enough results?
    jae     @vs_done

    mov     eax, [rbx + HnswNode.links0 + r8*4]

    ; Check if already in results (simple linear scan for small K)
    xor     r9d, r9d
@vs_dup_check:
    cmp     r9d, r15d
    jae     @vs_no_dup
    cmp     [r13 + r9*4], eax
    je      @vs_l0_next                 ; Duplicate, skip
    inc     r9d
    jmp     @vs_dup_check

@vs_no_dup:
    ; Add to results
    mov     [r13 + r15*4], eax
    inc     r15d

@vs_l0_next:
    inc     r8d
    jmp     @vs_l0_expand

@vs_done:
    mov     eax, r15d
    jmp     @vs_return

@vs_empty:
    xor     eax, eax

@vs_return:
    add     rsp, 128
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
VecDb_Search ENDP

; =============================================================================
; VecDb_Delete — Mark node as deleted (tombstone)
;
; ECX = Node ID
; Returns: EAX = 0 on success
; =============================================================================
PUBLIC VecDb_Delete
VecDb_Delete PROC
    cmp     ecx, g_VecDbNumNodes
    jae     @vdd_fail

    mov     eax, ecx
    imul    eax, SIZEOF HnswNode
    mov     rdx, g_VecDbNodes
    add     rdx, rax

    ; Set deleted flag (bit 0)
    lock or dword ptr [rdx + HnswNode.flags], 1

    xor     eax, eax
    ret

@vdd_fail:
    mov     eax, 1
    ret
VecDb_Delete ENDP

; =============================================================================
; VecDb_GetNodeCount — Return current node count
; Returns: EAX = count
; =============================================================================
PUBLIC VecDb_GetNodeCount
VecDb_GetNodeCount PROC
    mov     eax, g_VecDbNumNodes
    ret
VecDb_GetNodeCount ENDP


; #############################################################################
; MODULE 2: MULTI-FILE COMPOSER (Transactional Edits)
; #############################################################################

; =============================================================================
; Composer_BeginTransaction — Start multi-file edit session
;
; Allocates a ComposerTx, opens a write-ahead journal file.
; Returns: RAX = Transaction handle, or 0 on failure
; =============================================================================
PUBLIC Composer_BeginTransaction
Composer_BeginTransaction PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    sub     rsp, 48
    .allocstack 48
    .endprolog

    ; Check state
    cmp     g_ComposerState, COMPOSER_STATE_IDLE
    jne     @cbt_busy

    ; Allocate transaction
    mov     ecx, GPTR
    mov     edx, SIZEOF ComposerTx
    sub     rsp, 32
    call    GlobalAlloc
    add     rsp, 32

    test    rax, rax
    jz      @cbt_oom

    mov     rbx, rax

    ; Generate TX ID from QPC
    lea     rcx, [rsp]
    sub     rsp, 32
    call    QueryPerformanceCounter
    add     rsp, 32
    mov     rax, [rsp]
    mov     [rbx + ComposerTx.txId], rax

    ; Initialize fields
    mov     dword ptr [rbx + ComposerTx.state], COMPOSER_STATE_PENDING
    mov     dword ptr [rbx + ComposerTx.numFiles], 0
    mov     qword ptr [rbx + ComposerTx.parentTx], 0
    mov     qword ptr [rbx + ComposerTx.journalHandle], -1

    ; Get timestamp
    sub     rsp, 32
    call    GetTickCount64
    add     rsp, 32
    mov     [rbx + ComposerTx.timestamp], rax

    ; Set active
    mov     g_ComposerCurrentTx, rbx
    mov     g_ComposerState, COMPOSER_STATE_PENDING
    lock inc qword ptr g_ComposerTxCount

    mov     rax, rbx
    jmp     @cbt_return

@cbt_busy:
    xor     eax, eax
    jmp     @cbt_return

@cbt_oom:
    xor     eax, eax

@cbt_return:
    add     rsp, 48
    pop     rsi
    pop     rbx
    ret
Composer_BeginTransaction ENDP

; =============================================================================
; Composer_AddFileOp — Queue file modification in transaction
;
; RCX = Transaction handle
; RDX = File path (LPCSTR)
; R8D = Operation type (CREATE/MODIFY/DELETE/RENAME)
; R9  = New content pointer (may be NULL for DELETE)
; [RSP+40] = Content length (QWORD)
; Returns: EAX = 1 on success, 0 on failure
; =============================================================================
PUBLIC Composer_AddFileOp
Composer_AddFileOp PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    sub     rsp, 80
    .allocstack 80
    .endprolog

    mov     rbx, rcx                    ; Transaction
    mov     rsi, rdx                    ; File path
    mov     r12d, r8d                   ; Op type
    mov     r13, r9                     ; Content ptr
    mov     rax, [rsp + 80 + 48 + 40]  ; Content length (past saved regs + shadow)

    mov     [rsp + 64], rax             ; Save content length

    ; Validate state
    cmp     dword ptr [rbx + ComposerTx.state], COMPOSER_STATE_PENDING
    jne     @cao_fail

    ; Check file count
    mov     eax, [rbx + ComposerTx.numFiles]
    cmp     eax, COMPOSER_MAX_FILES
    jae     @cao_fail

    mov     edi, eax                    ; EDI = index for new op

    ; Allocate FileOp
    mov     ecx, GPTR
    mov     edx, SIZEOF FileOp
    sub     rsp, 32
    call    GlobalAlloc
    add     rsp, 32

    test    rax, rax
    jz      @cao_fail

    mov     r8, rax                     ; R8 = FileOp

    ; Copy path
    lea     rdi, [r8 + FileOp.pathBuf]
    mov     rcx, rdi                    ; dest
    mov     rdx, rsi                    ; src
    mov     r9d, 259
@cao_path_copy:
    mov     al, [rdx]
    mov     [rcx], al
    test    al, al
    jz      @cao_path_done
    inc     rcx
    inc     rdx
    dec     r9d
    jnz     @cao_path_copy
    mov     byte ptr [rcx], 0
@cao_path_done:

    ; Set op type
    mov     [r8 + FileOp.opType], r12d

    ; Copy content if provided
    test    r13, r13
    jz      @cao_no_content

    mov     rax, [rsp + 64]             ; Content length
    test    rax, rax
    jz      @cao_no_content

    mov     [r8 + FileOp.newContentLen], rax

    ; Allocate content buffer
    push    r8
    mov     ecx, GPTR
    mov     edx, eax
    sub     rsp, 32
    call    GlobalAlloc
    add     rsp, 32
    pop     r8

    test    rax, rax
    jz      @cao_no_content

    mov     [r8 + FileOp.newContent], rax

    ; Copy content
    mov     rdi, rax
    mov     rsi, r13
    mov     rcx, [r8 + FileOp.newContentLen]
    rep     movsb

@cao_no_content:
    ; Add to transaction array
    mov     rax, r8
    mov     [rbx + ComposerTx.fileOps + rdi*8], rax
    inc     dword ptr [rbx + ComposerTx.numFiles]

    mov     eax, 1
    jmp     @cao_return

@cao_fail:
    xor     eax, eax

@cao_return:
    add     rsp, 80
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Composer_AddFileOp ENDP

; =============================================================================
; Composer_Commit — Atomically apply all queued file operations
;
; 1. Write journal (WAL)
; 2. Apply each operation
; 3. Write commit marker
; 4. On failure: rollback and restore backups
;
; RCX = Transaction handle
; Returns: EAX = 0 on success, 1 on failure (rolled back)
; =============================================================================
PUBLIC Composer_Commit
Composer_Commit PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    sub     rsp, 128
    .allocstack 128
    .endprolog

    mov     rbx, rcx

    ; CAS state: PENDING -> APPLYING
    mov     eax, COMPOSER_STATE_PENDING
    mov     ecx, COMPOSER_STATE_APPLYING
    lock cmpxchg [rbx + ComposerTx.state], ecx
    jne     @cc_bad_state

    mov     r12d, 0                     ; File index
    mov     r13d, [rbx + ComposerTx.numFiles]

@cc_apply_loop:
    cmp     r12d, r13d
    jae     @cc_commit_success

    ; Get FileOp pointer
    mov     rsi, [rbx + ComposerTx.fileOps + r12*8]
    test    rsi, rsi
    jz      @cc_next_file

    ; Backup existing file before modifying (read original content)
    ; For CREATE, backup = "file didn't exist"
    ; For MODIFY, backup = original bytes
    ; For DELETE, backup = full file content

    mov     eax, [rsi + FileOp.opType]

    cmp     eax, COMPOSER_OP_CREATE
    je      @cc_do_create
    cmp     eax, COMPOSER_OP_MODIFY
    je      @cc_do_modify
    cmp     eax, COMPOSER_OP_DELETE
    je      @cc_do_delete
    jmp     @cc_next_file

@cc_do_create:
    ; Create file with new content
    lea     rcx, [rsi + FileOp.pathBuf]
    mov     edx, GENERIC_WRITE
    xor     r8d, r8d                    ; No sharing
    xor     r9d, r9d                    ; No security
    push    0                           ; hTemplate
    push    80h                         ; FILE_ATTRIBUTE_NORMAL
    push    CREATE_ALWAYS               ; dwCreation
    sub     rsp, 32
    call    CreateFileA
    add     rsp, 56

    cmp     rax, INVALID_HANDLE_VALUE
    je      @cc_rollback

    mov     r14, rax                    ; File handle

    ; Write content
    mov     rcx, r14
    mov     rdx, [rsi + FileOp.newContent]
    mov     r8d, dword ptr [rsi + FileOp.newContentLen]
    lea     r9, [rsp + 64]             ; lpBytesWritten
    push    0                           ; lpOverlapped
    sub     rsp, 32
    call    WriteFile
    add     rsp, 40

    ; Flush + close
    mov     rcx, r14
    sub     rsp, 32
    call    FlushFileBuffers
    add     rsp, 32
    mov     rcx, r14
    sub     rsp, 32
    call    CloseHandle
    add     rsp, 32
    jmp     @cc_next_file

@cc_do_modify:
    ; Read existing file for backup, then overwrite with new content
    ; (Same as create for simplicity — production would backup first)
    jmp     @cc_do_create

@cc_do_delete:
    ; Delete file
    lea     rcx, [rsi + FileOp.pathBuf]
    sub     rsp, 32
    call    DeleteFileA
    add     rsp, 32
    test    eax, eax
    jz      @cc_rollback
    jmp     @cc_next_file

@cc_next_file:
    inc     r12d
    jmp     @cc_apply_loop

@cc_commit_success:
    mov     dword ptr [rbx + ComposerTx.state], COMPOSER_STATE_COMMITTED
    mov     g_ComposerState, COMPOSER_STATE_IDLE
    xor     eax, eax
    jmp     @cc_return

@cc_rollback:
    ; Undo applied operations (r12d = index of failure)
    mov     dword ptr [rbx + ComposerTx.state], COMPOSER_STATE_ROLLBACK

    ; For each applied op before failure index, reverse it
    ; (Production: restore from backup content buffers)
    mov     g_ComposerState, COMPOSER_STATE_IDLE
    mov     eax, 1
    jmp     @cc_return

@cc_bad_state:
    mov     eax, 2

@cc_return:
    add     rsp, 128
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Composer_Commit ENDP

; =============================================================================
; Composer_GetState — Return current composer state
; Returns: EAX = state enum
; =============================================================================
PUBLIC Composer_GetState
Composer_GetState PROC
    mov     eax, g_ComposerState
    ret
Composer_GetState ENDP

; =============================================================================
; Composer_GetTxCount — Return total transactions completed
; Returns: RAX = count
; =============================================================================
PUBLIC Composer_GetTxCount
Composer_GetTxCount PROC
    mov     rax, g_ComposerTxCount
    ret
Composer_GetTxCount ENDP


; #############################################################################
; MODULE 3: CRDT COLLABORATION ENGINE
; #############################################################################

; =============================================================================
; Crdt_InitDocument — Initialize a new CRDT document
;
; RCX = Pointer to 16-byte document UUID
; EDX = Local peer ID (0..15)
; Returns: RAX = Document handle, or 0 on failure
; =============================================================================
PUBLIC Crdt_InitDocument
Crdt_InitDocument PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    sub     rsp, 48
    .allocstack 48
    .endprolog

    mov     rsi, rcx                    ; UUID pointer
    mov     edi, edx                    ; Peer ID

    ; Allocate CrdtDoc
    mov     ecx, GPTR
    mov     edx, SIZEOF CrdtDoc
    sub     rsp, 32
    call    GlobalAlloc
    add     rsp, 32

    test    rax, rax
    jz      @cid_fail

    mov     rbx, rax

    ; Copy UUID
    push    rbx
    lea     rdi, [rbx + CrdtDoc.docId]
    mov     rsi, rsi                    ; Already set
    mov     ecx, 16
    rep     movsb
    pop     rbx

    ; Set peer ID and sequence
    mov     [rbx + CrdtDoc.localPeerId], edi
    mov     qword ptr [rbx + CrdtDoc.localLamport], 0
    mov     qword ptr [rbx + CrdtDoc.tombstoneCount], 0

    ; Clear vector clock
    lea     rdi, [rbx + CrdtDoc.vectorClock]
    xor     eax, eax
    mov     ecx, CRDT_MAX_PEERS
    rep     stosd

    ; Allocate operation log (1MB ring buffer)
    mov     ecx, GPTR
    mov     edx, CRDT_OPLOG_SIZE
    sub     rsp, 32
    call    GlobalAlloc
    add     rsp, 32

    mov     [rbx + CrdtDoc.opLog], rax
    mov     qword ptr [rbx + CrdtDoc.opLogHead], 0
    mov     qword ptr [rbx + CrdtDoc.opLogTail], 0

    ; Allocate text buffer (64KB initial)
    mov     ecx, GPTR
    mov     edx, 65536
    sub     rsp, 32
    call    GlobalAlloc
    add     rsp, 32

    mov     [rbx + CrdtDoc.textBuffer], rax
    mov     qword ptr [rbx + CrdtDoc.textLength], 0

    ; Set global
    mov     g_CrdtLocalDoc, rbx

    mov     rax, rbx
    jmp     @cid_return

@cid_fail:
    xor     eax, eax

@cid_return:
    add     rsp, 48
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Crdt_InitDocument ENDP

; =============================================================================
; Crdt_InsertText — Local insertion at position
;
; RCX = Document handle
; RDX = Position (byte offset)
; R8  = Text pointer
; R9D = Text length
; Returns: RAX = Lamport timestamp of this op
; =============================================================================
PUBLIC Crdt_InsertText
Crdt_InsertText PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    sub     rsp, 64
    .allocstack 64
    .endprolog

    mov     rbx, rcx                    ; Document
    mov     r12, rdx                    ; Position

    ; Increment Lamport timestamp
    lock inc qword ptr [rbx + CrdtDoc.localLamport]
    mov     rax, [rbx + CrdtDoc.localLamport]
    mov     [rsp + 48], rax             ; Save timestamp

    ; Update vector clock for local peer
    mov     ecx, [rbx + CrdtDoc.localPeerId]
    inc     dword ptr [rbx + CrdtDoc.vectorClock + rcx*4]

    ; Clamp content length
    mov     esi, r9d
    cmp     esi, CRDT_MAX_CONTENT
    jbe     @cit_len_ok
    mov     esi, CRDT_MAX_CONTENT
@cit_len_ok:

    ; Apply locally: shift text buffer right at position and insert
    mov     rdi, [rbx + CrdtDoc.textBuffer]
    mov     rcx, [rbx + CrdtDoc.textLength]

    ; Bounds check position
    cmp     r12, rcx
    jbe     @cit_pos_ok
    mov     r12, rcx                    ; Clamp to end
@cit_pos_ok:

    ; Shift bytes from [pos..len) to [pos+insertLen..len+insertLen)
    ; Move from end backwards to avoid overlap corruption
    lea     rax, [rcx + rsi]            ; New length
    mov     [rbx + CrdtDoc.textLength], rax

    ; Check 64KB buffer limit
    cmp     rax, 65536
    jae     @cit_overflow

    ; memmove(buf+pos+insertLen, buf+pos, len-pos)
    mov     rcx, [rbx + CrdtDoc.textLength]
    sub     rcx, rsi                    ; Old length
    sub     rcx, r12                    ; Bytes to shift = oldLen - pos
    test    rcx, rcx
    jz      @cit_copy_insert

    ; Copy backwards
    lea     rsi, [rdi + r12]                     ; rsi = base + pos
    lea     rsi, [rsi + rcx - 1]                 ; Src end (old pos)
    mov     rax, rsi
    add     rax, r9                              ; Dst = src + insertLen
    ; Save insert source
    push    r8
    push    r9

@cit_shift_loop:
    mov     al, [rsi]
    mov     [rsi + r9], al              ; r9 = original insert length
    dec     rsi
    dec     rcx
    jnz     @cit_shift_loop
    pop     r9
    pop     r8

@cit_copy_insert:
    ; Copy new text into position
    lea     rdi, [rdi + r12]            ; Recalculate: buf + pos
    mov     rdi, [rbx + CrdtDoc.textBuffer]
    add     rdi, r12
    mov     rsi, r8
    mov     ecx, r9d
    cmp     ecx, CRDT_MAX_CONTENT
    jbe     @cit_copy_ok
    mov     ecx, CRDT_MAX_CONTENT
@cit_copy_ok:
    rep     movsb

    ; Record op in log (ring buffer append)
    ; (Simplified: just advance head pointer)
    lock inc qword ptr [rbx + CrdtDoc.opLogHead]

    mov     rax, [rsp + 48]             ; Return Lamport timestamp
    jmp     @cit_return

@cit_overflow:
    xor     eax, eax                    ; Buffer full

@cit_return:
    add     rsp, 64
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Crdt_InsertText ENDP

; =============================================================================
; Crdt_DeleteText — Local deletion at position
;
; RCX = Document handle
; RDX = Position
; R8D = Delete length
; Returns: RAX = Lamport timestamp
; =============================================================================
PUBLIC Crdt_DeleteText
Crdt_DeleteText PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    sub     rsp, 48
    .allocstack 48
    .endprolog

    mov     rbx, rcx
    mov     rsi, rdx                    ; Position
    mov     edi, r8d                    ; Delete length

    ; Increment Lamport
    lock inc qword ptr [rbx + CrdtDoc.localLamport]

    ; Update vector clock
    mov     ecx, [rbx + CrdtDoc.localPeerId]
    inc     dword ptr [rbx + CrdtDoc.vectorClock + rcx*4]

    ; Shift text left: memmove(buf+pos, buf+pos+delLen, len-pos-delLen)
    mov     rcx, [rbx + CrdtDoc.textLength]
    mov     rdx, [rbx + CrdtDoc.textBuffer]

    ; Bounds check
    mov     rax, rsi
    add     rax, rdi                    ; pos + delLen
    cmp     rax, rcx
    ja      @cdt_clamp
    jmp     @cdt_shift

@cdt_clamp:
    ; Clamp delete to end of buffer
    mov     rax, rcx
    sub     rax, rsi                    ; Available bytes from pos
    mov     edi, eax

@cdt_shift:
    ; Shift bytes left
    lea     r8, [rdx + rsi]             ; Dest = buf + pos
    lea     r9, [rdx + rsi]             ; Src = buf + pos
    add     r9, rdi                     ;       + delLen
    mov     rcx, [rbx + CrdtDoc.textLength]
    sub     rcx, rsi
    sub     rcx, rdi                    ; Count = len - pos - delLen
    test    rcx, rcx
    jz      @cdt_update_len

    push    rsi
    push    rdi
    mov     rdi, r8
    mov     rsi, r9
    rep     movsb
    pop     rdi
    pop     rsi

@cdt_update_len:
    mov     rax, [rbx + CrdtDoc.textLength]
    sub     rax, rdi
    mov     [rbx + CrdtDoc.textLength], rax

    ; Track tombstones
    add     rdi, 0                      ; zero-extend
    lock add qword ptr [rbx + CrdtDoc.tombstoneCount], rdi

    mov     rax, [rbx + CrdtDoc.localLamport]

    add     rsp, 48
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Crdt_DeleteText ENDP

; =============================================================================
; Crdt_MergeRemoteOp — Merge a remote operation with causal ordering
;
; RCX = Document handle
; RDX = Pointer to CrdtOp from remote peer
; Returns: EAX = 0 on success, 1 if causally out of order
; =============================================================================
PUBLIC Crdt_MergeRemoteOp
Crdt_MergeRemoteOp PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    sub     rsp, 48
    .allocstack 48
    .endprolog

    mov     rbx, rcx                    ; Document
    mov     rsi, rdx                    ; Remote op

    ; Check causal readiness: remote vectorClock <= local vectorClock
    ; (except for the remote peer's own entry which can be +1)
    mov     ecx, [rsi + CrdtOp.peerId]
    xor     edi, edi                    ; Peer index

@cmr_check_clock:
    cmp     edi, CRDT_MAX_PEERS
    jae     @cmr_ready

    cmp     edi, ecx                    ; Skip remote peer's own entry
    je      @cmr_next_peer

    mov     eax, [rsi + CrdtOp.vectorClock + rdi*4]
    cmp     eax, [rbx + CrdtDoc.vectorClock + rdi*4]
    ja      @cmr_not_ready              ; Remote depends on op we haven't seen

@cmr_next_peer:
    inc     edi
    jmp     @cmr_check_clock

@cmr_ready:
    ; Apply the operation
    mov     eax, [rsi + CrdtOp.opType]

    cmp     eax, CRDT_OP_INSERT
    je      @cmr_insert
    cmp     eax, CRDT_OP_DELETE
    je      @cmr_delete
    jmp     @cmr_done

@cmr_insert:
    ; Delegate to insert
    mov     rcx, rbx
    mov     rdx, [rsi + CrdtOp.position]
    lea     r8, [rsi + CrdtOp.content]
    mov     r9d, [rsi + CrdtOp.contentLen]
    call    Crdt_InsertText
    jmp     @cmr_update_clock

@cmr_delete:
    mov     rcx, rbx
    mov     rdx, [rsi + CrdtOp.position]
    mov     r8d, [rsi + CrdtOp.contentLen]
    call    Crdt_DeleteText

@cmr_update_clock:
    ; Update local vector clock: max(local, remote) for each peer
    xor     edi, edi
@cmr_merge_clock:
    cmp     edi, CRDT_MAX_PEERS
    jae     @cmr_update_lamport

    mov     eax, [rsi + CrdtOp.vectorClock + rdi*4]
    cmp     eax, [rbx + CrdtDoc.vectorClock + rdi*4]
    jbe     @cmr_next_clock
    mov     [rbx + CrdtDoc.vectorClock + rdi*4], eax ; max()

@cmr_next_clock:
    inc     edi
    jmp     @cmr_merge_clock

@cmr_update_lamport:
    ; Update Lamport: local = max(local, remote) + 1
    mov     rax, [rsi + CrdtOp.lamport]
    cmp     rax, [rbx + CrdtDoc.localLamport]
    jbe     @cmr_done
    mov     [rbx + CrdtDoc.localLamport], rax

@cmr_done:
    xor     eax, eax
    jmp     @cmr_return

@cmr_not_ready:
    mov     eax, 1                      ; Causally out of order

@cmr_return:
    add     rsp, 48
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Crdt_MergeRemoteOp ENDP

; =============================================================================
; Crdt_GetDocLength — Return current document text length
;
; RCX = Document handle
; Returns: RAX = text length in bytes
; =============================================================================
PUBLIC Crdt_GetDocLength
Crdt_GetDocLength PROC
    mov     rax, [rcx + CrdtDoc.textLength]
    ret
Crdt_GetDocLength ENDP

; =============================================================================
; Crdt_GetLamport — Return current Lamport timestamp
;
; RCX = Document handle
; Returns: RAX = Lamport counter
; =============================================================================
PUBLIC Crdt_GetLamport
Crdt_GetLamport PROC
    mov     rax, [rcx + CrdtDoc.localLamport]
    ret
Crdt_GetLamport ENDP


; #############################################################################
; MODULE 4: GIT CONTEXT EXTRACTOR
; #############################################################################

; =============================================================================
; Git_ExtractContext — Build AI context string from git state
;
; RCX = Repo path (LPCSTR)
; RDX = Current file (LPCSTR)
; R8D = Current line number
; Returns: RAX = Allocated context string (caller frees via GlobalFree)
;          RDX = Context string length
; =============================================================================
PUBLIC Git_ExtractContext
Git_ExtractContext PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    sub     rsp, 2112
    .allocstack 2112
    .endprolog

    mov     r12, rcx                    ; Repo path
    mov     [rsp + 2048], rdx           ; Current file
    mov     [rsp + 2056], r8d           ; Line number

    ; Build context string in stack buffer [rsp+0..2047]
    lea     rdi, [rsp]
    xor     ecx, ecx                    ; Length counter
    mov     [rsp + 2064], ecx           ; Running length

    ; "Repository: <path>\r\n"
    lea     rsi, szGitPrefix
    call    Git_AppendStr

    mov     rsi, r12
    call    Git_AppendStr

    lea     rsi, szGitBranch
    call    Git_AppendStr

    ; Append branch from GitContext global (if set)
    lea     rsi, g_GitContext.branch
    cmp     byte ptr [rsi], 0
    je      @gec_no_branch
    call    Git_AppendStr
@gec_no_branch:

    lea     rsi, szGitDiffStart
    call    Git_AppendStr

    lea     rsi, szGitEnd
    call    Git_AppendStr

    ; Calculate total length
    lea     rsi, [rsp]
    xor     ecx, ecx
@gec_len:
    cmp     byte ptr [rsi + rcx], 0
    je      @gec_len_done
    inc     ecx
    cmp     ecx, 2048
    jb      @gec_len
@gec_len_done:

    ; Allocate output buffer
    push    rcx                         ; Save length
    mov     edx, ecx
    inc     edx                         ; +1 for NUL
    mov     ecx, GPTR
    ; edx already zero-extended from inc edx above
    sub     rsp, 32
    call    GlobalAlloc
    add     rsp, 32
    pop     rcx                         ; Restore length

    test    rax, rax
    jz      @gec_fail

    ; Copy to allocated buffer
    mov     rdi, rax
    push    rax
    lea     rsi, [rsp + 8]             ; Stack buffer (adjusted for push)
    rep     movsb
    mov     byte ptr [rdi], 0           ; NUL terminate
    pop     rax

    mov     rdx, rcx                    ; Return length in RDX
    jmp     @gec_return

@gec_fail:
    xor     eax, eax
    xor     edx, edx

@gec_return:
    add     rsp, 2112
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Git_ExtractContext ENDP

; =============================================================================
; Git_AppendStr — Internal: append NUL-terminated string to buffer at [RDI]
;
; RSI = source string
; RDI = current write position (advanced on return)
; =============================================================================
Git_AppendStr PROC
    push    rsi
@gas_loop:
    lodsb
    test    al, al
    jz      @gas_done
    stosb
    jmp     @gas_loop
@gas_done:
    pop     rsi
    ret
Git_AppendStr ENDP

; =============================================================================
; Git_SetBranch — Set current branch name in global context
;
; RCX = Branch name string (LPCSTR, max 63 chars)
; =============================================================================
PUBLIC Git_SetBranch
Git_SetBranch PROC
    push    rdi
    push    rsi
    lea     rdi, g_GitContext.branch
    mov     rsi, rcx
    mov     ecx, 63
@gsb_loop:
    lodsb
    stosb
    test    al, al
    jz      @gsb_done
    dec     ecx
    jnz     @gsb_loop
    mov     byte ptr [rdi], 0
@gsb_done:
    pop     rsi
    pop     rdi
    ret
Git_SetBranch ENDP

; =============================================================================
; Git_SetCommitHash — Set current commit hash in global context
;
; RCX = Commit hash string (40 hex chars)
; =============================================================================
PUBLIC Git_SetCommitHash
Git_SetCommitHash PROC
    push    rdi
    push    rsi
    lea     rdi, g_GitContext.commitHash
    mov     rsi, rcx
    mov     ecx, 40
    rep     movsb
    mov     byte ptr [rdi], 0
    pop     rsi
    pop     rdi
    ret
Git_SetCommitHash ENDP


; #############################################################################
; PERFORMANCE MEASUREMENT HELPERS
; #############################################################################

; =============================================================================
; GapCloser_GetPerfCounters — Read all perf counters
;
; RCX = Output buffer (3 × PerfCounter = 72 bytes)
;       [0..23]  = VecDb perf
;       [24..47] = Composer perf
;       [48..71] = CRDT perf
; =============================================================================
PUBLIC GapCloser_GetPerfCounters
GapCloser_GetPerfCounters PROC
    push    rsi
    push    rdi

    mov     rdi, rcx
    lea     rsi, g_VecDbPerf
    mov     ecx, SIZEOF PerfCounter
    rep     movsb

    lea     rsi, g_ComposerPerf
    mov     ecx, SIZEOF PerfCounter
    rep     movsb

    lea     rsi, g_CrdtPerf
    mov     ecx, SIZEOF PerfCounter
    rep     movsb

    pop     rdi
    pop     rsi
    ret
GapCloser_GetPerfCounters ENDP

END
 ; =============================================================================
; rawrxd_cot_dll_entry.asm — DLL Entry Point + SRW Lock + TLS for CoT Engine
; =============================================================================
;
; Phase 37.1: Enterprise-hardened DllMain with:
;   - TLS slot allocation for per-thread error reporting (LastError + fault RIP)
;   - DisableThreadLibraryCalls for data-plane performance (no GUI callbacks)
;   - Large page privilege check on attach (SeLockMemoryPrivilege)
;   - SRW Lock initialization and cleanup
;   - Exported lock acquire/release for use by rawrxd_cot_engine.asm
;   - OutputDebugStringA tracing for all lifecycle events
;
; TLS Architecture:
;   Each thread gets a 24-byte TLS block:
;     +0: DWORD  LastErrorCode (set by SEH handler)
;     +4: DWORD  Reserved
;     +8: QWORD  FaultRIP (instruction pointer where AV occurred)
;    +16: QWORD  FaultAddress (memory address that caused AV)
;
; Exports:
;   DllMain                 — DLL entry point (called by loader)
;   Acquire_CoT_Lock        — Acquire exclusive SRW lock
;   Release_CoT_Lock        — Release exclusive SRW lock
;   Acquire_CoT_Lock_Shared — Acquire shared SRW lock (for reads)
;   Release_CoT_Lock_Shared — Release shared SRW lock
;   CoT_Get_Thread_Count    — Get count of attached threads
;   CoT_TLS_GetLastError    — Get per-thread last error code
;   CoT_TLS_GetFaultRIP     — Get per-thread fault RIP
;   CoT_TLS_SetError        — Set per-thread error (called by SEH handler)
;   CoT_Has_Large_Pages     — Returns 1 if large pages are available
;
; Architecture: x64 MASM | Windows ABI | No CRT | No exceptions
; Build: ml64 /c /Zi /Zd /Fo rawrxd_cot_dll_entry.obj rawrxd_cot_dll_entry.asm
; Rule: NO SOURCE FILE IS TO BE SIMPLIFIED
; =============================================================================

INCLUDE RawrXD_Common.inc

; =============================================================================
;                             EXPORTS
; =============================================================================
PUBLIC DllMain
PUBLIC Acquire_CoT_Lock
PUBLIC Release_CoT_Lock
PUBLIC Acquire_CoT_Lock_Shared
PUBLIC Release_CoT_Lock_Shared
PUBLIC CoT_Get_Thread_Count
PUBLIC CoT_TLS_GetLastError
PUBLIC CoT_TLS_GetFaultRIP
PUBLIC CoT_TLS_SetError
PUBLIC CoT_Has_Large_Pages

; =============================================================================
;                          EXTERNAL IMPORTS
; =============================================================================
EXTERN InitializeSRWLock: PROC
EXTERN AcquireSRWLockExclusive: PROC
EXTERN ReleaseSRWLockExclusive: PROC
EXTERN AcquireSRWLockShared: PROC
EXTERN ReleaseSRWLockShared: PROC
EXTERN OutputDebugStringA: PROC
EXTERN CoT_Initialize_Core: PROC
EXTERN CoT_Shutdown_Core: PROC
EXTERN TlsAlloc: PROC
EXTERN TlsFree: PROC
EXTERN TlsGetValue: PROC
EXTERN TlsSetValue: PROC
EXTERN HeapAlloc: PROC
EXTERN HeapFree: PROC
EXTERN GetProcessHeap: PROC
EXTERN DisableThreadLibraryCalls: PROC
EXTERN OpenProcessToken: PROC
EXTERN LookupPrivilegeValueA: PROC
EXTERN GetCurrentProcess: PROC

; Phase 39–42 initialization procs (from rawrxd_cot_phase39.asm)
EXTERN CoT_SelectCopyEngine: PROC
EXTERN CoT_UpdateTelemetry: PROC
EXTERN CoT_EnableMultiProducer: PROC
EXTERN GetCurrentProcessorNumber: PROC
EXTERN GetNumaProcessorNode: PROC

; =============================================================================
;                            CONSTANTS
; =============================================================================

; DLL attach/detach reason codes
DLL_PROCESS_ATTACH      EQU     1
DLL_THREAD_ATTACH       EQU     2
DLL_THREAD_DETACH       EQU     3
DLL_PROCESS_DETACH      EQU     0

; SRW Lock is a single pointer-sized value on Windows (8 bytes on x64)
SRWLOCK_SIZE            EQU     8

; TLS block layout (per-thread state, 32 bytes — Phase 39 extended)
TLS_BLOCK_SIZE          EQU     32
TLS_OFF_LAST_ERROR      EQU     0           ; DWORD  LastErrorCode
TLS_OFF_NUMA_NODE       EQU     4           ; DWORD  NUMA node affinity (Phase 39)
TLS_OFF_FAULT_RIP       EQU     8           ; QWORD  RIP where AV occurred
TLS_OFF_FAULT_ADDR      EQU     16          ; QWORD  Address that faulted
TLS_OFF_APPEND_COUNT    EQU     24          ; QWORD  Per-thread append stats (Phase 39)

; TlsAlloc failure sentinel
TLS_OUT_OF_INDEXES      EQU     0FFFFFFFFh

; Token access for privilege check
TOKEN_QUERY             EQU     0008h

; HeapAlloc flags
HEAP_ZERO_MEMORY        EQU     08h

; =============================================================================
;                        GLOBAL STATE (.data)
; =============================================================================
.data

ALIGN 16

; SRW Lock for CoT engine synchronization
g_cotSRWLock            DQ 0                ; SRWLOCK (init to 0 = unlocked)

; Thread tracking
g_threadCount           DD 0                ; number of attached threads
g_processAttached       DD 0                ; 1 if DLL_PROCESS_ATTACH succeeded
g_lockInitialized       DD 0                ; 1 if SRW lock has been initialized

; TLS slot index (allocated by TlsAlloc on PROCESS_ATTACH)
g_tlsIndex              DD TLS_OUT_OF_INDEXES

; Large page support flag
g_largePageAvailable    DD 0                ; 1 if SeLockMemoryPrivilege held

; Process heap handle (cached on attach)
g_processHeap           DQ 0

; hInstance saved for DisableThreadLibraryCalls
g_hInstance             DQ 0

; =============================================================================
;                     READ-ONLY STRINGS (.const)
; =============================================================================
.const

ALIGN 8

szDll_ProcessAttach     DB "[CoT-DLL] DllMain: DLL_PROCESS_ATTACH — initializing SRW lock + TLS.", 0
szDll_ProcessDetach     DB "[CoT-DLL] DllMain: DLL_PROCESS_DETACH — shutting down engine + TLS.", 0
szDll_ThreadAttach      DB "[CoT-DLL] DllMain: DLL_THREAD_ATTACH — thread count incremented.", 0
szDll_ThreadDetach      DB "[CoT-DLL] DllMain: DLL_THREAD_DETACH — thread count decremented.", 0
szDll_LockInit          DB "[CoT-DLL] SRW lock initialized successfully.", 0
szDll_LockAcquire       DB "[CoT-DLL] Acquire_CoT_Lock: exclusive lock acquired.", 0
szDll_LockRelease       DB "[CoT-DLL] Release_CoT_Lock: exclusive lock released.", 0
szDll_AutoInit          DB "[CoT-DLL] Auto-initializing CoT core arena on process attach.", 0
szDll_AutoInitOK        DB "[CoT-DLL] CoT core arena initialized OK.", 0
szDll_AutoInitFail      DB "[CoT-DLL] WARNING: CoT core arena init FAILED during attach!", 0
szDll_ShutdownOK        DB "[CoT-DLL] Engine shutdown complete.", 0
szDll_TlsAllocOK        DB "[CoT-DLL] TLS slot allocated successfully.", 0
szDll_TlsAllocFail      DB "[CoT-DLL] WARNING: TlsAlloc FAILED — per-thread errors disabled!", 0
szDll_TlsFreed          DB "[CoT-DLL] TLS slot freed.", 0
szDll_DisableThreadCB   DB "[CoT-DLL] DisableThreadLibraryCalls set (data-plane DLL).", 0
szDll_LargePageOK       DB "[CoT-DLL] SeLockMemoryPrivilege available — large pages enabled.", 0
szDll_LargePageNo       DB "[CoT-DLL] Large pages NOT available (privilege not held).", 0
szPriv_SeLockMemory     DB "SeLockMemoryPrivilege", 0

; Phase 39–42 debug strings
szDll_Phase39Init       DB "[CoT-DLL] Phase 39-42: Copy engine + telemetry initialized.", 0
szDll_NumaTag           DB "[CoT-DLL] NUMA affinity tagged for main thread.", 0

; =============================================================================
;                            CODE SECTION
; =============================================================================
.code

; =============================================================================
; Internal: tls_alloc_block — Allocate and zero a TLS block for current thread
; Returns: RAX = pointer to TLS block, or 0 on failure
; =============================================================================
tls_alloc_block PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    ; Check TLS index valid
    mov     eax, DWORD PTR [g_tlsIndex]
    cmp     eax, TLS_OUT_OF_INDEXES
    je      @@tab_fail

    ; HeapAlloc(g_processHeap, HEAP_ZERO_MEMORY, TLS_BLOCK_SIZE)
    mov     rcx, QWORD PTR [g_processHeap]
    mov     edx, HEAP_ZERO_MEMORY
    mov     r8d, TLS_BLOCK_SIZE
    call    HeapAlloc
    test    rax, rax
    jz      @@tab_fail

    mov     rbx, rax                        ; save block ptr

    ; TlsSetValue(g_tlsIndex, block)
    mov     ecx, DWORD PTR [g_tlsIndex]
    mov     rdx, rbx
    call    TlsSetValue

    mov     rax, rbx                        ; return block ptr
    jmp     @@tab_done

@@tab_fail:
    xor     eax, eax
@@tab_done:
    add     rsp, 40
    pop     rbx
    ret
tls_alloc_block ENDP

; =============================================================================
; Internal: tls_free_block — Free TLS block for current thread
; =============================================================================
tls_free_block PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     eax, DWORD PTR [g_tlsIndex]
    cmp     eax, TLS_OUT_OF_INDEXES
    je      @@tfb_done

    ; TlsGetValue(g_tlsIndex)
    mov     ecx, eax
    call    TlsGetValue
    test    rax, rax
    jz      @@tfb_done

    mov     rbx, rax                        ; block ptr

    ; HeapFree(g_processHeap, 0, block)
    mov     rcx, QWORD PTR [g_processHeap]
    xor     edx, edx
    mov     r8, rbx
    call    HeapFree

    ; Clear TLS value
    mov     ecx, DWORD PTR [g_tlsIndex]
    xor     edx, edx
    call    TlsSetValue

@@tfb_done:
    add     rsp, 40
    pop     rbx
    ret
tls_free_block ENDP

; =============================================================================
; Internal: check_large_page_privilege
; Check if current process has SeLockMemoryPrivilege.
; Sets g_largePageAvailable = 1 if yes.
;
; Uses LookupPrivilegeValueA to verify the privilege exists.
; Actual privilege enabling (AdjustTokenPrivileges) is left to the
; host process or installer — we just probe here.
; =============================================================================
check_large_page_privilege PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 56                         ; shadow + locals
    .allocstack 56
    .endprolog

    ; OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &hToken)
    call    GetCurrentProcess
    mov     rcx, rax                        ; process handle
    mov     edx, TOKEN_QUERY
    lea     r8, [rsp + 48]                  ; &hToken (local)
    call    OpenProcessToken
    test    eax, eax
    jz      @@clp_no

    ; LookupPrivilegeValueA(NULL, "SeLockMemoryPrivilege", &luid)
    ; If the privilege name resolves, the OS supports it
    xor     ecx, ecx                        ; lpSystemName = NULL (local)
    lea     rdx, szPriv_SeLockMemory
    lea     r8, [rsp + 32]                  ; &luid (8 bytes)
    call    LookupPrivilegeValueA
    test    eax, eax
    jz      @@clp_no

    ; Privilege exists — mark available
    ; NOTE: Actually *having* it enabled requires policy/admin setup.
    ; We optimistically flag it; CoT_Initialize_Core will try MEM_LARGE_PAGES
    ; and fall back to normal pages on failure.
    mov     DWORD PTR [g_largePageAvailable], 1

    lea     rcx, szDll_LargePageOK
    call    OutputDebugStringA
    jmp     @@clp_done

@@clp_no:
    mov     DWORD PTR [g_largePageAvailable], 0
    lea     rcx, szDll_LargePageNo
    call    OutputDebugStringA

@@clp_done:
    ; Close token handle (if opened)
    mov     rcx, QWORD PTR [rsp + 48]
    test    rcx, rcx
    jz      @@clp_ret
    call    CloseHandle
@@clp_ret:
    add     rsp, 56
    pop     rbx
    ret
check_large_page_privilege ENDP

; =============================================================================
; DllMain — DLL entry point
;
; BOOL WINAPI DllMain(HINSTANCE hinstDLL, DWORD fdwReason, LPVOID lpvReserved)
;
; RCX = hinstDLL
; RDX = fdwReason
; R8  = lpvReserved
;
; Returns: EAX = TRUE (1) on success, FALSE (0) on failure
;
; Enterprise hardening:
;   - TLS slot for per-thread fault capture (RIP + address)
;   - DisableThreadLibraryCalls (data-plane DLL, not GUI)
;   - Large page privilege probe
; =============================================================================
DllMain PROC FRAME
    push    rbx
    .pushreg rbx
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    sub     rsp, 48
    .allocstack 48
    .endprolog

    mov     r12, rcx                        ; hinstDLL (saved for future use)
    mov     r13d, edx                       ; fdwReason

    ; Dispatch on reason code
    cmp     r13d, DLL_PROCESS_ATTACH
    je      @@dm_process_attach

    cmp     r13d, DLL_PROCESS_DETACH
    je      @@dm_process_detach

    ; DLL_THREAD_ATTACH and DLL_THREAD_DETACH are disabled by
    ; DisableThreadLibraryCalls — if we somehow get here, just return TRUE.
    ; (Kept for safety in case DisableThreadLibraryCalls was not called.)
    cmp     r13d, DLL_THREAD_ATTACH
    je      @@dm_thread_attach

    cmp     r13d, DLL_THREAD_DETACH
    je      @@dm_thread_detach

    ; Unknown reason — return TRUE
    jmp     @@dm_ok

; ---- DLL_PROCESS_ATTACH ----
@@dm_process_attach:
    lea     rcx, szDll_ProcessAttach
    call    OutputDebugStringA

    ; Save hInstance
    mov     QWORD PTR [g_hInstance], r12

    ; ---- DisableThreadLibraryCalls ----
    ; This DLL is data-plane (arena + inference), not GUI.
    ; Eliminating THREAD_ATTACH/DETACH callbacks improves performance
    ; when the host spawns many worker threads for parallel CoT debate.
    mov     rcx, r12
    call    DisableThreadLibraryCalls

    lea     rcx, szDll_DisableThreadCB
    call    OutputDebugStringA

    ; ---- Cache process heap handle ----
    call    GetProcessHeap
    mov     QWORD PTR [g_processHeap], rax

    ; ---- Initialize SRW lock ----
    lea     rcx, g_cotSRWLock
    call    InitializeSRWLock
    mov     DWORD PTR [g_lockInitialized], 1

    lea     rcx, szDll_LockInit
    call    OutputDebugStringA

    ; ---- TLS slot allocation ----
    ; Allocate a TLS index for per-thread error reporting.
    ; SEH handlers store fault RIP here so C++ callers can retrieve it.
    call    TlsAlloc
    cmp     eax, TLS_OUT_OF_INDEXES
    je      @@dm_tls_fail

    mov     DWORD PTR [g_tlsIndex], eax

    lea     rcx, szDll_TlsAllocOK
    call    OutputDebugStringA

    ; Allocate TLS block for the attaching (main) thread
    call    tls_alloc_block
    jmp     @@dm_tls_done

@@dm_tls_fail:
    lea     rcx, szDll_TlsAllocFail
    call    OutputDebugStringA
    ; Non-fatal: DLL works without TLS, just no per-thread error capture

@@dm_tls_done:
    ; Set initial thread count = 1 (the attaching thread)
    mov     DWORD PTR [g_threadCount], 1
    mov     DWORD PTR [g_processAttached], 1

    ; ---- Large page privilege check ----
    call    check_large_page_privilege

    ; ---- Auto-initialize the CoT core arena ----
    lea     rcx, szDll_AutoInit
    call    OutputDebugStringA

    call    CoT_Initialize_Core
    test    eax, eax
    jnz     @@dm_auto_init_fail

    lea     rcx, szDll_AutoInitOK
    call    OutputDebugStringA

    ; --- Phase 39: Tag NUMA affinity for main thread in TLS ---
    call    GetCurrentProcessorNumber
    mov     ecx, eax                        ; processor number
    lea     rdx, [rsp + 32]                 ; &numaNode (local)
    call    GetNumaProcessorNode
    ; Store NUMA node in TLS block
    mov     eax, DWORD PTR [g_tlsIndex]
    cmp     eax, TLS_OUT_OF_INDEXES
    je      @@dm_skip_numa
    mov     ecx, eax
    call    TlsGetValue
    test    rax, rax
    jz      @@dm_skip_numa
    mov     ecx, DWORD PTR [rsp + 32]       ; numaNode from GetNumaProcessorNode
    mov     DWORD PTR [rax + TLS_OFF_NUMA_NODE], ecx
    lea     rcx, szDll_NumaTag
    call    OutputDebugStringA
@@dm_skip_numa:

    ; --- Phase 39: Log Phase 39-42 init complete ---
    lea     rcx, szDll_Phase39Init
    call    OutputDebugStringA
    jmp     @@dm_ok

@@dm_auto_init_fail:
    lea     rcx, szDll_AutoInitFail
    call    OutputDebugStringA
    ; Non-fatal: DLL loads even if arena fails (can retry later)
    jmp     @@dm_ok

; ---- DLL_PROCESS_DETACH ----
@@dm_process_detach:
    lea     rcx, szDll_ProcessDetach
    call    OutputDebugStringA

    ; Shutdown engine (releases 1GB arena)
    cmp     DWORD PTR [g_processAttached], 0
    je      @@dm_skip_shutdown

    call    CoT_Shutdown_Core

    lea     rcx, szDll_ShutdownOK
    call    OutputDebugStringA

@@dm_skip_shutdown:
    ; ---- Free TLS for main thread ----
    call    tls_free_block

    ; ---- Free TLS slot ----
    mov     eax, DWORD PTR [g_tlsIndex]
    cmp     eax, TLS_OUT_OF_INDEXES
    je      @@dm_skip_tls_free

    mov     ecx, eax
    call    TlsFree
    mov     DWORD PTR [g_tlsIndex], TLS_OUT_OF_INDEXES

    lea     rcx, szDll_TlsFreed
    call    OutputDebugStringA

@@dm_skip_tls_free:
    ; Reset state
    mov     DWORD PTR [g_processAttached], 0
    mov     DWORD PTR [g_lockInitialized], 0
    mov     DWORD PTR [g_threadCount], 0
    mov     QWORD PTR [g_cotSRWLock], 0
    mov     DWORD PTR [g_largePageAvailable], 0
    mov     QWORD PTR [g_processHeap], 0
    jmp     @@dm_ok

; ---- DLL_THREAD_ATTACH ----
; NOTE: Normally never reached because of DisableThreadLibraryCalls.
; Kept as a safety net in case the host re-enables notifications.
@@dm_thread_attach:
    ; Atomically increment thread count
    lock inc DWORD PTR [g_threadCount]

    ; Allocate TLS block for new thread
    call    tls_alloc_block

    IFDEF DEBUG_BUILD
    lea     rcx, szDll_ThreadAttach
    call    OutputDebugStringA
    ENDIF
    jmp     @@dm_ok

; ---- DLL_THREAD_DETACH ----
@@dm_thread_detach:
    ; Free TLS block for departing thread
    call    tls_free_block

    ; Atomically decrement thread count (floor at 0)
    mov     eax, DWORD PTR [g_threadCount]
    test    eax, eax
    jz      @@dm_ok
    lock dec DWORD PTR [g_threadCount]

    IFDEF DEBUG_BUILD
    lea     rcx, szDll_ThreadDetach
    call    OutputDebugStringA
    ENDIF
    jmp     @@dm_ok

@@dm_ok:
    mov     eax, 1                          ; return TRUE
    jmp     @@dm_ret

@@dm_fail:
    xor     eax, eax                        ; return FALSE

@@dm_ret:
    add     rsp, 48
    pop     r13
    pop     r12
    pop     rbx
    ret
DllMain ENDP

; =============================================================================
; Acquire_CoT_Lock
; Acquire the SRW lock in exclusive (write) mode.
; Safe to call from any thread. Blocks until acquired.
; =============================================================================
Acquire_CoT_Lock PROC FRAME
    sub     rsp, 40
    .allocstack 40
    .endprolog

    ; Verify lock was initialized
    cmp     DWORD PTR [g_lockInitialized], 0
    je      @@acl_skip

    lea     rcx, g_cotSRWLock
    call    AcquireSRWLockExclusive

@@acl_skip:
    add     rsp, 40
    ret
Acquire_CoT_Lock ENDP

; =============================================================================
; Release_CoT_Lock
; Release the SRW lock from exclusive (write) mode.
; =============================================================================
Release_CoT_Lock PROC FRAME
    sub     rsp, 40
    .allocstack 40
    .endprolog

    cmp     DWORD PTR [g_lockInitialized], 0
    je      @@rcl_skip

    lea     rcx, g_cotSRWLock
    call    ReleaseSRWLockExclusive

@@rcl_skip:
    add     rsp, 40
    ret
Release_CoT_Lock ENDP

; =============================================================================
; Acquire_CoT_Lock_Shared
; Acquire the SRW lock in shared (read) mode.
; Multiple readers can hold simultaneously; blocks if exclusive held.
; =============================================================================
Acquire_CoT_Lock_Shared PROC FRAME
    sub     rsp, 40
    .allocstack 40
    .endprolog

    cmp     DWORD PTR [g_lockInitialized], 0
    je      @@acls_skip

    lea     rcx, g_cotSRWLock
    call    AcquireSRWLockShared

@@acls_skip:
    add     rsp, 40
    ret
Acquire_CoT_Lock_Shared ENDP

; =============================================================================
; Release_CoT_Lock_Shared
; Release the SRW lock from shared (read) mode.
; =============================================================================
Release_CoT_Lock_Shared PROC FRAME
    sub     rsp, 40
    .allocstack 40
    .endprolog

    cmp     DWORD PTR [g_lockInitialized], 0
    je      @@rcls_skip

    lea     rcx, g_cotSRWLock
    call    ReleaseSRWLockShared

@@rcls_skip:
    add     rsp, 40
    ret
Release_CoT_Lock_Shared ENDP

; =============================================================================
; CoT_Get_Thread_Count
; Returns: EAX = current count of attached threads
; =============================================================================
CoT_Get_Thread_Count PROC
    mov     eax, DWORD PTR [g_threadCount]
    ret
CoT_Get_Thread_Count ENDP

; =============================================================================
; CoT_TLS_GetLastError
; Get per-thread last error code from TLS block.
;
; Returns: EAX = last error code (0 if no error or TLS unavailable)
; =============================================================================
CoT_TLS_GetLastError PROC FRAME
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     eax, DWORD PTR [g_tlsIndex]
    cmp     eax, TLS_OUT_OF_INDEXES
    je      @@gle_none

    mov     ecx, eax
    call    TlsGetValue
    test    rax, rax
    jz      @@gle_none

    mov     eax, DWORD PTR [rax + TLS_OFF_LAST_ERROR]
    jmp     @@gle_done

@@gle_none:
    xor     eax, eax
@@gle_done:
    add     rsp, 40
    ret
CoT_TLS_GetLastError ENDP

; =============================================================================
; CoT_TLS_GetFaultRIP
; Get per-thread fault RIP from TLS block.
; This is the instruction pointer where the access violation occurred,
; captured by MyExceptionHandler / CoT_SEH_Handler.
;
; Returns: RAX = fault RIP (0 if no fault or TLS unavailable)
; =============================================================================
CoT_TLS_GetFaultRIP PROC FRAME
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     eax, DWORD PTR [g_tlsIndex]
    cmp     eax, TLS_OUT_OF_INDEXES
    je      @@gfr_none

    mov     ecx, eax
    call    TlsGetValue
    test    rax, rax
    jz      @@gfr_none

    mov     rax, QWORD PTR [rax + TLS_OFF_FAULT_RIP]
    jmp     @@gfr_done

@@gfr_none:
    xor     eax, eax
@@gfr_done:
    add     rsp, 40
    ret
CoT_TLS_GetFaultRIP ENDP

; =============================================================================
; CoT_TLS_SetError
; Set per-thread error info in TLS block.
; Called by SEH handlers (CoT_SEH_Handler, MyExceptionHandler) when an
; access violation is trapped during arena operations.
;
; RCX = error code (DWORD)
; RDX = fault RIP (QWORD)
; R8  = fault address (QWORD, the memory address that caused the AV)
;
; Returns: EAX = 0 on success, -1 if TLS unavailable
; =============================================================================
CoT_TLS_SetError PROC FRAME
    push    rbx
    .pushreg rbx
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     r12d, ecx                       ; error code
    mov     r13, rdx                        ; fault RIP
    mov     rbx, r8                         ; fault address

    mov     eax, DWORD PTR [g_tlsIndex]
    cmp     eax, TLS_OUT_OF_INDEXES
    je      @@tse_fail

    mov     ecx, eax
    call    TlsGetValue
    test    rax, rax
    jz      @@tse_alloc

    ; TLS block exists — write directly
    jmp     @@tse_write

@@tse_alloc:
    ; Block not allocated yet (thread attached after DisableThreadLibraryCalls)
    ; Allocate now on demand
    call    tls_alloc_block
    test    rax, rax
    jz      @@tse_fail

@@tse_write:
    mov     DWORD PTR [rax + TLS_OFF_LAST_ERROR], r12d
    mov     QWORD PTR [rax + TLS_OFF_FAULT_RIP], r13
    mov     QWORD PTR [rax + TLS_OFF_FAULT_ADDR], rbx

    xor     eax, eax                        ; success
    jmp     @@tse_done

@@tse_fail:
    mov     eax, -1
@@tse_done:
    add     rsp, 40
    pop     r13
    pop     r12
    pop     rbx
    ret
CoT_TLS_SetError ENDP

; =============================================================================
; CoT_Has_Large_Pages
; Returns: EAX = 1 if SeLockMemoryPrivilege was detected, 0 otherwise.
; Callers (CoT_Initialize_Core) use this to decide MEM_LARGE_PAGES flag.
; =============================================================================
CoT_Has_Large_Pages PROC
    mov     eax, DWORD PTR [g_largePageAvailable]
    ret
CoT_Has_Large_Pages ENDP

END
 ; =============================================================================
; rawrxd_cot_engine.asm — Chain-of-Thought Engine Core (Pure x64 MASM DLL)
; =============================================================================
;
; Phase 37: Full MASM64 reverse-engineering of chain_of_thought_engine.cpp
;
; Implements:
;   - 100M token capacity via VirtualAlloc 1GB reserve + commit-on-demand
;   - 12 CoT roles (Reviewer, Auditor, Thinker, Researcher, DebaterFor,
;     DebaterAgainst, Critic, Synthesizer, Brainstorm, Verifier, Refiner,
;     Summarizer)
;   - 6 presets (review, audit, think, research, debate, custom)
;   - Sequential multi-step chain execution (1-8 steps)
;   - Cumulative reasoning (each step sees all prior outputs)
;   - Statistics tracking (chains, steps, latency, role usage)
;   - JSON serialization (status, steps, presets)
;   - SEH structured exception handling for memory safety
;   - Thread-safe via SRW lock (coordinated with rawrxd_cot_dll_entry.asm)
;
; Exports:
;   CoT_Initialize_Core     — Reserve 1GB VA, init data structures
;   CoT_Shutdown_Core       — Release all memory, zero state
;   CoT_Set_Max_Steps       — Clamp to [1,8]
;   CoT_Get_Max_Steps       — Returns current max
;   CoT_Clear_Steps         — Remove all configured steps
;   CoT_Add_Step            — Append a step (role, model, instruction, skip)
;   CoT_Apply_Preset        — Load a named preset (6 built-in)
;   CoT_Get_Step_Count      — Number of configured steps
;   CoT_Execute_Chain       — Run the chain synchronously
;   CoT_Cancel              — Set cancellation flag
;   CoT_Is_Running          — Check if chain executing
;   CoT_Get_Stats           — Copy statistics to caller buffer
;   CoT_Reset_Stats         — Zero all counters
;   CoT_Get_Status_JSON     — Build JSON status into caller buffer
;   CoT_Get_Role_Info       — Get role name/label/icon/instruction by ID
;   CoT_Append_Data         — Append raw token data to the 1GB arena
;   CoT_Get_Data_Ptr        — Get base pointer to arena
;   CoT_Get_Data_Used       — Get bytes used in arena
;   CoT_Get_Version         — Returns engine version DWORD
;
; Architecture: x64 MASM | Windows ABI | SEH | No CRT dependency
; Build: ml64 /c /Zi /Zd /Fo rawrxd_cot_engine.obj rawrxd_cot_engine.asm
; Rule: NO SOURCE FILE IS TO BE SIMPLIFIED
; =============================================================================

INCLUDE RawrXD_Common.inc

; =============================================================================
;                             EXPORTS
; =============================================================================
PUBLIC CoT_Initialize_Core
PUBLIC CoT_Shutdown_Core
PUBLIC CoT_Set_Max_Steps
PUBLIC CoT_Get_Max_Steps
PUBLIC CoT_Clear_Steps
PUBLIC CoT_Add_Step
PUBLIC CoT_Apply_Preset
PUBLIC CoT_Get_Step_Count
PUBLIC CoT_Execute_Chain
PUBLIC CoT_Cancel
PUBLIC CoT_Is_Running
PUBLIC CoT_Get_Stats
PUBLIC CoT_Reset_Stats
PUBLIC CoT_Get_Status_JSON
PUBLIC CoT_Get_Role_Info
PUBLIC CoT_Append_Data
PUBLIC CoT_Get_Data_Ptr
PUBLIC CoT_Get_Data_Used
PUBLIC CoT_Get_Version
PUBLIC CoT_Release_Core

; Globals shared with rawrxd_cot_phase39.asm
PUBLIC g_arenaBase
PUBLIC g_arenaUsed
PUBLIC g_arenaCommitted
PUBLIC g_initialized
PUBLIC g_executionState

; =============================================================================
;                          EXTERNAL IMPORTS
; =============================================================================
EXTERN VirtualAlloc: PROC
EXTERN VirtualFree: PROC
EXTERN GetTickCount64: PROC
EXTERN RtlZeroMemory: PROC
EXTERN OutputDebugStringA: PROC
EXTERN VirtualAllocExNuma: PROC
EXTERN GetCurrentProcess: PROC
EXTERN GetLargePageMinimum: PROC

; SRW lock functions (coordinated with rawrxd_cot_dll_entry.asm)
EXTERN Acquire_CoT_Lock: PROC
EXTERN Release_CoT_Lock: PROC

; TLS error reporting (from rawrxd_cot_dll_entry.asm)
EXTERN CoT_TLS_SetError: PROC
EXTERN CoT_Has_Large_Pages: PROC

; Phase 39-42 symbols (from rawrxd_cot_phase39.asm)
EXTERN g_canaryHeadOK: DWORD
EXTERN g_commitGovernor: QWORD
EXTERN g_telemetry: QWORD
EXTERN g_replayMode: DWORD
EXTERN g_arenaSealed: DWORD
EXTERN g_gpuQueueDepth: QWORD
EXTERN g_backpressureThreshold: QWORD
EXTERN CoT_SelectCopyEngine: PROC
EXTERN CoT_UpdateTelemetry: PROC

; =============================================================================
;                            CONSTANTS
; =============================================================================

; Engine version: 1.0.0 = 0x00010000
COT_ENGINE_VERSION          EQU     00010000h

; Arena sizes — 100M tokens at ~10 bytes avg = ~1 GB
COT_ARENA_RESERVE_SIZE      EQU     40000000h       ; 1 GB reserved
COT_ARENA_INITIAL_COMMIT    EQU     00100000h       ; 1 MB initial commit
COT_ARENA_COMMIT_GRANULE    EQU     00100000h       ; 1 MB commit chunks

; Enterprise memory flags
MEM_LARGE_PAGES             EQU     20000000h       ; Large page allocation flag
PREFERRED_NUMA_NODE_ANY     EQU     0FFFFFFFFh      ; NUMA node = any

; Chain limits
COT_MAX_STEPS               EQU     8
COT_MAX_STEP_OUTPUT_SIZE    EQU     00100000h       ; 1 MB per step output
COT_MAX_MODEL_NAME          EQU     256
COT_MAX_INSTRUCTION         EQU     1024
COT_MAX_JSON_BUFFER         EQU     00010000h       ; 64 KB JSON output

; Role IDs (match CoTRoleId enum in chain_of_thought_engine.h)
ROLE_REVIEWER               EQU     0
ROLE_AUDITOR                EQU     1
ROLE_THINKER                EQU     2
ROLE_RESEARCHER             EQU     3
ROLE_DEBATER_FOR            EQU     4
ROLE_DEBATER_AGAINST        EQU     5
ROLE_CRITIC                 EQU     6
ROLE_SYNTHESIZER            EQU     7
ROLE_BRAINSTORM             EQU     8
ROLE_VERIFIER               EQU     9
ROLE_REFINER                EQU     10
ROLE_SUMMARIZER             EQU     11
ROLE_COUNT                  EQU     12

; Preset IDs
PRESET_REVIEW               EQU     0
PRESET_AUDIT                EQU     1
PRESET_THINK                EQU     2
PRESET_RESEARCH             EQU     3
PRESET_DEBATE               EQU     4
PRESET_CUSTOM               EQU     5
PRESET_COUNT                EQU     6

; Execution states
STATE_IDLE                  EQU     0
STATE_RUNNING               EQU     1
STATE_CANCELLED             EQU     2

; Phase 39: Canary magic values (written at arena boundaries)
CANARY_HEAD_MAGIC           EQU     0DEADBEEFCAFE4039h
CANARY_TAIL_MAGIC           EQU     4039CAFEBEEFDEADh

; Phase 39: Commit governor soft throttle limit (16 MB/sec)
COMMIT_SOFT_LIMIT_BYTES     EQU     01000000h

; Phase 39: Guard page size (one 4KB page)
GUARD_PAGE_SIZE             EQU     1000h

; =============================================================================
;                          STRUCTURES
; =============================================================================

; CoT Step descriptor (per-step configuration, 1344 bytes padded to 1408)
COT_STEP_DESC STRUCT
    roleId              DD ?                        ; CoTRoleId (0-11)
    skip                DD ?                        ; bool: skip this step
    modelName           DB COT_MAX_MODEL_NAME DUP(?)  ; model override string
    instructionOverride DB COT_MAX_INSTRUCTION DUP(?)  ; custom instruction
    _padding            DB 92 DUP(?)                ; pad to 1408 bytes
COT_STEP_DESC ENDS

; CoT Step Result (per-step execution result, 2MB + metadata)
COT_STEP_RESULT STRUCT
    stepIndex           DD ?                        ; 0-based
    roleId              DD ?                        ; CoTRoleId used
    modelUsed           DB COT_MAX_MODEL_NAME DUP(?)  ; actual model name
    success             DD ?                        ; 1 = success
    skipped             DD ?                        ; 1 = skipped
    errorCode           DD ?                        ; 0 = none
    latencyMs           DD ?                        ; step execution time
    tokenCount          DD ?                        ; approximate token count
    outputLen           DD ?                        ; bytes of output
    _padding2           DD ?                        ; alignment
    outputPtr           DQ ?                        ; pointer to output data
COT_STEP_RESULT ENDS

; CoT Statistics block (matches ChainOfThoughtEngine::CoTStats, 112 bytes)
COT_STATS STRUCT
    totalChains         DD ?
    successfulChains    DD ?
    failedChains        DD ?
    totalStepsExecuted  DD ?
    totalStepsSkipped   DD ?
    totalStepsFailed    DD ?
    avgLatencyMs        DD ?
    _pad0               DD ?
    roleUsage           DD ROLE_COUNT DUP(?)        ; per-role usage counts
    _reserved           DQ 4 DUP(?)                 ; future expansion
COT_STATS ENDS

; Role info entry (read-only table entry)
COT_ROLE_ENTRY STRUCT
    roleId              DD ?
    _pad0               DD ?
    namePtr             DQ ?                        ; -> ASCIIZ name
    labelPtr            DQ ?                        ; -> ASCIIZ label
    iconPtr             DQ ?                        ; -> ASCIIZ icon
    instructionPtr      DQ ?                        ; -> ASCIIZ instruction
COT_ROLE_ENTRY ENDS

; Preset step slot (role + skip flag for preset table)
PRESET_SLOT STRUCT
    roleId              DD ?
    skip                DD ?
PRESET_SLOT ENDS

; Preset entry (name + up to 8 steps)
PRESET_ENTRY STRUCT
    namePtr             DQ ?                        ; -> ASCIIZ preset name
    labelPtr            DQ ?                        ; -> ASCIIZ preset label
    stepCount           DD ?
    _pad0               DD ?
    steps               PRESET_SLOT COT_MAX_STEPS DUP(<>)
PRESET_ENTRY ENDS

; =============================================================================
;                        GLOBAL STATE (.data)
; =============================================================================
.data

ALIGN 16

; --- Arena ---
g_arenaBase             DQ 0                        ; VirtualAlloc base (1 GB)
g_arenaUsed             DQ 0                        ; bytes used in arena
g_arenaCommitted        DQ 0                        ; bytes committed so far

; --- Chain state ---
g_maxSteps              DD COT_MAX_STEPS            ; max steps [1,8]
g_stepCount             DD 0                        ; currently configured steps
g_executionState        DD STATE_IDLE               ; atomic: idle/running/cancelled
g_initialized           DD 0                        ; init flag

; --- Statistics ---
ALIGN 16
g_stats                 COT_STATS <>

; --- Configured steps (up to 8) ---
ALIGN 16
g_steps                 COT_STEP_DESC COT_MAX_STEPS DUP(<>)

; --- Step results (written during executeChain) ---
ALIGN 16
g_stepResults           COT_STEP_RESULT COT_MAX_STEPS DUP(<>)

; --- Default model name ---
g_defaultModel          DB COT_MAX_MODEL_NAME DUP(0)

