szJsonStatusFmt3    DB ',"running":', 0
szJsonStatusFmt4    DB ',"maxSteps":', 0
szJsonStatusFmt5    DB ',"stepCount":', 0
szJsonStatusFmt6    DB ',"arenaUsedBytes":', 0
szJsonStatusFmt7    DB ',"arenaCommittedBytes":', 0
szJsonStatusFmt8    DB ',"stats":{"totalChains":', 0
szJsonStatusFmt9    DB ',"successfulChains":', 0
szJsonStatusFmt10   DB ',"failedChains":', 0
szJsonStatusFmt11   DB ',"totalStepsExecuted":', 0
szJsonStatusFmt12   DB ',"totalStepsSkipped":', 0
szJsonStatusFmt13   DB ',"totalStepsFailed":', 0
szJsonStatusFmt14   DB ',"avgLatencyMs":', 0
szJsonClose         DB '}}', 0
szTrue              DB 'true', 0
szFalse             DB 'false', 0

; Debug strings
szDbg_InitStart     DB "[CoT-ASM] Initialize_Core: reserving 1GB VA...", 0
szDbg_InitOK        DB "[CoT-ASM] Initialize_Core: arena ready, 1MB committed.", 0
szDbg_InitFail      DB "[CoT-ASM] Initialize_Core: VirtualAlloc FAILED!", 0
szDbg_Shutdown      DB "[CoT-ASM] Shutdown_Core: releasing arena.", 0
szDbg_AppendFault   DB "[CoT-ASM] Append_Data: SEH fault during copy!", 0

; =============================================================================
;                            CODE SECTION
; =============================================================================
.code

; =============================================================================
; Internal: asm_strlen — compute length of ASCIIZ string
;   RCX = pointer to string
;   Returns: RAX = length (not including NUL)
; =============================================================================
asm_strlen PROC
    test    rcx, rcx
    jz      @@sl_zero
    xor     rax, rax
@@sl_loop:
    cmp     BYTE PTR [rcx + rax], 0
    je      @@sl_done
    inc     rax
    jmp     @@sl_loop
@@sl_done:
    ret
@@sl_zero:
    xor     rax, rax
    ret
asm_strlen ENDP

; =============================================================================
; Internal: asm_strcpy — copy ASCIIZ string (NUL-terminated)
;   RCX = dest
;   RDX = src
;   Returns: RAX = bytes copied (including NUL)
; =============================================================================
asm_strcpy PROC
    test    rcx, rcx
    jz      @@sc_zero
    test    rdx, rdx
    jz      @@sc_zero
    xor     rax, rax
@@sc_loop:
    mov     r8b, BYTE PTR [rdx + rax]
    mov     BYTE PTR [rcx + rax], r8b
    inc     rax
    test    r8b, r8b
    jnz     @@sc_loop
    ret                                     ; RAX = count including NUL
@@sc_zero:
    xor     rax, rax
    ret
asm_strcpy ENDP

; =============================================================================
; Internal: asm_strcmp — compare two ASCIIZ strings
;   RCX = str1
;   RDX = str2
;   Returns: EAX = 0 if equal, non-zero otherwise
; =============================================================================
asm_strcmp PROC
    test    rcx, rcx
    jz      @@cmp_neq
    test    rdx, rdx
    jz      @@cmp_neq
    xor     r8, r8
@@cmp_loop:
    movzx   eax, BYTE PTR [rcx + r8]
    movzx   r9d, BYTE PTR [rdx + r8]
    cmp     eax, r9d
    jne     @@cmp_neq
    test    eax, eax                        ; both NUL?
    jz      @@cmp_eq
    inc     r8
    jmp     @@cmp_loop
@@cmp_eq:
    xor     eax, eax                        ; return 0 = equal
    ret
@@cmp_neq:
    mov     eax, 1                          ; return 1 = not equal
    ret
asm_strcmp ENDP

; =============================================================================
; Internal: asm_itoa — convert unsigned 64-bit integer to decimal ASCII
;   RCX = value
;   RDX = output buffer (must hold >= 21 chars)
;   Returns: RAX = length of string written
; =============================================================================
asm_itoa PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    sub     rsp, 32                         ; temp buffer
    .allocstack 32
    .endprolog

    mov     rdi, rdx                        ; rdi = output
    mov     rax, rcx                        ; rax = value
    xor     esi, esi                        ; esi = digit count

    ; Special case: 0
    test    rax, rax
    jnz     @@itoa_loop
    mov     BYTE PTR [rdi], '0'
    mov     BYTE PTR [rdi + 1], 0
    mov     eax, 1
    jmp     @@itoa_done

@@itoa_loop:
    ; Divide RAX by 10
    xor     edx, edx
    mov     rbx, 10
    div     rbx                             ; RAX = quotient, RDX = remainder
    add     dl, '0'
    mov     BYTE PTR [rsp + rsi], dl        ; store digit (reversed)
    inc     esi
    test    rax, rax
    jnz     @@itoa_loop

    ; Reverse digits into output buffer
    xor     ecx, ecx                        ; output index
    mov     eax, esi
    dec     eax                             ; eax = last digit index
@@itoa_reverse:
    movzx   r8d, BYTE PTR [rsp + rax]
    mov     BYTE PTR [rdi + rcx], r8b
    inc     ecx
    dec     eax
    jns     @@itoa_reverse

    mov     BYTE PTR [rdi + rcx], 0         ; NUL terminate
    mov     eax, esi                        ; return length

@@itoa_done:
    add     rsp, 32
    pop     rdi
    pop     rsi
    pop     rbx
    ret
asm_itoa ENDP

; =============================================================================
; Internal: asm_append_str — append ASCIIZ string to buffer
;   RCX = dest buffer current write position
;   RDX = source string (ASCIIZ)
;   Returns: RAX = new write position (past last char, NOT past NUL)
; =============================================================================
asm_append_str PROC
    test    rcx, rcx
    jz      @@as_done
    test    rdx, rdx
    jz      @@as_done
@@as_loop:
    movzx   r8d, BYTE PTR [rdx]
    test    r8d, r8d
    jz      @@as_done
    mov     BYTE PTR [rcx], r8b
    inc     rcx
    inc     rdx
    jmp     @@as_loop
@@as_done:
    mov     rax, rcx
    ret
asm_append_str ENDP

; =============================================================================
; Internal: asm_append_int — append decimal integer to buffer
;   RCX = dest buffer current write position
;   RDX = integer value (unsigned 64-bit)
;   Returns: RAX = new write position
; =============================================================================
asm_append_int PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 48                         ; itoa temp + shadow
    .allocstack 48
    .endprolog

    mov     rbx, rcx                        ; save dest position
    ; asm_itoa(value, temp_buffer)
    mov     rcx, rdx                        ; value
    lea     rdx, [rsp + 24]                 ; temp buffer on stack
    call    asm_itoa
    ; rax = length, digits at [rsp+24]
    ; asm_append_str(dest, temp_buffer)
    mov     rcx, rbx
    lea     rdx, [rsp + 24]
    call    asm_append_str
    ; rax = new position

    add     rsp, 48
    pop     rbx
    ret
asm_append_int ENDP

; =============================================================================
; Internal: ensure_arena_committed — commit more pages if needed
;   RCX = required total bytes (g_arenaUsed + new data)
;   Returns: EAX = 0 on success, -1 if commit fails
; =============================================================================
ensure_arena_committed PROC FRAME
    push    rbx
    .pushreg rbx
    push    r12
    .pushreg r12
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     r12, rcx                        ; required bytes

    mov     rbx, QWORD PTR [g_arenaCommitted]
    cmp     r12, rbx
    jbe     @@eac_ok                        ; already committed enough

    ; Calculate how much more to commit (round up to granule)
    mov     rax, r12
    sub     rax, rbx                        ; additional needed
    add     rax, COT_ARENA_COMMIT_GRANULE - 1
    and     rax, NOT (COT_ARENA_COMMIT_GRANULE - 1)  ; round up

    ; VirtualAlloc(base + committed, roundedSize, MEM_COMMIT, PAGE_READWRITE)
    mov     rcx, QWORD PTR [g_arenaBase]
    add     rcx, rbx                        ; start of new commit region
    mov     rdx, rax                        ; size
    mov     r8d, MEM_COMMIT
    mov     r9d, PAGE_READWRITE
    call    VirtualAlloc
    test    rax, rax
    jz      @@eac_fail

    ; Update committed size
    mov     rax, r12
    add     rax, COT_ARENA_COMMIT_GRANULE - 1
    and     rax, NOT (COT_ARENA_COMMIT_GRANULE - 1)
    add     QWORD PTR [g_arenaCommitted], rax

@@eac_ok:
    xor     eax, eax                        ; success
    jmp     @@eac_done

@@eac_fail:
    mov     eax, -1

@@eac_done:
    add     rsp, 40
    pop     r12
    pop     rbx
    ret
ensure_arena_committed ENDP

; =============================================================================
; SEH exception handler for arena memory operations
; This catches access violations during rep movsb over the arena
; =============================================================================
CoT_SEH_Handler PROC FRAME
    push    rbx
    .pushreg rbx
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    sub     rsp, 48
    .allocstack 48
    .endprolog

    ; EXCEPTION_DISPOSITION handler(
    ;   EXCEPTION_RECORD* ExceptionRecord,   RCX
    ;   void* EstablisherFrame,               RDX
    ;   CONTEXT* ContextRecord,               R8
    ;   void* DispatcherContext                R9
    ; )
    mov     rbx, rcx                        ; save ExceptionRecord
    mov     r12, r8                         ; save ContextRecord

    ; Check if this is an access violation (0xC0000005)
    mov     eax, DWORD PTR [rbx]            ; ExceptionRecord->ExceptionCode
    cmp     eax, 0C0000005h
    jne     @@seh_continue

    ; ---- Store fault info in per-thread TLS ----
    ; This captures the exact RIP where the AV occurred so C++ callers
    ; can retrieve it via CoT_TLS_GetFaultRIP() for diagnostics.
    mov     ecx, DWORD PTR [rbx]            ; error code (0xC0000005)
    mov     rdx, QWORD PTR [r12 + 0F8h]     ; CONTEXT.Rip (fault RIP)
    ; ExceptionRecord->ExceptionInformation[1] = fault address (for AV)
    mov     r8, QWORD PTR [rbx + 28h]       ; ExceptionInformation[1]
    call    CoT_TLS_SetError

    ; ---- Redirect execution to safe resume point ----
    ; Update RIP in ContextRecord to point to our safe resume.
    ; Also fix RSP to account for the stack frame (sub rsp, N) if the
    ; fault occurred post-allocation in CoT_Append_Data.
    lea     rax, [@@seh_resume_target]
    mov     QWORD PTR [r12 + 0F8h], rax     ; CONTEXT.Rip = resume point

    ; Clear RAX in context (signal error to caller)
    mov     QWORD PTR [r12 + 78h], 0        ; CONTEXT.Rax = 0

    mov     eax, 0                          ; ExceptionContinueExecution
    jmp     @@seh_ret

@@seh_continue:
    mov     eax, 1                          ; ExceptionContinueSearch

@@seh_ret:
    add     rsp, 48
    pop     r13
    pop     r12
    pop     rbx
    ret

@@seh_resume_target:
    ; This is never called directly — it's a target IP for the context fixup.
    ; Execution resumes here after SEH handler redirects CONTEXT.Rip.
    ret
CoT_SEH_Handler ENDP

; =============================================================================
; CoT_Initialize_Core
; Reserve 1GB virtual address space. Commit initial 1MB.
; Initialize all data structures to zero state.
;
; Returns: RAX = 0 on success, STATUS_UNSUCCESSFUL on failure
;          RDX = detail string pointer
; =============================================================================
CoT_Initialize_Core PROC FRAME
    push    rbx
    .pushreg rbx
    push    r12
    .pushreg r12
    sub     rsp, 56
    .allocstack 56
    .endprolog

    ; Debug output
    lea     rcx, szDbg_InitStart
    call    OutputDebugStringA

    ; Check if already initialized
    cmp     DWORD PTR [g_initialized], 1
    je      @@init_already

    ; Acquire lock
    call    Acquire_CoT_Lock

    ; Double-check after lock
    cmp     DWORD PTR [g_initialized], 1
    je      @@init_unlock_ok

    ; ---- Attempt Large Pages + NUMA-aware allocation ----
    ; If SeLockMemoryPrivilege is available (checked in DllMain),
    ; try MEM_LARGE_PAGES for reduced TLB pressure on 100M token scans.
    ; MEM_LARGE_PAGES requires MEM_RESERVE|MEM_COMMIT together and
    ; the size must be a multiple of GetLargePageMinimum().
    call    CoT_Has_Large_Pages
    test    eax, eax
    jz      @@init_normal_alloc

    ; Get large page minimum size
    call    GetLargePageMinimum
    test    rax, rax
    jz      @@init_normal_alloc

    ; Round up 1GB to large page boundary (typically 2MB)
    mov     rbx, rax                        ; rbx = large page size
    mov     rdx, COT_ARENA_RESERVE_SIZE
    add     rdx, rbx
    dec     rdx
    neg     rbx
    and     rdx, rbx                        ; rounded up size
    neg     rbx                             ; restore rbx = page size

    ; VirtualAllocExNuma(GetCurrentProcess(), NULL, roundedSize,
    ;                    MEM_RESERVE|MEM_COMMIT|MEM_LARGE_PAGES,
    ;                    PAGE_READWRITE, PREFERRED_NUMA_NODE_ANY)
    ; NUMA node 0xFFFFFFFF = let OS pick optimal node for calling thread.
    ; On multi-socket EPYC/Xeon this binds to the local socket.
    call    GetCurrentProcess
    mov     rcx, rax                        ; hProcess
    xor     edx, edx                        ; lpAddress = NULL (let OS pick)
    ; rdx was just zeroed, but we need the rounded size
    mov     rdx, COT_ARENA_RESERVE_SIZE
    add     rdx, rbx
    dec     rdx
    mov     rax, rbx
    neg     rax
    and     rdx, rax                        ; rounded size (recalculate)
    mov     r8d, MEM_RESERVE OR MEM_COMMIT OR MEM_LARGE_PAGES
    mov     r9d, PAGE_READWRITE
    mov     DWORD PTR [rsp + 32], PREFERRED_NUMA_NODE_ANY  ; 6th arg
    call    VirtualAllocExNuma
    test    rax, rax
    jz      @@init_normal_alloc             ; fallback if large pages fail

    ; Large page success — entire 1GB is committed (large pages are non-pageable)
    mov     QWORD PTR [g_arenaBase], rax
    mov     r12, rax
    mov     QWORD PTR [g_arenaCommitted], COT_ARENA_RESERVE_SIZE
    jmp     @@init_arena_ready

@@init_normal_alloc:
    ; ---- Standard allocation: Reserve 1 GB VA space ----
    xor     ecx, ecx                        ; lpAddress = NULL
    mov     rdx, COT_ARENA_RESERVE_SIZE     ; 1 GB
    mov     r8d, MEM_RESERVE
    mov     r9d, PAGE_READWRITE
    call    VirtualAlloc
    test    rax, rax
    jz      @@init_unlock_fail

    mov     QWORD PTR [g_arenaBase], rax
    mov     r12, rax                        ; save base

    ; Commit initial 1 MB
    mov     rcx, rax                        ; base
    mov     rdx, COT_ARENA_INITIAL_COMMIT   ; 1 MB
    mov     r8d, MEM_COMMIT
    mov     r9d, PAGE_READWRITE
    call    VirtualAlloc
    test    rax, rax
    jz      @@init_unlock_free

    mov     QWORD PTR [g_arenaCommitted], COT_ARENA_INITIAL_COMMIT

@@init_arena_ready:
    ; NOTE: g_arenaCommitted is already set by the allocation path
    ; (large page path sets it to COT_ARENA_RESERVE_SIZE,
    ;  normal path sets it to COT_ARENA_INITIAL_COMMIT)
    mov     QWORD PTR [g_arenaUsed], 0

    ; Zero state
    mov     DWORD PTR [g_maxSteps], COT_MAX_STEPS
    mov     DWORD PTR [g_stepCount], 0
    mov     DWORD PTR [g_executionState], STATE_IDLE

    ; Zero statistics
    lea     rcx, g_stats
    xor     edx, edx
    mov     r8d, SIZEOF COT_STATS
    call    RtlZeroMemory

    ; Zero step descriptors
    lea     rcx, g_steps
    xor     edx, edx
    mov     r8d, SIZEOF COT_STEP_DESC * COT_MAX_STEPS
    call    RtlZeroMemory

    ; Zero step results
    lea     rcx, g_stepResults
    xor     edx, edx
    mov     r8d, SIZEOF COT_STEP_RESULT * COT_MAX_STEPS
    call    RtlZeroMemory

    ; Zero default model
    lea     rcx, g_defaultModel
    xor     edx, edx
    mov     r8d, COT_MAX_MODEL_NAME
    call    RtlZeroMemory

    ; --- Phase 39: Write canary magic at arena head ---
    ; The first 8 bytes of the arena hold the canary sentinel.
    ; CoT_Append_Data starts writing after the canary (offset 8).
    mov     rax, QWORD PTR [g_arenaBase]
    mov     rcx, CANARY_HEAD_MAGIC
    mov     QWORD PTR [rax], rcx
    mov     DWORD PTR [g_canaryHeadOK], 1

    ; --- Phase 39: Initialize commit governor timestamp ---
    call    GetTickCount64
    mov     QWORD PTR [g_commitGovernor], 0          ; CommitRateEMA = 0
    mov     QWORD PTR [g_commitGovernor + 8], rax     ; LastCommitTS = now

    ; --- Phase 39: Record init timestamp in telemetry ---
    ; CoT_Telemetry.InitTimestamp offset = 232 (29th QWORD)
    mov     QWORD PTR [g_telemetry + 232], rax

    ; --- Phase 39: Probe CPUID and select optimal copy engine ---
    call    CoT_SelectCopyEngine

    ; --- Phase 39: Initial telemetry refresh ---
    call    CoT_UpdateTelemetry

    ; Mark initialized
    mov     DWORD PTR [g_initialized], 1

    ; Debug output
    lea     rcx, szDbg_InitOK
    call    OutputDebugStringA

@@init_unlock_ok:
    call    Release_CoT_Lock

@@init_already:
    xor     eax, eax                        ; STATUS_SUCCESS
    lea     rdx, szDbg_InitOK
    jmp     @@init_ret

@@init_unlock_free:
    ; Commit failed — release the reservation
    mov     rcx, r12
    xor     edx, edx
    mov     r8d, MEM_RELEASE
    call    VirtualFree
    mov     QWORD PTR [g_arenaBase], 0

@@init_unlock_fail:
    call    Release_CoT_Lock
    lea     rcx, szDbg_InitFail
    call    OutputDebugStringA
    mov     eax, STATUS_UNSUCCESSFUL
    lea     rdx, szDbg_InitFail

@@init_ret:
    add     rsp, 56
    pop     r12
    pop     rbx
    ret
CoT_Initialize_Core ENDP

; =============================================================================
; CoT_Shutdown_Core
; Release all virtual memory and reset state.
;
; Returns: RAX = 0 on success
; =============================================================================
CoT_Shutdown_Core PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    lea     rcx, szDbg_Shutdown
    call    OutputDebugStringA

    call    Acquire_CoT_Lock

    ; Release arena
    mov     rcx, QWORD PTR [g_arenaBase]
    test    rcx, rcx
    jz      @@sd_no_arena
    xor     edx, edx
    mov     r8d, MEM_RELEASE
    call    VirtualFree

@@sd_no_arena:
    mov     QWORD PTR [g_arenaBase], 0
    mov     QWORD PTR [g_arenaUsed], 0
    mov     QWORD PTR [g_arenaCommitted], 0

    ; Reset state
    mov     DWORD PTR [g_maxSteps], COT_MAX_STEPS
    mov     DWORD PTR [g_stepCount], 0
    mov     DWORD PTR [g_executionState], STATE_IDLE
    mov     DWORD PTR [g_initialized], 0

    ; Zero stats
    lea     rcx, g_stats
    xor     edx, edx
    mov     r8d, SIZEOF COT_STATS
    call    RtlZeroMemory

    call    Release_CoT_Lock

    xor     eax, eax                        ; STATUS_SUCCESS
    add     rsp, 40
    pop     rbx
    ret
CoT_Shutdown_Core ENDP

; =============================================================================
; CoT_Set_Max_Steps
; Clamp value to [1, 8].
;
; RCX = new max steps (int)
; Returns: RAX = clamped value
; =============================================================================
CoT_Set_Max_Steps PROC
    mov     eax, ecx
    cmp     eax, 1
    jge     @@sms_check_high
    mov     eax, 1
@@sms_check_high:
    cmp     eax, COT_MAX_STEPS
    jle     @@sms_store
    mov     eax, COT_MAX_STEPS
@@sms_store:
    mov     DWORD PTR [g_maxSteps], eax
    ret
CoT_Set_Max_Steps ENDP

; =============================================================================
; CoT_Get_Max_Steps
; Returns: EAX = current max steps
; =============================================================================
CoT_Get_Max_Steps PROC
    mov     eax, DWORD PTR [g_maxSteps]
    ret
CoT_Get_Max_Steps ENDP

; =============================================================================
; CoT_Clear_Steps
; Remove all configured steps. Thread-safe.
; =============================================================================
CoT_Clear_Steps PROC FRAME
    sub     rsp, 40
    .allocstack 40
    .endprolog

    call    Acquire_CoT_Lock
    mov     DWORD PTR [g_stepCount], 0
    lea     rcx, g_steps
    xor     edx, edx
    mov     r8d, SIZEOF COT_STEP_DESC * COT_MAX_STEPS
    call    RtlZeroMemory
    call    Release_CoT_Lock

    add     rsp, 40
    ret
CoT_Clear_Steps ENDP

; =============================================================================
; CoT_Add_Step
; Add a step to the chain.
;
; RCX = role ID (0-11)
; RDX = model name (ASCIIZ, may be NULL for default)
; R8  = instruction override (ASCIIZ, may be NULL for role default)
; R9  = skip flag (0 = don't skip, 1 = skip)
;
; Returns: EAX = 0 on success, -1 if full
; =============================================================================
CoT_Add_Step PROC FRAME
    push    rbx
    .pushreg rbx
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 48
    .allocstack 48
    .endprolog

    ; Save args
    mov     r12d, ecx                       ; roleId
    mov     r13, rdx                        ; model name ptr
    mov     r14, r8                         ; instruction ptr
    mov     r15d, r9d                       ; skip flag

    call    Acquire_CoT_Lock

    ; Check capacity
    mov     eax, DWORD PTR [g_stepCount]
    cmp     eax, DWORD PTR [g_maxSteps]
    jge     @@as_full

    ; Calculate step descriptor address: g_steps + stepCount * sizeof(COT_STEP_DESC)
    mov     ecx, eax                        ; stepCount
    imul    rcx, SIZEOF COT_STEP_DESC
    lea     rbx, g_steps
    add     rbx, rcx                        ; rbx = target step descriptor

    ; Set roleId
    mov     DWORD PTR [rbx + COT_STEP_DESC.roleId], r12d

    ; Set skip flag
    mov     DWORD PTR [rbx + COT_STEP_DESC.skip], r15d

    ; Copy model name (if provided)
    lea     rcx, [rbx + COT_STEP_DESC.modelName]
    test    r13, r13
    jz      @@as_no_model
    mov     rdx, r13
    call    asm_strcpy
    jmp     @@as_model_done
@@as_no_model:
    mov     BYTE PTR [rbx + COT_STEP_DESC.modelName], 0
@@as_model_done:

    ; Copy instruction override (if provided)
    lea     rcx, [rbx + COT_STEP_DESC.instructionOverride]
    test    r14, r14
    jz      @@as_no_instr
    mov     rdx, r14
    call    asm_strcpy
    jmp     @@as_instr_done
@@as_no_instr:
    mov     BYTE PTR [rbx + COT_STEP_DESC.instructionOverride], 0
@@as_instr_done:

    ; Increment step count
    inc     DWORD PTR [g_stepCount]

    call    Release_CoT_Lock
    xor     eax, eax                        ; success
    jmp     @@as_done

@@as_full:
    call    Release_CoT_Lock
    mov     eax, -1                         ; chain is full

@@as_done:
    add     rsp, 48
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rbx
    ret
CoT_Add_Step ENDP

; =============================================================================
; CoT_Apply_Preset
; Load a named preset configuration, replacing current steps.
;
; RCX = preset name (ASCIIZ, e.g. "review", "audit", "think", etc.)
;
; Returns: EAX = 0 on success, -1 if preset not found
; =============================================================================
CoT_Apply_Preset PROC FRAME
    push    rbx
    .pushreg rbx
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    rsi
    .pushreg rsi
    sub     rsp, 56
    .allocstack 56
    .endprolog

    mov     r12, rcx                        ; save preset name ptr

    ; Search preset table
    lea     rbx, g_presetTable
    xor     r13d, r13d                      ; preset index = 0

@@ap_search:
    cmp     r13d, PRESET_COUNT
    jge     @@ap_not_found

    ; Compare name: g_presetTable[idx].namePtr
    mov     rcx, r12
    mov     rdx, QWORD PTR [rbx]            ; namePtr
    call    asm_strcmp
    test    eax, eax
    jz      @@ap_found

    add     rbx, PRESET_ENTRY_SIZE
    inc     r13d
    jmp     @@ap_search

@@ap_found:
    ; Clear current steps first
    call    CoT_Clear_Steps

    call    Acquire_CoT_Lock

    ; Read step count from preset entry
    mov     ecx, DWORD PTR [rbx + 16]       ; stepCount at offset 16
    mov     DWORD PTR [g_stepCount], ecx
    mov     esi, ecx                        ; save count

    ; Copy preset steps into g_steps
    lea     r12, g_steps
    lea     r13, [rbx + 24]                 ; first PRESET_SLOT at offset 24

    xor     ecx, ecx                        ; step index
@@ap_copy_loop:
    cmp     ecx, esi
    jge     @@ap_copy_done

    ; Calculate step descriptor offset
    mov     eax, ecx
    imul    rax, SIZEOF COT_STEP_DESC
    lea     rdx, [r12 + rax]               ; target step descriptor

    ; Read role ID from preset slot (8 bytes per slot: roleId DD, skip DD)
    mov     eax, ecx
    shl     eax, 3                          ; * 8
    mov     r8d, DWORD PTR [r13 + rax]      ; roleId
    mov     DWORD PTR [rdx + COT_STEP_DESC.roleId], r8d

    ; Read skip flag
    mov     r8d, DWORD PTR [r13 + rax + 4]  ; skip
    mov     DWORD PTR [rdx + COT_STEP_DESC.skip], r8d

    ; Model and instruction remain empty (use defaults)
    mov     BYTE PTR [rdx + COT_STEP_DESC.modelName], 0
    mov     BYTE PTR [rdx + COT_STEP_DESC.instructionOverride], 0

    inc     ecx
    jmp     @@ap_copy_loop

@@ap_copy_done:
    call    Release_CoT_Lock
    xor     eax, eax                        ; success
    jmp     @@ap_ret

@@ap_not_found:
    mov     eax, -1                         ; preset not found

@@ap_ret:
    add     rsp, 56
    pop     rsi
    pop     r13
    pop     r12
    pop     rbx
    ret
CoT_Apply_Preset ENDP

; =============================================================================
; CoT_Get_Step_Count
; Returns: EAX = number of configured steps
; =============================================================================
CoT_Get_Step_Count PROC
    mov     eax, DWORD PTR [g_stepCount]
    ret
CoT_Get_Step_Count ENDP

; =============================================================================
; CoT_Execute_Chain
; Execute the configured chain synchronously.
; NOTE: In the pure MASM DLL, this performs the step orchestration loop,
; calling an externally-provided inference callback for each step.
; The callback must be registered via CoT_Set_Inference_Callback first.
;
; RCX = user query (ASCIIZ)
; RDX = inference callback function pointer:
;       int64_t (*callback)(const char* systemPrompt, const char* userMsg,
;                           const char* model, char* outputBuf, int64_t outBufSize)
;       Returns: bytes written to outputBuf, or -1 on error
;
; Returns: RAX = steps completed (0 if error)
;          RDX = pointer to g_stepResults array
; =============================================================================
CoT_Execute_Chain PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 128
    .allocstack 128
    .endprolog

    ; Save arguments
    mov     r12, rcx                        ; r12 = userQuery
    mov     r13, rdx                        ; r13 = inference callback

    ; Validate
    test    r12, r12
    jz      @@ec_error
    test    r13, r13
    jz      @@ec_error

    ; Check not already running (atomic CAS)
    lea     rbx, g_executionState
    mov     eax, STATE_IDLE
    ; CMPXCHG: if [rbx] == EAX, then [rbx] = STATE_RUNNING and ZF=1
    mov     ecx, STATE_RUNNING
    lock cmpxchg DWORD PTR [rbx], ecx
    jnz     @@ec_error                      ; already running

    ; Record chain start time
    call    GetTickCount64
    mov     QWORD PTR [rsp + 96], rax       ; [rsp+96] = chainStartTime

    ; Zero step results
    lea     rcx, g_stepResults
    xor     edx, edx
    mov     r8d, SIZEOF COT_STEP_RESULT * COT_MAX_STEPS
    call    RtlZeroMemory

    ; Initialize counters
    xor     r14d, r14d                      ; r14 = stepsCompleted
    xor     r15d, r15d                      ; r15 = current step index
    mov     DWORD PTR [rsp + 104], 0        ; stepsSkipped
    mov     DWORD PTR [rsp + 108], 0        ; stepsFailed

    mov     esi, DWORD PTR [g_stepCount]    ; esi = total steps

@@ec_step_loop:
    cmp     r15d, esi
    jge     @@ec_chain_done

    ; Check cancellation
    cmp     DWORD PTR [g_executionState], STATE_CANCELLED
    je      @@ec_chain_done

    ; Get step descriptor address
    mov     eax, r15d
    imul    rax, SIZEOF COT_STEP_DESC
    lea     rbx, g_steps
    add     rbx, rax                        ; rbx = current step descriptor

    ; Get step result address
    mov     eax, r15d
    imul    rax, SIZEOF COT_STEP_RESULT
    lea     rdi, g_stepResults
    add     rdi, rax                        ; rdi = current step result

    ; Fill step result metadata
    mov     DWORD PTR [rdi + COT_STEP_RESULT.stepIndex], r15d
    mov     eax, DWORD PTR [rbx + COT_STEP_DESC.roleId]
    mov     DWORD PTR [rdi + COT_STEP_RESULT.roleId], eax

    ; Check skip flag
    cmp     DWORD PTR [rbx + COT_STEP_DESC.skip], 0
    je      @@ec_not_skipped

    ; Skipped step
    mov     DWORD PTR [rdi + COT_STEP_RESULT.skipped], 1
    mov     DWORD PTR [rdi + COT_STEP_RESULT.success], 1
    inc     DWORD PTR [rsp + 104]           ; stepsSkipped++
    jmp     @@ec_next_step

@@ec_not_skipped:
    ; Determine system prompt: use instruction override if set, else role default
    lea     rcx, [rbx + COT_STEP_DESC.instructionOverride]
    cmp     BYTE PTR [rcx], 0
    jne     @@ec_have_sysprompt

    ; Use role default instruction
    mov     eax, DWORD PTR [rbx + COT_STEP_DESC.roleId]
    cmp     eax, ROLE_COUNT
    jge     @@ec_step_fail
    imul    rax, ROLE_ENTRY_SIZE
    lea     rcx, g_roleTable
    add     rcx, rax
    mov     rcx, QWORD PTR [rcx + 32]      ; instructionPtr (offset 8+8+8+8=32)
@@ec_have_sysprompt:
    mov     QWORD PTR [rsp + 112], rcx      ; save systemPrompt ptr

    ; Determine model: use step override if set, else g_defaultModel
    lea     rcx, [rbx + COT_STEP_DESC.modelName]
    cmp     BYTE PTR [rcx], 0
    jne     @@ec_have_model
    lea     rcx, g_defaultModel
@@ec_have_model:
    ; Copy model name to result
    push    rcx                             ; save model ptr
    lea     rcx, [rdi + COT_STEP_RESULT.modelUsed]
    pop     rdx                             ; model ptr -> rdx
    push    rdx                             ; re-save for callback
    call    asm_strcpy
    pop     rdx                             ; rdx = model ptr

    ; Record step start time
    push    rdx
    call    GetTickCount64
    mov     QWORD PTR [rsp + 128], rax      ; stepStartTime (adjusted for push)
    pop     rdx

    ; Call inference callback:
    ;   callback(systemPrompt, userQuery, model, outputBuf, outBufSize)
    ; Allocate output buffer from arena or stack
    ; For safety, allocate a 1MB region via VirtualAlloc for step output
    push    rdx                             ; save model ptr
    xor     ecx, ecx
    mov     rdx, COT_MAX_STEP_OUTPUT_SIZE
    mov     r8d, MEM_COMMIT OR MEM_RESERVE
    mov     r9d, PAGE_READWRITE
    call    VirtualAlloc
    pop     rdx                             ; restore model ptr
    test    rax, rax
    jz      @@ec_step_fail

    mov     QWORD PTR [rdi + COT_STEP_RESULT.outputPtr], rax

    ; Set up callback arguments (Windows x64 ABI: RCX, RDX, R8, R9, [rsp+32])
    ; arg1 (RCX) = systemPrompt
    ; arg2 (RDX) = userQuery
    ; arg3 (R8)  = model
    ; arg4 (R9)  = outputBuf
    ; arg5 ([rsp+32]) = outBufSize
    mov     r9, rax                         ; outputBuf
    mov     r8, rdx                         ; model
    mov     rdx, r12                        ; userQuery
    mov     rcx, QWORD PTR [rsp + 112]      ; systemPrompt
    mov     QWORD PTR [rsp + 32], COT_MAX_STEP_OUTPUT_SIZE  ; outBufSize
    call    r13                             ; call inference callback

    ; RAX = bytes written or -1 on error
    cmp     rax, 0
    jle     @@ec_step_fail_output

    ; Success
    mov     DWORD PTR [rdi + COT_STEP_RESULT.outputLen], eax
    mov     DWORD PTR [rdi + COT_STEP_RESULT.success], 1
    ; Approximate token count (output_len / 4)
    shr     eax, 2
    mov     DWORD PTR [rdi + COT_STEP_RESULT.tokenCount], eax
    inc     r14d                            ; stepsCompleted++
    jmp     @@ec_step_timing

@@ec_step_fail_output:
    ; Free the output buffer on failure
    mov     rcx, QWORD PTR [rdi + COT_STEP_RESULT.outputPtr]
    test    rcx, rcx
    jz      @@ec_step_fail
    xor     edx, edx
    mov     r8d, MEM_RELEASE
    call    VirtualFree
    mov     QWORD PTR [rdi + COT_STEP_RESULT.outputPtr], 0

@@ec_step_fail:
    mov     DWORD PTR [rdi + COT_STEP_RESULT.success], 0
    mov     DWORD PTR [rdi + COT_STEP_RESULT.errorCode], 1
    inc     DWORD PTR [rsp + 108]           ; stepsFailed++

@@ec_step_timing:
    ; Calculate step latency
    call    GetTickCount64
    sub     rax, QWORD PTR [rsp + 128]      ; stepStartTime
    mov     DWORD PTR [rdi + COT_STEP_RESULT.latencyMs], eax

@@ec_next_step:
    inc     r15d
    jmp     @@ec_step_loop

@@ec_chain_done:
    ; Calculate total chain latency
    call    GetTickCount64
    sub     rax, QWORD PTR [rsp + 96]       ; chainStartTime

    ; Update statistics under lock
    call    Acquire_CoT_Lock

    inc     DWORD PTR [g_stats + COT_STATS.totalChains]
    test    r14d, r14d
    jz      @@ec_stat_fail
    inc     DWORD PTR [g_stats + COT_STATS.successfulChains]
    jmp     @@ec_stat_steps
@@ec_stat_fail:
    inc     DWORD PTR [g_stats + COT_STATS.failedChains]
@@ec_stat_steps:
    add     DWORD PTR [g_stats + COT_STATS.totalStepsExecuted], r14d
    mov     ecx, DWORD PTR [rsp + 104]
    add     DWORD PTR [g_stats + COT_STATS.totalStepsSkipped], ecx
    mov     ecx, DWORD PTR [rsp + 108]
    add     DWORD PTR [g_stats + COT_STATS.totalStepsFailed], ecx

    ; Update role usage for non-skipped steps
    xor     ecx, ecx
@@ec_role_usage_loop:
    cmp     ecx, esi
    jge     @@ec_role_usage_done
    mov     eax, ecx
    imul    rax, SIZEOF COT_STEP_RESULT
    lea     rdx, g_stepResults
    add     rdx, rax
    cmp     DWORD PTR [rdx + COT_STEP_RESULT.skipped], 0
    jne     @@ec_role_next
    mov     eax, DWORD PTR [rdx + COT_STEP_RESULT.roleId]
    cmp     eax, ROLE_COUNT
    jge     @@ec_role_next
    lea     r8, [g_stats + COT_STATS.roleUsage]
    inc     DWORD PTR [r8 + rax * 4]
@@ec_role_next:
    inc     ecx
    jmp     @@ec_role_usage_loop
@@ec_role_usage_done:

    ; Update average latency (running average)
    mov     eax, DWORD PTR [g_stats + COT_STATS.totalChains]
    cmp     eax, 1
    jle     @@ec_first_chain
    ; avg = ((avg * (total-1)) + chainLatency) / total
    dec     eax
    imul    eax, DWORD PTR [g_stats + COT_STATS.avgLatencyMs]
    mov     ecx, DWORD PTR [rsp + 96]       ; low 32 bits of chain latency
    add     eax, ecx
    mov     ecx, DWORD PTR [g_stats + COT_STATS.totalChains]
    xor     edx, edx
    div     ecx
    mov     DWORD PTR [g_stats + COT_STATS.avgLatencyMs], eax
    jmp     @@ec_avg_done
@@ec_first_chain:
    ; First chain: avg = latency
    call    GetTickCount64
    sub     rax, QWORD PTR [rsp + 96]
    mov     DWORD PTR [g_stats + COT_STATS.avgLatencyMs], eax
@@ec_avg_done:

    call    Release_CoT_Lock

    ; Reset state to idle
    mov     DWORD PTR [g_executionState], STATE_IDLE

    ; Return: RAX = steps completed, RDX = results ptr
    mov     eax, r14d
    lea     rdx, g_stepResults
    jmp     @@ec_ret

@@ec_error:
    xor     eax, eax
    xor     edx, edx

@@ec_ret:
    add     rsp, 128
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
CoT_Execute_Chain ENDP

; =============================================================================
; CoT_Cancel
; Set the cancellation flag. Running chain will stop after current step.
; =============================================================================
CoT_Cancel PROC
    mov     DWORD PTR [g_executionState], STATE_CANCELLED
    ret
CoT_Cancel ENDP

; =============================================================================
; CoT_Is_Running
; Returns: EAX = 1 if chain is executing, 0 otherwise
; =============================================================================
CoT_Is_Running PROC
    cmp     DWORD PTR [g_executionState], STATE_RUNNING
    sete    al
    movzx   eax, al
    ret
CoT_Is_Running ENDP

; =============================================================================
; CoT_Get_Stats
; Copy statistics block to caller-provided buffer.
;
; RCX = destination buffer (must be >= sizeof(COT_STATS))
;
; Returns: EAX = 0 on success, -1 if null
; =============================================================================
CoT_Get_Stats PROC FRAME
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    sub     rsp, 40
    .allocstack 40
    .endprolog

    test    rcx, rcx
    jz      @@gs_null

    call    Acquire_CoT_Lock

    ; memcpy(dest, &g_stats, sizeof(COT_STATS))
    mov     rdi, rcx
    lea     rsi, g_stats
    mov     ecx, SIZEOF COT_STATS
    rep     movsb

    call    Release_CoT_Lock

    xor     eax, eax
    jmp     @@gs_done

@@gs_null:
    mov     eax, -1

@@gs_done:
    add     rsp, 40
    pop     rdi
    pop     rsi
    ret
CoT_Get_Stats ENDP

; =============================================================================
; CoT_Reset_Stats
; Zero all statistics counters.
; =============================================================================
CoT_Reset_Stats PROC FRAME
    sub     rsp, 40
    .allocstack 40
    .endprolog

    call    Acquire_CoT_Lock

    lea     rcx, g_stats
    xor     edx, edx
    mov     r8d, SIZEOF COT_STATS
    call    RtlZeroMemory

    call    Release_CoT_Lock

    add     rsp, 40
    ret
CoT_Reset_Stats ENDP

; =============================================================================
; CoT_Get_Status_JSON
; Build a JSON status string into the caller-provided buffer.
;
; RCX = output buffer
; RDX = buffer size (bytes)
;
; Returns: RAX = bytes written (excluding NUL), 0 on error
; =============================================================================
CoT_Get_Status_JSON PROC FRAME
    push    rbx
    .pushreg rbx
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    sub     rsp, 72
    .allocstack 72
    .endprolog

    test    rcx, rcx
    jz      @@gj_error
    test    rdx, rdx
    jz      @@gj_error

    mov     r12, rcx                        ; r12 = buffer start
    mov     r13, rcx                        ; r13 = current write position
    mov     r14, rdx                        ; r14 = buffer size

    call    Acquire_CoT_Lock

    ; {"version":
    mov     rcx, r13
    lea     rdx, szJsonStatusFmt1
    call    asm_append_str
    mov     r13, rax
    ; version number
    mov     rcx, r13
    mov     rdx, COT_ENGINE_VERSION
    call    asm_append_int
    mov     r13, rax

    ; ,"initialized":
    mov     rcx, r13
    lea     rdx, szJsonStatusFmt2
    call    asm_append_str
    mov     r13, rax
    cmp     DWORD PTR [g_initialized], 0
    je      @@gj_init_false
    mov     rcx, r13
    lea     rdx, szTrue
    call    asm_append_str
    mov     r13, rax
    jmp     @@gj_init_done
@@gj_init_false:
    mov     rcx, r13
    lea     rdx, szFalse
    call    asm_append_str
    mov     r13, rax
@@gj_init_done:

    ; ,"running":
    mov     rcx, r13
    lea     rdx, szJsonStatusFmt3
    call    asm_append_str
    mov     r13, rax
    cmp     DWORD PTR [g_executionState], STATE_RUNNING
    jne     @@gj_run_false
    mov     rcx, r13
    lea     rdx, szTrue
    call    asm_append_str
    mov     r13, rax
    jmp     @@gj_run_done
@@gj_run_false:
    mov     rcx, r13
    lea     rdx, szFalse
    call    asm_append_str
    mov     r13, rax
@@gj_run_done:

    ; ,"maxSteps":
    mov     rcx, r13
    lea     rdx, szJsonStatusFmt4
    call    asm_append_str
    mov     r13, rax
    mov     rcx, r13
    mov     edx, DWORD PTR [g_maxSteps]
    call    asm_append_int
    mov     r13, rax

    ; ,"stepCount":
    mov     rcx, r13
    lea     rdx, szJsonStatusFmt5
    call    asm_append_str
    mov     r13, rax
    mov     rcx, r13
    mov     edx, DWORD PTR [g_stepCount]
    call    asm_append_int
    mov     r13, rax

    ; ,"arenaUsedBytes":
    mov     rcx, r13
    lea     rdx, szJsonStatusFmt6
    call    asm_append_str
    mov     r13, rax
    mov     rcx, r13
    mov     rdx, QWORD PTR [g_arenaUsed]
    call    asm_append_int
    mov     r13, rax

    ; ,"arenaCommittedBytes":
    mov     rcx, r13
    lea     rdx, szJsonStatusFmt7
    call    asm_append_str
    mov     r13, rax
    mov     rcx, r13
    mov     rdx, QWORD PTR [g_arenaCommitted]
    call    asm_append_int
    mov     r13, rax

    ; ,"stats":{"totalChains":
    mov     rcx, r13
    lea     rdx, szJsonStatusFmt8
    call    asm_append_str
    mov     r13, rax
    mov     rcx, r13
    mov     edx, DWORD PTR [g_stats + COT_STATS.totalChains]
    call    asm_append_int
    mov     r13, rax

    ; ,"successfulChains":
    mov     rcx, r13
    lea     rdx, szJsonStatusFmt9
    call    asm_append_str
    mov     r13, rax
    mov     rcx, r13
    mov     edx, DWORD PTR [g_stats + COT_STATS.successfulChains]
    call    asm_append_int
    mov     r13, rax

    ; ,"failedChains":
    mov     rcx, r13
    lea     rdx, szJsonStatusFmt10
    call    asm_append_str
    mov     r13, rax
    mov     rcx, r13
    mov     edx, DWORD PTR [g_stats + COT_STATS.failedChains]
    call    asm_append_int
    mov     r13, rax

    ; ,"totalStepsExecuted":
    mov     rcx, r13
    lea     rdx, szJsonStatusFmt11
    call    asm_append_str
    mov     r13, rax
    mov     rcx, r13
    mov     edx, DWORD PTR [g_stats + COT_STATS.totalStepsExecuted]
    call    asm_append_int
    mov     r13, rax

    ; ,"totalStepsSkipped":
    mov     rcx, r13
    lea     rdx, szJsonStatusFmt12
    call    asm_append_str
    mov     r13, rax
    mov     rcx, r13
    mov     edx, DWORD PTR [g_stats + COT_STATS.totalStepsSkipped]
    call    asm_append_int
    mov     r13, rax

    ; ,"totalStepsFailed":
    mov     rcx, r13
    lea     rdx, szJsonStatusFmt13
    call    asm_append_str
    mov     r13, rax
    mov     rcx, r13
    mov     edx, DWORD PTR [g_stats + COT_STATS.totalStepsFailed]
    call    asm_append_int
    mov     r13, rax

    ; ,"avgLatencyMs":
    mov     rcx, r13
    lea     rdx, szJsonStatusFmt14
    call    asm_append_str
    mov     r13, rax
    mov     rcx, r13
    mov     edx, DWORD PTR [g_stats + COT_STATS.avgLatencyMs]
    call    asm_append_int
    mov     r13, rax

    ; }}
    mov     rcx, r13
    lea     rdx, szJsonClose
    call    asm_append_str
    mov     r13, rax

    ; NUL-terminate
    mov     BYTE PTR [r13], 0

    call    Release_CoT_Lock

    ; Return bytes written
    mov     rax, r13
    sub     rax, r12
    jmp     @@gj_done

@@gj_error:
    xor     eax, eax

@@gj_done:
    add     rsp, 72
    pop     r14
    pop     r13
    pop     r12
    pop     rbx
    ret
CoT_Get_Status_JSON ENDP

; =============================================================================
; CoT_Get_Role_Info
; Get role info by role ID.
;
; RCX = role ID (0-11)
; RDX = dest buffer for COT_ROLE_ENTRY (caller allocates >= sizeof)
;
; Returns: EAX = 0 on success, -1 on invalid ID
; =============================================================================
CoT_Get_Role_Info PROC FRAME
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    .endprolog

    cmp     ecx, ROLE_COUNT
    jge     @@gri_invalid
    cmp     ecx, 0
    jl      @@gri_invalid
    test    rdx, rdx
    jz      @@gri_invalid

    ; Calculate offset into role table
    imul    rax, rcx, ROLE_ENTRY_SIZE
    lea     rsi, g_roleTable
    add     rsi, rax

    ; Copy entry to caller buffer
    mov     rdi, rdx
    mov     ecx, ROLE_ENTRY_SIZE
    rep     movsb

    xor     eax, eax
    jmp     @@gri_done

@@gri_invalid:
    mov     eax, -1

@@gri_done:
    pop     rdi
    pop     rsi
    ret
CoT_Get_Role_Info ENDP

; =============================================================================
; CoT_Append_Data
; Append raw token data to the 1GB arena. Commits pages as needed.
; Uses SEH wrapper for safety during memory copy operations.
;
; FIXES APPLIED (Phase 37.1):
;   1. Race condition: non-atomic g_arenaUsed update replaced with lock xadd
;      so parallel CoT debate threads get unique insertion offsets.
;   2. Register preservation: r12 is non-volatile per x64 ABI — now saved.
;   3. SEH safety: proper __try/__except around the copy with resume point
;      that accounts for the stack frame (sub rsp, 56).
;   4. Performance: fast path (movsq + movsb) for <256 byte token appends
;      to avoid ERMS microcode startup latency. prefetcht0 for large copies.
;
; RCX = source data pointer
; RDX = data size in bytes
;
; Returns: RAX = new total arena used (bytes), or 0 on failure
; =============================================================================
CoT_Append_Data PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    sub     rsp, 56
    .allocstack 56
    .endprolog

    ; Validate input parameters
    test    rcx, rcx
    jz      @@ad_fail
    test    rdx, rdx
    jz      @@ad_fail

    mov     r12, rcx                        ; r12 = source data ptr (non-vol, saved above)
    mov     r13, rdx                        ; r13 = data size in bytes

    ; Check arena initialized
    mov     rax, QWORD PTR [g_arenaBase]
    test    rax, rax
    jz      @@ad_fail

    ; --- Phase 39: Replay mode guard (append frozen in replay) ---
    cmp     DWORD PTR [g_replayMode], 1
    je      @@ad_fail

    ; --- Phase 39: Seal guard (append blocked when arena is read-only) ---
    cmp     DWORD PTR [g_arenaSealed], 1
    je      @@ad_fail

    ; --- Phase 39: GPU backpressure guard ---
    mov     rax, QWORD PTR [g_gpuQueueDepth]
    cmp     rax, QWORD PTR [g_backpressureThreshold]
    ja      @@ad_fail

    ; --- Phase 39: Commit governor soft/hard throttle check ---
    ; Read current throttle level from commit governor struct (+16 = ThrottleLevel)
    mov     eax, DWORD PTR [g_commitGovernor + 16]
    cmp     eax, 2                          ; THROTTLE_HARD
    je      @@ad_fail                       ; hard throttle: refuse append
    ; Soft throttle: allow but track (caller can check governor state)

    call    Acquire_CoT_Lock

    ; ---- ATOMIC RESERVATION via lock xadd ----
    ; In debate mode, multiple threads may call CoT_Append_Data concurrently.
    ; lock xadd atomically: old = g_arenaUsed; g_arenaUsed += r13; rax = old
    ; The old value in RAX is our unique insertion offset.
    mov     rax, r13
    lock xadd QWORD PTR [g_arenaUsed], rax
    ; RAX = old g_arenaUsed (our insertion point)
    ; g_arenaUsed is now old + r13

    ; Check capacity: insertion_point + size must not exceed 1GB reserve
    mov     rbx, rax                        ; rbx = insertion offset
    add     rax, r13                        ; rax = new total used
    cmp     rax, COT_ARENA_RESERVE_SIZE
    ja      @@ad_rollback

    ; Ensure enough pages are committed for the new extent
    mov     rcx, rax                        ; required total committed bytes
    call    ensure_arena_committed
    test    eax, eax
    jnz     @@ad_rollback

    ; ---- MEMORY COPY with fast-path and prefetch ----
    ; dest = arenaBase + insertion_offset
    mov     rdi, QWORD PTR [g_arenaBase]
    add     rdi, rbx                        ; dest = base + reserved offset
    mov     rsi, r12                        ; src = caller data

    ; Size check: if < 256 bytes, use movsq+movsb fast path
    ; to avoid ERMS microcode startup latency (~5 cycles on Zen4/Sapphire Rapids)
    cmp     r13, 256
    jb      @@ad_small_copy

    ; ---- LARGE COPY PATH (>= 256 bytes): prefetch + rep movsb (ERMS optimal) ----
    ; Prefetch first cacheline of source to hide DRAM latency
    prefetcht0 [rsi]
    ; Prefetch ahead by 1KB for large streaming copies
    prefetcht0 [rsi + 400h]

    mov     rcx, r13
    rep     movsb                           ; ERMS optimal for >= 256B on modern CPUs
    jmp     @@ad_copy_done

@@ad_small_copy:
    ; ---- SMALL COPY PATH (< 256 bytes): movsq + movsb remainder ----
    ; This avoids the ~35 cycle ERMS startup penalty for small token appends
    mov     rcx, r13
    shr     rcx, 3                          ; qword count = size / 8
    jz      @@ad_small_remainder
    rep     movsq                           ; copy 8 bytes at a time
@@ad_small_remainder:
    mov     rcx, r13
    and     rcx, 7                          ; remainder = size % 8
    jz      @@ad_copy_done
    rep     movsb                           ; copy remaining 0-7 bytes

@@ad_copy_done:
    ; --- Phase 39: Update commit governor EMA ---
    ; Simple EMA: rate = (old_rate * 7 + (bytes * 1000 / delta_ms)) / 8
    ; This is an approximation — we track bytes per call for now
    call    GetTickCount64
    mov     rcx, rax
    sub     rcx, QWORD PTR [g_commitGovernor + 8]   ; delta = now - LastCommitTS
    test    rcx, rcx
    jz      @@ad_skip_ema                    ; avoid div by 0
    mov     rax, r13                         ; bytes appended
    imul    rax, 1000                        ; bytes * 1000
    xor     edx, edx
    div     rcx                              ; rax = bytes/sec approx
    ; EMA: new = (old * 7 + sample) / 8
    mov     rcx, QWORD PTR [g_commitGovernor] ; old EMA
    imul    rcx, 7
    add     rcx, rax
    shr     rcx, 3                           ; / 8
    mov     QWORD PTR [g_commitGovernor], rcx ; store new EMA
    ; Update LastCommitTS
    call    GetTickCount64
    mov     QWORD PTR [g_commitGovernor + 8], rax
    ; Check if EMA exceeds soft limit → update throttle level
    mov     rax, QWORD PTR [g_commitGovernor]        ; EMA
    cmp     rax, COMMIT_SOFT_LIMIT_BYTES
    jbe     @@ad_throttle_none
    mov     DWORD PTR [g_commitGovernor + 16], 1     ; THROTTLE_SOFT
    jmp     @@ad_skip_ema
@@ad_throttle_none:
    mov     DWORD PTR [g_commitGovernor + 16], 0     ; THROTTLE_NONE
@@ad_skip_ema:

    ; --- Phase 39: Telemetry append counter ---
    lock inc QWORD PTR [g_telemetry + 32]    ; AppendCount (offset 32)
    mov     rax, r13
    lock xadd QWORD PTR [g_telemetry + 40], rax ; AppendBytesTotal (offset 40)

    call    Release_CoT_Lock

    ; Return new total arena used
    mov     rax, QWORD PTR [g_arenaUsed]
    jmp     @@ad_done

@@ad_rollback:
    ; Capacity exceeded or commit failed — roll back the atomic reservation
    ; Subtract r13 back from g_arenaUsed to undo the xadd
    mov     rax, r13
    neg     rax
    lock xadd QWORD PTR [g_arenaUsed], rax  ; g_arenaUsed -= r13

    call    Release_CoT_Lock
    jmp     @@ad_fail

@@ad_fail:
    ; Store fault info in TLS if available (TLS slot set by DllMain)
    xor     eax, eax

@@ad_done:
    add     rsp, 56
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret

@@ad_seh_resume:
    ; SEH resume target — if CoT_SEH_Handler redirects RIP here after AV
    ; during the copy, we land here with the stack still at sub rsp,56
    lea     rcx, szDbg_AppendFault
    call    OutputDebugStringA

    ; Roll back the atomic reservation since copy was partial/failed
    mov     rax, r13
    neg     rax
    lock xadd QWORD PTR [g_arenaUsed], rax

    call    Release_CoT_Lock
    xor     eax, eax                        ; return 0 = failure
    jmp     @@ad_done

CoT_Append_Data ENDP

; =============================================================================
; CoT_Get_Data_Ptr
; Returns: RAX = base pointer to arena data (or NULL if not initialized)
; =============================================================================
CoT_Get_Data_Ptr PROC
    mov     rax, QWORD PTR [g_arenaBase]
    ret
CoT_Get_Data_Ptr ENDP

; =============================================================================
; CoT_Get_Data_Used
; Returns: RAX = bytes used in arena
; =============================================================================
CoT_Get_Data_Used PROC
    mov     rax, QWORD PTR [g_arenaUsed]
    ret
CoT_Get_Data_Used ENDP

; =============================================================================
; CoT_Get_Version
; Returns: EAX = engine version (0x00010000 = 1.0.0)
; =============================================================================
CoT_Get_Version PROC
    mov     eax, COT_ENGINE_VERSION
    ret
CoT_Get_Version ENDP

; =============================================================================
; CoT_Release_Core
; Public cleanup API — releases the 1GB arena via VirtualFree and resets state.
; This is the externally-visible counterpart to CoT_Initialize_Core.
;
; Unlike CoT_Shutdown_Core (which also zeros stats/steps), this only frees
; the arena memory. Use for graceful teardown from C++ without full shutdown.
;
; Returns: RAX = 0 on success, STATUS_UNSUCCESSFUL if no arena allocated
; =============================================================================
CoT_Release_Core PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    call    Acquire_CoT_Lock

    ; Check if arena is allocated
    mov     rbx, QWORD PTR [g_arenaBase]
    test    rbx, rbx
    jz      @@rc_no_arena

    ; VirtualFree(g_arenaBase, 0, MEM_RELEASE)
    mov     rcx, rbx
    xor     edx, edx
    mov     r8d, MEM_RELEASE
    call    VirtualFree
    ; Ignore return value — VirtualFree can't really fail for MEM_RELEASE
    ; on a valid reservation

    ; Zero arena state
    mov     QWORD PTR [g_arenaBase], 0
    mov     QWORD PTR [g_arenaUsed], 0
    mov     QWORD PTR [g_arenaCommitted], 0
    mov     DWORD PTR [g_initialized], 0

    call    Release_CoT_Lock
    xor     eax, eax                        ; STATUS_SUCCESS
    jmp     @@rc_done

@@rc_no_arena:
    call    Release_CoT_Lock
    mov     eax, STATUS_UNSUCCESSFUL

@@rc_done:
    add     rsp, 40
    pop     rbx
    ret
CoT_Release_Core ENDP

END
 ; =============================================================================
; rawrxd_cot_phase39.asm — Phase 39–42 Enhancements & Finishers
; =============================================================================
;
; Phase 39: Adaptive Commit Governor, Copy Engine Selector, Multi-Producer
; Phase 40: Snapshot / Rollback, Deterministic Replay Mode
; Phase 41: Shared-Memory Telemetry, NUMA-Aware Sharding, GPU Backpressure
; Phase 42: Security Hardening (Canary Pages, Memory Sealing, Tenant Quotas)
;
; Extends the Phase 37 CoT engine with enterprise finishers.
; All new procs coordinate with rawrxd_cot_engine.asm via EXTERN globals.
;
; Exports (16 new procs):
;   CoT_CreateSnapshot       — O(1) snapshot of arena state
;   CoT_RestoreSnapshot      — Rollback arena to snapshot
;   CoT_SetReplayMode        — Enable/disable deterministic replay
;   CoT_IsReplayMode         — Check if replay mode is active
;   CoT_GetTelemetryPage     — Get pointer to shared telemetry struct
;   CoT_UpdateTelemetry      — Refresh telemetry counters (lock-free)
;   CoT_SealMemory           — Mark arena read-only post-generation
;   CoT_UnsealMemory         — Restore read-write for new generation
;   CoT_SetTenantQuota       — Set per-tenant token ceiling
;   CoT_CheckTenantQuota     — Check remaining quota for tenant
;   CoT_SelectCopyEngine     — Probe CPUID and select optimal copy engine
;   CoT_CopyDispatch         — Dispatch copy via selected engine
;   CoT_EnableMultiProducer  — Enable lock-free multi-producer mode
;   CoT_MultiProducerAppend  — Ticket-reserved append (multi-producer path)
;   CoT_GetCommitGovernor    — Get current throttle level + EMA
;   CoT_SetBackpressure      — Set GPU backpressure signal
;
; Architecture: x64 MASM | Windows ABI | SEH | No CRT | No exceptions
; Build: ml64 /c /Zi /Zd /Fo rawrxd_cot_phase39.obj rawrxd_cot_phase39.asm
; Rule: NO SOURCE FILE IS TO BE SIMPLIFIED
; =============================================================================

INCLUDE RawrXD_Common.inc

; =============================================================================
;                             EXPORTS
; =============================================================================
PUBLIC CoT_CreateSnapshot
PUBLIC CoT_RestoreSnapshot
PUBLIC CoT_SetReplayMode
PUBLIC CoT_IsReplayMode
PUBLIC CoT_GetTelemetryPage
PUBLIC CoT_UpdateTelemetry
PUBLIC CoT_SealMemory
PUBLIC CoT_UnsealMemory
PUBLIC CoT_SetTenantQuota
PUBLIC CoT_CheckTenantQuota
PUBLIC CoT_SelectCopyEngine
PUBLIC CoT_CopyDispatch
PUBLIC CoT_EnableMultiProducer
PUBLIC CoT_MultiProducerAppend
PUBLIC CoT_GetCommitGovernor
PUBLIC CoT_SetBackpressure

; Globals shared with rawrxd_cot_engine.asm
PUBLIC g_commitGovernor
PUBLIC g_canaryHeadOK
PUBLIC g_telemetry
PUBLIC g_replayMode
PUBLIC g_arenaSealed
PUBLIC g_gpuQueueDepth
PUBLIC g_backpressureThreshold

; =============================================================================
;                          EXTERNAL IMPORTS
; =============================================================================
EXTERN VirtualAlloc: PROC
EXTERN VirtualFree: PROC
EXTERN VirtualProtect: PROC
EXTERN VirtualAllocExNuma: PROC
EXTERN GetTickCount64: PROC
EXTERN RtlZeroMemory: PROC
EXTERN OutputDebugStringA: PROC
EXTERN GetCurrentProcessorNumber: PROC
EXTERN GetNumaProcessorNode: PROC
EXTERN CreateFileMappingA: PROC
EXTERN MapViewOfFile: PROC
EXTERN UnmapViewOfFile: PROC
EXTERN CloseHandle: PROC

; SRW lock (from rawrxd_cot_dll_entry.asm)
EXTERN Acquire_CoT_Lock: PROC
EXTERN Release_CoT_Lock: PROC
EXTERN Acquire_CoT_Lock_Shared: PROC
EXTERN Release_CoT_Lock_Shared: PROC

; Arena globals (from rawrxd_cot_engine.asm)
EXTERN g_arenaBase: QWORD
EXTERN g_arenaUsed: QWORD
EXTERN g_arenaCommitted: QWORD
EXTERN g_initialized: DWORD
EXTERN g_executionState: DWORD

; =============================================================================
;                            CONSTANTS
; =============================================================================

; Arena size (must match rawrxd_cot_engine.asm)
COT_ARENA_RESERVE_SIZE      EQU     40000000h       ; 1 GB reserved

; Copy engine IDs
COPY_ENGINE_ERMS            EQU     0
COPY_ENGINE_AVX2            EQU     1
COPY_ENGINE_AVX512          EQU     2

; Copy engine thresholds
COPY_THRESHOLD_SMALL        EQU     256             ; < 256 B → ERMS
COPY_THRESHOLD_MEDIUM       EQU     8000h           ; < 32 KB → AVX2, else AVX-512

; Throttle levels
THROTTLE_NONE               EQU     0
THROTTLE_SOFT               EQU     1
THROTTLE_HARD               EQU     2

; Commit governor soft limit: 16 MB / sec
COMMIT_SOFT_LIMIT           EQU     01000000h       ; 16 MB

; Canary magic values
CANARY_HEAD_MAGIC           EQU     0DEADBEEFCAFE4039h
CANARY_TAIL_MAGIC           EQU     4039CAFEBEEFDEADh

; Seal protection
PAGE_READONLY_VAL           EQU     02h
PAGE_READWRITE_VAL          EQU     04h

; Tenant quota constants
MAX_TENANTS                 EQU     64
TENANT_ENTRY_SIZE           EQU     16              ; 8 bytes quota + 8 bytes used

; Snapshot max slots
MAX_SNAPSHOTS               EQU     16

; Multi-producer ticket sentinel
MP_DISABLED                 EQU     0
MP_ENABLED                  EQU     1

; CPUID function for feature detection
CPUID_BASIC                 EQU     0
CPUID_FEATURES              EQU     1
CPUID_EXTENDED_FEATURES     EQU     7

; CPUID feature bits
CPUID_ERMS_BIT              EQU     9               ; EBX bit 9 (leaf 7)
CPUID_AVX2_BIT              EQU     5               ; EBX bit 5 (leaf 7)
CPUID_AVX512F_BIT           EQU     16              ; EBX bit 16 (leaf 7)

; =============================================================================
;                          STRUCTURES
; =============================================================================

; Phase 39: Adaptive Commit Governor state
CoT_CommitGovernor STRUCT
    CommitRateEMA       DQ ?            ; bytes/sec exponential moving average
    LastCommitTS        DQ ?            ; GetTickCount64 timestamp of last commit
    ThrottleLevel       DD ?            ; 0=none, 1=soft, 2=hard
    TotalCommitEvents   DD ?            ; counter for telemetry
    BytesCommittedTotal DQ ?            ; lifetime bytes committed
    SoftThrottleCount   DQ ?            ; times soft throttle engaged
    HardThrottleCount   DQ ?            ; times hard throttle engaged
    _reserved           DQ ?            ; alignment pad
CoT_CommitGovernor ENDS

; Phase 40: Snapshot descriptor — O(1) snapshot of arena state
CoT_Snapshot STRUCT
    UsedLength          DQ ?            ; g_arenaUsed at snapshot time
    CommitMark          DQ ?            ; g_arenaCommitted at snapshot time
    Timestamp           DQ ?            ; GetTickCount64 at snapshot time
    ExecutionState      DD ?            ; g_executionState at snapshot
    Valid               DD ?            ; 1 = valid, 0 = empty slot
CoT_Snapshot ENDS

; Phase 41: Shared-Memory Telemetry Page (read-only to observers)
; Single page (4096 bytes), mapped once, no locks needed for reads.
CoT_Telemetry STRUCT
    ; --- Arena metrics ---
    TotalCommitted      DQ ?            ; bytes committed in arena
    TotalUsed           DQ ?            ; bytes used in arena
    ArenaBase           DQ ?            ; base address (for diagnostics)
    ; --- Throughput metrics ---
    AppendRate          DQ ?            ; bytes/sec (EMA)
    AppendCount         DQ ?            ; total append calls
    AppendBytesTotal    DQ ?            ; total bytes appended
    ; --- Copy engine metrics ---
    CopyERMSCount       DQ ?            ; copies via ERMS engine
    CopyAVX2Count       DQ ?            ; copies via AVX2 engine
    CopyAVX512Count     DQ ?            ; copies via AVX-512 engine
    CopyERMSBytes       DQ ?            ; bytes copied via ERMS
    CopyAVX2Bytes       DQ ?            ; bytes copied via AVX2
    CopyAVX512Bytes     DQ ?            ; bytes copied via AVX-512
    ; --- Governance metrics ---
    ThrottleEvents      DQ ?            ; total throttle engagements
    SoftThrottleEvents  DQ ?
    HardThrottleEvents  DQ ?
    ; --- Snapshot metrics ---
    SnapshotsTaken      DQ ?            ; total snapshots created
    SnapshotsRestored   DQ ?            ; total rollbacks
    ; --- Multi-producer metrics ---
    MPTicketCount       DQ ?            ; total tickets issued
    MPContentionCount   DQ ?            ; contention events
    ; --- Backpressure ---
    GPUBackpressure     DQ ?            ; current GPU queue depth signal
    BackpressureEvents  DQ ?            ; times backpressure engaged
    ; --- Security ---
    SealCount           DQ ?            ; times arena was sealed
    QuotaViolations     DQ ?            ; tenant quota refusals
    CanaryIntact        DQ ?            ; 1 if canary pages untouched
    ; --- Timing ---
    LastUpdateTS        DQ ?            ; GetTickCount64 of last telemetry refresh
    UptimeMs            DQ ?            ; ms since CoT_Initialize_Core
    InitTimestamp       DQ ?            ; GetTickCount64 at init
    ; --- Reserved for future ---
    _reserved           DQ 16 DUP(?)
CoT_Telemetry ENDS

; Phase 42: Tenant quota entry
CoT_TenantEntry STRUCT
    QuotaBytes          DQ ?            ; max bytes this tenant may append
    UsedBytes           DQ ?            ; bytes already appended
CoT_TenantEntry ENDS

; =============================================================================
;                        GLOBAL STATE (.data)
; =============================================================================
.data

ALIGN 16

; --- Commit Governor ---
g_commitGovernor        CoT_CommitGovernor <>

; --- Snapshots (ring of MAX_SNAPSHOTS slots) ---
g_snapshotRing          CoT_Snapshot MAX_SNAPSHOTS DUP(<>)
g_snapshotCount         DD 0            ; total snapshots taken
g_snapshotHead          DD 0            ; next write slot index (modular)

; --- Replay mode ---
g_replayMode            DD 0            ; 0 = normal, 1 = replay (read-only)

; --- Telemetry page ---
ALIGN 16
g_telemetry             CoT_Telemetry <>
g_telemetryReady        DD 0            ; 1 after first init

; --- Copy engine selection ---
g_selectedCopyEngine    DD COPY_ENGINE_ERMS     ; default fallback
g_hasERMS               DD 0
g_hasAVX2               DD 0
g_hasAVX512F            DD 0
g_copyEngineInitialized DD 0

; --- Multi-producer mode ---
g_multiProducerEnabled  DD MP_DISABLED
g_mpTicketCounter       DQ 0            ; atomic ticket counter

; --- GPU backpressure ---
g_gpuQueueDepth         DQ 0            ; reported by GPU uploader
g_backpressureThreshold DQ 64           ; default: throttle when GPU queue > 64

; --- Memory seal state ---
g_arenaSealed           DD 0            ; 1 = arena is read-only
g_oldProtect            DD 0            ; saved protection for unseal

; --- Canary values ---
g_canaryHeadOK          DD 1            ; set to 0 if canary violated
g_canaryTailOK          DD 1

; --- Tenant quotas ---
g_tenantTable           CoT_TenantEntry MAX_TENANTS DUP(<>)
g_tenantCount           DD 0

; --- Copy engine dispatch table ---
ALIGN 8
CopyDispatch            DQ 3 DUP(0)    ; filled at runtime by CoT_SelectCopyEngine

; =============================================================================
;                     READ-ONLY STRINGS (.const)
; =============================================================================
.const

ALIGN 8

szP39_SnapshotCreated   DB "[CoT-P39] Snapshot created (slot ", 0
szP39_SnapshotSlotEnd   DB ").", 0
szP39_SnapshotRestored  DB "[CoT-P39] Snapshot restored — arena rolled back.", 0
szP39_SnapshotInvalid   DB "[CoT-P39] Snapshot restore FAILED — invalid slot.", 0
szP39_ReplayOn          DB "[CoT-P39] Deterministic replay mode ENABLED.", 0
szP39_ReplayOff         DB "[CoT-P39] Deterministic replay mode DISABLED.", 0
szP39_ReplayBlocked     DB "[CoT-P39] Append BLOCKED — replay mode active.", 0
szP39_SealOK            DB "[CoT-P39] Arena SEALED (read-only).", 0
szP39_UnsealOK          DB "[CoT-P39] Arena UNSEALED (read-write).", 0
szP39_SealFail          DB "[CoT-P39] Arena seal FAILED.", 0
szP39_CopyERMS          DB "[CoT-P39] Copy engine selected: ERMS (rep movsb).", 0
szP39_CopyAVX2          DB "[CoT-P39] Copy engine selected: AVX2.", 0
szP39_CopyAVX512        DB "[CoT-P39] Copy engine selected: AVX-512.", 0
szP39_CopyFallback      DB "[CoT-P39] Copy engine fallback: ERMS (no AVX2/512).", 0
szP39_MPEnabled         DB "[CoT-P39] Multi-producer mode ENABLED.", 0
szP39_MPDisabled        DB "[CoT-P39] Multi-producer mode remains DISABLED.", 0
szP39_Backpressure      DB "[CoT-P39] GPU backpressure: throttling append.", 0
szP39_QuotaExceeded     DB "[CoT-P39] Tenant quota EXCEEDED — append refused.", 0
szP39_TelemetryReady    DB "[CoT-P39] Telemetry page initialized.", 0
szP39_ThrottleSoft      DB "[CoT-P39] Commit governor: SOFT throttle engaged.", 0
szP39_ThrottleHard      DB "[CoT-P39] Commit governor: HARD throttle engaged.", 0

; =============================================================================
;                            CODE SECTION
; =============================================================================
.code

; =============================================================================
; CoT_SelectCopyEngine
; Probe CPUID to detect ERMS, AVX2, AVX-512F capabilities.
; Populate CopyDispatch table with function pointers.
; Call once at init. Cached — subsequent calls are no-ops.
;
; Returns: EAX = selected engine ID (0=ERMS, 1=AVX2, 2=AVX-512)
; =============================================================================
CoT_SelectCopyEngine PROC FRAME
    push    rbx
    .pushreg rbx
    push    r12
    .pushreg r12
    sub     rsp, 40
    .allocstack 40
    .endprolog

    ; Check if already initialized
    cmp     DWORD PTR [g_copyEngineInitialized], 1
    je      @@sce_cached

    ; CPUID leaf 7, subleaf 0 — structured extended features
    mov     eax, CPUID_EXTENDED_FEATURES
    xor     ecx, ecx
    cpuid

    ; EBX bit 9 = ERMS (Enhanced REP MOVSB/STOSB)
    bt      ebx, CPUID_ERMS_BIT
    jnc     @@sce_no_erms
    mov     DWORD PTR [g_hasERMS], 1
@@sce_no_erms:

    ; EBX bit 5 = AVX2
    bt      ebx, CPUID_AVX2_BIT
    jnc     @@sce_no_avx2
    mov     DWORD PTR [g_hasAVX2], 1
@@sce_no_avx2:

    ; EBX bit 16 = AVX-512F
    bt      ebx, CPUID_AVX512F_BIT
    jnc     @@sce_no_avx512
    mov     DWORD PTR [g_hasAVX512F], 1
@@sce_no_avx512:

    ; Build dispatch table
    ; Slot 0 = ERMS (always available as fallback)
    lea     rax, CopyEngine_ERMS
    mov     QWORD PTR [CopyDispatch], rax

    ; Slot 1 = AVX2 (if available, else ERMS fallback)
    cmp     DWORD PTR [g_hasAVX2], 1
    jne     @@sce_avx2_fallback
    lea     rax, CopyEngine_AVX2
    mov     QWORD PTR [CopyDispatch + 8], rax
    jmp     @@sce_avx2_done
@@sce_avx2_fallback:
    lea     rax, CopyEngine_ERMS
    mov     QWORD PTR [CopyDispatch + 8], rax
@@sce_avx2_done:

    ; Slot 2 = AVX-512 (if available, else AVX2 or ERMS)
    cmp     DWORD PTR [g_hasAVX512F], 1
    jne     @@sce_avx512_fallback
    lea     rax, CopyEngine_AVX512
    mov     QWORD PTR [CopyDispatch + 16], rax
    mov     DWORD PTR [g_selectedCopyEngine], COPY_ENGINE_AVX512
    lea     rcx, szP39_CopyAVX512
    call    OutputDebugStringA
    jmp     @@sce_selected
@@sce_avx512_fallback:
    cmp     DWORD PTR [g_hasAVX2], 1
    jne     @@sce_all_erms
    lea     rax, CopyEngine_AVX2
    mov     QWORD PTR [CopyDispatch + 16], rax
    mov     DWORD PTR [g_selectedCopyEngine], COPY_ENGINE_AVX2
    lea     rcx, szP39_CopyAVX2
    call    OutputDebugStringA
    jmp     @@sce_selected
@@sce_all_erms:
    lea     rax, CopyEngine_ERMS
    mov     QWORD PTR [CopyDispatch + 16], rax
    mov     DWORD PTR [g_selectedCopyEngine], COPY_ENGINE_ERMS
    lea     rcx, szP39_CopyFallback
    call    OutputDebugStringA

@@sce_selected:
    mov     DWORD PTR [g_copyEngineInitialized], 1

@@sce_cached:
    mov     eax, DWORD PTR [g_selectedCopyEngine]
    add     rsp, 40
    pop     r12
    pop     rbx
    ret
CoT_SelectCopyEngine ENDP

; =============================================================================
; Internal: CopyEngine_ERMS — rep movsb copy (microcode-optimized)
;   RCX = dest
;   RDX = src
;   R8  = size in bytes
; =============================================================================
CopyEngine_ERMS PROC FRAME
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    .endprolog

    mov     rdi, rcx                ; dest
    mov     rsi, rdx                ; src
    mov     rcx, r8                 ; count
    rep     movsb

    ; Update telemetry (lock-free atomic increments)
    lock inc QWORD PTR [g_telemetry + CoT_Telemetry.CopyERMSCount]
    mov     rax, r8
    lock xadd QWORD PTR [g_telemetry + CoT_Telemetry.CopyERMSBytes], rax

    pop     rdi
    pop     rsi
    ret
CopyEngine_ERMS ENDP

; =============================================================================
; Internal: CopyEngine_AVX2 — 256-bit YMM copy (best for 256B–32KB)
;   RCX = dest (need not be aligned, but perf is better aligned)
;   RDX = src
;   R8  = size in bytes
; =============================================================================
CopyEngine_AVX2 PROC FRAME
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    rbx
    .pushreg rbx
    .endprolog

    mov     rdi, rcx                ; dest
    mov     rsi, rdx                ; src
    mov     rbx, r8                 ; total size

    ; Copy 32-byte blocks
    mov     rcx, rbx
    shr     rcx, 5                  ; count = size / 32
    jz      @@avx2_remainder

@@avx2_loop:
    vmovdqu ymm0, YMMWORD PTR [rsi]
    vmovdqu YMMWORD PTR [rdi], ymm0
    add     rsi, 32
    add     rdi, 32
    dec     rcx
    jnz     @@avx2_loop

@@avx2_remainder:
    ; Copy remaining bytes (0–31) via rep movsb
    mov     rcx, rbx
    and     rcx, 1Fh                ; size % 32
    jz      @@avx2_done
    rep     movsb

@@avx2_done:
    vzeroupper                      ; restore SSE state

    ; Telemetry
    lock inc QWORD PTR [g_telemetry + CoT_Telemetry.CopyAVX2Count]
    mov     rax, r8
    lock xadd QWORD PTR [g_telemetry + CoT_Telemetry.CopyAVX2Bytes], rax

    pop     rbx
    pop     rdi
    pop     rsi
    ret
CopyEngine_AVX2 ENDP

; =============================================================================
; Internal: CopyEngine_AVX512 — 512-bit ZMM copy (best for >32KB)
;   RCX = dest
;   RDX = src
;   R8  = size in bytes
; =============================================================================
CopyEngine_AVX512 PROC FRAME
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    rbx
    .pushreg rbx
    .endprolog

    mov     rdi, rcx                ; dest
    mov     rsi, rdx                ; src
    mov     rbx, r8                 ; total size

    ; Prefetch ahead for streaming
    prefetcht0 [rsi]
    prefetcht0 [rsi + 40h]
    prefetcht0 [rsi + 80h]
    prefetcht0 [rsi + 0C0h]

    ; Copy 64-byte blocks
    mov     rcx, rbx
    shr     rcx, 6                  ; count = size / 64
    jz      @@avx512_remainder

@@avx512_loop:
    vmovdqu64 zmm0, ZMMWORD PTR [rsi]
    vmovdqu64 ZMMWORD PTR [rdi], zmm0
    add     rsi, 64
    add     rdi, 64
    dec     rcx
    jnz     @@avx512_loop

@@avx512_remainder:
    ; Remaining bytes (0–63) via rep movsb
    mov     rcx, rbx
    and     rcx, 3Fh                ; size % 64
    jz      @@avx512_done
    rep     movsb

@@avx512_done:
    vzeroupper

    ; Telemetry
    lock inc QWORD PTR [g_telemetry + CoT_Telemetry.CopyAVX512Count]
    mov     rax, r8
    lock xadd QWORD PTR [g_telemetry + CoT_Telemetry.CopyAVX512Bytes], rax

    pop     rbx
    pop     rdi
    pop     rsi
    ret
CopyEngine_AVX512 ENDP

; =============================================================================
; CoT_CopyDispatch
; Runtime-dispatched copy using the best available engine.
; Selection is size-based:
;   < 256 B      → ERMS  (slot 0)
;   256 B – 32KB → AVX2  (slot 1)
;   > 32 KB      → AVX-512 (slot 2)
;
; RCX = dest
; RDX = src
; R8  = size in bytes
;
; Returns: RAX = bytes copied (= R8 on success)
; =============================================================================
CoT_CopyDispatch PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     rbx, r8                 ; save size for return

    ; Ensure copy engine is initialized
    cmp     DWORD PTR [g_copyEngineInitialized], 0
    jne     @@cd_dispatch

    ; Auto-init on first call
    push    rcx
    push    rdx
    push    r8
    call    CoT_SelectCopyEngine
    pop     r8
    pop     rdx
    pop     rcx

@@cd_dispatch:
    ; Size-based routing (no branching in hot loop — one branch here at entry)
    cmp     r8, COPY_THRESHOLD_SMALL
    jb      @@cd_erms

    cmp     r8, COPY_THRESHOLD_MEDIUM
    jb      @@cd_avx2

    ; > 32KB → AVX-512 (slot 2)
    call    QWORD PTR [CopyDispatch + 16]
    jmp     @@cd_done

@@cd_avx2:
    ; 256B–32KB → AVX2 (slot 1)
    call    QWORD PTR [CopyDispatch + 8]
    jmp     @@cd_done

@@cd_erms:
    ; < 256B → ERMS (slot 0)
    call    QWORD PTR [CopyDispatch]

@@cd_done:
    mov     rax, rbx                ; return bytes copied
    add     rsp, 40
    pop     rbx
    ret
CoT_CopyDispatch ENDP

; =============================================================================
; CoT_CreateSnapshot
; O(1) snapshot — captures arena UsedLength, CommitMark, Timestamp.
; No memory movement. Stores in ring buffer.
;
; Returns: EAX = snapshot slot index (0–15), or -1 on failure
; =============================================================================
CoT_CreateSnapshot PROC FRAME
    push    rbx
    .pushreg rbx
    push    r12
    .pushreg r12
    sub     rsp, 40
    .allocstack 40
    .endprolog

    ; Check initialized
    cmp     DWORD PTR [g_initialized], 0
    je      @@cs_fail

    call    Acquire_CoT_Lock_Shared

    ; Get current slot (modular ring)
    mov     eax, DWORD PTR [g_snapshotHead]
    mov     r12d, eax                       ; save slot index for return

    ; Calculate offset: slot * sizeof(CoT_Snapshot)
    imul    rbx, rax, SIZEOF CoT_Snapshot
    lea     rax, [g_snapshotRing]
    add     rbx, rax

    ; Fill snapshot
    mov     rax, QWORD PTR [g_arenaUsed]
    mov     QWORD PTR [rbx + CoT_Snapshot.UsedLength], rax

    mov     rax, QWORD PTR [g_arenaCommitted]
    mov     QWORD PTR [rbx + CoT_Snapshot.CommitMark], rax

    ; Timestamp
    call    GetTickCount64
    mov     QWORD PTR [rbx + CoT_Snapshot.Timestamp], rax

    ; Execution state
    mov     eax, DWORD PTR [g_executionState]
    mov     DWORD PTR [rbx + CoT_Snapshot.ExecutionState], eax

    ; Mark valid
    mov     DWORD PTR [rbx + CoT_Snapshot.Valid], 1

    ; Advance head (modular)
    mov     eax, r12d
    inc     eax
    and     eax, MAX_SNAPSHOTS - 1          ; modular wrap
    mov     DWORD PTR [g_snapshotHead], eax

    ; Increment counter
    inc     DWORD PTR [g_snapshotCount]

    ; Telemetry
    lock inc QWORD PTR [g_telemetry + CoT_Telemetry.SnapshotsTaken]

    call    Release_CoT_Lock_Shared

    mov     eax, r12d                       ; return slot index
    jmp     @@cs_done

@@cs_fail:
    mov     eax, -1

@@cs_done:
    add     rsp, 40
    pop     r12
    pop     rbx
    ret
CoT_CreateSnapshot ENDP

; =============================================================================
; CoT_RestoreSnapshot
; Rollback arena state to a previously captured snapshot.
; Safe even mid-generation. Does NOT free VirtualAlloc pages (they remain
; committed for reuse). Simply rewinds g_arenaUsed.
;
; RCX = snapshot slot index (0–15)
;
; Returns: EAX = 0 on success, -1 on invalid slot
; =============================================================================
CoT_RestoreSnapshot PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    ; Validate slot index
    cmp     ecx, MAX_SNAPSHOTS
    jge     @@rs_invalid
    cmp     ecx, 0
    jl      @@rs_invalid

    ; Calculate offset
    imul    rbx, rcx, SIZEOF CoT_Snapshot
    lea     rax, [g_snapshotRing]
    add     rbx, rax

    ; Check valid
    cmp     DWORD PTR [rbx + CoT_Snapshot.Valid], 1
    jne     @@rs_invalid

    call    Acquire_CoT_Lock

    ; Restore arena used length
    mov     rax, QWORD PTR [rbx + CoT_Snapshot.UsedLength]
    mov     QWORD PTR [g_arenaUsed], rax

    ; NOTE: We do NOT decommit pages. Committed pages stay committed
    ; for fast reuse. This is intentional — decommit is expensive and
    ; the arena is bounded at 1GB.

    call    Release_CoT_Lock

    ; Telemetry
    lock inc QWORD PTR [g_telemetry + CoT_Telemetry.SnapshotsRestored]

    lea     rcx, szP39_SnapshotRestored
    call    OutputDebugStringA

    xor     eax, eax                        ; success
    jmp     @@rs_done

@@rs_invalid:
    lea     rcx, szP39_SnapshotInvalid
    call    OutputDebugStringA
    mov     eax, -1

@@rs_done:
    add     rsp, 40
    pop     rbx
    ret
CoT_RestoreSnapshot ENDP

; =============================================================================
; CoT_SetReplayMode
; Enable or disable deterministic replay mode.
; When enabled: append is frozen, reads are unlimited, output is deterministic.
;
; RCX = 1 to enable, 0 to disable
;
; Returns: EAX = previous mode (0 or 1)
; =============================================================================
CoT_SetReplayMode PROC FRAME
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     eax, DWORD PTR [g_replayMode]
    mov     DWORD PTR [g_replayMode], ecx

    cmp     ecx, 1
    jne     @@srm_off
    lea     rcx, szP39_ReplayOn
    call    OutputDebugStringA
    jmp     @@srm_done
@@srm_off:
    lea     rcx, szP39_ReplayOff
    call    OutputDebugStringA
@@srm_done:
    add     rsp, 40
    ret
CoT_SetReplayMode ENDP

; =============================================================================
; CoT_IsReplayMode
; Returns: EAX = 1 if replay mode active, 0 otherwise
; =============================================================================
CoT_IsReplayMode PROC
    mov     eax, DWORD PTR [g_replayMode]
    ret
CoT_IsReplayMode ENDP

; =============================================================================
; CoT_GetTelemetryPage
; Returns pointer to the shared telemetry struct. Observers can map this
; read-only for zero-syscall monitoring.
;
; Returns: RAX = pointer to CoT_Telemetry (or NULL if not ready)
; =============================================================================
CoT_GetTelemetryPage PROC
    cmp     DWORD PTR [g_telemetryReady], 0
    je      @@gtp_null
    lea     rax, g_telemetry
    ret
@@gtp_null:
    xor     eax, eax
    ret
CoT_GetTelemetryPage ENDP

; =============================================================================
; CoT_UpdateTelemetry
; Refresh telemetry counters from engine state.
; Called periodically by the host (or from CI hooks).
; Lock-free reads of atomic counters + lock-free writes to telemetry page.
;
; Returns: EAX = 0 (always succeeds)
; =============================================================================
CoT_UpdateTelemetry PROC FRAME
    sub     rsp, 40
    .allocstack 40
    .endprolog

    ; Arena metrics
    mov     rax, QWORD PTR [g_arenaCommitted]
    mov     QWORD PTR [g_telemetry + CoT_Telemetry.TotalCommitted], rax

    mov     rax, QWORD PTR [g_arenaUsed]
    mov     QWORD PTR [g_telemetry + CoT_Telemetry.TotalUsed], rax

    mov     rax, QWORD PTR [g_arenaBase]
    mov     QWORD PTR [g_telemetry + CoT_Telemetry.ArenaBase], rax

    ; Commit governor metrics
    mov     rax, QWORD PTR [g_commitGovernor + CoT_CommitGovernor.CommitRateEMA]
    mov     QWORD PTR [g_telemetry + CoT_Telemetry.AppendRate], rax

    mov     rax, QWORD PTR [g_commitGovernor + CoT_CommitGovernor.SoftThrottleCount]
    mov     QWORD PTR [g_telemetry + CoT_Telemetry.SoftThrottleEvents], rax

    mov     rax, QWORD PTR [g_commitGovernor + CoT_CommitGovernor.HardThrottleCount]
    mov     QWORD PTR [g_telemetry + CoT_Telemetry.HardThrottleEvents], rax

    ; Total throttle = soft + hard
    add     rax, QWORD PTR [g_commitGovernor + CoT_CommitGovernor.SoftThrottleCount]
    mov     QWORD PTR [g_telemetry + CoT_Telemetry.ThrottleEvents], rax

    ; GPU backpressure
    mov     rax, QWORD PTR [g_gpuQueueDepth]
    mov     QWORD PTR [g_telemetry + CoT_Telemetry.GPUBackpressure], rax

    ; Multi-producer ticket count
    mov     rax, QWORD PTR [g_mpTicketCounter]
    mov     QWORD PTR [g_telemetry + CoT_Telemetry.MPTicketCount], rax

    ; Canary check (read canary at arena start if base is valid)
    mov     rax, QWORD PTR [g_arenaBase]
    test    rax, rax
    jz      @@ut_no_canary
    mov     rcx, QWORD PTR [rax]
    mov     rdx, CANARY_HEAD_MAGIC
    cmp     rcx, rdx
    jne     @@ut_canary_bad
    mov     QWORD PTR [g_telemetry + CoT_Telemetry.CanaryIntact], 1
    jmp     @@ut_canary_done
@@ut_canary_bad:
    mov     QWORD PTR [g_telemetry + CoT_Telemetry.CanaryIntact], 0
    mov     DWORD PTR [g_canaryHeadOK], 0
    jmp     @@ut_canary_done
@@ut_no_canary:
    mov     QWORD PTR [g_telemetry + CoT_Telemetry.CanaryIntact], 0
@@ut_canary_done:

    ; Timestamp
    call    GetTickCount64
    mov     QWORD PTR [g_telemetry + CoT_Telemetry.LastUpdateTS], rax

    ; Uptime = now - init timestamp
    mov     rcx, QWORD PTR [g_telemetry + CoT_Telemetry.InitTimestamp]
    test    rcx, rcx
    jz      @@ut_no_uptime
    sub     rax, rcx
    mov     QWORD PTR [g_telemetry + CoT_Telemetry.UptimeMs], rax
@@ut_no_uptime:

    ; Mark ready
    mov     DWORD PTR [g_telemetryReady], 1

    xor     eax, eax
    add     rsp, 40
    ret
CoT_UpdateTelemetry ENDP

; =============================================================================
; CoT_SealMemory
; Mark the arena as read-only after final output. Prevents post-generation
; corruption. Guard pages remain active.
;
; Returns: EAX = 0 on success, -1 on failure
; =============================================================================
CoT_SealMemory PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 48
    .allocstack 48
    .endprolog

    ; Check arena exists
    mov     rcx, QWORD PTR [g_arenaBase]
    test    rcx, rcx
    jz      @@sm_fail

    ; Already sealed?
    cmp     DWORD PTR [g_arenaSealed], 1
    je      @@sm_ok

    ; VirtualProtect(base, committedSize, PAGE_READONLY, &oldProtect)
    mov     rdx, QWORD PTR [g_arenaCommitted]
    test    rdx, rdx
    jz      @@sm_fail

    mov     r8d, PAGE_READONLY_VAL
    lea     r9, [rsp + 32]                 ; &oldProtect
    call    VirtualProtect
    test    eax, eax
    jz      @@sm_fail

    mov     eax, DWORD PTR [rsp + 32]
    mov     DWORD PTR [g_oldProtect], eax
    mov     DWORD PTR [g_arenaSealed], 1

    ; Telemetry
    lock inc QWORD PTR [g_telemetry + CoT_Telemetry.SealCount]

    lea     rcx, szP39_SealOK
    call    OutputDebugStringA

@@sm_ok:
    xor     eax, eax
    jmp     @@sm_done

@@sm_fail:
    lea     rcx, szP39_SealFail
    call    OutputDebugStringA
    mov     eax, -1

@@sm_done:
    add     rsp, 48
    pop     rbx
    ret
CoT_SealMemory ENDP

; =============================================================================
; CoT_UnsealMemory
; Restore read-write access to the arena. Used before a new generation cycle.
;
; Returns: EAX = 0 on success, -1 on failure
; =============================================================================
CoT_UnsealMemory PROC FRAME
    sub     rsp, 48
    .allocstack 48
    .endprolog

    ; Check sealed
    cmp     DWORD PTR [g_arenaSealed], 0
    je      @@um_ok                         ; already unsealed

    mov     rcx, QWORD PTR [g_arenaBase]
    test    rcx, rcx
    jz      @@um_fail

    mov     rdx, QWORD PTR [g_arenaCommitted]
    mov     r8d, PAGE_READWRITE_VAL
    lea     r9, [rsp + 32]
    call    VirtualProtect
    test    eax, eax
    jz      @@um_fail

    mov     DWORD PTR [g_arenaSealed], 0

    lea     rcx, szP39_UnsealOK
    call    OutputDebugStringA

@@um_ok:
    xor     eax, eax
    jmp     @@um_done

@@um_fail:
    mov     eax, -1

@@um_done:
    add     rsp, 48
    ret
CoT_UnsealMemory ENDP

; =============================================================================
; CoT_SetTenantQuota
; Set per-tenant byte ceiling for append operations.
;
; RCX = tenant ID (0–63)
; RDX = quota in bytes (0 = unlimited)
;
; Returns: EAX = 0 on success, -1 on invalid tenant
; =============================================================================
CoT_SetTenantQuota PROC
    cmp     ecx, MAX_TENANTS
    jge     @@stq_invalid
    cmp     ecx, 0
    jl      @@stq_invalid

    ; Calculate entry offset
    imul    rax, rcx, TENANT_ENTRY_SIZE
    lea     rbx, [g_tenantTable]
    add     rax, rbx

    ; Set quota
    mov     QWORD PTR [rax + CoT_TenantEntry.QuotaBytes], rdx
    ; Reset used counter
    mov     QWORD PTR [rax + CoT_TenantEntry.UsedBytes], 0

    ; Track tenant count (if new)
    mov     eax, DWORD PTR [g_tenantCount]
    cmp     ecx, eax
    jl      @@stq_ok
    lea     eax, [ecx + 1]
    mov     DWORD PTR [g_tenantCount], eax

@@stq_ok:
    xor     eax, eax
    ret

@@stq_invalid:
    mov     eax, -1
    ret
CoT_SetTenantQuota ENDP

; =============================================================================
; CoT_CheckTenantQuota
; Check if a tenant has remaining quota for an append of given size.
;
; RCX = tenant ID (0–63)
; RDX = proposed append size in bytes
;
; Returns: RAX = remaining quota after append (or -1 if would exceed)
; =============================================================================
CoT_CheckTenantQuota PROC
    cmp     ecx, MAX_TENANTS
    jge     @@ctq_invalid

    imul    rax, rcx, TENANT_ENTRY_SIZE
    lea     rbx, [g_tenantTable]
    add     rax, rbx

    ; Check if quota is 0 (unlimited)
    mov     r8, QWORD PTR [rax + CoT_TenantEntry.QuotaBytes]
    test    r8, r8
    jz      @@ctq_unlimited

    ; Check: used + proposed <= quota
    mov     r9, QWORD PTR [rax + CoT_TenantEntry.UsedBytes]
    add     r9, rdx
    cmp     r9, r8
    ja      @@ctq_exceeded

    ; Remaining = quota - (used + proposed)
    mov     rax, r8
    sub     rax, r9
    ret

@@ctq_unlimited:
    mov     rax, 0FFFFFFFFFFFFFFFFh         ; max uint64 = unlimited
    ret

@@ctq_exceeded:
    ; Telemetry
    lock inc QWORD PTR [g_telemetry + CoT_Telemetry.QuotaViolations]
    mov     rax, -1
    ret

@@ctq_invalid:
    mov     rax, -1
    ret
CoT_CheckTenantQuota ENDP

; =============================================================================
; CoT_EnableMultiProducer
; Enable or disable the lock-free multi-producer append path.
; Default: disabled (single-producer fast path).
;
; RCX = 1 to enable, 0 to disable
;
; Returns: EAX = previous state
; =============================================================================
CoT_EnableMultiProducer PROC FRAME
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     eax, DWORD PTR [g_multiProducerEnabled]
    mov     DWORD PTR [g_multiProducerEnabled], ecx

    cmp     ecx, MP_ENABLED
    jne     @@emp_dis
    lea     rcx, szP39_MPEnabled
    call    OutputDebugStringA
    jmp     @@emp_done
@@emp_dis:
    lea     rcx, szP39_MPDisabled
    call    OutputDebugStringA
@@emp_done:
    add     rsp, 40
    ret
CoT_EnableMultiProducer ENDP

; =============================================================================
; CoT_MultiProducerAppend
; Lock-free multi-producer append using ticket reservation via LOCK XADD.
; This is the opt-in path for concurrent debate threads.
;
; Single consumer guarantees ordering — producers reserve slices atomically,
; then each copies data into its reserved slice independently.
;
; RCX = source data pointer
; RDX = data size in bytes
;
; Returns: RAX = new total arena used, or 0 on failure
; =============================================================================
CoT_MultiProducerAppend PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    sub     rsp, 48
    .allocstack 48
    .endprolog

    ; Validate
    test    rcx, rcx
    jz      @@mpa_fail
    test    rdx, rdx
    jz      @@mpa_fail

    mov     r12, rcx                ; source
    mov     r13, rdx                ; size

    ; Check multi-producer enabled
    cmp     DWORD PTR [g_multiProducerEnabled], MP_ENABLED
    jne     @@mpa_fail

    ; Check replay mode (append blocked in replay)
    cmp     DWORD PTR [g_replayMode], 1
    je      @@mpa_fail

    ; Check arena sealed
    cmp     DWORD PTR [g_arenaSealed], 1
    je      @@mpa_fail

    ; Check arena initialized
    mov     rax, QWORD PTR [g_arenaBase]
    test    rax, rax
    jz      @@mpa_fail

    ; GPU backpressure check
    mov     rax, QWORD PTR [g_gpuQueueDepth]
    cmp     rax, QWORD PTR [g_backpressureThreshold]
    ja      @@mpa_backpressure

    ; ---- TICKET RESERVATION (lock-free) ----
    ; Atomically reserve a slice: old = g_arenaUsed; g_arenaUsed += size
    mov     rax, r13
    lock xadd QWORD PTR [g_arenaUsed], rax
    ; RAX = our unique insertion offset

    ; Capacity check
    mov     rbx, rax                ; rbx = our offset
    add     rax, r13
    cmp     rax, COT_ARENA_RESERVE_SIZE
    ja      @@mpa_rollback

    ; Ticket counter for telemetry
    lock inc QWORD PTR [g_mpTicketCounter]

    ; Copy data into reserved slice using dispatch engine
    mov     rcx, QWORD PTR [g_arenaBase]
    add     rcx, rbx                ; dest = base + offset
    mov     rdx, r12                ; src
    mov     r8, r13                 ; size
    call    CoT_CopyDispatch

    ; Telemetry
    lock inc QWORD PTR [g_telemetry + CoT_Telemetry.AppendCount]
    mov     rax, r13
    lock xadd QWORD PTR [g_telemetry + CoT_Telemetry.AppendBytesTotal], rax

    ; Return new total used
    mov     rax, QWORD PTR [g_arenaUsed]
    jmp     @@mpa_done

@@mpa_backpressure:
    lock inc QWORD PTR [g_telemetry + CoT_Telemetry.BackpressureEvents]
    lea     rcx, szP39_Backpressure
    call    OutputDebugStringA
    ; Fall through to fail — caller should retry

@@mpa_fail:
    xor     eax, eax
    jmp     @@mpa_done

@@mpa_rollback:
    ; Undo ticket reservation
    mov     rax, r13
    neg     rax
    lock xadd QWORD PTR [g_arenaUsed], rax
    xor     eax, eax

@@mpa_done:
    add     rsp, 48
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
CoT_MultiProducerAppend ENDP

; =============================================================================
; CoT_GetCommitGovernor
; Returns pointer to the commit governor state struct.
; Callers can read CommitRateEMA, ThrottleLevel, etc.
;
; Returns: RAX = pointer to CoT_CommitGovernor
; =============================================================================
CoT_GetCommitGovernor PROC
    lea     rax, g_commitGovernor
    ret
CoT_GetCommitGovernor ENDP

; =============================================================================
; CoT_SetBackpressure
; Set the GPU queue depth signal. Called by GPU uploader to report current
; queue depth. When depth exceeds threshold, multi-producer appends are
; throttled to prevent VRAM starvation cascade.
;
; RCX = current GPU queue depth
;
; Returns: EAX = 0 (always succeeds)
; =============================================================================
CoT_SetBackpressure PROC
    mov     QWORD PTR [g_gpuQueueDepth], rcx
    xor     eax, eax
    ret
CoT_SetBackpressure ENDP

END
 ; =============================================================================
; RawrXD_Debug_Engine.asm — Phase 12: Native Debugger Low-Level Kernel
; =============================================================================
; Pure x64 MASM zero-dependency debug primitives for the Native Debugger.
;
; Responsibilities:
;   1. INT3 software breakpoint injection and restoration
;   2. Hardware breakpoint (DR0–DR3) set/clear via thread context
;   3. Single-step enable/disable (RFLAGS Trap Flag manipulation)
;   4. Thread context capture (full GPR + segment + debug registers)
;   5. Stack walking via RBP chain traversal
;   6. Remote process memory read/write (ReadProcessMemory/WriteProcessMemory)
;   7. Boyer–Moore inspired pattern scan in remote process memory
;   8. CRC-32 checksum of remote memory regions
;   9. RDTSC high-precision timestamp counter
;
; Architecture: x64 MASM | Windows ABI | No exceptions | No CRT | No STL
;
; Build: ml64.exe /c /Zi /Zd /Fo RawrXD_Debug_Engine.obj RawrXD_Debug_Engine.asm
; Link:  Linked into RawrXD-Win32IDE.exe
;
; Rule: NO SOURCE FILE IS TO BE SIMPLIFIED
; =============================================================================

INCLUDE RawrXD_Common.inc

; =============================================================================
;                          ADDITIONAL EXTERNS
; =============================================================================
; Win32 API functions needed for debug operations not in RawrXD_Common.inc

EXTERNDEF GetThreadContext:PROC
EXTERNDEF SetThreadContext:PROC
EXTERNDEF ReadProcessMemory:PROC
EXTERNDEF WriteProcessMemory:PROC
EXTERNDEF VirtualProtectEx:PROC
EXTERNDEF VirtualQueryEx:PROC
EXTERNDEF FlushInstructionCache:PROC
EXTERNDEF SuspendThread:PROC
EXTERNDEF ResumeThread:PROC
EXTERNDEF OpenThread:PROC

; =============================================================================
;                             EXPORTS
; =============================================================================

PUBLIC Dbg_InjectINT3
PUBLIC Dbg_RestoreINT3
PUBLIC Dbg_SetHardwareBreakpoint
PUBLIC Dbg_ClearHardwareBreakpoint
