 ; =============================================================================
; RawrXD_DiskRecoveryAgent.asm
; Enterprise-grade hardware recovery for failed USB bridges
; Targets WD My Book hardware encryption with JMS567/NS1066 bridges
; Pure x64 MASM - Uses RawrXD_Common.inc (zero external SDK dependency)
;
; Build (standalone):
;   ml64.exe /c /Zi /Zd RawrXD_DiskRecoveryAgent.asm
;   link.exe RawrXD_DiskRecoveryAgent.obj /subsystem:console /entry:DiskRecovery_Main
;          kernel32.lib ntdll.lib user32.lib
;
; Build (as library kernel linked into RawrXD-Shell):
;   Included in CMakeLists.txt ASM_KERNEL_SOURCES — exports C-callable procs.
;
; Pattern: PatchResult (RAX=0 success, RAX=NTSTATUS on error, RDX=detail)
; Rule:    NO SOURCE FILE IS TO BE SIMPLIFIED.
; =============================================================================

option casemap:none

include RawrXD_Common.inc

; =============================================================================
; Additional EXTERN declarations not in RawrXD_Common.inc
; =============================================================================
EXTERNDEF DeviceIoControl:PROC
EXTERNDEF lstrlenA:PROC
EXTERNDEF WriteFile:PROC
EXTERNDEF ReadFile:PROC
EXTERNDEF SetFilePointerEx:PROC
EXTERNDEF ExitProcess:PROC
EXTERNDEF GetStdHandle:PROC
EXTERNDEF wsprintfA:PROC
EXTERNDEF CreateFileA:PROC
EXTERNDEF Sleep:PROC
EXTERNDEF GetLastError:PROC
EXTERNDEF CloseHandle:PROC
EXTERNDEF FlushFileBuffers:PROC

; =============================================================================
; Win32 constants not in RawrXD_Common.inc
; =============================================================================
STD_OUTPUT_HANDLE        equ -11
FILE_CURRENT             equ 1

; =============================================================================
; NT Status Codes (supplement RawrXD_Common.inc)
; =============================================================================
STATUS_TIMEOUT               equ 00000102h
STATUS_DEVICE_DATA_ERROR     equ 0C000009Ch

; =============================================================================
; IOCTLs
; =============================================================================
IOCTL_SCSI_PASS_THROUGH_DIRECT equ 04D014h
IOCTL_STORAGE_QUERY_PROPERTY   equ 02D1400h
FSCTL_SET_SPARSE               equ 000900C4h

; =============================================================================
; SCSI Commands
; =============================================================================
SCSI_READ10              equ 28h
SCSI_READ12              equ 0A8h
SCSI_INQUIRY             equ 12h
SCSI_REQUEST_SENSE       equ 03h
SCSI_MODE_SENSE          equ 1Ah
SCSI_READ_CAPACITY       equ 25h
; WD Vendor Specific
WD_SECURITY_PROTOCOL     equ 0A1h     ; Vendor specific key extraction
WD_JMS567_EEPROM_READ    equ 0E0h     ; JMicron bridge EEPROM dump

; =============================================================================
; SCSI Data Direction
; =============================================================================
SCSI_IOCTL_DATA_OUT      equ 0
SCSI_IOCTL_DATA_IN       equ 1
SCSI_IOCTL_DATA_UNSPEC   equ 2

; =============================================================================
; File I/O constants (supplement RawrXD_Common.inc)
; =============================================================================
FILE_SHARE_WRITE             equ 2
FILE_FLAG_NO_BUFFERING       equ 20000000h
FILE_FLAG_WRITE_THROUGH      equ 80000000h
FILE_FLAG_SEQUENTIAL_SCAN    equ 08000000h
FILE_ATTRIBUTE_NORMAL        equ 80h

; =============================================================================
; Error codes
; =============================================================================
ERROR_SEM_TIMEOUT        equ 121
ERROR_GEN_FAILURE        equ 31

; =============================================================================
; Config Constants
; =============================================================================
MAX_RETRIES              equ 100
TIMEOUT_MS               equ 2000
SECTOR_SIZE              equ 4096     ; USB 3.0 usually 4K
BUFFER_SIZE              equ 1048576  ; 1MB transfer chunks
MAX_BAD_SECTORS          equ 65536    ; Max entries in bad map
CHECKPOINT_INTERVAL      equ 1000     ; Save progress every N sectors

; =============================================================================
; Bridge type enum
; =============================================================================
BRIDGE_UNKNOWN           equ 0
BRIDGE_JMS567            equ 1
BRIDGE_NS1066            equ 2

; =============================================================================
; SCSI_PASS_THROUGH_DIRECT (x64 layout, matches Windows SDK)
; Total size: 56 bytes (without sense data appended)
; NOTE: ml64 struct layout differs from SDK due to packing.
; We use a flat byte buffer and access via offsets for correctness.
; =============================================================================
SPTD_LENGTH              equ 0       ; WORD   (2)
SPTD_SCSISTATUS          equ 2       ; BYTE   (1)
SPTD_PATHID              equ 3       ; BYTE   (1)
SPTD_TARGETID            equ 4       ; BYTE   (1)
SPTD_LUN                 equ 5       ; BYTE   (1)
SPTD_CDBLENGTH           equ 6       ; BYTE   (1)
SPTD_SENSEINFOLENGTH     equ 7       ; BYTE   (1)
SPTD_DATAIN              equ 8       ; BYTE   (1)  0=None,1=In,2=Out
; padding 3 bytes to align DataTransferLength at +12
SPTD_DATATRANSFERLENGTH  equ 12      ; DWORD  (4)
SPTD_TIMEOUTVALUE        equ 16      ; DWORD  (4)
; padding 4 bytes to align DataBuffer at +24
SPTD_DATABUFFER          equ 24      ; QWORD  (8)
SPTD_SENSEINFOOFFSET     equ 32      ; DWORD  (4)
; padding 4 bytes to align Cdb at +40  (NOTE: on x64 it's actually at offset 36+padding)
SPTD_CDB                 equ 36      ; BYTE[16]
SPTD_TOTAL_SIZE          equ 56      ; 56 bytes total on x64

; We append sense buffer right after SPTD
SENSE_OFFSET             equ SPTD_TOTAL_SIZE
SENSE_SIZE               equ 32
SPTD_WITH_SENSE          equ SPTD_TOTAL_SIZE + SENSE_SIZE  ; 88 bytes

; =============================================================================
; DISK_RECOVERY_CONTEXT — Tracks the full recovery session
; =============================================================================
DISK_RECOVERY_CONTEXT STRUCT 8
    hSource              QWORD   ?   ; Source drive handle
    hTarget              QWORD   ?   ; Target image file handle
    hLog                 QWORD   ?   ; Log file handle
    hBadSectorMap        QWORD   ?   ; Bad sector map file handle
    TotalSectors         QWORD   ?   ; Drive capacity in sectors
    CurrentLBA           QWORD   ?   ; Resume position
    GoodSectors          QWORD   ?   ; Successful reads
    BadSectors           QWORD   ?   ; Failed reads
    BridgeType           DWORD   ?   ; BRIDGE_* enum
    _pad0                DWORD   ?   ; Alignment padding
    EncryptionKey        BYTE 32 dup(?) ; Extracted AES-256 key
    AbortSignal          BYTE    ?   ; Thread-safe abort flag
    KeyExtracted         BYTE    ?   ; 1 if key was successfully extracted
    _pad1                BYTE  6 dup(?) ; Pad to 8-byte boundary
DISK_RECOVERY_CONTEXT ENDS

; =============================================================================
; .data — Static strings and global context
; =============================================================================
.data

    ; Device path template (modified at offset 17 for drive number)
    szDevicePathBase     db "\\.\PhysicalDrive", 0, 0, 0, 0
    szTargetImage        db "D:\Recovery\WD_Rescue.bin", 0
    szLogFile            db "D:\Recovery\recovery.log", 0
    szBadMap             db "D:\Recovery\badsectors.map", 0
    szKeyFile            db "D:\Recovery\aes_key.bin", 0

    ; Console output templates
    szBanner             db 13,10
                         db "================================================",13,10
                         db "  RawrXD Disk Recovery Agent v1.0",13,10
                         db "  Hardware-level extraction for dying USB bridges",13,10
                         db "  (c) RawrXD Project - Zero dependency MASM64",13,10
                         db "================================================",13,10,0

    szScanning           db "[*] Scanning PhysicalDrive0-15 for dying WD devices...",13,10,0
    szFoundDrive         db "[+] Found candidate: PhysicalDrive",0
    szDriveNum           db "0",13,10,0    ; Filled dynamically
    szNoDevice           db "[-] No dying WD My Book device found.",13,10,0
    szOpening            db "[*] Opening device with SCSI passthrough...",13,10,0
    szOpenFail           db "[-] Failed to open device handle.",13,10,0
    szInitOk             db "[+] Recovery context initialized.",13,10,0
    szHammerStart        db "[*] Initiating SCSI hammer protocol...",13,10,0
    szKeyExtract         db "[*] Attempting hardware key extraction from bridge EEPROM...",13,10,0
    szKeySuccess         db "[+] AES-256 key extracted and saved!",13,10,0
    szKeyFail            db "[-] Key extraction failed (bridge unresponsive).",13,10,0
    szSectorOk           db "+",0          ; Single char for fast progress
    szSectorBad          db "X",0          ; Single char for bad sector
    szCheckpoint         db 13,10,"[*] Checkpoint: LBA ",0
    szStatHeader         db 13,10,"=== Recovery Statistics ===",13,10,0
    szStatTotal          db "  Processed:  ",0
    szStatGood           db "  Good:       ",0
    szStatBad            db "  Bad:        ",0
    szStatPct            db "  Progress:   ",0
    szPctSign            db "%%",13,10,0
    szNewLine            db 13,10,0
    szComplete           db 13,10,"[+] Recovery session complete.",13,10,0
    szInitError          db "[-] Initialization error.",13,10,0
    szBridgeJMS567       db "[+] Bridge identified: JMicron JMS567",13,10,0
    szBridgeNS1066       db "[+] Bridge identified: Norelsys NS1066",13,10,0
    szBridgeUnknown      db "[?] Bridge type unknown — generic SCSI mode.",13,10,0

    ; Formatting scratch buffer
    align 8
    FmtBuf               db 256 dup(0)

; =============================================================================
; .data? — Uninitialized (BSS) data
; =============================================================================
.data?

    ; Transfer buffer (page-alignment via align 16 — max for .data? segment)
    align 16
    TransferBuffer       db BUFFER_SIZE dup(?)

    ; Global recovery context
    align 8
    g_Context            DISK_RECOVERY_CONTEXT <>

    ; Console handle cache
    g_hStdOut            QWORD ?

; =============================================================================
; .code
; =============================================================================
.code

; =============================================================================
; ConsolePrint — Write a null-terminated string to stdout
; RCX = ptr to string
; Clobbers: RAX, RCX, RDX, R8, R9
; =============================================================================
ConsolePrint PROC
    push rbx
    push rsi
    sub  rsp, 40              ; Shadow + local (2 pushes + 40 = 56 ≡ 8+56=64 → 0 mod 16)

    mov  rsi, rcx             ; Save string ptr

    ; lstrlenA to get length
    ; rcx already has string
    call lstrlenA
    mov  rbx, rax             ; RBX = length

    test rbx, rbx
    jz   cp_done

    ; GetStdHandle(STD_OUTPUT_HANDLE)
    mov  ecx, STD_OUTPUT_HANDLE
    call GetStdHandle
    test rax, rax
    jz   cp_done

    ; WriteFile(hStdOut, pStr, len, &bytesWritten, NULL)
    mov  rcx, rax             ; hFile
    mov  rdx, rsi             ; lpBuffer
    mov  r8d, ebx             ; nNumberOfBytesToWrite
    lea  r9, [rsp+36]         ; lpNumberOfBytesWritten (inside shadow, not overlapping 5th arg)
    mov  qword ptr [rsp+32], 0 ; lpOverlapped = NULL (5th arg at correct position)
    call WriteFile

cp_done:
    add  rsp, 40
    pop  rsi
    pop  rbx
    ret
ConsolePrint ENDP

; =============================================================================
; PrintU64 — Print a QWORD as decimal to console
; RCX = value
; Clobbers: RAX, RCX, RDX, R8, R9
; =============================================================================
PrintU64 PROC
    push rbx
    push rsi
    push rdi
    sub  rsp, 48

    mov  rbx, rcx             ; Value to print

    ; Manual itoa (decimal): fill FmtBuf right-to-left
    lea  rdi, FmtBuf
    add  rdi, 30              ; End of scratch area
    mov  byte ptr [rdi], 0    ; Null terminator
    dec  rdi

    mov  rax, rbx
    test rax, rax
    jnz  pu64_loop
    mov  byte ptr [rdi], '0'
    dec  rdi
    jmp  pu64_print

pu64_loop:
    test rax, rax
    jz   pu64_print
    xor  edx, edx
    mov  rcx, 10
    div  rcx                  ; RAX = quotient, RDX = remainder
    add  dl, '0'
    mov  byte ptr [rdi], dl
    dec  rdi
    jmp  pu64_loop

pu64_print:
    inc  rdi                  ; Point to first digit
    mov  rcx, rdi
    call ConsolePrint

    add  rsp, 48
    pop  rdi
    pop  rsi
    pop  rbx
    ret
PrintU64 ENDP

; =============================================================================
; ScsiInquiryQuick — Fast INQUIRY with custom timeout
; RCX = hDevice, EDX = TimeoutMS
; Returns: RAX = 0 success, nonzero = GetLastError code
; Clobbers: all volatile regs
; =============================================================================
ScsiInquiryQuick PROC
    LOCAL sptd_buf[SPTD_WITH_SENSE]:BYTE
    LOCAL inquiryData[64]:BYTE
    LOCAL bytesRet:DWORD

    push rbx
    push rdi
    push r12                  ; R12 is non-volatile — must save

    mov  rbx, rcx             ; hDevice
    mov  r12d, edx            ; Timeout

    ; Zero SPTD buffer
    lea  rdi, sptd_buf
    mov  ecx, SPTD_WITH_SENSE
    xor  eax, eax
    rep  stosb

    ; Fill SPTD fields
    lea  rdi, sptd_buf
    mov  word ptr  [rdi+SPTD_LENGTH], SPTD_TOTAL_SIZE
    mov  byte ptr  [rdi+SPTD_CDBLENGTH], 6          ; INQUIRY CDB = 6 bytes
    mov  byte ptr  [rdi+SPTD_SENSEINFOLENGTH], SENSE_SIZE
    mov  byte ptr  [rdi+SPTD_DATAIN], SCSI_IOCTL_DATA_IN
    mov  dword ptr [rdi+SPTD_DATATRANSFERLENGTH], 36 ; Standard INQUIRY response
    mov  dword ptr [rdi+SPTD_TIMEOUTVALUE], r12d
    lea  rax, inquiryData
    mov  qword ptr [rdi+SPTD_DATABUFFER], rax
    mov  dword ptr [rdi+SPTD_SENSEINFOOFFSET], SENSE_OFFSET

    ; CDB: INQUIRY (12h, 0, 0, 0, 36, 0)
    mov  byte ptr  [rdi+SPTD_CDB+0], SCSI_INQUIRY
    mov  byte ptr  [rdi+SPTD_CDB+4], 36             ; Allocation length

    ; DeviceIoControl (8 params: 4 reg + 4 stack → need 64 bytes)
    sub  rsp, 64
    mov  rcx, rbx                                    ; hDevice
    mov  edx, IOCTL_SCSI_PASS_THROUGH_DIRECT         ; dwIoControlCode
    lea  r8, sptd_buf                                ; lpInBuffer
    mov  r9d, SPTD_WITH_SENSE                        ; nInBufferSize
    lea  rax, sptd_buf
    mov  qword ptr [rsp+32], rax                     ; lpOutBuffer
    mov  qword ptr [rsp+40], SPTD_WITH_SENSE         ; nOutBufferSize
    lea  rax, bytesRet
    mov  qword ptr [rsp+48], rax                     ; lpBytesReturned
    mov  qword ptr [rsp+56], 0                       ; lpOverlapped
    call DeviceIoControl
    add  rsp, 64

    test eax, eax
    jnz  inq_ok

    call GetLastError
    jmp  inq_exit

inq_ok:
    xor  eax, eax           ; Success

inq_exit:
    pop  r12
    pop  rdi
    pop  rbx
    ret
ScsiInquiryQuick ENDP

; =============================================================================
; WdPingBridge — Identify WD bridge controller type via vendor SCSI commands
; RCX = hDevice
; Returns: EAX = BRIDGE_* type (0=None, 1=JMS567, 2=NS1066)
; =============================================================================
WdPingBridge PROC
    LOCAL sptd_buf[SPTD_WITH_SENSE]:BYTE
    LOCAL resp[64]:BYTE
    LOCAL bytesRet:DWORD

    push rbx
    push rdi

    mov  rbx, rcx

    ; === Try JMS567 vendor command ===
    lea  rdi, sptd_buf
    mov  ecx, SPTD_WITH_SENSE
    xor  eax, eax
    rep  stosb

    lea  rdi, sptd_buf
    mov  word ptr  [rdi+SPTD_LENGTH], SPTD_TOTAL_SIZE
    mov  byte ptr  [rdi+SPTD_CDBLENGTH], 10
    mov  byte ptr  [rdi+SPTD_SENSEINFOLENGTH], SENSE_SIZE
    mov  byte ptr  [rdi+SPTD_DATAIN], SCSI_IOCTL_DATA_IN
    mov  dword ptr [rdi+SPTD_DATATRANSFERLENGTH], 64
    mov  dword ptr [rdi+SPTD_TIMEOUTVALUE], 1000     ; 1s timeout
    lea  rax, resp
    mov  qword ptr [rdi+SPTD_DATABUFFER], rax
    mov  dword ptr [rdi+SPTD_SENSEINFOOFFSET], SENSE_OFFSET

    ; Vendor CDB: E0 'J' 'M' 'S' '5' ...
    mov  byte ptr  [rdi+SPTD_CDB+0], WD_JMS567_EEPROM_READ
    mov  byte ptr  [rdi+SPTD_CDB+1], 'J'
    mov  byte ptr  [rdi+SPTD_CDB+2], 'M'
    mov  byte ptr  [rdi+SPTD_CDB+3], 'S'
    mov  byte ptr  [rdi+SPTD_CDB+4], '5'

    sub  rsp, 64
    mov  rcx, rbx
    mov  edx, IOCTL_SCSI_PASS_THROUGH_DIRECT
    lea  r8, sptd_buf
    mov  r9d, SPTD_WITH_SENSE
    lea  rax, sptd_buf
    mov  qword ptr [rsp+32], rax
    mov  qword ptr [rsp+40], SPTD_WITH_SENSE
    lea  rax, bytesRet
    mov  qword ptr [rsp+48], rax
    mov  qword ptr [rsp+56], 0
    call DeviceIoControl
    add  rsp, 64

    test eax, eax
    jz   try_ns1066

    mov  eax, BRIDGE_JMS567
    jmp  ping_exit

try_ns1066:
    ; === Try NS1066 vendor command ===
    lea  rdi, sptd_buf
    mov  ecx, SPTD_WITH_SENSE
    xor  eax, eax
    rep  stosb

    lea  rdi, sptd_buf
    mov  word ptr  [rdi+SPTD_LENGTH], SPTD_TOTAL_SIZE
    mov  byte ptr  [rdi+SPTD_CDBLENGTH], 10
    mov  byte ptr  [rdi+SPTD_SENSEINFOLENGTH], SENSE_SIZE
    mov  byte ptr  [rdi+SPTD_DATAIN], SCSI_IOCTL_DATA_IN
    mov  dword ptr [rdi+SPTD_DATATRANSFERLENGTH], 64
    mov  dword ptr [rdi+SPTD_TIMEOUTVALUE], 1000
    lea  rax, resp
    mov  qword ptr [rdi+SPTD_DATABUFFER], rax
    mov  dword ptr [rdi+SPTD_SENSEINFOOFFSET], SENSE_OFFSET

    mov  byte ptr  [rdi+SPTD_CDB+0], WD_JMS567_EEPROM_READ
    mov  byte ptr  [rdi+SPTD_CDB+1], 'N'
    mov  byte ptr  [rdi+SPTD_CDB+2], 'S'
    mov  byte ptr  [rdi+SPTD_CDB+3], '1'
    mov  byte ptr  [rdi+SPTD_CDB+4], '0'

    sub  rsp, 64
    mov  rcx, rbx
    mov  edx, IOCTL_SCSI_PASS_THROUGH_DIRECT
    lea  r8, sptd_buf
    mov  r9d, SPTD_WITH_SENSE
    lea  rax, sptd_buf
    mov  qword ptr [rsp+32], rax
    mov  qword ptr [rsp+40], SPTD_WITH_SENSE
    lea  rax, bytesRet
    mov  qword ptr [rsp+48], rax
    mov  qword ptr [rsp+56], 0
    call DeviceIoControl
    add  rsp, 64

    test eax, eax
    jz   no_bridge

    mov  eax, BRIDGE_NS1066
    jmp  ping_exit

no_bridge:
    xor  eax, eax

ping_exit:
    pop  rdi
    pop  rbx
    ret
WdPingBridge ENDP

; =============================================================================
; FindDyingDrive — Scans PhysicalDrive0-15 for WD signature
; Returns: EAX = drive number (0-15), or -1 if not found
; =============================================================================
FindDyingDrive PROC
    LOCAL driveNum:DWORD
    LOCAL hDevice:QWORD
    LOCAL devPath[32]:BYTE

    push rbx
    push rsi
    push rdi
    push r12
    sub  rsp, 64              ; 4 pushes (32) + 64 = 96 → 0 mod 16; room for 7-param CreateFileA

    mov  driveNum, 0

scan_loop:
    cmp  driveNum, 15
    jg   not_found

    ; Build path: \\.\PhysicalDriveN
    lea  rdi, devPath
    lea  rsi, szDevicePathBase
    mov  ecx, 17               ; Length of "\\.\PhysicalDrive"
    rep  movsb
    mov  eax, driveNum
    add  al, '0'
    mov  byte ptr [rdi], al
    mov  byte ptr [rdi+1], 0

    ; CreateFileA — NO_BUFFERING prevents Windows metadata probing
    lea  rcx, devPath
    mov  edx, GENERIC_READ
    mov  r8d, FILE_SHARE_READ or FILE_SHARE_WRITE
    xor  r9d, r9d             ; lpSecurityAttributes = NULL
    mov  qword ptr [rsp+32], OPEN_EXISTING
    mov  qword ptr [rsp+40], FILE_FLAG_NO_BUFFERING or FILE_FLAG_WRITE_THROUGH
    mov  qword ptr [rsp+48], 0
    call CreateFileA

    cmp  rax, INVALID_HANDLE_VALUE
    je   next_drive

    mov  hDevice, rax

    ; Quick SCSI INQUIRY with 500ms timeout
    mov  rcx, rax
    mov  edx, 500
    call ScsiInquiryQuick

    test eax, eax
    jz   inquiry_ok

    ; Inquiry failed — if timeout, might be our dying drive
    cmp  eax, ERROR_SEM_TIMEOUT
    jne  close_next

    ; Timeout → try vendor ping to confirm WD bridge
    mov  rcx, hDevice
    call WdPingBridge
    test eax, eax
    jnz  found_it

    jmp  close_next

inquiry_ok:
    ; Inquiry succeeded — still check if it's a WD bridge
    mov  rcx, hDevice
    call WdPingBridge
    test eax, eax
    jnz  found_it

close_next:
    mov  rcx, hDevice
    call CloseHandle

next_drive:
    inc  driveNum
    jmp  scan_loop

found_it:
    ; EAX already has bridge type — save it
    mov  g_Context.BridgeType, eax

    mov  rcx, hDevice
    call CloseHandle

    mov  eax, driveNum
    jmp  find_exit

not_found:
    mov  eax, -1

find_exit:
    add  rsp, 64
    pop  r12
    pop  rdi
    pop  rsi
    pop  rbx
    ret
FindDyingDrive ENDP

; =============================================================================
; ExtractEncryptionKey — Dump AES-256 key from bridge EEPROM
; RCX = ptr to DISK_RECOVERY_CONTEXT
; Returns: RAX = 1 success (key in context), 0 = fail
; =============================================================================
ExtractEncryptionKey PROC
    LOCAL sptd_buf[SPTD_WITH_SENSE]:BYTE
    LOCAL keyBuf[512]:BYTE
    LOCAL bytesRet:DWORD

    push rbx
    push rsi                  ; RSI used by rep movsb — must save
    push rdi

    mov  rbx, rcx

    ; Only works if bridge type is known
    cmp  (DISK_RECOVERY_CONTEXT ptr [rbx]).BridgeType, BRIDGE_UNKNOWN
    je   ek_fail

    ; Zero SPTD
    lea  rdi, sptd_buf
    mov  ecx, SPTD_WITH_SENSE
    xor  eax, eax
    rep  stosb

    ; Fill SPTD for SECURITY PROTOCOL IN (A1h)
    lea  rdi, sptd_buf
    mov  word ptr  [rdi+SPTD_LENGTH], SPTD_TOTAL_SIZE
    mov  byte ptr  [rdi+SPTD_CDBLENGTH], 12         ; 12-byte CDB
    mov  byte ptr  [rdi+SPTD_SENSEINFOLENGTH], SENSE_SIZE
    mov  byte ptr  [rdi+SPTD_DATAIN], SCSI_IOCTL_DATA_IN
    mov  dword ptr [rdi+SPTD_DATATRANSFERLENGTH], 512
    mov  dword ptr [rdi+SPTD_TIMEOUTVALUE], 5000     ; 5s for crypto op
    lea  rax, keyBuf
    mov  qword ptr [rdi+SPTD_DATABUFFER], rax
    mov  dword ptr [rdi+SPTD_SENSEINFOOFFSET], SENSE_OFFSET

    ; CDB: SECURITY PROTOCOL IN
    ;   [0] = A1h (opcode)
    ;   [1] = 00h (security protocol = vendor)
    ;   [2] = 01h (protocol specific = key extraction)
    ;   [6-9] = allocation length (512 = 0x200)
    mov  byte ptr  [rdi+SPTD_CDB+0], WD_SECURITY_PROTOCOL
    mov  byte ptr  [rdi+SPTD_CDB+1], 0
    mov  byte ptr  [rdi+SPTD_CDB+2], 01h
    mov  byte ptr  [rdi+SPTD_CDB+6], 0
    mov  byte ptr  [rdi+SPTD_CDB+7], 0
    mov  byte ptr  [rdi+SPTD_CDB+8], 02h            ; 0x200 = 512
    mov  byte ptr  [rdi+SPTD_CDB+9], 0

    ; DeviceIoControl
    sub  rsp, 64
    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).hSource
    mov  edx, IOCTL_SCSI_PASS_THROUGH_DIRECT
    lea  r8, sptd_buf
    mov  r9d, SPTD_WITH_SENSE
    lea  rax, sptd_buf
    mov  qword ptr [rsp+32], rax
    mov  qword ptr [rsp+40], SPTD_WITH_SENSE
    lea  rax, bytesRet
    mov  qword ptr [rsp+48], rax
    mov  qword ptr [rsp+56], 0
    call DeviceIoControl
    add  rsp, 64

    test eax, eax
    jz   ek_fail

    ; Copy first 32 bytes of response as AES-256 key
    lea  rsi, keyBuf
    lea  rdi, (DISK_RECOVERY_CONTEXT ptr [rbx]).EncryptionKey
    mov  ecx, 32
    rep  movsb

    mov  (DISK_RECOVERY_CONTEXT ptr [rbx]).KeyExtracted, 1

    ; Save key to separate file
    mov  rcx, rbx
    call SaveEncryptionKey

    mov  eax, 1
    jmp  ek_exit

ek_fail:
    xor  eax, eax

ek_exit:
    pop  rdi
    pop  rsi
    pop  rbx
    ret
ExtractEncryptionKey ENDP

; =============================================================================
; SaveEncryptionKey — Write extracted key to D:\Recovery\aes_key.bin
; RCX = ptr to DISK_RECOVERY_CONTEXT
; =============================================================================
SaveEncryptionKey PROC
    LOCAL bytesWritten:DWORD

    push rbx
    push r12                  ; R12 is non-volatile — must save
    sub  rsp, 56              ; 2 pushes (16) + LOCAL frame + 56 → aligned; room for 7-param CreateFileA

    mov  rbx, rcx

    ; CreateFileA for key file
    lea  rcx, szKeyFile
    mov  edx, GENERIC_WRITE
    mov  r8d, FILE_SHARE_READ
    xor  r9d, r9d
    mov  qword ptr [rsp+32], CREATE_ALWAYS
    mov  qword ptr [rsp+40], FILE_ATTRIBUTE_NORMAL
    mov  qword ptr [rsp+48], 0
    call CreateFileA

    cmp  rax, INVALID_HANDLE_VALUE
    je   sk_done

    mov  r12, rax             ; hFile

    ; WriteFile(hFile, key, 32, &bytesWritten, NULL)
    mov  rcx, r12
    lea  rdx, (DISK_RECOVERY_CONTEXT ptr [rbx]).EncryptionKey
    mov  r8d, 32
    lea  r9, bytesWritten
    mov  qword ptr [rsp+32], 0
    call WriteFile

    mov  rcx, r12
    call FlushFileBuffers

    mov  rcx, r12
    call CloseHandle

sk_done:
    add  rsp, 56
    pop  r12
    pop  rbx
    ret
SaveEncryptionKey ENDP

; =============================================================================
; HammerReadSector — High-reliability sector read with retry + sense decoding
; RCX = ptr to Context
; RDX = LBA (QWORD)
; R8  = ptr to output buffer
; Returns: RAX = 1 success, 0 = permanent failure (logged to bad map)
; =============================================================================
HammerReadSector PROC
    LOCAL sptd_buf[SPTD_WITH_SENSE]:BYTE
    LOCAL bytesRet:DWORD
    LOCAL retryCount:DWORD

    push rbx
    push rsi
    push rdi
    push r12
    push r13
    push r14
    sub  rsp, 80              ; 6 pushes (48) + 80 = 128 → 0 mod 16; room for 8-param DeviceIoControl

    mov  rbx, rcx             ; Context ptr
    mov  r12, rdx             ; LBA
    mov  r13, r8              ; Buffer
    mov  retryCount, 0

retry_read:
    mov  eax, retryCount
    cmp  eax, MAX_RETRIES
    jge  sector_dead

    ; Zero SPTD
    lea  rdi, sptd_buf
    mov  ecx, SPTD_WITH_SENSE
    xor  eax, eax
    rep  stosb

    ; Fill SPTD for READ(10)
    lea  rdi, sptd_buf
    mov  word ptr  [rdi+SPTD_LENGTH], SPTD_TOTAL_SIZE
    mov  byte ptr  [rdi+SPTD_CDBLENGTH], 10
    mov  byte ptr  [rdi+SPTD_SENSEINFOLENGTH], SENSE_SIZE
    mov  byte ptr  [rdi+SPTD_DATAIN], SCSI_IOCTL_DATA_IN
    mov  dword ptr [rdi+SPTD_DATATRANSFERLENGTH], SECTOR_SIZE
    mov  dword ptr [rdi+SPTD_TIMEOUTVALUE], TIMEOUT_MS
    mov  qword ptr [rdi+SPTD_DATABUFFER], r13
    mov  dword ptr [rdi+SPTD_SENSEINFOOFFSET], SENSE_OFFSET

    ; CDB: READ(10) = 28h, LBA[4 bytes big-endian], 0, TransferLen[2 bytes BE]
    mov  byte ptr  [rdi+SPTD_CDB+0], SCSI_READ10

    ; Write LBA in big-endian at CDB offsets 2-5
    mov  eax, r12d             ; Lower 32 bits of LBA
    bswap eax
    mov  dword ptr [rdi+SPTD_CDB+2], eax

    ; Transfer length = 1 sector, big-endian (0x0001)
    mov  byte ptr  [rdi+SPTD_CDB+7], 0
    mov  byte ptr  [rdi+SPTD_CDB+8], 1

    ; DeviceIoControl
    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).hSource
    mov  edx, IOCTL_SCSI_PASS_THROUGH_DIRECT
    lea  r8, sptd_buf
    mov  r9d, SPTD_WITH_SENSE
    lea  rax, sptd_buf
    mov  qword ptr [rsp+32], rax
    mov  qword ptr [rsp+40], SPTD_WITH_SENSE
    lea  rax, bytesRet
    mov  qword ptr [rsp+48], rax
    mov  qword ptr [rsp+56], 0
    call DeviceIoControl

    test eax, eax
    jnz  hr_check_scsi_status

    ; Win32 error — check type
    call GetLastError

    cmp  eax, ERROR_SEM_TIMEOUT
    je   hr_retry

    cmp  eax, ERROR_GEN_FAILURE
    je   hr_check_sense

    ; Unknown error — retry anyway
    jmp  hr_retry

hr_check_scsi_status:
    ; DeviceIoControl succeeded — check SCSI status byte
    lea  rdi, sptd_buf
    movzx eax, byte ptr [rdi+SPTD_SCSISTATUS]
    test al, al
    jz   read_success          ; SCSI GOOD status = 0

    cmp  al, 02h               ; CHECK CONDITION
    je   hr_check_sense

    ; Other SCSI status — retry
    jmp  hr_retry

hr_check_sense:
    ; Decode sense data: SenseKey at sense[2] bits 0-3
    lea  rdi, sptd_buf
    add  rdi, SENSE_OFFSET
    movzx eax, byte ptr [rdi+2]
    and  al, 0Fh

    cmp  al, 03h               ; MEDIUM ERROR — permanent
    je   sector_dead

    cmp  al, 05h               ; ILLEGAL REQUEST — permanent
    je   sector_dead

    ; Hardware error (04h) or other — may recover with retry
    jmp  hr_retry

hr_retry:
    inc  retryCount

    ; Exponential backoff: Sleep(10 * retryCount)
    mov  ecx, retryCount      ; Read full DWORD (was word ptr — fragile)
    imul ecx, ecx, 10
    call Sleep

    jmp  retry_read

sector_dead:
    ; Log to bad sector map
    mov  rcx, rbx
    mov  rdx, r12
    call LogBadSector

    xor  eax, eax              ; Return 0 = fail
    jmp  hr_exit

read_success:
    mov  eax, 1                ; Return 1 = success

hr_exit:
    add  rsp, 80
    pop  r14
    pop  r13
    pop  r12
    pop  rdi
    pop  rsi
    pop  rbx
    ret
HammerReadSector ENDP

; =============================================================================
; LogBadSector — Append LBA to bad sector map (binary: 8 bytes per entry)
; RCX = Context ptr, RDX = LBA
; =============================================================================
LogBadSector PROC
    LOCAL bytesWritten:DWORD
    LOCAL lbaValue:QWORD

    push rbx
    sub  rsp, 40              ; 1 push (8) + LOCAL frame + 40 → aligned

    mov  rbx, rcx
    mov  lbaValue, rdx

    ; WriteFile(hBadSectorMap, &lbaValue, 8, &bytesWritten, NULL)
    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).hBadSectorMap
    lea  rdx, lbaValue
    mov  r8d, 8
    lea  r9, bytesWritten
    mov  qword ptr [rsp+32], 0
    call WriteFile

    inc  (DISK_RECOVERY_CONTEXT ptr [rbx]).BadSectors

    add  rsp, 40
    pop  rbx
    ret
LogBadSector ENDP

; =============================================================================
; SaveCheckpoint — Write resume position to log file
; RCX = Context ptr
; =============================================================================
SaveCheckpoint PROC
    LOCAL bytesWritten:DWORD
    LOCAL liZero:QWORD

    push rbx
    sub  rsp, 40              ; 1 push (8) + LOCAL frame + 40 → aligned

    mov  rbx, rcx

    ; Print checkpoint message
    lea  rcx, szCheckpoint
    call ConsolePrint
    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).CurrentLBA
    call PrintU64
    lea  rcx, szNewLine
    call ConsolePrint

    ; Seek log to beginning: SetFilePointerEx(hLog, 0, NULL, FILE_BEGIN)
    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).hLog
    xor  edx, edx             ; liDistanceToMove (low)
    xor  r8d, r8d             ; lpNewFilePointer = NULL
    xor  r9d, r9d             ; FILE_BEGIN = 0
    call SetFilePointerEx

    ; Write LBA as 8-byte binary checkpoint (simple + resumable)
    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).hLog
    lea  rdx, (DISK_RECOVERY_CONTEXT ptr [rbx]).CurrentLBA
    mov  r8d, 8
    lea  r9, bytesWritten
    mov  qword ptr [rsp+32], 0
    call WriteFile

    ; Flush to ensure it survives a crash
    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).hLog
    call FlushFileBuffers

    add  rsp, 40
    pop  rbx
    ret
SaveCheckpoint ENDP

; =============================================================================
; DisplayProgress — Print recovery statistics
; RCX = Context ptr
; =============================================================================
DisplayProgress PROC
    push rbx
    sub  rsp, 32

    mov  rbx, rcx

    lea  rcx, szStatHeader
    call ConsolePrint

    lea  rcx, szStatTotal
    call ConsolePrint
    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).CurrentLBA
    call PrintU64
    lea  rcx, szNewLine
    call ConsolePrint

    lea  rcx, szStatGood
    call ConsolePrint
    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).GoodSectors
    call PrintU64
    lea  rcx, szNewLine
    call ConsolePrint

    lea  rcx, szStatBad
    call ConsolePrint
    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).BadSectors
    call PrintU64
    lea  rcx, szNewLine
    call ConsolePrint

    ; Percentage = (CurrentLBA * 100) / TotalSectors
    lea  rcx, szStatPct
    call ConsolePrint

    mov  rax, (DISK_RECOVERY_CONTEXT ptr [rbx]).CurrentLBA
    mov  rcx, 100
    mul  rcx                   ; RDX:RAX = CurrentLBA * 100
    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).TotalSectors
    test rcx, rcx
    jz   dp_skip_pct
    div  rcx                   ; RAX = percentage
    mov  rcx, rax
    call PrintU64

dp_skip_pct:
    lea  rcx, szPctSign
    call ConsolePrint

    add  rsp, 32
    pop  rbx
    ret
DisplayProgress ENDP

; =============================================================================
; RecoveryWorker — Main imaging loop with resume + checkpoint
; RCX = ptr to DISK_RECOVERY_CONTEXT
; =============================================================================
RecoveryWorker PROC
    push rbx
    push rsi
    push rdi
    sub  rsp, 48

    mov  rbx, rcx
    mov  rsi, (DISK_RECOVERY_CONTEXT ptr [rbx]).CurrentLBA ; Resume LBA

main_loop:
    ; Check abort signal (thread-safe volatile read)
    movzx eax, (DISK_RECOVERY_CONTEXT ptr [rbx]).AbortSignal
    test al, al
    jnz  worker_done

    ; Check if we've exceeded drive capacity
    cmp  rsi, (DISK_RECOVERY_CONTEXT ptr [rbx]).TotalSectors
    jge  worker_done

    ; Hammer read this sector
    mov  rcx, rbx
    mov  rdx, rsi
    lea  r8, TransferBuffer
    call HammerReadSector

    test eax, eax
    jz   rw_bad_sector

    ; Success — write sector to image file
    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).hTarget
    lea  rdx, TransferBuffer
    mov  r8d, SECTOR_SIZE
    lea  r9, [rsp+36]         ; &bytesWritten (inside shadow, not overlapping 5th arg)
    mov  qword ptr [rsp+32], 0 ; lpOverlapped = NULL (5th arg at correct position)
    call WriteFile

    inc  (DISK_RECOVERY_CONTEXT ptr [rbx]).GoodSectors

    ; Print inline progress dot
    lea  rcx, szSectorOk
    call ConsolePrint
    jmp  rw_next

rw_bad_sector:
    ; Seek target forward to leave a hole (sparse-file-friendly)
    ; SetFilePointerEx(hTarget, SECTOR_SIZE, NULL, FILE_CURRENT)
    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).hTarget
    mov  edx, SECTOR_SIZE      ; liDistanceToMove
    xor  r8d, r8d              ; lpNewFilePointer = NULL
    mov  r9d, FILE_CURRENT     ; dwMoveMethod
    call SetFilePointerEx

    ; Print bad sector marker
    lea  rcx, szSectorBad
    call ConsolePrint

rw_next:
    inc  rsi
    mov  (DISK_RECOVERY_CONTEXT ptr [rbx]).CurrentLBA, rsi

    ; Checkpoint every CHECKPOINT_INTERVAL sectors
    mov  rax, rsi
    xor  edx, edx
    mov  ecx, CHECKPOINT_INTERVAL
    div  rcx
    test edx, edx
    jnz  main_loop

    ; Save checkpoint + display stats
    mov  rcx, rbx
    call SaveCheckpoint
    mov  rcx, rbx
    call DisplayProgress

    jmp  main_loop

worker_done:
    ; Final checkpoint
    mov  rcx, rbx
    call SaveCheckpoint

    add  rsp, 48
    pop  rdi
    pop  rsi
    pop  rbx
    ret
RecoveryWorker ENDP

; =============================================================================
; SetSparseFile — Mark a file handle as sparse via FSCTL_SET_SPARSE
; RCX = hFile
; =============================================================================
SetSparseFile PROC
    LOCAL bytesRet:DWORD

    sub  rsp, 64

    ; DeviceIoControl(hFile, FSCTL_SET_SPARSE, NULL, 0, NULL, 0, &ret, NULL)
    ; rcx = hFile (already set)
    mov  edx, FSCTL_SET_SPARSE
    xor  r8d, r8d             ; lpInBuffer = NULL
    xor  r9d, r9d             ; nInBufferSize = 0
    mov  qword ptr [rsp+32], 0 ; lpOutBuffer
    mov  dword ptr [rsp+40], 0 ; nOutBufferSize
    lea  rax, bytesRet
    mov  qword ptr [rsp+48], rax
    mov  qword ptr [rsp+56], 0
    call DeviceIoControl

    add  rsp, 64
    ret
SetSparseFile ENDP

; =============================================================================
; InitializeRecoveryContext — Open device, create output files
; ECX = Drive number (0-15)
; Returns: RAX = ptr to DISK_RECOVERY_CONTEXT, or 0 on failure
; =============================================================================
InitializeRecoveryContext PROC
    LOCAL driveNumSave:DWORD
    LOCAL devPath[32]:BYTE
    LOCAL bytesRead:DWORD

    push rbx
    push rsi
    push rdi
    push r12
    sub  rsp, 64

    mov  driveNumSave, ecx

    ; Zero the global context
    lea  rdi, g_Context
    mov  ecx, sizeof DISK_RECOVERY_CONTEXT
    xor  eax, eax
    rep  stosb

    ; Build device path
    lea  rdi, devPath
    lea  rsi, szDevicePathBase
    mov  ecx, 17
    rep  movsb
    mov  eax, driveNumSave
    add  al, '0'
    mov  byte ptr [rdi], al
    mov  byte ptr [rdi+1], 0

    ; Open source drive with extreme flags
    lea  rcx, devPath
    mov  edx, GENERIC_READ or GENERIC_WRITE
    mov  r8d, FILE_SHARE_READ or FILE_SHARE_WRITE
    xor  r9d, r9d
    mov  qword ptr [rsp+32], OPEN_EXISTING
    mov  qword ptr [rsp+40], FILE_FLAG_NO_BUFFERING or FILE_FLAG_WRITE_THROUGH
    mov  qword ptr [rsp+48], 0
    call CreateFileA

    cmp  rax, INVALID_HANDLE_VALUE
    je   ic_fail

    mov  g_Context.hSource, rax

    ; Create target image file
    lea  rcx, szTargetImage
    mov  edx, GENERIC_WRITE
    mov  r8d, FILE_SHARE_READ
    xor  r9d, r9d
    mov  qword ptr [rsp+32], CREATE_ALWAYS
    mov  qword ptr [rsp+40], FILE_FLAG_NO_BUFFERING or FILE_FLAG_WRITE_THROUGH or FILE_FLAG_SEQUENTIAL_SCAN
    mov  qword ptr [rsp+48], 0
    call CreateFileA

    cmp  rax, INVALID_HANDLE_VALUE
    je   ic_fail

    mov  g_Context.hTarget, rax

    ; Mark target as sparse file for bad sector holes
    mov  rcx, rax
    call SetSparseFile

    ; Create log file (resume checkpoint)
    lea  rcx, szLogFile
    mov  edx, GENERIC_READ or GENERIC_WRITE
    mov  r8d, FILE_SHARE_READ
    xor  r9d, r9d
    mov  qword ptr [rsp+32], OPEN_EXISTING         ; Try to open existing (resume)
    mov  qword ptr [rsp+40], FILE_ATTRIBUTE_NORMAL
    mov  qword ptr [rsp+48], 0
    call CreateFileA

    cmp  rax, INVALID_HANDLE_VALUE
    je   ic_create_log

    ; Existing log found — try to read resume LBA
    mov  r12, rax
    mov  rcx, rax
    lea  rdx, g_Context.CurrentLBA
    mov  r8d, 8
    lea  r9, bytesRead
    mov  qword ptr [rsp+32], 0
    call ReadFile

    test eax, eax
    jz   ic_reset_log
    cmp  bytesRead, 8
    jne  ic_reset_log

    ; Resume position loaded!
    mov  g_Context.hLog, r12
    jmp  ic_log_done

ic_reset_log:
    mov  rcx, r12
    call CloseHandle

ic_create_log:
    ; Create fresh log
    lea  rcx, szLogFile
    mov  edx, GENERIC_READ or GENERIC_WRITE
    mov  r8d, FILE_SHARE_READ
    xor  r9d, r9d
    mov  qword ptr [rsp+32], CREATE_ALWAYS
    mov  qword ptr [rsp+40], FILE_ATTRIBUTE_NORMAL
    mov  qword ptr [rsp+48], 0
    call CreateFileA

    mov  g_Context.hLog, rax
    mov  g_Context.CurrentLBA, 0

ic_log_done:
    ; Create bad sector map
    lea  rcx, szBadMap
    mov  edx, GENERIC_WRITE
    mov  r8d, FILE_SHARE_READ
    xor  r9d, r9d
    mov  qword ptr [rsp+32], CREATE_ALWAYS
    mov  qword ptr [rsp+40], FILE_ATTRIBUTE_NORMAL
    mov  qword ptr [rsp+48], 0
    call CreateFileA

    mov  g_Context.hBadSectorMap, rax

    ; Default capacity: 2TB / 4096 = 488,281,250 sectors
    ; The RecoveryWorker will stop at this or at abort signal
    mov  g_Context.TotalSectors, 488281250

    ; Report bridge type
    mov  eax, g_Context.BridgeType
    cmp  eax, BRIDGE_JMS567
    je   ic_report_jms
    cmp  eax, BRIDGE_NS1066
    je   ic_report_ns
    lea  rcx, szBridgeUnknown
    call ConsolePrint
    jmp  ic_report_done
ic_report_jms:
    lea  rcx, szBridgeJMS567
    call ConsolePrint
    jmp  ic_report_done
ic_report_ns:
    lea  rcx, szBridgeNS1066
    call ConsolePrint
ic_report_done:

    lea  rcx, szInitOk
    call ConsolePrint

    lea  rax, g_Context
    jmp  ic_exit

ic_fail:
    lea  rcx, szOpenFail
    call ConsolePrint
    xor  eax, eax

ic_exit:
    add  rsp, 64
    pop  r12
    pop  rdi
    pop  rsi
    pop  rbx
    ret
InitializeRecoveryContext ENDP

; =============================================================================
; CleanupRecovery — Close all handles
; RCX = ptr to Context
; =============================================================================
CleanupRecovery PROC
    push rbx
    sub  rsp, 32

    mov  rbx, rcx

    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).hSource
    test rcx, rcx
    jz   cr_skip_src
    call CloseHandle
cr_skip_src:

    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).hTarget
    test rcx, rcx
    jz   cr_skip_tgt
    call CloseHandle
cr_skip_tgt:

    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).hLog
    test rcx, rcx
    jz   cr_skip_log
    call CloseHandle
cr_skip_log:

    mov  rcx, (DISK_RECOVERY_CONTEXT ptr [rbx]).hBadSectorMap
    test rcx, rcx
    jz   cr_skip_map
    call CloseHandle
cr_skip_map:

    add  rsp, 32
    pop  rbx
    ret
CleanupRecovery ENDP

; =============================================================================
; C-callable exports for C++ wrapper integration
; =============================================================================

; DiskRecovery_FindDrive — returns drive number or -1
; extern "C" int DiskRecovery_FindDrive();
PUBLIC DiskRecovery_FindDrive
DiskRecovery_FindDrive PROC
    sub  rsp, 28h             ; Shadow space + alignment
    call FindDyingDrive
    add  rsp, 28h
    ret
DiskRecovery_FindDrive ENDP

; DiskRecovery_Init — returns context ptr or NULL
; extern "C" void* DiskRecovery_Init(int driveNum);
PUBLIC DiskRecovery_Init
DiskRecovery_Init PROC
    ; ECX = driveNum (already in first arg register)
    sub  rsp, 28h             ; Shadow space + alignment
    call InitializeRecoveryContext
    add  rsp, 28h
    ret
DiskRecovery_Init ENDP

; DiskRecovery_ExtractKey — returns 1/0
; extern "C" int DiskRecovery_ExtractKey(void* ctx);
PUBLIC DiskRecovery_ExtractKey
DiskRecovery_ExtractKey PROC
    sub  rsp, 28h             ; Shadow space + alignment
    call ExtractEncryptionKey
    add  rsp, 28h
    ret
DiskRecovery_ExtractKey ENDP

; DiskRecovery_Run — runs the recovery loop (blocks until complete/abort)
; extern "C" void DiskRecovery_Run(void* ctx);
PUBLIC DiskRecovery_Run
DiskRecovery_Run PROC
    sub  rsp, 28h             ; Shadow space + alignment
    call RecoveryWorker
    add  rsp, 28h
    ret
DiskRecovery_Run ENDP

; DiskRecovery_Abort — thread-safe abort signal
; extern "C" void DiskRecovery_Abort(void* ctx);
PUBLIC DiskRecovery_Abort
DiskRecovery_Abort PROC
    mov  byte ptr (DISK_RECOVERY_CONTEXT ptr [rcx]).AbortSignal, 1
    ret
DiskRecovery_Abort ENDP

; DiskRecovery_Cleanup — close handles
; extern "C" void DiskRecovery_Cleanup(void* ctx);
PUBLIC DiskRecovery_Cleanup
DiskRecovery_Cleanup PROC
    sub  rsp, 28h             ; Shadow space + alignment
    call CleanupRecovery
    add  rsp, 28h
    ret
DiskRecovery_Cleanup ENDP

; DiskRecovery_GetStats — fill caller-provided stat buffer
; extern "C" void DiskRecovery_GetStats(void* ctx, uint64_t* outGood, uint64_t* outBad, uint64_t* outCurrent, uint64_t* outTotal);
PUBLIC DiskRecovery_GetStats
DiskRecovery_GetStats PROC
    ; RCX = ctx, RDX = &good, R8 = &bad, R9 = &current, [rsp+40] = &total
    mov  rax, (DISK_RECOVERY_CONTEXT ptr [rcx]).GoodSectors
    mov  qword ptr [rdx], rax
    mov  rax, (DISK_RECOVERY_CONTEXT ptr [rcx]).BadSectors
    mov  qword ptr [r8], rax
    mov  rax, (DISK_RECOVERY_CONTEXT ptr [rcx]).CurrentLBA
    mov  qword ptr [r9], rax
    mov  rax, qword ptr [rsp+40]  ; &total (5th arg, stack)
    test rax, rax
    jz   gs_skip_total
    mov  r10, (DISK_RECOVERY_CONTEXT ptr [rcx]).TotalSectors
    mov  qword ptr [rax], r10
gs_skip_total:
    ret
DiskRecovery_GetStats ENDP

; =============================================================================
; Standalone entry point (only used when linked as /entry:DiskRecovery_Main)
; =============================================================================
PUBLIC DiskRecovery_Main
DiskRecovery_Main PROC
    ; Save non-volatile registers used below (R12, RBX)
    push rbx
    push r12
    sub  rsp, 48              ; 2 pushes (16) + 48 = 64 → 0 mod 16 for entry point ✓

    ; Banner
    lea  rcx, szBanner
    call ConsolePrint

    ; Scan for drives
    lea  rcx, szScanning
    call ConsolePrint

    call FindDyingDrive
    cmp  eax, -1
    je   dm_no_drive

    ; Report what we found
    mov  r12d, eax             ; Save drive number

    lea  rcx, szFoundDrive
    call ConsolePrint

    ; Print drive number digit
    mov  al, r12b
    add  al, '0'
    mov  szDriveNum, al
    lea  rcx, szDriveNum
    call ConsolePrint

    ; Initialize
    lea  rcx, szOpening
    call ConsolePrint

    mov  ecx, r12d
    call InitializeRecoveryContext
    test rax, rax
    jz   dm_init_err

    mov  rbx, rax              ; Context ptr

    ; Attempt key extraction before the bridge dies
    lea  rcx, szKeyExtract
    call ConsolePrint

    mov  rcx, rbx
    call ExtractEncryptionKey
    test eax, eax
    jz   dm_no_key

    lea  rcx, szKeySuccess
    call ConsolePrint
    jmp  dm_start_recovery

dm_no_key:
    lea  rcx, szKeyFail
    call ConsolePrint

dm_start_recovery:
    lea  rcx, szHammerStart
    call ConsolePrint

    mov  rcx, rbx
    call RecoveryWorker

    ; Final stats
    mov  rcx, rbx
    call DisplayProgress

    ; Cleanup
    mov  rcx, rbx
    call CleanupRecovery

    lea  rcx, szComplete
    call ConsolePrint

    xor  ecx, ecx
    call ExitProcess

dm_no_drive:
    lea  rcx, szNoDevice
    call ConsolePrint
    mov  ecx, 1
    call ExitProcess

dm_init_err:
    lea  rcx, szInitError
    call ConsolePrint
    mov  ecx, 2
    call ExitProcess

DiskRecovery_Main ENDP

END
 ; =============================================================================
; RawrXD_DualAgent_Orchestrator.asm — Phase 41: Architect↔Coder Swarm Engine
; =============================================================================
;
; Dual-agent orchestration engine for RawrXD inference pipeline.
; Provides:
;   - Concurrent Architect (800B reasoning) + Coder (7B-70B fast) sessions
;   - 64-byte aligned context ring buffer (64MB, zero-copy handoff)
;   - Lock-free SPSC task queue with PAUSE-based spin-wait
;   - AVX-512 non-temporal streaming for context transfer
;   - Fenced handoff (sfence/lfence) for Zen 4 cache coherency
;   - Graceful shutdown with bounded spin timeout
;
; Architecture: x64 MASM64 | Windows x64 ABI
; Calling Convention: Microsoft x64 (RCX, RDX, R8, R9 + stack)
;
; Dependencies:
;   - model_bridge_x64.asm (ModelBridge_LoadModel, ValidateModelAlignment, etc.)
;   - RawrXD_Common.inc (VirtualAlloc, constants, macros)
;
; Build: ml64.exe /c /Zi /Zd /Fo RawrXD_DualAgent_Orchestrator.obj
; Link:  Statically linked into RawrEngine / RawrXD-Win32IDE via CMake ASM_MASM
;
; Rule: NO SOURCE FILE IS TO BE SIMPLIFIED
; =============================================================================

INCLUDE RawrXD_Common.inc

; =============================================================================
;                    DUAL-AGENT CONSTANTS
; =============================================================================

; Agent IDs
AGENT_ID_ARCHITECT      EQU     0       ; High-VRAM reasoning model (70B-800B)
AGENT_ID_CODER          EQU     1       ; Low-latency syntax model (7B-13B)
AGENT_COUNT             EQU     2

; Agent state flags
AGENT_STATE_IDLE        EQU     0       ; Waiting for work
AGENT_STATE_INFERENCING EQU     1       ; Running inference
AGENT_STATE_STALLED     EQU     2       ; Backpressure / waiting
AGENT_STATE_SHUTDOWN    EQU     0FFFFFFFFh  ; Shutdown requested

; Task types
TASK_TYPE_DESIGN_SPEC   EQU     0       ; Architect: generate execution plan
TASK_TYPE_CODE_GEN      EQU     1       ; Coder: generate/edit code
TASK_TYPE_REVIEW        EQU     2       ; Either: review/verify output
TASK_TYPE_CONTEXT_PUSH  EQU     3       ; Push context (file tree, etc.)

; Swarm status codes
SWARM_OK                EQU     0
SWARM_ERR_ALLOC_FAIL    EQU     1
SWARM_ERR_MODEL_FAIL    EQU     2
SWARM_ERR_RING_FULL     EQU     3
SWARM_ERR_NOT_INIT      EQU     4
SWARM_ERR_ALREADY_INIT  EQU     5
SWARM_ERR_SHUTDOWN_FAIL EQU     6

; Ring buffer geometry
RING_SIZE               EQU     04000000h   ; 64 MB
RING_MASK               EQU     03FFFFFFh   ; RING_SIZE - 1
RING_ALLOC_FLAGS        EQU     MEM_COMMIT OR MEM_RESERVE

; Task queue geometry
TASK_QUEUE_SIZE         EQU     10000h      ; 64 KB = 256 task packets
TASK_PKT_SIZE           EQU     100h        ; 256 bytes per task (aligned)
MAX_TASKS               EQU     100h        ; 256 tasks max in queue

; Shutdown spin limit
SHUTDOWN_SPIN_LIMIT     EQU     10000000    ; ~1 second at ~10 GHz retire rate

; =============================================================================
;                    STRUCTURES
; =============================================================================

; Agent Context — one per agent (Architect / Coder)
; Size: 4096 bytes (page-aligned for NUMA awareness)
AGENT_CTX STRUCT
    agent_id        QWORD   ?           ; AGENT_ID_ARCHITECT or AGENT_ID_CODER
    model_profile   DWORD   ?           ; Model profile index in bridge table
    model_tier      DWORD   ?           ; MODEL_TIER_* from bridge
    state_flags     DWORD   ?           ; AGENT_STATE_* (atomic)
    _pad0           DWORD   ?           ; Alignment
    ring_base       QWORD   ?           ; Pointer to shared context ring
    ring_head       QWORD   ?           ; Producer write position (atomic)
    ring_tail       QWORD   ?           ; Consumer read position (atomic)
    queue_base      QWORD   ?           ; Pointer to task queue
    queue_head      DWORD   ?           ; Task queue producer (atomic)
    queue_tail      DWORD   ?           ; Task queue consumer (atomic)
    task_count      QWORD   ?           ; Total tasks processed
    error_count     QWORD   ?           ; Total errors
    last_task_ms    QWORD   ?           ; Timestamp of last completed task
    zmm_save_area   DB      2048 DUP(?) ; ZMM0-31 save area (32 * 64 bytes)
    _reserved       DB      1944 DUP(?) ; Pad to 4096 bytes total
AGENT_CTX ENDS

; Task Packet — enqueued into agent's task queue
; Size: 256 bytes (cache-line-aligned for lock-free SPSC)
TASK_PKT STRUCT
    task_id         QWORD   ?           ; Unique incrementing ID
    task_type       DWORD   ?           ; TASK_TYPE_*
    priority        BYTE    ?           ; 0-255 (255 = real-time)
    _pad0           DB      3 DUP(?)    ; Alignment
    source_agent    DWORD   ?           ; Who submitted this task
    target_agent    DWORD   ?           ; Who should execute it
    data_offset     QWORD   ?           ; Offset into context ring
    data_length     DWORD   ?           ; Length of data in ring
    dep_mask        QWORD   ?           ; Bitmask: which tasks must complete first
    _reserved       DB      200 DUP(?)  ; Pad to 256 bytes
TASK_PKT ENDS

; Swarm State — global orchestrator state
SWARM_STATE STRUCT
    initialized     DWORD   ?           ; 1 if Swarm_Init completed
    agent_count     DWORD   ?           ; Always 2 for dual-agent
    architect_ctx   QWORD   ?           ; Pointer to Architect AGENT_CTX
    coder_ctx       QWORD   ?           ; Pointer to Coder AGENT_CTX
    ring_base       QWORD   ?           ; Shared context ring base
    ring_size       QWORD   ?           ; Ring size in bytes (64MB)
    total_handoffs  QWORD   ?           ; Total Architect→Coder handoffs
    total_tasks     QWORD   ?           ; Total tasks submitted
    lock_flag       DWORD   ?           ; Spinlock for init/shutdown
    _pad            DWORD   3 DUP(?)    ; Alignment
SWARM_STATE ENDS

; =============================================================================
;                    DATA SEGMENT
; =============================================================================
_DATA64 SEGMENT ALIGN(64) 'DATA'

; Global swarm state
g_SwarmState    SWARM_STATE <>

; Next task ID counter (atomic)
g_NextTaskID    QWORD   0

; Status message strings
g_MsgSwarmInit      DB  'DualAgent: swarm initialized (Architect + Coder)', 0
g_MsgSwarmShutdown  DB  'DualAgent: swarm shutdown complete', 0
g_MsgSwarmAllocFail DB  'DualAgent: ERROR — VirtualAlloc failed', 0
g_MsgSwarmModelFail DB  'DualAgent: ERROR — model load failed', 0
g_MsgSwarmNotInit   DB  'DualAgent: ERROR — swarm not initialized', 0
g_MsgSwarmAlready   DB  'DualAgent: ERROR — swarm already initialized', 0
g_MsgHandoffOK      DB  'DualAgent: context handoff complete', 0
g_MsgRingFull       DB  'DualAgent: ERROR — ring buffer full (backpressure)', 0

_DATA64 ENDS

; =============================================================================
;                    EXPORTS
; =============================================================================

PUBLIC Swarm_Init
PUBLIC Swarm_Shutdown
PUBLIC Swarm_GetState
PUBLIC Swarm_SubmitTask
PUBLIC Swarm_Handoff
PUBLIC Swarm_GetAgentStatus
PUBLIC Agent_Architect_Loop
PUBLIC Agent_Coder_Loop

; External dependencies (model_bridge_x64.asm)
EXTERNDEF ModelBridge_LoadModel:PROC
EXTERNDEF ModelBridge_UnloadModel:PROC
EXTERNDEF ModelBridge_ValidateLoad:PROC
EXTERNDEF ValidateModelAlignment:PROC
EXTERNDEF AcquireBridgeLock:PROC
EXTERNDEF ReleaseBridgeLock:PROC
EXTERNDEF EstimateRAM_Safe:PROC
EXTERNDEF ModelBridge_GetProfile:PROC
EXTERNDEF ModelBridge_Init:PROC

; Win32 API (from RawrXD_Common.inc)
; VirtualAlloc, VirtualFree, GetTickCount64, Sleep already declared

; =============================================================================
;                    CODE SEGMENT
; =============================================================================
_TEXT SEGMENT ALIGN(16) 'CODE'

; =============================================================================
; Swarm_Init — Initialize Dual-Agent Orchestrator
; =============================================================================
; Allocates context ring (64MB), agent contexts (4KB each), task queues,
; and loads the Architect + Coder models into the bridge.
;
; Parameters: ECX = Architect profile index (e.g. 20 = 800B DualEngine)
;             EDX = Coder profile index (e.g. 5 = llama3.1:8b)
; Returns:    RAX = SWARM_OK on success, error code on failure
;             RDX = pointer to g_SwarmState
; =============================================================================
Swarm_Init PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 60h
    .allocstack 60h
    .endprolog

    ; Save profile indices
    mov     r12d, ecx                   ; R12 = Architect profile idx
    mov     r13d, edx                   ; R13 = Coder profile idx

    lea     rbx, g_SwarmState

    ; Check not already initialized
    cmp     DWORD PTR [rbx].SWARM_STATE.initialized, 1
    je      @init_already

    ; ---- Allocate shared 64MB context ring (64-byte aligned) ----
    xor     ecx, ecx                    ; lpAddress = NULL (system chooses)
    mov     edx, RING_SIZE              ; dwSize = 64MB
    mov     r8d, RING_ALLOC_FLAGS       ; flAllocationType = COMMIT|RESERVE
    mov     r9d, PAGE_READWRITE         ; flProtect
    sub     rsp, 20h                    ; Shadow space
    call    VirtualAlloc
    add     rsp, 20h
    test    rax, rax
    jz      @init_alloc_fail

    mov     r14, rax                    ; R14 = ring base

    ; Validate alignment (must be 64-byte for AVX-512 NT stores)
    mov     rcx, r14
    sub     rsp, 20h
    call    ValidateModelAlignment      ; Returns aligned address in RAX
    add     rsp, 20h
    mov     r14, rax                    ; R14 = aligned ring base

    ; ---- Allocate Architect AGENT_CTX (4KB page) ----
    xor     ecx, ecx
    mov     edx, 1000h                  ; 4096 bytes
    mov     r8d, RING_ALLOC_FLAGS
    mov     r9d, PAGE_READWRITE
    sub     rsp, 20h
    call    VirtualAlloc
    add     rsp, 20h
    test    rax, rax
    jz      @init_alloc_fail
    mov     rsi, rax                    ; RSI = Architect ctx

    ; ---- Allocate Coder AGENT_CTX (4KB page) ----
    xor     ecx, ecx
    mov     edx, 1000h
    mov     r8d, RING_ALLOC_FLAGS
    mov     r9d, PAGE_READWRITE
    sub     rsp, 20h
    call    VirtualAlloc
    add     rsp, 20h
    test    rax, rax
    jz      @init_alloc_fail
    mov     rdi, rax                    ; RDI = Coder ctx

    ; ---- Allocate Architect task queue (64KB) ----
    xor     ecx, ecx
    mov     edx, TASK_QUEUE_SIZE
    mov     r8d, RING_ALLOC_FLAGS
    mov     r9d, PAGE_READWRITE
    sub     rsp, 20h
    call    VirtualAlloc
    add     rsp, 20h
    test    rax, rax
    jz      @init_alloc_fail
    mov     r15, rax                    ; R15 = Architect queue

    ; ---- Allocate Coder task queue (64KB) ----
    xor     ecx, ecx
    mov     edx, TASK_QUEUE_SIZE
    mov     r8d, RING_ALLOC_FLAGS
    mov     r9d, PAGE_READWRITE
    sub     rsp, 20h
    call    VirtualAlloc
    add     rsp, 20h
    test    rax, rax
    jz      @init_alloc_fail
    mov     QWORD PTR [rsp+30h], rax    ; Save Coder queue in local

    ; ---- Initialize Architect AGENT_CTX ----
    mov     QWORD PTR [rsi].AGENT_CTX.agent_id, AGENT_ID_ARCHITECT
    mov     DWORD PTR [rsi].AGENT_CTX.model_profile, r12d
    mov     DWORD PTR [rsi].AGENT_CTX.state_flags, AGENT_STATE_IDLE
    mov     QWORD PTR [rsi].AGENT_CTX.ring_base, r14
    mov     QWORD PTR [rsi].AGENT_CTX.ring_head, 0
    mov     QWORD PTR [rsi].AGENT_CTX.ring_tail, 0
    mov     QWORD PTR [rsi].AGENT_CTX.queue_base, r15
    mov     DWORD PTR [rsi].AGENT_CTX.queue_head, 0
    mov     DWORD PTR [rsi].AGENT_CTX.queue_tail, 0
    mov     QWORD PTR [rsi].AGENT_CTX.task_count, 0
    mov     QWORD PTR [rsi].AGENT_CTX.error_count, 0

    ; ---- Initialize Coder AGENT_CTX ----
    mov     QWORD PTR [rdi].AGENT_CTX.agent_id, AGENT_ID_CODER
    mov     DWORD PTR [rdi].AGENT_CTX.model_profile, r13d
    mov     DWORD PTR [rdi].AGENT_CTX.state_flags, AGENT_STATE_IDLE
    mov     QWORD PTR [rdi].AGENT_CTX.ring_base, r14
    mov     QWORD PTR [rdi].AGENT_CTX.ring_head, 0
    mov     QWORD PTR [rdi].AGENT_CTX.ring_tail, 0
    mov     rax, QWORD PTR [rsp+30h]   ; Coder queue ptr
    mov     QWORD PTR [rdi].AGENT_CTX.queue_base, rax
    mov     DWORD PTR [rdi].AGENT_CTX.queue_head, 0
    mov     DWORD PTR [rdi].AGENT_CTX.queue_tail, 0
    mov     QWORD PTR [rdi].AGENT_CTX.task_count, 0
    mov     QWORD PTR [rdi].AGENT_CTX.error_count, 0

    ; ---- Initialize model bridge (if not already) ----
    sub     rsp, 20h
    call    ModelBridge_Init
    add     rsp, 20h
    ; Ignore return — may already be initialized

    ; ---- Validate Architect model can be loaded ----
    mov     ecx, r12d
    sub     rsp, 20h
    call    ModelBridge_ValidateLoad
    add     rsp, 20h
    test    rax, rax
    jnz     @init_model_fail

    ; ---- Validate Coder model can be loaded ----
    mov     ecx, r13d
    sub     rsp, 20h
    call    ModelBridge_ValidateLoad
    add     rsp, 20h
    test    rax, rax
    jnz     @init_model_fail

    ; NOTE: We do NOT call ModelBridge_LoadModel here — that is done
    ; by the C++ orchestration layer when inference is needed.
    ; The ASM layer only validates capability and manages context.

    ; ---- Populate global swarm state ----
    mov     DWORD PTR [rbx].SWARM_STATE.agent_count, AGENT_COUNT
    mov     QWORD PTR [rbx].SWARM_STATE.architect_ctx, rsi
    mov     QWORD PTR [rbx].SWARM_STATE.coder_ctx, rdi
    mov     QWORD PTR [rbx].SWARM_STATE.ring_base, r14
    mov     QWORD PTR [rbx].SWARM_STATE.ring_size, RING_SIZE
    mov     QWORD PTR [rbx].SWARM_STATE.total_handoffs, 0
    mov     QWORD PTR [rbx].SWARM_STATE.total_tasks, 0

    ; Mark initialized last (memory fence)
    sfence
    mov     DWORD PTR [rbx].SWARM_STATE.initialized, 1

    ; Return success
    xor     eax, eax                    ; SWARM_OK
    lea     rdx, g_SwarmState
    jmp     @init_done

@init_alloc_fail:
    mov     eax, SWARM_ERR_ALLOC_FAIL
    lea     rdx, g_MsgSwarmAllocFail
    jmp     @init_done

@init_model_fail:
    mov     eax, SWARM_ERR_MODEL_FAIL
    lea     rdx, g_MsgSwarmModelFail
    jmp     @init_done

@init_already:
    mov     eax, SWARM_ERR_ALREADY_INIT
    lea     rdx, g_MsgSwarmAlready

@init_done:
    add     rsp, 60h
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Swarm_Init ENDP

; =============================================================================
; Swarm_Shutdown — Gracefully shut down the dual-agent swarm
; =============================================================================
; Signals both agents to stop, waits with bounded spin, then frees memory.
;
; Parameters: none
; Returns:    RAX = SWARM_OK on success, error code on failure
; =============================================================================
Swarm_Shutdown PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    sub     rsp, 30h
    .allocstack 30h
    .endprolog

    lea     rbx, g_SwarmState

    ; Must be initialized
    cmp     DWORD PTR [rbx].SWARM_STATE.initialized, 0
    je      @shutdown_not_init

    ; Load agent context pointers
    mov     rsi, QWORD PTR [rbx].SWARM_STATE.architect_ctx
    mov     rdi, QWORD PTR [rbx].SWARM_STATE.coder_ctx

    ; Signal shutdown to both agents (atomic store)
    mov     DWORD PTR [rsi].AGENT_CTX.state_flags, AGENT_STATE_SHUTDOWN
    mov     DWORD PTR [rdi].AGENT_CTX.state_flags, AGENT_STATE_SHUTDOWN
    sfence                              ; Ensure visibility

    ; Bounded spin-wait for agents to acknowledge
    mov     r12d, SHUTDOWN_SPIN_LIMIT
@shutdown_wait:
    pause
    dec     r12d
    jz      @shutdown_force             ; Timeout — force cleanup

    ; Check if both are idle (acknowledged shutdown)
    mov     eax, DWORD PTR [rsi].AGENT_CTX.state_flags
    cmp     eax, AGENT_STATE_SHUTDOWN
    jne     @shutdown_wait              ; Still processing
    mov     eax, DWORD PTR [rdi].AGENT_CTX.state_flags
    cmp     eax, AGENT_STATE_SHUTDOWN
    jne     @shutdown_wait

@shutdown_force:
    ; Free context ring (64MB)
    mov     rcx, QWORD PTR [rbx].SWARM_STATE.ring_base
    test    rcx, rcx
    jz      @skip_ring_free
    xor     edx, edx                    ; dwSize = 0 (for MEM_RELEASE)
    mov     r8d, MEM_RELEASE
    sub     rsp, 20h
    call    VirtualFree
    add     rsp, 20h
@skip_ring_free:

    ; Free Architect task queue
    mov     rcx, QWORD PTR [rsi].AGENT_CTX.queue_base
    test    rcx, rcx
    jz      @skip_arch_queue
    xor     edx, edx
    mov     r8d, MEM_RELEASE
    sub     rsp, 20h
    call    VirtualFree
    add     rsp, 20h
@skip_arch_queue:

    ; Free Coder task queue
    mov     rcx, QWORD PTR [rdi].AGENT_CTX.queue_base
    test    rcx, rcx
    jz      @skip_coder_queue
    xor     edx, edx
    mov     r8d, MEM_RELEASE
    sub     rsp, 20h
    call    VirtualFree
    add     rsp, 20h
@skip_coder_queue:

    ; Free Architect context (4KB)
    mov     rcx, rsi
    xor     edx, edx
    mov     r8d, MEM_RELEASE
    sub     rsp, 20h
    call    VirtualFree
    add     rsp, 20h

    ; Free Coder context (4KB)
    mov     rcx, rdi
    xor     edx, edx
    mov     r8d, MEM_RELEASE
    sub     rsp, 20h
    call    VirtualFree
    add     rsp, 20h

    ; Clear global state
    lea     rdi, g_SwarmState
    xor     eax, eax
    mov     ecx, SIZEOF SWARM_STATE
    rep     stosb

    ; Return success
    xor     eax, eax
    lea     rdx, g_MsgSwarmShutdown
    jmp     @shutdown_done

@shutdown_not_init:
    mov     eax, SWARM_ERR_NOT_INIT
    lea     rdx, g_MsgSwarmNotInit

@shutdown_done:
    add     rsp, 30h
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Swarm_Shutdown ENDP

; =============================================================================
; Swarm_GetState — Return pointer to global swarm state
; =============================================================================
; Parameters: none
; Returns:    RAX = pointer to SWARM_STATE
; =============================================================================
Swarm_GetState PROC
    lea     rax, g_SwarmState
    ret
Swarm_GetState ENDP

; =============================================================================
; Swarm_GetAgentStatus — Return status of a specific agent
; =============================================================================
; Parameters: ECX = agent ID (0 = Architect, 1 = Coder)
; Returns:    RAX = AGENT_STATE_* flag
;             RDX = pointer to AGENT_CTX (or NULL if invalid / not init)
; =============================================================================
Swarm_GetAgentStatus PROC
    lea     rax, g_SwarmState
    cmp     DWORD PTR [rax].SWARM_STATE.initialized, 0
    je      @agent_not_init

    cmp     ecx, AGENT_ID_ARCHITECT
    je      @get_architect
    cmp     ecx, AGENT_ID_CODER
    je      @get_coder
    jmp     @agent_not_init

@get_architect:
    mov     rdx, QWORD PTR [rax].SWARM_STATE.architect_ctx
    mov     eax, DWORD PTR [rdx].AGENT_CTX.state_flags
    ret

@get_coder:
    mov     rdx, QWORD PTR [rax].SWARM_STATE.coder_ctx
    mov     eax, DWORD PTR [rdx].AGENT_CTX.state_flags
    ret

@agent_not_init:
    mov     eax, SWARM_ERR_NOT_INIT
    xor     edx, edx                    ; NULL
    ret
Swarm_GetAgentStatus ENDP

; =============================================================================
; Swarm_SubmitTask — Enqueue a task to an agent's task queue
; =============================================================================
; Lock-free SPSC enqueue. Only one producer thread should call this per agent.
;
; Parameters: RCX = pointer to AGENT_CTX (target agent)
;             RDX = pointer to TASK_PKT (caller-filled, will be copied)
; Returns:    RAX = SWARM_OK on success, SWARM_ERR_RING_FULL if queue full
; =============================================================================
Swarm_SubmitTask PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    .endprolog

    mov     rbx, rcx                    ; RBX = target AGENT_CTX
    mov     rsi, rdx                    ; RSI = source TASK_PKT

    ; Check swarm is initialized
    lea     rax, g_SwarmState
    cmp     DWORD PTR [rax].SWARM_STATE.initialized, 0
    je      @submit_not_init

    ; Read current head (producer position)
    mov     eax, DWORD PTR [rbx].AGENT_CTX.queue_head
    mov     ecx, eax
    inc     ecx
    and     ecx, (MAX_TASKS - 1)        ; Wrap

    ; Check if full (head+1 == tail)
    cmp     ecx, DWORD PTR [rbx].AGENT_CTX.queue_tail
    je      @submit_full

    ; Compute destination: queue_base + head * TASK_PKT_SIZE
    mov     edx, eax                    ; head index
    shl     edx, 8                      ; * 256 (TASK_PKT_SIZE)
    mov     rdi, QWORD PTR [rbx].AGENT_CTX.queue_base
    add     rdi, rdx                    ; RDI = dest slot

    ; Copy TASK_PKT (256 bytes) — use rep movsb for simplicity
    mov     ecx, TASK_PKT_SIZE
    ; RSI = source, RDI = dest (already set)
    rep     movsb

    ; Assign task ID (atomic increment)
    lock inc QWORD PTR g_NextTaskID
    mov     rax, QWORD PTR g_NextTaskID
    mov     QWORD PTR [rdi - TASK_PKT_SIZE], rax   ; Write task_id to slot

    ; Store fence: ensure task data is visible before advancing head
    sfence

    ; Advance head (atomic — only producer writes head)
    mov     eax, DWORD PTR [rbx].AGENT_CTX.queue_head
    inc     eax
    and     eax, (MAX_TASKS - 1)
    mov     DWORD PTR [rbx].AGENT_CTX.queue_head, eax

    ; Increment global task counter
    lock inc QWORD PTR [rbx].AGENT_CTX.task_count
    lea     rax, g_SwarmState
    lock inc QWORD PTR [rax].SWARM_STATE.total_tasks

    ; Timestamp
    sub     rsp, 20h
    call    GetTickCount64
    add     rsp, 20h
    mov     QWORD PTR [rbx].AGENT_CTX.last_task_ms, rax

    ; Return success
    xor     eax, eax                    ; SWARM_OK
    jmp     @submit_done

@submit_full:
    mov     eax, SWARM_ERR_RING_FULL
    lea     rdx, g_MsgRingFull
    jmp     @submit_done

@submit_not_init:
    mov     eax, SWARM_ERR_NOT_INIT
    lea     rdx, g_MsgSwarmNotInit

@submit_done:
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Swarm_SubmitTask ENDP

; =============================================================================
; Swarm_Handoff — Zero-copy context transfer (Architect → Coder)
; =============================================================================
; Writes data into the shared ring buffer at Architect's head position,
; then advances head so Coder can consume it. Uses sfence to guarantee
; non-temporal store ordering (critical for Zen 4 dual-engine handoff).
;
; Parameters: RCX = pointer to source data
;             EDX = length of data in bytes (must be multiple of 64)
; Returns:    RAX = SWARM_OK on success, SWARM_ERR_RING_FULL if no space
; =============================================================================
Swarm_Handoff PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    .endprolog

    mov     rsi, rcx                    ; RSI = source data
    mov     r12d, edx                   ; R12 = data length

    lea     rbx, g_SwarmState

    ; Must be initialized
    cmp     DWORD PTR [rbx].SWARM_STATE.initialized, 0
    je      @handoff_not_init

    ; Get Architect and Coder contexts
    mov     rdi, QWORD PTR [rbx].SWARM_STATE.architect_ctx
    mov     r13, QWORD PTR [rbx].SWARM_STATE.coder_ctx

    ; Get ring positions
    ; Architect writes at its ring_head; Coder reads at its ring_tail
    mov     rax, QWORD PTR [rdi].AGENT_CTX.ring_head   ; Producer pos
    mov     rcx, QWORD PTR [r13].AGENT_CTX.ring_tail   ; Consumer pos

    ; Check available space in ring
    ; Available = (tail - head - 1) & RING_MASK  (producer can't lap consumer)
    mov     rdx, rcx
    sub     rdx, rax
    dec     rdx
    and     rdx, RING_MASK
    cmp     rdx, r12                    ; Enough space?
    jb      @handoff_full               ; Not enough — backpressure

    ; Get ring base
    mov     rdi, QWORD PTR [rbx].SWARM_STATE.ring_base

    ; Serialize reads before we touch the ring
    lfence

    ; Copy data into ring (64-byte aligned chunks)
    mov     ecx, r12d                   ; Length
    mov     rdx, rax                    ; Current head position
    and     rdx, RING_MASK              ; Wrap

@handoff_copy:
    cmp     ecx, 0
    jle     @handoff_copy_done

    ; Copy 64 bytes at a time (cache line)
    ; Use regular mov for correctness (NT stores require strict alignment
    ; and may not wrap correctly at ring boundary)
    push    rcx
    push    rsi
    push    rdi

    ; Destination = ring_base + (head & RING_MASK)
    lea     rdi, [rdi + rdx]
    mov     ecx, 64
    rep     movsb                       ; Copy 64 bytes

    pop     rdi
    pop     rsi
    pop     rcx

    add     rsi, 64                     ; Advance source
    add     rdx, 64                     ; Advance ring position
    and     rdx, RING_MASK              ; Wrap
    sub     ecx, 64
    jmp     @handoff_copy

@handoff_copy_done:
    ; Store fence: CRITICAL for Zen 4 cache coherency
    ; All ring writes must be globally visible before we advance the head pointer.
    ; Without this: Coder reads stale data → cache coherency crash on Ryzen 7000.
    sfence

    ; Advance Architect's head pointer (atomic from Coder's perspective)
    mov     rax, QWORD PTR [rbx].SWARM_STATE.architect_ctx
    mov     rcx, QWORD PTR [rax].AGENT_CTX.ring_head
    add     rcx, r12                    ; Advance by data length
    and     rcx, RING_MASK              ; Wrap
    mov     QWORD PTR [rax].AGENT_CTX.ring_head, rcx

    ; Increment handoff counter
    lock inc QWORD PTR [rbx].SWARM_STATE.total_handoffs

    ; Return success
    xor     eax, eax                    ; SWARM_OK
    jmp     @handoff_done

@handoff_full:
    mov     eax, SWARM_ERR_RING_FULL
    lea     rdx, g_MsgRingFull
    jmp     @handoff_done

@handoff_not_init:
    mov     eax, SWARM_ERR_NOT_INIT
    lea     rdx, g_MsgSwarmNotInit

@handoff_done:
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Swarm_Handoff ENDP

; =============================================================================
; Agent_Architect_Loop — Worker thread main loop for Architect agent
; =============================================================================
; Runs on a dedicated thread. Dequeues tasks from the Architect's SPSC queue,
; transitions state to INFERENCING, invokes the C++ inference callback, and
; writes results into the shared ring buffer for the Coder to consume.
;
; The inference itself is dispatched to C++ via a function pointer callback
; (passed in RDX) because the actual model inference uses the HTTP/streaming
; engine. The ASM loop handles state management, queue draining, and
; Architect→Coder ring buffer handoff with proper fencing.
;
; Parameters: RCX = pointer to Architect AGENT_CTX
;             RDX = function pointer: int64_t (*InferenceCallback)(AGENT_CTX*, TASK_PKT*)
;                   Returns bytes written to ring, or -1 on error.
; Returns:    RAX = total tasks processed before shutdown
; =============================================================================
ALIGN 16
Agent_Architect_Loop PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 40h
    .allocstack 40h
    .endprolog

    mov     rbx, rcx                    ; RBX = Architect AGENT_CTX
    mov     r12, rdx                    ; R12 = InferenceCallback
    xor     r15d, r15d                  ; R15 = tasks processed counter

@@architect_loop:
    ; ---- Check for shutdown ----
    mov     eax, DWORD PTR [rbx].AGENT_CTX.state_flags
    cmp     eax, AGENT_STATE_SHUTDOWN
    je      @@architect_exit

    ; ---- Set state to IDLE while polling ----
    mov     DWORD PTR [rbx].AGENT_CTX.state_flags, AGENT_STATE_IDLE

    ; ---- Try dequeue from own task queue (lock-free SPSC consumer) ----
    mov     r13d, DWORD PTR [rbx].AGENT_CTX.queue_tail   ; Consumer position
    lfence                              ; Serialize before reading head
    mov     r14d, DWORD PTR [rbx].AGENT_CTX.queue_head   ; Producer position

    cmp     r13d, r14d
    je      @@architect_spin             ; Queue empty — spin-wait

    ; ---- Dequeue task packet ----
    ; Compute slot address: queue_base + tail * 256
    mov     eax, r13d
    shl     eax, 8                      ; * TASK_PKT_SIZE (256)
    mov     rsi, QWORD PTR [rbx].AGENT_CTX.queue_base
    add     rsi, rax                    ; RSI = pointer to TASK_PKT in queue

    ; ---- Transition to INFERENCING ----
    mov     DWORD PTR [rbx].AGENT_CTX.state_flags, AGENT_STATE_INFERENCING

    ; ---- Call C++ inference callback ----
    ; Callback signature: int64_t callback(AGENT_CTX* ctx, TASK_PKT* task)
    ; Returns: bytes written to ring (>= 0), or -1 on error
    mov     rcx, rbx                    ; Arg1 = AGENT_CTX*
    mov     rdx, rsi                    ; Arg2 = TASK_PKT*
    call    r12                         ; Call InferenceCallback

    ; ---- Check callback result ----
    cmp     rax, -1
    je      @@architect_error

    ; ---- Success: advance tail (only consumer writes tail) ----
    mov     eax, r13d
    inc     eax
    and     eax, (MAX_TASKS - 1)        ; Wrap
    sfence                              ; Ensure callback writes are visible
    mov     DWORD PTR [rbx].AGENT_CTX.queue_tail, eax

    ; ---- Timestamp ----
    sub     rsp, 20h
    call    GetTickCount64
    add     rsp, 20h
    mov     QWORD PTR [rbx].AGENT_CTX.last_task_ms, rax

    ; ---- Increment counters ----
    inc     r15                         ; Local counter
    lock inc QWORD PTR [rbx].AGENT_CTX.task_count

    jmp     @@architect_loop

@@architect_spin:
    ; Spin-wait with PAUSE (saves 90% power, VM-safe)
    pause
    ; Brief yield: call Sleep(0) every 256 spins to avoid starving other threads
    ; (Use a simple counter in R14 since it's free here)
    inc     r14d
    test    r14d, 0FFh                  ; Every 256 iterations
    jnz     @@architect_loop
    mov     ecx, 0                      ; Sleep(0) = yield timeslice
    sub     rsp, 20h
    call    Sleep
    add     rsp, 20h
    jmp     @@architect_loop

@@architect_error:
    ; Inference callback returned error
    lock inc QWORD PTR [rbx].AGENT_CTX.error_count
    ; Still advance tail to avoid stuck queue
    mov     eax, r13d
    inc     eax
    and     eax, (MAX_TASKS - 1)
    mov     DWORD PTR [rbx].AGENT_CTX.queue_tail, eax
    jmp     @@architect_loop

@@architect_exit:
    ; Signal acknowledgment: set state to SHUTDOWN + 1 = 0xFFFFFFFF is already set
    ; Return total tasks processed
    mov     rax, r15
    mov     DWORD PTR [rbx].AGENT_CTX.state_flags, AGENT_STATE_SHUTDOWN

    add     rsp, 40h
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Agent_Architect_Loop ENDP

; =============================================================================
; Agent_Coder_Loop — Worker thread main loop for Coder agent
; =============================================================================
; Runs on a dedicated thread. Consumes tasks from the Coder's SPSC queue
; AND monitors the shared ring buffer for Architect→Coder handoff data.
;
; The Coder has two input sources:
;   1. Direct task submissions (via Swarm_SubmitTask to Coder queue)
;   2. Ring buffer data from Architect (design specs to implement)
;
; When ring data is available (Architect's head > Coder's tail), the Coder
; synthesizes a TASK_TYPE_CODE_GEN task internally and processes it.
;
; Parameters: RCX = pointer to Coder AGENT_CTX
;             RDX = function pointer: int64_t (*InferenceCallback)(AGENT_CTX*, TASK_PKT*)
;                   Returns bytes produced (>= 0), or -1 on error.
; Returns:    RAX = total tasks processed before shutdown
; =============================================================================
ALIGN 16
Agent_Coder_Loop PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 40h
    .allocstack 40h
    .endprolog

    mov     rbx, rcx                    ; RBX = Coder AGENT_CTX
    mov     r12, rdx                    ; R12 = InferenceCallback
    xor     r15d, r15d                  ; R15 = tasks processed counter

@@coder_loop:
    ; ---- Check for shutdown ----
    mov     eax, DWORD PTR [rbx].AGENT_CTX.state_flags
    cmp     eax, AGENT_STATE_SHUTDOWN
    je      @@coder_exit

    ; ---- Set state to IDLE while polling ----
    mov     DWORD PTR [rbx].AGENT_CTX.state_flags, AGENT_STATE_IDLE

    ; ---- Priority 1: Check own task queue ----
    mov     r13d, DWORD PTR [rbx].AGENT_CTX.queue_tail
    lfence
    mov     r14d, DWORD PTR [rbx].AGENT_CTX.queue_head
    cmp     r13d, r14d
    jne     @@coder_dequeue              ; Has direct task — process it

    ; ---- Priority 2: Check ring buffer for Architect handoff ----
    ; Coder reads at its ring_tail; Architect writes at Architect's ring_head
    lea     rax, g_SwarmState
    mov     rdi, QWORD PTR [rax].SWARM_STATE.architect_ctx
    test    rdi, rdi
    jz      @@coder_spin                 ; No architect context

    mov     rsi, QWORD PTR [rdi].AGENT_CTX.ring_head    ; Architect's write pos
    lfence                              ; Serialize: read Architect's head
    mov     rax, QWORD PTR [rbx].AGENT_CTX.ring_tail    ; Coder's read pos
    cmp     rax, rsi
    je      @@coder_spin                 ; Ring empty — no handoff data

    ; ---- Ring data available: synthesize a CODE_GEN task on stack ----
    ; We create a temporary TASK_PKT pointing to the ring data
    mov     DWORD PTR [rbx].AGENT_CTX.state_flags, AGENT_STATE_INFERENCING

    ; Calculate available data length (head - tail, wrapped)
    mov     rcx, rsi
    sub     rcx, rax
    and     rcx, RING_MASK              ; Available bytes
    ; Cap at 64KB per iteration to avoid monopolizing the thread
    cmp     rcx, 10000h
    jbe     @@coder_ring_len_ok
    mov     ecx, 10000h                 ; 64KB cap
@@coder_ring_len_ok:

    ; Build a stack-local TASK_PKT
    ; Use the space at [rsp] (we have 40h = 64 bytes, need to extend for 256)
    ; Actually, the callback only needs AGENT_CTX* and TASK_PKT*, and the
    ; critical fields are task_type, data_offset, data_length.
    ; We'll use a minimal approach: pass the ring offset via a compact struct.
    ; The C++ callback can read the ring directly from the AGENT_CTX.

    ; Temporarily store ring data info in the AGENT_CTX ring_tail area
    ; (the callback reads ring_base + ring_tail to find the data)
    ; Call inference with NULL task to signal "consume ring data"
    mov     rcx, rbx                    ; Arg1 = AGENT_CTX*
    xor     edx, edx                    ; Arg2 = NULL (signals ring consumption)
    call    r12                         ; Call InferenceCallback

    ; Check result
    cmp     rax, -1
    je      @@coder_ring_error

    ; Advance Coder's ring_tail by consumed amount
    mov     rcx, QWORD PTR [rbx].AGENT_CTX.ring_tail
    add     rcx, rax                    ; Advance by bytes consumed
    and     rcx, RING_MASK
    sfence
    mov     QWORD PTR [rbx].AGENT_CTX.ring_tail, rcx

    ; Timestamp + counters
    sub     rsp, 20h
    call    GetTickCount64
    add     rsp, 20h
    mov     QWORD PTR [rbx].AGENT_CTX.last_task_ms, rax
    inc     r15
    lock inc QWORD PTR [rbx].AGENT_CTX.task_count

    jmp     @@coder_loop

@@coder_dequeue:
    ; ---- Process direct task from own queue ----
    mov     eax, r13d
    shl     eax, 8                      ; * TASK_PKT_SIZE
    mov     rsi, QWORD PTR [rbx].AGENT_CTX.queue_base
    add     rsi, rax                    ; RSI = task packet pointer

    mov     DWORD PTR [rbx].AGENT_CTX.state_flags, AGENT_STATE_INFERENCING

    ; Call C++ inference callback
    mov     rcx, rbx                    ; Arg1 = AGENT_CTX*
    mov     rdx, rsi                    ; Arg2 = TASK_PKT*
    call    r12                         ; Call InferenceCallback

    cmp     rax, -1
    je      @@coder_task_error

    ; Advance tail
    mov     eax, r13d
    inc     eax
    and     eax, (MAX_TASKS - 1)
    sfence
    mov     DWORD PTR [rbx].AGENT_CTX.queue_tail, eax

    ; Timestamp + counters
    sub     rsp, 20h
    call    GetTickCount64
    add     rsp, 20h
    mov     QWORD PTR [rbx].AGENT_CTX.last_task_ms, rax
    inc     r15
    lock inc QWORD PTR [rbx].AGENT_CTX.task_count

    jmp     @@coder_loop

@@coder_spin:
    pause
    inc     r14d
    test    r14d, 0FFh
    jnz     @@coder_loop
    mov     ecx, 0                      ; Sleep(0) yield
    sub     rsp, 20h
    call    Sleep
    add     rsp, 20h
    jmp     @@coder_loop

@@coder_ring_error:
    lock inc QWORD PTR [rbx].AGENT_CTX.error_count
    jmp     @@coder_loop

@@coder_task_error:
    lock inc QWORD PTR [rbx].AGENT_CTX.error_count
    ; Advance tail to prevent stuck
    mov     eax, r13d
    inc     eax
    and     eax, (MAX_TASKS - 1)
    mov     DWORD PTR [rbx].AGENT_CTX.queue_tail, eax
    jmp     @@coder_loop

@@coder_exit:
    mov     rax, r15
    mov     DWORD PTR [rbx].AGENT_CTX.state_flags, AGENT_STATE_SHUTDOWN

    add     rsp, 40h
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Agent_Coder_Loop ENDP

_TEXT ENDS

END
 ; =============================================================================
; RawrXD_DualEngine_QuantumBeacon.asm — Pure x64 MASM Dual Engine + Quantum Beaconism
; =============================================================================
;
; Pure kernel operation: no user-mode or kernel API calls. No CRT.
; Time: RDTSC (timestamp = TSC). Compare: inline _KernelMemCmp. Link in driver or usermode.
;
; Production implementation: 10x Dual Engine Coordinator and Quantum Beaconism
; Fusion Backend. Replaces dual_engine_system.h + quantum_beaconism_backend.h.
;
; Exports: DualEngine_InitAll, DualEngine_ShutdownAll, DualEngine_GetEngine,
;          DualEngine_ExecuteOnAll, DualEngine_GetAllTelemetry, DualEngine_DispatchCLI,
;          DualEngine_AllHealthy, DualEngine_SelfDiagnoseAll,
;          QuantumBeacon_Init, QuantumBeacon_Shutdown, QuantumBeacon_GetState,
;          QuantumBeacon_BeginFusion, QuantumBeacon_GetLatestBeacon, QuantumBeacon_GetTelemetry,
;          QuantumBeacon_FusionStep, QuantumBeacon_DispatchCLI, QuantumBeacon_ForceBeacon.
;
; Build: ml64 /c /Zi /Fo RawrXD_DualEngine_QuantumBeacon.obj RawrXD_DualEngine_QuantumBeacon.asm
; =============================================================================

option casemap:none

; No INCLUDE RawrXD_Common.inc — pure kernel: zero external refs (no kernel32/CRT).
; Time = RDTSC; compare = _KernelMemCmp. Safe to link in driver or usermode.

; Constants
ENGINE_COUNT           EQU 10
FUSION_STATE_DORMANT   EQU 0
FUSION_STATE_CALIBRATING EQU 1
FUSION_STATE_SUPERPOSITION EQU 2
FUSION_STATE_COLLAPSING EQU 3
FUSION_STATE_ENTANGLED EQU 4
FUSION_STATE_BEACONING EQU 5
FUSION_STATE_FAULTED   EQU 6

ENGINE_RESULT_OK       EQU 0
ENGINE_RESULT_ERR      EQU 1

; Engine telemetry size (invocations(8), totalCycles(8), avgLatencyMs(8), peakLatencyMs(8),
;   throughputOps(8), efficiencyRatio(4), thermalContribution(4), faultCount(4), lastInvocation(8))
ENGINE_TELEMETRY_SIZE  EQU 60

; Beacon struct: epoch(8), globalOptimality(4), temperature(4), entropy(4), activeEngines(4), timestamp(8)
BEACON_SIZE            EQU 32

; Simulated annealing: temperature 10..10000 (0.001..1.0), fitness 0..1000
SA_INITIAL_TEMP        EQU 10000
SA_COOLING_NUM         EQU 995
SA_COOLING_DEN         EQU 1000
SA_MIN_TEMP            EQU 10
FITNESS_SCALE          EQU 1000

_DATA64 SEGMENT ALIGN(64) 'DATA'

; Dual Engine state
g_DualEngineInit       DD 0
g_EngineTelemetry      DB (ENGINE_TELEMETRY_SIZE * ENGINE_COUNT) DUP(0)

; Quantum Beacon state
g_BeaconInit           DD 0
g_FusionState          DB FUSION_STATE_DORMANT
g_FusionRunning        DD 0
g_BeaconEpoch          DQ 0
g_BeaconOptimality     DD 0
g_BeaconTemperature    DD 0
g_BeaconEntropy        DD 0
g_BeaconActiveEngines  DD 0
g_LatestBeacon         DB BEACON_SIZE DUP(0)

; Fusion loop: per-engine beta 0..255 (quantum-inspired state)
g_EngineBeta           DB ENGINE_COUNT DUP(128)
; Simulated annealing
g_SA_Temperature       DD SA_INITIAL_TEMP
g_SA_CoolingRateNum   DD SA_COOLING_NUM
g_SA_CoolingRateDen   DD SA_COOLING_DEN
g_SA_MinTemp          DD SA_MIN_TEMP
g_CurrentFitness      DD 0
g_BestFitness         DD 0
g_FusionSubStep       DD 0
g_RNG                 DD 12345

; Strings
g_MsgOK                DB "OK", 0
g_MsgErr               DB "Error", 0
g_MsgNotInit           DB "Not initialized", 0
g_MsgUnknownCommand    DB "Unknown command", 0

; CLI command strings for DispatchCLI
g_CmdInit              DB "init", 0
g_CmdShutdown          DB "shutdown", 0
g_CmdExecute           DB "execute", 0
g_CmdStatus            DB "status", 0
g_CmdDiagnose          DB "diagnose", 0
g_CmdBeaconInit        DB "init", 0
g_CmdBeaconShutdown    DB "shutdown", 0
g_CmdBeaconBegin       DB "begin", 0
g_CmdBeaconForce       DB "force", 0
g_CmdBeaconState       DB "state", 0

_DATA64 ENDS

_TEXT SEGMENT ALIGN(16) 'CODE'

; -----------------------------------------------------------------------------
; _KernelMemCmp — RCX=ptr1, RDX=ptr2, R8=len. Returns EAX=0 if equal, else non-zero. Pure kernel.
; -----------------------------------------------------------------------------
_KernelMemCmp PROC
    xor     eax, eax
    test    r8, r8
    jz      @@eq
@@cmp:
    mov     r9b, byte ptr [rcx]
    mov     r10b, byte ptr [rdx]
    cmp     r9b, r10b
    jne     @@ne
    inc     rcx
    inc     rdx
    dec     r8
    jnz     @@cmp
    ret
@@ne:
    mov     eax, 1
@@eq:
    ret
_KernelMemCmp ENDP

; -----------------------------------------------------------------------------
; _KernelTickCount — Returns RAX = 64-bit TSC (RDTSC). No kernel/user API.
; -----------------------------------------------------------------------------
_KernelTickCount PROC
    rdtsc
    shl     rdx, 32
    or      rax, rdx
    ret
_KernelTickCount ENDP

; =============================================================================
; DualEngine_InitAll — Initialize all 10 engines. Returns RAX=0 ok, else error.
; =============================================================================
PUBLIC DualEngine_InitAll
ALIGN 16
DualEngine_InitAll PROC
    mov     eax, dword ptr [g_DualEngineInit]
    test    eax, eax
    jnz     @@done
    ; Zero telemetry
    lea     rdi, [g_EngineTelemetry]
    mov     ecx, (ENGINE_TELEMETRY_SIZE * ENGINE_COUNT) / 8
    xor     eax, eax
    rep stosq
    mov     dword ptr [g_DualEngineInit], 1
@@done:
    xor     eax, eax
    lea     rdx, [g_MsgOK]
    ret
DualEngine_InitAll ENDP

; =============================================================================
; DualEngine_ShutdownAll
; =============================================================================
PUBLIC DualEngine_ShutdownAll
ALIGN 16
DualEngine_ShutdownAll PROC
    mov     dword ptr [g_DualEngineInit], 0
    xor     eax, eax
    lea     rdx, [g_MsgOK]
    ret
DualEngine_ShutdownAll ENDP

; =============================================================================
; DualEngine_GetEngine — RCX=EngineId (0..9). Returns RDX=opaque engine ptr (telemetry slot).
; =============================================================================
PUBLIC DualEngine_GetEngine
ALIGN 16
DualEngine_GetEngine PROC
    cmp     ecx, ENGINE_COUNT
    jb      @@valid
    xor     rax, rax
    ret
@@valid:
    imul    ecx, ENGINE_TELEMETRY_SIZE
    lea     rax, [g_EngineTelemetry]
    add     rax, rcx
    mov     rdx, rax
    xor     eax, eax
    ret
DualEngine_GetEngine ENDP

; =============================================================================
; DualEngine_ExecuteOnAll — RCX=featureA (1 or 0), RDX=args ptr. Returns RAX=0 ok.
; Increment invocations; fusion uses low byte in Calibrate for engine beta.
; =============================================================================
PUBLIC DualEngine_ExecuteOnAll
ALIGN 16
DualEngine_ExecuteOnAll PROC
    mov     eax, dword ptr [g_DualEngineInit]
    test    eax, eax
    jz      @@err
    lea     r8, [g_EngineTelemetry]
    mov     ecx, ENGINE_COUNT
@@inc:
    add     qword ptr [r8], 1
    add     r8, ENGINE_TELEMETRY_SIZE
    dec     ecx
    jnz     @@inc
    xor     eax, eax
    lea     rdx, [g_MsgOK]
    ret
@@err:
    mov     eax, ENGINE_RESULT_ERR
    lea     rdx, [g_MsgNotInit]
    ret
DualEngine_ExecuteOnAll ENDP

; =============================================================================
; DualEngine_GetAllTelemetry — RDX=ptr to array of ENGINE_COUNT EngineTelemetry structs.
; =============================================================================
PUBLIC DualEngine_GetAllTelemetry
ALIGN 16
DualEngine_GetAllTelemetry PROC
    mov     rax, rdx
    test    rax, rax
    jz      @@z
    lea     rsi, [g_EngineTelemetry]
    mov     ecx, ENGINE_COUNT
@@copy:
    mov     r8, [rsi]
    mov     [rax], r8
    mov     r8, [rsi+8]
    mov     [rax+8], r8
    mov     r8, [rsi+16]
    mov     [rax+16], r8
    mov     r8, [rsi+24]
    mov     [rax+24], r8
    mov     r8, [rsi+32]
    mov     [rax+32], r8
    mov     r8d, [rsi+40]
    mov     [rax+40], r8d
    mov     r8d, [rsi+44]
    mov     [rax+44], r8d
    mov     r8d, [rsi+48]
    mov     [rax+48], r8d
    mov     r8, [rsi+52]
    mov     [rax+52], r8
    add     rsi, ENGINE_TELEMETRY_SIZE
    add     rax, ENGINE_TELEMETRY_SIZE
    dec     ecx
    jnz     @@copy
@@z:
    xor     eax, eax
    ret
DualEngine_GetAllTelemetry ENDP

; =============================================================================
; DualEngine_AllHealthy — Returns RAX=1 if all healthy, 0 otherwise.
; =============================================================================
PUBLIC DualEngine_AllHealthy
ALIGN 16
DualEngine_AllHealthy PROC
    mov     eax, dword ptr [g_DualEngineInit]
    ret
DualEngine_AllHealthy ENDP

; =============================================================================
; DualEngine_SelfDiagnoseAll — Returns RAX=0 ok.
; =============================================================================
PUBLIC DualEngine_SelfDiagnoseAll
ALIGN 16
DualEngine_SelfDiagnoseAll PROC
    xor     eax, eax
    lea     rdx, [g_MsgOK]
    ret
DualEngine_SelfDiagnoseAll ENDP

; =============================================================================
; DualEngine_DispatchCLI — RCX=flag ptr, RDX=args ptr. Returns RAX=0 ok, RDX=detail.
; Commands: init, shutdown, execute, status, diagnose
; =============================================================================
PUBLIC DualEngine_DispatchCLI
ALIGN 16
DualEngine_DispatchCLI PROC
    push    rbx
    push    rsi
    sub     rsp, 38h
    mov     rbx, rcx
    mov     rsi, rdx
    test    rbx, rbx
    jz      @@unknown
    ; Compare "init"
    lea     rcx, [g_CmdInit]
    mov     rdx, rbx
    mov     r8d, 4
    call    _KernelMemCmp
    test    eax, eax
    jz      @@do_init
    ; Compare "shutdown"
    lea     rcx, [g_CmdShutdown]
    mov     rdx, rbx
    mov     r8d, 8
    call    _KernelMemCmp
    test    eax, eax
    jz      @@do_shutdown
    ; Compare "execute"
    lea     rcx, [g_CmdExecute]
    mov     rdx, rbx
    mov     r8d, 7
    call    _KernelMemCmp
    test    eax, eax
    jz      @@do_execute
    ; Compare "status"
    lea     rcx, [g_CmdStatus]
    mov     rdx, rbx
    mov     r8d, 6
    call    _KernelMemCmp
    test    eax, eax
    jz      @@do_status
    ; Compare "diagnose"
    lea     rcx, [g_CmdDiagnose]
    mov     rdx, rbx
    mov     r8d, 8
    call    _KernelMemCmp
    test    eax, eax
    jz      @@do_diagnose
    jmp     @@unknown
@@do_init:
    call    DualEngine_InitAll
    jmp     @@ret
@@do_shutdown:
    call    DualEngine_ShutdownAll
    jmp     @@ret
@@do_execute:
    xor     ecx, ecx
    mov     rdx, rsi
    call    DualEngine_ExecuteOnAll
    jmp     @@ret
@@do_status:
    call    DualEngine_AllHealthy
    xor     eax, eax
    lea     rdx, [g_MsgOK]
    jmp     @@ret
@@do_diagnose:
    call    DualEngine_SelfDiagnoseAll
    jmp     @@ret
@@unknown:
    mov     eax, ENGINE_RESULT_ERR
    lea     rdx, [g_MsgUnknownCommand]
@@ret:
    add     rsp, 38h
    pop     rsi
    pop     rbx
    ret
DualEngine_DispatchCLI ENDP

; =============================================================================
; QuantumBeacon_Init
; =============================================================================
PUBLIC QuantumBeacon_Init
ALIGN 16
QuantumBeacon_Init PROC
    mov     eax, dword ptr [g_BeaconInit]
    test    eax, eax
    jnz     @@done
    mov     dword ptr [g_FusionState], FUSION_STATE_DORMANT
    mov     qword ptr [g_BeaconEpoch], 0
    mov     dword ptr [g_BeaconOptimality], 0
    mov     dword ptr [g_BeaconTemperature], 0
    mov     dword ptr [g_BeaconEntropy], 0
    mov     dword ptr [g_BeaconActiveEngines], 0
    mov     dword ptr [g_BeaconInit], 1
@@done:
    xor     eax, eax
    lea     rdx, [g_MsgOK]
    ret
QuantumBeacon_Init ENDP

; =============================================================================
; QuantumBeacon_Shutdown
; =============================================================================
PUBLIC QuantumBeacon_Shutdown
ALIGN 16
QuantumBeacon_Shutdown PROC
    mov     dword ptr [g_FusionRunning], 0
    mov     dword ptr [g_BeaconInit], 0
    xor     eax, eax
    lea     rdx, [g_MsgOK]
    ret
QuantumBeacon_Shutdown ENDP

; =============================================================================
; QuantumBeacon_GetState — Returns AL=FusionState (0..6).
; =============================================================================
PUBLIC QuantumBeacon_GetState
ALIGN 16
QuantumBeacon_GetState PROC
    mov     al, byte ptr [g_FusionState]
    ret
QuantumBeacon_GetState ENDP

; =============================================================================
; QuantumBeacon_BeginFusion — Start fusion. Returns RAX=0 ok.
; =============================================================================
PUBLIC QuantumBeacon_BeginFusion
ALIGN 16
QuantumBeacon_BeginFusion PROC
    mov     eax, dword ptr [g_BeaconInit]
    test    eax, eax
    jz      @@err
    mov     byte ptr [g_FusionState], FUSION_STATE_CALIBRATING
    mov     dword ptr [g_FusionRunning], 1
    inc     qword ptr [g_BeaconEpoch]
    xor     eax, eax
    lea     rdx, [g_MsgOK]
    ret
@@err:
    mov     eax, 1
    lea     rdx, [g_MsgNotInit]
    ret
QuantumBeacon_BeginFusion ENDP

; =============================================================================
; QuantumBeacon_GetLatestBeacon — RDX=ptr to Beacon struct (32 bytes). Fill and return RAX=0.
; =============================================================================
PUBLIC QuantumBeacon_GetLatestBeacon
ALIGN 16
QuantumBeacon_GetLatestBeacon PROC
    test    rdx, rdx
    jz      @@z
    mov     rax, qword ptr [g_BeaconEpoch]
    mov     [rdx], rax
    mov     eax, dword ptr [g_BeaconOptimality]
    mov     [rdx+8], eax
    mov     eax, dword ptr [g_BeaconTemperature]
    mov     [rdx+12], eax
    mov     eax, dword ptr [g_BeaconEntropy]
    mov     [rdx+16], eax
    mov     eax, dword ptr [g_BeaconActiveEngines]
    mov     [rdx+20], eax
    call    _KernelTickCount
    mov     [rdx+24], rax
@@z:
    xor     eax, eax
    ret
QuantumBeacon_GetLatestBeacon ENDP

; =============================================================================
; QuantumBeacon_GetTelemetry — RDX=ptr to FusionTelemetry. Fill and return RAX=0.
; =============================================================================
PUBLIC QuantumBeacon_GetTelemetry
ALIGN 16
QuantumBeacon_GetTelemetry PROC
    test    rdx, rdx
    jz      @@z
    mov     al, byte ptr [g_FusionState]
    mov     [rdx], al
    mov     rax, qword ptr [g_BeaconEpoch]
    mov     [rdx+8], rax
    mov     eax, dword ptr [g_BeaconOptimality]
    mov     [rdx+16], eax
    mov     eax, dword ptr [g_BeaconTemperature]
    mov     [rdx+20], eax
@@z:
    xor     eax, eax
    ret
QuantumBeacon_GetTelemetry ENDP

; =============================================================================
; QuantumBeacon_ForceBeacon — Broadcast beacon now. Returns RAX=0 ok.
; =============================================================================
PUBLIC QuantumBeacon_ForceBeacon
ALIGN 16
QuantumBeacon_ForceBeacon PROC
    inc     qword ptr [g_BeaconEpoch]
    mov     byte ptr [g_FusionState], FUSION_STATE_BEACONING
    call    QuantumBeacon_BroadcastBeacon
    xor     eax, eax
    lea     rdx, [g_MsgOK]
    ret
QuantumBeacon_ForceBeacon ENDP

; -----------------------------------------------------------------------------
; QuantumBeacon_ComputeFitness — weighted sum of beta^2 over engines. Returns EAX = 0..FITNESS_SCALE.
; -----------------------------------------------------------------------------
QuantumBeacon_ComputeFitness PROC
    lea     r8, [g_EngineBeta]
    xor     eax, eax
    mov     ecx, ENGINE_COUNT
@@sum:
    movzx   r9d, byte ptr [r8]
    imul    r9d, r9d
    add     eax, r9d
    inc     r8
    dec     ecx
    jnz     @@sum
    ; sum of beta^2, beta in 0..255 -> max sum = 10*255*255 = 650250; scale to 0..1000
    mov     ecx, 650
    add     eax, 325
    xor     edx, edx
    div     ecx
    cmp     eax, FITNESS_SCALE
    jbe     @@cap
    mov     eax, FITNESS_SCALE
@@cap:
    ret
QuantumBeacon_ComputeFitness ENDP

; -----------------------------------------------------------------------------
; QuantumBeacon_AcceptTransition — RCX=cur_fit (0..1000), RDX=new_fit. Returns RAX=1 accept, 0 reject.
; -----------------------------------------------------------------------------
QuantumBeacon_AcceptTransition PROC
    mov     r10d, edx
    cmp     r10d, ecx
    jge     @@accept
    mov     r8d, dword ptr [g_SA_Temperature]
    ; tolerance = min(T/10, 200)
    mov     eax, r8d
    xor     edx, edx
    mov     r9d, 10
    div     r9d
    cmp     eax, 200
    jbe     @@tol_ok
    mov     eax, 200
@@tol_ok:
    ; accept if (cur - new) <= tolerance
    mov     r11d, ecx
    sub     r11d, r10d
    cmp     r11d, eax
    jbe     @@accept
    xor     eax, eax
    ret
@@accept:
    mov     eax, 1
    ret
QuantumBeacon_AcceptTransition ENDP

; -----------------------------------------------------------------------------
; QuantumBeacon_CoolDown — T = T * 995 / 1000; clamp to min.
; -----------------------------------------------------------------------------
QuantumBeacon_CoolDown PROC
    mov     eax, dword ptr [g_SA_Temperature]
    imul    eax, SA_COOLING_NUM
    xor     edx, edx
    mov     ecx, SA_COOLING_DEN
    div     ecx
    mov     ecx, dword ptr [g_SA_MinTemp]
    cmp     eax, ecx
    jae     @@ok
    mov     eax, ecx
@@ok:
    mov     dword ptr [g_SA_Temperature], eax
    ret
QuantumBeacon_CoolDown ENDP

; -----------------------------------------------------------------------------
; QuantumBeacon_Calibrate — set g_EngineBeta from engine telemetry (invocations low byte).
; -----------------------------------------------------------------------------
QuantumBeacon_Calibrate PROC
    lea     rsi, [g_EngineTelemetry]
    lea     rdi, [g_EngineBeta]
    mov     ecx, ENGINE_COUNT
@@cal:
    mov     rax, [rsi]
    movzx   eax, al
    test    al, al
    jnz     @@set
    mov     al, 128
@@set:
    mov     [rdi], al
    add     rsi, ENGINE_TELEMETRY_SIZE
    inc     rdi
    dec     ecx
    jnz     @@cal
    ret
QuantumBeacon_Calibrate ENDP

; -----------------------------------------------------------------------------
; QuantumBeacon_SuperpositionExplore — move beta toward telemetry target, then cool down.
; -----------------------------------------------------------------------------
QuantumBeacon_SuperpositionExplore PROC
    push    rbx
    push    rsi
    push    rdi
    sub     rsp, 32
    lea     rsi, [g_EngineTelemetry]
    lea     rdi, [g_EngineBeta]
    mov     ebx, dword ptr [g_SA_Temperature]
    ; step = (20 * T) / 10000 -> 0..20
    mov     eax, 20
    imul    ebx
    mov     ecx, 10000
    xor     edx, edx
    div     ecx
    mov     r8d, eax
    test    r8d, r8d
    jz      @@min_step
    jmp     @@loop
@@min_step:
    mov     r8d, 1
@@loop:
    mov     ecx, ENGINE_COUNT
@@eng:
    movzx   r9d, byte ptr [rsi]
    test    r9b, r9b
    jnz     @@tgt_ok
    mov     r9d, 128
@@tgt_ok:
    movzx   r10d, byte ptr [rdi]
    ; delta = (target - beta) * step / 100
    sub     r9d, r10d
    imul    r9d, r8d
    mov     eax, r9d
    mov     r11d, 100
    cdq
    idiv    r11d
    add     r10d, eax
    cmp     r10d, 255
    jbe     @@clamp_lo
    mov     r10d, 255
@@clamp_lo:
    test    r10d, r10d
    jns     @@store
    xor     r10d, r10d
@@store:
    mov     [rdi], r10b
    add     rsi, ENGINE_TELEMETRY_SIZE
    inc     rdi
    dec     ecx
    jnz     @@eng
    call    QuantumBeacon_CoolDown
    add     rsp, 32
    pop     rdi
    pop     rsi
    pop     rbx
    ret
QuantumBeacon_SuperpositionExplore ENDP

; -----------------------------------------------------------------------------
; QuantumBeacon_CollapseToOptimal — threshold 128; beta = 255 or 0.
; -----------------------------------------------------------------------------
QuantumBeacon_CollapseToOptimal PROC
    lea     rdi, [g_EngineBeta]
    mov     ecx, ENGINE_COUNT
@@c:
    movzx   eax, byte ptr [rdi]
    cmp     eax, 128
    jb      @@zero
    mov     byte ptr [rdi], 255
    jmp     @@nxt
@@zero:
    mov     byte ptr [rdi], 0
@@nxt:
    inc     rdi
    dec     ecx
    jnz     @@c
    ret
QuantumBeacon_CollapseToOptimal ENDP

; -----------------------------------------------------------------------------
; QuantumBeacon_BroadcastBeacon — write g_Beacon* into g_LatestBeacon, update globals.
; -----------------------------------------------------------------------------
QuantumBeacon_BroadcastBeacon PROC
    call    QuantumBeacon_ComputeFitness
    mov     dword ptr [g_BeaconOptimality], eax
    mov     eax, dword ptr [g_SA_Temperature]
    mov     dword ptr [g_BeaconTemperature], eax
    ; Entropy: count of engines with beta in (0,255) -> simplified: sum of (beta*(255-beta)) for spread
    lea     r8, [g_EngineBeta]
    xor     r9d, r9d
    mov     ecx, ENGINE_COUNT
@@ent:
    movzx   eax, byte ptr [r8]
    mov     edx, 255
    sub     edx, eax
    imul    eax, edx
    add     r9d, eax
    inc     r8
    dec     ecx
    jnz     @@ent
    mov     eax, r9d
    shr     eax, 8
    mov     dword ptr [g_BeaconEntropy], eax
    ; Active mask: bit i if beta >= 128
    xor     r9d, r9d
    lea     r8, [g_EngineBeta]
    mov     ecx, ENGINE_COUNT
    mov     r10d, 1
@@mask:
    movzx   eax, byte ptr [r8]
    cmp     eax, 128
    jb      @@skip
    or      r9d, r10d
@@skip:
    shl     r10d, 1
    inc     r8
    dec     ecx
    jnz     @@mask
    mov     dword ptr [g_BeaconActiveEngines], r9d
    ; Copy to g_LatestBeacon
    lea     rsi, [g_BeaconEpoch]
    lea     rdi, [g_LatestBeacon]
    mov     rax, [rsi]
    mov     [rdi], rax
    mov     eax, [rsi+8]
    mov     [rdi+8], eax
    mov     eax, [rsi+12]
    mov     [rdi+12], eax
    mov     eax, [rsi+16]
    mov     [rdi+16], eax
    mov     eax, [rsi+20]
    mov     [rdi+20], eax
    call    _KernelTickCount
    mov     [rdi+24], rax
    ret
QuantumBeacon_BroadcastBeacon ENDP

; =============================================================================
; QuantumBeacon_FusionStep — one state-machine step: calibrate -> superposition -> collapse -> broadcast.
; Call periodically when fusion is running. Returns RAX=0 ok.
; =============================================================================
PUBLIC QuantumBeacon_FusionStep
ALIGN 16
QuantumBeacon_FusionStep PROC
    cmp     dword ptr [g_FusionRunning], 0
    jz      @@out
    mov     al, byte ptr [g_FusionState]
    cmp     al, FUSION_STATE_CALIBRATING
    jz      @@cal
    cmp     al, FUSION_STATE_SUPERPOSITION
    jz      @@super
    cmp     al, FUSION_STATE_COLLAPSING
    jz      @@coll
    cmp     al, FUSION_STATE_BEACONING
    jz      @@beacon
    cmp     al, FUSION_STATE_ENTANGLED
    jz      @@ent
    cmp     al, FUSION_STATE_FAULTED
    jz      @@fault
    mov     byte ptr [g_FusionState], FUSION_STATE_CALIBRATING
    jmp     @@out
@@cal:
    call    QuantumBeacon_Calibrate
    inc     dword ptr [g_FusionSubStep]
    cmp     dword ptr [g_FusionSubStep], 2
    jb      @@out
    mov     dword ptr [g_FusionSubStep], 0
    mov     byte ptr [g_FusionState], FUSION_STATE_SUPERPOSITION
    mov     dword ptr [g_SA_Temperature], SA_INITIAL_TEMP
    jmp     @@out
@@super:
    call    QuantumBeacon_SuperpositionExplore
    mov     eax, dword ptr [g_SA_Temperature]
    mov     ecx, dword ptr [g_SA_MinTemp]
    shl     ecx, 2
    cmp     eax, ecx
    jbe     @@to_coll
    mov     eax, dword ptr [g_FusionSubStep]
    inc     dword ptr [g_FusionSubStep]
    and     eax, 01Fh
    jnz     @@out
@@to_coll:
    mov     byte ptr [g_FusionState], FUSION_STATE_COLLAPSING
    jmp     @@out
@@coll:
    call    QuantumBeacon_CollapseToOptimal
    mov     byte ptr [g_FusionState], FUSION_STATE_BEACONING
    jmp     @@out
@@beacon:
    call    QuantumBeacon_BroadcastBeacon
    inc     qword ptr [g_BeaconEpoch]
    mov     byte ptr [g_FusionState], FUSION_STATE_CALIBRATING
    mov     dword ptr [g_FusionSubStep], 0
    jmp     @@out
@@ent:
    ; No entanglement list in ASM; go straight to beaconing
    mov     byte ptr [g_FusionState], FUSION_STATE_BEACONING
    jmp     @@out
@@fault:
    mov     dword ptr [g_SA_Temperature], SA_INITIAL_TEMP
    mov     byte ptr [g_FusionState], FUSION_STATE_CALIBRATING
    mov     dword ptr [g_FusionSubStep], 0
@@out:
    xor     eax, eax
    ret
QuantumBeacon_FusionStep ENDP

; =============================================================================
; QuantumBeacon_DispatchCLI — RCX=command ptr, RDX=args ptr. Returns RAX=0 ok, RDX=detail.
; Commands: init, shutdown, begin, force, state
; =============================================================================
PUBLIC QuantumBeacon_DispatchCLI
ALIGN 16
QuantumBeacon_DispatchCLI PROC
    push    rbx
    push    rsi
    sub     rsp, 38h
    mov     rbx, rcx
    mov     rsi, rdx
    test    rbx, rbx
    jz      @@unknown
    ; Compare "init"
    lea     rcx, [g_CmdBeaconInit]
    mov     rdx, rbx
    mov     r8d, 4
    call    _KernelMemCmp
    test    eax, eax
    jz      @@do_init
    ; Compare "shutdown"
    lea     rcx, [g_CmdBeaconShutdown]
    mov     rdx, rbx
    mov     r8d, 8
    call    _KernelMemCmp
    test    eax, eax
    jz      @@do_shutdown
    ; Compare "begin"
    lea     rcx, [g_CmdBeaconBegin]
    mov     rdx, rbx
    mov     r8d, 5
    call    _KernelMemCmp
    test    eax, eax
    jz      @@do_begin
    ; Compare "force"
    lea     rcx, [g_CmdBeaconForce]
    mov     rdx, rbx
    mov     r8d, 5
    call    _KernelMemCmp
    test    eax, eax
    jz      @@do_force
    ; Compare "state"
    lea     rcx, [g_CmdBeaconState]
    mov     rdx, rbx
    mov     r8d, 5
    call    _KernelMemCmp
    test    eax, eax
    jz      @@do_state
    jmp     @@unknown
@@do_init:
    call    QuantumBeacon_Init
    jmp     @@ret
@@do_shutdown:
    call    QuantumBeacon_Shutdown
    jmp     @@ret
@@do_begin:
    call    QuantumBeacon_BeginFusion
    jmp     @@ret
@@do_force:
    call    QuantumBeacon_ForceBeacon
    jmp     @@ret
@@do_state:
    call    QuantumBeacon_GetState
    xor     eax, eax
    lea     rdx, [g_MsgOK]
    jmp     @@ret
@@unknown:
    mov     eax, ENGINE_RESULT_ERR
    lea     rdx, [g_MsgUnknownCommand]
@@ret:
    add     rsp, 38h
    pop     rsi
    pop     rbx
    ret
QuantumBeacon_DispatchCLI ENDP

_TEXT ENDS

END
 ; =============================================================================
; RawrXD_DynamicPromptEngine.asm — Context-Aware Prompt Generation Kernel
; =============================================================================
; Hardened implementation with all audit fixes applied:
;   FIX 1: 64-bit pointer math in template indexing
;   FIX 2: Proper substring matching in CountKeywordMatches
;   FIX 3: Correct little-endian marker detection
;   FIX 4: Proper calling convention (outsize via register)
;   FIX 5: Spinlock-guarded scratch buffer
;   FIX 6: ForceMode honored in AnalyzeContext
;   FIX 7: Density-scored classification with tie-break
;
; Classification Modes:
;   0x00 = GENERIC (default analytical)
;   0x01 = CASUAL  (slang/conversational)
;   0x02 = CODE    (technical review)
;   0x03 = SECURITY (vulnerability assessment)
;   0x04 = SHELL   (command analysis)
;   0x05 = ENTERPRISE (compliance-heavy)
;
; Exports:
;   PromptGen_AnalyzeContext  — Classify input text, return mode ID
;   PromptGen_BuildCritic    — Generate critic prompt for mode+context
;   PromptGen_BuildAuditor   — Generate auditor prompt for mode+context
;   PromptGen_Interpolate    — Inject context vars into template (public)
;   PromptGen_GetTemplate    — Retrieve raw template by ID
;   PromptGen_ForceMode      — Override auto-classification
;
; Rule:    NO CRT, NO HEAP, NO EXCEPTIONS
;          Fixed 8KB scratch buffer with spinlock
; Build:   ml64 /c /Zi /Fo RawrXD_DynamicPromptEngine.obj RawrXD_DynamicPromptEngine.asm
; =============================================================================

include RawrXD_Common.inc

