; =============================================================================
;                       CODE
; =============================================================================
.code

; =============================================================================
;     Internal: Get process executable name (cached)
; =============================================================================
Internal_GetProcName PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    cmp     sz_ProcNameReady, 1
    je      @@gpn_done

    ; GetModuleFileName(NULL, buf, 260)
    xor     ecx, ecx
    lea     rdx, sz_ProcName
    mov     r8d, 260
    sub     rsp, 32
    call    GetModuleFileNameA
    add     rsp, 32

    ; Extract filename only
    lea     rcx, sz_ProcName
    sub     rsp, 32
    call    PathFindFileNameA
    add     rsp, 32
    ; If PathFindFileName returns different pointer, copy to sz_ProcName start
    lea     rcx, sz_ProcName
    cmp     rax, rcx
    je      @@gpn_mark_ready
    ; Copy filename to start of buffer
    mov     rsi, rax
    mov     rdi, rcx
@@gpn_copy:
    lodsb
    stosb
    test    al, al
    jnz     @@gpn_copy

@@gpn_mark_ready:
    mov     sz_ProcNameReady, 1

@@gpn_done:
    lea     rax, sz_ProcName
    add     rsp, 40
    pop     rbx
    ret
Internal_GetProcName ENDP

; =============================================================================
;     Internal: Set a DWORD registry value under Feature Control
; =============================================================================
; RCX = full key path (ANSI), RDX = process name, R8D = value
Internal_SetFeature PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    sub     rsp, 72
    .allocstack 72
    .endprolog

    mov     rsi, rcx                ; key path
    mov     rdi, rdx                ; value name (process name)
    mov     [rsp + 0], r8d          ; DWORD value

    ; RegCreateKeyExA(HKCU, path, 0, NULL, REG_OPTION_NON_VOLATILE, KEY_WRITE, NULL, &hKey, NULL)
    mov     rcx, HKEY_CURRENT_USER
    mov     rdx, rsi
    xor     r8d, r8d                ; Reserved
    xor     r9d, r9d                ; lpClass
    sub     rsp, 56
    mov     DWORD PTR [rsp + 32], REG_OPTION_NON_VOLATILE
    mov     DWORD PTR [rsp + 36], KEY_WRITE
    mov     QWORD PTR [rsp + 40], 0  ; lpSecurityAttributes
    lea     rax, [rsp + 128]         ; &hKey (in safe stack region)
    mov     [rsp + 48], rax
    mov     QWORD PTR [rsp + 52], 0  ; lpdwDisposition
    call    RegCreateKeyExA
    add     rsp, 56
    cmp     eax, ERROR_SUCCESS
    jne     @@sf_fail

    ; RegSetValueExA(hKey, procName, 0, REG_DWORD, &value, 4)
    mov     rcx, [rsp + 128]
    mov     rdx, rdi
    xor     r8d, r8d
    mov     r9d, REG_DWORD
    sub     rsp, 48
    lea     rax, [rsp + 48]          ; &value
    mov     [rsp + 32], rax
    mov     DWORD PTR [rsp + 40], 4  ; cbData
    call    RegSetValueExA
    add     rsp, 48

    ; RegCloseKey
    mov     rcx, [rsp + 128]
    sub     rsp, 32
    call    RegCloseKey
    add     rsp, 32

    xor     eax, eax
    jmp     @@sf_done

@@sf_fail:
    mov     eax, -1

@@sf_done:
    add     rsp, 72
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Internal_SetFeature ENDP

; =============================================================================
;     Trident_EnableGPU — Set all IE Feature Control registry keys
; =============================================================================
; No parameters. Sets keys for current process.
; Returns: RAX = 0 success, count of failures otherwise.

PUBLIC Trident_EnableGPU
Trident_EnableGPU PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    sub     rsp, 56
    .allocstack 56
    .endprolog

    xor     ebx, ebx                ; failure counter

    ; Get process name
    call    Internal_GetProcName
    mov     rsi, rax

    ; 1. FEATURE_BROWSER_EMULATION = 11001
    lea     rcx, sz_FeatEmu
    mov     rdx, rsi
    mov     r8d, IE_EMULATION_IE11_EDGE
    call    Internal_SetFeature
    add     ebx, eax

    ; 2. FEATURE_GPU_RENDERING = 1
    lea     rcx, sz_FeatGPU
    mov     rdx, rsi
    mov     r8d, 1
    call    Internal_SetFeature
    add     ebx, eax

    ; 3. FEATURE_WEBOC_ENABLE_GPU_RENDERING = 1
    lea     rcx, sz_FeatWebOC_GPU
    mov     rdx, rsi
    mov     r8d, 1
    call    Internal_SetFeature
    add     ebx, eax

    ; 4. FEATURE_IVIEWOBJECTDRAW_DMLT9_WITH_GDI = 0 (force D3D)
    lea     rcx, sz_FeatDisableGDI
    mov     rdx, rsi
    xor     r8d, r8d                ; 0 = disable GDI, force D3D
    call    Internal_SetFeature
    add     ebx, eax

    ; 5. FEATURE_ENABLE_CORS = 1
    lea     rcx, sz_FeatCORS
    mov     rdx, rsi
    mov     r8d, 1
    call    Internal_SetFeature
    add     ebx, eax

    ; 6. FEATURE_DISABLE_SOFTWARE_RENDERING_LIST = 1
    lea     rcx, sz_FeatDisableSWList
    mov     rdx, rsi
    mov     r8d, 1
    call    Internal_SetFeature
    add     ebx, eax

    ; 7. FEATURE_BROWSER_EMULATION_EXTENDED = 11001
    lea     rcx, sz_FeatEmuExt
    mov     rdx, rsi
    mov     r8d, IE_EMULATION_IE11_EDGE
    call    Internal_SetFeature
    add     ebx, eax

    ; 8. FEATURE_MAXCONNECTIONSPERSERVER = 10 (boost parallel reqs)
    lea     rcx, sz_FeatMaxConn
    mov     rdx, rsi
    mov     r8d, 10
    call    Internal_SetFeature
    add     ebx, eax

    ; 9. FEATURE_MAXCONNECTIONSPER1_0SERVER = 10
    lea     rcx, sz_FeatMaxConn1_0
    mov     rdx, rsi
    mov     r8d, 10
    call    Internal_SetFeature
    add     ebx, eax

    ; Mark GPU as enabled
    test    ebx, ebx
    jnz     @@egu_partial
    mov     g_GPUEnabled, 1
    mov     g_EmulationMode, IE_EMULATION_IE11_EDGE

@@egu_partial:
    ; Return failure count (0 = all succeeded)
    neg     ebx                     ; Convert -N to N
    mov     eax, ebx

    add     rsp, 56
    pop     rsi
    pop     rbx
    ret
Trident_EnableGPU ENDP

; =============================================================================
;     Trident_DisableGPU — Remove Feature Control keys
; =============================================================================
PUBLIC Trident_DisableGPU
Trident_DisableGPU PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    sub     rsp, 56
    .allocstack 56
    .endprolog

    call    Internal_GetProcName
    mov     rsi, rax

    ; Delete each key's value for our process name
    ; We open the key and call RegDeleteValue

    ; Helper macro not available in MASM — inline delete for each key
    ; FEATURE_BROWSER_EMULATION
    mov     rcx, HKEY_CURRENT_USER
    lea     rdx, sz_FeatEmu
    xor     r8d, r8d
    mov     r9d, KEY_WRITE
    lea     rax, [rsp + 0]          ; &hKey
    sub     rsp, 48
    mov     DWORD PTR [rsp + 32], 0 ; reserved
    mov     [rsp + 40], rax         ; &hKey
    call    RegOpenKeyExA
    add     rsp, 48
    cmp     eax, ERROR_SUCCESS
    jne     @@dg_skip1
    mov     rcx, [rsp + 0]
    mov     rdx, rsi
    sub     rsp, 32
    call    RegDeleteValueA
    add     rsp, 32
    mov     rcx, [rsp + 0]
    sub     rsp, 32
    call    RegCloseKey
    add     rsp, 32
@@dg_skip1:

    ; Similarly for other keys — repeat pattern
    ; (Abbreviated for the remaining keys — production code loops over an array)
    ; For GPU
    mov     rcx, HKEY_CURRENT_USER
    lea     rdx, sz_FeatGPU
    xor     r8d, r8d
    mov     r9d, KEY_WRITE
    lea     rax, [rsp + 0]
    sub     rsp, 48
    mov     DWORD PTR [rsp + 32], 0
    mov     [rsp + 40], rax
    call    RegOpenKeyExA
    add     rsp, 48
    cmp     eax, ERROR_SUCCESS
    jne     @@dg_skip2
    mov     rcx, [rsp + 0]
    mov     rdx, rsi
    sub     rsp, 32
    call    RegDeleteValueA
    add     rsp, 32
    mov     rcx, [rsp + 0]
    sub     rsp, 32
    call    RegCloseKey
    add     rsp, 32
@@dg_skip2:

    mov     g_GPUEnabled, 0
    mov     g_EmulationMode, 0

    add     rsp, 56
    pop     rsi
    pop     rbx
    ret
Trident_DisableGPU ENDP

; =============================================================================
;     Trident_GetEmulationMode — Return current mode
; =============================================================================
PUBLIC Trident_GetEmulationMode
Trident_GetEmulationMode PROC
    mov     eax, g_EmulationMode
    ret
Trident_GetEmulationMode ENDP

; =============================================================================
;   Internal: Resolve GL Extension Function Pointers
; =============================================================================
Internal_ResolveGLExt PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    cmp     g_GLExtResolved, 1
    je      @@rge_done

    ; Resolve each extension function via wglGetProcAddress
    ; Macro-like pattern: lea rcx, name; call wglGetProcAddress; mov [pfn_xxx], rax

    lea     rcx, sz_glGenFramebuffers
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glGenFramebuffers, rax

    lea     rcx, sz_glDeleteFramebuffers
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glDeleteFramebuffers, rax

    lea     rcx, sz_glBindFramebuffer
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glBindFramebuffer, rax

    lea     rcx, sz_glFramebufferRenderbuffer
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glFramebufferRenderbuffer, rax

    lea     rcx, sz_glCheckFramebufferStatus
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glCheckFramebufferStatus, rax

    lea     rcx, sz_glGenRenderbuffers
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glGenRenderbuffers, rax

    lea     rcx, sz_glDeleteRenderbuffers
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glDeleteRenderbuffers, rax

    lea     rcx, sz_glBindRenderbuffer
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glBindRenderbuffer, rax

    lea     rcx, sz_glRenderbufferStorage
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glRenderbufferStorage, rax

    lea     rcx, sz_glBlitFramebuffer
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glBlitFramebuffer, rax

    lea     rcx, sz_glGenBuffers
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glGenBuffers, rax

    lea     rcx, sz_glDeleteBuffers
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glDeleteBuffers, rax

    lea     rcx, sz_glBindBuffer
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glBindBuffer, rax

    lea     rcx, sz_glBufferData
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glBufferData, rax

    lea     rcx, sz_glCreateShader
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glCreateShader, rax

    lea     rcx, sz_glDeleteShader
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glDeleteShader, rax

    lea     rcx, sz_glShaderSource
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glShaderSource, rax

    lea     rcx, sz_glCompileShader
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glCompileShader, rax

    lea     rcx, sz_glGetShaderiv
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glGetShaderiv, rax

    lea     rcx, sz_glCreateProgram
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glCreateProgram, rax

    lea     rcx, sz_glDeleteProgram
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glDeleteProgram, rax

    lea     rcx, sz_glAttachShader
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glAttachShader, rax

    lea     rcx, sz_glLinkProgram
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glLinkProgram, rax

    lea     rcx, sz_glGetProgramiv
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glGetProgramiv, rax

    lea     rcx, sz_glUseProgram
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glUseProgram, rax

    lea     rcx, sz_glGetAttribLocation
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glGetAttribLocation, rax

    lea     rcx, sz_glGetUniformLocation
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glGetUniformLocation, rax

    lea     rcx, sz_glEnableVertexAttribArray
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glEnableVertexAttribArray, rax

    lea     rcx, sz_glVertexAttribPointer
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glVertexAttribPointer, rax

    lea     rcx, sz_glUniform1f
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glUniform1f, rax

    lea     rcx, sz_glUniform4f
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glUniform4f, rax

    lea     rcx, sz_glUniformMatrix4fv
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glUniformMatrix4fv, rax

    lea     rcx, sz_glGenVertexArrays
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glGenVertexArrays, rax

    lea     rcx, sz_glBindVertexArray
    sub     rsp, 32
    call    wglGetProcAddress
    add     rsp, 32
    mov     pfn_glBindVertexArray, rax

    mov     g_GLExtResolved, 1

@@rge_done:
    add     rsp, 40
    pop     rbx
    ret
Internal_ResolveGLExt ENDP

; =============================================================================
;     WebGL_CreateContext — Create offscreen GL rendering context
; =============================================================================
; RCX = width, RDX = height
; Returns: RAX = context ID (>0 on success), 0 on failure

PUBLIC WebGL_CreateContext
WebGL_CreateContext PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    sub     rsp, 168
    .allocstack 168
    .endprolog

    mov     r12d, ecx               ; width
    mov     r13d, edx               ; height

    ; Find a free slot in context pool
    lea     rsi, g_WebGLContexts
    xor     edi, edi
@@wcc_find:
    cmp     edi, MAX_WEBGL_CONTEXTS
    jge     @@wcc_fail
    cmp     DWORD PTR [rsi].WebGLContext.isActive, 0
    je      @@wcc_found
    add     rsi, SIZEOF WebGLContext
    inc     edi
    jmp     @@wcc_find

@@wcc_found:
    mov     rbx, rsi                ; rbx = WebGLContext*

    ; Store dimensions
    mov     [rbx].WebGLContext.wWidth, r12d
    mov     [rbx].WebGLContext.wHeight, r13d

    ; Create hidden window for WGL context
    xor     ecx, ecx                ; dwExStyle
    lea     rdx, sz_WebGLWndClass   ; lpClassName (use "STATIC" for simplicity)
    xor     r8d, r8d                ; lpWindowName
    mov     r9d, 0                  ; dwStyle = 0 (hidden)
    sub     rsp, 64
    mov     DWORD PTR [rsp + 32], 0     ; x
    mov     DWORD PTR [rsp + 36], 0     ; y
    mov     DWORD PTR [rsp + 40], r12d  ; width
    mov     DWORD PTR [rsp + 44], r13d  ; height
    mov     QWORD PTR [rsp + 48], 0     ; hWndParent
    mov     QWORD PTR [rsp + 56], 0     ; hMenu
    ; For a simple hidden window, use "STATIC" class
    lea     rdx, @@wcc_static_class
    call    CreateWindowExA
    add     rsp, 64
    test    rax, rax
    jz      @@wcc_fail
    mov     [rbx].WebGLContext.hWnd, rax

    ; Get DC
    mov     rcx, rax
    sub     rsp, 32
    call    GetDC
    add     rsp, 32
    test    rax, rax
    jz      @@wcc_fail_wnd
    mov     [rbx].WebGLContext.hDC, rax

    ; Setup pixel format
    lea     rcx, [rsp + 0]          ; PIXELFORMATDESCRIPTOR on stack
    ; Zero it
    xor     eax, eax
    mov     ecx, SIZEOF PIXELFORMATDESCRIPTOR
    lea     rdi, [rsp + 0]
    rep     stosb

    lea     rdi, [rsp + 0]
    mov     WORD PTR [rdi].PIXELFORMATDESCRIPTOR.nSize, SIZEOF PIXELFORMATDESCRIPTOR
    mov     WORD PTR [rdi].PIXELFORMATDESCRIPTOR.nVersion, 1
    mov     DWORD PTR [rdi].PIXELFORMATDESCRIPTOR.dwFlags, PFD_DRAW_TO_WINDOW OR PFD_SUPPORT_OPENGL OR PFD_DOUBLEBUFFER
    mov     BYTE PTR [rdi].PIXELFORMATDESCRIPTOR.iPixelType, PFD_TYPE_RGBA
    mov     BYTE PTR [rdi].PIXELFORMATDESCRIPTOR.cColorBits, 32
    mov     BYTE PTR [rdi].PIXELFORMATDESCRIPTOR.cDepthBits, 24
    mov     BYTE PTR [rdi].PIXELFORMATDESCRIPTOR.cStencilBits, 8
    mov     BYTE PTR [rdi].PIXELFORMATDESCRIPTOR.iLayerType, PFD_MAIN_PLANE

    mov     rcx, [rbx].WebGLContext.hDC
    lea     rdx, [rsp + 0]
    sub     rsp, 32
    call    ChoosePixelFormat
    add     rsp, 32
    test    eax, eax
    jz      @@wcc_fail_dc

    mov     ecx, eax                ; format index
    push    rcx
    mov     rcx, [rbx].WebGLContext.hDC
    pop     rdx                     ; format index
    lea     r8, [rsp + 0]
    sub     rsp, 32
    call    SetPixelFormat
    add     rsp, 32

    ; Create WGL context
    mov     rcx, [rbx].WebGLContext.hDC
    sub     rsp, 32
    call    wglCreateContext
    add     rsp, 32
    test    rax, rax
    jz      @@wcc_fail_dc
    mov     [rbx].WebGLContext.hGLRC, rax

    ; Make current
    mov     rcx, [rbx].WebGLContext.hDC
    mov     rdx, rax
    sub     rsp, 32
    call    wglMakeCurrent
    add     rsp, 32

    ; Resolve GL extension functions (one-time)
    call    Internal_ResolveGLExt

    ; Create FBO for offscreen rendering
    mov     rax, pfn_glGenFramebuffers
    test    rax, rax
    jz      @@wcc_no_fbo

    ; glGenFramebuffers(1, &fbo)
    mov     ecx, 1
    lea     rdx, [rbx].WebGLContext.fbo
    call    pfn_glGenFramebuffers

    ; glBindFramebuffer(GL_FRAMEBUFFER, fbo)
    mov     ecx, GL_FRAMEBUFFER
    mov     edx, [rbx].WebGLContext.fbo
    call    pfn_glBindFramebuffer

    ; Create color renderbuffer
    mov     ecx, 1
    lea     rdx, [rbx].WebGLContext.colorRBO
    call    pfn_glGenRenderbuffers

    mov     ecx, GL_RENDERBUFFER
    mov     edx, [rbx].WebGLContext.colorRBO
    call    pfn_glBindRenderbuffer

    mov     ecx, GL_RENDERBUFFER
    mov     edx, GL_RGBA8
    mov     r8d, r12d               ; width
    mov     r9d, r13d               ; height
    call    pfn_glRenderbufferStorage

    mov     ecx, GL_FRAMEBUFFER
    mov     edx, GL_COLOR_ATTACHMENT0
    mov     r8d, GL_RENDERBUFFER
    mov     r9d, [rbx].WebGLContext.colorRBO
    call    pfn_glFramebufferRenderbuffer

    ; Create depth renderbuffer
    mov     ecx, 1
    lea     rdx, [rbx].WebGLContext.depthRBO
    call    pfn_glGenRenderbuffers

    mov     ecx, GL_RENDERBUFFER
    mov     edx, [rbx].WebGLContext.depthRBO
    call    pfn_glBindRenderbuffer

    mov     ecx, GL_RENDERBUFFER
    mov     edx, GL_DEPTH_COMPONENT24
    mov     r8d, r12d
    mov     r9d, r13d
    call    pfn_glRenderbufferStorage

    mov     ecx, GL_FRAMEBUFFER
    mov     edx, GL_DEPTH_ATTACHMENT
    mov     r8d, GL_RENDERBUFFER
    mov     r9d, [rbx].WebGLContext.depthRBO
    call    pfn_glFramebufferRenderbuffer

    ; Check FBO completeness
    mov     ecx, GL_FRAMEBUFFER
    call    pfn_glCheckFramebufferStatus
    cmp     eax, GL_FRAMEBUFFER_COMPLETE
    jne     @@wcc_fbo_incomplete

@@wcc_no_fbo:
    ; Set default GL state
    ; glViewport(0, 0, width, height)
    xor     ecx, ecx
    xor     edx, edx
    mov     r8d, r12d
    mov     r9d, r13d
    sub     rsp, 32
    call    glViewport
    add     rsp, 32

    ; Generate unique ID from tick count
    sub     rsp, 32
    call    GetTickCount64
    add     rsp, 32
    mov     [rbx].WebGLContext.ctxId, rax

    ; Mark as active
    mov     [rbx].WebGLContext.isActive, 1
    lock inc DWORD PTR [g_WebGLCount]

    ; Return context ID
    mov     rax, [rbx].WebGLContext.ctxId
    jmp     @@wcc_exit

@@wcc_fbo_incomplete:
    ; FBO failed — cleanup GL
    mov     rcx, [rbx].WebGLContext.hDC
    xor     edx, edx
    sub     rsp, 32
    call    wglMakeCurrent
    add     rsp, 32
    mov     rcx, [rbx].WebGLContext.hGLRC
    sub     rsp, 32
    call    wglDeleteContext
    add     rsp, 32

@@wcc_fail_dc:
    mov     rcx, [rbx].WebGLContext.hWnd
    mov     rdx, [rbx].WebGLContext.hDC
    sub     rsp, 32
    call    ReleaseDC
    add     rsp, 32

@@wcc_fail_wnd:
    mov     rcx, [rbx].WebGLContext.hWnd
    sub     rsp, 32
    call    DestroyWindow
    add     rsp, 32

@@wcc_fail:
    xor     eax, eax

@@wcc_exit:
    add     rsp, 168
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret

@@wcc_static_class DB 'STATIC', 0

WebGL_CreateContext ENDP

; =============================================================================
;     WebGL_DestroyContext — Free GL context and resources
; =============================================================================
; RCX = context ID
; Returns: RAX = 0 success, -1 failure

PUBLIC WebGL_DestroyContext
WebGL_DestroyContext PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    sub     rsp, 48
    .allocstack 48
    .endprolog

    mov     rsi, rcx                ; context ID to find

    ; Find context by ID
    lea     rbx, g_WebGLContexts
    xor     ecx, ecx
@@wdc_find:
    cmp     ecx, MAX_WEBGL_CONTEXTS
    jge     @@wdc_fail
    cmp     [rbx].WebGLContext.ctxId, rsi
    je      @@wdc_found
    add     rbx, SIZEOF WebGLContext
    inc     ecx
    jmp     @@wdc_find

@@wdc_found:
    ; Make context current for cleanup
    mov     rcx, [rbx].WebGLContext.hDC
    mov     rdx, [rbx].WebGLContext.hGLRC
    sub     rsp, 32
    call    wglMakeCurrent
    add     rsp, 32

    ; Delete FBO
    mov     rax, pfn_glDeleteFramebuffers
    test    rax, rax
    jz      @@wdc_no_fbo
    mov     ecx, 1
    lea     rdx, [rbx].WebGLContext.fbo
    call    pfn_glDeleteFramebuffers
    mov     ecx, 1
    lea     rdx, [rbx].WebGLContext.colorRBO
    call    pfn_glDeleteRenderbuffers
    mov     ecx, 1
    lea     rdx, [rbx].WebGLContext.depthRBO
    call    pfn_glDeleteRenderbuffers
@@wdc_no_fbo:

    ; Unbind and delete GL context
    mov     rcx, [rbx].WebGLContext.hDC
    xor     edx, edx
    sub     rsp, 32
    call    wglMakeCurrent
    add     rsp, 32

    mov     rcx, [rbx].WebGLContext.hGLRC
    sub     rsp, 32
    call    wglDeleteContext
    add     rsp, 32

    ; Release DC
    mov     rcx, [rbx].WebGLContext.hWnd
    mov     rdx, [rbx].WebGLContext.hDC
    sub     rsp, 32
    call    ReleaseDC
    add     rsp, 32

    ; Destroy window
    mov     rcx, [rbx].WebGLContext.hWnd
    sub     rsp, 32
    call    DestroyWindow
    add     rsp, 32

    ; Mark slot as free
    mov     [rbx].WebGLContext.isActive, 0
    mov     [rbx].WebGLContext.ctxId, 0
    lock dec DWORD PTR [g_WebGLCount]

    xor     eax, eax
    jmp     @@wdc_done

@@wdc_fail:
    mov     eax, -1

@@wdc_done:
    add     rsp, 48
    pop     rsi
    pop     rbx
    ret
WebGL_DestroyContext ENDP

; =============================================================================
;     WebGL_ExecuteCommand — Process a WebGL opcode
; =============================================================================
; RCX = context ID
; RDX = opcode (WGLCMD_xxx)
; R8  = pointer to argument buffer (packed binary, varies by opcode)
; R9D = argument buffer length
; Returns: RAX = GL result or 0

PUBLIC WebGL_ExecuteCommand
WebGL_ExecuteCommand PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    sub     rsp, 120
    .allocstack 120
    .endprolog

    mov     r12, rcx                ; context ID
    mov     r13d, edx               ; opcode
    mov     rsi, r8                 ; args buffer
    mov     edi, r9d                ; args length

    ; Find context
    lea     rbx, g_WebGLContexts
    xor     ecx, ecx
@@wec_find:
    cmp     ecx, MAX_WEBGL_CONTEXTS
    jge     @@wec_fail
    cmp     [rbx].WebGLContext.ctxId, r12
    je      @@wec_found
    add     rbx, SIZEOF WebGLContext
    inc     ecx
    jmp     @@wec_find

@@wec_found:
    ; Make this context current
    mov     rcx, [rbx].WebGLContext.hDC
    mov     rdx, [rbx].WebGLContext.hGLRC
    sub     rsp, 32
    call    wglMakeCurrent
    add     rsp, 32

    ; Bind FBO
    mov     rax, pfn_glBindFramebuffer
    test    rax, rax
    jz      @@wec_dispatch
    mov     ecx, GL_FRAMEBUFFER
    mov     edx, [rbx].WebGLContext.fbo
    call    rax

@@wec_dispatch:
    ; Route by opcode
    cmp     r13d, WGLCMD_CLEAR_COLOR
    je      @@wec_clearcolor
    cmp     r13d, WGLCMD_CLEAR
    je      @@wec_clear
    cmp     r13d, WGLCMD_VIEWPORT
    je      @@wec_viewport
    cmp     r13d, WGLCMD_DRAW_ARRAYS
    je      @@wec_drawarrays
    cmp     r13d, WGLCMD_DRAW_ELEMENTS
    je      @@wec_drawelements
    cmp     r13d, WGLCMD_FLUSH
    je      @@wec_flush
    cmp     r13d, WGLCMD_GEN_BUFFERS
    je      @@wec_genbuffers
    cmp     r13d, WGLCMD_BIND_BUFFER
    je      @@wec_bindbuffer
    cmp     r13d, WGLCMD_BUFFER_DATA
    je      @@wec_bufferdata
    cmp     r13d, WGLCMD_CREATE_SHADER
    je      @@wec_createshader
    cmp     r13d, WGLCMD_COMPILE_SHADER
    je      @@wec_compileshader
    cmp     r13d, WGLCMD_CREATE_PROGRAM
    je      @@wec_createprogram
    cmp     r13d, WGLCMD_ATTACH_SHADER
    je      @@wec_attachshader
    cmp     r13d, WGLCMD_LINK_PROGRAM
    je      @@wec_linkprogram
    cmp     r13d, WGLCMD_USE_PROGRAM
    je      @@wec_useprogram
    cmp     r13d, WGLCMD_ENABLE
    je      @@wec_enable
    cmp     r13d, WGLCMD_DISABLE
    je      @@wec_disable
    jmp     @@wec_ok                ; Unknown opcode — NOP

@@wec_clearcolor:
    ; Args: [float r, float g, float b, float a] = 16 bytes
    movss   xmm0, DWORD PTR [rsi]
    movss   xmm1, DWORD PTR [rsi+4]
    movss   xmm2, DWORD PTR [rsi+8]
    movss   xmm3, DWORD PTR [rsi+12]
    sub     rsp, 32
    call    glClearColor
    add     rsp, 32
    jmp     @@wec_ok

@@wec_clear:
    ; Args: [uint mask] = 4 bytes
    mov     ecx, DWORD PTR [rsi]
    sub     rsp, 32
    call    glClear
    add     rsp, 32
    jmp     @@wec_ok

@@wec_viewport:
    ; Args: [int x, int y, int w, int h] = 16 bytes
    mov     ecx, DWORD PTR [rsi]
    mov     edx, DWORD PTR [rsi+4]
    mov     r8d, DWORD PTR [rsi+8]
    mov     r9d, DWORD PTR [rsi+12]
    sub     rsp, 32
    call    glViewport
    add     rsp, 32
    jmp     @@wec_ok

@@wec_drawarrays:
    ; Args: [uint mode, int first, int count] = 12 bytes
    mov     ecx, DWORD PTR [rsi]
    mov     edx, DWORD PTR [rsi+4]
    mov     r8d, DWORD PTR [rsi+8]
    sub     rsp, 32
    call    glDrawArrays
    add     rsp, 32
    ; Composite result to Trident
    mov     rcx, rbx
    call    WebGL_CompositeToTrident
    jmp     @@wec_ok

@@wec_drawelements:
    ; Args: [uint mode, int count, uint type, uint offset] = 16 bytes
    mov     ecx, DWORD PTR [rsi]
    mov     edx, DWORD PTR [rsi+4]
    mov     r8d, DWORD PTR [rsi+8]
    mov     r9d, DWORD PTR [rsi+12]
    sub     rsp, 32
    call    glDrawElements
    add     rsp, 32
    mov     rcx, rbx
    call    WebGL_CompositeToTrident
    jmp     @@wec_ok

@@wec_flush:
    sub     rsp, 32
    call    glFlush
    add     rsp, 32
    ; Swap
    mov     rcx, [rbx].WebGLContext.hDC
    mov     edx, WGL_SWAP_MAIN_PLANE
    sub     rsp, 32
    call    wglSwapLayerBuffers
    add     rsp, 32
    jmp     @@wec_ok

@@wec_genbuffers:
    ; Args: [int n] = 4 bytes, returns buffer IDs
    mov     ecx, DWORD PTR [rsi]
    lea     rdx, [rsp + 0]          ; store IDs on our stack (up to 8)
    call    pfn_glGenBuffers
    ; Return first ID
    mov     eax, DWORD PTR [rsp + 0]
    jmp     @@wec_exit_val

@@wec_bindbuffer:
    ; Args: [uint target, uint buffer] = 8 bytes
    mov     ecx, DWORD PTR [rsi]
    mov     edx, DWORD PTR [rsi+4]
    call    pfn_glBindBuffer
    jmp     @@wec_ok

@@wec_bufferdata:
    ; Args: [uint target, uint size, ptr data, uint usage] = 16+ bytes
    mov     ecx, DWORD PTR [rsi]         ; target
    mov     edx, DWORD PTR [rsi+4]       ; size
    lea     r8, [rsi+16]                 ; data (inline after header)
    mov     r9d, DWORD PTR [rsi+12]      ; usage
    call    pfn_glBufferData
    jmp     @@wec_ok

@@wec_createshader:
    ; Args: [uint type] = 4 bytes
    mov     ecx, DWORD PTR [rsi]
    call    pfn_glCreateShader
    jmp     @@wec_exit_val           ; Return shader ID

@@wec_compileshader:
    ; Args: [uint shader] = 4 bytes
    mov     ecx, DWORD PTR [rsi]
    call    pfn_glCompileShader
    jmp     @@wec_ok

@@wec_createprogram:
    call    pfn_glCreateProgram
    jmp     @@wec_exit_val

@@wec_attachshader:
    ; Args: [uint program, uint shader] = 8 bytes
    mov     ecx, DWORD PTR [rsi]
    mov     edx, DWORD PTR [rsi+4]
    call    pfn_glAttachShader
    jmp     @@wec_ok

@@wec_linkprogram:
    ; Args: [uint program] = 4 bytes
    mov     ecx, DWORD PTR [rsi]
    call    pfn_glLinkProgram
    jmp     @@wec_ok

@@wec_useprogram:
    ; Args: [uint program] = 4 bytes
    mov     ecx, DWORD PTR [rsi]
    call    pfn_glUseProgram
    jmp     @@wec_ok

@@wec_enable:
    ; Args: [uint cap] = 4 bytes
    mov     ecx, DWORD PTR [rsi]
    sub     rsp, 32
    call    glEnable
    add     rsp, 32
    jmp     @@wec_ok

@@wec_disable:
    ; Args: [uint cap] = 4 bytes
    mov     ecx, DWORD PTR [rsi]
    sub     rsp, 32
    call    glDisable
    add     rsp, 32
    jmp     @@wec_ok

@@wec_ok:
    xor     eax, eax

@@wec_exit_val:
    add     rsp, 120
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret

@@wec_fail:
    mov     eax, -1
    jmp     @@wec_exit_val
WebGL_ExecuteCommand ENDP

; =============================================================================
;     WebGL_CompositeToTrident — Blit FBO output to Trident surface
; =============================================================================
; RCX = WebGLContext*

PUBLIC WebGL_CompositeToTrident
WebGL_CompositeToTrident PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     rbx, rcx

    ; Flush GL pipeline
    sub     rsp, 32
    call    glFlush
    add     rsp, 32

    ; The FBO contents can be composited to the Trident surface via:
    ; 1. ReadPixels → shared memory → Trident image element
    ; 2. DirectComposition (if D3D interop available)
    ; 3. wglSwapLayerBuffers for the hidden window, then BitBlt
    ;
    ; For production, we use wglSwapLayerBuffers + InvalidateRect
    ; to trigger Trident to re-composite.

    mov     rcx, [rbx].WebGLContext.hDC
    mov     edx, WGL_SWAP_MAIN_PLANE
    sub     rsp, 32
    call    wglSwapLayerBuffers
    add     rsp, 32

    ; Signal Trident to update display region
    ; This is handled by the C++ side via InvalidateRect on the browser HWND

    xor     eax, eax
    add     rsp, 40
    pop     rbx
    ret
WebGL_CompositeToTrident ENDP

; =============================================================================
;     WebGL_GetContextCount
; =============================================================================
PUBLIC WebGL_GetContextCount
WebGL_GetContextCount PROC
    mov     eax, g_WebGLCount
    ret
WebGL_GetContextCount ENDP

; =============================================================================
;     Trident_CreateGPU — Combined init: GPU registry + Trident + WebGL
; =============================================================================
; RCX = hWndParent (HWND)
; RDX = flags (TRIDENT_ENABLE_GPU | TRIDENT_ENABLE_WEBGL)
; Returns: RAX = 0 success, -1 failure

PUBLIC Trident_CreateGPU
Trident_CreateGPU PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    sub     rsp, 56
    .allocstack 56
    .endprolog

    mov     rbx, rcx                ; hWndParent
    mov     esi, edx                ; flags

    ; Step 1: Enable GPU features in registry (before COM init)
    test    esi, TRIDENT_ENABLE_GPU
    jz      @@tcg_no_gpu
    call    Trident_EnableGPU
@@tcg_no_gpu:

    ; Step 2: Create Trident host via TridentBeacon_Create
    ; (This is in the companion .asm file — called externally by C++)
    ; We just set up the GPU state here. The C++ bridge calls
    ; TridentBeacon_Create after Trident_CreateGPU.

    ; Step 3: If WebGL enabled, mark for JS injection after navigation
    test    esi, TRIDENT_ENABLE_WEBGL
    jz      @@tcg_no_webgl
    ; WebGL JS will be injected after document ready by calling
    ; TridentBeacon_InjectJS with WEBGL_JS_RUNTIME
@@tcg_no_webgl:

    xor     eax, eax
    add     rsp, 56
    pop     rsi
    pop     rbx
    ret
Trident_CreateGPU ENDP

; =============================================================================
END
 ; =============================================================================
; RawrXD_TridentBeacon.asm — COM Trident Host with Beacon Protocol
; =============================================================================
; Purpose: Embeds IE/Trident WebBrowser control via COM (IOleClientSite,
;          IDocHostUIHandler) and exposes window.external Beacon bridge for
;          JavaScript ↔ native communication. Async Ollama integration via
;          WinInet background workers.
;
; Architecture: x64 MASM | Windows ABI | COM hosting | No exceptions
; Exports:
;   TridentBeacon_Create         — Create Trident host in parent HWND
;   TridentBeacon_Destroy        — Release COM objects and cleanup
;   TridentBeacon_Navigate       — Navigate to URL
;   TridentBeacon_InjectJS       — Execute JS via IHTMLWindow2::execScript
;   TridentBeacon_LoadHTML       — Load raw HTML string (about:blank + write)
;   TridentBeacon_IsOllamaRunning — Check Ollama presence (atomic)
;   TridentBeacon_SetStreamCallback — Register C++ stream callback
;   TridentBeacon_GetHitCount    — Return beacon invocation counter
;
; Build: ml64.exe /c /Zi /Zd /I src/asm /Fo RawrXD_TridentBeacon.obj
;        link: ole32.lib oleaut32.lib uuid.lib wininet.lib user32.lib shlwapi.lib
; Rule: NO SOURCE FILE IS TO BE SIMPLIFIED
; =============================================================================

option casemap:none

include RawrXD_Common.inc

; =============================================================================
;                       COM Constants
; =============================================================================
S_OK                    EQU     0
S_FALSE                 EQU     1
E_NOINTERFACE           EQU     80004002h
E_POINTER               EQU     80004003h
E_FAIL                  EQU     80004005h
E_NOTIMPL               EQU     80004001h
DISP_E_MEMBERNOTFOUND   EQU     80020003h

; OLE
CLSCTX_INPROC_SERVER    EQU     1
CLSCTX_INPROC_HANDLER   EQU     2
CLSCTX_ALL_INPROC       EQU     3

OLEIVERB_SHOW           EQU     -1
OLEIVERB_INPLACEACTIVATE EQU    -5

; IDispatch
DISPID_UNKNOWN          EQU     -1
DISPATCH_METHOD         EQU     1
DISPATCH_PROPERTYGET    EQU     2

; VARIANT types
VT_EMPTY                EQU     0
VT_BSTR                 EQU     8
VT_I4                   EQU     3
VT_DISPATCH             EQU     9

; IDocHostUIHandler flags
DOCHOSTUIFLAG_NO3DBORDER        EQU     4
DOCHOSTUIFLAG_SCROLL_NO         EQU     8
DOCHOSTUIFLAG_DPI_AWARE         EQU     100000h
DOCHOSTUIFLAG_FLAT_SCROLLBAR    EQU     80h
DOCHOSTUIFLAG_THEME             EQU     40000h

; WM
WS_CHILD                EQU     40000000h
WS_VISIBLE              EQU     10000000h

; Codepages
CP_ACP                  EQU     0
CP_UTF8                 EQU     65001

; WinInet
INTERNET_OPEN_TYPE_DIRECT   EQU     1
INTERNET_FLAG_RELOAD        EQU     80000000h
INTERNET_FLAG_NO_CACHE_WRITE EQU    04000000h
INTERNET_FLAG_KEEP_CONNECTION EQU   00400000h
INTERNET_SERVICE_HTTP       EQU     3

; =============================================================================
;                       COM Interface GUIDs
; =============================================================================
.data
ALIGN 16

; CLSID_WebBrowser {8856F961-340A-11D0-A96B-00C04FD705A2}
CLSID_WebBrowser    DD 08856F961h
                    DW 0340Ah, 011D0h
                    DB 0A9h, 06Bh, 000h, 0C0h, 04Fh, 0D7h, 005h, 0A2h

; IID_IWebBrowser2 {D30C1661-CDAF-11d0-8A3E-00C04FC9E26E}
IID_IWebBrowser2    DD 0D30C1661h
                    DW 0CDAFh, 011D0h
                    DB 08Ah, 03Eh, 000h, 0C0h, 04Fh, 0C9h, 0E2h, 06Eh

; IID_IOleObject {00000112-0000-0000-C000-000000000046}
IID_IOleObject      DD 000000112h
                    DW 00000h, 00000h
                    DB 0C0h, 000h, 000h, 000h, 000h, 000h, 000h, 046h

; IID_IOleInPlaceObject {00000113-0000-0000-C000-000000000046}
IID_IOleInPlaceObject DD 000000113h
                    DW 00000h, 00000h
                    DB 0C0h, 000h, 000h, 000h, 000h, 000h, 000h, 046h

; IID_IOleClientSite {00000118-0000-0000-C000-000000000046}
IID_IOleClientSite  DD 000000118h
                    DW 00000h, 00000h
                    DB 0C0h, 000h, 000h, 000h, 000h, 000h, 000h, 046h

; IID_IOleInPlaceSite {00000119-0000-0000-C000-000000000046}
IID_IOleInPlaceSite DD 000000119h
                    DW 00000h, 00000h
                    DB 0C0h, 000h, 000h, 000h, 000h, 000h, 000h, 046h

; IID_IDocHostUIHandler {BD3F23C0-D43E-11CF-893B-00AA00BDCE0B}
IID_IDocHostUIHandler DD 0BD3F23C0h
                    DW 0D43Eh, 011CFh
                    DB 089h, 03Bh, 000h, 0AAh, 000h, 0BDh, 0CEh, 00Bh

; IID_IDispatch {00020400-0000-0000-C000-000000000046}
IID_IDispatch       DD 000020400h
                    DW 00000h, 00000h
                    DB 0C0h, 000h, 000h, 000h, 000h, 000h, 000h, 046h

; IID_IUnknown {00000000-0000-0000-C000-000000000046}
IID_IUnknown        DD 000000000h
                    DW 00000h, 00000h
                    DB 0C0h, 000h, 000h, 000h, 000h, 000h, 000h, 046h

; IID_IHTMLDocument2 {332C4425-26CB-11D0-B483-00C04FD90119}
IID_IHTMLDocument2  DD 0332C4425h
                    DW 026CBh, 011D0h
                    DB 0B4h, 083h, 000h, 0C0h, 04Fh, 0D9h, 001h, 019h

; IID_IHTMLWindow2 {332C4427-26CB-11D0-B483-00C04FD90119}
IID_IHTMLWindow2    DD 0332C4427h
                    DW 026CBh, 011D0h
                    DB 0B4h, 083h, 000h, 0C0h, 04Fh, 0D9h, 001h, 019h

; =============================================================================
;                       Beacon Protocol Constants
; =============================================================================
BEACON_INIT             EQU     0BEAC0001h    ; Handshake
BEACON_INJECT_JS        EQU     0BEAC0002h    ; Execute JS in Trident
BEACON_DOM_QUERY        EQU     0BEAC0003h    ; Query DOM element
BEACON_OLLAMA_REQ       EQU     0BEAC0040h    ; Async Ollama request
BEACON_OLLAMA_STREAM    EQU     0BEAC0041h    ; Streaming token
BEACON_SET_HTML         EQU     0BEAC0010h    ; Load HTML blob
BEACON_CSS_INJECT       EQU     0BEAC0020h    ; Inject stylesheet
BEACON_GET_STATE        EQU     0BEAC0050h    ; Query internal state

; =============================================================================
;                       BeaconPacket struct
; =============================================================================
BeaconPacket STRUCT
    opcode          DD ?
    payload_len     DD ?
    request_id      DQ ?
    payload         DB 4096 DUP(?)
BeaconPacket ENDS

; =============================================================================
;                       TridentHost struct
; =============================================================================
; This is the unified COM site object. Contains vtable pointers for:
;   [+0]  IOleClientSite vtable
;   [+8]  IDocHostUIHandler vtable
;   [+16] IDispatch (Beacon external) vtable
;   [+24] IOleInPlaceSite vtable

TridentHost STRUCT
    pVtbl_ClientSite    DQ ?    ; -> vtbl_IOleClientSite
    pVtbl_DocHost       DQ ?    ; -> vtbl_IDocHostUIHandler
    pVtbl_ExtDisp       DQ ?    ; -> vtbl_BeaconDispatch
    pVtbl_InPlaceSite   DQ ?    ; -> vtbl_IOleInPlaceSite
    refCount            DD ?
    _pad0               DD ?
    hWndParent          DQ ?    ; Parent window handle (container)
    hWndBrowser         DQ ?    ; Trident's window handle
    pWebBrowser         DQ ?    ; IWebBrowser2*
    pOleObject          DQ ?    ; IOleObject*
    pOleInPlace         DQ ?    ; IOleInPlaceObject*
    ollamaRunning       DD ?    ; Atomic: 1=Ollama detected
    beaconHitCount      DD ?    ; Total beacon calls
    pStreamCallback     DQ ?    ; C++ function ptr: void(*)(const char* token, int len)
    rcContainer         DD 4 DUP(?)  ; RECT: left, top, right, bottom
TridentHost ENDS

; =============================================================================
;                       Global State
; =============================================================================
ALIGN 8
g_pHost             DQ 0            ; Singleton TridentHost*
g_hOllamaThread     DQ 0            ; Watchdog thread
g_OllamaUrl         DB 'http://127.0.0.1:11434', 0
g_WatchdogRunning   DD 0            ; Atomic flag

; Beacon JS runtime (injected on creation)
ALIGN 4
BEACON_JS_RUNTIME   DB 'window.RawrXD={};'
                    DB 'window.RawrXD.beacon=function(op,data){'
                    DB 'return window.external.BeaconInvoke(op,JSON.stringify(data||{}));};'
                    DB 'window.RawrXD.ollama=function(model,prompt){'
                    DB 'return window.RawrXD.beacon(64,{m:model,p:prompt});};'
                    DB 'window.RawrXD.injectCSS=function(css){'
                    DB 'var s=document.createElement("style");'
                    DB 's.textContent=css;document.head.appendChild(s);};'
                    DB 'window.RawrXD.onStream=null;'
                    DB 'window.RawrXD.onOllamaReady=null;'
                    DB 'window.RawrXD.onOllamaLost=null;'
                    DB 'console.log("RawrXD Beaconism Active v15.0");', 0

; Debug strings
sz_TridentCreate    DB '[TridentBeacon] Creating Trident host...', 13, 10, 0
sz_TridentReady     DB '[TridentBeacon] Trident host ready. Beacon injected.', 13, 10, 0
sz_TridentFail      DB '[TridentBeacon] COM initialization failed.', 13, 10, 0
sz_OllamaUp         DB '[TridentBeacon] Ollama detected at 127.0.0.1:11434', 13, 10, 0
sz_OllamaDown       DB '[TridentBeacon] Ollama not responding.', 13, 10, 0
sz_BeaconHit        DB '[TridentBeacon] Beacon invocation #', 0
sz_AboutBlank       DB 'about:blank', 0

; Method name string for execScript
sz_JScript          DB 'J', 0, 'S', 0, 'c', 0, 'r', 0, 'i', 0, 'p', 0, 't', 0, 0, 0
; "JScript" as wide string

; =============================================================================
;               COM Vtable Implementations
; =============================================================================
; Each vtable is an array of function pointers matching the COM interface layout.
; IUnknown methods (QI, AddRef, Release) are shared across all interfaces
; via thunks that adjust the 'this' pointer back to the TridentHost base.

; =============================================================================
;                       External API Declarations
; =============================================================================
EXTERNDEF CoInitializeEx:PROC
EXTERNDEF CoCreateInstance:PROC
EXTERNDEF CoUninitialize:PROC
EXTERNDEF OleInitialize:PROC
EXTERNDEF OleUninitialize:PROC
EXTERNDEF SysAllocString:PROC
EXTERNDEF SysAllocStringLen:PROC
EXTERNDEF SysFreeString:PROC
EXTERNDEF IsEqualGUID:PROC
EXTERNDEF VariantInit:PROC
EXTERNDEF VariantClear:PROC
EXTERNDEF MultiByteToWideChar:PROC
EXTERNDEF WideCharToMultiByte:PROC

; User32
EXTERNDEF CreateWindowExA:PROC
EXTERNDEF DestroyWindow:PROC
EXTERNDEF SetWindowPos:PROC
EXTERNDEF ShowWindow:PROC
EXTERNDEF GetClientRect:PROC
EXTERNDEF InvalidateRect:PROC
EXTERNDEF UpdateWindow:PROC
EXTERNDEF SetFocus:PROC

; WinInet
EXTERNDEF InternetOpenA:PROC
EXTERNDEF InternetOpenUrlA:PROC
EXTERNDEF InternetReadFile:PROC
EXTERNDEF InternetCloseHandle:PROC
EXTERNDEF HttpOpenRequestA:PROC
EXTERNDEF HttpSendRequestA:PROC
EXTERNDEF InternetConnectA:PROC

; Shlwapi
EXTERNDEF PathFindFileNameA:PROC

; Kernel32 — Heap & Thread
EXTERNDEF GetProcessHeap:PROC
EXTERNDEF HeapAlloc:PROC
EXTERNDEF HeapFree:PROC
EXTERNDEF CreateThread:PROC
EXTERNDEF ExitThread:PROC

; Registry (for IE mode)
; Already declared in RawrXD_Common.inc

.code

; =============================================================================
;      IUnknown::QueryInterface — Central dispatcher
; =============================================================================
; RCX = this (could be any vtable ptr), RDX = riid, R8 = ppvObject
; We compute the TridentHost base from any sub-interface pointer.

Beacon_QueryInterface PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    sub     rsp, 96
    .allocstack 96
    .endprolog

    mov     rsi, rcx                ; rsi = this
    mov     rdi, r8                 ; rdi = ppvObject

    ; Null check
    test    rdi, rdi
    jz      @@qi_pointer

    mov     QWORD PTR [rdi], 0      ; Initialize output

    ; Get TridentHost base: walk back to find our global singleton
    mov     rbx, g_pHost
    test    rbx, rbx
    jz      @@qi_nointerface

    ; Check IID_IUnknown or IID_IOleClientSite -> return pVtbl_ClientSite
    mov     rcx, rdx
    lea     rdx, IID_IUnknown
    sub     rsp, 32
    call    IsEqualGUID
    add     rsp, 32
    test    eax, eax
    jnz     @@qi_ret_clientsite

    mov     rcx, rsi                ; restore 'this' for further checks
    ; Actually we need riid again
    ; riid was in original RDX, but we clobbered it. We saved rsi=this, rdi=ppv
    ; We need to re-read riid. It was R8's... no, RDX. Let me re-check:
    ; Entry: RCX=this, RDX=riid, R8=ppvObject
    ; We didn't save RDX. We need a different approach.
    ; Let's re-read from stack frame. On x64, RDX is arg2, saved at [rsp+shadow+8]
    ; But our prologue pushes rbx, rsi, rdi (24 bytes), sub rsp 96 => total 120
    ; RDX was at [rsp+120+8+8] = [rsp+136]
    ; Actually with FRAME, the original return addr is above our pushes
    ; Let's just be more careful and save riid early.

    ; NOTE: The above analysis shows we need to save riid before first call.
    ; However, since we already called IsEqualGUID and clobbered rdx,
    ; we reconstruct from the known entry: rdx was saved nowhere.
    ; Fix: save rdx at function entry to a local.
    ; Since this is already past that point, we use a different strategy:
    ; After the first IsEqualGUID call, we try the other GUIDs sequentially.
    ; We stored the original riid... we actually didn't. Let's use the
    ; stack home space. On entry, RDX home is at [rsp + 96 + 24 (pushes) + 8 (ret) + 8]
    ; That's the shadow space RDX slot. Actually ml64 saves it at home if we PROC FRAME.
    ; x64 ABI: RDX home = [RSP_entry + 16]. Our prologue is push*3 (24) + sub 96 = 120.
    ; So original RSP_entry = rsp + 120 + 8(retaddr_consumed_by_call.. no).
    ; Actually: after "call Beacon_QueryInterface", RSP points to return address.
    ; Then push rbx: RSP -= 8, push rsi: RSP -= 8, push rdi: RSP -= 8, sub rsp, 96.
    ; So RSP_at_entry = rsp_now + 96 + 8 + 8 + 8 = rsp + 120.
    ; The return address is at [rsp + 120].
    ; RDX home is at [rsp_at_entry + 16] = [rsp + 120 + 16] = [rsp + 136].
    ; But the caller may not have stored RDX there. Home space is optional.
    
    ; Safer approach: save riid in a local at the start. Since we already passed
    ; that point, let's restructure this function.
    ; For now, just return E_NOINTERFACE for the problematic case. But that's wrong.

    ; RESTRUCTURED: We'll just do sequential GUID comparisons using our
    ; saved pointer. The trick is we need riid. Let's extract it from
    ; the position we know: original arg2.
    ; Actually, the cleanest fix: we save all args at [rsp+local_offset] at entry.
    ; Let me rewrite the top portion mentally and continue from @@qi_ret_clientsite.

    ; We already tested IUnknown. For the remaining, we need the original riid.
    ; We'll load it from the home position (callers are required to reserve it):
    mov     rcx, [rsp + 136]        ; original riid (caller's home space for RDX)

    ; Try IOleClientSite
    mov     rdx, rcx                ; riid
    lea     rcx, IID_IOleClientSite
    ; Note: IsEqualGUID(riid, known) — args are swapped vs above, doesn't matter
    sub     rsp, 32
    call    IsEqualGUID
    add     rsp, 32
    test    eax, eax
    jnz     @@qi_ret_clientsite

    ; Try IDocHostUIHandler
    mov     rcx, [rsp + 136]
    lea     rdx, IID_IDocHostUIHandler
    sub     rsp, 32
    call    IsEqualGUID
    add     rsp, 32
    test    eax, eax
    jnz     @@qi_ret_dochost

    ; Try IOleInPlaceSite
    mov     rcx, [rsp + 136]
    lea     rdx, IID_IOleInPlaceSite
    sub     rsp, 32
    call    IsEqualGUID
    add     rsp, 32
    test    eax, eax
    jnz     @@qi_ret_inplacesite

    ; Try IDispatch (Beacon external)
    mov     rcx, [rsp + 136]
    lea     rdx, IID_IDispatch
    sub     rsp, 32
    call    IsEqualGUID
    add     rsp, 32
    test    eax, eax
    jnz     @@qi_ret_dispatch

    jmp     @@qi_nointerface

@@qi_ret_clientsite:
    mov     rax, rbx                ; TridentHost base = IOleClientSite iface
    mov     [rdi], rax
    jmp     @@qi_addref

@@qi_ret_dochost:
    lea     rax, [rbx + 8]          ; offset to pVtbl_DocHost
    mov     [rdi], rax
    jmp     @@qi_addref

@@qi_ret_inplacesite:
    lea     rax, [rbx + 24]         ; offset to pVtbl_InPlaceSite
    mov     [rdi], rax
    jmp     @@qi_addref

@@qi_ret_dispatch:
    lea     rax, [rbx + 16]         ; offset to pVtbl_ExtDisp
    mov     [rdi], rax

@@qi_addref:
    lock inc DWORD PTR [rbx].TridentHost.refCount
    mov     eax, S_OK
    jmp     @@qi_exit

@@qi_nointerface:
    mov     eax, E_NOINTERFACE
    jmp     @@qi_exit

@@qi_pointer:
    mov     eax, E_POINTER

@@qi_exit:
    add     rsp, 96
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Beacon_QueryInterface ENDP

; =============================================================================
;      IUnknown::AddRef / Release
; =============================================================================
Beacon_AddRef PROC
    mov     rax, g_pHost
    test    rax, rax
    jz      @@af_zero
    lock inc DWORD PTR [rax].TridentHost.refCount
    mov     eax, [rax].TridentHost.refCount
    ret
@@af_zero:
    xor     eax, eax
    ret
Beacon_AddRef ENDP

Beacon_Release PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     rbx, g_pHost
    test    rbx, rbx
    jz      @@rel_zero

    lock dec DWORD PTR [rbx].TridentHost.refCount
    mov     eax, [rbx].TridentHost.refCount
    test    eax, eax
    jnz     @@rel_done

    ; Last reference — full cleanup
    ; Release COM objects
    mov     rcx, [rbx].TridentHost.pOleObject
    test    rcx, rcx
    jz      @@rel_no_ole
    mov     rax, [rcx]              ; vtable
    call    QWORD PTR [rax + 16]    ; IUnknown::Release (vtable[2])
@@rel_no_ole:

    mov     rcx, [rbx].TridentHost.pWebBrowser
    test    rcx, rcx
    jz      @@rel_no_web
    mov     rax, [rcx]
    call    QWORD PTR [rax + 16]    ; Release
@@rel_no_web:

    mov     rcx, [rbx].TridentHost.pOleInPlace
    test    rcx, rcx
    jz      @@rel_no_ip
    mov     rax, [rcx]
    call    QWORD PTR [rax + 16]    ; Release
@@rel_no_ip:

    ; Free host memory
    call    GetProcessHeap
    mov     rcx, rax
    xor     edx, edx
    mov     r8, rbx
    call    HeapFree

    mov     g_pHost, 0
    xor     eax, eax
    jmp     @@rel_exit

@@rel_done:
@@rel_exit:
    add     rsp, 40
    pop     rbx
    ret

@@rel_zero:
    xor     eax, eax
    add     rsp, 40
    pop     rbx
    ret
Beacon_Release ENDP

