OIPS_OnInPlaceActivate ENDP

OIPS_OnUIActivate PROC
    xor     eax, eax
    ret
OIPS_OnUIActivate ENDP

OIPS_GetWindowContext PROC FRAME
    ; RCX = this
    ; RDX = ppFrame (IOleInPlaceFrame**)
    ; R8  = ppDoc (IOleInPlaceUIWindow**)
    ; R9  = lprcPosRect (LPRECT)
    ; [rsp+40] = lprcClipRect (LPRECT)
    ; [rsp+48] = lpFrameInfo (LPOLEINPLACEFRAMEINFO)
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    ; We don't provide frame/doc — set to NULL
    test    rdx, rdx
    jz      @@gwc_noframe
    mov     QWORD PTR [rdx], 0
@@gwc_noframe:
    test    r8, r8
    jz      @@gwc_nodoc
    mov     QWORD PTR [r8], 0
@@gwc_nodoc:

    ; Fill position rect from host's stored rect
    test    r9, r9
    jz      @@gwc_norect
    mov     rbx, g_pHost
    test    rbx, rbx
    jz      @@gwc_norect
    lea     rax, [rbx].TridentHost.rcContainer
    mov     ecx, [rax]              ; left
    mov     [r9], ecx
    mov     ecx, [rax+4]            ; top
    mov     [r9+4], ecx
    mov     ecx, [rax+8]            ; right
    mov     [r9+8], ecx
    mov     ecx, [rax+12]           ; bottom
    mov     [r9+12], ecx
@@gwc_norect:

    ; Fill clip rect same as pos rect
    mov     rax, [rsp + 40 + 40 + 8]  ; lprcClipRect (5th arg, stack)
    test    rax, rax
    jz      @@gwc_noclip
    mov     rbx, g_pHost
    test    rbx, rbx
    jz      @@gwc_noclip
    lea     rcx, [rbx].TridentHost.rcContainer
    mov     edx, [rcx]
    mov     [rax], edx
    mov     edx, [rcx+4]
    mov     [rax+4], edx
    mov     edx, [rcx+8]
    mov     [rax+8], edx
    mov     edx, [rcx+12]
    mov     [rax+12], edx
@@gwc_noclip:

    xor     eax, eax                ; S_OK
    add     rsp, 40
    pop     rbx
    ret
OIPS_GetWindowContext ENDP

OIPS_Scroll PROC
    mov     eax, E_NOTIMPL
    ret
OIPS_Scroll ENDP

