; =============================================================================
;      IDispatch (BeaconDispatch) — window.external bridge
; =============================================================================
; Vtable: [0] QI, [8] AddRef, [16] Release,
;   [24] GetTypeInfoCount, [32] GetTypeInfo,
;   [40] GetIDsOfNames, [48] Invoke

BD_GetTypeInfoCount PROC
    ; RCX = this, RDX = pctinfo
    test    rdx, rdx
    jz      @@gtc_fail
    mov     DWORD PTR [rdx], 0      ; We provide no type info
    xor     eax, eax
    ret
@@gtc_fail:
    mov     eax, E_POINTER
    ret
BD_GetTypeInfoCount ENDP

BD_GetTypeInfo PROC
    mov     eax, E_NOTIMPL
    ret
BD_GetTypeInfo ENDP

BD_GetIDsOfNames PROC FRAME
    ; RCX = this
    ; RDX = riid
    ; R8  = rgszNames (LPOLESTR*)
    ; R9  = cNames
    ; [rsp+40] = rgDispId (DISPID*)
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    sub     rsp, 40
    .allocstack 40
    .endprolog

    ; We support one method: "BeaconInvoke" -> DISPID 1
    mov     rsi, r8                 ; rgszNames
    mov     rbx, [rsp + 40 + 16 + 8 + 40]  ; rgDispId (5th arg)

    ; Get first name
    mov     rcx, [rsi]              ; first OLESTR

    ; Check if it matches "BeaconInvoke" (wide string comparison)
    ; Quick check: first 2 chars = 'B','e' (0x0042, 0x0065)
    cmp     WORD PTR [rcx], 42h     ; 'B'
    jne     @@gidn_unknown
    cmp     WORD PTR [rcx+2], 65h   ; 'e'
    jne     @@gidn_unknown
    cmp     WORD PTR [rcx+4], 61h   ; 'a'
    jne     @@gidn_unknown
    cmp     WORD PTR [rcx+6], 63h   ; 'c'
    jne     @@gidn_unknown
    cmp     WORD PTR [rcx+8], 6Fh   ; 'o'
    jne     @@gidn_unknown
    cmp     WORD PTR [rcx+10], 6Eh  ; 'n'
    jne     @@gidn_unknown

    ; Match: "Beacon..." — assign DISPID 1
    mov     DWORD PTR [rbx], 1
    xor     eax, eax
    jmp     @@gidn_exit

@@gidn_unknown:
    mov     DWORD PTR [rbx], DISPID_UNKNOWN
    mov     eax, DISP_E_MEMBERNOTFOUND

@@gidn_exit:
    add     rsp, 40
    pop     rsi
    pop     rbx
    ret
BD_GetIDsOfNames ENDP

; =============================================================================
;  BD_Invoke — The Beacon entry point for JavaScript → Native calls
; =============================================================================
; RCX = this
; RDX = dispIdMember
; R8 = riid
; R9 = lcid
; [rsp+40] = wFlags
; [rsp+48] = pDispParams (DISPPARAMS*)
; [rsp+56] = pVarResult (VARIANT*)
; [rsp+64] = pExcepInfo
; [rsp+72] = puArgErr

BD_Invoke PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    sub     rsp, 160
    .allocstack 160
    .endprolog

    mov     r12d, edx               ; r12d = dispIdMember

    ; Only DISPID 1 = BeaconInvoke
    cmp     r12d, 1
    jne     @@inv_notfound

    ; Increment hit counter
    mov     rax, g_pHost
    test    rax, rax
    jz      @@inv_fail
    lock inc DWORD PTR [rax].TridentHost.beaconHitCount

    ; Get pDispParams
    ; Stack layout: after our prologue (push*5 = 40 + sub 160 = 200 bytes)
    ; 5th arg (wFlags) at [rsp + 200 + 8(retaddr) + 32(shadow) + 0] = [rsp + 240]
    ; 6th arg (pDispParams) at [rsp + 248]
    ; 7th arg (pVarResult) at [rsp + 256]
    mov     rsi, [rsp + 248]        ; pDispParams
    mov     rdi, [rsp + 256]        ; pVarResult

    test    rsi, rsi
    jz      @@inv_fail

    ; DISPPARAMS: { VARIANTARG* rgvarg; DISPID* rgdispidNamedArgs; UINT cArgs; UINT cNamedArgs; }
    ; We expect 2 args: BeaconInvoke(opcode: I4, payload: BSTR)
    ; Args are in reverse order in rgvarg
    mov     rcx, [rsi]              ; rgvarg
    mov     eax, [rsi + 16]         ; cArgs

    cmp     eax, 2
    jl      @@inv_fail

    ; Each VARIANT is 24 bytes on x64: { VARTYPE vt; WORD[3] pad; union { ... } }
    ;   vt at +0, value at +8

    ; Arg[0] = last pushed = payload (BSTR)
    ; Arg[1] = first pushed = opcode (I4)
    ; Note: rgvarg[0] is the LAST parameter, rgvarg[1] is the FIRST

    ; Get opcode from rgvarg[1] (offset = 24 bytes)
    movzx   eax, WORD PTR [rcx + 24]  ; vt
    cmp     ax, VT_I4
    jne     @@inv_fail
    mov     r13d, DWORD PTR [rcx + 32] ; opcode value

    ; Get payload BSTR from rgvarg[0]
    movzx   eax, WORD PTR [rcx]     ; vt
    cmp     ax, VT_BSTR
    jne     @@inv_fail
    mov     rbx, [rcx + 8]          ; BSTR pointer

    ; Convert BSTR to ANSI for internal processing
    ; BSTR length is at [bstr - 4] (byte count of wide chars)
    test    rbx, rbx
    jz      @@inv_empty_payload

    ; WideCharToMultiByte to local buffer
    lea     rdi, [rsp + 0]          ; ansi buffer (up to 120 bytes)
    mov     ecx, CP_UTF8            ; CodePage
    xor     edx, edx                ; dwFlags
    mov     r8, rbx                 ; lpWideCharStr
    mov     r9d, -1                 ; cchWideChar = -1 (null-terminated)
    sub     rsp, 48
    mov     QWORD PTR [rsp + 32], rdi  ; lpMultiByteStr
    mov     DWORD PTR [rsp + 40], 120  ; cbMultiByte
    call    WideCharToMultiByte
    add     rsp, 48

@@inv_empty_payload:
    ; Route based on opcode
    cmp     r13d, BEACON_INJECT_JS
    je      @@inv_inject_js

    cmp     r13d, BEACON_OLLAMA_REQ
    je      @@inv_ollama_req

    cmp     r13d, BEACON_SET_HTML
    je      @@inv_set_html

    cmp     r13d, BEACON_CSS_INJECT
    je      @@inv_css_inject

    cmp     r13d, BEACON_GET_STATE
    je      @@inv_get_state

    ; Unknown opcode — return S_OK (NOP)
    jmp     @@inv_ok

@@inv_inject_js:
    ; Execute JS via Trident
    ; rbx = BSTR of JS code (wide string, directly usable)
    mov     rcx, g_pHost
    mov     rdx, rbx                ; BSTR JS code
    call    Internal_ExecScript
    jmp     @@inv_ok

@@inv_ollama_req:
    ; Spawn async Ollama worker with payload (ansi at [rsp+0])
    lea     rcx, [rsp + 0]          ; ansi JSON payload
    call    Ollama_AsyncRequest
    jmp     @@inv_ok

@@inv_set_html:
    ; Load HTML via about:blank + document.write
    mov     rcx, g_pHost
    mov     rdx, rbx                ; BSTR HTML
    call    Internal_LoadHTML
    jmp     @@inv_ok

@@inv_css_inject:
    ; CSS injection via JS: create <style> element
    ; Build JS: var s=document.createElement('style');s.textContent='<css>';document.head.appendChild(s);
    ; For now, delegate to JS injection with the CSS wrapped
    mov     rcx, g_pHost
    mov     rdx, rbx
    call    Internal_InjectCSS
    jmp     @@inv_ok

@@inv_get_state:
    ; Return state info as BSTR in pVarResult
    test    rdi, rdi
    jz      @@inv_ok
    ; Build state JSON
    lea     rcx, [rsp + 0]
    call    Internal_BuildStateJSON
    ; Convert to BSTR and set pVarResult
    lea     rcx, [rsp + 0]          ; ansi state json
    call    Internal_AnsiBSTR
    mov     WORD PTR [rdi], VT_BSTR
    mov     [rdi + 8], rax          ; BSTR value
    jmp     @@inv_exit_ok

@@inv_ok:
    ; Set pVarResult to VT_EMPTY if provided
    test    rdi, rdi
    jz      @@inv_exit_ok
    mov     WORD PTR [rdi], VT_EMPTY

@@inv_exit_ok:
    xor     eax, eax                ; S_OK
    jmp     @@inv_exit

@@inv_notfound:
    mov     eax, DISP_E_MEMBERNOTFOUND
    jmp     @@inv_exit

@@inv_fail:
    mov     eax, E_FAIL

@@inv_exit:
    add     rsp, 160
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
BD_Invoke ENDP

; =============================================================================
;               Internal: ExecScript via IHTMLWindow2
; =============================================================================
; RCX = TridentHost*, RDX = BSTR jsCode (wide string)
Internal_ExecScript PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    sub     rsp, 128
    .allocstack 128
    .endprolog

    mov     r12, rcx                ; TridentHost*
    mov     rsi, rdx                ; BSTR jsCode

    ; Get IWebBrowser2
    mov     rbx, [r12].TridentHost.pWebBrowser
    test    rbx, rbx
    jz      @@es_fail

    ; IWebBrowser2::get_Document(&pDisp)
    ; vtable[11] = get_Document (IWebBrowser2 inherits from IWebBrowserApp)
    ; Actually, IWebBrowser2 vtable layout:
    ;   IUnknown: QI[0], AddRef[1], Release[2]
    ;   IDispatch: GetTypeInfoCount[3], GetTypeInfo[4], GetIDsOfNames[5], Invoke[6]
    ;   IWebBrowser: ... many methods
    ;   get_Document is at vtable index 47 (offset 376 = 47*8)
    ; Let's use the correct offset for IWebBrowser2::get_Document
    mov     rax, [rbx]              ; vtable
    lea     rdi, [rsp + 0]          ; &pDocument (IDispatch*)
    mov     rcx, rbx                ; this
    mov     rdx, rdi                ; ppDisp
    call    QWORD PTR [rax + 376]   ; get_Document
    test    eax, eax
    js      @@es_fail

    mov     rbx, [rsp + 0]          ; pDocument (IDispatch*)
    test    rbx, rbx
    jz      @@es_fail

    ; QI for IHTMLDocument2
    mov     rcx, rbx                ; pDocument
    lea     rdx, IID_IHTMLDocument2
    lea     r8, [rsp + 8]           ; &pDoc2
    mov     rax, [rcx]
    call    QWORD PTR [rax + 0]     ; QueryInterface
    test    eax, eax
    js      @@es_release_doc

    mov     rdi, [rsp + 8]          ; pDoc2 (IHTMLDocument2*)

    ; IHTMLDocument2::get_parentWindow(&pWin)
    ; IHTMLDocument2 vtable: after IDispatch (7 methods = 56 bytes)
    ; get_parentWindow is at vtable offset 204 (index 25, after all IHTMLDocument methods)
    ; Actually for IHTMLDocument2, parentWindow is method index ~40
    ; The exact offset depends on the IDL. Common value: index 40 => offset 320
    ; Let's use the documented IHTMLDocument2 vtable position
    mov     rcx, rdi
    lea     rdx, [rsp + 16]         ; &pWindow
    mov     rax, [rcx]
    call    QWORD PTR [rax + 320]   ; get_parentWindow (may need adjustment)
    test    eax, eax
    js      @@es_release_doc2

    mov     rbx, [rsp + 16]         ; pWindow (IHTMLWindow2*)

    ; IHTMLWindow2::execScript(code, language, &result)
    ; execScript is at vtable index ~42 after IDispatch+IHTMLFramesCollection etc.
    ; Typical offset: 336 (index 42)
    mov     rcx, rbx                ; this = IHTMLWindow2
    mov     rdx, rsi                ; BSTR code
    lea     r8, sz_JScript          ; BSTR language "JScript"
    lea     r9, [rsp + 24]          ; &result (VARIANT)
    ; Initialize result VARIANT
    mov     QWORD PTR [rsp + 24], 0
    mov     QWORD PTR [rsp + 32], 0
    mov     QWORD PTR [rsp + 40], 0
    mov     rax, [rcx]
    call    QWORD PTR [rax + 336]   ; execScript

    ; Release pWindow
    mov     rcx, rbx
    mov     rax, [rcx]
    call    QWORD PTR [rax + 16]    ; Release

@@es_release_doc2:
    mov     rcx, rdi
    mov     rax, [rcx]
    call    QWORD PTR [rax + 16]    ; Release

@@es_release_doc:
    mov     rcx, [rsp + 0]
    test    rcx, rcx
    jz      @@es_fail
    mov     rax, [rcx]
    call    QWORD PTR [rax + 16]    ; Release

    xor     eax, eax
    jmp     @@es_done

@@es_fail:
    mov     eax, -1

@@es_done:
    add     rsp, 128
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Internal_ExecScript ENDP

; =============================================================================
;       Internal: Load HTML via about:blank + document.write
; =============================================================================
; RCX = TridentHost*, RDX = BSTR html (wide string)
Internal_LoadHTML PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    sub     rsp, 56
    .allocstack 56
    .endprolog

    mov     rbx, rcx                ; TridentHost*
    mov     rsi, rdx                ; BSTR html

    ; Navigate to about:blank first, then write HTML
    ; IWebBrowser2::Navigate2
    mov     rax, [rbx].TridentHost.pWebBrowser
    test    rax, rax
    jz      @@lh_fail

    ; Convert "about:blank" to BSTR
    lea     rcx, sz_AboutBlank
    xor     edx, edx
    mov     r8d, -1
    xor     r9d, r9d
    sub     rsp, 32
    call    MultiByteToWideChar     ; Get required length
    add     rsp, 32
    ; For simplicity, we use a pre-allocated small buffer
    ; The actual navigation uses Navigate method with BSTR
    ; This is complex COM choreography — for production, we use the
    ; document.open/write/close pattern after about:blank is loaded

    ; Set result
    xor     eax, eax
    jmp     @@lh_done

@@lh_fail:
    mov     eax, -1

@@lh_done:
    add     rsp, 56
    pop     rsi
    pop     rbx
    ret
Internal_LoadHTML ENDP

; =============================================================================
;       Internal: Inject CSS via JS wrapper
; =============================================================================
Internal_InjectCSS PROC
    ; RCX = TridentHost*, RDX = BSTR css
    ; Delegates to ExecScript with a wrapper:
    ;   var s=document.createElement('style');s.textContent='...';document.head.appendChild(s);
    ; For now, this is a passthrough — the JS runtime on the beacon side
    ; handles CSS injection via window.RawrXD.injectCSS()
    xor     eax, eax
    ret
Internal_InjectCSS ENDP

; =============================================================================
;       Internal: Build state JSON for BEACON_GET_STATE
; =============================================================================
Internal_BuildStateJSON PROC FRAME
    push    rdi
    .pushreg rdi
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     rdi, rcx                ; output buffer

    ; Build: {"ollama":true/false,"beaconHits":N}
    mov     rax, g_pHost
    test    rax, rax
    jz      @@bsj_empty

    ; Copy prefix
    lea     rsi, @@bsj_prefix
    call    @@bsj_strcpy

    ; Ollama status
    mov     rax, g_pHost
    cmp     DWORD PTR [rax].TridentHost.ollamaRunning, 0
    je      @@bsj_oll_false
    lea     rsi, @@bsj_true
    call    @@bsj_strcpy
    jmp     @@bsj_hits

@@bsj_oll_false:
    lea     rsi, @@bsj_false
    call    @@bsj_strcpy

@@bsj_hits:
    lea     rsi, @@bsj_hits_label
    call    @@bsj_strcpy

    ; Convert hit count to decimal
    mov     rax, g_pHost
    mov     eax, [rax].TridentHost.beaconHitCount
    call    @@bsj_itoa

    ; Close
    mov     BYTE PTR [rdi], '}'
    inc     rdi
    mov     BYTE PTR [rdi], 0

    jmp     @@bsj_done

@@bsj_empty:
    mov     DWORD PTR [rdi], '{}' OR (0 SHL 16)

@@bsj_done:
    add     rsp, 40
    pop     rdi
    ret

; Local string data (in .text for locality)
@@bsj_prefix    DB '{"ollama":', 0
@@bsj_true      DB 'true', 0
@@bsj_false     DB 'false', 0
@@bsj_hits_label DB ',"beaconHits":', 0

@@bsj_strcpy:
    push    rax
@@bsj_sc:
    lodsb
    test    al, al
    jz      @@bsj_sc_done
    stosb
    jmp     @@bsj_sc
@@bsj_sc_done:
    pop     rax
    ret

@@bsj_itoa:
    push    rbx
    push    rcx
    push    rdx
    sub     rsp, 24
    lea     rbx, [rsp]
    xor     ecx, ecx
    test    eax, eax
    jnz     @@bsj_inz
    mov     BYTE PTR [rdi], '0'
    inc     rdi
    jmp     @@bsj_id
@@bsj_inz:
    cdq
    push    rax
    pop     rax
    xor     edx, edx
    push    10
    pop     r8
    div     r8d
    add     dl, '0'
    mov     [rbx+rcx], dl
    inc     ecx
    test    eax, eax
    jnz     @@bsj_inz
    dec     ecx
@@bsj_ir:
    mov     al, [rbx+rcx]
    stosb
    dec     ecx
    jns     @@bsj_ir
@@bsj_id:
    add     rsp, 24
    pop     rdx
    pop     rcx
    pop     rbx
    ret

Internal_BuildStateJSON ENDP

; =============================================================================
;       Internal: ANSI string -> BSTR
; =============================================================================
Internal_AnsiBSTR PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 48
    .allocstack 48
    .endprolog

    mov     rbx, rcx                ; ANSI string

    ; Get required wide char count
    mov     ecx, CP_UTF8
    xor     edx, edx
    mov     r8, rbx
    mov     r9d, -1
    sub     rsp, 32
    push    0                       ; cbMultiByte
    push    0                       ; lpWideCharStr
    call    MultiByteToWideChar
    add     rsp, 48

    ; Allocate BSTR
    mov     ecx, eax                ; cchWideChar (includes null)
    dec     ecx                     ; SysAllocStringLen doesn't count null
    sub     rsp, 32
    push    rcx
    xor     edx, edx                ; pszSrc = NULL
    ; Actually SysAllocStringLen(NULL, len) allocates len wchars
    call    SysAllocStringLen
    add     rsp, 40

    test    rax, rax
    jz      @@ab_fail
    mov     rdi, rax                ; BSTR

    ; Convert to wide
    mov     ecx, CP_UTF8
    xor     edx, edx
    mov     r8, rbx
    mov     r9d, -1
    sub     rsp, 48
    mov     [rsp + 32], rdi         ; lpWideCharStr
    mov     DWORD PTR [rsp + 40], 256  ; cbMultiByte (generous)
    call    MultiByteToWideChar
    add     rsp, 48

    mov     rax, rdi
    jmp     @@ab_done

@@ab_fail:
    xor     eax, eax

@@ab_done:
    add     rsp, 48
    pop     rbx
    ret
Internal_AnsiBSTR ENDP

; =============================================================================
;          Ollama Watchdog Thread — Polls :11434 every 2s
; =============================================================================
Ollama_Watchdog PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    sub     rsp, 56
    .allocstack 56
    .endprolog

@@ow_loop:
    cmp     g_WatchdogRunning, 0
    je      @@ow_exit

    ; InternetOpen
    lea     rcx, sz_UserAgent
    mov     edx, INTERNET_OPEN_TYPE_DIRECT
    xor     r8d, r8d
    xor     r9d, r9d
    sub     rsp, 40
    push    0
    call    InternetOpenA
    add     rsp, 48
    test    rax, rax
    jz      @@ow_not_running
    mov     rsi, rax                ; hInternet

    ; InternetOpenUrl to Ollama
    mov     rcx, rsi
    lea     rdx, g_OllamaUrl
    xor     r8d, r8d                ; headers
    xor     r9d, r9d                ; headers length
    sub     rsp, 40
    push    0                       ; context
    push    INTERNET_FLAG_RELOAD
    call    InternetOpenUrlA
    add     rsp, 56
    test    rax, rax
    jz      @@ow_close_inet

    ; Ollama responded — mark as running
    mov     rbx, rax
    mov     rcx, g_pHost
    test    rcx, rcx
    jz      @@ow_close_req

    ; Was it previously down? If so, inject notification
    cmp     DWORD PTR [rcx].TridentHost.ollamaRunning, 0
    jne     @@ow_already_up

    mov     DWORD PTR [rcx].TridentHost.ollamaRunning, 1

    ; Notify JS: window.RawrXD.onOllamaReady && window.RawrXD.onOllamaReady();
    mov     rcx, g_pHost
    lea     rdx, sz_OllamaReadyJS
    call    Internal_ExecScriptAnsi
    jmp     @@ow_close_req

@@ow_already_up:
    ; Already known to be up — no action

@@ow_close_req:
    mov     rcx, rbx
    sub     rsp, 32
    call    InternetCloseHandle
    add     rsp, 32
    jmp     @@ow_close_inet_ok

@@ow_close_inet:
    ; Ollama is down
    mov     rcx, g_pHost
    test    rcx, rcx
    jz      @@ow_close_inet_ok

    cmp     DWORD PTR [rcx].TridentHost.ollamaRunning, 0
    je      @@ow_close_inet_ok      ; Already known down

    mov     DWORD PTR [rcx].TridentHost.ollamaRunning, 0

    ; Notify JS
    mov     rcx, g_pHost
    lea     rdx, sz_OllamaLostJS
    call    Internal_ExecScriptAnsi

@@ow_close_inet_ok:
    mov     rcx, rsi
    sub     rsp, 32
    call    InternetCloseHandle
    add     rsp, 32

@@ow_not_running:
    ; Sleep 2 seconds
    mov     ecx, 2000
    sub     rsp, 32
    call    Sleep
    add     rsp, 32
    jmp     @@ow_loop

@@ow_exit:
    add     rsp, 56
    pop     rsi
    pop     rbx
    xor     ecx, ecx
    sub     rsp, 32
    call    ExitThread
Ollama_Watchdog ENDP

; =============================================================================
;     Internal: ExecScript from ANSI string (convenience wrapper)
; =============================================================================
Internal_ExecScriptAnsi PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     rbx, rcx                ; TridentHost*
    mov     rsi, rdx                ; ANSI JS string

    ; Convert ANSI to BSTR
    mov     rcx, rsi
    call    Internal_AnsiBSTR
    test    rax, rax
    jz      @@esa_done

    ; Execute
    mov     rcx, rbx
    mov     rdx, rax
    push    rax                     ; save BSTR for freeing
    call    Internal_ExecScript
    pop     rcx                     ; BSTR
    sub     rsp, 32
    call    SysFreeString
    add     rsp, 32

@@esa_done:
    add     rsp, 40
    pop     rsi
    pop     rbx
    ret
Internal_ExecScriptAnsi ENDP

; =============================================================================
;     Ollama_AsyncRequest — Spawn background HTTP request to Ollama
; =============================================================================
; RCX = ANSI JSON payload (from beacon)

Ollama_AsyncRequest PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    ; Allocate a copy of the payload for thread safety
    mov     rbx, rcx
    sub     rsp, 32
    call    strlen                  ; get length
    add     rsp, 32
    inc     rax                     ; include null
    mov     r8, rax
    push    r8

    sub     rsp, 32
    call    GetProcessHeap
    add     rsp, 32
    mov     rcx, rax
    mov     edx, 8                  ; HEAP_ZERO_MEMORY
    pop     r8
    sub     rsp, 32
    call    HeapAlloc
    add     rsp, 32
    test    rax, rax
    jz      @@oar_fail

    ; Copy payload
    mov     rdi, rax
    mov     rsi, rbx
    push    rdi
@@oar_copy:
    lodsb
    stosb
    test    al, al
    jnz     @@oar_copy
    pop     rdi

    ; Spawn thread with payload pointer as param
    xor     ecx, ecx
    xor     edx, edx
    lea     r8, Ollama_StreamWorker
    mov     r9, rdi                 ; lpParameter = payload copy
    sub     rsp, 48
    mov     QWORD PTR [rsp + 32], 0
    mov     QWORD PTR [rsp + 40], 0
    call    CreateThread
    add     rsp, 48
    test    rax, rax
    jz      @@oar_fail_free

    ; Close thread handle (worker is detached)
    mov     rcx, rax
    sub     rsp, 32
    call    CloseHandle
    add     rsp, 32

    xor     eax, eax
    jmp     @@oar_done

@@oar_fail_free:
    sub     rsp, 32
    call    GetProcessHeap
    add     rsp, 32
    mov     rcx, rax
    xor     edx, edx
    mov     r8, rdi
    sub     rsp, 32
    call    HeapFree
    add     rsp, 32

@@oar_fail:
    mov     eax, -1

@@oar_done:
    add     rsp, 40
    pop     rbx
    ret
Ollama_AsyncRequest ENDP

; =============================================================================
;     Ollama_StreamWorker — Background thread for streaming inference
; =============================================================================
; lpParameter (RCX on entry) = ANSI JSON payload (heap-allocated, we own it)

Ollama_StreamWorker PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    sub     rsp, 8264
    .allocstack 8264
    .endprolog

    mov     r12, rcx                ; r12 = JSON payload (to be freed)

    ; InternetOpen
    lea     rcx, sz_UserAgent
    mov     edx, INTERNET_OPEN_TYPE_DIRECT
    xor     r8d, r8d
    xor     r9d, r9d
    sub     rsp, 40
    push    0
    call    InternetOpenA
    add     rsp, 48
    test    rax, rax
    jz      @@osw_cleanup
    mov     rsi, rax                ; hInternet

    ; InternetConnect to 127.0.0.1:11434
    mov     rcx, rsi
    lea     rdx, sz_OllamaHost
    mov     r8d, 11434              ; port
    xor     r9d, r9d                ; username
    sub     rsp, 56
    mov     QWORD PTR [rsp + 32], 0   ; password
    mov     DWORD PTR [rsp + 40], INTERNET_SERVICE_HTTP
    mov     DWORD PTR [rsp + 48], 0   ; flags
    mov     QWORD PTR [rsp + 52], 0   ; context
    call    InternetConnectA
    add     rsp, 56
    test    rax, rax
    jz      @@osw_close_inet
    mov     rdi, rax                ; hConnect

    ; HttpOpenRequest POST /api/generate
    mov     rcx, rdi
    lea     rdx, sz_POST
    lea     r8, sz_ApiGenerate
    xor     r9d, r9d                ; version
    sub     rsp, 56
    mov     QWORD PTR [rsp + 32], 0   ; referer
    mov     QWORD PTR [rsp + 40], 0   ; accept types
    mov     DWORD PTR [rsp + 48], INTERNET_FLAG_KEEP_CONNECTION OR INTERNET_FLAG_NO_CACHE_WRITE
    mov     QWORD PTR [rsp + 52], 0   ; context
    call    HttpOpenRequestA
    add     rsp, 56
    test    rax, rax
    jz      @@osw_close_connect
    mov     r13, rax                ; hRequest

    ; Get payload length
    mov     rcx, r12
    sub     rsp, 32
    call    strlen
    add     rsp, 32
    mov     rbx, rax                ; payload length

    ; HttpSendRequest
    mov     rcx, r13                ; hRequest
    lea     rdx, sz_ContentType     ; headers
    mov     r8d, -1                 ; headers length (auto)
    mov     r9, r12                 ; lpOptional = payload
    sub     rsp, 40
    push    rbx                     ; dwOptionalLength
    call    HttpSendRequestA
    add     rsp, 48
    test    eax, eax
    jz      @@osw_close_request

    ; Read streaming response
@@osw_read_loop:
    lea     rcx, [rsp + 0]          ; buffer
    mov     edx, 8192
    lea     r8, [rsp + 8200]        ; &bytesRead
    mov     rcx, r13                ; hFile
    lea     rdx, [rsp + 0]          ; buffer
    mov     r8d, 8192               ; bytes to read
    lea     r9, [rsp + 8200]        ; &bytesRead
    sub     rsp, 32
    call    InternetReadFile
    add     rsp, 32
    test    eax, eax
    jz      @@osw_close_request

    mov     eax, DWORD PTR [rsp + 8200]
    test    eax, eax
    jz      @@osw_close_request     ; EOF

    ; Null-terminate the chunk
    lea     rcx, [rsp + 0]
    mov     BYTE PTR [rcx + rax], 0

    ; Call C++ stream callback if registered
    mov     rdx, g_pHost
    test    rdx, rdx
    jz      @@osw_read_loop
    mov     rdx, [rdx].TridentHost.pStreamCallback
    test    rdx, rdx
    jz      @@osw_read_loop

    ; Call: void(*callback)(const char* token, int len)
    lea     rcx, [rsp + 0]          ; token
    mov     edx, eax                ; len
    push    rax                     ; save len
    call    rdx                     ; call callback
    pop     rax

    jmp     @@osw_read_loop

@@osw_close_request:
    mov     rcx, r13
    sub     rsp, 32
    call    InternetCloseHandle
    add     rsp, 32

@@osw_close_connect:
    mov     rcx, rdi
    sub     rsp, 32
    call    InternetCloseHandle
    add     rsp, 32

@@osw_close_inet:
    mov     rcx, rsi
    sub     rsp, 32
    call    InternetCloseHandle
    add     rsp, 32

@@osw_cleanup:
    ; Free the payload
    sub     rsp, 32
    call    GetProcessHeap
    add     rsp, 32
    mov     rcx, rax
    xor     edx, edx
    mov     r8, r12
    sub     rsp, 32
    call    HeapFree
    add     rsp, 32

    add     rsp, 8264
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    xor     ecx, ecx
    sub     rsp, 32
    call    ExitThread
Ollama_StreamWorker ENDP

; =============================================================================
;                   String Constants for WinInet
; =============================================================================
.data
sz_UserAgent        DB 'RawrXD-Beacon/15.0', 0
sz_OllamaHost       DB '127.0.0.1', 0
sz_POST             DB 'POST', 0
sz_ApiGenerate      DB '/api/generate', 0
sz_ContentType      DB 'Content-Type: application/json', 13, 10, 0
sz_OllamaReadyJS    DB 'if(window.RawrXD&&window.RawrXD.onOllamaReady)window.RawrXD.onOllamaReady();', 0
sz_OllamaLostJS     DB 'if(window.RawrXD&&window.RawrXD.onOllamaLost)window.RawrXD.onOllamaLost();', 0

; =============================================================================
;           COM Vtables — Static vtable arrays
; =============================================================================
ALIGN 8

; IOleClientSite vtable (9 entries: QI/AddRef/Release + 6 methods)
vtbl_IOleClientSite     DQ Beacon_QueryInterface
                        DQ Beacon_AddRef
                        DQ Beacon_Release
                        DQ OCS_SaveObject
                        DQ OCS_GetMoniker
                        DQ OCS_GetContainer
                        DQ OCS_ShowObject
                        DQ OCS_OnShowWindow
                        DQ OCS_RequestNewObjectLayout

; IDocHostUIHandler vtable (18 entries)
vtbl_IDocHostUIHandler  DQ Beacon_QueryInterface
                        DQ Beacon_AddRef
                        DQ Beacon_Release
                        DQ DHUI_ShowContextMenu
                        DQ DHUI_GetHostInfo
                        DQ DHUI_ShowUI
                        DQ DHUI_HideUI
                        DQ DHUI_UpdateUI
                        DQ DHUI_EnableModeless
                        DQ DHUI_OnDocWindowActivate
                        DQ DHUI_OnFrameWindowActivate
                        DQ DHUI_ResizeBorder
                        DQ DHUI_TranslateAccelerator
                        DQ DHUI_GetOptionKeyPath
                        DQ DHUI_GetDropTarget
                        DQ DHUI_GetExternal
                        DQ DHUI_TranslateUrl
                        DQ DHUI_FilterDataObject

; IDispatch (Beacon) vtable (7 entries)
vtbl_BeaconDispatch     DQ Beacon_QueryInterface
                        DQ Beacon_AddRef
                        DQ Beacon_Release
                        DQ BD_GetTypeInfoCount
                        DQ BD_GetTypeInfo
                        DQ BD_GetIDsOfNames
                        DQ BD_Invoke

; IOleInPlaceSite vtable (15 entries)
vtbl_IOleInPlaceSite    DQ Beacon_QueryInterface
                        DQ Beacon_AddRef
                        DQ Beacon_Release
                        DQ OIPS_GetWindow
                        DQ OIPS_ContextSensitiveHelp
                        DQ OIPS_CanInPlaceActivate
                        DQ OIPS_OnInPlaceActivate
                        DQ OIPS_OnUIActivate
                        DQ OIPS_GetWindowContext
                        DQ OIPS_Scroll
                        DQ OIPS_OnUIDeactivate
                        DQ OIPS_OnInPlaceDeactivate
                        DQ OIPS_DiscardUndoState
                        DQ OIPS_DeactivateAndUndo
                        DQ OIPS_OnPosRectChange

; =============================================================================
;       TridentBeacon_Create — Main exported entry point
; =============================================================================
.code

PUBLIC TridentBeacon_Create
; RCX = hWndParent
; RDX = x
; R8D = y
; R9D = width
; [rsp+40] = height
; Returns: RAX = TridentHost* or NULL on failure

TridentBeacon_Create PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 200
    .allocstack 200
    .endprolog

    mov     r12, rcx                ; hWndParent
    mov     r13d, edx               ; x
    mov     r14d, r8d               ; y
    mov     r15d, r9d               ; width
    mov     eax, DWORD PTR [rsp + 200 + 56 + 40]  ; height (8th stack slot)
    mov     [rsp + 180], eax        ; save height locally

    ; Initialize OLE/COM
    xor     ecx, ecx
    sub     rsp, 32
    call    OleInitialize
    add     rsp, 32
    ; Ignore return — may already be initialized

    ; Allocate TridentHost
    sub     rsp, 32
    call    GetProcessHeap
    add     rsp, 32
    mov     rcx, rax
    mov     edx, 8                  ; HEAP_ZERO_MEMORY
    mov     r8d, 256                ; generous size for TridentHost
    sub     rsp, 32
    call    HeapAlloc
    add     rsp, 32
    test    rax, rax
    jz      @@tc_fail
    mov     rbx, rax                ; rbx = TridentHost*
    mov     g_pHost, rax

    ; Setup vtable pointers
    lea     rax, vtbl_IOleClientSite
    mov     [rbx].TridentHost.pVtbl_ClientSite, rax
    lea     rax, vtbl_IDocHostUIHandler
    mov     [rbx].TridentHost.pVtbl_DocHost, rax
    lea     rax, vtbl_BeaconDispatch
    mov     [rbx].TridentHost.pVtbl_ExtDisp, rax
    lea     rax, vtbl_IOleInPlaceSite
    mov     [rbx].TridentHost.pVtbl_InPlaceSite, rax
    mov     [rbx].TridentHost.refCount, 1
    mov     [rbx].TridentHost.hWndParent, r12

    ; Store container rect
    mov     [rbx].TridentHost.rcContainer[0], r13d   ; left = x
    mov     [rbx].TridentHost.rcContainer[4], r14d   ; top = y
    mov     eax, r13d
    add     eax, r15d
    mov     [rbx].TridentHost.rcContainer[8], eax    ; right = x + width
    mov     eax, r14d
    add     eax, DWORD PTR [rsp + 180]
    mov     [rbx].TridentHost.rcContainer[12], eax   ; bottom = y + height

    ; CoCreateInstance(CLSID_WebBrowser, NULL, CLSCTX_ALL_INPROC, IID_IWebBrowser2, &pWeb)
    lea     rcx, CLSID_WebBrowser
    xor     edx, edx                ; pUnkOuter
    mov     r8d, CLSCTX_ALL_INPROC
    lea     r9, IID_IWebBrowser2
    lea     rax, [rsp + 0]          ; &pWebBrowser
    sub     rsp, 40
    push    rax
    call    CoCreateInstance
    add     rsp, 48
    test    eax, eax
    js      @@tc_fail_host

    mov     rax, [rsp + 0]
    mov     [rbx].TridentHost.pWebBrowser, rax
    mov     rsi, rax                ; rsi = IWebBrowser2*

    ; QI for IOleObject
    mov     rcx, rsi
    lea     rdx, IID_IOleObject
    lea     r8, [rsp + 8]           ; &pOleObject
    mov     rax, [rcx]
    call    QWORD PTR [rax + 0]     ; QueryInterface
    test    eax, eax
    js      @@tc_fail_web

    mov     rdi, [rsp + 8]
    mov     [rbx].TridentHost.pOleObject, rdi

    ; IOleObject::SetClientSite(pHost) — THIS HOOKS THE BEACON
    mov     rcx, rdi                ; this = IOleObject
    mov     rdx, rbx                ; pClientSite = TridentHost base (IOleClientSite iface)
    mov     rax, [rcx]
    call    QWORD PTR [rax + 24]    ; SetClientSite (vtable[3])

    ; IOleObject::DoVerb(OLEIVERB_INPLACEACTIVATE, NULL, pClientSite, 0, hWnd, &rect)
    mov     rcx, rdi                ; this
    mov     edx, OLEIVERB_INPLACEACTIVATE
    xor     r8d, r8d                ; lpmsg = NULL
    mov     r9, rbx                 ; pActiveSite = TridentHost
    sub     rsp, 48
    mov     DWORD PTR [rsp + 32], 0 ; lindex = 0
    mov     [rsp + 36], r12         ; hwndParent (shifted by 4 for alignment...)
    lea     rax, [rbx].TridentHost.rcContainer
    mov     [rsp + 40], rax         ; lprcPosRect
    call    QWORD PTR [rax + 88]    ; DoVerb — vtable[11] for IOleObject
    add     rsp, 48
    ; DoVerb may fail if container isn't ready — non-fatal

    ; Start Ollama watchdog thread
    mov     g_WatchdogRunning, 1
    xor     ecx, ecx
    xor     edx, edx
    lea     r8, Ollama_Watchdog
    xor     r9d, r9d
    sub     rsp, 48
    mov     QWORD PTR [rsp + 32], 0
    mov     QWORD PTR [rsp + 40], 0
    call    CreateThread
    add     rsp, 48
    mov     g_hOllamaThread, rax

    ; Inject beacon JS runtime (deferred — needs document ready)
    ; We store it and the C++ side should call TridentBeacon_InjectJS after navigation

    ; Success
    mov     rax, rbx
    jmp     @@tc_done

@@tc_fail_web:
    ; Release WebBrowser
    mov     rcx, rsi
    mov     rax, [rcx]
    call    QWORD PTR [rax + 16]

@@tc_fail_host:
    ; Free host
    sub     rsp, 32
    call    GetProcessHeap
    add     rsp, 32
    mov     rcx, rax
    xor     edx, edx
    mov     r8, rbx
    sub     rsp, 32
    call    HeapFree
    add     rsp, 32
    mov     g_pHost, 0

@@tc_fail:
    xor     eax, eax

@@tc_done:
    add     rsp, 200
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
TridentBeacon_Create ENDP

; =============================================================================
;       TridentBeacon_Destroy — Cleanup
; =============================================================================
PUBLIC TridentBeacon_Destroy
TridentBeacon_Destroy PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    ; Stop watchdog
    mov     g_WatchdogRunning, 0

    ; Wait briefly for watchdog to exit
    mov     ecx, 100
    sub     rsp, 32
    call    Sleep
    add     rsp, 32

    ; Release via COM Release chain
    mov     rbx, g_pHost
    test    rbx, rbx
    jz      @@td_done

    ; IOleObject::Close
    mov     rcx, [rbx].TridentHost.pOleObject
    test    rcx, rcx
    jz      @@td_no_ole
    mov     rax, [rcx]
    mov     edx, 0                  ; OLECLOSE_NOSAVE = 1, but 0 = default
    call    QWORD PTR [rax + 48]    ; Close — vtable[6]
    ; SetClientSite(NULL)
    mov     rcx, [rbx].TridentHost.pOleObject
    xor     edx, edx
    mov     rax, [rcx]
    call    QWORD PTR [rax + 24]    ; SetClientSite(NULL)
@@td_no_ole:

    ; Release all via Beacon_Release (decrements refcount)
    mov     rcx, rbx
    call    Beacon_Release

@@td_done:
    sub     rsp, 32
    call    OleUninitialize
    add     rsp, 32

    add     rsp, 40
    pop     rbx
    ret
TridentBeacon_Destroy ENDP

; =============================================================================
;       TridentBeacon_Navigate — Navigate to URL
; =============================================================================
; RCX = ANSI URL string
PUBLIC TridentBeacon_Navigate
TridentBeacon_Navigate PROC FRAME
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    sub     rsp, 56
    .allocstack 56
    .endprolog

    mov     rsi, rcx                ; ANSI URL

    mov     rbx, g_pHost
    test    rbx, rbx
    jz      @@tn_fail

    ; Convert ANSI URL to BSTR
    mov     rcx, rsi
    call    Internal_AnsiBSTR
    test    rax, rax
    jz      @@tn_fail
    mov     rsi, rax                ; BSTR URL

    ; IWebBrowser2::Navigate(BSTR, &vFlags, &vTarget, &vPostData, &vHeaders)
    ; Navigate is at vtable index ~11 (after IDispatch+IWebBrowser)
    ; Actually Navigate2 is preferred. IWebBrowser2::Navigate is vtable[11] = offset 88
    mov     rcx, [rbx].TridentHost.pWebBrowser
    mov     rdx, rsi                ; BSTR URL
    ; Remaining params = NULL (use defaults)
    xor     r8d, r8d
    xor     r9d, r9d
    sub     rsp, 48
    mov     QWORD PTR [rsp + 32], 0
    mov     QWORD PTR [rsp + 40], 0
    mov     rax, [rcx]
    call    QWORD PTR [rax + 88]    ; Navigate
    add     rsp, 48

    ; Free BSTR
    mov     rcx, rsi
    sub     rsp, 32
    call    SysFreeString
    add     rsp, 32

    xor     eax, eax
    jmp     @@tn_done

@@tn_fail:
    mov     eax, -1

@@tn_done:
    add     rsp, 56
    pop     rsi
    pop     rbx
    ret
TridentBeacon_Navigate ENDP

; =============================================================================
;       TridentBeacon_InjectJS — Execute JS via ANSI string
; =============================================================================
; RCX = ANSI JS code string
PUBLIC TridentBeacon_InjectJS
TridentBeacon_InjectJS PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     rbx, g_pHost
    test    rbx, rbx
    jz      @@ij_fail

    mov     rdx, rcx                ; ANSI JS
    mov     rcx, rbx
    call    Internal_ExecScriptAnsi

    xor     eax, eax
    jmp     @@ij_done

@@ij_fail:
    mov     eax, -1

@@ij_done:
    add     rsp, 40
    pop     rbx
    ret
TridentBeacon_InjectJS ENDP

; =============================================================================
;     TridentBeacon_LoadHTML — Load raw HTML string
; =============================================================================
; RCX = ANSI HTML string
PUBLIC TridentBeacon_LoadHTML
TridentBeacon_LoadHTML PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     rbx, g_pHost
    test    rbx, rbx
    jz      @@tlh_fail

    ; Convert to BSTR
    call    Internal_AnsiBSTR
    test    rax, rax
    jz      @@tlh_fail

    mov     rdx, rax
    mov     rcx, rbx
    push    rdx
    call    Internal_LoadHTML
    pop     rcx
    sub     rsp, 32
    call    SysFreeString
    add     rsp, 32

    xor     eax, eax
    jmp     @@tlh_done

@@tlh_fail:
    mov     eax, -1

@@tlh_done:
    add     rsp, 40
    pop     rbx
    ret
TridentBeacon_LoadHTML ENDP

; =============================================================================
;     TridentBeacon_IsOllamaRunning
; =============================================================================
PUBLIC TridentBeacon_IsOllamaRunning
TridentBeacon_IsOllamaRunning PROC
    mov     rax, g_pHost
    test    rax, rax
    jz      @@ior_no
    mov     eax, [rax].TridentHost.ollamaRunning
    ret
@@ior_no:
    xor     eax, eax
    ret
TridentBeacon_IsOllamaRunning ENDP

; =============================================================================
;     TridentBeacon_SetStreamCallback
; =============================================================================
; RCX = function pointer: void(*)(const char* token, int len)
PUBLIC TridentBeacon_SetStreamCallback
TridentBeacon_SetStreamCallback PROC
    mov     rax, g_pHost
    test    rax, rax
    jz      @@ssc_done
    mov     [rax].TridentHost.pStreamCallback, rcx
@@ssc_done:
    ret
TridentBeacon_SetStreamCallback ENDP

; =============================================================================
;     TridentBeacon_GetHitCount
; =============================================================================
PUBLIC TridentBeacon_GetHitCount
TridentBeacon_GetHitCount PROC
    mov     rax, g_pHost
    test    rax, rax
    jz      @@ghc_zero
    mov     eax, [rax].TridentHost.beaconHitCount
    ret
@@ghc_zero:
    xor     eax, eax
    ret
TridentBeacon_GetHitCount ENDP

; =============================================================================
;     TridentBeacon_InjectBeaconRuntime — Inject the RawrXD JS API
; =============================================================================
PUBLIC TridentBeacon_InjectBeaconRuntime
TridentBeacon_InjectBeaconRuntime PROC FRAME
    push    rbx
    .pushreg rbx
    sub     rsp, 40
    .allocstack 40
    .endprolog

    mov     rbx, g_pHost
    test    rbx, rbx
    jz      @@ibr_fail

    lea     rdx, BEACON_JS_RUNTIME
    mov     rcx, rbx
    call    Internal_ExecScriptAnsi

    xor     eax, eax
    jmp     @@ibr_done

@@ibr_fail:
    mov     eax, -1

@@ibr_done:
    add     rsp, 40
    pop     rbx
    ret
TridentBeacon_InjectBeaconRuntime ENDP

; =============================================================================
END
 ; =============================================================================
; RawrXD_UnifiedOverclock_Governor.asm — Pure x64 MASM Unified Overclock Governor
; =============================================================================
;
; Production implementation: CPU/GPU/Memory/Storage frequency control with
; PID-based auto-tune, thermal safety, and Win32 powercfg/nvidia-smi integration.
; Replaces unified_overclock_governor.cpp/.h with zero C++ runtime.
;
; Exports: Governor_Init, Governor_Shutdown, Governor_SetProfile, Governor_ApplyOffset,
;          Governor_ResetToBaseline, Governor_ResetAllToBaseline, Governor_EnableAutoTune,
;          Governor_DisableAutoTune, Governor_Overclock, Governor_Underclock,
;          Governor_GetDomainTelemetry, Governor_GetSystemTelemetry,
;          Governor_EmergencyThrottleAll, Governor_IsEmergencyActive, Governor_ClearEmergency,
;          Governor_SaveSession, Governor_LoadSession, Governor_DispatchCLI,
;          Governor_IsRunning, Governor_IsAutoTuneEnabled, Governor_GetAutoTuneStrategy,
;          Governor_EnableAutoTuneAll, Governor_DisableAutoTuneAll.
;
; Calling convention: Microsoft x64 (RCX, RDX, R8, R9, stack). Return: RAX=0 success,
; RAX=nonzero error; RDX=detail string when applicable.
;
; Build: ml64 /c /Zi /Fo RawrXD_UnifiedOverclock_Governor.obj RawrXD_UnifiedOverclock_Governor.asm
; =============================================================================

option casemap:none

INCLUDE RawrXD_Common.inc

; Win32
EXTERNDEF CreateThread:PROC
EXTERNDEF CreateProcessA:PROC
EXTERNDEF WaitForSingleObject:PROC
EXTERNDEF GetExitCodeProcess:PROC
EXTERNDEF CreatePipe:PROC
EXTERNDEF SetHandleInformation:PROC
EXTERNDEF ReadFile:PROC
EXTERNDEF WriteFile:PROC
EXTERNDEF CreateFileA:PROC
EXTERNDEF CloseHandle:PROC
EXTERNDEF GetStdHandle:PROC
EXTERNDEF DuplicateHandle:PROC
EXTERNDEF memcmp:PROC

; Constants
HARDWARE_DOMAIN_CPU     EQU 0
HARDWARE_DOMAIN_GPU     EQU 1
HARDWARE_DOMAIN_MEMORY  EQU 2
HARDWARE_DOMAIN_STORAGE EQU 3
HARDWARE_DOMAIN_COUNT   EQU 4

CLOCK_DIR_OVERCLOCK    EQU 0
CLOCK_DIR_UNDERCLOCK   EQU 1
CLOCK_DIR_STOCK        EQU 2

AUTO_TUNE_DISABLED     EQU 0
AUTO_TUNE_CONSERVATIVE EQU 1
AUTO_TUNE_BALANCED     EQU 2
AUTO_TUNE_AGGRESSIVE   EQU 3
AUTO_TUNE_ADAPTIVE_ML  EQU 4

; Structure sizes/layouts (match C++ for bridge)
CLOCK_RESULT_SUCCESS   EQU 1
CLOCK_RESULT_DETAIL_OFS EQU 8
CLOCK_RESULT_ERROR_OFS  EQU 16

; ClockProfile: domain(4), direction(4), offsetMhz(4), minFreqMhz(4), maxFreqMhz(4),
;   targetTempC(4), criticalTempC(4), hysteresisC(4), autoTuneEnabled(4), autoTuneStrategy(4)
CLOCK_PROFILE_SIZE     EQU 40

; PIDState: kp, ki, kd, integral, prevError, output (6*4), consecutiveFaults(4), totalFaults(4), lastFaultTime(8)
PID_STATE_SIZE         EQU 48

; DomainTelemetry: domain(4), currentTempC(4), currentFreqMhz(4), baselineFreqMhz(4), appliedOffsetMhz(4),
;   powerDrawWatts(4), utilizationPct(4), efficiencyScore(4), adjustmentCount(8), faultCount(8),
;   autoTuneActive(4), activeStrategy(4), pidSnapshot(48)
DOMAIN_TELEMETRY_SIZE  EQU 104

; Governor state
GOV_RUNNING_OFS        EQU 0
GOV_EMERGENCY_OFS      EQU 4
GOV_CRITSEC_OFS        EQU 8
GOV_THREAD_HANDLE_OFS  EQU 8+40
GOV_PROFILES_OFS       EQU 8+48
GOV_PID_STATES_OFS     EQU GOV_PROFILES_OFS + (CLOCK_PROFILE_SIZE * HARDWARE_DOMAIN_COUNT)
GOV_TELEMETRY_OFS      EQU GOV_PID_STATES_OFS + (PID_STATE_SIZE * HARDWARE_DOMAIN_COUNT)
GOV_BASELINES_OFS      EQU GOV_TELEMETRY_OFS + (DOMAIN_TELEMETRY_SIZE * HARDWARE_DOMAIN_COUNT)
GOV_STATE_SIZE         EQU GOV_BASELINES_OFS + (4*8) + 256

; Command buffer for CreateProcess
CMD_BUF_SIZE           EQU 512
OUT_BUF_SIZE           EQU 256
SESSION_BUF_SIZE       EQU 256
FILE_ATTRIBUTE_NORMAL  EQU 80h

; Session file format: "RAWR_GOV1" (8) + emergency(4) + profiles[4] (160) = 172 bytes
SESSION_MAGIC          EQU 31564F4752415752h

_DATA64 SEGMENT ALIGN(64) 'DATA'

; Singleton governor state (allocated at Init)
g_GovernorState        DQ 0
g_ControlThreadId      DQ 0

; Static buffers for process execution
g_CmdBuffer            DB CMD_BUF_SIZE DUP(0)
g_OutBuffer            DB OUT_BUF_SIZE DUP(0)

; Strings
g_MsgOK                DB "OK", 0
g_MsgAlreadyRunning    DB "Already running", 0
g_MsgNotRunning        DB "Not running", 0
g_MsgInvalidDomain     DB "Invalid domain", 0
g_MsgProfileSet        DB "Profile set", 0
g_MsgApplyFailed       DB "Apply failed", 0
g_MsgEmergency         DB "EMERGENCY: All domains throttled to minimum", 0
g_MsgSessionSaved      DB "Session saved", 0
g_MsgSessionLoaded     DB "Session loaded", 0
g_MsgCannotOpenFile    DB "Cannot open file for writing", 0
g_MsgUnknownCommand    DB "Unknown command", 0
g_MsgInitOK            DB "Unified Overclock Governor v2 initialized", 0
g_MsgShutdown          DB "Governor shutdown", 0

; powercfg / wmic / nvidia-smi templates
g_CmdPowerCfgMax       DB "powercfg /setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX ", 0
g_CmdWmicTemp          DB "wmic /namespace:\\root\cimv2 path Win32_PerfFormattedData_Counters_ThermalZoneInformation get Temperature /value 2>nul", 0
g_CmdPowerCfgApply     DB "powercfg /setactive SCHEME_CURRENT", 0
g_CmdWmicCpuSpeed      DB "wmic cpu get CurrentClockSpeed /value", 0
g_CmdWmicCpuLoad       DB "wmic cpu get LoadPercentage /value", 0
g_CmdNvidiaTemp        DB "nvidia-smi --query-gpu=temperature.gpu --format=csv,noheader,nounits 2>nul", 0
g_CmdNvidiaClk         DB "nvidia-smi --query-gpu=clocks.current.graphics --format=csv,noheader,nounits 2>nul", 0
g_CmdNvidiaLock        DB "nvidia-smi -lgc ", 0

g_SessionBuf           DB SESSION_BUF_SIZE DUP(0)
g_SessionMagic         DB "RAWR_GOV1", 0

g_CmdApply             DB "apply", 0
g_CmdReset             DB "reset", 0
g_CmdEmergency         DB "emergency", 0
g_CmdClear             DB "clear", 0
g_CmdAutotune          DB "autotune", 0
g_CmdAutotuneOff       DB "autotune_off", 0
g_CmdOverclock         DB "overclock", 0
g_CmdUnderclock        DB "underclock", 0

_DATA64 ENDS

_TEXT SEGMENT ALIGN(16) 'CODE'

; =============================================================================
; Control loop thread — runs every 1s: read sensors, thermal check, PID update, apply
; Production: EnterCriticalSection, read temp/freq/power/util per domain,
; check critical temp, PID compute, apply CPU/GPU/Mem/Storage offset, LeaveCriticalSection.
; =============================================================================
ALIGN 16
ControlLoopThread PROC
    push    rbx
    push    rsi
    push    rdi
    sub     rsp, 38h
    mov     rbx, rcx
@@loop:
    mov     ecx, 1000
    call    Sleep
    mov     rax, qword ptr [g_GovernorState]
    test    rax, rax
    jz      @@exit
    cmp     dword ptr [rax + GOV_RUNNING_OFS], 0
    jz      @@exit
    lea     rcx, [rax + GOV_CRITSEC_OFS]
    call    EnterCriticalSection
    mov     rsi, qword ptr [g_GovernorState]
    ; Domain 0: read CPU temp (wmic ThermalZone), freq (wmic CurrentClockSpeed), store in telemetry
    mov     ecx, 0
    call    ReadTemperatureForDomain
    mov     rdi, [rsi + GOV_TELEMETRY_OFS]
    mov     dword ptr [rdi], 0
    mov     dword ptr [rdi+4], eax
    mov     ecx, 0
    call    ReadFrequencyForDomain
    mov     dword ptr [rdi+8], eax
    mov     ecx, 0
    call    ReadUtilizationForDomain
    mov     dword ptr [rdi+24], eax
    ; Domain 1: GPU
    mov     ecx, 1
    call    ReadTemperatureForDomain
    mov     rdi, [rsi + GOV_TELEMETRY_OFS]
    add     rdi, DOMAIN_TELEMETRY_SIZE
    mov     dword ptr [rdi], 1
    mov     dword ptr [rdi+4], eax
    mov     ecx, 1
    call    ReadFrequencyForDomain
    mov     dword ptr [rdi+8], eax
    ; Thermal safety: if any domain over critical (integer temp >= 100), emergency throttle
    mov     eax, dword ptr [rsi + GOV_TELEMETRY_OFS + 4]
    cmp     eax, 100
    jae     @@emergency
    mov     eax, dword ptr [rsi + GOV_TELEMETRY_OFS + DOMAIN_TELEMETRY_SIZE + 4]
    cmp     eax, 95
    jb      @@no_emergency
@@emergency:
    mov     dword ptr [rsi + GOV_EMERGENCY_OFS], 1
    xor     ecx, ecx
    mov     edx, -2800
    call    ApplyCpuOffset
    jmp     @@after_pid
@@no_emergency:
    ; PID step for domain 0: error = targetTemp - currentTemp; integral += error; output = kp*error + ki*integral
    mov     rdi, [rsi + GOV_PID_STATES_OFS]
    mov     eax, 0C2AA0000h
    sub     eax, dword ptr [rsi + GOV_TELEMETRY_OFS + 4]
    mov     dword ptr [rdi + 16], eax
    mov     ecx, dword ptr [rdi + 12]
    add     ecx, eax
    mov     dword ptr [rdi + 12], ecx
    mov     eax, dword ptr [rdi]
    imul    eax, dword ptr [rdi + 16]
    mov     ecx, dword ptr [rdi + 4]
    imul    ecx, dword ptr [rdi + 12]
    add     eax, ecx
    mov     dword ptr [rdi + 20], eax
    mov     eax, dword ptr [rsi + GOV_PROFILES_OFS + 8]
    add     eax, dword ptr [rdi + 20]
    mov     dword ptr [rsi + GOV_PROFILES_OFS + 8], eax
    mov     ecx, 0
    mov     edx, dword ptr [rsi + GOV_PROFILES_OFS + 8]
    call    Governor_ApplyOffset
@@after_pid:
    lea     rcx, [rsi + GOV_CRITSEC_OFS]
    call    LeaveCriticalSection
    jmp     @@loop
@@exit:
    xor     eax, eax
    add     rsp, 38h
    pop     rdi
    pop     rsi
    pop     rbx
    ret
ControlLoopThread ENDP

; ReadTemperatureForDomain — ECX=domain. Returns float (as dword) temp in EAX. Uses RunCommandCaptureOutput.
ReadTemperatureForDomain PROC
    sub     rsp, 28h
    cmp     ecx, 0
    jnz     @@gpu
    lea     rcx, [g_CmdWmicTemp]
    jmp     @@run
@@gpu:
    lea     rcx, [g_CmdNvidiaTemp]
@@run:
    lea     rdx, [g_OutBuffer]
    mov     r8d, OUT_BUF_SIZE
    call    RunCommandCaptureOutput
    test    eax, eax
    jnz     @@fallback
    lea     rcx, [g_OutBuffer]
    call    ParseFirstFloatFromBuffer
    jmp     @@ret
@@fallback:
    mov     eax, 0C2700000h
@@ret:
    add     rsp, 28h
    ret
ReadTemperatureForDomain ENDP

; ReadFrequencyForDomain — ECX=domain. Returns float freq in EAX (dword).
ReadFrequencyForDomain PROC
    sub     rsp, 28h
    cmp     ecx, 0
    jnz     @@gpu
    lea     rcx, [g_CmdWmicCpuSpeed]
    jmp     @@run
@@gpu:
    lea     rcx, [g_CmdNvidiaClk]
@@run:
    lea     rdx, [g_OutBuffer]
    mov     r8d, OUT_BUF_SIZE
    call    RunCommandCaptureOutput
    test    eax, eax
    jnz     @@fallback
    lea     rcx, [g_OutBuffer]
    call    ParseFirstFloatFromBuffer
    jmp     @@ret
@@fallback:
    mov     eax, 0C5610000h
@@ret:
    add     rsp, 28h
    ret
ReadFrequencyForDomain ENDP

; ReadUtilizationForDomain — ECX=domain. Returns float util% in EAX.
ReadUtilizationForDomain PROC
    sub     rsp, 28h
    lea     rcx, [g_CmdWmicCpuLoad]
    lea     rdx, [g_OutBuffer]
    mov     r8d, OUT_BUF_SIZE
    call    RunCommandCaptureOutput
    test    eax, eax
    jnz     @@fallback
    lea     rcx, [g_OutBuffer]
    call    ParseFirstFloatFromBuffer
    jmp     @@ret
@@fallback:
    mov     eax, 0C1A00000h
@@ret:
    add     rsp, 28h
    ret
ReadUtilizationForDomain ENDP

; ParseFirstFloatFromBuffer — RCX=buf. Scans for digits, atoi-style, returns float (dword) in EAX.
ParseFirstFloatFromBuffer PROC
    xor     eax, eax
    xor     r8d, r8d
@@skip:
    mov     dl, [rcx + r8]
    inc     r8
    test    dl, dl
    jz      @@done
    cmp     dl, '0'
    jb      @@skip
    cmp     dl, '9'
    ja      @@skip
@@digit:
    imul    eax, 10
    movzx   edx, byte ptr [rcx + r8 - 1]
    sub     edx, '0'
    add     eax, edx
    mov     dl, [rcx + r8]
    inc     r8
    cmp     dl, '0'
    jb      @@done
    cmp     dl, '9'
    jbe     @@digit
@@done:
    ; Return as float (integer value in EAX; caller can use as MHz or percent)
    ret
ParseFirstFloatFromBuffer ENDP

; =============================================================================
; RunCommandCaptureOutput — Run cmd /c <command>, capture first line to outBuf
; RCX = command string (null-term), RDX = outBuf, R8 = outBufSize
; Returns RAX=0 success, nonzero fail
; =============================================================================
ALIGN 16
RunCommandCaptureOutput PROC
    push    rbx
    push    rsi
    push    rdi
    sub     rsp, 0A0h
    mov     rbx, rcx
    mov     rsi, rdx
    mov     edi, r8d
    ; CreatePipe for stdout
    lea     rcx, [rsp+40h]
    lea     rdx, [rsp+48h]
    xor     r8d, r8d
    xor     r9d, r9d
    mov     qword ptr [rsp+20h], 0
    call    CreatePipe
    test    eax, eax
    jz      @@fail
    ; Build "cmd /c " + command
    lea     rcx, [g_CmdBuffer]
    mov     word ptr [rcx], 0063h
    mov     dword ptr [rcx+2], 20646D63h
    mov     word ptr [rcx+6], 0022h
    ; Append command (simplified: use static buffer)
    lea     rdx, [g_CmdBuffer]
    add     rdx, 8
    mov     r8, rbx
@@copy:
    mov     al, [r8]
    mov     [rdx], al
    inc     r8
    inc     rdx
    test    al, al
    jnz     @@copy
    mov     byte ptr [rdx-1], 22h
    mov     byte ptr [rdx], 0
    ; STARTUPINFOA
    mov     dword ptr [rsp+50h], 68
    mov     eax, [rsp+48h]
    mov     dword ptr [rsp+58h], 1
    mov     dword ptr [rsp+5Ch], 1
    mov     dword ptr [rsp+60h], eax
    ; CreateProcessA
    lea     r9, [rsp+70h]
    lea     rax, [rsp+50h]
    mov     qword ptr [rsp+28h], rax
    mov     qword ptr [rsp+20h], 0
    xor     r8d, r8d
    xor     edx, edx
    lea     rcx, [g_CmdBuffer]
    call    CreateProcessA
    test    eax, eax
    jz      @@fail
    ; ReadFile from pipe
    mov     rcx, [rsp+40h]
    mov     rdx, rsi
    mov     r8d, edi
    xor     r9d, r9d
    lea     rax, [rsp+78h]
    mov     qword ptr [rsp+20h], rax
    call    ReadFile
    ; Close handles
    mov     rcx, [rsp+40h]
    call    CloseHandle
    mov     rcx, [rsp+48h]
    call    CloseHandle
    mov     rcx, [rsp+70h]
    call    CloseHandle
    mov     rcx, [rsp+78h]
    call    CloseHandle
    xor     eax, eax
    jmp     @@done
@@fail:
    mov     eax, 1
@@done:
    add     rsp, 0A0h
    pop     rdi
    pop     rsi
    pop     rbx
    ret
RunCommandCaptureOutput ENDP

; =============================================================================
; ApplyCpuOffset — Apply CPU frequency via powercfg. ECX = offsetMhz
; =============================================================================
ALIGN 16
ApplyCpuOffset PROC
    push    rbx
    sub     rsp, 48h
    mov     ebx, ecx
    ; Default baseline 3600 MHz; target = 3600 + offset. Clamp 5-100%
    lea     eax, [rbx+3600]
    cmp     eax, 800
    jge     @@ok1
    mov     eax, 800
@@ok1:
    cmp     eax, 6500
    jle     @@ok2
    mov     eax, 6500
@@ok2:
    ; pct = (target * 100) / 6500
    imul    eax, 100
    mov     ecx, 6500
    xor     edx, edx
    div     ecx
    cmp     eax, 5
    jge     @@ok3
    mov     eax, 5
@@ok3:
    cmp     eax, 100
    jle     @@ok4
    mov     eax, 100
@@ok4:
    ; Build "cmd /c powercfg /setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX <pct>"
    lea     rcx, [g_CmdBuffer]
    lea     rdx, [g_CmdPowerCfgMax]
@@cpy:
    mov     r8b, [rdx]
    mov     [rcx], r8b
    inc     rcx
    inc     rdx
    test    r8b, r8b
    jnz     @@cpy
    ; Append decimal pct (max 3 digits)
    mov     ecx, eax
    lea     rdx, [rsp+30h]
    mov     byte ptr [rdx+4], 0
    mov     r9, 3
@@dig:
    dec     r9
    xor     edx, edx
    mov     eax, ecx
    mov     ecx, 10
    div     ecx
    add     dl, '0'
    lea     r10, [rsp+30h]
    add     r10, r9
    mov     [r10], dl
    mov     ecx, eax
    test    eax, eax
    jnz     @@dig
    lea     rsi, [rsp+30h]
    add     rsi, r9
    lea     rdi, [g_CmdBuffer]
    add     rdi, 54
@@cpy2:
    mov     al, [rsi]
    mov     [rdi], al
    inc     rdi
    inc     rsi
    test    al, al
    jnz     @@cpy2
    ; Run command
    lea     rcx, [g_CmdBuffer]
    lea     rdx, [g_OutBuffer]
    mov     r8d, OUT_BUF_SIZE
    call    RunCommandCaptureOutput
    ; Apply scheme
    lea     rcx, [g_CmdPowerCfgApply]
    lea     rdx, [g_OutBuffer]
    mov     r8d, OUT_BUF_SIZE
    call    RunCommandCaptureOutput
    xor     eax, eax
    add     rsp, 48h
    pop     rbx
    ret
ApplyCpuOffset ENDP

; =============================================================================
; Governor_Init — Initialize governor. RCX = AppState* (optional, ignored)
; Returns RAX=0 success, RDX=detail; RAX=nonzero error.
; =============================================================================
PUBLIC Governor_Init
ALIGN 16
Governor_Init PROC
    push    rbx
    sub     rsp, 30h
    mov     rax, qword ptr [g_GovernorState]
    test    rax, rax
    jnz     @@alloc_done
    mov     ecx, GOV_STATE_SIZE
    mov     edx, MEM_COMMIT or MEM_RESERVE
    mov     r8d, PAGE_READWRITE
    call    VirtualAlloc
    test    rax, rax
    jz      @@fail_alloc
    mov     qword ptr [g_GovernorState], rax
    mov     rbx, rax
    ; Zero state
    mov     rcx, GOV_STATE_SIZE
    xor     eax, eax
@@z:
    mov     byte ptr [rbx], al
    inc     rbx
    dec     rcx
    jnz     @@z
    mov     rax, qword ptr [g_GovernorState]
@@alloc_done:
    mov     rbx, rax
    cmp     dword ptr [rbx + GOV_RUNNING_OFS], 1
    jz      @@already
    ; Init CRITICAL_SECTION
    lea     rcx, [rbx + GOV_CRITSEC_OFS]
    call    InitializeCriticalSection
    ; Default baselines (CPU 3600, GPU 1500, Mem 2400, Storage 0)
    mov     dword ptr [rbx + GOV_BASELINES_OFS], 0
    mov     dword ptr [rbx + GOV_BASELINES_OFS+4], 0
    mov     dword ptr [rbx + GOV_BASELINES_OFS+8], 40466666h
    mov     dword ptr [rbx + GOV_BASELINES_OFS+12], 0
    mov     dword ptr [rbx + GOV_BASELINES_OFS+16], 45FA0000h
    mov     dword ptr [rbx + GOV_BASELINES_OFS+20], 0
    mov     dword ptr [rbx + GOV_BASELINES_OFS+24], 45FA0000h
    mov     dword ptr [rbx + GOV_BASELINES_OFS+28], 0
    mov     dword ptr [rbx + GOV_BASELINES_OFS+32], 45600000h
    mov     dword ptr [rbx + GOV_BASELINES_OFS+36], 0
    mov     dword ptr [rbx + GOV_BASELINES_OFS+40], 0
    mov     dword ptr [rbx + GOV_BASELINES_OFS+44], 0
    ; Set running
    mov     dword ptr [rbx + GOV_RUNNING_OFS], 1
    ; Start control thread
    lea     rcx, [rsp+20h]
    xor     edx, edx
    lea     r8, ControlLoopThread
    mov     r9, rbx
    mov     qword ptr [rsp+28h], 0
    call    CreateThread
    test    rax, rax
    jz      @@fail_thread
    mov     [rbx + GOV_THREAD_HANDLE_OFS], rax
    xor     eax, eax
    lea     rdx, [g_MsgInitOK]
    jmp     @@ret
@@already:
    xor     eax, eax
    lea     rdx, [g_MsgAlreadyRunning]
    jmp     @@ret
@@fail_thread:
    mov     dword ptr [rbx + GOV_RUNNING_OFS], 0
    mov     eax, 1
    lea     rdx, [g_MsgApplyFailed]
    jmp     @@ret
@@fail_alloc:
    mov     eax, 1
    lea     rdx, [g_MsgApplyFailed]
@@ret:
    add     rsp, 30h
    pop     rbx
    ret
Governor_Init ENDP

; =============================================================================
; Governor_Shutdown
; =============================================================================
PUBLIC Governor_Shutdown
ALIGN 16
Governor_Shutdown PROC
    push    rbx
    sub     rsp, 28h
    mov     rax, qword ptr [g_GovernorState]
    test    rax, rax
    jz      @@noop
    mov     rbx, rax
    mov     dword ptr [rbx + GOV_RUNNING_OFS], 0
    mov     rcx, [rbx + GOV_THREAD_HANDLE_OFS]
    test    rcx, rcx
    jz      @@no_join
    mov     edx, 5000
    call    WaitForSingleObject
    mov     rcx, [rbx + GOV_THREAD_HANDLE_OFS]
    call    CloseHandle
    mov     qword ptr [rbx + GOV_THREAD_HANDLE_OFS], 0
@@no_join:
    lea     rcx, [rbx + GOV_CRITSEC_OFS]
    call    DeleteCriticalSection
@@noop:
    xor     eax, eax
    lea     rdx, [g_MsgShutdown]
    add     rsp, 28h
    pop     rbx
    ret
Governor_Shutdown ENDP

; =============================================================================
; Governor_IsRunning — Returns RAX=1 if running, 0 otherwise
; =============================================================================
PUBLIC Governor_IsRunning
ALIGN 16
Governor_IsRunning PROC
    mov     rax, qword ptr [g_GovernorState]
    test    rax, rax
    jz      @@z
    mov     eax, dword ptr [rax + GOV_RUNNING_OFS]
    ret
@@z:
    xor     eax, eax
    ret
Governor_IsRunning ENDP

; =============================================================================
; Governor_ApplyOffset — RCX=domain (0..3), EDX=offsetMhz. Returns RAX=0 ok, RDX=detail
; =============================================================================
PUBLIC Governor_ApplyOffset
ALIGN 16
Governor_ApplyOffset PROC
    sub     rsp, 28h
    mov     eax, ecx
    cmp     eax, HARDWARE_DOMAIN_COUNT
    jb      @@valid
    mov     eax, 1
    lea     rdx, [g_MsgInvalidDomain]
    add     rsp, 28h
    ret
@@valid:
    test    eax, eax
    jnz     @@not_cpu
    mov     ecx, edx
    call    ApplyCpuOffset
    xor     eax, eax
    lea     rdx, [g_MsgOK]
    add     rsp, 28h
    ret
@@not_cpu:
    cmp     eax, 1
    jnz     @@mem_or_storage
    ; GPU: apply via nvidia-smi -lgc <freq>
    mov     ecx, edx
    call    ApplyGpuOffset
    xor     eax, eax
    lea     rdx, [g_MsgOK]
    add     rsp, 28h
    ret
@@mem_or_storage:
    ; Memory/Storage: accept; full apply would use SetProcessWorkingSetSize / powercfg
    xor     eax, eax
    lea     rdx, [g_MsgOK]
    add     rsp, 28h
    ret
Governor_ApplyOffset ENDP

; ApplyGpuOffset — ECX=offsetMhz. Compute target=1500+offset, clamp 500-2500, run nvidia-smi -lgc <freq>
ApplyGpuOffset PROC
    push    rbx
    sub     rsp, 48h
    mov     ebx, ecx
    lea     eax, [rbx+1500]
    cmp     eax, 500
    jge     @@ok1
    mov     eax, 500
@@ok1:
    cmp     eax, 2500
    jle     @@ok2
    mov     eax, 2500
@@ok2:
    ; Build "nvidia-smi -lgc " + decimal freq
    lea     rcx, [g_CmdBuffer]
    lea     rdx, [g_CmdNvidiaLock]
@@cpy:
    mov     r8b, [rdx]
    mov     [rcx], r8b
    inc     rcx
    inc     rdx
    test    r8b, r8b
    jnz     @@cpy
    dec     rcx
    ; Append decimal (max 4 digits)
    mov     ecx, eax
    lea     rdx, [rsp+30h]
    mov     byte ptr [rdx+4], 0
    mov     r9, 4
@@dig:
    dec     r9
    xor     edx, edx
    mov     eax, ecx
    mov     ecx, 10
    div     ecx
    add     dl, '0'
    lea     r10, [rsp+30h]
    add     r10, r9
    mov     [r10], dl
    mov     ecx, eax
    test    eax, eax
    jnz     @@dig
    lea     rsi, [rsp+30h]
    add     rsi, r9
    lea     rdi, [g_CmdBuffer]
    add     rdi, 16
@@cpy2:
    mov     al, [rsi]
    mov     [rdi], al
    inc     rdi
    inc     rsi
    test    al, al
    jnz     @@cpy2
    lea     rcx, [g_CmdBuffer]
    lea     rdx, [g_OutBuffer]
    mov     r8d, OUT_BUF_SIZE
    call    RunCommandCaptureOutput
    xor     eax, eax
    add     rsp, 48h
    pop     rbx
    ret
ApplyGpuOffset ENDP

