    sub     rsp, 28h
    xor     ecx, ecx
    xor     edx, edx
    call    Governor_ApplyOffset
    test    eax, eax
    jnz     @@ret
    mov     ecx, 1
    xor     edx, edx
    call    Governor_ApplyOffset
    test    eax, eax
    jnz     @@ret
    mov     ecx, 2
    xor     edx, edx
    call    Governor_ApplyOffset
    test    eax, eax
    jnz     @@ret
    mov     ecx, 3
    xor     edx, edx
    call    Governor_ApplyOffset
@@ret:
    xor     eax, eax
    lea     rdx, [g_MsgOK]
    add     rsp, 28h
    ret
Governor_ResetAllToBaseline ENDP

