; =============================================================================
; Governor_SetProfile — RCX=domain, RDX=ptr to ClockProfile (40 bytes)
PUBLIC Governor_SetProfile
Governor_SetProfile PROC
    sub     rsp, 28h
    cmp     ecx, HARDWARE_DOMAIN_COUNT
    jb      @@valid
    mov     eax, 1
    lea     rdx, [g_MsgInvalidDomain]
    add     rsp, 28h
    ret
@@valid:
    mov     rax, qword ptr [g_GovernorState]
    test    rax, rax
    jz      @@noop
    imul    ecx, CLOCK_PROFILE_SIZE
    add     rax, GOV_PROFILES_OFS
    add     rax, rcx
    mov     r8, [rdx]
    mov     [rax], r8
    mov     r8, [rdx+8]
    mov     [rax+8], r8
    mov     r8, [rdx+16]
    mov     [rax+16], r8
    mov     r8, [rdx+24]
    mov     [rax+24], r8
    mov     r8, [rdx+32]
    mov     [rax+32], r8
@@noop:
    xor     eax, eax
    lea     rdx, [g_MsgProfileSet]
    add     rsp, 28h
    ret
Governor_SetProfile ENDP

; AutoTune: write to profiles[domain].autoTuneEnabled (offset 32), autoTuneStrategy (offset 36)
PUBLIC Governor_EnableAutoTune
Governor_EnableAutoTune PROC
