    mov     rax, qword ptr [g_GovernorState]
    test    rax, rax
    jz      @@z
    imul    ecx, ecx, CLOCK_PROFILE_SIZE
    add     rax, GOV_PROFILES_OFS
    add     rax, rcx
    mov     dword ptr [rax + 32], 1
    mov     dword ptr [rax + 36], edx
@@z:
    xor     eax, eax
    lea     rdx, [g_MsgOK]
    add     rsp, 28h
    ret
Governor_EnableAutoTune ENDP

