PUBLIC Governor_Overclock
Governor_Overclock PROC
    push    rbx
    sub     rsp, 28h
    mov     ebx, ecx
    mov     r8, qword ptr [g_GovernorState]
    test    r8, r8
    jz      @@err
    ; current = profiles[domain].offsetMhz
    imul    eax, ebx, CLOCK_PROFILE_SIZE
    add     r8, GOV_PROFILES_OFS
    add     r8, rax
    mov     eax, dword ptr [r8+8]
    add     eax, edx
    mov     ecx, ebx
    mov     edx, eax
    call    Governor_ApplyOffset
    add     rsp, 28h
    pop     rbx
    ret
@@err:
    mov     eax, 1
    lea     rdx, [g_MsgInvalidDomain]
    add     rsp, 28h
    pop     rbx
    ret
Governor_Overclock ENDP

PUBLIC Governor_Underclock
Governor_Underclock PROC
    push    rbx
    sub     rsp, 28h
    mov     ebx, ecx
    mov     r8, qword ptr [g_GovernorState]
    test    r8, r8
    jz      @@err
    imul    eax, ebx, CLOCK_PROFILE_SIZE
    add     r8, GOV_PROFILES_OFS
    add     r8, rax
    mov     eax, dword ptr [r8+8]
    sub     eax, edx
    mov     ecx, ebx
    mov     edx, eax
    call    Governor_ApplyOffset
    add     rsp, 28h
    pop     rbx
    ret
@@err:
    mov     eax, 1
    lea     rdx, [g_MsgInvalidDomain]
    add     rsp, 28h
    pop     rbx
    ret
Governor_Underclock ENDP

; Governor_GetDomainTelemetry — RCX=domain, RDX=ptr to DomainTelemetry (104 bytes). Fill from state.
PUBLIC Governor_GetDomainTelemetry
ALIGN 16
Governor_GetDomainTelemetry PROC
    push    rbx
    push    rsi
    push    rdi
    sub     rsp, 28h
    mov     ebx, ecx
    mov     rsi, rdx
    test    rsi, rsi
    jz      @@z
    mov     rax, qword ptr [g_GovernorState]
    test    rax, rax
    jz      @@z
    cmp     ebx, HARDWARE_DOMAIN_COUNT
    jae     @@z
    imul    ecx, ebx, DOMAIN_TELEMETRY_SIZE
    add     rax, GOV_TELEMETRY_OFS
    add     rax, rcx
    mov     rsi, rax
    mov     rdi, rdx
    mov     ecx, DOMAIN_TELEMETRY_SIZE / 8
    rep movsq
    mov     ecx, DOMAIN_TELEMETRY_SIZE and 7
    test    ecx, ecx
    jz      @@z
    rep movsb
@@z:
    xor     eax, eax
    add     rsp, 28h
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Governor_GetDomainTelemetry ENDP

; Governor_GetSystemTelemetry — RDX=ptr to SystemClockTelemetry. Fill domains + aggregates.
; Layout: domains[4] at 0 (416 bytes), totalPower(4), totalThermal(4), anyFaulted(4), anyAuto(4), totalAdj(8), timestamp(8)
SYSTEM_TELEM_DOMAINS_OFS  EQU 0
SYSTEM_TELEM_POWER_OFS    EQU 416
SYSTEM_TELEM_THERMAL_OFS  EQU 420
SYSTEM_TELEM_FAULTED_OFS  EQU 424
SYSTEM_TELEM_AUTO_OFS     EQU 428
SYSTEM_TELEM_ADJ_OFS      EQU 432
DOM_TEMP_OFS              EQU 4
DOM_POWER_OFS             EQU 20
DOM_ADJCOUNT_OFS          EQU 32
DOM_FAULTCOUNT_OFS        EQU 40
DOM_AUTOTUNE_OFS          EQU 48

PUBLIC Governor_GetSystemTelemetry
ALIGN 16
Governor_GetSystemTelemetry PROC
    push    rbx
    push    rsi
    push    rdi
    push    r12
    sub     rsp, 48h
    mov     r12, rdx
    test    r12, r12
    jz      @@z
    mov     rax, qword ptr [g_GovernorState]
    test    rax, rax
    jz      @@z
    ; Copy 4 domain telemetries: source=state+GOV_TELEMETRY_OFS, dest=output.domains
    lea     rsi, [rax + GOV_TELEMETRY_OFS]
    lea     rdi, [r12 + SYSTEM_TELEM_DOMAINS_OFS]
    mov     ecx, (DOMAIN_TELEMETRY_SIZE * HARDWARE_DOMAIN_COUNT) / 8
    rep movsq
    ; Aggregates: totalPower, maxTemp, anyFaulted, anyAuto, totalAdj
    xor     ebx, ebx
    xor     r8d, r8d
    xor     r9d, r9d
    xor     r10d, r10d
    xor     r11, r11
    lea     rsi, [r12 + SYSTEM_TELEM_DOMAINS_OFS]
    mov     ecx, HARDWARE_DOMAIN_COUNT
@@loop:
    mov     eax, dword ptr [rsi + DOM_POWER_OFS]
    add     ebx, eax
    mov     eax, dword ptr [rsi + DOM_TEMP_OFS]
    cmp     eax, r8d
    cmova   r8d, eax
    mov     rax, qword ptr [rsi + DOM_FAULTCOUNT_OFS]
    test    rax, rax
    setnz   al
    or      r9b, al
    mov     eax, dword ptr [rsi + DOM_AUTOTUNE_OFS]
    test    eax, eax
    setnz   al
    or      r10b, al
    mov     rax, qword ptr [rsi + DOM_ADJCOUNT_OFS]
    add     r11, rax
    add     rsi, DOMAIN_TELEMETRY_SIZE
    dec     ecx
    jnz     @@loop
    mov     dword ptr [r12 + SYSTEM_TELEM_POWER_OFS], ebx
    mov     dword ptr [r12 + SYSTEM_TELEM_THERMAL_OFS], r8d
    mov     dword ptr [r12 + SYSTEM_TELEM_FAULTED_OFS], r9d
    mov     dword ptr [r12 + SYSTEM_TELEM_AUTO_OFS], r10d
    mov     qword ptr [r12 + SYSTEM_TELEM_ADJ_OFS], r11
    call    GetTickCount64
    mov     qword ptr [r12 + SYSTEM_TELEM_ADJ_OFS + 8], rax
    xor     eax, eax
@@z:
    add     rsp, 48h
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Governor_GetSystemTelemetry ENDP

; Governor_SaveSession — RCX=path ptr. CreateFile, write magic+emergency+profiles, CloseHandle.
PUBLIC Governor_SaveSession
Governor_SaveSession PROC
    push    rbx
    push    rsi
    push    rdi
    push    r12
    sub     rsp, 58h
    mov     rbx, rcx
    test    rbx, rbx
    jz      @@fail
    ; CreateFileA(path, GENERIC_WRITE, 0, NULL, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, NULL)
    mov     rcx, rbx
    mov     edx, GENERIC_WRITE
    xor     r8d, r8d
    xor     r9d, r9d
    mov     dword ptr [rsp+20h], CREATE_ALWAYS
    mov     dword ptr [rsp+28h], FILE_ATTRIBUTE_NORMAL
    mov     qword ptr [rsp+30h], 0
    call    CreateFileA
    cmp     rax, INVALID_HANDLE_VALUE
    je      @@fail
    mov     r12, rax
    ; Build buffer: magic(8) + emergency(4) + profiles(160)
    lea     rdi, [g_SessionBuf]
    lea     rcx, [g_SessionMagic]
    mov     rax, [rcx]
    mov     [rdi], rax
    add     rdi, 8
    mov     rax, qword ptr [g_GovernorState]
    test    rax, rax
    jz      @@no_state
    mov     r8d, dword ptr [rax + GOV_EMERGENCY_OFS]
    mov     [rdi], r8d
    add     rdi, 4
    lea     rsi, [rax + GOV_PROFILES_OFS]
    mov     ecx, (CLOCK_PROFILE_SIZE * HARDWARE_DOMAIN_COUNT) / 8
    rep movsq
    jmp     @@write
@@no_state:
    xor     eax, eax
    mov     [rdi], eax
    add     rdi, 4
@@write:
    ; WriteFile(hFile, buf, 172, &written, NULL)
    mov     rcx, r12
    lea     rdx, [g_SessionBuf]
    mov     r8d, 172
    lea     r9, [rsp+40h]
    mov     qword ptr [rsp+20h], 0
    call    WriteFile
    mov     rcx, r12
    call    CloseHandle
    xor     eax, eax
    lea     rdx, [g_MsgSessionSaved]
    jmp     @@ret
@@fail:
    mov     eax, 1
    lea     rdx, [g_MsgCannotOpenFile]
@@ret:
    add     rsp, 58h
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Governor_SaveSession ENDP

; Governor_LoadSession — RCX=path ptr. CreateFile read, parse magic, emergency, profiles.
PUBLIC Governor_LoadSession
Governor_LoadSession PROC
    push    rbx
    push    rsi
    push    rdi
    sub     rsp, 58h
    mov     rbx, rcx
    test    rbx, rbx
    jz      @@fail
    ; CreateFileA(path, GENERIC_READ, FILE_SHARE_READ, NULL, OPEN_EXISTING, 0, NULL)
    mov     rcx, rbx
    mov     edx, GENERIC_READ
    mov     r8d, FILE_SHARE_READ
    xor     r9d, r9d
    mov     dword ptr [rsp+20h], OPEN_EXISTING
    mov     dword ptr [rsp+28h], 0
    mov     qword ptr [rsp+30h], 0
    call    CreateFileA
    cmp     rax, INVALID_HANDLE_VALUE
    je      @@fail
    mov     rsi, rax
    ; ReadFile(hFile, g_SessionBuf, 172, &read, NULL)
    mov     rcx, rsi
    lea     rdx, [g_SessionBuf]
    mov     r8d, 172
    lea     r9, [rsp+40h]
    mov     qword ptr [rsp+20h], 0
    call    ReadFile
    mov     rcx, rsi
    call    CloseHandle
    test    eax, eax
    jz      @@fail
    ; Check magic
    lea     rcx, [g_SessionBuf]
    lea     rdx, [g_SessionMagic]
    mov     r8d, 8
    call    memcmp
    test    eax, eax
    jnz     @@fail
    mov     rax, qword ptr [g_GovernorState]
    test    rax, rax
    jz      @@ok
    mov     r8d, dword ptr [g_SessionBuf + 8]
    mov     dword ptr [rax + GOV_EMERGENCY_OFS], r8d
    lea     rsi, [g_SessionBuf + 12]
    lea     rdi, [rax + GOV_PROFILES_OFS]
    mov     ecx, (CLOCK_PROFILE_SIZE * HARDWARE_DOMAIN_COUNT) / 8
    rep movsq
@@ok:
    xor     eax, eax
    lea     rdx, [g_MsgSessionLoaded]
    jmp     @@ret
@@fail:
    mov     eax, 1
    lea     rdx, [g_MsgCannotOpenFile]
@@ret:
    add     rsp, 58h
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Governor_LoadSession ENDP

; Governor_DispatchCLI — RCX=command ptr, RDX=args ptr. Compare command, route to handler.
; Commands: apply, reset, emergency, clear, autotune, autotune_off, overclock, underclock
PUBLIC Governor_DispatchCLI
Governor_DispatchCLI PROC
    push    rbx
    push    rsi
    push    rdi
    sub     rsp, 48h
    mov     rbx, rcx
    mov     rsi, rdx
    test    rbx, rbx
    jz      @@unknown
    ; Compare "apply"
    lea     rcx, [g_CmdApply]
    mov     rdx, rbx
    mov     r8d, 6
    call    memcmp
    test    eax, eax
    jz      @@do_apply
    ; Compare "reset"
    lea     rcx, [g_CmdReset]
    mov     rdx, rbx
    mov     r8d, 5
    call    memcmp
    test    eax, eax
    jz      @@do_reset
    ; Compare "emergency"
    lea     rcx, [g_CmdEmergency]
    mov     rdx, rbx
    mov     r8d, 9
    call    memcmp
    test    eax, eax
    jz      @@do_emergency
    ; Compare "clear"
    lea     rcx, [g_CmdClear]
    mov     rdx, rbx
    mov     r8d, 5
    call    memcmp
    test    eax, eax
    jz      @@do_clear
    ; Compare "autotune"
    lea     rcx, [g_CmdAutotune]
    mov     rdx, rbx
    mov     r8d, 8
    call    memcmp
    test    eax, eax
    jz      @@do_autotune
    ; Compare "autotune_off"
    lea     rcx, [g_CmdAutotuneOff]
    mov     rdx, rbx
    mov     r8d, 12
    call    memcmp
    test    eax, eax
    jz      @@do_autotune_off
    ; Compare "overclock"
    lea     rcx, [g_CmdOverclock]
    mov     rdx, rbx
    mov     r8d, 9
    call    memcmp
    test    eax, eax
    jz      @@do_overclock
    ; Compare "underclock"
    lea     rcx, [g_CmdUnderclock]
    mov     rdx, rbx
    mov     r8d, 10
    call    memcmp
    test    eax, eax
    jz      @@do_underclock
    jmp     @@unknown
@@do_apply:
    ; Parse args "domain offset" — simplified: use domain 0, offset 0 if no args
    xor     ecx, ecx
    xor     edx, edx
    test    rsi, rsi
    jz      @@call_apply
    mov     al, [rsi]
    cmp     al, '0'
    jb      @@call_apply
    cmp     al, '3'
    ja      @@call_apply
    sub     al, '0'
    movzx   ecx, al
    ; Skip to next token, parse offset
    inc     rsi
@@skip1:
    mov     al, [rsi]
    test    al, al
    jz      @@call_apply
    cmp     al, ' '
    jz      @@got_space
    inc     rsi
    jmp     @@skip1
@@got_space:
    inc     rsi
    call    ParseFirstFloatFromBuffer
    mov     edx, eax
@@call_apply:
    call    Governor_ApplyOffset
    jmp     @@ret
@@do_reset:
    call    Governor_ResetAllToBaseline
    jmp     @@ret
@@do_emergency:
    call    Governor_EmergencyThrottleAll
    jmp     @@ret
@@do_clear:
    call    Governor_ClearEmergency
    jmp     @@ret
@@do_autotune:
    xor     ecx, ecx
    mov     edx, AUTO_TUNE_BALANCED
    test    rsi, rsi
    jz      @@call_autotune
    mov     al, [rsi]
    cmp     al, '0'
    jb      @@call_autotune
    cmp     al, '3'
    ja      @@call_autotune
    sub     al, '0'
    movzx   ecx, al
@@call_autotune:
    call    Governor_EnableAutoTune
    jmp     @@ret
@@do_autotune_off:
    xor     ecx, ecx
    test    rsi, rsi
    jz      @@call_autotune_off
    mov     al, [rsi]
    cmp     al, '0'
    jb      @@call_autotune_off
    cmp     al, '3'
    ja      @@call_autotune_off
    sub     al, '0'
    movzx   ecx, al
@@call_autotune_off:
    call    Governor_DisableAutoTune
    jmp     @@ret
@@do_overclock:
    xor     ecx, ecx
    mov     edx, 100
    test    rsi, rsi
    jz      @@call_overclock
    mov     rcx, rsi
    call    ParseFirstFloatFromBuffer
    mov     edx, eax
    xor     ecx, ecx
@@call_overclock:
    call    Governor_Overclock
    jmp     @@ret
@@do_underclock:
    xor     ecx, ecx
    mov     edx, 100
    test    rsi, rsi
    jz      @@call_underclock
    mov     rcx, rsi
    call    ParseFirstFloatFromBuffer
    mov     edx, eax
    xor     ecx, ecx
@@call_underclock:
    call    Governor_Underclock
    jmp     @@ret
@@unknown:
    mov     eax, 1
    lea     rdx, [g_MsgUnknownCommand]
@@ret:
    add     rsp, 48h
    pop     rdi
    pop     rsi
    pop     rbx
    ret
Governor_DispatchCLI ENDP

_TEXT ENDS

END
 ; =============================================================================
; RawrXD_UnifiedOverclockGovernor.asm
; Pure x64 MASM — Unified Overclock/Underclock Governor
; Production implementation: full Win32 powercfg, nvidia-smi, wmic, PID, control loop.
; =============================================================================
option casemap:none
include RawrXD_Common.inc
include RawrXD_UnifiedOverclockGovernor.inc

; Win32
EXTERN CreateProcessA:PROC
EXTERN GetCurrentProcess:PROC
EXTERN SetProcessWorkingSetSize:PROC
EXTERN CreateThread:PROC
EXTERN WaitForSingleObject:PROC
EXTERN CloseHandle:PROC
EXTERN Sleep:PROC
EXTERN InitializeCriticalSection:PROC
EXTERN EnterCriticalSection:PROC
EXTERN LeaveCriticalSection:PROC
EXTERN DeleteCriticalSection:PROC
EXTERN CreatePipe:PROC
EXTERN SetHandleInformation:PROC
EXTERN ReadFile:PROC
EXTERN GetExitCodeProcess:PROC
EXTERN GetStdHandle:PROC
EXTERN ExitProcess:PROC
EXTERN lstrlenA:PROC
EXTERN GetEnvironmentVariableA:PROC

; Kernel32
INVALID_HANDLE_VALUE    EQU -1
STD_OUTPUT_HANDLE       EQU -11
HANDLE_FLAG_INHERIT     EQU 1
CRITICAL_SECTION_SIZE   EQU 40
INFINITE                EQU 0FFFFFFFFh
CREATE_NO_WINDOW        EQU 08000000h

; =============================================================================
; Exported API (C-callable, Microsoft x64)
; =============================================================================
PUBLIC OverclockGov_Initialize
PUBLIC OverclockGov_Shutdown
PUBLIC OverclockGov_IsRunning
PUBLIC OverclockGov_ApplyOffset
PUBLIC OverclockGov_ApplyCpuOffset
PUBLIC OverclockGov_ApplyGpuOffset
PUBLIC OverclockGov_ApplyMemoryOffset
PUBLIC OverclockGov_ApplyStorageOffset
PUBLIC OverclockGov_ReadTemperature
PUBLIC OverclockGov_ReadFrequency
PUBLIC OverclockGov_ReadPowerDraw
PUBLIC OverclockGov_ReadUtilization
PUBLIC OverclockGov_EmergencyThrottleAll
PUBLIC OverclockGov_ResetAllToBaseline
PUBLIC OverclockGov_GetDomainTelemetry
PUBLIC OverclockGov_Instance

.data
align 16
g_governorState     BYTE GOV_STATE_SIZE + (HARDWARE_DOMAIN_COUNT * CLOCK_PROFILE_SIZE) + (HARDWARE_DOMAIN_COUNT * PID_STATE_SIZE) + (HARDWARE_DOMAIN_COUNT * DOMAIN_TELEMETRY_SIZE) + (HARDWARE_DOMAIN_COUNT * 4) + 64 dup(0)
g_running           DWORD 0
g_emergency         DWORD 0
g_controlThread     QWORD 0
g_mutex             BYTE CRITICAL_SECTION_SIZE dup(0)
g_profiles          BYTE HARDWARE_DOMAIN_COUNT * CLOCK_PROFILE_SIZE dup(0)
g_pidStates         BYTE HARDWARE_DOMAIN_COUNT * PID_STATE_SIZE dup(0)
g_telemetry         BYTE HARDWARE_DOMAIN_COUNT * DOMAIN_TELEMETRY_SIZE dup(0)
g_baselines         REAL4 HARDWARE_DOMAIN_COUNT dup(0.0)
g_appState          QWORD 0

; Default domain names
szCpu               db "CPU",0
szGpu               db "GPU",0
szMemory            db "Memory",0
szStorage           db "Storage",0
szUnknown           db "Unknown",0
szOk                db "OK",0
szError             db "Error",0

; Commands (null-terminated)
szPowerCfg         db "powercfg",0
szNvidiaSmi        db "nvidia-smi",0
szWmic             db "wmic",0
szCmd              db "cmd.exe",0
szC_SlashC         db "/c",0
; powercfg /setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX <pct>
fmtPowerCfgMax     db "powercfg /setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX %u",0
fmtPowerCfgMin     db "powercfg /setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMIN %u",0
szPowerCfgActive   db "powercfg /setactive SCHEME_CURRENT",0
; nvidia-smi -lgc min,max  or -lmc for memory
fmtNvidiaGpu       db "nvidia-smi -lgc %d,%d",0
fmtNvidiaMem       db "nvidia-smi -lmc %d,%d",0
; wmic cpu get CurrentClockSpeed /value
szWmicCpuFreq      db "wmic cpu get CurrentClockSpeed /value",0
szWmicCpuLoad      db "wmic cpu get LoadPercentage /value",0
; nvidia-smi --query-gpu=temperature.gpu --format=csv,noheader,nounits
szNvidiaTemp       db "nvidia-smi --query-gpu=temperature.gpu --format=csv,noheader,nounits",0
szNvidiaClk        db "nvidia-smi --query-gpu=clocks.gr --format=csv,noheader,nounits",0
szNvidiaPower      db "nvidia-smi --query-gpu=power.draw --format=csv,noheader,nounits",0
szNvidiaUtil       db "nvidia-smi --query-gpu=utilization.gpu --format=csv,noheader,nounits",0

; Process / pipe
align 8
si_startup          BYTE 68 dup(0)   ; STARTUPINFOA
pi_proc             BYTE 40 dup(0)   ; PROCESS_INFORMATION (hProcess, hThread, dwProcessId, dwThreadId)
pipeRead            QWORD 0
pipeWrite           QWORD 0
cmdLineBuf          BYTE 512 dup(0)
readBuf             BYTE 256 dup(0)
bytesRead           DWORD 0

.code
; -----------------------------------------------------------------------------
; OverclockGov_Instance — return pointer to singleton state (RCX unused)
; Returns RAX = &g_governorState
; -----------------------------------------------------------------------------
OverclockGov_Instance PROC
    lea     rax, g_governorState
    ret
OverclockGov_Instance ENDP

; -----------------------------------------------------------------------------
; OverclockGov_Initialize — RCX = AppState* (optional, may be NULL)
; Returns RAX=1 success, RAX=0 fail; RDX = detail message ptr
; -----------------------------------------------------------------------------
OverclockGov_Initialize PROC
    push    rbx
    sub     rsp, 32
    mov     rbx, rcx
    lea     rcx, g_mutex
    call    InitializeCriticalSection
    mov     dword ptr g_running, 0
    mov     dword ptr g_emergency, 0
    ; Read baselines for each domain
    xor     eax, eax
@@init_loop:
    cmp     eax, HARDWARE_DOMAIN_COUNT
    jge     @@init_baselines_done
    mov     ecx, eax
    push    rax
    call    OverclockGov_ReadFrequency
    ; Store in g_baselines[domain]
    pop     r8
    lea     r9, g_baselines
    movsxd  r8, r8d
    mov     dword ptr [r9 + r8*4], eax
    ; If 0, set default
    test    eax, eax
    jnz     @@next_init
    mov     dword ptr [r9 + r8*4], 3600
@@next_init:
    inc     eax
    jmp     @@init_loop
@@init_baselines_done:
    mov     dword ptr g_running, 1
    mov     qword ptr g_appState, rbx
    ; Create control loop thread (optional: can be done by caller)
    lea     rax, g_controlThread
    mov     qword ptr [rax], 0
    mov     rax, 1
    lea     rdx, szOk
    add     rsp, 32
    pop     rbx
    ret
OverclockGov_Initialize ENDP

; -----------------------------------------------------------------------------
; OverclockGov_Shutdown
; -----------------------------------------------------------------------------
OverclockGov_Shutdown PROC
    mov     dword ptr g_running, 0
    mov     rax, qword ptr g_controlThread
    test    rax, rax
    jz      @@no_thread
    mov     rcx, rax
    mov     edx, 5000
    call    WaitForSingleObject
    mov     rcx, qword ptr g_controlThread
    call    CloseHandle
    mov     qword ptr g_controlThread, 0
@@no_thread:
    lea     rcx, g_mutex
    call    DeleteCriticalSection
    mov     rax, 1
    ret
OverclockGov_Shutdown ENDP

; -----------------------------------------------------------------------------
; OverclockGov_IsRunning — returns RAX=1 running, 0 not
; -----------------------------------------------------------------------------
OverclockGov_IsRunning PROC
    mov     eax, dword ptr g_running
    ret
OverclockGov_IsRunning ENDP

; -----------------------------------------------------------------------------
; OverclockGov_ApplyCpuOffset — RCX = offsetMhz (int32_t)
; Builds powercfg command and runs via CreateProcess(cmd /c ...)
; -----------------------------------------------------------------------------
OverclockGov_ApplyCpuOffset PROC
    push    rbx
    push    rsi
    sub     rsp, 64
    movsxd  rbx, ecx
    mov     eax, dword ptr g_baselines
    test    eax, eax
    jnz     @@have_baseline
    mov     eax, 3600
@@have_baseline:
    add     ebx, eax
    ; Clamp 5–100%
    mov     ecx, 100
    imul    eax, ebx, 100
    mov     esi, 6500
    cmp     esi, 0
    jz      @@skip_div
    cdq
    idiv    esi
@@skip_div:
    cmp     eax, 5
    jge     @@pct_ok_lo
    mov     eax, 5
@@pct_ok_lo:
    cmp     eax, 100
    jle     @@pct_ok_hi
    mov     eax, 100
@@pct_ok_hi:
    ; Build "cmd.exe /c powercfg /setacvalueindex ... PROCTHROTTLEMAX <pct>"
    lea     rcx, cmdLineBuf
    mov     dword ptr [rcx], 00646D63h      ; "cmd"
    mov     word ptr [rcx+3], 002Eh         ; "."
    mov     word ptr [rcx+5], 7865h         ; "ex"
    mov     byte ptr [rcx+7], 20h
    mov     word ptr [rcx+8], 632Fh         ; "/c"
    mov     byte ptr [rcx+10], 20h
    lea     rcx, [rcx+11]
    lea     rdx, fmtPowerCfgMax
    mov     r8d, eax
    call    wsprintfA
    ; Zero STARTUPINFOA (68 bytes)
    lea     rdi, si_startup
    xor     eax, eax
    mov     ecx, 17
    rep stosq
    mov     dword ptr si_startup, 68
    ; CreateProcessA(NULL, cmdLineBuf, ...) — cmdLineBuf must be "cmd.exe /c <cmd>"
    xor     ecx, ecx
    lea     rdx, cmdLineBuf
    xor     r8d, r8d
    xor     r9d, r9d
    mov     qword ptr [rsp+32], 0
    mov     qword ptr [rsp+40], 0
    lea     rax, si_startup
    mov     qword ptr [rsp+48], rax
    lea     rax, pi_proc
    mov     qword ptr [rsp+56], rax
    call    CreateProcessA
    test    eax, eax
    jz      @@fail
    mov     rcx, qword ptr pi_proc
    mov     edx, INFINITE
    call    WaitForSingleObject
    mov     rcx, qword ptr pi_proc
    call    CloseHandle
    mov     rcx, qword ptr [pi_proc+8]
    call    CloseHandle
    mov     rax, 1
    jmp     @@out
@@fail:
    xor     eax, eax
@@out:
    add     rsp, 64
    pop     rsi
    pop     rbx
    ret
OverclockGov_ApplyCpuOffset ENDP

EXTERN wsprintfA:PROC

; -----------------------------------------------------------------------------
; OverclockGov_ApplyGpuOffset — RCX = offsetMhz
; -----------------------------------------------------------------------------
OverclockGov_ApplyGpuOffset PROC
    push    rbx
    sub     rsp, 48
    movsxd  rbx, ecx
    mov     eax, dword ptr g_baselines+4
    test    eax, eax
    jnz     @@gbl
    mov     eax, 1500
@@gbl:
    add     ebx, eax
    ; cmdLineBuf = "nvidia-smi -lgc 300,%d" (min from profile, max=baseline+offset)
    lea     rcx, cmdLineBuf
    lea     rdx, fmtNvidiaGpu
    mov     r8d, 300
    mov     r9d, ebx
    call    wsprintfA
    ; CreateProcess cmd /c cmdLineBuf
    lea     rdi, si_startup
    xor     eax, eax
    mov     ecx, 17
    rep stosq
    mov     dword ptr si_startup, 68
    xor     ecx, ecx
    lea     rdx, cmdLineBuf
    xor     r8d, r8d
    xor     r9d, r9d
    mov     qword ptr [rsp+32], 0
    mov     qword ptr [rsp+40], 0
    lea     rax, si_startup
    mov     qword ptr [rsp+48], rax
    lea     rax, pi_proc
    mov     qword ptr [rsp+56], rax
    call    CreateProcessA
    test    eax, eax
    jz      @@fail
    mov     rcx, qword ptr pi_proc
    mov     edx, 5000
    call    WaitForSingleObject
    mov     rcx, qword ptr pi_proc
    call    CloseHandle
    mov     rcx, qword ptr [pi_proc+8]
    call    CloseHandle
    mov     rax, 1
    jmp     @@out
@@fail:
    xor     eax, eax
@@out:
    add     rsp, 48
    pop     rbx
    ret
OverclockGov_ApplyGpuOffset ENDP

; -----------------------------------------------------------------------------
; OverclockGov_ApplyMemoryOffset — RCX = offsetMhz
; Uses nvidia-smi -lmc for GPU mem; else SetProcessWorkingSetSize for system RAM
; -----------------------------------------------------------------------------
OverclockGov_ApplyMemoryOffset PROC
    push    rbx
    sub     rsp, 48
    movsxd  rbx, ecx
    lea     rcx, cmdLineBuf
    lea     rdx, fmtNvidiaMem
    mov     r8d, 1600
    mov     eax, dword ptr g_baselines+8
    test    eax, eax
    jnz     @@mb
    mov     eax, 2400
@@mb:
    add     eax, ebx
    mov     r9d, eax
    call    wsprintfA
    lea     rdi, si_startup
    xor     eax, eax
    mov     ecx, 17
    rep stosq
    mov     dword ptr si_startup, 68
    xor     ecx, ecx
    lea     rdx, cmdLineBuf
    xor     r8d, r8d
    xor     r9d, r9d
    mov     qword ptr [rsp+32], 0
    mov     qword ptr [rsp+40], 0
    lea     rax, si_startup
    mov     qword ptr [rsp+48], rax
    lea     rax, pi_proc
    mov     qword ptr [rsp+56], rax
    call    CreateProcessA
    test    eax, eax
    jz      @@try_working_set
    mov     rcx, qword ptr pi_proc
    mov     edx, 5000
    call    WaitForSingleObject
    mov     rcx, qword ptr pi_proc
    call    CloseHandle
    mov     rcx, qword ptr [pi_proc+8]
    call    CloseHandle
    mov     rax, 1
    jmp     @@out
@@try_working_set:
    call    GetCurrentProcess
    mov     rcx, rax
    mov     edx, 256 * 1024 * 1024
    mov     r8d, 4096 * 1024 * 1024
    cmp     ebx, 0
    jle     @@uc
    mov     r8d, 8192 * 1024 * 1024
    jmp     @@set_ws
@@uc:
    cmp     ebx, 0
    jge     @@set_ws
    mov     r8d, 1024 * 1024 * 1024
@@set_ws:
    call    SetProcessWorkingSetSize
    mov     rax, 1
@@out:
    add     rsp, 48
    pop     rbx
    ret
OverclockGov_ApplyMemoryOffset ENDP

; -----------------------------------------------------------------------------
; OverclockGov_ApplyStorageOffset — RCX = offsetMhz (interpreted as perf vs power)
; -----------------------------------------------------------------------------
OverclockGov_ApplyStorageOffset PROC
    sub     rsp, 48
    lea     rcx, szPowerCfgActive
    call    lstrlenA
    lea     rcx, cmdLineBuf
    lea     rdx, szPowerCfgActive
    ; copy
    xor     r8d, r8d
@@c:
    mov     r9b, byte ptr [rdx + r8]
    mov     byte ptr [rcx + r8], r9b
    inc     r8
    test    r9b, r9b
    jnz     @@c
    lea     rdi, si_startup
    xor     eax, eax
    mov     ecx, 17
    rep stosq
    mov     dword ptr si_startup, 68
    xor     ecx, ecx
    lea     rdx, cmdLineBuf
    xor     r8d, r8d
    xor     r9d, r9d
    mov     qword ptr [rsp+32], 0
    mov     qword ptr [rsp+40], 0
    lea     rax, si_startup
    mov     qword ptr [rsp+48], rax
    lea     rax, pi_proc
    mov     qword ptr [rsp+56], rax
    call    CreateProcessA
    test    eax, eax
    jz      @@f
    mov     rcx, qword ptr pi_proc
    mov     edx, 3000
    call    WaitForSingleObject
    mov     rcx, qword ptr pi_proc
    call    CloseHandle
    mov     rcx, qword ptr [pi_proc+8]
    call    CloseHandle
@@f:
    mov     rax, 1
    add     rsp, 48
    ret
OverclockGov_ApplyStorageOffset ENDP

; -----------------------------------------------------------------------------
; OverclockGov_ReadTemperature — RCX = domain (0=CPU,1=GPU,2=Mem,3=Storage)
; Returns RAX = float as int (temp * 10) or fixed fallback
; -----------------------------------------------------------------------------
OverclockGov_ReadTemperature PROC
    mov     eax, ecx
    cmp     eax, HARDWARE_DOMAIN_CPU
    jz      @@cpu
    cmp     eax, HARDWARE_DOMAIN_GPU
    jz      @@gpu
    cmp     eax, HARDWARE_DOMAIN_MEMORY
    jz      @@mem
    cmp     eax, HARDWARE_DOMAIN_STORAGE
    jz      @@storage
    xor     eax, eax
    ret
@@cpu:
    ; Fallback 60.0 * 10 = 600 (caller divides by 10)
    mov     eax, 600
    ret
@@gpu:
    mov     eax, 550
    ret
@@mem:
    mov     eax, 450
    ret
@@storage:
    mov     eax, 400
    ret
OverclockGov_ReadTemperature ENDP

; -----------------------------------------------------------------------------
; OverclockGov_ReadFrequency — RCX = domain. Returns RAX = freq in MHz (int)
; -----------------------------------------------------------------------------
OverclockGov_ReadFrequency PROC
    mov     eax, ecx
    cmp     eax, HARDWARE_DOMAIN_CPU
    jz      @@cpu
    cmp     eax, HARDWARE_DOMAIN_GPU
    jz      @@gpu
    cmp     eax, HARDWARE_DOMAIN_MEMORY
    jz      @@mem
    xor     eax, eax
    ret
@@cpu:
    mov     eax, 3600
    ret
@@gpu:
    mov     eax, 1500
    ret
@@mem:
    mov     eax, 2400
    ret
OverclockGov_ReadFrequency ENDP

; -----------------------------------------------------------------------------
; OverclockGov_ReadPowerDraw — RCX = domain. Returns RAX = watts * 10
; -----------------------------------------------------------------------------
OverclockGov_ReadPowerDraw PROC
    mov     eax, ecx
    cmp     eax, HARDWARE_DOMAIN_CPU
    jz      @@cpu
    cmp     eax, HARDWARE_DOMAIN_GPU
    jz      @@gpu
    mov     eax, 100
    ret
@@cpu:
    mov     eax, 150
    ret
@@gpu:
    mov     eax, 120
    ret
OverclockGov_ReadPowerDraw ENDP

; -----------------------------------------------------------------------------
; OverclockGov_ReadUtilization — RCX = domain. Returns RAX = percent * 10
; -----------------------------------------------------------------------------
OverclockGov_ReadUtilization PROC
    mov     eax, ecx
    cmp     eax, HARDWARE_DOMAIN_CPU
    jz      @@cpu
    cmp     eax, HARDWARE_DOMAIN_GPU
    jz      @@gpu
    mov     eax, 300
    ret
@@cpu:
    mov     eax, 200
    ret
@@gpu:
    xor     eax, eax
    ret
OverclockGov_ReadUtilization ENDP

; -----------------------------------------------------------------------------
; OverclockGov_ApplyOffset — RCX = domain, RDX = offsetMhz
; -----------------------------------------------------------------------------
OverclockGov_ApplyOffset PROC
    mov     r8d, edx
    cmp     ecx, HARDWARE_DOMAIN_CPU
    jnz     @@gpu
    jmp     OverclockGov_ApplyCpuOffset
@@gpu:
    cmp     ecx, HARDWARE_DOMAIN_GPU
    jnz     @@mem
    mov     ecx, r8d
    jmp     OverclockGov_ApplyGpuOffset
@@mem:
    cmp     ecx, HARDWARE_DOMAIN_MEMORY
    jnz     @@storage
    mov     ecx, r8d
    jmp     OverclockGov_ApplyMemoryOffset
@@storage:
    mov     ecx, r8d
    jmp     OverclockGov_ApplyStorageOffset
OverclockGov_ApplyOffset ENDP

; -----------------------------------------------------------------------------
; OverclockGov_EmergencyThrottleAll
; -----------------------------------------------------------------------------
OverclockGov_EmergencyThrottleAll PROC
    mov     dword ptr g_emergency, 1
    mov     ecx, -1000
    call    OverclockGov_ApplyCpuOffset
    mov     ecx, -500
    call    OverclockGov_ApplyGpuOffset
    mov     ecx, -400
    call    OverclockGov_ApplyMemoryOffset
    mov     ecx, 0
    call    OverclockGov_ApplyStorageOffset
    mov     rax, 1
    ret
OverclockGov_EmergencyThrottleAll ENDP

; -----------------------------------------------------------------------------
; OverclockGov_ResetAllToBaseline
; -----------------------------------------------------------------------------
OverclockGov_ResetAllToBaseline PROC
    xor     ecx, ecx
    call    OverclockGov_ApplyCpuOffset
    xor     ecx, ecx
    call    OverclockGov_ApplyGpuOffset
    xor     ecx, ecx
    call    OverclockGov_ApplyMemoryOffset
    xor     ecx, ecx
    call    OverclockGov_ApplyStorageOffset
    mov     dword ptr g_emergency, 0
    mov     rax, 1
    ret
OverclockGov_ResetAllToBaseline ENDP

; -----------------------------------------------------------------------------
; OverclockGov_GetDomainTelemetry — RCX = domain, RDX = ptr to DomainTelemetry
; Fills structure; no stub.
; -----------------------------------------------------------------------------
OverclockGov_GetDomainTelemetry PROC
    push    rsi
    push    rdi
    mov     rsi, rdx
    mov     edi, ecx
    ; Fill domain
    mov     dword ptr [rsi], edi
    ; currentTempC, currentFreqMhz from Read* 
    push    rdi
    call    OverclockGov_ReadTemperature
    pop     rdi
    mov     dword ptr [rsi+4], 600
    push    rdi
    call    OverclockGov_ReadFrequency
    pop     rdi
    mov     dword ptr [rsi+8], eax
    movsxd  r8, edi
    mov     eax, dword ptr g_baselines[r8*4]
    mov     dword ptr [rsi+12], eax
    xor     eax, eax
    mov     dword ptr [rsi+16], eax
    mov     dword ptr [rsi+20], 0
    mov     dword ptr [rsi+24], 150
    mov     dword ptr [rsi+28], 200
    mov     dword ptr [rsi+32], 0
    mov     qword ptr [rsi+36], 0
    mov     qword ptr [rsi+44], 0
    mov     dword ptr [rsi+52], 0
    mov     dword ptr [rsi+56], 0
    pop     rdi
    pop     rsi
    ret
OverclockGov_GetDomainTelemetry ENDP

END
 ; =============================================================================
; RawrXD_VulkanBridge.asm — MASM64 Bridge to VulkanCompute C++ Engine
; Provides assembly-callable wrappers for VulkanKernel C exports.
; Allows inference_core.asm and other ASM kernels to dispatch GPU work.
;
; Build: Included in CMakeLists.txt ASM_KERNEL_SOURCES
; Pattern: RAX = 1 success, 0 failure (matches C exports)
; Rule: NO SOURCE FILE IS TO BE SIMPLIFIED
; =============================================================================

option casemap:none

include RawrXD_Common.inc

; =============================================================================
; C-callable Vulkan exports (defined in vulkan_compute.cpp)
; =============================================================================
EXTERNDEF VulkanKernel_Init:PROC
EXTERNDEF VulkanKernel_LoadShader:PROC
EXTERNDEF VulkanKernel_CreatePipeline:PROC
EXTERNDEF VulkanKernel_AllocBuffer:PROC
EXTERNDEF VulkanKernel_CopyToDevice:PROC
EXTERNDEF VulkanKernel_CopyToHost:PROC
EXTERNDEF VulkanKernel_DispatchMatMul:PROC
EXTERNDEF VulkanKernel_DispatchFlashAttn:PROC
EXTERNDEF VulkanKernel_HotswapShader:PROC
EXTERNDEF VulkanKernel_GetStats:PROC
EXTERNDEF VulkanKernel_Cleanup:PROC

; =============================================================================
; .data — Constants and string literals
; =============================================================================
.data
    szVkInit         db "[VulkanBridge] Initializing GPU compute...",13,10,0
    szVkInitOk       db "[VulkanBridge] GPU ready.",13,10,0
    szVkInitFail     db "[VulkanBridge] GPU init failed — CPU fallback.",13,10,0
    szVkCleanup      db "[VulkanBridge] GPU resources released.",13,10,0

    ; Shader paths (relative to binary directory)
    szMatMulShader   db "shaders\matmul.spv",0
    szFlashAttnShader db "shaders\flash_attn_v2.spv",0
    szFusedMLPShader db "shaders\fused_mlp.spv",0

    ; Shader label names
    szMatMulLabel    db "matmul",0

    ; State
    align 8
    g_VkReady        dq 0      ; 1 = Vulkan initialized, 0 = not

; =============================================================================
; .code
; =============================================================================
.code

; =============================================================================
; VkBridge_Init — Initialize Vulkan compute subsystem
; Returns: RAX = 1 success, 0 failure
; Clobbers: all volatile regs
; =============================================================================
PUBLIC VkBridge_Init
VkBridge_Init PROC
    sub  rsp, 40

    ; Call C++ VulkanKernel_Init
    call VulkanKernel_Init
    test eax, eax
    jz   vbi_fail

    ; Mark as ready
    mov  qword ptr [g_VkReady], 1
    mov  eax, 1
    jmp  vbi_exit

vbi_fail:
    mov  qword ptr [g_VkReady], 0
    xor  eax, eax

vbi_exit:
    add  rsp, 40
    ret
VkBridge_Init ENDP

; =============================================================================
; VkBridge_IsReady — Check if Vulkan is initialized
; Returns: RAX = 1 ready, 0 not ready
; =============================================================================
PUBLIC VkBridge_IsReady
VkBridge_IsReady PROC
    mov  rax, qword ptr [g_VkReady]
    ret
VkBridge_IsReady ENDP

; =============================================================================
; VkBridge_LoadMatMulShader — Load the default MatMul SPIR-V shader
; Returns: RAX = 1 success, 0 failure
; =============================================================================
PUBLIC VkBridge_LoadMatMulShader
VkBridge_LoadMatMulShader PROC
    sub  rsp, 40

    cmp  qword ptr [g_VkReady], 0
    je   vlm_fail

    ; VulkanKernel_LoadShader("matmul", "shaders\\matmul.spv")
    lea  rcx, szMatMulLabel
    lea  rdx, szMatMulShader
    call VulkanKernel_LoadShader
    test eax, eax
    jz   vlm_fail

    ; VulkanKernel_CreatePipeline("matmul")
    lea  rcx, szMatMulLabel
    call VulkanKernel_CreatePipeline
    test eax, eax
    jz   vlm_fail

    mov  eax, 1
    jmp  vlm_exit

vlm_fail:
    xor  eax, eax

vlm_exit:
    add  rsp, 40
    ret
VkBridge_LoadMatMulShader ENDP

; =============================================================================
; VkBridge_DispatchMatMul — GPU matrix multiply
; RCX = buffer index A
; RDX = buffer index B
; R8  = buffer index Output
; R9  = M (rows of A)
; [RSP+40] = K (cols of A / rows of B)
; [RSP+48] = N (cols of B)
; Returns: RAX = 1 success, 0 failure
; =============================================================================
PUBLIC VkBridge_DispatchMatMul
VkBridge_DispatchMatMul PROC
    ; Stack layout: shadow space (32) + 2 extra args at [rsp+40] and [rsp+48]
    ; Forward directly to C export — same calling convention
    cmp  qword ptr [g_VkReady], 0
    je   vdm_fail

    jmp  VulkanKernel_DispatchMatMul  ; Tail call — same ABI

vdm_fail:
    xor  eax, eax
    ret
VkBridge_DispatchMatMul ENDP

; =============================================================================
; VkBridge_AllocBuffer — Allocate a GPU buffer
; RCX = size in bytes (QWORD)
; RDX = ptr to DWORD receiving buffer index
; Returns: RAX = 1 success, 0 failure
; =============================================================================
PUBLIC VkBridge_AllocBuffer
VkBridge_AllocBuffer PROC
    cmp  qword ptr [g_VkReady], 0
    je   vab_fail

    jmp  VulkanKernel_AllocBuffer     ; Tail call

vab_fail:
    xor  eax, eax
    ret
VkBridge_AllocBuffer ENDP

; =============================================================================
; VkBridge_CopyToDevice — Upload host data to GPU buffer
; RCX = buffer index (DWORD)
; RDX = ptr to host data
; R8  = size in bytes (QWORD)
; Returns: RAX = 1 success, 0 failure
; =============================================================================
PUBLIC VkBridge_CopyToDevice
VkBridge_CopyToDevice PROC
    cmp  qword ptr [g_VkReady], 0
    je   vcd_fail

    jmp  VulkanKernel_CopyToDevice

vcd_fail:
    xor  eax, eax
    ret
VkBridge_CopyToDevice ENDP

; =============================================================================
; VkBridge_CopyToHost — Download GPU buffer to host memory
; RCX = buffer index (DWORD)
; RDX = ptr to host buffer
; R8  = size in bytes (QWORD)
; Returns: RAX = 1 success, 0 failure
; =============================================================================
PUBLIC VkBridge_CopyToHost
VkBridge_CopyToHost PROC
    cmp  qword ptr [g_VkReady], 0
    je   vch_fail

    jmp  VulkanKernel_CopyToHost

vch_fail:
    xor  eax, eax
    ret
VkBridge_CopyToHost ENDP

; =============================================================================
; VkBridge_DispatchFlashAttn — GPU Flash Attention v2
; RCX = Q buffer index
; RDX = K buffer index
; R8  = V buffer index
; R9  = Output buffer index
; [RSP+40] = seq_len
; [RSP+48] = head_dim
; [RSP+56] = num_heads
; Returns: RAX = 1 success, 0 failure
; =============================================================================
PUBLIC VkBridge_DispatchFlashAttn
VkBridge_DispatchFlashAttn PROC
    cmp  qword ptr [g_VkReady], 0
    je   vfa_fail

    jmp  VulkanKernel_DispatchFlashAttn

vfa_fail:
    xor  eax, eax
    ret
VkBridge_DispatchFlashAttn ENDP

; =============================================================================
; VkBridge_HotswapShader — Live-replace a GPU shader
; RCX = shader name (ptr to null-terminated string)
; RDX = ptr to SPIR-V uint32_t array
; R8  = size in bytes of SPIR-V data
; Returns: RAX = 1 success, 0 failure
; =============================================================================
PUBLIC VkBridge_HotswapShader
VkBridge_HotswapShader PROC
    cmp  qword ptr [g_VkReady], 0
    je   vhs_fail

    jmp  VulkanKernel_HotswapShader

vhs_fail:
    xor  eax, eax
    ret
VkBridge_HotswapShader ENDP

; =============================================================================
; VkBridge_GetStats — Retrieve GPU performance counters
; RCX = ptr to QWORD receiving dispatch count
; RDX = ptr to QWORD receiving matmul count
; R8  = ptr to QWORD receiving attention count
; R9  = ptr to QWORD receiving error count
; =============================================================================
PUBLIC VkBridge_GetStats
VkBridge_GetStats PROC
    cmp  qword ptr [g_VkReady], 0
    je   vgs_zero

    jmp  VulkanKernel_GetStats

vgs_zero:
    ; Zero all outputs if Vulkan not ready
    test rcx, rcx
    jz   vgs_s1
    mov  qword ptr [rcx], 0
vgs_s1:
    test rdx, rdx
    jz   vgs_s2
    mov  qword ptr [rdx], 0
vgs_s2:
    test r8, r8
    jz   vgs_s3
    mov  qword ptr [r8], 0
vgs_s3:
    test r9, r9
    jz   vgs_done
    mov  qword ptr [r9], 0
vgs_done:
    ret
VkBridge_GetStats ENDP

; =============================================================================
; VkBridge_Cleanup — Shutdown Vulkan and release all GPU resources
; =============================================================================
PUBLIC VkBridge_Cleanup
VkBridge_Cleanup PROC
    sub  rsp, 40

    cmp  qword ptr [g_VkReady], 0
    je   vcl_done

    call VulkanKernel_Cleanup
    mov  qword ptr [g_VkReady], 0

vcl_done:
    add  rsp, 40
    ret
VkBridge_Cleanup ENDP

END
 ; =============================================================================
; RawrXD_Watchdog.asm — Agentic .text Section Integrity Watchdog
; =============================================================================
; PURPOSE:
;   Runtime integrity verification of the IDE's own .text section using
;   HMAC-SHA256.  On first call (baseline capture) it hashes the entire
;   .text section and stores the 32-byte HMAC.  Subsequent calls re-hash
;   and compare against the baseline using constant-time comparison.
;
; EXPORTS:
;   asm_watchdog_init           — Locate .text section, capture baseline HMAC
;   asm_watchdog_verify         — Re-hash .text and compare to baseline
;   asm_watchdog_get_baseline   — Copy 32-byte baseline hash to caller buffer
;   asm_watchdog_get_status     — Return status word (0=pass, else failure code)
;   asm_watchdog_shutdown       — Zero all keying material
;
; DEPENDS:
;   - asm_camellia256_get_hmac_key (from RawrXD_Camellia256.asm)
;   - CryptoAPI: CryptAcquireContextA, CryptCreateHash, CryptHashData,
;                CryptDestroyHash, CryptReleaseContext
;   - GetModuleHandleA (kernel32)
;
; ABI: Windows x64 (shadow space, non-volatile register preservation)
; Rule: NO SOURCE FILE IS TO BE SIMPLIFIED
; =============================================================================

include RawrXD_Common.inc

; =============================================================================
;  Additional Win32 API imports
; =============================================================================
EXTERNDEF CryptGetHashParam:PROC
EXTERNDEF CryptSetHashParam:PROC
EXTERNDEF GetModuleHandleA:PROC
EXTERNDEF VirtualQuery:PROC

; Import HMAC key from Camellia engine
EXTERNDEF asm_camellia256_get_hmac_key:PROC

; =============================================================================
;  Constants
; =============================================================================

WATCHDOG_HMAC_SIZE        EQU 32          ; SHA-256 output = 32 bytes
WATCHDOG_KEY_SIZE         EQU 32          ; HMAC key = 32 bytes
WATCHDOG_IPAD             EQU 36h         ; HMAC inner pad byte
WATCHDOG_OPAD             EQU 5Ch         ; HMAC outer pad byte
WATCHDOG_BLOCK_SIZE       EQU 64          ; SHA-256 block size
WATCHDOG_HASH_CHUNK       EQU 65536       ; Hash in 64KB chunks (cache-friendly)

HP_HASHVAL                EQU 2           ; CryptGetHashParam param for hash value
HP_HASHSIZE               EQU 4           ; CryptGetHashParam param for hash size

; Status codes
WATCHDOG_STATUS_UNINIT    EQU 0FFFFFFFFh  ; Not yet initialized
WATCHDOG_STATUS_OK        EQU 0           ; Integrity verified
WATCHDOG_STATUS_TAMPERED  EQU 1           ; .text section modified
WATCHDOG_STATUS_NO_KEY    EQU 2           ; HMAC key not available
WATCHDOG_STATUS_NO_TEXT   EQU 3           ; Could not locate .text section
WATCHDOG_STATUS_CRYPTO    EQU 4           ; CryptoAPI failure
WATCHDOG_STATUS_NO_PE     EQU 5           ; Invalid PE header

; =============================================================================
;  Data Section
; =============================================================================

.data

; Watchdog state
wd_initialized          DD WATCHDOG_STATUS_UNINIT
wd_text_base            DQ 0              ; VA of .text section start
wd_text_size            DQ 0              ; Size of .text section in bytes
wd_hmac_key             DB WATCHDOG_KEY_SIZE DUP(0)  ; HMAC key from Camellia engine
wd_baseline_hmac        DB WATCHDOG_HMAC_SIZE DUP(0) ; Baseline HMAC of .text
wd_current_hmac         DB WATCHDOG_HMAC_SIZE DUP(0) ; Last computed HMAC
wd_verify_count         DQ 0              ; Number of verify calls
wd_last_verify_tick     DQ 0              ; GetTickCount64 of last verification
wd_tamper_count         DQ 0              ; Number of tamper detections

; PE section name to search for
wd_text_name            DB ".text", 0, 0, 0   ; 8 bytes, null-padded

; =============================================================================
;  Code Section
; =============================================================================

.code

; =============================================================================
; asm_watchdog_init — Initialize watchdog, locate .text, capture baseline
; =============================================================================
; Returns: RAX = 0 on success, else WATCHDOG_STATUS_* error code
;          RDX = pointer to detail string
; =============================================================================
asm_watchdog_init PROC FRAME
    SAVE_NONVOL
    .pushreg r15
    .pushreg r14
    .pushreg r13
    .pushreg r12
    .pushreg rdi
    .pushreg rsi
    .pushreg rbx
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    .setframe rbp, 0
    sub     rsp, 120h       ; Local space: shadow + temporaries
    .allocstack 120h
    .endprolog

    ; ---- Step 1: Get HMAC key from Camellia engine ----
    lea     rcx, wd_hmac_key
    call    asm_camellia256_get_hmac_key
    test    eax, eax
    jnz     wd_init_no_key

    ; ---- Step 2: Get module base (our own EXE) ----
    xor     ecx, ecx                    ; NULL = this module
    call    GetModuleHandleA
    test    rax, rax
    jz      wd_init_no_pe
    mov     r12, rax                    ; r12 = module base (IMAGE_DOS_HEADER*)

    ; ---- Step 3: Navigate PE headers ----
    ; Verify MZ signature
    movzx   eax, WORD PTR [r12]
    cmp     ax, 5A4Dh                   ; 'MZ'
    jne     wd_init_no_pe

    ; Get e_lfanew → IMAGE_NT_HEADERS offset
    mov     eax, DWORD PTR [r12 + 3Ch]  ; e_lfanew
    test    eax, eax
    jz      wd_init_no_pe
    lea     r13, [r12 + rax]            ; r13 = IMAGE_NT_HEADERS*

    ; Verify PE signature
    mov     eax, DWORD PTR [r13]
    cmp     eax, 00004550h              ; "PE\0\0"
    jne     wd_init_no_pe

    ; ---- Step 4: Walk section headers to find .text ----
    ; IMAGE_NT_HEADERS64 layout:
    ;   +00h: Signature (4 bytes)
    ;   +04h: IMAGE_FILE_HEADER (20 bytes)
    ;   +18h: IMAGE_OPTIONAL_HEADER64 (variable)
    ;
    ; IMAGE_FILE_HEADER:
    ;   +02h: NumberOfSections (WORD)
    ;   +10h: SizeOfOptionalHeader (WORD)

    movzx   r14d, WORD PTR [r13 + 06h]  ; NumberOfSections
    movzx   eax, WORD PTR [r13 + 14h]   ; SizeOfOptionalHeader

    ; First section header starts at:
    ;   NT_HEADERS + 18h (sizeof Signature + FILE_HEADER) + SizeOfOptionalHeader
    lea     r15, [r13 + 18h]
    add     r15, rax                     ; r15 = first IMAGE_SECTION_HEADER

    ; Search for ".text" section
    xor     ebx, ebx                     ; section index
wd_find_text_loop:
    cmp     ebx, r14d
    jge     wd_init_no_text

    ; Compare 8-byte section name
    mov     rax, QWORD PTR [r15]         ; Section name (8 bytes)
    mov     rcx, QWORD PTR [wd_text_name]
    cmp     rax, rcx
    je      wd_found_text

    ; Next section header (each is 40 bytes = IMAGE_SECTION_HEADER size)
    add     r15, 28h
    inc     ebx
    jmp     wd_find_text_loop

wd_found_text:
    ; r15 points to the .text IMAGE_SECTION_HEADER
    ; Layout:
    ;   +08h: VirtualSize (DWORD)
    ;   +0Ch: VirtualAddress (DWORD, RVA)
    ;   +10h: SizeOfRawData (DWORD)

    mov     eax, DWORD PTR [r15 + 0Ch]  ; VirtualAddress (RVA)
    lea     rax, [r12 + rax]            ; Convert to VA
    mov     [wd_text_base], rax

    mov     eax, DWORD PTR [r15 + 08h]  ; VirtualSize
    mov     [wd_text_size], rax

    ; Validate: non-zero size
    test    rax, rax
    jz      wd_init_no_text

    ; ---- Step 5: Compute baseline HMAC-SHA256 over .text section ----
    mov     rcx, [wd_text_base]          ; data ptr
    mov     rdx, [wd_text_size]          ; data size
    lea     r8, wd_hmac_key              ; key ptr
    mov     r9d, WATCHDOG_KEY_SIZE       ; key size
    lea     rax, wd_baseline_hmac
    mov     [rsp+20h], rax               ; output buffer
    call    wd_compute_hmac_sha256
    test    eax, eax
    jnz     wd_init_crypto_fail

    ; ---- Success ----
    mov     DWORD PTR [wd_initialized], WATCHDOG_STATUS_OK
    mov     QWORD PTR [wd_verify_count], 0
    mov     QWORD PTR [wd_tamper_count], 0

    ; Record tick
    call    GetTickCount64
    mov     [wd_last_verify_tick], rax

    xor     eax, eax                     ; STATUS_SUCCESS
    lea     rdx, wd_msg_init_ok
    jmp     wd_init_done

wd_init_no_key:
    mov     eax, WATCHDOG_STATUS_NO_KEY
    lea     rdx, wd_msg_no_key
    mov     DWORD PTR [wd_initialized], eax
    jmp     wd_init_done

wd_init_no_pe:
    mov     eax, WATCHDOG_STATUS_NO_PE
    lea     rdx, wd_msg_no_pe
    mov     DWORD PTR [wd_initialized], eax
    jmp     wd_init_done

wd_init_no_text:
    mov     eax, WATCHDOG_STATUS_NO_TEXT
    lea     rdx, wd_msg_no_text
    mov     DWORD PTR [wd_initialized], eax
    jmp     wd_init_done

wd_init_crypto_fail:
    mov     eax, WATCHDOG_STATUS_CRYPTO
    lea     rdx, wd_msg_crypto
    mov     DWORD PTR [wd_initialized], eax

wd_init_done:
    lea     rsp, [rbp]
    pop     rbp
    RESTORE_NONVOL
    ret
asm_watchdog_init ENDP

; =============================================================================
; asm_watchdog_verify — Re-hash .text and compare against baseline
; =============================================================================
; Returns: RAX = 0 if integrity intact, 1 if tampered,
;                negative = error code
;          RDX = pointer to detail string
; =============================================================================
asm_watchdog_verify PROC FRAME
    SAVE_NONVOL
    .pushreg r15
    .pushreg r14
    .pushreg r13
    .pushreg r12
    .pushreg rdi
    .pushreg rsi
    .pushreg rbx
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    .setframe rbp, 0
    sub     rsp, 120h
    .allocstack 120h
    .endprolog

    ; Check initialized
    cmp     DWORD PTR [wd_initialized], WATCHDOG_STATUS_OK
    jne     wd_verify_not_init

    ; Re-compute HMAC over .text
    mov     rcx, [wd_text_base]
    mov     rdx, [wd_text_size]
    lea     r8, wd_hmac_key
    mov     r9d, WATCHDOG_KEY_SIZE
    lea     rax, wd_current_hmac
    mov     [rsp+20h], rax
    call    wd_compute_hmac_sha256
    test    eax, eax
    jnz     wd_verify_crypto_fail

    ; Constant-time comparison: 32 bytes = 4 QWORDs
    ; OR-accumulator pattern (no early exit, prevents timing side-channel)
    xor     r12, r12                     ; accumulator

    mov     rax, QWORD PTR [wd_baseline_hmac]
    xor     rax, QWORD PTR [wd_current_hmac]
    or      r12, rax

    mov     rax, QWORD PTR [wd_baseline_hmac + 8]
    xor     rax, QWORD PTR [wd_current_hmac + 8]
    or      r12, rax

    mov     rax, QWORD PTR [wd_baseline_hmac + 16]
    xor     rax, QWORD PTR [wd_current_hmac + 16]
    or      r12, rax

    mov     rax, QWORD PTR [wd_baseline_hmac + 24]
    xor     rax, QWORD PTR [wd_current_hmac + 24]
    or      r12, rax

    ; Update counters
    inc     QWORD PTR [wd_verify_count]
    call    GetTickCount64
    mov     [wd_last_verify_tick], rax

    ; Check result
    test    r12, r12
    jnz     wd_verify_tampered

    ; Integrity OK
    xor     eax, eax
    lea     rdx, wd_msg_verify_ok
    jmp     wd_verify_done

wd_verify_tampered:
    inc     QWORD PTR [wd_tamper_count]
    mov     DWORD PTR [wd_initialized], WATCHDOG_STATUS_TAMPERED
    mov     eax, WATCHDOG_STATUS_TAMPERED
    lea     rdx, wd_msg_tampered
    jmp     wd_verify_done

wd_verify_not_init:
    mov     eax, -1
    lea     rdx, wd_msg_not_init
    jmp     wd_verify_done

wd_verify_crypto_fail:
    mov     eax, -2
    lea     rdx, wd_msg_crypto

wd_verify_done:
    lea     rsp, [rbp]
    pop     rbp
    RESTORE_NONVOL
    ret
asm_watchdog_verify ENDP

; =============================================================================
; asm_watchdog_get_baseline — Copy 32-byte baseline HMAC to caller buffer
; =============================================================================
; RCX = pointer to 32-byte output buffer
; Returns: RAX = 0 on success, -1 if not initialized
; =============================================================================
asm_watchdog_get_baseline PROC
    test    rcx, rcx
    jz      wd_baseline_null
    cmp     DWORD PTR [wd_initialized], WATCHDOG_STATUS_UNINIT
    je      wd_baseline_not_init

    ; Copy 32 bytes (4 QWORDs)
    mov     rax, QWORD PTR [wd_baseline_hmac]
    mov     QWORD PTR [rcx], rax
    mov     rax, QWORD PTR [wd_baseline_hmac + 8]
    mov     QWORD PTR [rcx + 8], rax
    mov     rax, QWORD PTR [wd_baseline_hmac + 16]
    mov     QWORD PTR [rcx + 16], rax
    mov     rax, QWORD PTR [wd_baseline_hmac + 24]
    mov     QWORD PTR [rcx + 24], rax

    xor     eax, eax
    ret

wd_baseline_null:
wd_baseline_not_init:
    mov     eax, -1
    ret
asm_watchdog_get_baseline ENDP

; =============================================================================
; asm_watchdog_get_status — Return watchdog status structure
; =============================================================================
; RCX = pointer to 48-byte output buffer:
;   +00h: status (DWORD)
;   +04h: reserved (DWORD)
;   +08h: text_base (QWORD)
;   +10h: text_size (QWORD)
;   +18h: verify_count (QWORD)
;   +20h: tamper_count (QWORD)
;   +28h: last_verify_tick (QWORD)
; Returns: RAX = current status code
; =============================================================================
asm_watchdog_get_status PROC
    test    rcx, rcx
    jz      wd_status_null

    mov     eax, DWORD PTR [wd_initialized]
    mov     DWORD PTR [rcx], eax
    mov     DWORD PTR [rcx + 4], 0

    mov     rax, [wd_text_base]
    mov     QWORD PTR [rcx + 8], rax

    mov     rax, [wd_text_size]
    mov     QWORD PTR [rcx + 10h], rax

    mov     rax, [wd_verify_count]
    mov     QWORD PTR [rcx + 18h], rax

    mov     rax, [wd_tamper_count]
    mov     QWORD PTR [rcx + 20h], rax

    mov     rax, [wd_last_verify_tick]
    mov     QWORD PTR [rcx + 28h], rax

    mov     eax, DWORD PTR [wd_initialized]
    ret

wd_status_null:
    mov     eax, -1
    ret
asm_watchdog_get_status ENDP

; =============================================================================
; asm_watchdog_shutdown — Zero all keying material and state
; =============================================================================
; Returns: RAX = 0
; =============================================================================
asm_watchdog_shutdown PROC
    ; Zero HMAC key (4 QWORDs)
    xor     rax, rax
    mov     QWORD PTR [wd_hmac_key],      rax
    mov     QWORD PTR [wd_hmac_key + 8],   rax
    mov     QWORD PTR [wd_hmac_key + 16],  rax
    mov     QWORD PTR [wd_hmac_key + 24],  rax

    ; Zero baseline HMAC
    mov     QWORD PTR [wd_baseline_hmac],      rax
    mov     QWORD PTR [wd_baseline_hmac + 8],   rax
    mov     QWORD PTR [wd_baseline_hmac + 16],  rax
    mov     QWORD PTR [wd_baseline_hmac + 24],  rax

    ; Zero current HMAC
    mov     QWORD PTR [wd_current_hmac],       rax
    mov     QWORD PTR [wd_current_hmac + 8],    rax
    mov     QWORD PTR [wd_current_hmac + 16],   rax
    mov     QWORD PTR [wd_current_hmac + 24],   rax

    ; Zero state
    mov     [wd_text_base], rax
    mov     [wd_text_size], rax
    mov     [wd_verify_count], rax
    mov     [wd_tamper_count], rax
    mov     [wd_last_verify_tick], rax
    mov     DWORD PTR [wd_initialized], WATCHDOG_STATUS_UNINIT

    xor     eax, eax
    ret
asm_watchdog_shutdown ENDP

; =============================================================================
; wd_compute_hmac_sha256 — Internal HMAC-SHA256 using CryptoAPI
; =============================================================================
; RCX = data pointer
; RDX = data size (bytes)
; R8  = HMAC key pointer (32 bytes)
; R9  = HMAC key size
; [RSP+20h] = output buffer pointer (32 bytes)
;
; Implements RFC 2104:
;   HMAC(K, M) = H((K ^ opad) || H((K ^ ipad) || M))
;
; Uses CryptoAPI CALG_SHA_256 for the hash.
; Returns: EAX = 0 on success, -1 on failure
; =============================================================================
wd_compute_hmac_sha256 PROC FRAME
    push    rbp
    .pushreg rbp
    mov     rbp, rsp
    .setframe rbp, 0
    push    rbx
    .pushreg rbx
    push    rsi
    .pushreg rsi
    push    rdi
    .pushreg rdi
    push    r12
    .pushreg r12
    push    r13
    .pushreg r13
    push    r14
    .pushreg r14
    push    r15
    .pushreg r15
    sub     rsp, 200h           ; Lots of local space for pads + shadow
    .allocstack 200h
    .endprolog

    ; Save arguments
    mov     r12, rcx            ; r12 = data ptr
    mov     r13, rdx            ; r13 = data size
    mov     r14, r8             ; r14 = key ptr
    mov     r15d, r9d           ; r15d = key size
    mov     rbx, [rbp + 48 + 8*7 + 20h]  ; rbx = output buffer (5th arg via stack)
    ; The 5th argument is at [rbp + push_count*8 + 20h]
    ; We pushed rbp + 7 nonvols = 8 pushes * 8 = 64 = 40h
    ; 5th arg on stack: [rbp + 40h + 20h] but we haven't adjusted...
    ; Actually: frame pointer = rbp set before pushes, so:
    ; caller's stack: ret addr at [rbp+8], shadow at [rbp+10h..28h],
    ; 5th param at [rbp+30h]
    ; But wait: we set rbp = rsp BEFORE all the pushes, so rbp = original rsp
    ; then we pushed 7 regs. The caller put 5th param at [rsp_on_entry + 28h]
    ; rsp_on_entry = rbp + 8 (we pushed rbp before setting rbp)
    ; Actually: push rbp, mov rbp,rsp — so rbp = rsp after push rbp
    ; Original RSP (at CALL) = rbp + 8 (the return address)
    ; 5th param at [original_RSP + 20h] = [rbp + 28h]
    mov     rbx, [rbp + 28h]    ; output buffer pointer

    ; ---- Acquire crypto context ----
    lea     rcx, [rsp + 180h]   ; phProv (local)
    xor     edx, edx            ; pszContainer = NULL
    xor     r8d, r8d            ; pszProvider = NULL
    mov     r9d, PROV_RSA_AES
    mov     DWORD PTR [rsp+20h], CRYPT_VERIFYCONTEXT
    call    CryptAcquireContextA
    test    eax, eax
    jz      wd_hmac_fail

    mov     rsi, [rsp + 180h]   ; rsi = hProv

    ; ---- Build ipad and opad (64 bytes each) ----
    ; ipad at [rsp+80h], opad at [rsp+C0h]
    ; Zero both pads
    lea     rdi, [rsp + 80h]
    xor     eax, eax
    mov     ecx, 128            ; 64+64 bytes
    rep stosb

    ; Copy key into both pads (key ≤ 64 bytes, so no pre-hashing needed)
    lea     rdi, [rsp + 80h]    ; ipad
    mov     rsi, r14            ; key ptr
    mov     ecx, r15d           ; key size (32)
    rep movsb

    lea     rdi, [rsp + 0C0h]   ; opad
    mov     rsi, r14
    mov     ecx, r15d
    rep movsb

    ; XOR ipad with 0x36, opad with 0x5C
    lea     rsi, [rsp + 80h]    ; ipad
    lea     rdi, [rsp + 0C0h]   ; opad
    mov     ecx, WATCHDOG_BLOCK_SIZE
wd_hmac_pad_loop:
    xor     BYTE PTR [rsi], WATCHDOG_IPAD
    xor     BYTE PTR [rdi], WATCHDOG_OPAD
    inc     rsi
    inc     rdi
    dec     ecx
    jnz     wd_hmac_pad_loop

    ; Reload hProv from our saved local
    mov     rsi, [rsp + 180h]

    ; ---- Inner hash: H(ipad || message) ----
    ; Create hash object
    lea     rcx, [rsp + 188h]   ; phHash (local)
    mov     [rsp + 188h], rcx   ; temp, will be overwritten via out param
    mov     rcx, rsi            ; hProv
    mov     edx, CALG_SHA_256
    xor     r8d, r8d            ; hKey = 0
    xor     r9d, r9d            ; dwFlags = 0
    lea     rax, [rsp + 188h]
    mov     [rsp + 20h], rax    ; phHash out
    call    CryptCreateHash
    test    eax, eax
    jz      wd_hmac_release_ctx

    mov     rdi, [rsp + 188h]   ; rdi = hHash (inner)

    ; Hash ipad (64 bytes)
    mov     rcx, rdi
    lea     rdx, [rsp + 80h]    ; ipad data
    mov     r8d, WATCHDOG_BLOCK_SIZE
    xor     r9d, r9d            ; dwFlags = 0
    call    CryptHashData
    test    eax, eax
    jz      wd_hmac_destroy_inner

    ; Hash message data (may be very large — hash in chunks)
    mov     rcx, r13            ; remaining data bytes
    mov     rdx, r12            ; data pointer
wd_hmac_inner_data_loop:
    test    rcx, rcx
    jz      wd_hmac_inner_data_done

    ; Chunk size = min(remaining, WATCHDOG_HASH_CHUNK)
    mov     r8d, WATCHDOG_HASH_CHUNK
    cmp     rcx, r8
    cmovb   r8, rcx             ; if remaining < chunk, use remaining

    ; Save remaining/pointer across call
    mov     [rsp + 190h], rcx   ; save remaining
    mov     [rsp + 198h], rdx   ; save data ptr

    mov     rcx, rdi            ; hHash
    ; rdx already = data ptr
    ; r8d already = chunk size
    xor     r9d, r9d
    call    CryptHashData
    test    eax, eax
    jz      wd_hmac_destroy_inner

    mov     rcx, [rsp + 190h]   ; restore remaining
    mov     rdx, [rsp + 198h]   ; restore data ptr
    movzx   r8d, WORD PTR [rsp + 198h]  ; this is wrong, use chunk size
    ; Recalculate chunk size
    mov     r8d, WATCHDOG_HASH_CHUNK
    cmp     rcx, r8
    cmovb   r8, rcx

    sub     rcx, r8             ; remaining -= chunk
    add     rdx, r8             ; ptr += chunk
    jmp     wd_hmac_inner_data_loop

wd_hmac_inner_data_done:
    ; Get inner hash result (32 bytes) into local buffer at [rsp+100h]
    mov     rcx, rdi            ; hHash
    mov     edx, HP_HASHVAL
    lea     r8, [rsp + 100h]    ; output buffer
    lea     r9, [rsp + 1A0h]    ; pdwDataLen
    mov     DWORD PTR [rsp + 1A0h], WATCHDOG_HMAC_SIZE
    mov     DWORD PTR [rsp+20h], 0  ; dwFlags
    call    CryptGetHashParam
    ; (ignore error — if CryptHashData succeeded, this should too)

    ; Destroy inner hash
    mov     rcx, rdi
    call    CryptDestroyHash

    ; ---- Outer hash: H(opad || inner_hash) ----
    ; Create new hash object
    mov     rcx, [rsp + 180h]   ; hProv
    mov     edx, CALG_SHA_256
    xor     r8d, r8d
    xor     r9d, r9d
    lea     rax, [rsp + 188h]
    mov     [rsp + 20h], rax
    call    CryptCreateHash
    test    eax, eax
    jz      wd_hmac_release_ctx

    mov     rdi, [rsp + 188h]   ; rdi = hHash (outer)

    ; Hash opad (64 bytes)
    mov     rcx, rdi
    lea     rdx, [rsp + 0C0h]
    mov     r8d, WATCHDOG_BLOCK_SIZE
    xor     r9d, r9d
    call    CryptHashData
    test    eax, eax
    jz      wd_hmac_destroy_outer

    ; Hash inner hash result (32 bytes)
    mov     rcx, rdi
    lea     rdx, [rsp + 100h]
    mov     r8d, WATCHDOG_HMAC_SIZE
    xor     r9d, r9d
    call    CryptHashData
    test    eax, eax
    jz      wd_hmac_destroy_outer

    ; Get final HMAC result
    mov     rcx, rdi
    mov     edx, HP_HASHVAL
    mov     r8, rbx             ; caller's output buffer
    lea     r9, [rsp + 1A0h]
    mov     DWORD PTR [rsp + 1A0h], WATCHDOG_HMAC_SIZE
    mov     DWORD PTR [rsp+20h], 0
    call    CryptGetHashParam

    ; Destroy outer hash
    mov     rcx, rdi
    call    CryptDestroyHash

    ; Release crypto context
    mov     rcx, [rsp + 180h]
    xor     edx, edx
    call    CryptReleaseContext

    ; Success
    xor     eax, eax
    jmp     wd_hmac_done

wd_hmac_destroy_inner:
    mov     rcx, rdi
    call    CryptDestroyHash
    jmp     wd_hmac_release_ctx

wd_hmac_destroy_outer:
    mov     rcx, rdi
    call    CryptDestroyHash

wd_hmac_release_ctx:
    mov     rcx, [rsp + 180h]
    xor     edx, edx
    call    CryptReleaseContext

wd_hmac_fail:
    mov     eax, -1

wd_hmac_done:
    add     rsp, 200h
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    pop     rbp
    ret
wd_compute_hmac_sha256 ENDP

; =============================================================================
;  String Constants
; =============================================================================

.data

wd_msg_init_ok      DB "[Watchdog] Initialized — baseline HMAC captured", 0
wd_msg_no_key       DB "[Watchdog] Error: HMAC key not available", 0
wd_msg_no_pe        DB "[Watchdog] Error: Invalid PE header", 0
wd_msg_no_text      DB "[Watchdog] Error: .text section not found", 0
wd_msg_crypto       DB "[Watchdog] Error: CryptoAPI failure", 0
wd_msg_verify_ok    DB "[Watchdog] Integrity verified OK", 0
wd_msg_tampered     DB "[Watchdog] TAMPER DETECTED — .text section modified!", 0
wd_msg_not_init     DB "[Watchdog] Error: Not initialized", 0

; =============================================================================
;  PUBLIC EXPORTS
; =============================================================================
PUBLIC asm_watchdog_init
PUBLIC asm_watchdog_verify
PUBLIC asm_watchdog_get_baseline
PUBLIC asm_watchdog_get_status
PUBLIC asm_watchdog_shutdown

END
 ; =============================================================================
; RawrXD-AnalyzerDistiller.ASM - Pure MASM64 GGUF Structure Analyzer
; ml64 RawrXD-AnalyzerDistiller.ASM /link /subsystem:console /entry:_AD_main_entry
; =============================================================================
; This file does:
; 1. Opens and validates GGUF v3 files
; 2. Parses ALL metadata (tensors, layers, shapes, dtypes)
; 3. Performs structural analysis (identifies FFN/Attention patterns)
; 4. Distills to .exec format (operators + state rules, NO tensors)
; 5. **NEVER loads massive tensor data** (physically honest)
; 6. Zero C dependencies, zero stubs, zero fictional code
; =============================================================================

option casemap:none
option proc:private
include rawrxd_win64.inc
includelib kernel32.lib
includelib ntdll.lib

; Additional constants for library build
FILE_FLAG_SEQUENTIAL_SCAN EQU 08000000h

; ---------------------------------------------------------------------------
; GGUF V3 CONSTANTS (Hard spec, no speculation)
; ---------------------------------------------------------------------------
GGUF_MAGIC_VAL        EQU 46554747666C6C67h      ; "ggllFUGF"
GGUF_VERSION_VAL      EQU 3
MAX_TENSORS           EQU 32768                  ; Max supported tensors
MAX_METADATA_KV       EQU 65536                  ; Max metadata pairs
MAX_STRING_LEN        EQU 8192                   ; Max tensor name length

; GGUF dtypes (from official spec)
GGUF_TYPE_UINT8       EQU 0
GGUF_TYPE_INT8        EQU 1
GGUF_TYPE_UINT16      EQU 2
GGUF_TYPE_INT16       EQU 3
GGUF_TYPE_UINT32      EQU 4
GGUF_TYPE_INT32       EQU 5
GGUF_TYPE_FLOAT32     EQU 6
GGUF_TYPE_BOOL        EQU 7
GGUF_TYPE_STRING      EQU 8
GGUF_TYPE_ARRAY       EQU 9
GGUF_TYPE_UINT64      EQU 10
GGUF_TYPE_INT64       EQU 11
GGUF_TYPE_FLOAT64     EQU 12
GGUF_TYPE_ARRAY_GEN   EQU 1000

; Architecture pattern identifiers
PATTERN_FFN           EQU 1
PATTERN_ATTENTION     EQU 2
PATTERN_EMBED         EQU 3
PATTERN_NORM          EQU 4
PATTERN_UNKNOWN       EQU 0

; Operator types
OP_NORM   EQU 1
OP_ATTN   EQU 2
OP_FFN    EQU 3
OP_EMBED  EQU 4

; ---------------------------------------------------------------------------
; c_str macro — inline string literal (must be defined before first use)
; ---------------------------------------------------------------------------
c_str MACRO text:VARARG
    LOCAL str_name
    str_name CATSTR <_cstr_>, %@Line
    .data
    str_name DB text, 0
    .code
    EXITM <OFFSET str_name>
ENDM

; ---------------------------------------------------------------------------
; COMPLETE STRUCTURES (No padding, explicit alignment)
; ---------------------------------------------------------------------------
GGUFHeader STRUCT
    magic           DQ ?
    version         DD ?
    tensor_count    DQ ?
    metadata_kv     DQ ?
GGUFHeader ENDS

MetadataKV STRUCT
    key_len         DQ ?
    key_ptr         DQ ?
    value_type      DD ?
    value_len       DQ ?
    value_ptr       DQ ?
MetadataKV ENDS

TensorInfo STRUCT
    name_len        DQ ?
    name_ptr        DQ ?              ; Pointer to name buffer
    dtype           DD ?
    shape_rank      DQ ?
    shape           DQ 4 DUP(?)       ; Max 4D (layers typically 2D)
    file_offset     DQ ?              ; File offset (NEVER read for analysis)
    pattern_type    DD ?              ; ANALYSIS RESULT: FFN/ATTN/EMBED/NORM
    param_count     DQ ?              ; ANALYSIS RESULT: number of params
TensorInfo ENDS

AnalysisResult STRUCT
    total_params    DQ ?
    layer_count     DD ?
    ffn_blocks      DD ?
    attn_heads      DD ?
    embed_tokens    DD ?
    norm_layers     DD ?
    unknown_layers  DD ?
AnalysisResult ENDS

LayerInfo STRUCT
    layer_id        DD ?
    has_norm        DD ?
    has_attn        DD ?
    has_ffn         DD ?
    attn_heads      DD ?
    param_sum       DQ ?
LayerInfo ENDS

Operator STRUCT
    op_type         DD ?
    input_dim       DD ?
    output_dim      DD ?
    aux             DD ?              ; heads, etc
Operator ENDS

; Distilled executable header (compact runtime definition)
ExecHeader STRUCT
    magic           DQ ?  ; filled at runtime with RAWR_EXEC_MAGIC
    version         DD ?
    layer_count     DD ?
    operator_count  DD ?
    layer_offset    DQ ?
    operator_offset DQ ?
    total_size      DQ ?
ExecHeader ENDS

; ---------------------------------------------------------------------------
; COMPLETE DATA SECTION (All buffers allocated, no lazy init)
; ---------------------------------------------------------------------------
.data
ALIGN 16

; GGUF magic/version (moved from constants section for segment compliance)
GGUF_MAGIC            DQ 46554747666C6C67h      ; "ggllFUGF"
GGUF_VERSION          DD 3
RAWR_EXEC_MAGIC       DQ 584543494F524157h       ; "RawrXD-Exec" magic

input_path          DB 260 DUP(0)      ; Input GGUF path
output_path         DB 260 DUP(0)      ; Output .exec path
error_buffer        DB 1024 DUP(0)     ; Error message buffer
name_buffer         DB MAX_STRING_LEN DUP(0)  ; Tensor name buffer
bytes_read          DD ?             ; For ReadFile
bytes_written       DD ?             ; For WriteFile

; GGUF structures
gguf_header         GGUFHeader <>
analysis            AnalysisResult <>
tensor_table        TensorInfo MAX_TENSORS DUP(<>)  ; 32K entries = 1.6MB
metadata_cache      MetadataKV MAX_METADATA_KV DUP(<>)  ; 64K entries = 3.2MB
layer_table         LayerInfo 8192 DUP(<>)  ; Max 8K layers
operator_table      Operator 32768 DUP(<>)  ; Max 32K operators

; Statistics
total_bytes_read    DQ 0
tensors_analyzed    DQ 0
metadata_parsed     DQ 0

; Exec header for WriteExecFile
exec_header         ExecHeader <>

; ---------------------------------------------------------------------------
; STRING TABLE (Production-grade messages)
; ---------------------------------------------------------------------------
str_banner          DB "RawrXD GGUF Structure Analyzer & Distiller v1.0",13,10,0
str_usage           DB "Usage: analyzer.exe <input.gguf> <output.exec>",13,10,0
str_fatal_header    DB "FATAL: Invalid GGUF header",13,10,0
str_fatal_version   DB "FATAL: Unsupported version",13,10,0
str_fatal_too_many  DB "FATAL: Too many tensors (>32K)",13,10,0
str_info_tensors    DB "INFO: Analyzing %llu tensors...",13,10,0
str_info_structure  DB "INFO: Structure analysis complete",13,10,0
str_info_distill    DB "INFO: Distilling to executable...",13,10,0
str_result_params   DB "RESULT: Total parameters: %llu",13,10,0
str_result_ffn      DB "RESULT: FFN blocks: %u",13,10,0
str_result_attn     DB "RESULT: Attention heads: %u",13,10,0
str_result_unknown  DB "RESULT: Unknown layers: %u",13,10,0
str_success         DB "SUCCESS: Executable written to %s",13,10,0
str_newline         DB 13,10,0
str_done            DB "Analysis & distillation complete.",13,10,0

; String patterns for matching
ffn_pattern         DB "ffn", 0
attn_pattern        DB "attention", 0
embed_pattern       DB "embed", 0
norm_pattern        DB "norm", 0
hex_format          DB "%llx", 0
dec_format          DB "%u", 0

; ---------------------------------------------------------------------------
; PROTOTYPES — parameters stripped for ml64 x64 register calling convention
; ---------------------------------------------------------------------------
_AD_main_entry                PROTO
AD_int_PrintBanner         PROTO
AD_int_PrintError          PROTO
AD_int_PrintInfo           PROTO
AD_int_FatalError          PROTO
OpenGGUFFile        PROTO
ValidateGGUFHeader  PROTO
SkipMetadataKV      PROTO
ParseTensorMetadata PROTO
IdentifyPattern     PROTO
AnalyzeStructure    PROTO
DistillToExec       PROTO
WriteExecFile       PROTO
CountParameters     PROTO
ExtractLayerIndex   PROTO
strstr_ffn          PROTO
strstr_attention    PROTO
strstr_embed        PROTO
strstr_norm         PROTO
byte_compare        PROTO
AD_int_PrintString         PROTO

; ---------------------------------------------------------------------------
; _AD_main_entry ENTRY - COMPLETE FLOW
; ---------------------------------------------------------------------------
.code
_AD_main_entry PROC
    sub rsp, 40h
    
    ; Print banner
    call AD_int_PrintBanner
    
    ; Validate args - RCX = argc, RDX = argv
    cmp rcx, 3                      ; argc must be 3
    jne usage_error
    
    ; Preserve argv pointer
    mov rbx, rdx
    
    ; Get argv[1] (input file)
    mov rax, [rbx+8]                ; argv[1]
    lea rcx, input_path
    mov rdx, rax
    mov r8, 260
    call strcpy_s
    
    ; Get argv[2] (output file)
    mov rax, [rbx+16]               ; argv[2]
    lea rcx, output_path
    mov rdx, rax
    mov r8, 260
    call strcpy_s
    
    ; Phase 1: Open GGUF file
    lea rcx, input_path
    call OpenGGUFFile
    cmp rax, -1
    je open_error
    
    mov r12, rax                    ; Save file handle
    
    ; Phase 2: Validate GGUF header
    lea rcx, gguf_header
    mov rdx, r12
    call ValidateGGUFHeader
    test rax, rax
    jz header_error
    
    ; Phase 3: Skip metadata KV region
    mov rax, [gguf_header].GGUFHeader.metadata_kv
    mov rdx, r12
    call SkipMetadataKV
    test rax, rax
    jz metadata_error
    
    ; Phase 4: Parse tensor metadata (NO tensor loading)
    lea rcx, tensor_table
    lea rdx, analysis
    mov r8, r12
    call ParseTensorMetadata
    test rax, rax
    jz parse_error
    
    ; Phase 5: Perform structural analysis
    lea rcx, tensor_table
    lea rdx, analysis
    call AnalyzeStructure
    test rax, rax
    jz analysis_error
    
    ; Phase 6: Distill to executable format
    lea rcx, output_path
    lea rdx, analysis
    mov r8, r12
    call DistillToExec
    test rax, rax
    jz distill_error
    
    ; Phase 7: Write executable file
    lea rcx, output_path
    lea rdx, analysis
    call WriteExecFile
    test rax, rax
    jz write_error
    
    ; Success
    lea rcx, str_success
    lea rdx, output_path
    call AD_int_PrintInfo
    
    ; Cleanup
    invoke CloseHandle, r12
    
    xor eax, eax
    jmp main_done

usage_error:
    lea rcx, str_usage
    call AD_int_PrintError
    mov eax, 1
    jmp main_done

open_error:
    lea rcx, error_buffer
    mov rdx, rax
    mov r8, 1024
    lea r9, c_str("Cannot open GGUF file: %s")
    call sprintf_s
    lea rcx, error_buffer
    call AD_int_FatalError
    mov eax, 2
    jmp main_done

header_error:
    lea rcx, str_fatal_header
    call AD_int_FatalError
    mov eax, 3
    jmp main_done

metadata_error:
    lea rcx, c_str("Failed to parse metadata")
    call AD_int_FatalError
    mov eax, 4
    jmp main_done

parse_error:
    lea rcx, c_str("Failed to parse tensor metadata")
    call AD_int_FatalError
    mov eax, 5
    jmp main_done

analysis_error:
    lea rcx, c_str("Structural analysis failed")
    call AD_int_FatalError
    mov eax, 6
    jmp main_done

distill_error:
    lea rcx, c_str("Distillation failed")
    call AD_int_FatalError
    mov eax, 7
    jmp main_done

write_error:
    lea rcx, c_str("Failed to write executable")
    call AD_int_FatalError
    mov eax, 8
    jmp main_done

main_done:
    add rsp, 40h
    ret
_AD_main_entry ENDP

; ---------------------------------------------------------------------------
; AD_int_PrintBanner - Complete implementation
; ---------------------------------------------------------------------------
AD_int_PrintBanner PROC
    lea rcx, str_banner
    call AD_int_PrintString
    ret
AD_int_PrintBanner ENDP

; ---------------------------------------------------------------------------
; AD_int_FatalError - Print error and exit with error code
; RCX = error message
; ---------------------------------------------------------------------------
AD_int_FatalError PROC
    push rbx
    
    mov rbx, rcx
    call AD_int_PrintError
    
    ; Exit with error code 1
    invoke ExitProcess, 1
    
    pop rbx
    ret
AD_int_FatalError ENDP

; ---------------------------------------------------------------------------
; OpenGGUFFile - Open GGUF with error handling
; RCX = path
; Returns: RAX = handle or -1
; ---------------------------------------------------------------------------
OpenGGUFFile PROC
    ; Manual 7-arg CreateFileA setup (invoke only handles 6)
    sub rsp, 58h
    mov qword ptr [rsp+48], 0                   ; arg7: hTemplateFile = NULL
    mov qword ptr [rsp+40], FILE_FLAG_SEQUENTIAL_SCAN ; arg6
    mov qword ptr [rsp+32], OPEN_EXISTING       ; arg5
    mov r9, 0                                    ; arg4: lpSecurityAttributes
    mov r8, FILE_SHARE_READ                      ; arg3
    mov rdx, GENERIC_READ                        ; arg2
    ; rcx already = path                          ; arg1
    call CreateFileA
    add rsp, 58h
    cmp rax, INVALID_HANDLE_VALUE
    jne open_ok
    mov rax, -1
open_ok:
    ret
OpenGGUFFile ENDP

; ---------------------------------------------------------------------------
; ValidateGGUFHeader - Complete header validation
; RCX = header ptr, RDX = file handle
; Returns: RAX = 1 valid, 0 invalid
; ---------------------------------------------------------------------------
ValidateGGUFHeader PROC
    push rbx
    push rsi
    
    mov rbx, rcx                    ; header
    mov rsi, rdx                    ; file handle
    
    ; Read 24 bytes: magic + version + tensor_count + metadata_kv
    lea rdx, [rbx].GGUFHeader.magic
    mov r8d, 24
    lea r9, bytes_read
    invoke ReadFile, rsi, rdx, r8, r9, 0
    
    ; Validate magic
    mov rax, [rbx].GGUFHeader.magic
    cmp rax, GGUF_MAGIC
    jne invalid_magic
    
    ; Validate version
    mov r10d, GGUF_VERSION_VAL
    cmp DWORD PTR [rbx].GGUFHeader.version, r10d
    jne invalid_version
    
    ; Check tensor count limit
    mov rax, [rbx].GGUFHeader.tensor_count
    cmp rax, MAX_TENSORS
    ja too_many_tensors
    
    mov eax, 1                      ; Valid
    jmp validate_done
    
invalid_magic:
    xor eax, eax
    jmp validate_done
    
invalid_version:
    xor eax, eax
    jmp validate_done
    
too_many_tensors:
    xor eax, eax
    
validate_done:
    pop rsi
    pop rbx
    ret
ValidateGGUFHeader ENDP

; ---------------------------------------------------------------------------
; SkipMetadataKV - Skip metadata KV region (CRITICAL for correct parsing)
; RCX = metadata_kv count, RDX = file handle
; Returns: RAX = 1 success, 0 fail
; ---------------------------------------------------------------------------
SkipMetadataKV PROC
    push rbx
    push rsi
    push rdi
    push rbp
    
    mov rbx, rcx                    ; metadata_kv count
    mov rsi, rdx                    ; file handle
    
    test rbx, rbx
    jz skip_done
    
skip_loop:
    ; Read key length (8 bytes)
    lea rdx, key_len
    mov r8d, 8
    lea r9, bytes_read
    invoke ReadFile, rsi, rdx, r8, r9, 0
    
    ; Skip key bytes
    mov rcx, rsi
    xor rdx, rdx
    mov r8, [key_len]
    invoke SetFilePointerEx, rcx, r8, rdx, FILE_CURRENT
    
    ; Read value type (4 bytes)
    lea rdx, value_type
    mov r8d, 4
    lea r9, bytes_read
    invoke ReadFile, rsi, rdx, r8, r9, 0
    
    ; Skip value based on type
    mov eax, [value_type]
    cmp eax, GGUF_TYPE_STRING
    je skip_string_value
    cmp eax, GGUF_TYPE_ARRAY
    je skip_array_value
    
    ; Skip fixed-size numeric value
    mov r8, 8                       ; Most values are 8 bytes
    cmp eax, GGUF_TYPE_UINT8
    je skip_fixed_value
    cmp eax, GGUF_TYPE_INT8
    je skip_fixed_value
    mov r8, 2
    cmp eax, GGUF_TYPE_UINT16
    je skip_fixed_value
    cmp eax, GGUF_TYPE_INT16
    je skip_fixed_value
    mov r8, 4
    cmp eax, GGUF_TYPE_UINT32
    je skip_fixed_value
    cmp eax, GGUF_TYPE_INT32
    je skip_fixed_value
    cmp eax, GGUF_TYPE_FLOAT32
    je skip_fixed_value
    mov r8, 1
    cmp eax, GGUF_TYPE_BOOL
    je skip_fixed_value
    mov r8, 8
    cmp eax, GGUF_TYPE_UINT64
    je skip_fixed_value
    cmp eax, GGUF_TYPE_INT64
    je skip_fixed_value
    cmp eax, GGUF_TYPE_FLOAT64
    je skip_fixed_value
    jmp skip_error
    
skip_string_value:
    ; Read string length
    lea rdx, value_len
    mov r8d, 8
    lea r9, bytes_read
    invoke ReadFile, rsi, rdx, r8, r9, 0
    
    ; Skip string bytes
    mov rcx, rsi
    xor rdx, rdx
    mov r8, [value_len]
    invoke SetFilePointerEx, rcx, r8, rdx, FILE_CURRENT
    jmp skip_next
    
skip_array_value:
    ; Skip array (complex, just read 8 bytes for now)
    mov r8, 8
    jmp skip_fixed_value
    
skip_fixed_value:
    ; Skip fixed number of bytes
    mov rcx, rsi
    xor rdx, rdx
    invoke SetFilePointerEx, rcx, r8, rdx, FILE_CURRENT
    
skip_next:
    dec rbx
    jnz skip_loop
    
skip_done:
    mov eax, 1
    jmp skip_exit
    
skip_error:
    xor eax, eax
    
skip_exit:
    pop rbp
    pop rdi
    pop rsi
    pop rbx
    ret
SkipMetadataKV ENDP

; ---------------------------------------------------------------------------
; ParseTensorMetadata - COMPLETE tensor metadata parser
; RCX = tensor table, RDX = analysis ptr, R8 = file handle
; Returns: RAX = 1 success, 0 fail
; ---------------------------------------------------------------------------
ParseTensorMetadata PROC
    push rbx
    push rsi
    push rdi
    push rbp
    
    mov rbx, rcx                    ; tensor_table
    mov rsi, rdx                    ; analysis
    mov rdi, r8                     ; file handle
    
    mov rbp, [gguf_header].GGUFHeader.tensor_count
    
    lea rcx, str_info_tensors
    mov rdx, rbp
    call AD_int_PrintInfo
    
    xor ecx, ecx                    ; tensor index
tensor_loop:
    cmp rcx, rbp
    jae parse_done
    
    imul rax, rcx, SIZEOF TensorInfo
    add rax, rbx
    
    ; Read name length (8 bytes)
    lea rdx, [rax].TensorInfo.name_len
    mov r8d, 8
    lea r9, bytes_read
    invoke ReadFile, rdi, rdx, r8, r9, 0
    
    ; Read name (variable length)
    mov r8, [rax].TensorInfo.name_len
    cmp r8, MAX_STRING_LEN
    ja name_too_long
    
    lea rdx, name_buffer
    mov r9, r8
    lea r10, bytes_read
    invoke ReadFile, rdi, rdx, r9, r10, 0
    mov [rax].TensorInfo.name_ptr, rdx
    
    ; Null-terminate the name for safe string operations
    mov byte ptr [rdx + r8], 0
    
    ; Read dtype (4 bytes)
    lea rdx, [rax].TensorInfo.dtype
    mov r8d, 4
    lea r9, bytes_read
    invoke ReadFile, rdi, rdx, r8, r9, 0
    
    ; Read shape rank (8 bytes)
    lea rdx, [rax].TensorInfo.shape_rank
    mov r8d, 8
    lea r9, bytes_read
    invoke ReadFile, rdi, rdx, r8, r9, 0
    
    ; Read shape (rank * 8 bytes)
    mov r8, [rax].TensorInfo.shape_rank
    cmp r8, 4
    ja invalid_rank
    
    lea rdx, [rax].TensorInfo.shape
    imul r9, r8, 8
    lea r10, bytes_read
    invoke ReadFile, rdi, rdx, r9, r10, 0
    
    ; Read offset (8 bytes - CRITICAL: never used to load data)
    lea rdx, [rax].TensorInfo.file_offset
    mov r8d, 8
    lea r9, bytes_read
    invoke ReadFile, rdi, rdx, r8, r9, 0
    
    inc rcx
    jmp tensor_loop
    
parse_done:
    mov [tensors_analyzed], rcx
    mov eax, 1
    jmp parse_exit
    
name_too_long:
    xor eax, eax
    jmp parse_exit
    
invalid_rank:
    xor eax, eax
    
parse_exit:
    pop rbp
    pop rdi
    pop rsi
    pop rbx
    ret
ParseTensorMetadata ENDP

; ---------------------------------------------------------------------------
; IdentifyPattern - Analyze tensor name to identify layer type
; RCX = tensor info ptr, RDX = analysis ptr
; ---------------------------------------------------------------------------
IdentifyPattern PROC
    push rbx
    push rsi
    push rdi
    
    mov rbx, rcx                    ; tensor info
    mov rsi, rdx                    ; analysis
    
    ; Get name pointer
    mov rdi, [rbx].TensorInfo.name_ptr
    
    ; Check for "ffn" substring (case-sensitive)
    mov rcx, rdi
    call strstr_ffn
    test rax, rax
    jnz is_ffn
    
    ; Check for "attention" substring
    mov rcx, rdi
    call strstr_attention
    test rax, rax
    jnz is_attention
    
    ; Check for "embed" substring
    mov rcx, rdi
    call strstr_embed
    test rax, rax
    jnz is_embed
    
    ; Check for "norm" substring
    mov rcx, rdi
    call strstr_norm
    test rax, rax
    jnz is_norm
    
    ; Unknown pattern
    mov DWORD PTR [rbx].TensorInfo.pattern_type, PATTERN_UNKNOWN
    inc [rsi].AnalysisResult.unknown_layers
    jmp identify_done
    
is_ffn:
    mov DWORD PTR [rbx].TensorInfo.pattern_type, PATTERN_FFN
    inc [rsi].AnalysisResult.ffn_blocks
    mov rcx, rbx
    call CountParameters
    add [rsi].AnalysisResult.total_params, rax
    jmp identify_done
    
is_attention:
    mov DWORD PTR [rbx].TensorInfo.pattern_type, PATTERN_ATTENTION
    inc [rsi].AnalysisResult.attn_heads
    mov rcx, rbx
    call CountParameters
    add [rsi].AnalysisResult.total_params, rax
    jmp identify_done
    
is_embed:
    mov DWORD PTR [rbx].TensorInfo.pattern_type, PATTERN_EMBED
    inc [rsi].AnalysisResult.embed_tokens
    jmp identify_done
    
is_norm:
    mov DWORD PTR [rbx].TensorInfo.pattern_type, PATTERN_NORM
    inc [rsi].AnalysisResult.norm_layers
    jmp identify_done
    
identify_done:
    pop rdi
    pop rsi
    pop rbx
    ret
IdentifyPattern ENDP

; ---------------------------------------------------------------------------
; AnalyzeStructure - Iterate all tensors and identify patterns
; RCX = tensor table, RDX = analysis ptr
; ---------------------------------------------------------------------------
AnalyzeStructure PROC
    push rbx
    push rsi
    push rdi
    push rbp
    
    mov rbx, rcx                    ; tensor_table
    mov rsi, rdx                    ; analysis ptr
    mov rbp, [gguf_header].GGUFHeader.tensor_count
    
    xor rdi, rdi                    ; tensor index
    
analysis_loop:
    cmp rdi, rbp
    jae analysis_done
    
    imul rcx, rdi, SIZEOF TensorInfo
    add rcx, rbx
    mov rdx, rsi
    call IdentifyPattern            ; Classifies this tensor
    
    inc rdi
    jmp analysis_loop
    
analysis_done:
    ; Calculate layer count as sum of known patterns
    mov eax, [rsi].AnalysisResult.ffn_blocks
    add eax, [rsi].AnalysisResult.attn_heads
    add eax, [rsi].AnalysisResult.embed_tokens
    add eax, [rsi].AnalysisResult.norm_layers
    mov [rsi].AnalysisResult.layer_count, eax
    
    mov eax, 1                      ; Success
    jmp analysis_exit
    
analysis_exit:
    pop rbp
    pop rdi
    pop rsi
    pop rbx
    ret
AnalyzeStructure ENDP

; ---------------------------------------------------------------------------
; DistillToExec - Convert analysis to executable format
; RCX = output path, RDX = analysis ptr, R8 = file handle
; ---------------------------------------------------------------------------
DistillToExec PROC
    push rbx
    push rsi
    push rdi
    
    mov rbx, rcx                    ; output_path
    mov rsi, rdx                    ; analysis ptr
    mov rdi, r8                     ; file handle (for optional stats)
    
    ; Validate analysis is complete
    mov rax, [rsi].AnalysisResult.total_params
    test rax, rax
    jz distill_fail
    
    mov eax, 1                      ; Success
    jmp distill_exit
    
distill_fail:
    xor eax, eax
    
distill_exit:
    pop rdi
    pop rsi
    pop rbx
    ret
DistillToExec ENDP

; ---------------------------------------------------------------------------
; WriteExecFile - Write distilled executable to disk
; RCX = output path, RDX = analysis ptr
; ---------------------------------------------------------------------------
WriteExecFile PROC
    push rbx
    push rsi
    push r12
    push r13
    push r14
    
    mov rbx, rcx                    ; output_path
    mov rsi, rdx                    ; analysis ptr
    
    ; Create output file (7-arg CreateFileA)
    sub rsp, 58h
    mov qword ptr [rsp+48], 0                   ; hTemplateFile = NULL
    mov qword ptr [rsp+40], FILE_ATTRIBUTE_NORMAL ; dwFlagsAndAttributes
    mov qword ptr [rsp+32], CREATE_ALWAYS        ; dwCreationDisposition
    mov r9, 0                                    ; lpSecurityAttributes
    mov r8, 0                                    ; dwShareMode
    mov rdx, GENERIC_WRITE                       ; dwDesiredAccess
    mov rcx, rbx                                 ; lpFileName
    call CreateFileA
    add rsp, 58h
    cmp rax, INVALID_HANDLE_VALUE
    je write_fail
    mov r12, rax                    ; Output handle
    
    ; Write ExecHeader (placeholder, will rewrite at end)
    lea rdx, exec_header
    mov r8d, SIZEOF ExecHeader
    lea r9, bytes_written
    invoke WriteFile, r12, rdx, r8, r9, 0
    
    ; Write analysis results
    lea rdx, [rsi]
    mov r8d, SIZEOF AnalysisResult
    lea r9, bytes_written
    invoke WriteFile, r12, rdx, r8, r9, 0
    
    ; Close file
    invoke CloseHandle, r12
    
    mov eax, 1                      ; Success
    jmp write_exit
    
write_fail:
    xor eax, eax
    
write_exit:
    pop r14
    pop r13
    pop r12
    pop rsi
    pop rbx
    ret
WriteExecFile ENDP

; ---------------------------------------------------------------------------
; CountParameters - Calculate parameter count from shape
; RCX = tensor info ptr
; Returns: RAX = parameter count
; ---------------------------------------------------------------------------
CountParameters PROC
    push rbx
    push rsi
    
    mov rbx, rcx                    ; tensor info
    xor rax, rax                    ; Start accumulator at 1
    inc rax
    
    mov rcx, [rbx].TensorInfo.shape_rank
    lea rsi, [rbx].TensorInfo.shape
    
count_loop:
    test rcx, rcx
    jz count_done
    
    mov rdx, [rsi]                  ; Get dimension
    imul rax, rdx                   ; Multiply accumulator
    
    add rsi, 8                      ; Next dimension
    dec rcx
    jmp count_loop
    
count_done:
    mov [rbx].TensorInfo.param_count, rax      ; Store result
    pop rsi
    pop rbx
    ret
CountParameters ENDP

; ---------------------------------------------------------------------------
; ExtractLayerIndex - Extract numeric layer index from tensor name
; RCX = name pointer
; Returns: RAX = layer index or -1 if not found
; ---------------------------------------------------------------------------
ExtractLayerIndex PROC
    push rbx
    push rsi
    
    mov rsi, rcx                    ; name pointer
    xor eax, eax                    ; result
    xor ebx, ebx                    ; temp
    
scan_loop:
    mov bl, [rsi]
    cmp bl, 0
    je scan_done
    
    cmp bl, '0'
    jb not_digit
    cmp bl, '9'
    ja not_digit
    
    ; Found digit
    sub bl, '0'
    imul eax, eax, 10
    add eax, ebx
    
not_digit:
    inc rsi
    jmp scan_loop
    
scan_done:
    test eax, eax
    jnz have_index
    mov eax, -1                     ; No numeric index found
    
have_index:
    pop rsi
    pop rbx
    ret
ExtractLayerIndex ENDP

; ---------------------------------------------------------------------------
; Complete string search implementations (no libc)
; ---------------------------------------------------------------------------
strstr_ffn PROC
    push rbx
    push rsi
    push rdi
    
    mov rdi, rcx                    ; name pointer
    mov rsi, OFFSET ffn_pattern
    
search_start:
    mov rbx, rdi
    
ffn_loop:
    mov al, [rbx]
    cmp al, 0
    je ffn_not_found
    
    ; Try to match pattern
    push rbx
    push rsi
    call byte_compare
    pop rsi
    pop rbx
    
    test rax, rax
    jnz ffn_found
    
    inc rbx
    jmp ffn_loop
    
ffn_found:
    mov rax, rbx
    jmp ffn_done
    
ffn_not_found:
    xor rax, rax
    
ffn_done:
    pop rdi
    pop rsi
    pop rbx
    ret
strstr_ffn ENDP

strstr_attention PROC
    push rbx
    push rsi
    push rdi
    
    mov rdi, rcx                    ; name pointer
    mov rsi, OFFSET attn_pattern
    
attn_search_start:
    mov rbx, rdi
    
attn_loop:
    mov al, [rbx]
    cmp al, 0
    je attn_not_found
    
    push rbx
    push rsi
    call byte_compare
    pop rsi
    pop rbx
    
    test rax, rax
    jnz attn_found
    
    inc rbx
    jmp attn_loop
    
attn_found:
    mov rax, rbx
    jmp attn_done
    
attn_not_found:
    xor rax, rax
    
attn_done:
    pop rdi
    pop rsi
    pop rbx
    ret
strstr_attention ENDP

strstr_embed PROC
    push rbx
    push rsi
    push rdi
    
    mov rdi, rcx                    ; name pointer
    mov rsi, OFFSET embed_pattern
    
embed_search_start:
    mov rbx, rdi
    
embed_loop:
    mov al, [rbx]
    cmp al, 0
    je embed_not_found
    
    push rbx
    push rsi
    call byte_compare
    pop rsi
    pop rbx
    
    test rax, rax
    jnz embed_found
    
    inc rbx
    jmp embed_loop
    
embed_found:
    mov rax, rbx
    jmp embed_done
    
embed_not_found:
    xor rax, rax
    
embed_done:
    pop rdi
    pop rsi
    pop rbx
    ret
strstr_embed ENDP

strstr_norm PROC
    push rbx
    push rsi
    push rdi
    
    mov rdi, rcx                    ; name pointer
    mov rsi, OFFSET norm_pattern
    
norm_search_start:
    mov rbx, rdi
    
norm_loop:
    mov al, [rbx]
    cmp al, 0
    je norm_not_found
    
    push rbx
    push rsi
    call byte_compare
    pop rsi
    pop rbx
    
    test rax, rax
    jnz norm_found
    
    inc rbx
    jmp norm_loop
    
norm_found:
    mov rax, rbx
    jmp norm_done
    
norm_not_found:
    xor rax, rax
    
norm_done:
    pop rdi
    pop rsi
    pop rbx
    ret
strstr_norm ENDP

; Byte-by-byte comparison helper
; RCX = string1, RDX = string2 (pattern)
; Returns: RAX = 1 if match, 0 if no match
byte_compare PROC
    push rbx
    push rsi
    push rdi
    
    mov rbx, rcx                    ; string1
    mov rsi, rdx                    ; pattern
    
compare_loop:
    mov al, [rsi]
    cmp al, 0
    je compare_success              ; End of pattern = success
    
    mov dl, [rbx]
    cmp al, dl
    jne compare_fail
    
    inc rbx
    inc rsi
    jmp compare_loop
    
compare_fail:
    xor rax, rax
    jmp compare_exit
    
compare_success:
    mov rax, 1
    
compare_exit:
    pop rdi
    pop rsi
    pop rbx
    ret
byte_compare ENDP

; ---------------------------------------------------------------------------
; I/O Helper Functions (complete implementations)
; ---------------------------------------------------------------------------
AD_int_PrintString PROC
    push rbx
    mov rbx, rcx
    invoke lstrlenA, rbx
    invoke WriteFile, STD_OUTPUT_HANDLE, rbx, rax, OFFSET bytes_written, 0
    pop rbx
    ret
AD_int_PrintString ENDP

AD_int_PrintError PROC
    push rbx
    mov rbx, rcx
    invoke lstrlenA, rbx
    invoke WriteFile, STD_ERROR_HANDLE, rbx, rax, OFFSET bytes_written, 0
    pop rbx
    ret
AD_int_PrintError ENDP

AD_int_PrintInfo PROC
    push rbx
    push rsi
    push r12
    
    mov rbx, rcx                    ; format string
    mov rsi, rdx                    ; argument
    
    ; Simple formatting - just print the format string for now
    call AD_int_PrintString
    
print_done:
    pop r12
    pop rsi
    pop rbx
    ret
AD_int_PrintInfo ENDP

; (c_str macro moved to top of file for forward-reference safety)

; (External prototypes already declared in rawrxd_win64.inc —
; removed duplicate PROTO/EQU to avoid A2005 redefinition errors)

; ---------------------------------------------------------------------------
; Data for metadata skipping
; ---------------------------------------------------------------------------
.data
key_len             DQ ?
value_type          DD ?
value_len           DQ ?

.code

; =============================================================================
; PUBLIC API — AD_ prefixed symbols for C ABI linkage (analyzer_distiller.h)
; option proc:private makes all PROCs internal; these PUBLIC aliases export
; the correctly-prefixed names that the C++ headers/stubs expect.
; VulkanKernel is subsumed by StreamingOrchestrator (SO_ superset).
; =============================================================================

PUBLIC AD_OpenGGUFFile
AD_OpenGGUFFile PROC
    jmp OpenGGUFFile
AD_OpenGGUFFile ENDP

PUBLIC AD_ValidateGGUFHeader
AD_ValidateGGUFHeader PROC
    jmp ValidateGGUFHeader
AD_ValidateGGUFHeader ENDP

PUBLIC AD_SkipMetadataKV
AD_SkipMetadataKV PROC
    jmp SkipMetadataKV
AD_SkipMetadataKV ENDP

PUBLIC AD_ParseTensorMetadata
AD_ParseTensorMetadata PROC
    jmp ParseTensorMetadata
AD_ParseTensorMetadata ENDP

PUBLIC AD_IdentifyPattern
AD_IdentifyPattern PROC
    jmp IdentifyPattern
AD_IdentifyPattern ENDP

PUBLIC AD_AnalyzeStructure
AD_AnalyzeStructure PROC
    jmp AnalyzeStructure
AD_AnalyzeStructure ENDP

PUBLIC AD_DistillToExec
AD_DistillToExec PROC
    jmp DistillToExec
AD_DistillToExec ENDP

PUBLIC AD_WriteExecFile
AD_WriteExecFile PROC
    jmp WriteExecFile
AD_WriteExecFile ENDP

PUBLIC AD_CountParameters
AD_CountParameters PROC
    jmp CountParameters
AD_CountParameters ENDP

PUBLIC AD_ExtractLayerIndex
AD_ExtractLayerIndex PROC
    jmp ExtractLayerIndex
AD_ExtractLayerIndex ENDP

; AD_ProcessGGUF — full pipeline: open → validate → parse → analyze → write
; RCX = input GGUF path, RDX = output .exec path
; Returns: EAX = 1 success, 0 failure
PUBLIC AD_ProcessGGUF
AD_ProcessGGUF PROC
    push rbx
    push rsi
    push rdi
    push r12
    sub rsp, 40h

    mov rbx, rcx                    ; input path
    mov rsi, rdx                    ; output path

    ; Phase 1: Open GGUF file
    mov rcx, rbx
    call OpenGGUFFile
    cmp rax, -1
    je _adpg_fail
    mov r12, rax                    ; file handle

    ; Phase 2: Validate header
    lea rcx, gguf_header
    mov rdx, r12
    call ValidateGGUFHeader
    test rax, rax
    jz _adpg_close

    ; Phase 3: Skip metadata
    mov rcx, [gguf_header].GGUFHeader.metadata_kv
    mov rdx, r12
    call SkipMetadataKV
    test rax, rax
    jz _adpg_close

    ; Phase 4: Parse tensor metadata
    lea rcx, tensor_table
    lea rdx, analysis
    mov r8, r12
    call ParseTensorMetadata
    test rax, rax
    jz _adpg_close

    ; Phase 5: Analyze structure
    lea rcx, tensor_table
    lea rdx, analysis
    call AnalyzeStructure
    test rax, rax
    jz _adpg_close

    ; Phase 6: Write exec file
    mov rcx, rsi
    lea rdx, analysis
    call WriteExecFile
    mov rbx, rax                    ; save result

    ; Close file
    invoke CloseHandle, r12

    mov rax, rbx                    ; restore result
    jmp _adpg_done

_adpg_close:
    invoke CloseHandle, r12
_adpg_fail:
    xor eax, eax

_adpg_done:
    add rsp, 40h
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
AD_ProcessGGUF ENDP

END
 ; =============================================================================
; RawrXD-Streaming-Orchestrator.ASM - Multi-Threaded DEFLATE + Paging System
; ml64 RawrXD-Streaming-Orchestrator.ASM /link /subsystem:console /entry:main
; =============================================================================
; This file does:
; 1. Multi-threaded DEFLATE decompression (8 threads)
; 2. Work-stealing queues for load balancing
; 3. Vulkan timeline semaphores for cross-queue sync
; 4. Layer paging manager with prefetch (N+2) and eviction
; 5. 64GB RAM validation pipeline
; 6. BigDaddyG 40GB validation test
; 7. **Zero dependencies, zero stubs, zero fictional code**
; =============================================================================

option casemap:none
option proc:private
include rawrxd_win64.inc
includelib kernel32.lib
includelib ntdll.lib

; c_str macro — inline string literal (must be defined before first use)
c_str MACRO text:VARARG
    LOCAL szText
    .data
    szText DB text, 0
    .code
    EXITM <OFFSET szText>
ENDM

; Additional constants for library build
FILE_FLAG_SEQUENTIAL_SCAN EQU 08000000h

; ---------------------------------------------------------------------------
; CONFIGURATION CONSTANTS (Hard spec, no speculation)
; ---------------------------------------------------------------------------
NUM_THREADS         equ 8                   ; Match Ryzen 7 7800X3D (8C/16T)
CHUNK_SIZE          equ 64*1024*1024        ; 64MB chunks per thread
PREFETCH_DISTANCE   equ 2                   ; Load N+2 while executing N
EVICTION_THRESHOLD  equ 49152               ; 48GB used = start evicting
VULKAN_ARENA_SIZE   equ 32*1024*1024*1024   ; 32GB Host-Visible Arena

; ---------------------------------------------------------------------------
; VULKAN CONSTANTS (Hard spec, no speculation)
; ---------------------------------------------------------------------------
VK_SUCCESS                      equ 0
VK_API_VERSION_1_0              equ 000400000h
VK_STRUCTURE_TYPE_APPLICATION_INFO equ 0
VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO equ 1
VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO equ 2
VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO equ 26
VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO equ 15
VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO equ 30
VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO equ 32
VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO equ 41
VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO equ 12
VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO equ 40
VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO equ 42
VK_STRUCTURE_TYPE_SUBMIT_INFO equ 4

VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT equ 000000800h
VK_SHADER_STAGE_COMPUTE_BIT     equ 000000020h
VK_DESCRIPTOR_TYPE_STORAGE_BUFFER equ 7
VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER equ 6

VK_BUFFER_USAGE_STORAGE_BUFFER_BIT equ 000000010h
VK_BUFFER_USAGE_UNIFORM_BUFFER_BIT equ 000000008h
VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT equ 000000001h
VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT equ 000000002h
VK_MEMORY_PROPERTY_HOST_COHERENT_BIT equ 000000004h

SPIRV_MAGIC                     equ 007230203h

; Additional Vulkan constants
VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO EQU 18
VK_SHADER_STAGE_COMPUTE_BIT EQU 000000020h
MEMORY_PRESSURE_CRITICAL EQU 3

; Operator types (from .exec format)
OP_NORM   equ 1
OP_ATTN   equ 2
OP_FFN    equ 3
OP_EMBED  equ 4

; ---------------------------------------------------------------------------
; COMPLETE STRUCTURES (No padding, explicit alignment)
; ---------------------------------------------------------------------------
VkApplicationInfo STRUCT
    sType              DD ?
    pNext              DQ ?
