CreateAttentionPipeline ENDP

; ---------------------------------------------------------------------------
; CreateFFNPipeline - Create FFN compute pipeline
; RCX = shader module pointer
; Returns: RAX = 1 (success) or 0 (failure)
; ---------------------------------------------------------------------------
CreateFFNPipeline PROC
    push rbx
    push rsi
    push rdi
    
    mov rbx, rcx                    ; shader module
    
    ; Create shader module
