; ============================================================================
; SECTION: Uninitialized Data (BSS)
; ============================================================================
section .bss
    align 16
    
    ; === Compiler State ===
    compiler_state          resq 1      ; Current compilation stage
    error_code              resq 1      ; Last error code
    error_line              resq 1      ; Error line number
    error_column            resq 1      ; Error column number
    verbose_mode            resb 1      ; Verbose output flag
    debug_info              resb 1      ; Include debug info flag
    opt_level               resb 1      ; Optimization level
    target_arch             resb 1      ; Target architecture
    output_format           resb 1      ; Output format
    
    ; === Memory Pools ===
    heap_start              resq 1
    heap_end                resq 1  
    heap_current            resq 1
    
    ; === Source Management ===
    source_buffer           resb SOURCE_BUFFER_SIZE
    source_length           resq 1
    source_pos              resq 1
    current_line            resq 1
    current_column          resq 1
    
    ; === Lexer State ===
    token_buffer            resb TOKEN_BUFFER_SIZE
    token_count             resq 1
    token_pos               resq 1
    current_token_type      resq 1
    current_token_start     resq 1
    current_token_length    resq 1
    current_token_value     resq 1
    
    ; === Parser State ===
    ast_pool                resb AST_POOL_SIZE
    ast_pool_pos            resq 1
    ast_root                resq 1
    ast_node_count          resq 1
    parse_errors            resq 1
    
    ; === Symbol Table ===
    symbol_table            resb SYMBOL_TABLE_SIZE
    symbol_count            resq 1
    scope_stack             resq 256    ; Max 256 nested scopes
    scope_depth             resq 1
    
    ; === IR Generation ===
    ir_buffer               resb IR_BUFFER_SIZE
    ir_pos                  resq 1
    ir_instruction_count    resq 1
    temp_var_counter        resq 1
    label_counter           resq 1
    
    ; === Code Generation ===
    output_buffer           resb OUTPUT_BUFFER_SIZE
    output_pos              resq 1
    code_section_start      resq 1
    data_section_start      resq 1
    bss_section_start       resq 1
    reloc_table             resq 1024   ; Relocation entries
    reloc_count             resq 1
    
    ; === File Paths ===
    input_file              resb 512
    output_file             resb 512
    temp_file               resb 512
    
    ; === Temporary Buffers ===
    temp_buffer             resb 4096
    error_buffer            resb 1024
    name_buffer             resb 256

; ============================================================================
; SECTION: Code
; ============================================================================
section .text
    global _start
    global main
    global compile_source
    global compile_file
    global initialize_compiler
    global cleanup_compiler
    global get_error_message
    
    ; External functions (when linking with C runtime)
    extern malloc
    extern free
    extern fopen
    extern fread
    extern fwrite
    extern fclose
    extern printf
    extern exit

; ============================================================================
; ENTRY POINT
; ============================================================================
_start:
main:
    push rbp
    mov rbp, rsp
    sub rsp, 64                     ; Local variables
    
    ; Save argc, argv
    mov [rbp-8], rdi                ; argc
    mov [rbp-16], rsi               ; argv
    
    ; Print banner
    lea rdi, [COMPILER_BANNER]
    call print_string
    
    ; Initialize compiler subsystems
    call initialize_compiler
    test rax, rax
    jnz .init_error
    
    ; Parse command line arguments
    mov rdi, [rbp-8]                ; argc
    mov rsi, [rbp-16]               ; argv
    call parse_arguments
    test rax, rax
    jnz .arg_error
    
    ; Check if we have an input file
    lea rdi, [input_file]
    cmp byte [rdi], 0
    je .no_input
    
    ; Compile the input file
    lea rdi, [input_file]
    lea rsi, [output_file]
    call compile_file
    test rax, rax
    jnz .compile_error
    
    ; Print success message
    lea rdi, [msg_done]
    call print_string
    
    ; Cleanup and exit
    call cleanup_compiler
    xor eax, eax
    jmp .exit
    
.init_error:
    lea rdi, [err_init_failed]
    call print_error
    mov eax, 1
    jmp .exit
    
.arg_error:
    lea rdi, [msg_usage]
    call print_string
    mov eax, 1
    jmp .exit
    
.no_input:
    lea rdi, [msg_usage]
    call print_string
    xor eax, eax
    jmp .exit
    
.compile_error:
    call print_compile_error
    mov eax, 1
    
.exit:
    mov rsp, rbp
    pop rbp
    
    ; Exit syscall (Linux) or ret (Windows)
%ifdef LINUX
    mov rdi, rax
    mov rax, 60                     ; sys_exit
    syscall
%else
    ret
%endif

; ============================================================================
; COMPILER INITIALIZATION
; ============================================================================
initialize_compiler:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    
    ; Initialize state
    mov qword [compiler_state], STAGE_INIT
    mov qword [error_code], ERR_NONE
    mov byte [verbose_mode], 0
    mov byte [debug_info], 0
    mov byte [opt_level], 1
    mov byte [target_arch], TARGET_X86_64
    mov byte [output_format], OUTPUT_EXE
    
    ; Initialize heap
    lea rax, [heap_memory]
    mov [heap_start], rax
    mov [heap_current], rax
    add rax, HEAP_SIZE
    mov [heap_end], rax
    
    ; Initialize source management
    mov qword [source_length], 0
    mov qword [source_pos], 0
    mov qword [current_line], 1
    mov qword [current_column], 1
    
    ; Initialize lexer
    mov qword [token_count], 0
    mov qword [token_pos], 0
    
    ; Initialize parser
    mov qword [ast_pool_pos], 0
    mov qword [ast_root], 0
    mov qword [ast_node_count], 0
    mov qword [parse_errors], 0
    
    ; Initialize symbol table
    mov qword [symbol_count], 0
    mov qword [scope_depth], 0
    
    ; Initialize IR generator
    mov qword [ir_pos], 0
    mov qword [ir_instruction_count], 0
    mov qword [temp_var_counter], 0
    mov qword [label_counter], 0
    
    ; Initialize code generator
    mov qword [output_pos], 0
    mov qword [reloc_count], 0
    
    ; Default output file
    lea rdi, [output_file]
    lea rsi, [default_output]
    call copy_string
    
    ; Success
    xor eax, eax
    
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; ============================================================================
; COMMAND LINE PARSING
; ============================================================================
parse_arguments:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    
    mov r12, rdi                    ; argc
    mov r13, rsi                    ; argv
    mov r14, 1                      ; Start from argv[1]
    
.arg_loop:
    cmp r14, r12
    jge .arg_done
    
    ; Get current argument
    mov rdi, [r13 + r14*8]
    
    ; Check for options (starts with -)
    cmp byte [rdi], '-'
    jne .input_file
    
    ; Check option type
    mov al, [rdi + 1]
    
    cmp al, 'o'
    je .opt_output
    
    cmp al, 't'
    je .opt_target
    
    cmp al, 'f'
    je .opt_format
    
    cmp al, 'O'
    je .opt_optimize
    
    cmp al, 'g'
    je .opt_debug
    
    cmp al, 'v'
    je .opt_verbose
    
    cmp al, 'h'
    je .opt_help
    
    cmp al, '-'
    je .long_option
    
    jmp .next_arg
    
.opt_output:
    inc r14
    cmp r14, r12
    jge .missing_value
    mov rdi, [r13 + r14*8]
    lea rsi, [output_file]
    call copy_string
    jmp .next_arg
    
.opt_target:
    inc r14
    cmp r14, r12
    jge .missing_value
    mov rdi, [r13 + r14*8]
    call parse_target
    mov [target_arch], al
    jmp .next_arg
    
.opt_format:
    inc r14
    cmp r14, r12
    jge .missing_value
    mov rdi, [r13 + r14*8]
    call parse_format
    mov [output_format], al
    jmp .next_arg
    
.opt_optimize:
    movzx eax, byte [rdi + 2]
    sub al, '0'
    cmp al, 3
    ja .next_arg
    mov [opt_level], al
    jmp .next_arg
    
.opt_debug:
    mov byte [debug_info], 1
    jmp .next_arg
    
.opt_verbose:
    mov byte [verbose_mode], 1
    jmp .next_arg
    
.opt_help:
    mov eax, 2                      ; Signal to show help
    jmp .arg_exit
    
.long_option:
    lea rsi, [opt_version]
    add rdi, 2
    call string_compare
    test eax, eax
    jz .show_version
    jmp .next_arg
    
.show_version:
    lea rdi, [COMPILER_NAME]
    call print_string
    lea rdi, [space_v]
    call print_string
    lea rdi, [COMPILER_VERSION]
    call print_string
    lea rdi, [newline]
    call print_string
    mov eax, 2
    jmp .arg_exit
    
.input_file:
    lea rsi, [input_file]
    call copy_string
    
.next_arg:
    inc r14
    jmp .arg_loop
    
.arg_done:
    xor eax, eax
    
.arg_exit:
    pop r14
    pop r13
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret
    
.missing_value:
    mov eax, 1
    jmp .arg_exit

; ============================================================================
; FILE COMPILATION
; ============================================================================
compile_file:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    sub rsp, 32
    
    mov r12, rdi                    ; Input file
    mov r13, rsi                    ; Output file
    
    ; Print status
    cmp byte [verbose_mode], 0
    je .skip_init_msg
    lea rdi, [msg_init]
    call print_string
.skip_init_msg:
    
    ; Read source file
    mov rdi, r12
    lea rsi, [source_buffer]
    mov rdx, SOURCE_BUFFER_SIZE
    call read_file
    test rax, rax
    js .read_error
    mov [source_length], rax
    
    ; Compile source
    lea rdi, [source_buffer]
    mov rsi, [source_length]
    call compile_source
    test rax, rax
    jnz .compile_fail
    
    ; Write output file
    mov rdi, r13
    lea rsi, [output_buffer]
    mov rdx, [output_pos]
    call write_file
    test rax, rax
    js .write_error
    
    xor eax, eax
    jmp .done
    
.read_error:
    mov qword [error_code], ERR_FILE_READ
    mov eax, ERR_FILE_READ
    jmp .done
    
.write_error:
    mov qword [error_code], ERR_FILE_WRITE
    mov eax, ERR_FILE_WRITE
    jmp .done
    
.compile_fail:
    ; Error code already set
    
.done:
    add rsp, 32
    pop r13
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; ============================================================================
; SOURCE COMPILATION PIPELINE
; ============================================================================
compile_source:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub rsp, 48
    
    mov r12, rdi                    ; Source buffer
    mov r13, rsi                    ; Source length
    
    ; === Stage 1: Lexical Analysis ===
    mov qword [compiler_state], STAGE_LEXICAL
    cmp byte [verbose_mode], 0
    je .skip_lex_msg
    lea rdi, [msg_lexing]
    call print_string
.skip_lex_msg:
    
    mov rdi, r12
    mov rsi, r13
    call tokenize
    test rax, rax
    jnz .lex_error
    
    ; === Stage 2: Syntactic Analysis (Parsing) ===
    mov qword [compiler_state], STAGE_SYNTACTIC
    cmp byte [verbose_mode], 0
    je .skip_parse_msg
    lea rdi, [msg_parsing]
    call print_string
.skip_parse_msg:
    
    call parse_program
    test rax, rax
    jnz .parse_error
    mov [ast_root], rax
    
    ; === Stage 3: Semantic Analysis ===
    mov qword [compiler_state], STAGE_SEMANTIC
    cmp byte [verbose_mode], 0
    je .skip_sem_msg
    lea rdi, [msg_semantic]
    call print_string
.skip_sem_msg:
    
    mov rdi, [ast_root]
    call semantic_analysis
    test rax, rax
    jnz .semantic_error
    
    ; === Stage 4: IR Generation ===
    mov qword [compiler_state], STAGE_IR_GEN
    cmp byte [verbose_mode], 0
    je .skip_ir_msg
    lea rdi, [msg_ir_gen]
    call print_string
.skip_ir_msg:
    
    mov rdi, [ast_root]
    call generate_ir
    test rax, rax
    jnz .ir_error
    
    ; === Stage 5: Optimization ===
    mov qword [compiler_state], STAGE_OPTIMIZATION
    movzx eax, byte [opt_level]
    test al, al
    jz .skip_opt
    
    cmp byte [verbose_mode], 0
    je .skip_opt_msg
    lea rdi, [msg_optimize]
    call print_string
.skip_opt_msg:
    
    lea rdi, [ir_buffer]
    mov rsi, [ir_instruction_count]
    movzx edx, byte [opt_level]
    call optimize_ir
    
.skip_opt:
    ; === Stage 6: Code Generation ===
    mov qword [compiler_state], STAGE_CODE_GEN
    cmp byte [verbose_mode], 0
    je .skip_gen_msg
    lea rdi, [msg_codegen]
    call print_string
.skip_gen_msg:
    
    movzx edi, byte [target_arch]
    call generate_code
    test rax, rax
    jnz .codegen_error
    
    ; === Stage 7: Assembly ===
    mov qword [compiler_state], STAGE_ASSEMBLY
    cmp byte [verbose_mode], 0
    je .skip_asm_msg
    lea rdi, [msg_assemble]
    call print_string
.skip_asm_msg:
    
    call assemble_code
    test rax, rax
    jnz .asm_error
    
    ; === Stage 8: Linking ===
    mov qword [compiler_state], STAGE_LINKING
    cmp byte [verbose_mode], 0
    je .skip_link_msg
    lea rdi, [msg_link]
    call print_string
.skip_link_msg:
    
    movzx edi, byte [output_format]
    call link_executable
    test rax, rax
    jnz .link_error
    
    ; Success
    mov qword [compiler_state], STAGE_COMPLETE
    xor eax, eax
    jmp .done
    
.lex_error:
    mov qword [error_code], ERR_LEXICAL
    mov eax, ERR_LEXICAL
    jmp .done
    
.parse_error:
    mov qword [error_code], ERR_SYNTAX
    mov eax, ERR_SYNTAX
    jmp .done
    
.semantic_error:
    mov qword [error_code], ERR_SEMANTIC
    jmp .done
    
.ir_error:
    mov qword [error_code], ERR_CODE_GEN
    mov eax, ERR_CODE_GEN
    jmp .done
    
.codegen_error:
    mov qword [error_code], ERR_CODE_GEN
    mov eax, ERR_CODE_GEN
    jmp .done
    
.asm_error:
    mov qword [error_code], ERR_CODE_GEN
    mov eax, ERR_CODE_GEN
    jmp .done
    
.link_error:
    mov qword [error_code], ERR_LINK
    mov eax, ERR_LINK
    
.done:
    add rsp, 48
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; ============================================================================
; LEXER - Tokenization
; ============================================================================
tokenize:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    push r15
    sub rsp, 32
    
    mov r12, rdi                    ; Source buffer
    mov r13, rsi                    ; Source length
    xor r14, r14                    ; Current position
    mov qword [current_line], 1
    mov qword [current_column], 1
    mov qword [token_count], 0
    
    lea r15, [token_buffer]         ; Token output buffer
    
.lex_loop:
    cmp r14, r13
    jge .lex_done
    
    ; Get current character
    movzx eax, byte [r12 + r14]
    
    ; Skip whitespace (but track newlines)
    cmp al, ' '
    je .skip_space
    cmp al, 9                       ; Tab
    je .skip_space
    cmp al, 13                      ; CR
    je .skip_space
    cmp al, 10                      ; LF
    je .handle_newline
    
    ; Check for comments
    cmp al, '/'
    jne .not_comment
    cmp r14, r13
    jge .not_comment
    movzx ebx, byte [r12 + r14 + 1]
    cmp bl, '/'
    je .line_comment
    cmp bl, '*'
    je .block_comment
    
.not_comment:
    ; Check for string literal
    cmp al, '"'
    je .string_literal
    cmp al, "'"
    je .char_literal
    
    ; Check for number
    cmp al, '0'
    jl .not_number
    cmp al, '9'
    jle .number_literal
    
.not_number:
    ; Check for identifier/keyword
    call is_alpha
    test al, al
    jnz .identifier
    
    ; Check for operators and punctuation
    movzx eax, byte [r12 + r14]
    call scan_operator
    test rax, rax
    jnz .operator_done
    
    ; Unknown character - error
    jmp .lex_error
    
.skip_space:
    inc r14
    inc qword [current_column]
    jmp .lex_loop
    
.handle_newline:
    inc r14
    inc qword [current_line]
    mov qword [current_column], 1
    jmp .lex_loop
    
.line_comment:
    add r14, 2
.line_comment_loop:
    cmp r14, r13
    jge .lex_loop
    movzx eax, byte [r12 + r14]
    inc r14
    cmp al, 10
    jne .line_comment_loop
    inc qword [current_line]
    mov qword [current_column], 1
    jmp .lex_loop
    
.block_comment:
    add r14, 2
.block_comment_loop:
    cmp r14, r13
    jge .lex_error                  ; Unterminated comment
    movzx eax, byte [r12 + r14]
    cmp al, 10
    jne .bc_not_newline
    inc qword [current_line]
    mov qword [current_column], 1
.bc_not_newline:
    cmp al, '*'
    jne .bc_next
    inc r14
    cmp r14, r13
    jge .lex_error
    movzx eax, byte [r12 + r14]
    cmp al, '/'
    je .bc_done
    jmp .block_comment_loop
.bc_next:
    inc r14
    jmp .block_comment_loop
.bc_done:
    inc r14
    jmp .lex_loop
    
.string_literal:
    ; Record token start
    mov rbx, r14
    inc r14                         ; Skip opening quote
.string_loop:
    cmp r14, r13
    jge .lex_error                  ; Unterminated string
    movzx eax, byte [r12 + r14]
    cmp al, '"'
    je .string_done
    cmp al, '\'
    jne .string_next
    ; Handle escape sequence
    inc r14
    cmp r14, r13
    jge .lex_error
.string_next:
    inc r14
    jmp .string_loop
.string_done:
    inc r14                         ; Skip closing quote
    ; Store token
    mov dword [r15], TOK_STRING_LITERAL
    mov [r15 + 4], rbx              ; Start position
    mov rax, r14
    sub rax, rbx
    mov [r15 + 12], rax             ; Length
    mov rax, [current_line]
    mov [r15 + 20], rax             ; Line
    add r15, 32
    inc qword [token_count]
    jmp .lex_loop
    
.char_literal:
    mov rbx, r14
    inc r14
    cmp r14, r13
    jge .lex_error
    movzx eax, byte [r12 + r14]
    cmp al, '\'
    je .lex_error                   ; Empty char literal
    inc r14
    cmp r14, r13
    jge .lex_error
    movzx eax, byte [r12 + r14]
    cmp al, "'"
    jne .lex_error                  ; Unterminated char literal
    inc r14
    mov dword [r15], TOK_CHAR_LITERAL
    mov [r15 + 4], rbx
    mov qword [r15 + 12], 3
    mov rax, [current_line]
    mov [r15 + 20], rax
    add r15, 32
    inc qword [token_count]
    jmp .lex_loop
    
.number_literal:
    mov rbx, r14
    movzx eax, byte [r12 + r14]
    
    ; Check for hex/binary/octal
    cmp al, '0'
    jne .decimal_number
    inc r14
    cmp r14, r13
    jge .single_zero
    movzx eax, byte [r12 + r14]
    cmp al, 'x'
    je .hex_number
    cmp al, 'X'
    je .hex_number
    cmp al, 'b'
    je .binary_number
    cmp al, 'B'
    je .binary_number
    cmp al, '0'
    jl .single_zero
    cmp al, '7'
    jle .octal_number
    jmp .decimal_continue
    
.hex_number:
    inc r14
.hex_loop:
    cmp r14, r13
    jge .number_done
    movzx eax, byte [r12 + r14]
    call is_hex_digit
    test al, al
    jz .number_done
    inc r14
    jmp .hex_loop
    
.binary_number:
    inc r14
.binary_loop:
    cmp r14, r13
    jge .number_done
    movzx eax, byte [r12 + r14]
    cmp al, '0'
    je .binary_next
    cmp al, '1'
    jne .number_done
.binary_next:
    inc r14
    jmp .binary_loop
    
.octal_number:
.octal_loop:
    cmp r14, r13
    jge .number_done
    movzx eax, byte [r12 + r14]
    cmp al, '0'
    jl .number_done
    cmp al, '7'
    jg .number_done
    inc r14
    jmp .octal_loop
    
.single_zero:
    mov dword [r15], TOK_INT_LITERAL
    mov [r15 + 4], rbx
    mov qword [r15 + 12], 1
    mov rax, [current_line]
    mov [r15 + 20], rax
    add r15, 32
    inc qword [token_count]
    jmp .lex_loop
    
.decimal_number:
.decimal_loop:
    cmp r14, r13
    jge .number_done
    movzx eax, byte [r12 + r14]
    cmp al, '0'
    jl .check_float
    cmp al, '9'
    jg .check_float
    inc r14
    jmp .decimal_loop
    
.decimal_continue:
    dec r14
    jmp .decimal_loop
    
.check_float:
    cmp al, '.'
    jne .number_done
    inc r14
.float_loop:
    cmp r14, r13
    jge .float_done
    movzx eax, byte [r12 + r14]
    cmp al, '0'
    jl .check_exponent
    cmp al, '9'
    jg .check_exponent
    inc r14
    jmp .float_loop
    
.check_exponent:
    cmp al, 'e'
    je .parse_exponent
    cmp al, 'E'
    jne .float_done
.parse_exponent:
    inc r14
    cmp r14, r13
    jge .float_done
    movzx eax, byte [r12 + r14]
    cmp al, '+'
    je .exp_sign
    cmp al, '-'
    jne .exp_digits
.exp_sign:
    inc r14
.exp_digits:
    cmp r14, r13
    jge .float_done
    movzx eax, byte [r12 + r14]
    cmp al, '0'
    jl .float_done
    cmp al, '9'
    jg .float_done
    inc r14
    jmp .exp_digits
    
.float_done:
    mov dword [r15], TOK_FLOAT_LITERAL
    jmp .store_number
    
.number_done:
    mov dword [r15], TOK_INT_LITERAL
.store_number:
    mov [r15 + 4], rbx
    mov rax, r14
    sub rax, rbx
    mov [r15 + 12], rax
    mov rax, [current_line]
    mov [r15 + 20], rax
    add r15, 32
    inc qword [token_count]
    jmp .lex_loop
    
.identifier:
    mov rbx, r14
.ident_loop:
    cmp r14, r13
    jge .ident_done
    movzx eax, byte [r12 + r14]
    call is_alnum
    test al, al
    jz .ident_done
    inc r14
    jmp .ident_loop
    
.ident_done:
    ; Check if it's a keyword
    lea rdi, [r12 + rbx]
    mov rsi, r14
    sub rsi, rbx
    call lookup_keyword
    test eax, eax
    jnz .store_keyword
    mov eax, TOK_IDENTIFIER
.store_keyword:
    mov [r15], eax
    mov [r15 + 4], rbx
    mov rax, r14
    sub rax, rbx
    mov [r15 + 12], rax
    mov rax, [current_line]
    mov [r15 + 20], rax
    add r15, 32
    inc qword [token_count]
    jmp .lex_loop
    
.operator_done:
    ; Token already stored by scan_operator
    jmp .lex_loop
    
.lex_done:
    ; Add EOF token
    mov dword [r15], TOK_EOF
    mov [r15 + 4], r14
    mov qword [r15 + 12], 0
    mov rax, [current_line]
    mov [r15 + 20], rax
    inc qword [token_count]
    
    xor eax, eax
    jmp .lex_exit
    
.lex_error:
    mov rax, [current_line]
    mov [error_line], rax
    mov rax, [current_column]
    mov [error_column], rax
    mov eax, ERR_LEXICAL
    
.lex_exit:
    add rsp, 32
    pop r15
    pop r14
    pop r13
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; ============================================================================
; PARSER - Recursive Descent
; ============================================================================
parse_program:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    sub rsp, 48
    
    ; Reset token position
    mov qword [token_pos], 0
    
    ; Create program root node
    mov edi, AST_PROGRAM
    call create_ast_node
    test rax, rax
    jz .parse_error
    mov r12, rax                    ; Program node
    
.parse_loop:
    ; Get current token
    call current_token
    mov r13, rax
    
    ; Check for EOF
    mov eax, [r13]
    cmp eax, TOK_EOF
    je .parse_done
    
    ; Parse top-level declaration
    call parse_declaration
    test rax, rax
    jz .parse_error
    
    ; Add to program children
    mov rdi, r12
    mov rsi, rax
    call add_child_node
    
    jmp .parse_loop
    
.parse_done:
    mov rax, r12
    jmp .parse_exit
    
.parse_error:
    xor eax, eax
    
.parse_exit:
    add rsp, 48
    pop r14
    pop r13
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; Parse a declaration (function, variable, struct, etc.)
parse_declaration:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    sub rsp, 32
    
    call current_token
    mov r12, rax
    mov eax, [r12]
    
    ; Check declaration type
    cmp eax, TOK_KW_FN
    je .parse_function
    cmp eax, TOK_KW_FUNCTION
    je .parse_function
    cmp eax, TOK_KW_LET
    je .parse_variable
    cmp eax, TOK_KW_VAR
    je .parse_variable
    cmp eax, TOK_KW_CONST
    je .parse_const
    cmp eax, TOK_KW_STRUCT
    je .parse_struct
    cmp eax, TOK_KW_ENUM
    je .parse_enum
    cmp eax, TOK_KW_IMPORT
    je .parse_import
    cmp eax, TOK_KW_EXTERN
    je .parse_extern
    
    ; Default: try to parse as statement
    call parse_statement
    jmp .parse_exit
    
.parse_function:
    call parse_function_decl
    jmp .parse_exit
    
.parse_variable:
    call parse_variable_decl
    jmp .parse_exit
    
.parse_const:
    call parse_const_decl
    jmp .parse_exit
    
.parse_struct:
    call parse_struct_decl
    jmp .parse_exit
    
.parse_enum:
    call parse_enum_decl
    jmp .parse_exit
    
.parse_import:
    call parse_import_decl
    jmp .parse_exit
    
.parse_extern:
    call parse_extern_decl
    jmp .parse_exit
    
.parse_exit:
    add rsp, 32
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; Parse function declaration
parse_function_decl:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    sub rsp, 48
    
    ; Skip 'fn' keyword
    call advance_token
    
    ; Create function node
    mov edi, AST_FUNCTION
    call create_ast_node
    test rax, rax
    jz .func_error
    mov r12, rax                    ; Function node
    
    ; Expect identifier (function name)
    call current_token
    mov r13, rax
    mov eax, [r13]
    cmp eax, TOK_IDENTIFIER
    jne .func_error
    
    ; Store function name
    mov rdi, r12
    lea rsi, [r13 + 4]              ; Token data
    call set_node_name
    call advance_token
    
    ; Expect '('
    call expect_token
    mov edi, TOK_LPAREN
    call expect_token
    test eax, eax
    jz .func_error
    
    ; Parse parameters
    call parse_parameters
    mov rdi, r12
    mov rsi, rax
    call set_node_params
    
    ; Expect ')'
    mov edi, TOK_RPAREN
    call expect_token
    test eax, eax
    jz .func_error
    
    ; Check for return type
    call current_token
    mov eax, [rax]
    cmp eax, TOK_ARROW
    jne .no_return_type
    call advance_token
    call parse_type
    mov rdi, r12
    mov rsi, rax
    call set_node_type
    
.no_return_type:
    ; Parse function body
    call parse_block
    test rax, rax
    jz .func_error
    mov rdi, r12
    mov rsi, rax
    call add_child_node
    
    mov rax, r12
    jmp .func_exit
    
.func_error:
    xor eax, eax
    
.func_exit:
    add rsp, 48
    pop r14
    pop r13
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; Parse code block
parse_block:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    sub rsp, 32
    
    ; Expect '{'
    mov edi, TOK_LBRACE
    call expect_token
    test eax, eax
    jz .block_error
    
    ; Create block node
    mov edi, AST_BLOCK
    call create_ast_node
    test rax, rax
    jz .block_error
    mov r12, rax
    
    ; Enter new scope
    call push_scope
    
.block_loop:
    call current_token
    mov r13, rax
    mov eax, [r13]
    
    ; Check for '}'
    cmp eax, TOK_RBRACE
    je .block_done
    
    ; Check for EOF
    cmp eax, TOK_EOF
    je .block_error
    
    ; Parse statement
    call parse_statement
    test rax, rax
    jz .block_error
    
    ; Add to block
    mov rdi, r12
    mov rsi, rax
    call add_child_node
    
    jmp .block_loop
    
.block_done:
    ; Skip '}'
    call advance_token
    
    ; Exit scope
    call pop_scope
    
    mov rax, r12
    jmp .block_exit
    
.block_error:
    xor eax, eax
    
.block_exit:
    add rsp, 32
    pop r13
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; Parse statement
parse_statement:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    sub rsp, 32
    
    call current_token
    mov r12, rax
    mov eax, [r12]
    
    cmp eax, TOK_KW_IF
    je .parse_if
    cmp eax, TOK_KW_WHILE
    je .parse_while
    cmp eax, TOK_KW_FOR
    je .parse_for
    cmp eax, TOK_KW_RETURN
    je .parse_return
    cmp eax, TOK_KW_BREAK
    je .parse_break
    cmp eax, TOK_KW_CONTINUE
    je .parse_continue
    cmp eax, TOK_KW_LET
    je .parse_local_var
    cmp eax, TOK_KW_VAR
    je .parse_local_var
    cmp eax, TOK_LBRACE
    je .parse_nested_block
    
    ; Default: expression statement
    call parse_expression
    test rax, rax
    jz .stmt_error
    mov rbx, rax
    
    ; Expect semicolon
    mov edi, TOK_SEMICOLON
    call expect_token
    
    ; Wrap in expression statement node
    mov edi, AST_EXPR_STMT
    call create_ast_node
    mov rdi, rax
    mov rsi, rbx
    call add_child_node
    jmp .stmt_exit
    
.parse_if:
    call parse_if_statement
    jmp .stmt_exit
    
.parse_while:
    call parse_while_statement
    jmp .stmt_exit
    
.parse_for:
    call parse_for_statement
    jmp .stmt_exit
    
.parse_return:
    call parse_return_statement
    jmp .stmt_exit
    
.parse_break:
    call advance_token
    mov edi, AST_BREAK
    call create_ast_node
    mov edi, TOK_SEMICOLON
    call expect_token
    jmp .stmt_exit
    
.parse_continue:
    call advance_token
    mov edi, AST_CONTINUE
    call create_ast_node
    mov edi, TOK_SEMICOLON
    call expect_token
    jmp .stmt_exit
    
.parse_local_var:
    call parse_variable_decl
    jmp .stmt_exit
    
.parse_nested_block:
    call parse_block
    jmp .stmt_exit
    
.stmt_error:
    xor eax, eax
    
.stmt_exit:
    add rsp, 32
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; ============================================================================
; SEMANTIC ANALYSIS
; ============================================================================
semantic_analysis:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    sub rsp, 32
    
    mov r12, rdi                    ; AST root
    
    ; Initialize symbol table
    call init_symbol_table
    
    ; First pass: collect declarations
    mov rdi, r12
    call collect_declarations
    test eax, eax
    jnz .sem_error
    
    ; Second pass: resolve references and check types
    mov rdi, r12
    call resolve_and_typecheck
    test eax, eax
    jnz .sem_error
    
    ; Third pass: check for main function
    lea rdi, [main_name]
    call lookup_symbol
    test rax, rax
    jz .no_main_warning
    
    xor eax, eax
    jmp .sem_exit
    
.no_main_warning:
    ; Just a warning, not an error
    xor eax, eax
    jmp .sem_exit
    
.sem_error:
    mov eax, ERR_SEMANTIC
    
.sem_exit:
    add rsp, 32
    pop r13
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; ============================================================================
; IR GENERATION
; ============================================================================
generate_ir:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    sub rsp, 48
    
    mov r12, rdi                    ; AST root
    
    ; Reset IR state
    mov qword [ir_pos], 0
    mov qword [ir_instruction_count], 0
    mov qword [temp_var_counter], 0
    mov qword [label_counter], 0
    
    ; Generate IR for each top-level declaration
    mov rdi, r12
    call get_first_child
    
.ir_loop:
    test rax, rax
    jz .ir_done
    mov r13, rax
    
    ; Generate IR for this node
    mov rdi, r13
    call generate_ir_node
    test eax, eax
    jnz .ir_error
    
    ; Get next sibling
    mov rdi, r13
    call get_next_sibling
    jmp .ir_loop
    
.ir_done:
    xor eax, eax
    jmp .ir_exit
    
.ir_error:
    ; Error already set
    
.ir_exit:
    add rsp, 48
    pop r13
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; ============================================================================
; CODE GENERATION
; ============================================================================
generate_code:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    sub rsp, 48
    
    mov r12d, edi                   ; Target architecture
    
    ; Reset output
    mov qword [output_pos], 0
    
    ; Select code generator based on target
    cmp r12d, TARGET_X86_64
    je .gen_x86_64
    cmp r12d, TARGET_X86_32
    je .gen_x86_32
    cmp r12d, TARGET_ARM64
    je .gen_arm64
    jmp .gen_error
    
.gen_x86_64:
    call generate_x86_64
    jmp .gen_check
    
.gen_x86_32:
    call generate_x86_32
    jmp .gen_check
    
.gen_arm64:
    call generate_arm64
    jmp .gen_check
    
.gen_check:
    test eax, eax
    jnz .gen_error
    
    xor eax, eax
    jmp .gen_exit
    
.gen_error:
    mov eax, ERR_CODE_GEN
    
.gen_exit:
    add rsp, 48
    pop r13
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; Generate x86-64 code
generate_x86_64:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    sub rsp, 32
    
    lea r12, [output_buffer]
    
    ; Generate code section header
    lea rdi, [r12]
    add rdi, [output_pos]
    lea rsi, [x86_64_prologue]
    call copy_string
    call update_output_pos
    
    ; Generate code from IR
    lea rdi, [ir_buffer]
    mov rsi, [ir_instruction_count]
    call emit_x86_64_instructions
    
    ; Generate data section
    lea rdi, [r12]
    add rdi, [output_pos]
    lea rsi, [x86_64_data_section]
    call copy_string
    call update_output_pos
    
    xor eax, eax
    
    add rsp, 32
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; ============================================================================
; ASSEMBLER
; ============================================================================
assemble_code:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    sub rsp, 32
    
    ; Convert assembly text to machine code
    lea rdi, [output_buffer]
    mov rsi, [output_pos]
    call assemble_to_machine_code
    
    add rsp, 32
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; ============================================================================
; LINKER
; ============================================================================
link_executable:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    sub rsp, 48
    
    mov r12d, edi                   ; Output format
    
    ; Select linker based on output format
    cmp r12d, OUTPUT_EXE
    je .link_exe
    cmp r12d, OUTPUT_DLL
    je .link_dll
    cmp r12d, OUTPUT_OBJ
    je .link_obj
    jmp .link_error
    
.link_exe:
    ; Generate PE or ELF executable
%ifdef WINDOWS
    call generate_pe_executable
%else
    call generate_elf_executable
%endif
    jmp .link_check
    
.link_dll:
    call generate_shared_library
    jmp .link_check
    
.link_obj:
    ; Object file is already generated
    xor eax, eax
    jmp .link_exit
    
.link_check:
    test eax, eax
    jnz .link_error
    xor eax, eax
    jmp .link_exit
    
.link_error:
    mov eax, ERR_LINK
    
.link_exit:
    add rsp, 48
    pop r13
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; Generate PE executable (Windows)
generate_pe_executable:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    sub rsp, 32
    
    lea r12, [output_buffer]
    mov qword [output_pos], 0
    
    ; DOS Header
    mov word [r12], 0x5A4D          ; 'MZ'
    mov word [r12 + 0x3C], 0x80     ; PE header offset
    
    ; PE Signature
    lea rdi, [r12 + 0x80]
    mov dword [rdi], 0x00004550     ; 'PE\0\0'
    
    ; COFF Header
    add rdi, 4
    mov word [rdi], 0x8664          ; Machine: AMD64
    mov word [rdi + 2], 1           ; NumberOfSections
    mov dword [rdi + 4], 0          ; TimeDateStamp
    mov dword [rdi + 8], 0          ; PointerToSymbolTable
    mov dword [rdi + 12], 0         ; NumberOfSymbols
    mov word [rdi + 16], 240        ; SizeOfOptionalHeader
    mov word [rdi + 18], 0x22       ; Characteristics
    
    ; Optional Header (PE32+)
    add rdi, 20
    mov word [rdi], 0x20B           ; Magic: PE32+
    mov byte [rdi + 2], 14          ; MajorLinkerVersion
    mov byte [rdi + 3], 0           ; MinorLinkerVersion
    ; ... (continue with full PE header)
    
    xor eax, eax
    
    add rsp, 32
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; Generate ELF executable (Linux)
generate_elf_executable:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    sub rsp, 32
    
    lea r12, [output_buffer]
    mov qword [output_pos], 0
    
    ; ELF Header
    mov dword [r12], 0x464C457F     ; ELF magic
    mov byte [r12 + 4], 2           ; 64-bit
    mov byte [r12 + 5], 1           ; Little endian
    mov byte [r12 + 6], 1           ; ELF version
    mov byte [r12 + 7], 0           ; OS/ABI
    mov qword [r12 + 8], 0          ; Padding
    mov word [r12 + 16], 2          ; Type: executable
    mov word [r12 + 18], 0x3E       ; Machine: x86-64
    mov dword [r12 + 20], 1         ; Version
    mov qword [r12 + 24], 0x400000  ; Entry point
    mov qword [r12 + 32], 64        ; Program header offset
    mov qword [r12 + 40], 0         ; Section header offset
    mov dword [r12 + 48], 0         ; Flags
    mov word [r12 + 52], 64         ; ELF header size
    mov word [r12 + 54], 56         ; Program header entry size
    mov word [r12 + 56], 1          ; Number of program headers
    mov word [r12 + 58], 64         ; Section header entry size
    mov word [r12 + 60], 0          ; Number of section headers
    mov word [r12 + 62], 0          ; Section name string table index
    
    ; Program Header
    lea rdi, [r12 + 64]
    mov dword [rdi], 1              ; Type: PT_LOAD
    mov dword [rdi + 4], 5          ; Flags: R-X
    mov qword [rdi + 8], 0          ; Offset
    mov qword [rdi + 16], 0x400000  ; Virtual address
    mov qword [rdi + 24], 0x400000  ; Physical address
    ; ... (continue with full ELF structure)
    
    xor eax, eax
    
    add rsp, 32
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; ============================================================================
; UTILITY FUNCTIONS
; ============================================================================

; Print string to stdout
print_string:
    push rbp
    mov rbp, rsp
    push rbx
    
    mov rbx, rdi
    
    ; Calculate string length
    xor ecx, ecx
.strlen_loop:
    cmp byte [rbx + rcx], 0
    je .strlen_done
    inc ecx
    jmp .strlen_loop
.strlen_done:
    
%ifdef LINUX
    mov rax, 1                      ; sys_write
    mov rdi, 1                      ; stdout
    mov rsi, rbx
    mov rdx, rcx
    syscall
%else
    ; Windows: call WriteConsole or use printf
    mov rdi, rbx
    xor eax, eax
    call printf
%endif
    
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; Copy string
copy_string:
    push rbp
    mov rbp, rsp
    
.copy_loop:
    mov al, [rdi]
    mov [rsi], al
    test al, al
    jz .copy_done
    inc rdi
    inc rsi
    jmp .copy_loop
.copy_done:
    
    mov rsp, rbp
    pop rbp
    ret

; Compare strings
string_compare:
    push rbp
    mov rbp, rsp
    
.cmp_loop:
    mov al, [rdi]
    mov bl, [rsi]
    cmp al, bl
    jne .cmp_not_equal
    test al, al
    jz .cmp_equal
    inc rdi
    inc rsi
    jmp .cmp_loop
    
.cmp_equal:
    xor eax, eax
    jmp .cmp_exit
    
.cmp_not_equal:
    mov eax, 1
    
.cmp_exit:
    mov rsp, rbp
    pop rbp
    ret

; Check if character is alphabetic
is_alpha:
    cmp al, 'A'
    jl .not_alpha
    cmp al, 'Z'
    jle .is_alpha_yes
    cmp al, 'a'
    jl .check_underscore
    cmp al, 'z'
    jle .is_alpha_yes
.check_underscore:
    cmp al, '_'
    je .is_alpha_yes
.not_alpha:
    xor eax, eax
    ret
.is_alpha_yes:
    mov eax, 1
    ret

; Check if character is alphanumeric
is_alnum:
    push rbx
    mov bl, al
    call is_alpha
    test al, al
    jnz .is_alnum_yes
    mov al, bl
    cmp al, '0'
    jl .is_alnum_no
    cmp al, '9'
    jle .is_alnum_yes
.is_alnum_no:
    xor eax, eax
    pop rbx
    ret
.is_alnum_yes:
    mov eax, 1
    pop rbx
    ret

; Check if character is hex digit
is_hex_digit:
    cmp al, '0'
    jl .not_hex
    cmp al, '9'
    jle .is_hex_yes
    cmp al, 'A'
    jl .not_hex
    cmp al, 'F'
    jle .is_hex_yes
    cmp al, 'a'
    jl .not_hex
    cmp al, 'f'
    jle .is_hex_yes
.not_hex:
    xor eax, eax
    ret
.is_hex_yes:
    mov eax, 1
    ret

; Read file into buffer
read_file:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    sub rsp, 32
    
    mov r12, rdi                    ; Filename
    mov r13, rsi                    ; Buffer
    mov rbx, rdx                    ; Buffer size
    
%ifdef LINUX
    ; Open file
    mov rax, 2                      ; sys_open
    mov rdi, r12
    xor esi, esi                    ; O_RDONLY
    syscall
    test rax, rax
    js .read_error
    mov r12, rax                    ; File descriptor
    
    ; Read file
    mov rax, 0                      ; sys_read
    mov rdi, r12
    mov rsi, r13
    mov rdx, rbx
    syscall
    mov rbx, rax                    ; Bytes read
    
    ; Close file
    mov rax, 3                      ; sys_close
    mov rdi, r12
    syscall
    
    mov rax, rbx
%else
    ; Windows: use CreateFile, ReadFile, CloseHandle
    lea rdi, [r12]
    lea rsi, [rb_mode]
    call fopen
    test rax, rax
    jz .read_error
    mov r12, rax
    
    mov rdi, r13
    mov rsi, 1
    mov rdx, rbx
    mov rcx, r12
    call fread
    mov rbx, rax
    
    mov rdi, r12
    call fclose
    
    mov rax, rbx
%endif
    jmp .read_exit
    
.read_error:
    mov rax, -1
    
.read_exit:
    add rsp, 32
    pop r13
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; Write buffer to file
write_file:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    sub rsp, 32
    
    mov r12, rdi                    ; Filename
    mov r13, rsi                    ; Buffer
    mov rbx, rdx                    ; Size
    
%ifdef LINUX
    ; Open file for writing
    mov rax, 2                      ; sys_open
    mov rdi, r12
    mov esi, 0x241                  ; O_WRONLY | O_CREAT | O_TRUNC
    mov edx, 0755                   ; Permissions
    syscall
    test rax, rax
    js .write_error
    mov r12, rax
    
    ; Write file
    mov rax, 1                      ; sys_write
    mov rdi, r12
    mov rsi, r13
    mov rdx, rbx
    syscall
    
    ; Close file
    push rax
    mov rax, 3                      ; sys_close
    mov rdi, r12
    syscall
    pop rax
%else
    ; Windows
    lea rdi, [r12]
    lea rsi, [wb_mode]
    call fopen
    test rax, rax
    jz .write_error
    mov r12, rax
    
    mov rdi, r13
    mov rsi, 1
    mov rdx, rbx
    mov rcx, r12
    call fwrite
    
    mov rdi, r12
    call fclose
    
    mov rax, rbx
%endif
    jmp .write_exit
    
.write_error:
    mov rax, -1
    
.write_exit:
    add rsp, 32
    pop r13
    pop r12
    pop rbx
    mov rsp, rbp
    pop rbp
    ret

; Cleanup compiler resources
cleanup_compiler:
    push rbp
    mov rbp, rsp
    
    ; Reset all state
    mov qword [compiler_state], STAGE_INIT
    
    mov rsp, rbp
    pop rbp
    ret

; ============================================================================
; ADDITIONAL DATA
; ============================================================================
section .data
    align 8
    
    default_output      db "a.out", 0
    rb_mode             db "rb", 0
    wb_mode             db "wb", 0
    opt_version         db "version", 0
    space_v             db " v", 0
    newline             db 10, 0
    main_name           db "main", 0
    err_init_failed     db "Failed to initialize compiler", 10, 0
    
    x86_64_prologue     db "section .text", 10, "global _start", 10, "_start:", 10, 0
    x86_64_data_section db 10, "section .data", 10, 0

; ============================================================================
; HEAP MEMORY ALLOCATION
; ============================================================================
section .bss
    align 16
    heap_memory         resb HEAP_SIZE

; ============================================================================
; PRODUCTION IMPLEMENTATIONS (to be filled in)
; ============================================================================
section .text

; These are production implementations that need full code:

scan_operator:
    ; Scan and return operator token
    xor eax, eax
    ret

lookup_keyword:
    ; Look up keyword in table
    xor eax, eax
    ret

current_token:
    ; Return pointer to current token
    lea rax, [token_buffer]
    mov rcx, [token_pos]
    shl rcx, 5
    add rax, rcx
    ret

advance_token:
    ; Move to next token
    inc qword [token_pos]
    ret

expect_token:
    ; Expect specific token type
    call current_token
    mov eax, [rax]
    cmp eax, edi
    jne .expect_fail
    call advance_token
    mov eax, 1
    ret
.expect_fail:
    xor eax, eax
    ret

create_ast_node:
    ; Create new AST node
    lea rax, [ast_pool]
    mov rcx, [ast_pool_pos]
    add rax, rcx
    mov [rax], edi
    add qword [ast_pool_pos], 64
    inc qword [ast_node_count]
    ret

