; GenerateGhostKeyPair(void* priv_out, void* pub_out)
; RCX = priv_out, RDX = pub_out
GenerateGhostKeyPair PROC
    push rsi
    push rdi
    
    mov rsi, rcx
    mov rdi, rdx
    
    ; 1. Generate 32 bytes of random
    mov rcx, 4
_rand_loop:
    rdrand rax
    jnc _rand_loop
    mov [rsi], rax
