;------------------------------------------------------------------------------
; vscode.workspace.findFiles
;------------------------------------------------------------------------------
API_FindFiles proc frame uses rbx rsi rdi r12 r13 r14,
    includePattern:qword,
    excludePattern:qword,
    maxResults:dword,
    token:qword
    
    mov r12, includePattern
    mov r13, excludePattern
    mov r14d, maxResults
    
    ; Build search request for main process
    sub rsp, 256
    
    mov rdi, rsp
    mov dword ptr [rdi], '{'
    inc rdi
    
    ; include pattern
    mov dword ptr [rdi], '"inc'
    add rdi, 4
    mov dword ptr [rdi], 'lude'
    add rdi, 4
    mov byte ptr [rdi], '"'
    inc rdi
    mov byte ptr [rdi], ':'
    inc rdi
    mov byte ptr [rdi], '"'
    inc rdi
    
    mov rcx, rdi
    mov rdx, r12
    call strcpy
    add rdi, rax
    
    mov byte ptr [rdi], '"'
    inc rdi
    
    ; exclude pattern (if provided)
    test r13, r13
    jz @F
    
    mov byte ptr [rdi], ','
    inc rdi
    mov dword ptr [rdi], '"exc'
    add rdi, 4
    mov dword ptr [rdi], 'lude'
    add rdi, 4
    mov byte ptr [rdi], '"'
    inc rdi
    mov byte ptr [rdi], ':'
    inc rdi
    mov byte ptr [rdi], '"'
    inc rdi
    
    mov rcx, rdi
    mov rdx, r13
    call strcpy
    add rdi, rax
    
    mov byte ptr [rdi], '"'
    inc rdi

@@:
    ; maxResults
    mov byte ptr [rdi], ','
    inc rdi
    mov dword ptr [rdi], '"max'
    add rdi, 4
    mov byte ptr [rdi], '"'
    inc rdi
    mov byte ptr [rdi], ':'
    inc rdi
    
    mov ecx, r14d
    mov rdx, rdi
    call itoa
    add rdi, rax
    
    mov byte ptr [rdi], '}'
    inc rdi
    mov byte ptr [rdi], 0
    
    ; Send request via bridge
    mov ecx, MSG_FIND_FILES
    mov rdx, rsp
    mov r8, rdi
    sub r8, rsp
    call ExtensionHostBridge_SendRequest
    
    add rsp, 256
    
    ; Return Thenable<Uri[]>
    ret
API_FindFiles endp

;------------------------------------------------------------------------------
; vscode.window.showInformationMessage
;------------------------------------------------------------------------------
API_ShowInformationMessage proc frame uses rbx rsi rdi r12 r13 r14,
    message:qword,
    options:qword,
    items:qword,
    itemCount:dword
    
    mov r12, message
    mov r13, options
    mov r14, items
    mov r15d, itemCount
    
    ; Build message request
    sub rsp, 512
    
    mov rdi, rsp
    mov dword ptr [rdi], '{'
    inc rdi
    mov dword ptr [rdi], '"typ'
    add rdi, 4
    mov dword ptr [rdi], 'e":'
    add rdi, 4
    mov dword ptr [rdi], '"inf'
    add rdi, 4
    mov byte ptr [rdi], 'o'
    inc rdi
    mov byte ptr [rdi], '"'
    inc rdi
    mov byte ptr [rdi], ','
    inc rdi
    mov dword ptr [rdi], '"mes'
    add rdi, 4
    mov dword ptr [rdi], 'sag'
    add rdi, 4
    mov byte ptr [rdi], 'e'
    inc rdi
    mov byte ptr [rdi], '"'
    inc rdi
    mov byte ptr [rdi], ':'
    inc rdi
    mov byte ptr [rdi], '"'
    inc rdi
    
    ; Escape message JSON
    mov rcx, rdi
    mov rdx, r12
    call Json_EscapeString
    add rdi, rax
    
    mov byte ptr [rdi], '"'
    inc rdi
    
    ; Add items if provided
    test r15d, r15d
    jz @F
    
    mov byte ptr [rdi], ','
    inc rdi
    mov dword ptr [rdi], '"ite'
    add rdi, 4
    mov dword ptr [rdi], 'ms":'
    add rdi, 5
    mov byte ptr [rdi], '['
    inc rdi
    
    ; TODO: Add items array
    
    mov byte ptr [rdi], ']'
    inc rdi

@@:
    mov byte ptr [rdi], '}'
    inc rdi
    mov byte ptr [rdi], 0
    
    ; Send to main process
    mov ecx, MSG_SHOW_MESSAGE
    mov rdx, rsp
    call ExtensionHostBridge_SendRequest
    
    add rsp, 512
    
    ret
API_ShowInformationMessage endp

