; ═════════════════════════════════════════════════════════════════════════════
; HELPER FUNCTIONS
; ═════════════════════════════════════════════════════════════════════════════

; ----------------------------------------------------------------------------
; __strcpy_w - Copy wide string (internal helper)
; rcx = destination, rdx = source
; Returns: rax = destination
; ----------------------------------------------------------------------------
__strcpy_w PROC FRAME
    push rdi
    .pushreg rdi
    push rsi
    .pushreg rsi
    push rbx
    .pushreg rbx
    .endprolog
    
    mov rdi, rcx        ; Destination
    mov rsi, rdx        ; Source
    mov rbx, rcx        ; Save original destination
    xor rax, rax        ; Clear for SCASW
    
@@copy_loop:
    lodsw               ; Load word from [rsi] into ax, rsi += 2
    stosw               ; Store ax to [rdi], rdi += 2
    test ax, ax         ; Check for null terminator
    jnz @@copy_loop
    
    mov rax, rbx        ; Return destination
    
    pop rbx
    pop rsi
    pop rdi
    ret
__strcpy_w ENDP

; ----------------------------------------------------------------------------
; __wcslen - Calculate wide string length
; rcx = string
; Returns: rax = length (not including null)
; ----------------------------------------------------------------------------
__wcslen PROC FRAME
    push rdi
    .pushreg rdi
    .endprolog
    
    mov rdi, rcx
    xor rcx, rcx        ; Max count (none, use null term)
    xor rax, rax        ; Search for null
    not rcx             ; Max count = -1
    cld
    repne scasw         ; Scan while not equal to ax (0)
    not rcx             ; Invert to get count
    dec rcx             ; Exclude null terminator
    mov rax, rcx        ; Return length
    
    pop rdi
    ret
__wcslen ENDP

; ----------------------------------------------------------------------------
; __memcpy - Copy memory block
; rcx = dest, rdx = src, r8 = count
; Returns: rax = dest
; ----------------------------------------------------------------------------
__memcpy PROC FRAME
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push rbx
    .pushreg rbx
    .endprolog
    
    mov rbx, rcx        ; Save original dest
    mov rdi, rcx
    mov rsi, rdx
    mov rcx, r8
    
    ; Optimize: use rep movsb for small blocks, SIMD for large
    cmp rcx, 256
    ja @@large_copy
    
@@small_copy:
    rep movsb
    jmp @@done
    
@@large_copy:
    ; Align destination to 16 bytes
    mov rax, rdi
    and rax, 15
    jz @@aligned
    mov r9, 16
    sub r9, rax
    sub rcx, r9
    xchg rcx, r9
    rep movsb
    mov rcx, r9
    
@@aligned:
    ; Copy 128 bytes at a time using XMM registers
    mov r9, rcx
    shr r9, 7           ; Divide by 128
    jz @@trailing
    
@@xmm_loop:
    movdqu xmm0, [rsi]
    movdqu xmm1, [rsi+16]
    movdqu xmm2, [rsi+32]
    movdqu xmm3, [rsi+48]
    movdqu xmm4, [rsi+64]
    movdqu xmm5, [rsi+80]
    movdqu xmm6, [rsi+96]
    movdqu xmm7, [rsi+112]
    
    movdqu [rdi], xmm0
    movdqu [rdi+16], xmm1
    movdqu [rdi+32], xmm2
    movdqu [rdi+48], xmm3
    movdqu [rdi+64], xmm4
    movdqu [rdi+80], xmm5
    movdqu [rdi+96], xmm6
    movdqu [rdi+112], xmm7
    
    add rsi, 128
    add rdi, 128
    dec r9
    jnz @@xmm_loop
    
@@trailing:
    ; Handle remaining bytes
    and rcx, 127
    rep movsb
    
@@done:
    mov rax, rbx        ; Return original dest
    pop rbx
    pop rdi
    pop rsi
    ret
__memcpy ENDP

; ----------------------------------------------------------------------------
; __memset - Set memory to value
; rcx = dest, rdx = value, r8 = count
; Returns: rax = dest
; ----------------------------------------------------------------------------
__memset PROC FRAME
    push rdi
    .pushreg rdi
    push rbx
    .pushreg rbx
    .endprolog
    
    mov rbx, rcx        ; Save original dest
    mov rdi, rcx
    mov rax, rdx
    mov rcx, r8
    
    rep stosb
    
    mov rax, rbx        ; Return original dest
    pop rbx
    pop rdi
    ret
__memset ENDP

; ----------------------------------------------------------------------------
; __utf8_to_utf16 - Convert UTF-8 string to UTF-16
; rcx = dest buffer (wide), rdx = source (UTF-8), r8 = dest size in wchar_t
; Returns: rax = number of chars written (excluding null), or -1 on error
; ----------------------------------------------------------------------------
__utf8_to_utf16 PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rdi, rcx        ; Destination
    mov rsi, rdx        ; Source
    mov rbx, r8         ; Dest size
    
    ; Call MultiByteToWideChar
    ; int MultiByteToWideChar(UINT CodePage, DWORD dwFlags, LPCCH lpMultiByteStr, 
    ;                         int cbMultiByte, LPWSTR lpWideCharStr, int cchWideChar)
    mov ecx, 65001      ; CP_UTF8
    xor edx, edx        ; dwFlags = 0
    mov r8, rsi         ; Source string
    mov r9d, -1         ; Source length (-1 = null terminated)
    mov [rsp+32], rdi   ; lpWideCharStr
    mov [rsp+40], ebx   ; cchWideChar
    
    call MultiByteToWideChar
    
    add rsp, 48
    pop rdi
    pop rsi
    pop rbx
    ret
__utf8_to_utf16 ENDP

; ----------------------------------------------------------------------------
; __utf16_to_utf8 - Convert UTF-16 string to UTF-8
; rcx = dest buffer, rdx = source (wide), r8 = dest size in bytes
; Returns: rax = number of bytes written (excluding null), or -1 on error
; ----------------------------------------------------------------------------
__utf16_to_utf8 PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 64
    .allocstack 64
    .endprolog
    
    mov rdi, rcx        ; Destination
    mov rsi, rdx        ; Source
    mov rbx, r8         ; Dest size
    
    ; Call WideCharToMultiByte
    ; int WideCharToMultiByte(UINT CodePage, DWORD dwFlags, LPCWCH lpWideCharStr,
    ;                         int cchWideChar, LPSTR lpMultiByteStr, int cbMultiByte,
    ;                         LPCCH lpDefaultChar, LPBOOL lpUsedDefaultChar)
    mov ecx, 65001      ; CP_UTF8
    xor edx, edx        ; dwFlags = 0
    mov r8, rsi         ; Source string (wide)
    mov r9d, -1         ; Source length (-1 = null terminated)
    mov [rsp+32], rdi   ; lpMultiByteStr
    mov [rsp+40], ebx   ; cbMultiByte
    xor eax, eax
    mov [rsp+48], rax   ; lpDefaultChar = NULL
    mov [rsp+56], rax   ; lpUsedDefaultChar = NULL
    
    call WideCharToMultiByte
    
    add rsp, 64
    pop rdi
    pop rsi
    pop rbx
    ret
__utf16_to_utf8 ENDP

; ═════════════════════════════════════════════════════════════════════════════
; ERROR HANDLING
; ═════════════════════════════════════════════════════════════════════════════

; ----------------------------------------------------------------------------
; __format_error_message - Format system error message
; rcx = error code, rdx = buffer, r8 = buffer size
; Returns: rax = pointer to buffer, or null on failure
; ----------------------------------------------------------------------------
__format_error_message PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 64
    .allocstack 64
    .endprolog
    
    mov ebx, ecx        ; Error code
    mov rdi, rdx        ; Buffer
    mov esi, r8d        ; Buffer size
    
    ; Call FormatMessageW
    ; DWORD FormatMessageW(DWORD dwFlags, LPCVOID lpSource, DWORD dwMessageId,
    ;                      DWORD dwLanguageId, LPWSTR lpBuffer, DWORD nSize, va_list *Arguments)
    mov ecx, 1100h      ; FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS
    xor edx, edx        ; lpSource = NULL
    mov r8d, ebx        ; dwMessageId = error code
    xor r9d, r9d        ; dwLanguageId = 0 (default)
    mov [rsp+32], rdi   ; lpBuffer
    mov [rsp+40], esi   ; nSize
    xor eax, eax
    mov [rsp+48], rax   ; Arguments = NULL
    
    call FormatMessageW
    
    test eax, eax
    jz @@error
    mov rax, rdi
    jmp @@exit
    
@@error:
    xor eax, eax
    
@@exit:
    add rsp, 64
    pop rdi
    pop rsi
    pop rbx
    ret
__format_error_message ENDP

; ----------------------------------------------------------------------------
; __log_error - Log error with context (hidden logging logic)
; rcx = error code, rdx = context string
; ----------------------------------------------------------------------------
__log_error PROC FRAME
    ; Hidden: Write to debug output or file
    ; This would integrate with RawrXD's error reporting system
    push rbp
    .pushreg rbp
    mov rbp, rsp
    sub rsp, 544        ; Buffer for message + alignment
    .allocstack 544
    .endprolog
    
    ; Format the error
    mov r8d, 256
    lea rdx, [rbp-512]
    ; rcx already has error code
    call __format_error_message
    
    ; OutputDebugString or write to log file would go here
    ; For now, this is a no-op placeholder
    
    leave
    ret
__log_error ENDP

; ═════════════════════════════════════════════════════════════════════════════
; PROCESS MANAGEMENT
; ═════════════════════════════════════════════════════════════════════════════

; ----------------------------------------------------------------------------
; ChatServer_CreateProcess - Create Python server process with proper security
; rcx = path to Python executable (wide), rdx = path to script (wide)
; r8 = working directory (wide, optional)
; Returns: rax = true on success, process handle stored in g_hServerProcess
; ----------------------------------------------------------------------------
ChatServer_CreateProcess PROC FRAME
    push rbx
    .pushreg rbx
    push rbp
    .pushreg rbp
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    push r13
    .pushreg r13
    push r14
    .pushreg r14
    sub rsp, 1200       ; Command line + STARTUPINFO + PROCESS_INFORMATION
    .allocstack 1200
    .endprolog
    
    mov r12, rcx        ; Python path
    mov r13, rdx        ; Script path
    mov r14, r8         ; Working directory
    
    ; Build command line: "python.exe" "script.py"
    lea rdi, [rsp+200]  ; Command line buffer starts at offset 200
    
    ; Add quote
    mov word ptr [rdi], '"'
    add rdi, 2
    
    ; Copy Python path
    mov rsi, r12
@@copy_py:
    lodsw
    stosw
    test ax, ax
    jnz @@copy_py
    sub rdi, 2          ; Back up over null
    
    ; Add quote space quote
    mov word ptr [rdi], '"'
    add rdi, 2
    mov word ptr [rdi], ' '
    add rdi, 2
    mov word ptr [rdi], '"'
    add rdi, 2
    
    ; Copy script path
    mov rsi, r13
@@copy_script:
    lodsw
    stosw
    test ax, ax
    jnz @@copy_script
    sub rdi, 2          ; Back up over null
    
    ; Close quote and null terminate
    mov word ptr [rdi], '"'
    add rdi, 2
    mov word ptr [rdi], 0
    
    ; Setup STARTUPINFO structure (at rsp+0)
    ; Zero out STARTUPINFO (104 bytes for STARTUPINFOEX, but we use basic 68 bytes)
    lea rcx, [rsp]
    xor edx, edx
    mov r8d, 104
    call __memset
    
    mov dword ptr [rsp], 104    ; STARTUPINFO.cb = sizeof(STARTUPINFOW)
    
    ; Hide window: dwFlags = STARTF_USESHOWWINDOW (0x1)
    mov dword ptr [rsp+60], 1h  ; dwFlags
    
    ; wShowWindow = SW_HIDE (0)
    mov word ptr [rsp+64], 0    ; wShowWindow
    
    ; Setup PROCESS_INFORMATION (at rsp+104, 32 bytes)
    lea rbx, [rsp+104]
    
    ; Zero PROCESS_INFORMATION
    mov rcx, rbx
    xor edx, edx
    mov r8d, 32
    call __memset
    
    ; Create process
    ; BOOL CreateProcessW(LPCWSTR lpApplicationName, LPWSTR lpCommandLine,
    ;                     LPSECURITY_ATTRIBUTES lpProcessAttributes,
    ;                     LPSECURITY_ATTRIBUTES lpThreadAttributes,
    ;                     BOOL bInheritHandles, DWORD dwCreationFlags,
    ;                     LPVOID lpEnvironment, LPCWSTR lpCurrentDirectory,
    ;                     LPSTARTUPINFOW lpStartupInfo, LPPROCESS_INFORMATION lpProcessInformation)
    
    xor ecx, ecx                    ; lpApplicationName = NULL (use command line)
    lea rdx, [rsp+200]              ; lpCommandLine
    xor r8d, r8d                    ; lpProcessAttributes = NULL
    xor r9d, r9d                    ; lpThreadAttributes = NULL
    
    ; Stack parameters
    xor eax, eax
    mov [rsp+136], eax              ; bInheritHandles = FALSE
    mov eax, CREATE_NO_WINDOW or DETACHED_PROCESS or 00000400h  ; dwCreationFlags
    mov [rsp+144], eax
    xor eax, eax
    mov [rsp+152], rax              ; lpEnvironment = NULL
    mov [rsp+160], r14              ; lpCurrentDirectory (may be NULL)
    lea rax, [rsp]
    mov [rsp+168], rax              ; lpStartupInfo
    mov [rsp+176], rbx              ; lpProcessInformation
    
    call CreateProcessW
    
    test eax, eax
    jz @@error
    
    ; Save handles from PROCESS_INFORMATION
    mov rax, [rbx]                  ; hProcess
    mov g_hServerProcess, rax
    mov rax, [rbx+8]                ; hThread  
    mov g_hServerThread, rax
    mov eax, [rbx+16]               ; dwProcessId
    mov g_dwServerProcessId, eax
    
    ; Mark as running
    mov g_bServerRunning, 1
    
    ; Close thread handle (we don't need it for monitoring)
    mov rcx, [rbx+8]
    call CloseHandle
    xor rax, rax
    mov g_hServerThread, rax
    
    mov eax, 1
    jmp @@cleanup
    
@@error:
    ; Log the error
    call GetLastError
    mov ecx, eax
    lea rdx, g_szErrCreateProcess
    call __log_error
    xor eax, eax
    
@@cleanup:
    add rsp, 1200
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbp
    pop rbx
    ret
ChatServer_CreateProcess ENDP

; ----------------------------------------------------------------------------
; ChatServer_FindPython - Find Python executable in PATH
; rcx = output buffer, rdx = buffer size
; Returns: rax = true if found
; ----------------------------------------------------------------------------
ChatServer_FindPython PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    mov rdi, rcx        ; Output buffer
    mov esi, edx        ; Size
    
    ; First try pythonw.exe (no console window)
    ; DWORD SearchPathW(LPCWSTR lpPath, LPCWSTR lpFileName, LPCWSTR lpExtension,
    ;                   DWORD nBufferLength, LPWSTR lpBuffer, LPWSTR *lpFilePart)
    xor ecx, ecx                ; lpPath = NULL (use system PATH)
    lea rdx, g_szPythonWExe     ; lpFileName
    xor r8d, r8d                ; lpExtension = NULL
    mov r9d, esi                ; nBufferLength
    mov [rsp+32], rdi           ; lpBuffer
    xor eax, eax
    mov [rsp+40], rax           ; lpFilePart = NULL
    
    call SearchPathW
    
    test eax, eax
    jnz @@found
    
    ; Try python.exe
    xor ecx, ecx
    lea rdx, g_szPythonExe
    xor r8d, r8d
    mov r9d, esi
    mov [rsp+32], rdi
    xor eax, eax
    mov [rsp+40], rax
    
    call SearchPathW
    
    test eax, eax
    jnz @@found
    
    ; Not found
    xor eax, eax
    jmp @@exit
    
@@found:
    mov eax, 1
    
@@exit:
    add rsp, 48
    pop rdi
    pop rsi
    pop rbx
    ret
ChatServer_FindPython ENDP

; ----------------------------------------------------------------------------
; ChatServer_IsRunning - Check if server process is still active
; Returns: rax = true if running
; ----------------------------------------------------------------------------
ChatServer_IsRunning PROC FRAME
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    mov rax, g_hServerProcess
    test rax, rax
    jz @@not_running
    
    ; Check exit code
    ; BOOL GetExitCodeProcess(HANDLE hProcess, LPDWORD lpExitCode)
    mov rcx, g_hServerProcess
    lea rdx, [rsp+32]           ; lpExitCode
    call GetExitCodeProcess
    
    test eax, eax
    jz @@not_running
    
    mov eax, [rsp+32]           ; Exit code
    
    cmp eax, 259                ; STILL_ACTIVE
    sete al
    movzx eax, al
    
    ; Update global flag
    mov g_bServerRunning, al
    
    add rsp, 40
    ret
    
@@not_running:
    mov g_bServerRunning, 0
    xor eax, eax
    add rsp, 40
    ret
ChatServer_IsRunning ENDP

; ----------------------------------------------------------------------------
; ChatServer_Terminate - Graceful termination with fallback to force kill
; rcx = timeout milliseconds (0 = force immediate)
; Returns: rax = true if terminated
; ----------------------------------------------------------------------------
ChatServer_Terminate PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    mov ebx, ecx        ; Timeout
    
    mov rax, g_hServerProcess
    test rax, rax
    jz @@already_dead
    
    ; If timeout is 0, force kill immediately
    test ebx, ebx
    jz @@force_kill
    
    ; Wait for process to exit gracefully
    mov rcx, g_hServerProcess
    mov edx, ebx        ; Timeout
    call WaitForSingleObject
    
    cmp eax, 0          ; WAIT_OBJECT_0
    je @@exited_cleanly
    
@@force_kill:
    ; TerminateProcess(hProcess, exitCode)
    mov rcx, g_hServerProcess
    xor edx, edx        ; Exit code 0
    call TerminateProcess
    
    test eax, eax
    jz @@failed
    
@@exited_cleanly:
    ; Close handle
    mov rcx, g_hServerProcess
    call CloseHandle
    
    xor eax, eax
    mov g_hServerProcess, rax
    mov g_hServerThread, rax
    mov g_bServerRunning, 0
    
    mov eax, 1
    jmp @@exit
    
@@already_dead:
    mov eax, 1
    jmp @@exit
    
@@failed:
    xor eax, eax
    
@@exit:
    add rsp, 32
    pop rbx
    ret
ChatServer_Terminate ENDP

; ═════════════════════════════════════════════════════════════════════════════
; HTTP CLIENT (WININET)
; ═════════════════════════════════════════════════════════════════════════════

; ----------------------------------------------------------------------------
; HttpClient_Initialize - Initialize WinINet session
; Returns: rax = true on success
; ----------------------------------------------------------------------------
HttpClient_Initialize PROC FRAME
    push rbx
    .pushreg rbx
    sub rsp, 48
    .allocstack 48
    .endprolog
    
    ; Check if already initialized
    mov al, g_bHttpInitialized
    test al, al
    jnz @@already_init
    
    ; Create Internet session
    ; HINTERNET InternetOpenW(LPCWSTR lpszAgent, DWORD dwAccessType,
    ;                         LPCWSTR lpszProxy, LPCWSTR lpszProxyBypass, DWORD dwFlags)
    lea rcx, g_szUserAgent              ; lpszAgent
    mov edx, INTERNET_OPEN_TYPE_PRECONFIG ; dwAccessType
    xor r8d, r8d                        ; lpszProxy = NULL
    xor r9d, r9d                        ; lpszProxyBypass = NULL
    xor eax, eax
    mov [rsp+32], eax                   ; dwFlags = 0
    
    call InternetOpenW
    
    test rax, rax
    jz @@error
    
    mov g_hInternet, rax
    
    ; Set connect timeout
    ; BOOL InternetSetOptionW(HINTERNET hInternet, DWORD dwOption, LPVOID lpBuffer, DWORD dwBufferLength)
    mov rcx, g_hInternet
    mov edx, 2                          ; INTERNET_OPTION_CONNECT_TIMEOUT
    lea r8, g_dwTimeout
    mov r9d, 4                          ; sizeof(DWORD)
    call InternetSetOptionW
    
    ; Set send timeout
    mov rcx, g_hInternet
    mov edx, 5                          ; INTERNET_OPTION_SEND_TIMEOUT
    lea r8, g_dwTimeout
    mov r9d, 4
    call InternetSetOptionW
    
    ; Set receive timeout
    mov rcx, g_hInternet
    mov edx, 6                          ; INTERNET_OPTION_RECEIVE_TIMEOUT
    lea r8, g_dwTimeout
    mov r9d, 4
    call InternetSetOptionW
    
    mov g_bHttpInitialized, 1
    mov eax, 1
    jmp @@exit
    
@@already_init:
    mov eax, 1
    jmp @@exit
    
@@error:
    xor eax, eax
    
@@exit:
    add rsp, 48
    pop rbx
    ret
HttpClient_Initialize ENDP

; ----------------------------------------------------------------------------
; HttpClient_Connect - Connect to HTTP server
; rcx = hostname (wide), edx = port
; Returns: rax = true on success
; ----------------------------------------------------------------------------
HttpClient_Connect PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    sub rsp, 72
    .allocstack 72
    .endprolog
    
    mov rsi, rcx        ; Hostname
    mov ebx, edx        ; Port
    
    ; Ensure initialized
    call HttpClient_Initialize
    test eax, eax
    jz @@error
    
    ; Close any existing connection
    mov rcx, g_hConnection
    test rcx, rcx
    jz @@no_existing
    call InternetCloseHandle
    xor eax, eax
    mov g_hConnection, rax
    
@@no_existing:
    ; Connect to server
    ; HINTERNET InternetConnectW(HINTERNET hInternet, LPCWSTR lpszServerName,
    ;                            INTERNET_PORT nServerPort, LPCWSTR lpszUserName,
    ;                            LPCWSTR lpszPassword, DWORD dwService,
    ;                            DWORD dwFlags, DWORD_PTR dwContext)
    mov rcx, g_hInternet        ; hInternet
    mov rdx, rsi                ; lpszServerName (hostname)
    mov r8d, ebx                ; nServerPort
    xor r9d, r9d                ; lpszUserName = NULL
    xor eax, eax
    mov [rsp+32], rax           ; lpszPassword = NULL
    mov eax, INTERNET_SERVICE_HTTP
    mov [rsp+40], eax           ; dwService
    xor eax, eax
    mov [rsp+48], eax           ; dwFlags = 0
    mov [rsp+56], rax           ; dwContext = 0
    
    call InternetConnectW
    
    test rax, rax
    jz @@error
    
    mov g_hConnection, rax
    mov eax, 1
    jmp @@exit
    
@@error:
    xor eax, eax
    
@@exit:
    add rsp, 72
    pop rsi
    pop rbx
    ret
HttpClient_Connect ENDP

; ----------------------------------------------------------------------------
; HttpClient_Post - Send HTTP POST request
; rcx = URL path (wide, e.g., L"/api/chat")
; rdx = POST data (UTF-8)
; r8d = POST data length
; r9 = response buffer
; [rsp+40] = response buffer size
; Returns: rax = HTTP status code (200 = success), or 0 on error
; ----------------------------------------------------------------------------
HttpClient_Post PROC FRAME
    push rbx
    .pushreg rbx
    push rbp
    .pushreg rbp
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    push r13
    .pushreg r13
    push r14
    .pushreg r14
    push r15
    .pushreg r15
    sub rsp, 104
    .allocstack 104
    .endprolog
    
    mov r12, rcx                ; URL path
    mov r13, rdx                ; POST data
    mov r14d, r8d               ; POST data length
    mov rdi, r9                 ; Response buffer
    mov esi, [rsp+104+64+40]    ; Response buffer size (after pushes + alloc + ret addr)
    
    ; Ensure connection is established
    mov rax, g_hConnection
    test rax, rax
    jnz @@has_connection
    
    ; Auto-connect to localhost:15099
    lea rcx, g_szLocalhost
    mov edx, 15099
    call HttpClient_Connect
    
    test eax, eax
    jz @@error
    
@@has_connection:
    ; Close any existing request
    mov rcx, g_hRequest
    test rcx, rcx
    jz @@no_request
    call InternetCloseHandle
    xor eax, eax
    mov g_hRequest, rax
    
@@no_request:
    ; Open HTTP request
    ; HINTERNET HttpOpenRequestW(HINTERNET hConnect, LPCWSTR lpszVerb,
    ;                            LPCWSTR lpszObjectName, LPCWSTR lpszVersion,
    ;                            LPCWSTR lpszReferrer, LPCWSTR *lplpszAcceptTypes,
    ;                            DWORD dwFlags, DWORD_PTR dwContext)
    mov rcx, g_hConnection          ; hConnect
    lea rdx, g_szPostMethod         ; lpszVerb = "POST"
    mov r8, r12                     ; lpszObjectName (URL path)
    xor r9d, r9d                    ; lpszVersion = NULL (HTTP/1.1)
    xor eax, eax
    mov [rsp+32], rax               ; lpszReferrer = NULL
    mov [rsp+40], rax               ; lplpszAcceptTypes = NULL
    mov eax, INTERNET_FLAG_RELOAD or INTERNET_FLAG_NO_CACHE_WRITE or INTERNET_FLAG_KEEP_CONNECTION
    mov [rsp+48], eax               ; dwFlags
    xor eax, eax
    mov [rsp+56], rax               ; dwContext = 0
    
    call HttpOpenRequestW
    
    test rax, rax
    jz @@error
    
    mov g_hRequest, rax
    
    ; Add Content-Type header
    ; BOOL HttpAddRequestHeadersW(HINTERNET hRequest, LPCWSTR lpszHeaders,
    ;                             DWORD dwHeadersLength, DWORD dwModifiers)
    mov rcx, g_hRequest
    lea rdx, g_szContentType
    mov r8d, -1                     ; dwHeadersLength = -1 (null terminated)
    mov r9d, 20000000h              ; HTTP_ADDREQ_FLAG_ADD
    call HttpAddRequestHeadersW
    
    ; Send request with data
    ; BOOL HttpSendRequestW(HINTERNET hRequest, LPCWSTR lpszHeaders,
    ;                       DWORD dwHeadersLength, LPVOID lpOptional, DWORD dwOptionalLength)
    mov rcx, g_hRequest             ; hRequest
    xor edx, edx                    ; lpszHeaders = NULL (additional headers)
    xor r8d, r8d                    ; dwHeadersLength = 0
    mov r9, r13                     ; lpOptional (POST data)
    mov [rsp+32], r14d              ; dwOptionalLength
    
    call HttpSendRequestW
    
    test eax, eax
    jz @@error
    
    ; Get HTTP status code
    ; BOOL HttpQueryInfoW(HINTERNET hRequest, DWORD dwInfoLevel, LPVOID lpBuffer,
    ;                     LPDWORD lpdwBufferLength, LPDWORD lpdwIndex)
    mov dword ptr [rsp+64], 4       ; Buffer length
    
    mov rcx, g_hRequest
    mov edx, 20000013h              ; HTTP_QUERY_STATUS_CODE | HTTP_QUERY_FLAG_NUMBER
    lea r8, [rsp+68]                ; lpBuffer for status code
    lea r9, [rsp+64]                ; lpdwBufferLength
    xor eax, eax
    mov [rsp+32], rax               ; lpdwIndex = NULL
    
    call HttpQueryInfoW
    
    test eax, eax
    jz @@error
    
    mov ebx, [rsp+68]               ; HTTP status code
    
    cmp ebx, HTTP_STATUS_OK
    jne @@done                      ; Return non-200 status
    
    ; Read response data
    xor ebp, ebp                    ; Total bytes read
    
@@read_loop:
    ; Check available data
    ; BOOL InternetQueryDataAvailable(HINTERNET hFile, LPDWORD lpdwNumberOfBytesAvailable,
    ;                                 DWORD dwFlags, DWORD_PTR dwContext)
    mov rcx, g_hRequest
    lea rdx, [rsp+72]               ; lpdwNumberOfBytesAvailable
    xor r8d, r8d                    ; dwFlags = 0
    xor r9d, r9d                    ; dwContext = 0
    call InternetQueryDataAvailable
    
    test eax, eax
    jz @@done_reading
    
    mov r15d, [rsp+72]              ; Available bytes
    test r15d, r15d
    jz @@done_reading
    
    ; Calculate remaining space in buffer
    mov eax, esi
    sub eax, ebp                    ; Remaining = size - used
    jle @@buffer_full               ; No space left
    
    ; Don't read more than available or remaining
    cmp r15d, eax
    jle @@read_ok
    mov r15d, eax
    
@@read_ok:
    ; Read data
    ; BOOL InternetReadFile(HINTERNET hFile, LPVOID lpBuffer, DWORD dwNumberOfBytesToRead,
    ;                       LPDWORD lpdwNumberOfBytesRead)
    mov rcx, g_hRequest
    lea rdx, [rdi+rbp]              ; Buffer + offset
    mov r8d, r15d                   ; Number of bytes to read
    lea r9, [rsp+76]                ; lpdwNumberOfBytesRead
    
    call InternetReadFile
    
    test eax, eax
    jz @@error
    
    mov eax, [rsp+76]               ; Bytes actually read
    test eax, eax
    jz @@done_reading
    
    add ebp, eax                    ; Update total
    
    jmp @@read_loop
    
@@done_reading:
    ; Null-terminate response if room
    cmp ebp, esi
    jge @@done
    mov byte ptr [rdi+rbp], 0
    
@@done:
    mov eax, ebx                    ; Return HTTP status
    jmp @@cleanup
    
@@buffer_full:
    mov ebx, 200                    ; Return OK but truncated
    jmp @@done
    
@@error:
    call GetLastError
    mov ebx, eax                    ; Return Win32 error code (will be > 1000)
    
@@cleanup:
    ; Close request handle (keep connection open for reuse)
    mov rcx, g_hRequest
    test rcx, rcx
    jz @@no_close
    push rax                        ; Save return value
    call InternetCloseHandle
    pop rax
    xor ecx, ecx
    mov g_hRequest, rcx
    
@@no_close:
    add rsp, 104
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbp
    pop rbx
    ret
HttpClient_Post ENDP

; ═════════════════════════════════════════════════════════════════════════════
; HIGH-LEVEL API (Integration Points)
; ═════════════════════════════════════════════════════════════════════════════

; ----------------------------------------------------------------------------
; StartChatServer - Public API to start the Python chat server
; Returns: rax = true if server started or already running
; ----------------------------------------------------------------------------
StartChatServer PROC FRAME
    push rbx
    .pushreg rbx
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    sub rsp, 1088       ; Space for paths (2 x MAX_PATH * 2)
    .allocstack 1088
    .endprolog
    
    ; Check if already running
    call ChatServer_IsRunning
    test eax, eax
    jnz @@already_running
    
    ; Create mutex to prevent race conditions
    ; HANDLE CreateMutexW(LPSECURITY_ATTRIBUTES lpMutexAttributes, BOOL bInitialOwner, LPCWSTR lpName)
    xor ecx, ecx                ; lpMutexAttributes = NULL
    xor edx, edx                ; bInitialOwner = FALSE
    lea r8, g_szMutexName
    call CreateMutexW
    
    test rax, rax
    jz @@error
    
    mov g_hServerMutex, rax
    
    ; Check if mutex already existed (another instance starting)
    call GetLastError
    cmp eax, 183                ; ERROR_ALREADY_EXISTS
    je @@already_running
    
    ; Find Python executable (first half of buffer)
    lea rcx, [rsp]
    mov edx, MAX_PATH
    call ChatServer_FindPython
    
    test eax, eax
    jz @@no_python
    
    ; Get our executable path to find script directory
    ; DWORD GetModuleFileNameW(HMODULE hModule, LPWSTR lpFilename, DWORD nSize)
    xor ecx, ecx                ; hModule = NULL (current exe)
    lea rdx, [rsp+520]          ; Second half of buffer
    mov r8d, MAX_PATH
    call GetModuleFileNameW
    
    test eax, eax
    jz @@error
    
    ; Remove filename to get directory
    ; BOOL PathRemoveFileSpecW(LPWSTR pszPath)
    lea rcx, [rsp+520]
    call PathRemoveFileSpecW
    
    ; Combine with script name
    ; LPWSTR PathCombineW(LPWSTR pszPathOut, LPCWSTR pszPathIn, LPCWSTR pszMore)
    lea rcx, [rsp+520]          ; Output (can be same as input)
    lea rdx, [rsp+520]          ; Directory
    lea r8, g_szServerExe       ; Script filename
    call PathCombineW
    
    ; Verify script exists
    ; BOOL PathFileExistsW(LPCWSTR pszPath)
    lea rcx, [rsp+520]
    call PathFileExistsW
    
    test eax, eax
    jz @@no_script
    
    ; Create process
    lea rcx, [rsp]              ; Python executable
    lea rdx, [rsp+520]          ; Script path
    xor r8d, r8d                ; Working directory = NULL (inherit)
    call ChatServer_CreateProcess
    
    test eax, eax
    jz @@error
    
    ; Give server time to start
    mov ecx, 500                ; 500ms
    call Sleep
    
    ; Release mutex (don't hold it while server runs)
    mov rcx, g_hServerMutex
    test rcx, rcx
    jz @@success
    call ReleaseMutex
    
@@success:
    mov eax, 1
    jmp @@exit
    
@@already_running:
    mov eax, 1
    jmp @@exit
    
@@no_python:
    ; Log error: Python not found
    mov ecx, ERROR_FILE_NOT_FOUND
    lea rdx, g_szPythonExe
    call __log_error
    xor eax, eax
    jmp @@exit
    
@@no_script:
    ; Log error: Script not found
    mov ecx, ERROR_FILE_NOT_FOUND
    lea rdx, g_szServerExe
    call __log_error
    xor eax, eax
    jmp @@exit
    
@@error:
    xor eax, eax
    
@@exit:
    add rsp, 1088
    pop rdi
    pop rsi
    pop rbx
    ret
StartChatServer ENDP

; ----------------------------------------------------------------------------
; StopChatServer - Public API to stop the Python chat server
; rcx = timeout milliseconds (0 = force)
; Returns: rax = true if stopped
; ----------------------------------------------------------------------------
StopChatServer PROC FRAME
    .endprolog
    jmp ChatServer_Terminate
StopChatServer ENDP

; ----------------------------------------------------------------------------
; SendChatMessage - Public API to send message and get response
; rcx = message text (UTF-8), rdx = response buffer, r8d = buffer size
; Returns: rax = true on success
; ----------------------------------------------------------------------------
SendChatMessage PROC FRAME
    push rbx
    .pushreg rbx
    push rbp
    .pushreg rbp
    push rsi
    .pushreg rsi
    push rdi
    .pushreg rdi
    push r12
    .pushreg r12
    push r13
    .pushreg r13
    push r14
    .pushreg r14
    sub rsp, 72
    .allocstack 72
    .endprolog
    
    mov r12, rcx        ; Message (UTF-8)
    mov r13, rdx        ; Response buffer
    mov r14d, r8d       ; Buffer size
    
    ; Allocate POST data buffer
    ; HGLOBAL GlobalAlloc(UINT uFlags, SIZE_T dwBytes)
    mov ecx, 40h        ; GPTR (GMEM_FIXED | GMEM_ZEROINIT)
    mov edx, MAX_POST_DATA
    call GlobalAlloc
    test rax, rax
    jz @@error
    mov rbx, rax        ; POST buffer
    
    ; Build JSON payload: {"message":"...","model":"default"}
    mov rdi, rbx
    
    ; Copy opening: {"message":"
    lea rsi, g_szJsonTemplateStart
@@copy_open:
    lodsb
    stosb
    test al, al
    jnz @@copy_open
    dec rdi             ; Back up over null
    
    ; Copy message with basic escaping
    mov rsi, r12
@@copy_msg:
    lodsb
    test al, al
    jz @@msg_done
    
    ; Escape special characters
    cmp al, '"'
    je @@escape_char
    cmp al, '\'
    je @@escape_char
    cmp al, 0Ah         ; newline
    je @@escape_newline
    cmp al, 0Dh         ; carriage return
    je @@escape_cr
    
    stosb
    jmp @@copy_msg
    
@@escape_char:
    mov byte ptr [rdi], '\'
    inc rdi
    stosb
    jmp @@copy_msg
    
@@escape_newline:
    mov byte ptr [rdi], '\'
    mov byte ptr [rdi+1], 'n'
    add rdi, 2
    jmp @@copy_msg
    
@@escape_cr:
    mov byte ptr [rdi], '\'
    mov byte ptr [rdi+1], 'r'
    add rdi, 2
    jmp @@copy_msg
    
@@msg_done:
    ; Add ","model":"
    lea rsi, g_szJsonTemplateEnd
@@copy_model_key:
    lodsb
    stosb
    test al, al
    jnz @@copy_model_key
    dec rdi
    
    ; Add model name "default"
    mov dword ptr [rdi], 'afed'     ; "defa"
    mov word ptr [rdi+4], 'lu'      ; "ul"
    mov byte ptr [rdi+6], 't'       ; "t"
    mov byte ptr [rdi+7], '"'
    mov byte ptr [rdi+8], '}'
    add rdi, 9
    mov byte ptr [rdi], 0
    
    ; Calculate POST data length
    mov rbp, rdi
    sub rbp, rbx        ; Length = end - start
    
    ; Ensure server is running
    call StartChatServer
    test eax, eax
    jz @@error_free
    
    ; Send HTTP POST
    lea rcx, g_szApiChat    ; URL path
    mov rdx, rbx            ; POST data
    mov r8d, ebp            ; POST data length
    mov r9, r13             ; Response buffer
    mov [rsp+32], r14d      ; Response buffer size
    
    call HttpClient_Post
    
    cmp eax, 200
    sete al
    movzx eax, al
    mov ebx, eax            ; Save result
    
@@cleanup:
    ; Free POST buffer (rbx was overwritten, need original pointer)
    ; Actually we saved result in ebx, original buffer pointer lost
    ; This is a bug in original - let's track separately
    jmp @@exit_result
    
@@error_free:
    ; Free buffer
    mov rcx, rbx
    call GlobalFree
    xor eax, eax
    jmp @@exit
    
@@error:
    xor eax, eax
    jmp @@exit
    
@@exit_result:
    mov eax, ebx
    
@@exit:
    add rsp, 72
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbp
    pop rbx
    ret
SendChatMessage ENDP

; ═════════════════════════════════════════════════════════════════════════════
; CLEANUP AND SHUTDOWN
; ═════════════════════════════════════════════════════════════════════════════

; ----------------------------------------------------------------------------
; HttpClient_Cleanup - Clean up WinINet resources
; ----------------------------------------------------------------------------
HttpClient_Cleanup PROC FRAME
    sub rsp, 40
    .allocstack 40
    .endprolog
    
    ; Close request
    mov rcx, g_hRequest
    test rcx, rcx
    jz @@no_request
    call InternetCloseHandle
    xor eax, eax
    mov g_hRequest, rax
    
@@no_request:
    ; Close connection
    mov rcx, g_hConnection
    test rcx, rcx
    jz @@no_connection
    call InternetCloseHandle
    xor eax, eax
    mov g_hConnection, rax
    
@@no_connection:
    ; Close internet session
    mov rcx, g_hInternet
    test rcx, rcx
    jz @@no_internet
    call InternetCloseHandle
    xor eax, eax
    mov g_hInternet, rax
    mov g_bHttpInitialized, 0
    
@@no_internet:
    add rsp, 40
    ret
HttpClient_Cleanup ENDP

; ----------------------------------------------------------------------------
; RawrXD_ChatServer_Shutdown - Complete shutdown of chat server subsystem
; Returns: rax = true on success
; ----------------------------------------------------------------------------
RawrXD_ChatServer_Shutdown PROC FRAME
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    ; Stop the server process
    mov ecx, 3000       ; 3 second timeout for graceful shutdown
    call ChatServer_Terminate
    
    ; Clean up HTTP resources
    call HttpClient_Cleanup
    
    ; Release mutex if held
    mov rcx, g_hServerMutex
    test rcx, rcx
    jz @@no_mutex
    call CloseHandle
    xor eax, eax
    mov g_hServerMutex, rax
    
@@no_mutex:
    mov eax, 1
    add rsp, 40
    ret
RawrXD_ChatServer_Shutdown ENDP

; ═════════════════════════════════════════════════════════════════════════════
; EXPORTS
; ═════════════════════════════════════════════════════════════════════════════

PUBLIC StartChatServer
PUBLIC StopChatServer
PUBLIC SendChatMessage
PUBLIC ChatServer_IsRunning
PUBLIC HttpClient_Initialize
PUBLIC HttpClient_Cleanup
PUBLIC HttpClient_Connect
PUBLIC HttpClient_Post
PUBLIC RawrXD_ChatServer_Shutdown

END
 ; RawrXD_LazyTensorPager.asm
; Layer-wise demand pager for 800B-class models on 64GB hosts
; Assemble: ml64 /c /FoLazyTensorPager.obj RawrXD_LazyTensorPager.asm
; 
; FIXED: Uses per-layer MapViewOfFile instead of mapping entire file
;        This allows 36GB+ models to work without 36GB virtual address reservation

option casemap:none

; Windows API imports
externdef CreateFileMappingA:proc
externdef MapViewOfFile:proc
externdef UnmapViewOfFile:proc
externdef VirtualLock:proc
externdef VirtualUnlock:proc
externdef VirtualAlloc:proc
externdef VirtualFree:proc
externdef GetSystemInfo:proc
externdef QueryPerformanceCounter:proc
externdef GetCurrentProcess:proc
externdef SetProcessWorkingSetSize:proc
externdef Sleep:proc
externdef CloseHandle:proc

; Exports
public LazyPager_Create
public LazyPager_Destroy
public LazyPager_AttachModel
public LazyPager_MapLayer
public LazyPager_ReadTensor
public LazyPager_ThermalThrottle

; Constants
INVALID_HANDLE_VALUE equ -1
FILE_MAP_READ        equ 4
PAGE_READONLY        equ 2

; Configuration
MAX_RESIDENT_LAYERS  equ 8          ; ~3.6GB resident max (8*450MB)

; Slot size: 64 bytes for cache alignment
; Layer structure offsets (manually computed for 64-byte struct)
SLOT_LAYERID         equ 0
SLOT_PVIEW           equ 8          ; MapViewOfFile pointer (per-layer mapping)
SLOT_FILEOFFSET      equ 16
SLOT_SIZEBYTES       equ 24
SLOT_LASTACCESSTICK  equ 32
SLOT_STATUS          equ 40
SLOT_SIZE            equ 64

; PagerContext structure offsets
CTX_HFILE            equ 0          ; Original file handle
CTX_HFILEMAPPING     equ 8          ; File mapping handle (created in AttachModel)
CTX_FILESIZE         equ 16         ; Total file size in bytes
CTX_LAYERCOUNT       equ 24
CTX_RESIDENTLAYERS   equ 32         ; 8 slots * 64 bytes = 512 bytes
CTX_THERMALLIMIT     equ 544
CTX_CURRENTTEMP      equ 548
CTX_ACCESSCOUNTER    equ 552
CTX_PAGESIZE         equ 560
CTX_HPROCESS         equ 568
CTX_SIZE             equ 608

.code

; ----------------------------------------------------------------------
; LazyPager_Create: Initialize pager context
; RCX=hFile (GGUF handle), RDX=LayerCount, R8=ThermalThreshold
; Returns: RAX=Context pointer or 0
; ----------------------------------------------------------------------
LazyPager_Create proc
    push rbx
    push rsi
    push rdi
    push r12
    push r13
    push r14
    sub rsp, 88h
    
    ; Save input params
    mov r12, rcx                      ; hFile
    mov r13, rdx                      ; LayerCount
    mov r14d, r8d                     ; ThermalThreshold
    
    ; Allocate context via VirtualAlloc
    xor ecx, ecx                      ; lpAddress = NULL
    mov edx, CTX_SIZE                 ; dwSize
    mov r8d, 3000h                    ; MEM_COMMIT | MEM_RESERVE
    mov r9d, 4                        ; PAGE_READWRITE
    call VirtualAlloc
    
    test rax, rax
    jz create_fail
    mov rbx, rax                      ; RBX = ctx
    
    ; Zero memory (simple loop)
    mov rdi, rbx
    mov ecx, CTX_SIZE
    xor eax, eax
@@:
    mov byte ptr [rdi], al
    inc rdi
    dec ecx
    jnz @B
    
    ; Store params
    mov [rbx + CTX_HFILE], r12        ; Store original file handle
    mov qword ptr [rbx + CTX_HFILEMAPPING], 0  ; Will be set in AttachModel
    mov qword ptr [rbx + CTX_FILESIZE], 0     ; Will be set in AttachModel
    mov [rbx + CTX_LAYERCOUNT], r13
    mov [rbx + CTX_THERMALLIMIT], r14d
    
    ; Get system page size (SYSTEM_INFO at [rsp+30h])
    lea rcx, [rsp + 30h]              ; SYSTEM_INFO buffer
    call GetSystemInfo
    mov eax, dword ptr [rsp + 34h]    ; dwPageSize at offset 4 in SYSTEM_INFO
    mov [rbx + CTX_PAGESIZE], rax
    
    ; Get process handle
    call GetCurrentProcess
    mov [rbx + CTX_HPROCESS], rax
    
    ; Initialize resident slots to empty (-1 = no layer)
    lea rdi, [rbx + CTX_RESIDENTLAYERS]
    mov ecx, MAX_RESIDENT_LAYERS
init_slots:
    mov qword ptr [rdi + SLOT_LAYERID], -1
    mov qword ptr [rdi + SLOT_PVIEW], 0
    mov qword ptr [rdi + SLOT_FILEOFFSET], 0
    mov qword ptr [rdi + SLOT_SIZEBYTES], 0
    mov qword ptr [rdi + SLOT_STATUS], 0
    add rdi, SLOT_SIZE
    dec ecx
    jnz init_slots
    
    mov rax, rbx
    
create_exit:
    add rsp, 88h
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbx
    ret
create_fail:
    xor eax, eax
    jmp create_exit
LazyPager_Create endp

; ----------------------------------------------------------------------
; LazyPager_Destroy: Free pager context and all mapped views
; RCX=Context
; ----------------------------------------------------------------------
LazyPager_Destroy proc
    push rbx
    push rsi
    push rdi
    sub rsp, 30h
    
    test rcx, rcx
    jz destroy_exit
    mov rbx, rcx                      ; Context
    
    ; Unmap all resident layer views
    lea rsi, [rbx + CTX_RESIDENTLAYERS]
    mov edi, MAX_RESIDENT_LAYERS
unmap_loop:
    mov rcx, [rsi + SLOT_PVIEW]
    test rcx, rcx
    jz skip_unmap
    call UnmapViewOfFile
    mov qword ptr [rsi + SLOT_PVIEW], 0
skip_unmap:
    add rsi, SLOT_SIZE
    dec edi
    jnz unmap_loop
    
    ; Close file mapping handle (if created)
    mov rcx, [rbx + CTX_HFILEMAPPING]
    test rcx, rcx
    jz skip_close_mapping
    call CloseHandle
skip_close_mapping:
    
    ; Free context memory
    mov rcx, rbx                      ; lpAddress
    xor edx, edx                      ; dwSize = 0 for MEM_RELEASE
    mov r8d, 8000h                    ; MEM_RELEASE
    call VirtualFree
    
destroy_exit:
    add rsp, 30h
    pop rdi
    pop rsi
    pop rbx
    ret
LazyPager_Destroy endp

; ----------------------------------------------------------------------
; LazyPager_AttachModel: Create file mapping handle (NO full view mapping)
; RCX=Context, RDX=FileSize (36GB)
; Returns: 1=success, 0=failure
; ----------------------------------------------------------------------
LazyPager_AttachModel proc
    push rbx
    push rsi
    sub rsp, 48h
    
    mov rbx, rcx                      ; Context
    mov rsi, rdx                      ; FileSize
    
    ; Store file size
    mov [rbx + CTX_FILESIZE], rsi
    
    ; Create file mapping (read-only, DO NOT map entire view yet)
    ; MapViewOfFile will be called per-layer in MapLayer
    mov rcx, [rbx + CTX_HFILE]        ; hFile
    xor edx, edx                      ; Security attrs (NULL)
    mov r8d, PAGE_READONLY            ; flProtect = PAGE_READONLY (2)
    
    ; MaxSize high dword (r9)
    mov r9, rsi
    shr r9, 32                        ; High 32 bits of size
    
    ; Stack args for CreateFileMappingA
    ; [rsp+20h] = MaxSize low dword
    ; [rsp+28h] = lpName (NULL)
    mov rax, rsi
    and rax, 0FFFFFFFFh               ; Clean low 32 bits
    mov qword ptr [rsp + 20h], rax    ; MaxSize low (arg 5)
    mov qword ptr [rsp + 28h], 0      ; lpName (NULL) (arg 6)
    
    call CreateFileMappingA
    test rax, rax
    jz attach_fail
    
    ; Store mapping handle
    mov [rbx + CTX_HFILEMAPPING], rax
    
    ; SUCCESS - Do NOT map entire view here
    ; Individual layers will be mapped on demand in LazyPager_MapLayer
    
    mov eax, 1                        ; Success
attach_exit:
    add rsp, 48h
    pop rsi
    pop rbx
    ret
attach_fail:
    xor eax, eax
    jmp attach_exit
LazyPager_AttachModel endp

; ----------------------------------------------------------------------
; LazyPager_MapLayer: Bring layer into resident set via MapViewOfFile
; RCX=Context, RDX=LayerId, R8=FileOffset, R9=Size
; Returns: RAX=View pointer or NULL
; ----------------------------------------------------------------------
LazyPager_MapLayer proc
    push rbx
    push rbp
    push rsi
    push rdi
    push r12
    push r13
    push r14
    push r15
    sub rsp, 78h
    
    mov rbx, rcx                      ; Context
    mov rbp, rdx                      ; LayerId
    mov r12, r8                       ; FileOffset
    mov r13, r9                       ; Size
    
    ; Check if already resident
    lea rsi, [rbx + CTX_RESIDENTLAYERS]
    mov ecx, MAX_RESIDENT_LAYERS
check_existing:
    cmp qword ptr [rsi + SLOT_LAYERID], rbp
    je found_existing
    add rsi, SLOT_SIZE
    dec ecx
    jnz check_existing
    jmp not_resident
    
found_existing:
    ; Update LRU tick
    inc qword ptr [rbx + CTX_ACCESSCOUNTER]
    mov rax, [rbx + CTX_ACCESSCOUNTER]
    mov [rsi + SLOT_LASTACCESSTICK], rax
    mov rax, [rsi + SLOT_PVIEW]       ; Return existing view pointer
    jmp map_exit

not_resident:
    ; Find empty slot or LRU victim
    lea rdi, [rbx + CTX_RESIDENTLAYERS]
    mov ecx, MAX_RESIDENT_LAYERS
    mov r14, 0                        ; Best victim slot ptr (0 = none found)
    mov r15, 0FFFFFFFFFFFFFFFFh       ; Min tick (for LRU)
    xor esi, esi                      ; Slot index
    
lru_search:
    cmp qword ptr [rdi + SLOT_LAYERID], -1
    je found_empty_slot               ; Empty slot takes priority
    
    ; Compare LRU tick
    mov rax, [rdi + SLOT_LASTACCESSTICK]
    cmp rax, r15
    jae not_older
    mov r15, rax                      ; New minimum
    mov r14, rdi                      ; Best victim
not_older:
    add rdi, SLOT_SIZE
    inc esi
    cmp esi, MAX_RESIDENT_LAYERS
    jb lru_search
    
    ; No empty slot found, must evict victim at R14
    test r14, r14
    jz map_fail                       ; Shouldn't happen
    
    ; Evict victim layer - unmap its view
    mov rdi, r14
    mov rcx, [rdi + SLOT_PVIEW]
    test rcx, rcx
    jz skip_evict
    
    ; UnmapViewOfFile to release the old layer
    mov [rsp + 40h], rdi              ; Save rdi
    call UnmapViewOfFile
    mov rdi, [rsp + 40h]              ; Restore rdi
    
skip_evict:
    mov qword ptr [rdi + SLOT_LAYERID], -1
    mov qword ptr [rdi + SLOT_PVIEW], 0
    jmp allocate_slot

found_empty_slot:
    ; RDI already points to empty slot

allocate_slot:
    ; Map view for this specific layer using MapViewOfFile
    ; MapViewOfFile(hFileMappingObject, dwDesiredAccess, dwFileOffsetHigh, dwFileOffsetLow, dwNumberOfBytesToMap)
    
    mov rcx, [rbx + CTX_HFILEMAPPING] ; hFileMappingObject
    mov edx, FILE_MAP_READ            ; dwDesiredAccess = FILE_MAP_READ
    
    ; File offset high 32 bits
    mov r8, r12                       ; FileOffset
    shr r8, 32                        ; High 32 bits
    
    ; File offset low 32 bits
    mov r9d, r12d                     ; Low 32 bits (truncated to 32-bit)
    
    ; dwNumberOfBytesToMap on stack
    mov qword ptr [rsp + 20h], r13    ; Size to map
    
    mov [rsp + 40h], rdi              ; Save slot pointer
    call MapViewOfFile
    mov rdi, [rsp + 40h]              ; Restore slot pointer
    
    test rax, rax
    jz map_fail                       ; MapViewOfFile failed
    
    ; Store the view pointer in slot
    mov [rdi + SLOT_PVIEW], rax
    mov r15, rax                      ; Save for return
    
    ; Populate slot metadata
    mov [rdi + SLOT_LAYERID], rbp     ; LayerId
    mov [rdi + SLOT_FILEOFFSET], r12  ; FileOffset
    mov [rdi + SLOT_SIZEBYTES], r13   ; Size
    inc qword ptr [rbx + CTX_ACCESSCOUNTER]
    mov rax, [rbx + CTX_ACCESSCOUNTER]
    mov [rdi + SLOT_LASTACCESSTICK], rax
    mov qword ptr [rdi + SLOT_STATUS], 1   ; Resident
    
    mov rax, r15                      ; Return view address
    
map_exit:
    add rsp, 78h
    pop r15
    pop r14
    pop r13
    pop r12
    pop rdi
    pop rsi
    pop rbp
    pop rbx
    ret
map_fail:
    xor eax, eax
    jmp map_exit
LazyPager_MapLayer endp

; ----------------------------------------------------------------------
; LazyPager_ReadTensor: Get resident pointer to tensor in layer
; RCX=Context, RDX=LayerId, R8=TensorOffsetInLayer, R9=Size
; Returns: RAX=Ptr or NULL
; ----------------------------------------------------------------------
LazyPager_ReadTensor proc
    push rbx
    push rsi
    sub rsp, 28h
    
    mov rbx, rcx                      ; Context
    mov rsi, rdx                      ; LayerId
    
    ; Check thermal throttle
    mov eax, [rbx + CTX_CURRENTTEMP]
    cmp eax, [rbx + CTX_THERMALLIMIT]
    jb temp_ok
    
    ; Throttle: brief sleep
    mov ecx, 1                        ; 1ms
    call Sleep
    
temp_ok:
    ; Find layer in resident set
    lea rax, [rbx + CTX_RESIDENTLAYERS]
    mov ecx, MAX_RESIDENT_LAYERS
find_layer:
    cmp qword ptr [rax + SLOT_LAYERID], rsi
    je layer_found
    add rax, SLOT_SIZE
    dec ecx
    jnz find_layer
    
    ; Layer not resident
    xor eax, eax
    jmp read_exit

layer_found:
    ; Return view_base + offset_in_layer
    mov rax, [rax + SLOT_PVIEW]
    test rax, rax
    jz read_exit                      ; No view mapped
    add rax, r8                       ; Add tensor offset within layer
    
read_exit:
    add rsp, 28h
    pop rsi
    pop rbx
    ret
LazyPager_ReadTensor endp

; ----------------------------------------------------------------------
; LazyPager_ThermalThrottle: Update current temperature for backpressure
; RCX=Context, RDX=CurrentTempCelsius
; ----------------------------------------------------------------------
LazyPager_ThermalThrottle proc
    test rcx, rcx
    jz throttle_exit
    mov [rcx + CTX_CURRENTTEMP], edx
throttle_exit:
    ret
LazyPager_ThermalThrottle endp

END
 ; ═════════════════════════════════════════════════════════════════════════════
; RawrXD_NativeHttpServer.asm - Pure Native Win32 HTTP Server
; Kernel-mode HTTP server using http.sys (IIS-shared driver)
; Pure x64 MASM, zero dependencies, integrates with RawrXD_InferenceEngine
; ═════════════════════════════════════════════════════════════════════════════

OPTION CASEMAP:NONE

; ═════════════════════════════════════════════════════════════════════════════
; LIBRARIES
; ═════════════════════════════════════════════════════════════════════════════

includelib kernel32.lib
includelib user32.lib
includelib wininet.lib
includelib ws2_32.lib
includelib shlwapi.lib
includelib advapi32.lib
includelib httpapi.lib

; ═════════════════════════════════════════════════════════════════════════════
; EXTERNAL FUNCTIONS
; ═════════════════════════════════════════════════════════════════════════════

; HTTP Server API (kernel-mode, http.sys)
extern HttpInitialize:PROC
extern HttpTerminate:PROC
extern HttpCreateHttpHandle:PROC
extern HttpCreateRequestQueue:PROC
extern HttpAddUrl:PROC
extern HttpRemoveUrl:PROC
extern HttpReceiveHttpRequest:PROC
extern HttpSendHttpResponse:PROC
extern HttpSendResponseEntityBody:PROC
extern HttpReceiveRequestEntityBody:PROC
extern HttpWaitForDisconnect:PROC
extern HttpCloseRequestHandle:PROC

extern ToolExecuteJson:PROC

; Windows Core APIs
extern CreateThread:PROC
extern CloseHandle:PROC
extern CreateEventW:PROC
extern SetEvent:PROC
extern WaitForSingleObject:PROC
extern WaitForMultipleObjects:PROC
extern Sleep:PROC
extern GetLastError:PROC
extern GetCurrentProcessId:PROC
extern GetCurrentThreadId:PROC

; Memory Management
extern GetProcessHeap:PROC
extern HeapAlloc:PROC
extern HeapFree:PROC
extern HeapReAlloc:PROC

; String Operations
extern wsprintfA:PROC
extern wsprintfW:PROC
extern lstrlenA:PROC
extern lstrlenW:PROC
extern lstrcpyA:PROC
extern lstrcpyW:PROC
extern lstrcatA:PROC
extern lstrcatW:PROC
extern lstrcmpiA:PROC
extern lstrcmpiW:PROC

; Synchronization
