 ; =============================================================================
; RawrXD_QuadBuffer_DMA_Orchestrator.asm
; Pure MASM x64 Implementation of HDD-to-RAM-to-VRAM Quad-Buffer
; For 800B Parameter Models with Direct I/O (DMA) Bypassing OS Cache
; =============================================================================
; Architecture:
;   Layer N   -> GPU Compute (Active)
;   Layer N+1 -> VRAM Preload (DMA from RAM)
;   Layer N+2 -> RAM Cache (Async from HDD)
;   Layer N+3 -> HDD Prefetch (Background I/O)
;
; The "backwards formula" creates a sliding window of reality:
;   GPU always sees 4GB of contiguous VRAM with current + next 3 layers
;   MASM orchestrator transparently manages 800GB HDD stream
;   YTFN_SENTINEL trap ensures GPU never reads uninitialized memory
; =============================================================================

OPTION CASEMAP:NONE
OPTION WIN64:3

INCLUDE \masm64\include64\masm64rt.inc

; =============================================================================
; CONSTANTS FOR 800B SCALING
; =============================================================================
QUAD_BUFFER_COUNT   EQU 4
PAGE_SIZE           EQU 040000000h       ; 1GB pages (1 << 30)
PAGE_SHIFT          EQU 30
YTFN_SENTINEL       EQU 07FFFFFFFFFFFFFFFh  ; Trap sentinel (highest pos i64)
HDD_BLOCK_SIZE      EQU 0100000000h      ; 4GB HDD chunks
DMA_ALIGNMENT       EQU 4096             ; Page alignment for Direct I/O

; Buffer status flags
BUF_STATE_EMPTY     EQU 0   ; Available for loading
BUF_STATE_LOADING   EQU 1   ; DMA in progress
BUF_STATE_READY     EQU 2   ; Ready for compute
BUF_STATE_COMPUTING EQU 3   ; Currently on GPU

; Win32 constants
FILE_FLAG_NO_BUFFERING     EQU 020000000h
FILE_FLAG_OVERLAPPED       EQU 040000000h
FILE_FLAG_SEQUENTIAL_SCAN  EQU 008000000h
GENERIC_READ               EQU 080000000h
OPEN_EXISTING              EQU 3
MEM_COMMIT                 EQU 1000h
MEM_RESERVE                EQU 2000h
MEM_LARGE_PAGES            EQU 20000000h
PAGE_READWRITE             EQU 4
WAIT_OBJECT_0              EQU 0
WAIT_TIMEOUT               EQU 258
INFINITE                   EQU -1

; =============================================================================
; DATA STRUCTURES
; =============================================================================

OVERLAPPED STRUCT
    Internal                DQ  ?
    InternalHigh            DQ  ?
    Offset                  DD  ?
    OffsetHigh              DD  ?
    hEvent                  DQ  ?
OVERLAPPED ENDS

QUAD_SLOT STRUCT
    state               DD  ?           ; BUF_STATE_*
    layer_idx           DD  ?           ; Which layer this holds (-1 = empty)
    vram_ptr            DQ  ?           ; GPU memory address
    ram_ptr             DQ  ?           ; Pinned system RAM address
    hdd_offset          DQ  ?           ; File offset on disk
    dma_overlapped      OVERLAPPED <>   ; Windows async I/O structure
    hEvent              DQ  ?           ; Completion event
    padding             DD  ?           ; Align to 128 bytes for cache line
QUAD_SLOT ENDS

INFINITY_STREAM STRUCT
    ; The "Virtual" 800B address space
    hdd_file_handle     DQ  ?           ; Handle to model file (unbuffered)
    total_layers        DD  ?
    layer_size          DQ  ?           ; Uniform layer size for 800B
    
    ; Quad-buffer state machine
    slots               QUAD_SLOT QUAD_BUFFER_COUNT DUP(<>)
    current_gpu_layer   DD  ?           ; Which layer GPU is currently on
    current_dma_slot    DD  ?           ; Which slot is being DMA'd
    
    ; Synchronization
    status_lock         DQ  ?           ; SRWLock for status updates
    dma_completion_port DQ  ?           ; I/O Completion Port
    
    ; Metrics
    hdd_read_bytes      DQ  ?
    dma_write_bytes     DQ  ?
    stall_cycles        DQ  ?
    trap_count          DD  ?
    trap_resolved_count DD  ?
INFINITY_STREAM ENDS

; =============================================================================
; DATA SECTION
; =============================================================================

.DATA

align 64
g_infinity_stream   INFINITY_STREAM <>

; Pre-calculated masks for modulo 4 (bitwise AND)
align 16
g_mod4_mask         DQ 03h, 03h, 03h, 03h

; AVX-512 index scale for gather operations
align 64
g_vramptr_indices   DQ 0, 8, 16, 24, 32, 40, 48, 56

; Phase integration constants
PHASE_2_MODEL_LAYER_SIZE DQ 1000000h    ; Phase 2 exports this
PHASE_3_TENSOR_STRIDE    DQ 100000h     ; Phase 3 stride
PHASE_4_DMA_BATCH_SIZE   DQ 8h          ; Phase 4 batch units

.CODE

; =============================================================================
; INFINITY_InitializeStream
; Opens 800B model file with Direct I/O (no OS caching)
; RCX = path to model file (wchar_t*)
; RDX = layer size (bytes)
; R8 = total layers
; R9 = vram_base
; Returns RAX = INFINITY_STREAM* or NULL
; =============================================================================
INFINITY_InitializeStream PROC FRAME
    push rbx rsi rdi r12 r13 r14 r15
    sub rsp, 96
    .allocstack 96
    .endprolog
    
    mov r12, rcx                    ; file path
    mov r13, rdx                    ; layer_size
    mov r14d, r8d                   ; total_layers
    mov r15, r9                     ; vram_base
    
    lea rdi, g_infinity_stream
    mov [rdi].INFINITY_STREAM.layer_size, r13
    mov [rdi].INFINITY_STREAM.total_layers, r14d
    
    ; Open file with FILE_FLAG_NO_BUFFERING | FILE_FLAG_OVERLAPPED
    ; This bypasses Windows cache entirely, preventing 800GB from polluting system RAM
    mov rcx, r12                    ; lpFileName
    mov edx, GENERIC_READ           ; dwDesiredAccess (read-only)
    xor r8d, r8d                    ; dwShareMode (exclusive)
    xor r9d, r9d                    ; lpSecurityAttributes
    
    mov rax, FILE_FLAG_NO_BUFFERING
    or rax, FILE_FLAG_OVERLAPPED
    or rax, FILE_FLAG_SEQUENTIAL_SCAN
    mov [rsp + 40], 3               ; OPEN_EXISTING
    mov [rsp + 48], rax             ; dwFlagsAndAttributes
    mov [rsp + 56], 0               ; hTemplateFile
    
    call CreateFileW
    
    cmp rax, -1
    je init_failed
    mov [rdi].INFINITY_STREAM.hdd_file_handle, rax
    
    ; Initialize I/O Completion Port for async notifications
    ; This allows zero-overhead notification when HDD reads complete
    mov rcx, rax                    ; FileHandle
    xor edx, edx                    ; ExistingCompletionPort (NULL = create new)
    xor r8d, r8d                    ; CompletionKey
    xor r9d, r9d                    ; NumberOfConcurrentThreads (0 = CPU count)
    call CreateIoCompletionPort
    
    cmp rax, 0
    je init_failed
    mov [rdi].INFINITY_STREAM.dma_completion_port, rax
    
    ; Initialize SRWLock for minimal-overhead synchronization
    lea rcx, [rdi].INFINITY_STREAM.status_lock
    call InitializeSRWLock
    
    ; Allocate pinned RAM for all 4 slots (4GB total)
    ; VirtualAlloc with MEM_LARGE_PAGES for optimal DMA performance
    mov eax, QUAD_BUFFER_COUNT
    mov rcx, PAGE_SIZE
    mul rcx                         ; RAX = 4GB (4 * 1GB)
    mov r12, rax                    ; Total allocation
    
    mov rcx, rax                    ; lpAddress
    mov edx, MEM_COMMIT or MEM_RESERVE or MEM_LARGE_PAGES
    mov r8d, PAGE_READWRITE
    call VirtualAlloc
    
    test rax, rax
    jz init_failed
    mov rsi, rax                    ; RAM base
    
    ; Initialize each quad slot
    mov rbx, rdi                    ; INFINITY_STREAM base
    add rbx, OFFSET INFINITY_STREAM.slots
    xor ecx, ecx                    ; Slot index
    
init_slot_loop:
    cmp ecx, QUAD_BUFFER_COUNT
    jge init_done
    
    mov [rbx].QUAD_SLOT.state, BUF_STATE_EMPTY
    mov DWORD PTR [rbx].QUAD_SLOT.layer_idx, -1
    
    ; VRAM pointer: vram_base + (slot_idx * PAGE_SIZE)
    mov eax, PAGE_SIZE
    mul ecx
    add rax, r15
    mov [rbx].QUAD_SLOT.vram_ptr, rax
    
    ; RAM pointer: ram_base + (slot_idx * PAGE_SIZE)
    mov eax, ecx
    mov r12d, PAGE_SIZE
    mul r12                         ; RAX = slot_idx * PAGE_SIZE
    add rax, rsi
    mov [rbx].QUAD_SLOT.ram_ptr, rax
    
    ; Create completion event for this slot (auto-reset, initially false)
    xor ecx, ecx
    mov edx, 1                      ; bManualReset = FALSE (auto-reset)
    xor r8d, r8d                    ; bInitialState = FALSE
    xor r9, r9                      ; lpName
    call CreateEventA
    mov [rbx].QUAD_SLOT.hEvent, rax
    
    add rbx, SIZEOF QUAD_SLOT
    mov ecx, [rdi].INFINITY_STREAM.total_layers  ; Restore for loop
    xor ecx, ecx
    inc ecx
    cmp ecx, QUAD_BUFFER_COUNT
    jle init_slot_loop
    
init_done:
    mov rax, rdi                    ; Return INFINITY_STREAM*
    add rsp, 96
    pop r15 r14 r13 r12 rdi rsi rbx
    ret
    
init_failed:
    xor eax, eax
    add rsp, 96
    pop r15 r14 r13 r12 rdi rsi rbx
    ret
INFINITY_InitializeStream ENDP

; =============================================================================
; INFINITY_CheckQuadBuffer
; The Core "Backwards" Formula Implementation
; Returns physical VRAM pointer or YTFN_SENTINEL trap
;
; The "backwards formula" creates the sliding window:
;   slot = layer_idx % 4
;   if slots[slot].layer_idx == layer_idx && slots[slot].state == READY
;       return slots[slot].vram_ptr
;   else
;       return YTFN_SENTINEL (trap)
;
; RCX = Requested Virtual Layer Index (i)
; RDX = Current Buffer Head (for validation)
; Returns RAX = Physical VRAM Pointer or YTFN_SENTINEL
; =============================================================================
INFINITY_CheckQuadBuffer PROC FRAME
    push rbx r12 r13 r14 r15
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    mov r12, rcx                    ; Save layer index
    mov r13, rdx                    ; Save buffer head
    lea r15, g_infinity_stream
    
    ; 1. Calculate Buffer Slot: slot = i % 4 (bitwise AND with 3)
    mov rax, r12
    and rax, 3                      ; RAX = slot_index (0-3)
    mov rbx, rax                    ; RBX = slot_index
    
    ; 2. Acquire SRWLock (shared read) to check status
    lea rcx, [r15].INFINITY_STREAM.status_lock
    call AcquireSRWLockShared
    
    ; 3. Get slot state
    mov r14, r15
    add r14, OFFSET INFINITY_STREAM.slots
    mov eax, SIZEOF QUAD_SLOT
    mul rbx                         ; RAX = slot_index * sizeof(QUAD_SLOT)
    add r14, rax                    ; R14 = &slots[slot_index]
    
    mov eax, [r14].QUAD_SLOT.state
    cmp eax, BUF_STATE_READY
    je buffer_ready
    cmp eax, BUF_STATE_COMPUTING
    je buffer_computing
    
    ; Buffer not ready - release lock and return YTFN trap
    lea rcx, [r15].INFINITY_STREAM.status_lock
    call ReleaseSRWLockShared
    
    ; Return YTFN_SENTINEL encoded with layer index
    mov rax, YTFN_SENTINEL
    sub rax, r12                    ; Encode layer for trap handler
    inc dword ptr [r15].INFINITY_STREAM.trap_count
    
    add rsp, 40
    pop r15 r14 r13 r12 rbx
    ret
    
buffer_computing:
    ; Already computing on GPU - valid access
    ; Fall through to return pointer
    
buffer_ready:
    ; 4. Calculate Physical Address
    ; Physical = vram_ptr + offset_within_page
    ; For uniform 1GB layers, offset is 0
    mov rax, [r14].QUAD_SLOT.vram_ptr
    
    ; Verify layer index matches
    cmp DWORD PTR [r14].QUAD_SLOT.layer_idx, r12d
    jne buffer_mismatch
    
    ; Mark as computing
    mov [r14].QUAD_SLOT.state, BUF_STATE_COMPUTING
    
    ; Release lock
    lea rcx, [r15].INFINITY_STREAM.status_lock
    call ReleaseSRWLockShared
    
    add rsp, 40
    pop r15 r14 r13 r12 rbx
    ret
    
buffer_mismatch:
    ; Layer mismatch - stale data, return trap
    lea rcx, [r15].INFINITY_STREAM.status_lock
    call ReleaseSRWLockShared
    mov rax, YTFN_SENTINEL
    sub rax, r12
    inc dword ptr [r15].INFINITY_STREAM.trap_count
    
    add rsp, 40
    pop r15 r14 r13 r12 rbx
    ret
INFINITY_CheckQuadBuffer ENDP

; =============================================================================
; INFINITY_RotateBuffers
; The "Backwards" DMA Request - Manages the Sliding Window
; Triggered when GPU finishes processing a layer
;
; State transitions:
;   slot[i-2].COMPUTING -> slot[i-2].EMPTY (GPU done, reuse for prefetch)
;   slot[i].LOADING -> slot[i].READY (HDD read complete, ready for GPU)
;   slot[i+2].EMPTY -> slot[i+2].LOADING (Start HDD prefetch)
;
; RCX = current_layer (the one GPU just finished)
; =============================================================================
INFINITY_RotateBuffers PROC FRAME
    push rbx rsi rdi r12 r13 r14 r15
    sub rsp, 80
    .allocstack 80
    .endprolog
    
    mov r12, rcx                    ; Current layer
    lea r15, g_infinity_stream
    
    ; Acquire exclusive lock for state modification
    lea rcx, [r15].INFINITY_STREAM.status_lock
    call AcquireSRWLockExclusive
    
    ; 1. Free Slot (current - 2) - GPU is done with it 2 layers ago
    ; This slot can now be reused for prefetch
    mov rax, r12
    sub rax, 2
    and rax, 3                      ; Mod 4
    mov rbx, rax                    ; Free slot index
    
    mov r13, r15
    add r13, OFFSET INFINITY_STREAM.slots
    mov eax, SIZEOF QUAD_SLOT
    mul rbx
    add r13, rax                    ; R13 = &slots[free_slot]
    
    ; Only free if it was in COMPUTING state
    cmp [r13].QUAD_SLOT.state, BUF_STATE_COMPUTING
    jne skip_free
    
    mov [r13].QUAD_SLOT.state, BUF_STATE_EMPTY
    mov DWORD PTR [r13].QUAD_SLOT.layer_idx, -1
    
skip_free:
    ; 2. Start Async Read from HDD for (current + 2)
    mov rax, r12
    add rax, 2                      ; N+2 prefetch
    cmp eax, [r15].INFINITY_STREAM.total_layers
    jae skip_prefetch               ; Beyond model end
    
    ; Find an empty slot for the new layer
    xor ecx, ecx
find_empty_slot:
    cmp ecx, QUAD_BUFFER_COUNT
    jge skip_prefetch               ; No empty slots available
    
    mov r14, r15
    add r14, OFFSET INFINITY_STREAM.slots
    mov eax, SIZEOF QUAD_SLOT
    mul ecx
    add r14, rax
    
    cmp [r14].QUAD_SLOT.state, BUF_STATE_EMPTY
    je found_empty
    inc ecx
    jmp find_empty_slot
    
found_empty:
    ; R14 = empty slot, ECX = slot index, RAX = layer to load
    mov [r14].QUAD_SLOT.layer_idx, eax
    mov [r14].QUAD_SLOT.state, BUF_STATE_LOADING
    
    ; Calculate HDD offset: layer_idx * layer_size
    mov rbx, rax
    mov rax, [r15].INFINITY_STREAM.layer_size
    mul rbx
    mov [r14].QUAD_SLOT.hdd_offset, rax
    
    ; Initiate async read with Direct I/O
    mov rcx, [r15].INFINITY_STREAM.hdd_file_handle
    mov rdx, [r14].QUAD_SLOT.ram_ptr  ; Buffer (must be DMA aligned)
    mov r8, [r15].INFINITY_STREAM.layer_size
    lea r9, [r14].QUAD_SLOT.dma_overlapped
    
    ; Set up OVERLAPPED structure with file offset
    mov rbx, [r14].QUAD_SLOT.hdd_offset
    mov [r14].QUAD_SLOT.dma_overlapped.Offset, ebx
    shr rbx, 32
    mov [r14].QUAD_SLOT.dma_overlapped.OffsetHigh, ebx
    mov rax, [r14].QUAD_SLOT.hEvent
    mov [r14].QUAD_SLOT.dma_overlapped.hEvent, rax
    
    call ReadFile
    test eax, eax
    jnz read_completed_sync         ; Synchronous completion (unlikely with Direct I/O)
    
    call GetLastError
    cmp eax, 997                    ; ERROR_IO_PENDING
    je read_pending
    
    ; Read failed - mark slot empty
    mov [r14].QUAD_SLOT.state, BUF_STATE_EMPTY
    jmp skip_prefetch
    
read_completed_sync:
    ; Mark as ready immediately (rare case with cached data)
    mov [r14].QUAD_SLOT.state, BUF_STATE_READY
    jmp skip_prefetch
    
read_pending:
    ; Async read in progress - completion will be handled by IOCP
    
skip_prefetch:
    ; 3. Start DMA from RAM to VRAM for (current + 1) if ready
    mov rax, r12
    inc rax                         ; N+1
    cmp eax, [r15].INFINITY_STREAM.total_layers
    jae skip_dma
    
    ; Find slot with this layer in RAM (LOADING state -> check completion)
    xor ecx, ecx
check_loading_slots:
    cmp ecx, QUAD_BUFFER_COUNT
    jge skip_dma
    
    mov r14, r15
    add r14, OFFSET INFINITY_STREAM.slots
    mov eax, SIZEOF QUAD_SLOT
    mul ecx
    add r14, rax
    
    cmp [r14].QUAD_SLOT.state, BUF_STATE_LOADING
    jne next_slot
    
    cmp DWORD PTR [r14].QUAD_SLOT.layer_idx, r12d
    jne next_slot_inc
    
    ; Found layer N+1 in loading state - check if HDD read completed
    mov rcx, [r14].QUAD_SLOT.hEvent
    xor edx, edx                    ; dwMilliseconds = 0 (non-blocking)
    call WaitForSingleObject
    
    cmp eax, 0                      ; WAIT_OBJECT_0
    jne next_slot                   ; Still loading
    
    ; HDD read complete - mark as ready for GPU DMA
    mov [r14].QUAD_SLOT.state, BUF_STATE_READY
    
    ; Note: Actual GPU DMA would be initiated here by Phase 4
    ; For now, we mark ready and Phase 3/4 will handle transfer
    
    jmp skip_dma
    
next_slot_inc:
    inc ecx
next_slot:
    inc ecx
    jmp check_loading_slots
    
skip_dma:
    ; Release exclusive lock
    lea rcx, [r15].INFINITY_STREAM.status_lock
    call ReleaseSRWLockExclusive
    
    add rsp, 80
    pop r15 r14 r13 r12 rdi rsi rbx
    ret
INFINITY_RotateBuffers ENDP

; =============================================================================
; INFINITY_ProcessIOCP
; Background thread to handle I/O completion notifications
; Runs on dedicated thread, processes HDD read completions
; =============================================================================
INFINITY_ProcessIOCP PROC FRAME
    push rbx rsi rdi r12 r13 r14 r15
    sub rsp, 96
    .allocstack 96
    .endprolog
    
    lea r15, g_infinity_stream
    
iocp_loop:
    ; Get completion status from I/O Completion Port
    mov rcx, [r15].INFINITY_STREAM.dma_completion_port
    lea rdx, [rsp + 40]             ; lpNumberOfBytesTransferred
    lea r8, [rsp + 48]              ; lpCompletionKey
    lea r9, [rsp + 56]              ; lpOverlapped
    mov QWORD PTR [rsp + 64], INFINITE  ; dwMilliseconds
    call GetQueuedCompletionStatus
    
    test eax, eax
    jz iocp_error
    
    ; Find which slot completed
    mov r12, [rsp + 56]             ; OVERLAPPED* from completion
    mov r13, r15
    add r13, OFFSET INFINITY_STREAM.slots
    xor ecx, ecx
    
find_slot:
    cmp ecx, QUAD_BUFFER_COUNT
    jge iocp_loop                   ; Not found (shouldn't happen)
    
    mov rax, r13
    add rax, rcx
    mov rbx, rax
    mov eax, SIZEOF QUAD_SLOT
    mul ecx
    add rax, r13
    
    lea r14, [rax].QUAD_SLOT.dma_overlapped
    cmp r14, r12
    je slot_found
    inc ecx
    jmp find_slot
    
slot_found:
    ; RAX = QUAD_SLOT* that completed
    ; Update state from LOADING to READY
    cmp [rax].QUAD_SLOT.state, BUF_STATE_LOADING
    jne iocp_loop                   ; Already changed (race condition?)
    
    mov [rax].QUAD_SLOT.state, BUF_STATE_READY
    
    ; Update metrics
    mov rdx, [rax].QUAD_SLOT.hdd_offset
    add [r15].INFINITY_STREAM.hdd_read_bytes, rdx
    
    ; Trigger immediate DMA to VRAM for this slot
    ; This minimizes latency between HDD read and GPU availability
    ; Phase 4 will handle the actual GPU DMA transfer
    
    jmp iocp_loop
    
iocp_error:
    ; Handle error or exit condition
    call GetLastError
    cmp eax, 735                    ; ERROR_ABANDONED_WAIT_0
    je iocp_exit
    jmp iocp_loop
    
iocp_exit:
    add rsp, 96
    pop r15 r14 r13 r12 rdi rsi rbx
    ret
INFINITY_ProcessIOCP ENDP

; =============================================================================
; INFINITY_HandleYTfnTrap
; Called when GPU hits YTFN_SENTINEL
; Decoder trap mechanism for lazy data materialization
;
; RCX = trapped address (YTFN_SENTINEL - layer_idx)
; Returns RAX = physical pointer after resolution
; =============================================================================
INFINITY_HandleYTfnTrap PROC FRAME
    push rbx r12
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    lea r12, g_infinity_stream
    
    ; Decode layer index from sentinel
    mov rax, YTFN_SENTINEL
    sub rax, rcx                    ; RAX = layer_idx
    mov rbx, rax                    ; RBX = layer_idx
    
    inc dword ptr [r12].INFINITY_STREAM.trap_resolved_count
    
stall_loop:
    ; Check if this layer is now in READY or COMPUTING state
    mov rcx, rbx
    xor edx, edx                    ; buffer_head (unused in check)
    call INFINITY_CheckQuadBuffer
    
    cmp rax, YTFN_SENTINEL
    jb trap_resolved                ; Got valid pointer (check LSB)
    
    ; Still not ready - yield and retry
    ; This implements the "stall until data is ready" mechanism
    call SwitchToThread             ; Yield CPU to other threads
    inc qword ptr [r12].INFINITY_STREAM.stall_cycles
    jmp stall_loop
    
trap_resolved:
    add rsp, 40
    pop r12 rbx
    ret
INFINITY_HandleYTfnTrap ENDP

; =============================================================================
; INFINITY_GetMetrics
; Returns performance statistics
;
; Returns RAX = hdd_read_bytes
;         RDX = dma_write_bytes
;         R8  = stall_cycles
;         R9D = trap_count
; =============================================================================
INFINITY_GetMetrics PROC
    lea rcx, g_infinity_stream
    mov rax, [rcx].INFINITY_STREAM.hdd_read_bytes
    mov rdx, [rcx].INFINITY_STREAM.dma_write_bytes
    mov r8, [rcx].INFINITY_STREAM.stall_cycles
    mov r9d, [rcx].INFINITY_STREAM.trap_count
    ret
INFINITY_GetMetrics ENDP

; =============================================================================
; INFINITY_ResetMetrics
; Clears all performance counters
; =============================================================================
INFINITY_ResetMetrics PROC
    lea rcx, g_infinity_stream
    mov [rcx].INFINITY_STREAM.hdd_read_bytes, 0
    mov [rcx].INFINITY_STREAM.dma_write_bytes, 0
    mov [rcx].INFINITY_STREAM.stall_cycles, 0
    mov [rcx].INFINITY_STREAM.trap_count, 0
    mov [rcx].INFINITY_STREAM.trap_resolved_count, 0
    ret
INFINITY_ResetMetrics ENDP

; =============================================================================
; INFINITY_GetSlotState
; Returns current state of a specific slot
;
; RCX = slot_index (0-3)
; Returns EAX = BUF_STATE_*
; =============================================================================
INFINITY_GetSlotState PROC
    lea rax, g_infinity_stream
    add rax, OFFSET INFINITY_STREAM.slots
    mov edx, SIZEOF QUAD_SLOT
    mul ecx
    add rax, rdx
    mov eax, [rax].QUAD_SLOT.state
    ret
INFINITY_GetSlotState ENDP

; =============================================================================
; INFINITY_GetSlotVramPtr
; Returns VRAM pointer for a specific slot
;
; RCX = slot_index (0-3)
; Returns RAX = VRAM pointer
; =============================================================================
INFINITY_GetSlotVramPtr PROC
    lea rax, g_infinity_stream
    add rax, OFFSET INFINITY_STREAM.slots
    mov edx, SIZEOF QUAD_SLOT
    mul ecx
    add rax, rdx
    mov rax, [rax].QUAD_SLOT.vram_ptr
    ret
INFINITY_GetSlotVramPtr ENDP

; =============================================================================
; INFINITY_GetSlotRamPtr
; Returns RAM pointer for a specific slot
;
; RCX = slot_index (0-3)
; Returns RAX = RAM pointer
; =============================================================================
INFINITY_GetSlotRamPtr PROC
    lea rax, g_infinity_stream
    add rax, OFFSET INFINITY_STREAM.slots
    mov edx, SIZEOF QUAD_SLOT
    mul ecx
    add rax, rdx
    mov rax, [rax].QUAD_SLOT.ram_ptr
    ret
INFINITY_GetSlotRamPtr ENDP

; =============================================================================
; INFINITY_Shutdown
; Closes all handles and frees memory
; =============================================================================
INFINITY_Shutdown PROC
    lea rax, g_infinity_stream
    
    ; Close file handle
    mov rcx, [rax].INFINITY_STREAM.hdd_file_handle
    call CloseHandle
    
    ; Close I/O Completion Port
    mov rcx, [rax].INFINITY_STREAM.dma_completion_port
    call CloseHandle
    
    ; Close all slot events
    mov rbx, rax
    add rbx, OFFSET INFINITY_STREAM.slots
    xor ecx, ecx
    
close_event_loop:
    cmp ecx, QUAD_BUFFER_COUNT
    jge shutdown_done
    
    mov rcx, [rbx].QUAD_SLOT.hEvent
    call CloseHandle
    
    add rbx, SIZEOF QUAD_SLOT
    inc ecx
    jmp close_event_loop
    
shutdown_done:
    xor eax, eax
    ret
INFINITY_Shutdown ENDP

END
 ; =============================================================================
; RawrXD_QuadBuffer_Validate.asm
; Runtime Validation and Benchmarking for QuadBuffer DMA System
; =============================================================================
; Tests and validates QuadBuffer functionality at runtime
; Measures throughput, latency, and buffer efficiency
; =============================================================================

OPTION CASEMAP:NONE
OPTION WIN64:3

INCLUDE \masm64\include64\masm64rt.inc
INCLUDE RawrXD_QuadBuffer_Integration.inc

; =============================================================================
; External Functions
; =============================================================================

EXTERN GetTickCount:PROC
EXTERN GetTickCount64:PROC
EXTERN QueryPerformanceCounter:PROC
EXTERN QueryPerformanceFrequency:PROC
EXTERN Sleep:PROC
EXTERN OutputDebugStringA:PROC

; =============================================================================
; Data Structures
; =============================================================================

VALIDATION_RESULT STRUCT
    test_name           DB 64 DUP(0)
    test_passed         DD ?
    elapsed_ms          DD ?
    throughput_mbps     DQ ?
    error_code          DD ?
VALIDATION_RESULT ENDS

BENCHMARK_STATS STRUCT
    total_tests         DD ?
    passed_tests        DD ?
    failed_tests        DD ?
    total_time_ms       DD ?
    avg_layer_time_ms   DD ?
    buffer_efficiency   DD ?
BENCHMARK_STATS ENDS

; =============================================================================
; Data Section
; =============================================================================

.DATA

align 64
g_validation_results    VALIDATION_RESULT 10 DUP(<>)
g_result_count          DD 0

align 64
g_benchmark_stats       BENCHMARK_STATS <>

align 64
g_perf_frequency        DQ 0

; Test strings
test_buffer_init        DB "QuadBuffer Initialization", 0
test_buffer_access      DB "Buffer Access (Optimal)", 0
test_buffer_trap        DB "YTFN Trap Handling", 0
test_buffer_rotation    DB "Buffer Rotation Cascade", 0
test_sequential_access  DB "Sequential Layer Access", 0
test_random_access      DB "Random Layer Access", 0
test_dma_throughput     DB "DMA Throughput Measurement", 0
test_efficiency         DB "Buffer Efficiency Check", 0

.CODE

; =============================================================================
; INITIALIZE_VALIDATION
; Setup validation environment
; =============================================================================
INITIALIZE_VALIDATION PROC FRAME
    push rbx
    .allocstack 8
    .endprolog
    
    ; Get performance counter frequency
    lea rcx, g_perf_frequency
    call QueryPerformanceFrequency
    
    ; Initialize result counter
    mov dword ptr g_result_count, 0
    
    ; Initialize stats
    mov dword ptr g_benchmark_stats.total_tests, 0
    mov dword ptr g_benchmark_stats.passed_tests, 0
    mov dword ptr g_benchmark_stats.failed_tests, 0
    mov dword ptr g_benchmark_stats.total_time_ms, 0
    
    pop rbx
    ret
INITIALIZE_VALIDATION ENDP

; =============================================================================
; TEST_BUFFER_INITIALIZATION
; Verify QuadBuffer initializes correctly
; =============================================================================
TEST_BUFFER_INITIALIZATION PROC FRAME
    push rbx r12 r13
    sub rsp, 40
    .allocstack 40
    .endprolog
    
    mov r12d, 1                     ; Assume pass
    
    ; Get result index
    mov eax, g_result_count
    mov rbx, rax
    imul rax, SIZEOF VALIDATION_RESULT
    lea r13, g_validation_results[rax]
    
    ; Record test name
    lea rax, test_buffer_init
    mov rcx, r13
    mov rdx, OFFSET VALIDATION_RESULT.test_name
    add rcx, rdx
    mov edx, 64
.copy_name:
    dec edx
    js .name_done
    mov al, byte ptr [rax]
    test al, al
    mov byte ptr [rcx], al
    jz .name_done
    inc rax
    inc rcx
    jmp .copy_name
    
.name_done:
    ; Start timer
    call GetTickCount
    mov r8d, eax
    
    ; Call initialization
    mov rcx, OFFSET INFINITY_InitializeStream
    call rcx
    test rax, rax
    jz .init_failed
    
    ; Stop timer
    call GetTickCount
    sub eax, r8d
    mov [r13].VALIDATION_RESULT.elapsed_ms, eax
    
    ; Check result
    mov eax, 1
    jmp .init_done
    
.init_failed:
    mov r12d, 0
    mov eax, 0
    
.init_done:
    mov [r13].VALIDATION_RESULT.test_passed, eax
    inc dword ptr g_result_count
    
    add rsp, 40
    pop r13 r12 rbx
    ret
TEST_BUFFER_INITIALIZATION ENDP

; =============================================================================
; TEST_SEQUENTIAL_ACCESS
; Test optimal case: sequential layer access
; Measures throughput for layers 0-99
; =============================================================================
TEST_SEQUENTIAL_ACCESS PROC FRAME
    push rbx r12 r13 r14
    sub rsp, 40
    .allocstack 40
    .endprolog
    
    mov r12d, 1                     ; Assume pass
    
    ; Get result index
    mov eax, g_result_count
    imul rax, SIZEOF VALIDATION_RESULT
    lea r13, g_validation_results[rax]
    
    ; Record test name
    lea rax, test_sequential_access
    mov rcx, r13
    mov rdx, OFFSET VALIDATION_RESULT.test_name
    add rcx, rdx
    mov edx, 64
.copy_seq_name:
    dec edx
    js .seq_name_done
    mov al, byte ptr [rax]
    mov byte ptr [rcx], al
    inc rax
    inc rcx
    jmp .copy_seq_name
    
.seq_name_done:
    ; Start timer
    call GetTickCount
    mov r14d, eax
    
    ; Access 100 layers sequentially
    xor ecx, ecx                    ; Layer counter
    
.seq_loop:
    cmp ecx, 100
    jge .seq_done
    
    ; Check buffer
    CHECK_BUFFER rcx, 0
    
    ; Simulate compute
    nop
    nop
    
    ; Notify completion
    ROTATE_AFTER_COMPUTE rcx
    
    inc ecx
    jmp .seq_loop
    
.seq_done:
    ; Stop timer
    call GetTickCount
    sub eax, r14d
    mov [r13].VALIDATION_RESULT.elapsed_ms, eax
    
    ; Calculate throughput
    ; Assume 1GB per layer = 100GB total
    ; Throughput = 100GB / elapsed_time
    mov edx, 100                    ; 100 GB
    mov ecx, eax                    ; elapsed ms
    test ecx, ecx
    jz .seq_calc_done
    
    mov eax, edx
    mov edx, 1024
    mul edx                         ; Convert GB to MB
    div ecx                         ; MB / ms = MB/s
    mov [r13].VALIDATION_RESULT.throughput_mbps, rax
    
.seq_calc_done:
    mov eax, 1
    mov [r13].VALIDATION_RESULT.test_passed, eax
    inc dword ptr g_result_count
    
    add rsp, 40
    pop r14 r13 r12 rbx
    ret
TEST_SEQUENTIAL_ACCESS ENDP

; =============================================================================
; TEST_TRAP_HANDLING
; Test YTFN_SENTINEL trap mechanism
; Verifies that traps are resolved correctly
; =============================================================================
TEST_TRAP_HANDLING PROC FRAME
    push rbx r12 r13
    sub rsp, 40
    .allocstack 40
    .endprolog
    
    mov r12d, 1                     ; Assume pass
    
    ; Get result index
    mov eax, g_result_count
    imul rax, SIZEOF VALIDATION_RESULT
    lea r13, g_validation_results[rax]
    
    ; Record test name
    lea rax, test_buffer_trap
    mov rcx, r13
    mov rdx, OFFSET VALIDATION_RESULT.test_name
    add rcx, rdx
    mov edx, 64
.copy_trap_name:
    dec edx
    js .trap_name_done
    mov al, byte ptr [rax]
    mov byte ptr [rcx], al
    inc rax
    inc rcx
    jmp .copy_trap_name
    
.trap_name_done:
    ; Start timer
    call GetTickCount
    mov r8d, eax
    
    ; Request a layer that's not ready
    mov rcx, 150                    ; Layer 150 (not in buffer)
    mov rdx, 0
    call INFINITY_CheckQuadBuffer
    
    ; Check if we got YTFN_SENTINEL
    cmp rax, YTFN_SENTINEL
    jne .trap_failed
    
    ; Handle the trap
    mov rcx, rax
    call INFINITY_HandleYTfnTrap
    
    ; After trap, should have valid pointer
    cmp rax, YTFN_SENTINEL
    jae .trap_failed
    
    ; Stop timer
    call GetTickCount
    sub eax, r8d
    mov [r13].VALIDATION_RESULT.elapsed_ms, eax
    
    mov eax, 1
    jmp .trap_done
    
.trap_failed:
    mov r12d, 0
    mov eax, 0
    
.trap_done:
    mov [r13].VALIDATION_RESULT.test_passed, eax
    inc dword ptr g_result_count
    
    add rsp, 40
    pop r13 r12 rbx
    ret
TEST_TRAP_HANDLING ENDP

; =============================================================================
; TEST_BUFFER_ROTATION
; Test buffer rotation cascade
; Verifies state transitions: EMPTY->LOADING->READY->COMPUTING->EMPTY
; =============================================================================
TEST_BUFFER_ROTATION PROC FRAME
    push rbx r12 r13 r14 r15
    sub rsp, 40
    .allocstack 40
    .endprolog
    
    mov r12d, 1                     ; Assume pass
    
    ; Get result index
    mov eax, g_result_count
    imul rax, SIZEOF VALIDATION_RESULT
    lea r13, g_validation_results[rax]
    
    ; Record test name
    lea rax, test_buffer_rotation
    mov rcx, r13
    mov rdx, OFFSET VALIDATION_RESULT.test_name
    add rcx, rdx
    mov edx, 64
.copy_rot_name:
    dec edx
    js .rot_name_done
    mov al, byte ptr [rax]
    mov byte ptr [rcx], al
    inc rax
    inc rcx
    jmp .copy_rot_name
    
.rot_name_done:
    ; Start timer
    call GetTickCount
    mov r14d, eax
    
    ; Get initial state
    xor ecx, ecx
    GET_SLOT_STATE ecx
    mov r15d, eax                   ; Save initial state
    
    ; Trigger rotations
    xor ecx, ecx                    ; Start at layer 0
.rot_loop:
    cmp ecx, 10
    jge .rot_done
    
    ROTATE_AFTER_COMPUTE rcx
    
    inc ecx
    jmp .rot_loop
    
.rot_done:
    ; Check final state
    xor ecx, ecx
    GET_SLOT_STATE ecx
    
    ; Should have changed
    cmp eax, r15d
    jne .rot_success
    
    mov r12d, 0
    
.rot_success:
    ; Stop timer
    call GetTickCount
    sub eax, r14d
    mov [r13].VALIDATION_RESULT.elapsed_ms, eax
    
    mov eax, r12d
    mov [r13].VALIDATION_RESULT.test_passed, eax
    inc dword ptr g_result_count
    
    add rsp, 40
    pop r15 r14 r13 r12 rbx
    ret
TEST_BUFFER_ROTATION ENDP

; =============================================================================
; TEST_BUFFER_EFFICIENCY
; Measure buffer utilization
; Reports percentage of slots in active use
; =============================================================================
TEST_BUFFER_EFFICIENCY PROC FRAME
    push rbx r12 r13 r14
    sub rsp, 40
    .allocstack 40
    .endprolog
    
    ; Get result index
    mov eax, g_result_count
    imul rax, SIZEOF VALIDATION_RESULT
    lea r13, g_validation_results[rax]
    
    ; Record test name
    lea rax, test_efficiency
    mov rcx, r13
    mov rdx, OFFSET VALIDATION_RESULT.test_name
    add rcx, rdx
    mov edx, 64
.copy_eff_name:
    dec edx
    js .eff_name_done
    mov al, byte ptr [rax]
    mov byte ptr [rcx], al
    inc rax
    inc rcx
    jmp .copy_eff_name
    
.eff_name_done:
    ; Count active slots
    xor r14d, r14d                  ; Active count
    xor ecx, ecx                    ; Slot counter
    
.eff_loop:
    cmp ecx, 4
    jge .eff_calc
    
    GET_SLOT_STATE ecx
    cmp eax, BUF_STATE_EMPTY
    je .eff_skip
    
    inc r14d                        ; Count this slot
    
.eff_skip:
    inc ecx
    jmp .eff_loop
    
.eff_calc:
    ; Efficiency = (active * 100) / 4
    mov eax, r14d
    mov ecx, 100
    mul ecx
    mov ecx, 4
    div ecx
    
    mov [r13].VALIDATION_RESULT.throughput_mbps, rax
    mov dword ptr [r13].VALIDATION_RESULT.test_passed, 1
    inc dword ptr g_result_count
    
    add rsp, 40
    pop r14 r13 r12 rbx
    ret
TEST_BUFFER_EFFICIENCY ENDP

; =============================================================================
; RUN_VALIDATION_SUITE
; Execute all validation tests
; =============================================================================
RUN_VALIDATION_SUITE PROC FRAME
    push rbx
    .allocstack 8
    .endprolog
    
    ; Initialize
    call INITIALIZE_VALIDATION
    
    ; Run tests
    call TEST_BUFFER_INITIALIZATION
    call TEST_SEQUENTIAL_ACCESS
    call TEST_TRAP_HANDLING
    call TEST_BUFFER_ROTATION
    call TEST_BUFFER_EFFICIENCY
    
    ; Summarize
    call REPORT_VALIDATION_RESULTS
    
    pop rbx
    ret
RUN_VALIDATION_SUITE ENDP

; =============================================================================
; REPORT_VALIDATION_RESULTS
; Display validation results
; =============================================================================
REPORT_VALIDATION_RESULTS PROC FRAME
    push rbx rcx rdx rax
    sub rsp, 40
    .allocstack 40
    .endprolog
    
    mov ecx, g_result_count
    xor ebx, ebx                    ; Pass count
    
.report_loop:
    cmp ecx, 0
    jle .report_done
    
    dec ecx
    mov rax, rcx
    imul rax, SIZEOF VALIDATION_RESULT
    lea rdx, g_validation_results[rax]
    
    ; Check if passed
    cmp dword ptr [rdx].VALIDATION_RESULT.test_passed, 1
    jne .report_fail
    
    inc ebx
    
.report_fail:
    jmp .report_loop
    
.report_done:
    ; Summary
    mov eax, g_result_count
    mov ecx, ebx
    
    ; Would output: "Passed X/Y tests"
    
    add rsp, 40
    pop rax rdx rcx rbx
    ret
REPORT_VALIDATION_RESULTS ENDP

; =============================================================================
; BENCHMARK_QUADBUFFER
; Full system benchmarking
; Measures performance across various scenarios
; =============================================================================
BENCHMARK_QUADBUFFER PROC FRAME
    push rbx r12 r13
    sub rsp, 40
    .allocstack 40
    .endprolog
    
    ; Test 1: Sequential throughput (optimal)
    mov ecx, 0
.bench_seq_loop:
    cmp ecx, 200
    jge .bench_seq_done
    
    CHECK_BUFFER rcx, 0
    ROTATE_AFTER_COMPUTE rcx
    
    inc ecx
    jmp .bench_seq_loop
    
.bench_seq_done:
    ; Test 2: Random access (worst case)
    mov ecx, 0
.bench_rand_loop:
    cmp ecx, 100
    jge .bench_rand_done
    
    ; Random layer = (ecx * 7) mod 800
    mov eax, ecx
    imul eax, 7
    mov edx, 800
    div edx
    mov ecx, edx                    ; edx = remainder
    
    CHECK_BUFFER rcx, 0
    
    inc ecx
    jmp .bench_rand_loop
    
.bench_rand_done:
    ; Test 3: Trap latency
    xor ecx, ecx
.bench_trap_loop:
    cmp ecx, 50
    jge .bench_trap_done
    
    ; Request layer that will trap
    mov eax, ecx
    add eax, 600                    ; Offset to ensure trap
    mov rcx, rax
    call INFINITY_CheckQuadBuffer
    
    ; If trap, resolve it
    cmp rax, YTFN_SENTINEL
    jb .bench_trap_skip
    
    mov rcx, rax
    call INFINITY_HandleYTfnTrap
    
.bench_trap_skip:
    inc ecx
    jmp .bench_trap_loop
    
.bench_trap_done:
    ; Collect final metrics
    PHASE5_COLLECT_METRICS
    ; RAX = HDD bytes
    ; RDX = DMA bytes
    ; R8 = stalls
    ; R9D = traps
    
    add rsp, 40
    pop r13 r12 rbx
    ret
BENCHMARK_QUADBUFFER ENDP

END
 ; =============================================================================
; RawrXD_Titan_Extensions.asm
; ADVANCED FEATURES 14-21: Titan Engine Integration
; Extends QuadBuffer DMA with Predictive Paging, DirectStorage, and Vulkan Sparse
; =============================================================================
; New Features:
;   14. BAR Zero-Copy (Re-BAR GPU memory mapping)
;   15. GPU NF4 Decompression + Live Theta Sync (006.1 rotary embeddings)
;   17. Vulkan Sparse Binding (Virtual VRAM expansion)
;   18. Attention-Drift Predictor (Non-linear layer prefetch)
;   19. DirectStorage Queue (Hardware-accelerated I/O)
;   20. Ghost Cache (Hierarchical L2 for frequently-accessed layers)
;   21. Dynamic Header Sieve (Runtime Safetensors/GGUF parsing)
; =============================================================================

OPTION CASEMAP:NONE
OPTION WIN64:3

INCLUDE \masm64\include64\masm64rt.inc
INCLUDE D:\rawrxd\include\RawrXD_QuadBuffer_Integration.inc

; =============================================================================
; TITAN CONSTANTS
; =============================================================================
GHOST_CACHE_SIZE        EQU 64              ; L2 cache for hot layers
PREDICTOR_LOOKAHEAD     EQU 8               ; Look-ahead depth
ATTENTION_VARIANCE_THRESHOLD EQU 3F800000h  ; 1.0f (IEEE-754)
DIRECTSTORAGE_QUEUE_SIZE EQU 128            ; Async request depth
SPARSE_PAGE_SIZE        EQU 010000h         ; 64KB sparse pages

; Feature flags (bitmask)
FEAT_BAR_ZERO_COPY      EQU 00000001h
FEAT_VULKAN_SPARSE      EQU 00000002h
FEAT_GPU_NF4            EQU 00000004h
FEAT_PREDICTOR          EQU 00000008h
FEAT_DIRECTSTORAGE      EQU 00000010h
FEAT_GHOST_CACHE        EQU 00000020h

; NF4 quantization table (4-bit float lookup)
NF4_SCALE               EQU 08h             ; Bits per weight

; =============================================================================
; DATA STRUCTURES
; =============================================================================

TITAN_CONFIG STRUCT
    rot_theta           DW  0461Ah          ; 006.1 rotary embedding (FP16)
    dma_priority        DD  1               ; 0=Idle, 1=Normal, 2=Realtime
    feature_mask        DD  03Fh            ; All features enabled
    stream_active       DB  1               ; Kill switch
    gpu_device_id       DD  0               ; Multi-GPU selector
    prefetch_depth      DD  PREDICTOR_LOOKAHEAD
    cache_policy        DD  0               ; 0=LRU, 1=Attention-weighted
    padding             DB  44 DUP(0)
TITAN_CONFIG ENDS

LAYER_METADATA STRUCT
    hdd_offset          DQ  ?               ; Physical offset in file
    compressed_size     DD  ?               ; Bytes on disk (NF4)
    uncompressed_size   DD  ?               ; Bytes after decompression
    quant_scale         REAL4 ?             ; Per-layer quantization scale
    access_count        DD  ?               ; Ghost cache frequency
    last_access_time    DQ  ?               ; TSC timestamp
LAYER_METADATA ENDS

GHOST_ENTRY STRUCT
    layer_idx           DD  ?
    ram_ptr             DQ  ?               ; Cached data pointer
    weight              DD  ?               ; LRU/frequency weight
    state               DD  ?               ; 0=Empty, 1=Valid, 2=Evicting
GHOST_ENTRY ENDS

PREDICTOR_STATE STRUCT
    attn_history        REAL4 16 DUP(?)    ; Rolling window of variance
    history_index       DD  ?
    predicted_stride    DD  1               ; Next layer delta (1=sequential, >1=jump)
    confidence          REAL4 ?             ; Prediction confidence (0.0-1.0)
    last_update_tsc     DQ  ?
PREDICTOR_STATE ENDS

DIRECTSTORAGE_REQUEST STRUCT
    layer_idx           DD  ?
    priority            DD  ?
    dest_ram_ptr        DQ  ?
    dest_vram_ptr       DQ  ?
    hdd_offset          DQ  ?
    size_bytes          DD  ?
    fence_value         DQ  ?
    status              DD  ?               ; 0=Pending, 1=Complete, 2=Error
DIRECTSTORAGE_REQUEST ENDS

TITAN_ENGINE STRUCT
    ; Core config
    config              TITAN_CONFIG <>
    
    ; Metadata tables
    layer_map           LAYER_METADATA 2048 DUP(<>)  ; 800B model = ~1600 layers
    
    ; Ghost cache (L2 for hot layers)
    ghost_cache         GHOST_ENTRY GHOST_CACHE_SIZE DUP(<>)
    ghost_lock          DQ  ?               ; SRWLock
    
    ; Attention predictor
    predictor           PREDICTOR_STATE <>
    
    ; DirectStorage queue
    dstorage_factory    DQ  ?               ; IDStorageFactory*
    dstorage_queue      DQ  ?               ; IDStorageQueue*
    dstorage_file       DQ  ?               ; IDStorageFile*
    dstorage_requests   DIRECTSTORAGE_REQUEST DIRECTSTORAGE_QUEUE_SIZE DUP(<>)
    dstorage_head       DD  ?
    dstorage_tail       DD  ?
    
    ; Vulkan sparse memory
    vk_device           DQ  ?               ; VkDevice
    vk_sparse_memory    DQ  ?               ; VkDeviceMemory (sparse)
    vk_bind_info_pool   DQ  ?               ; Pre-allocated bind structures
    vk_fence_pool       DQ  ?               ; Sync primitives
    
    ; GPU shader handles
    nf4_pipeline        DQ  ?               ; VkPipeline for decompression
    nf4_descriptor_set  DQ  ?               ; VkDescriptorSet
    cmd_buffer_pool     DQ  ?               ; Command buffer pool
    
    ; Performance metrics
    predictor_hits      DD  ?
    predictor_misses    DD  ?
    ghost_cache_hits    DD  ?
    ghost_cache_misses  DD  ?
    dstorage_throughput DQ  ?               ; Bytes/sec
TITAN_ENGINE ENDS

; =============================================================================
; DATA SECTION
; =============================================================================

.DATA

align 128
g_titan_engine      TITAN_ENGINE <>

; NF4 Dequantization Lookup Table (16 values)
align 64
nf4_lut             REAL4 -1.0, -0.6962, -0.5251, -0.3949, \
                          -0.2844, -0.1848, -0.0911, 0.0, \
                          0.0796, 0.1609, 0.2461, 0.3379, \
                          0.4407, 0.5626, 0.7230, 1.0

; Attention variance smoothing kernel (Gaussian-like)
align 32
smooth_kernel       REAL4 0.06, 0.09, 0.12, 0.15, 0.15, 0.12, 0.09, 0.06

.CODE

; =============================================================================
; TITAN_Initialize
; Extends INFINITY_InitializeStream with advanced features
; RCX = INFINITY_STREAM* (existing QuadBuffer)
; RDX = Feature mask (FEAT_*)
; Returns RAX = 0 on success, error code otherwise
; =============================================================================
PUBLIC TITAN_Initialize
TITAN_Initialize PROC FRAME
    push rbx rsi rdi r12 r13 r14 r15
    sub rsp, 128
    .allocstack 128
    .endprolog
    
    mov r12, rcx                        ; Save QuadBuffer handle
    mov r13d, edx                       ; Feature mask
    
    lea rdi, g_titan_engine
    mov [rdi].TITAN_ENGINE.config.feature_mask, r13d
    
    ; Initialize SRWLock for ghost cache
    lea rcx, [rdi].TITAN_ENGINE.ghost_lock
    call InitializeSRWLock
    
    ; Feature 21: Dynamic Header Sieve
    ; Scan model file header to build layer_map
    test r13d, 01h                      ; Check any feature enabled
    jz skip_header_sieve
    
    mov rcx, r12
    call TITAN_ParseModelHeader
    test rax, rax
    jnz error_exit
    
skip_header_sieve:
    ; Feature 19: Initialize DirectStorage
    test r13d, FEAT_DIRECTSTORAGE
    jz skip_directstorage
    
    call TITAN_InitDirectStorage
    test rax, rax
    jnz error_exit
    
skip_directstorage:
    ; Feature 17: Initialize Vulkan Sparse Binding
    test r13d, FEAT_VULKAN_SPARSE
    jz skip_vulkan
    
    call TITAN_InitVulkanSparse
    test rax, rax
    jnz error_exit
    
skip_vulkan:
    ; Feature 15: Compile NF4 Decompression Shader
    test r13d, FEAT_GPU_NF4
    jz skip_nf4
    
    call TITAN_CompileNF4Shader
    test rax, rax
    jnz error_exit
    
skip_nf4:
    ; Feature 18: Initialize Predictor State
    test r13d, FEAT_PREDICTOR
    jz skip_predictor
    
    ; Zero out attention history
    lea rcx, [rdi].TITAN_ENGINE.predictor
    xor eax, eax
    mov ecx, SIZEOF PREDICTOR_STATE
    rep stosb
    
    ; Set initial stride to 1 (sequential)
    mov [rdi].TITAN_ENGINE.predictor.predicted_stride, 1
    
skip_predictor:
    xor eax, eax                        ; Success
    jmp done
    
error_exit:
    ; Return error code already in RAX
    
done:
    add rsp, 128
    pop r15 r14 r13 r12 rdi rsi rbx
    ret
TITAN_Initialize ENDP

; =============================================================================
; TITAN_ParseModelHeader (Feature 21: Dynamic Header Sieve)
; Reverse-engineers Safetensors/GGUF header to populate layer_map
; RCX = INFINITY_STREAM*
; Returns RAX = 0 on success
; =============================================================================
TITAN_ParseModelHeader PROC FRAME
    push rbx rsi rdi r12 r13
    sub rsp, 65536 + 32                 ; 64KB buffer + shadow space
    .allocstack 65568
    .endprolog
    
    mov r12, rcx                        ; QuadBuffer handle
    lea r13, [rsp + 32]                 ; Header buffer
    
    ; Read first 64KB of model file
    mov rcx, [r12].INFINITY_STREAM.hdd_file_handle
    mov rdx, r13                        ; Buffer
    mov r8d, 65536                      ; Size
    lea r9, [rsp + 24]                  ; BytesRead
    xor eax, eax
    mov qword ptr [rsp], rax            ; NULL overlapped
    call ReadFile
    test eax, eax
    jz parse_error
    
    ; Detect format: Safetensors vs GGUF
    mov eax, dword ptr [r13]            ; First 4 bytes
    cmp eax, 'FUGG'                     ; "GGUF" magic
    je parse_gguf
    
    ; Assume Safetensors (JSON header)
parse_safetensors:
    ; Look for "data_offsets": [ pattern
    lea rsi, r13
    mov ecx, 65536
    
find_offsets:
    cmp byte ptr [rsi], '"'
    jne next_byte
    
    ; Check for "data_offsets"
    mov eax, dword ptr [rsi + 1]
    cmp eax, 'atad'                     ; "data"
    jne next_byte
    
    ; Found it - parse JSON array
    ; (Simplified: real implementation needs full JSON parser)
    ; Extract [start, end] pairs and populate layer_map
    
    lea rdi, g_titan_engine.layer_map
    xor ebx, ebx                        ; Layer index
    
parse_offsets_loop:
    ; Skip to next number
    call SkipToDigit
    test rax, rax
    jz parse_done
    
    ; Parse start offset
    call ParseDecimalNumber
    mov [rdi + rbx*SIZEOF LAYER_METADATA].LAYER_METADATA.hdd_offset, rax
    
    ; Parse end offset
    call SkipToDigit
    call ParseDecimalNumber
    
    ; Calculate size
    sub rax, [rdi + rbx*SIZEOF LAYER_METADATA].LAYER_METADATA.hdd_offset
    mov [rdi + rbx*SIZEOF LAYER_METADATA].LAYER_METADATA.compressed_size, eax
    mov [rdi + rbx*SIZEOF LAYER_METADATA].LAYER_METADATA.uncompressed_size, eax
    
    ; Default scale
    mov dword ptr [rdi + rbx*SIZEOF LAYER_METADATA].LAYER_METADATA.quant_scale, 3F800000h ; 1.0f
    
    inc ebx
    cmp ebx, 2048
    jl parse_offsets_loop
    
    jmp parse_done
    
next_byte:
    inc rsi
    loop find_offsets
    jmp parse_done
    
parse_gguf:
    ; GGUF format: Binary header with tensor metadata
    ; Format: [magic:4][version:4][tensor_count:8][metadata_count:8]
    ; Followed by tensor descriptors
    
    mov rbx, qword ptr [r13 + 12]       ; Tensor count
    lea rsi, [r13 + 20]                 ; First tensor descriptor
    lea rdi, g_titan_engine.layer_map
    xor r14, r14                        ; Layer index
    
parse_gguf_loop:
    ; Read tensor name length
    movzx ecx, word ptr [rsi]
    lea rsi, [rsi + 2 + rcx]            ; Skip name
    
    ; Read dimensions (4 x uint32)
    add rsi, 16
    
    ; Read type (uint32) and offset (uint64)
    mov eax, dword ptr [rsi]            ; Type
    mov r8, qword ptr [rsi + 8]         ; Offset
    
    mov [rdi + r14*SIZEOF LAYER_METADATA].LAYER_METADATA.hdd_offset, r8
    
    ; Calculate size from type (simplified)
    ; Type 0=F32, 1=F16, 2=Q4_0, etc.
    mov [rdi + r14*SIZEOF LAYER_METADATA].LAYER_METADATA.compressed_size, 1000000h
    
    add rsi, 16
    inc r14
    cmp r14, rbx
    jl parse_gguf_loop
    
parse_done:
    xor eax, eax                        ; Success
    jmp done
    
parse_error:
    mov eax, 1                          ; Error
    
done:
    add rsp, 65568
    pop r13 r12 rdi rsi rbx
    ret
TITAN_ParseModelHeader ENDP

; =============================================================================
; TITAN_UpdatePredictor (Feature 18: Attention-Drift Predictor)
; Analyzes GPU attention variance to predict next layer access pattern
; RCX = Current layer index
; RDX = GPU attention stats buffer (VRAM mapped)
; Returns RAX = Predicted next layer (may be non-sequential)
; =============================================================================
PUBLIC TITAN_UpdatePredictor
TITAN_UpdatePredictor PROC FRAME
    push rbx rsi rdi r12 r13 r14 r15
    sub rsp, 64
    .allocstack 64
    .endprolog
    
    mov r12, rcx                        ; Current layer
    mov r13, rdx                        ; Attention stats
    
    lea rdi, g_titan_engine.predictor
    
    ; Read attention variance from GPU stats buffer
    ; Layout: [avg_attn:f32][variance:f32][max_attn:f32][entropy:f32]
    vmovss xmm0, real4 ptr [r13 + 4]    ; variance
    
    ; Update rolling history
    mov eax, [rdi].PREDICTOR_STATE.history_index
    vmovss real4 ptr [rdi + rax*4].PREDICTOR_STATE.attn_history, xmm0
    
    inc eax
    and eax, 0Fh                        ; Wrap at 16
    mov [rdi].PREDICTOR_STATE.history_index, eax
    
    ; Calculate smoothed variance using kernel
    vxorps ymm1, ymm1, ymm1             ; Accumulator
    lea rsi, smooth_kernel
    xor ecx, ecx
    
smooth_loop:
    vmovss xmm2, real4 ptr [rdi + rcx*4].PREDICTOR_STATE.attn_history
    vmovss xmm3, real4 ptr [rsi + rcx*4]
    vmulss xmm2, xmm2, xmm3
    vaddss xmm1, xmm1, xmm2
    inc ecx
    cmp ecx, 8
    jl smooth_loop
    
    ; Compare smoothed variance against threshold
    vucomiss xmm1, real4 ptr [ATTENTION_VARIANCE_THRESHOLD]
    jb predict_linear
    
predict_jump:
    ; High variance: Context is non-linear (e.g., retrieval, attention loop)
    ; Predict a JUMP to a distant layer based on attention focus
    
    ; Simple heuristic: Look at max_attn position
    vmovss xmm0, real4 ptr [r13 + 8]    ; max_attn score
    vcvtss2si eax, xmm0
    and eax, 3Fh                        ; Modulo 64 (max lookahead)
    add eax, 8                          ; Jump ahead 8-72 layers
    
    mov [rdi].PREDICTOR_STATE.predicted_stride, eax
    mov dword ptr [rdi].PREDICTOR_STATE.confidence, 3F4CCCCDh ; 0.8f
    
    jmp predict_done
    
predict_linear:
    ; Low variance: Sequential processing
    mov [rdi].PREDICTOR_STATE.predicted_stride, 1
    mov dword ptr [rdi].PREDICTOR_STATE.confidence, 3F800000h ; 1.0f
    
predict_done:
    ; Calculate predicted layer = current + stride
    mov eax, [rdi].PREDICTOR_STATE.predicted_stride
    add rax, r12                        ; Next layer
    
    ; Trigger prefetch for predicted layer
    push rax
    mov rcx, rax
    call TITAN_PrefetchLayer
    pop rax
    
    add rsp, 64
    pop r15 r14 r13 r12 rdi rsi rbx
    ret
TITAN_UpdatePredictor ENDP

; =============================================================================
; TITAN_PrefetchLayer (Feature 19: DirectStorage Integration)
; Enqueues a layer for async DMA from HDD
; RCX = Layer index
; =============================================================================
TITAN_PrefetchLayer PROC FRAME
    push rbx rsi rdi r12 r13
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    mov r12, rcx                        ; Layer index
    
    ; Check if DirectStorage is enabled
    lea rdi, g_titan_engine
    test [rdi].TITAN_ENGINE.config.feature_mask, FEAT_DIRECTSTORAGE
    jz fallback_readfile
    
    ; Get free slot in request queue
    mov eax, [rdi].TITAN_ENGINE.dstorage_tail
    mov ebx, [rdi].TITAN_ENGINE.dstorage_head
    inc eax
    and eax, DIRECTSTORAGE_QUEUE_SIZE - 1
    cmp eax, ebx
    je queue_full
    
    ; Fill request structure
    imul rsi, rax, SIZEOF DIRECTSTORAGE_REQUEST
    lea rsi, [rdi + rsi].TITAN_ENGINE.dstorage_requests
    
    mov [rsi].DIRECTSTORAGE_REQUEST.layer_idx, r12d
    mov [rsi].DIRECTSTORAGE_REQUEST.priority, 1
    
    ; Lookup metadata
    imul rbx, r12, SIZEOF LAYER_METADATA
    lea rbx, [rdi + rbx].TITAN_ENGINE.layer_map
    
    mov r8, [rbx].LAYER_METADATA.hdd_offset
    mov [rsi].DIRECTSTORAGE_REQUEST.hdd_offset, r8
    
    mov r8d, [rbx].LAYER_METADATA.compressed_size
    mov [rsi].DIRECTSTORAGE_REQUEST.size_bytes, r8d
    
    ; Allocate destination RAM buffer (from arena or ghost cache)
    call TITAN_AllocateGhostSlot
    mov [rsi].DIRECTSTORAGE_REQUEST.dest_ram_ptr, rax
    
    ; Submit to DirectStorage queue
    ; (Requires IDStorageQueue::EnqueueRequest COM call)
    ; Simplified: Queue for background thread processing
    
    mov [rsi].DIRECTSTORAGE_REQUEST.status, 0 ; Pending
    
    mov eax, [rdi].TITAN_ENGINE.dstorage_tail
    inc eax
    and eax, DIRECTSTORAGE_QUEUE_SIZE - 1
    mov [rdi].TITAN_ENGINE.dstorage_tail, eax
    
    jmp done
    
queue_full:
    ; Fallback to synchronous read if queue full
    
fallback_readfile:
    ; Use original QuadBuffer mechanism
    mov rcx, r12
    ; call INFINITY_TriggerPrefetch (from QuadBuffer)
    
done:
    add rsp, 32
    pop r13 r12 rdi rsi rbx
    ret
TITAN_PrefetchLayer ENDP

; =============================================================================
; TITAN_CheckGhostCache (Feature 20: Ghost Cache L2)
; Checks if layer is cached in RAM before triggering HDD I/O
; RCX = Layer index
; Returns RAX = RAM pointer or 0 if miss
; =============================================================================
PUBLIC TITAN_CheckGhostCache
TITAN_CheckGhostCache PROC FRAME
    push rbx rsi rdi r12
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    mov r12, rcx                        ; Layer index
    
    lea rdi, g_titan_engine
    
    ; Acquire read lock
    lea rcx, [rdi].TITAN_ENGINE.ghost_lock
    call AcquireSRWLockShared
    
    ; Linear search through ghost cache
    lea rsi, [rdi].TITAN_ENGINE.ghost_cache
    xor ebx, ebx
    
search_loop:
    mov eax, [rsi + rbx*SIZEOF GHOST_ENTRY].GHOST_ENTRY.layer_idx
    cmp eax, r12d
    je found_entry
    
    inc ebx
    cmp ebx, GHOST_CACHE_SIZE
    jl search_loop
    
    ; Miss
    inc [rdi].TITAN_ENGINE.ghost_cache_misses
    xor eax, eax
    jmp done
    
found_entry:
    ; Hit - return pointer and update LRU weight
    inc [rdi].TITAN_ENGINE.ghost_cache_hits
    
    mov rax, [rsi + rbx*SIZEOF GHOST_ENTRY].GHOST_ENTRY.ram_ptr
    inc [rsi + rbx*SIZEOF GHOST_ENTRY].GHOST_ENTRY.weight
    
    ; Update access time
    rdtsc
    shl rdx, 32
    or rax, rdx
    lea r8, [rdi].TITAN_ENGINE.layer_map
    imul r9, r12, SIZEOF LAYER_METADATA
    mov [r8 + r9].LAYER_METADATA.last_access_time, rax
    
    mov rax, [rsi + rbx*SIZEOF GHOST_ENTRY].GHOST_ENTRY.ram_ptr
    
done:
    ; Release lock
    lea rcx, [rdi].TITAN_ENGINE.ghost_lock
    call ReleaseSRWLockShared
    
    add rsp, 32
    pop r12 rdi rsi rbx
    ret
TITAN_CheckGhostCache ENDP

; =============================================================================
; TITAN_SyncLiveTheta (Feature 15: GPU Live Parameter Sync)
; Updates rot_theta in GPU shader push constants
; RCX = New theta value (FP16)
; =============================================================================
PUBLIC TITAN_SyncLiveTheta
TITAN_SyncLiveTheta PROC FRAME
    push rbx rsi rdi
    sub rsp, 32
    .allocstack 32
    .endprolog
    
    mov bx, cx                          ; Save FP16 value
    
    lea rdi, g_titan_engine
    mov [rdi].TITAN_ENGINE.config.rot_theta, bx
    
    ; Check if Vulkan NF4 shader is active
    test [rdi].TITAN_ENGINE.config.feature_mask, FEAT_GPU_NF4
    jz skip_vulkan_update
    
    ; Update push constant in command buffer
    ; (Requires vkCmdPushConstants - simplified here)
    ; mov rcx, [rdi].TITAN_ENGINE.cmd_buffer_pool
    ; lea rdx, [rdi].TITAN_ENGINE.config.rot_theta
    ; call vkCmdPushConstants
    
skip_vulkan_update:
    add rsp, 32
    pop rdi rsi rbx
    ret
TITAN_SyncLiveTheta ENDP

; =============================================================================
; Helper Functions (Stubs for complex subsystems)
; =============================================================================

TITAN_InitDirectStorage PROC
    ; Initialize DirectStorage factory and queue
    ; (Requires dstorage.lib and COM interfaces)
    xor eax, eax
    ret
TITAN_InitDirectStorage ENDP

TITAN_InitVulkanSparse PROC
    ; Create Vulkan device with sparse binding feature
    ; Allocate VkDeviceMemory with SPARSE_BINDING flag
    xor eax, eax
    ret
TITAN_InitVulkanSparse ENDP

TITAN_CompileNF4Shader PROC
    ; Compile GLSL shader to SPIR-V
    ; Create VkPipeline for compute shader
    xor eax, eax
    ret
TITAN_CompileNF4Shader ENDP

TITAN_AllocateGhostSlot PROC
    ; VirtualAlloc(NULL, 1GB, MEM_COMMIT|MEM_RESERVE, PAGE_READWRITE)
    sub rsp, 40
    xor ecx, ecx
    mov rdx, 40000000h
    mov r8d, 3000h
    mov r9d, 4
    call QWORD PTR [__imp_VirtualAlloc]
    add rsp, 40
    ret
TITAN_AllocateGhostSlot ENDP

SkipToDigit PROC
    ; Scan forward in RCX char* to first ASCII digit '0'-'9'
    ; Returns RAX = pointer to digit, or NULL if end-of-string first
    mov rax, rcx
@@ssd_loop:
    movzx edx, byte ptr [rax]
    test dl, dl
    jz @@ssd_null
    cmp dl, '0'
    jb @@ssd_next
    cmp dl, '9'
    jbe @@ssd_found
@@ssd_next:
    inc rax
    jmp @@ssd_loop
@@ssd_null:
    xor rax, rax
@@ssd_found:
    ret
SkipToDigit ENDP

ParseDecimalNumber PROC
    ; Parse ASCII decimal digits at RCX char*
    ; Returns RAX = uint64 value
    xor rax, rax
    xor edx, edx
@@pdn_loop:
    movzx edx, byte ptr [rcx]
    cmp dl, '0'
    jb @@pdn_done
    cmp dl, '9'
    ja @@pdn_done
    sub dl, '0'
    imul rax, rax, 10
    add rax, rdx
    inc rcx
    jmp @@pdn_loop
@@pdn_done:
    ret
ParseDecimalNumber ENDP

AcquireSRWLockShared PROC
    JMP QWORD PTR [__imp_AcquireSRWLockShared]
AcquireSRWLockShared ENDP

ReleaseSRWLockShared PROC
    JMP QWORD PTR [__imp_ReleaseSRWLockShared]
ReleaseSRWLockShared ENDP

END
 ; MCP Transport Hook Assembly - MASM64
; Raw buffer manipulation for MCP message interception
; Provides trampoline stubs that preserve all registers before calling C++ handlers

.code

; External C++ handlers
EXTERN MCP_ReadMessageHook:PROC
EXTERN MCP_WriteMessageHook:PROC
EXTERN MCP_OnSocketDataHook:PROC
EXTERN MCP_WebSocketFrameHook:PROC

; Storage for original function addresses (filled by hook installer)
PUBLIC g_OrigReadMessage
PUBLIC g_OrigWriteMessage
PUBLIC g_OrigOnSocketData
PUBLIC g_OrigWebSocketFrame

.data
ALIGN 8
g_OrigReadMessage      QWORD 0
g_OrigWriteMessage     QWORD 0
g_OrigOnSocketData     QWORD 0
g_OrigWebSocketFrame   QWORD 0

; Hook enable flags (atomic, can be toggled at runtime)
PUBLIC g_EnableReadHook
PUBLIC g_EnableWriteHook
PUBLIC g_EnableSocketHook
PUBLIC g_EnableWSHook

g_EnableReadHook       DWORD 1
g_EnableWriteHook      DWORD 1
g_EnableSocketHook     DWORD 1
g_EnableWSHook         DWORD 1

.code

;------------------------------------------------------------------------------
; ReadMessage Trampoline
; RCX = buffer pointer, RDX = length
; Captures raw MCP frame BEFORE any JS parsing occurs
;------------------------------------------------------------------------------
PUBLIC MCP_ReadMessage_Trampoline
MCP_ReadMessage_Trampoline PROC
    ; Check if hook is enabled
    mov     eax, [g_EnableReadHook]
    test    eax, eax
    jz      @F_bypass_read
    
    ; Save all volatile registers (Win64 ABI)
    push    rbx
    push    rsi
    push    rdi
    push    r8
    push    r9
    push    r10
    push    r11
    push    r12
    push    r13
    push    r14
    push    r15
    sub     rsp, 40h                    ; Shadow space + alignment
    
    ; Save original parameters
    mov     rbx, rcx                    ; buffer
    mov     rsi, rdx                    ; length
    
    ; Call C++ handler: MCP_ReadMessageHook(buffer, length)
    ; RCX = buffer (already set)
    ; RDX = length (already set)
    call    MCP_ReadMessageHook
    
    ; Restore original parameters for original function
    mov     rcx, rbx
    mov     rdx, rsi
    
    add     rsp, 40h
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     r11
    pop     r10
    pop     r9
    pop     r8
    pop     rdi
    pop     rsi
    pop     rbx
    
@F_bypass_read:
    ; Jump to original function
    mov     rax, [g_OrigReadMessage]
    test    rax, rax
    jz      @F_null_read
    jmp     rax
    
@F_null_read:
    ; No original function - just return
    xor     eax, eax
    ret
MCP_ReadMessage_Trampoline ENDP

;------------------------------------------------------------------------------
; WriteMessage Trampoline
; RCX = buffer pointer, RDX = length
; Captures outgoing MCP response/notification frames
;------------------------------------------------------------------------------
PUBLIC MCP_WriteMessage_Trampoline
MCP_WriteMessage_Trampoline PROC
    mov     eax, [g_EnableWriteHook]
    test    eax, eax
    jz      @F_bypass_write
    
    push    rbx
    push    rsi
    push    rdi
    push    r8
    push    r9
    push    r10
    push    r11
    push    r12
    push    r13
    push    r14
    push    r15
    sub     rsp, 40h
    
    mov     rbx, rcx
    mov     rsi, rdx
    
    ; Call C++ handler
    call    MCP_WriteMessageHook
    
    mov     rcx, rbx
    mov     rdx, rsi
    
    add     rsp, 40h
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     r11
    pop     r10
    pop     r9
    pop     r8
    pop     rdi
    pop     rsi
    pop     rbx
    
@F_bypass_write:
    mov     rax, [g_OrigWriteMessage]
    test    rax, rax
    jz      @F_null_write
    jmp     rax
    
@F_null_write:
    xor     eax, eax
    ret
MCP_WriteMessage_Trampoline ENDP

;------------------------------------------------------------------------------
; OnSocketData Trampoline
; RCX = data buffer, RDX = length, R8 = SOCKET handle
; Captures raw TCP/IPC socket data before MCP framing
;------------------------------------------------------------------------------
PUBLIC MCP_OnSocketData_Trampoline
MCP_OnSocketData_Trampoline PROC
    mov     eax, [g_EnableSocketHook]
    test    eax, eax
    jz      @F_bypass_socket
    
    push    rbx
    push    rsi
    push    rdi
    push    r8
    push    r9
    push    r10
    push    r11
    push    r12
    push    r13
    push    r14
    push    r15
    sub     rsp, 40h
    
    ; Save all three parameters
    mov     rbx, rcx                    ; data
    mov     rsi, rdx                    ; length
    mov     rdi, r8                     ; socket
    
    ; Call C++ handler: MCP_OnSocketDataHook(data, length, socket)
    ; RCX, RDX, R8 already set
    call    MCP_OnSocketDataHook
    
    ; Restore parameters
    mov     rcx, rbx
    mov     rdx, rsi
    mov     r8, rdi
    
    add     rsp, 40h
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     r11
    pop     r10
    pop     r9
    pop     r8
    pop     rdi
    pop     rsi
    pop     rbx
    
@F_bypass_socket:
    mov     rax, [g_OrigOnSocketData]
    test    rax, rax
    jz      @F_null_socket
    jmp     rax
    
@F_null_socket:
    xor     eax, eax
    ret
MCP_OnSocketData_Trampoline ENDP

;------------------------------------------------------------------------------
; WebSocket Frame Trampoline
; RCX = frame buffer, RDX = frame length, R8 = opcode (text=1, binary=2, etc.)
; Captures WebSocket frames for WS-based MCP transport
;------------------------------------------------------------------------------
PUBLIC MCP_WebSocketFrame_Trampoline
MCP_WebSocketFrame_Trampoline PROC
    mov     eax, [g_EnableWSHook]
    test    eax, eax
    jz      @F_bypass_ws
    
    push    rbx
    push    rsi
    push    rdi
    push    r8
    push    r9
    push    r10
    push    r11
    push    r12
    push    r13
    push    r14
    push    r15
    sub     rsp, 40h
    
    mov     rbx, rcx                    ; frame
    mov     rsi, rdx                    ; length
    mov     rdi, r8                     ; opcode
    
    ; Call C++ handler
    call    MCP_WebSocketFrameHook
    
    mov     rcx, rbx
    mov     rdx, rsi
    mov     r8, rdi
    
    add     rsp, 40h
    pop     r15
    pop     r14
    pop     r13
    pop     r12
    pop     r11
    pop     r10
    pop     r9
    pop     r8
    pop     rdi
    pop     rsi
    pop     rbx
    
@F_bypass_ws:
    mov     rax, [g_OrigWebSocketFrame]
    test    rax, rax
    jz      @F_null_ws
    jmp     rax
    
@F_null_ws:
    xor     eax, eax
    ret
MCP_WebSocketFrame_Trampoline ENDP

;------------------------------------------------------------------------------
; Buffer Hex Dump Helper (for debugging)
; RCX = buffer, RDX = length, R8 = output buffer
; Returns number of chars written in RAX
;------------------------------------------------------------------------------
PUBLIC MCP_HexDumpBuffer
MCP_HexDumpBuffer PROC
    push    rbx
    push    rsi
    push    rdi
    
    mov     rsi, rcx                    ; source buffer
    mov     rbx, rdx                    ; length
    mov     rdi, r8                     ; output buffer
    xor     rax, rax                    ; chars written
    
    test    rbx, rbx
    jz      @F_hex_done
    
@F_hex_loop:
    movzx   ecx, BYTE PTR [rsi]
    
    ; High nibble
    mov     edx, ecx
    shr     edx, 4
    add     edx, '0'
    cmp     edx, '9'
    jbe     @F_high_ok
    add     edx, 7                      ; A-F offset
@F_high_ok:
    mov     BYTE PTR [rdi], dl
    inc     rdi
    inc     rax
    
    ; Low nibble
    mov     edx, ecx
    and     edx, 0Fh
    add     edx, '0'
    cmp     edx, '9'
    jbe     @F_low_ok
    add     edx, 7
@F_low_ok:
    mov     BYTE PTR [rdi], dl
    inc     rdi
    inc     rax
    
    ; Space separator
    mov     BYTE PTR [rdi], ' '
    inc     rdi
    inc     rax
    
    inc     rsi
    dec     rbx
    jnz     @F_hex_loop
    
@F_hex_done:
    ; Null terminate
    mov     BYTE PTR [rdi], 0
    
    pop     rdi
    pop     rsi
    pop     rbx
    ret
MCP_HexDumpBuffer ENDP

;------------------------------------------------------------------------------
; Content-Length Parser (for stdio MCP transport)
; RCX = buffer start, RDX = buffer length
; Returns content-length value in RAX, or -1 if not found
;------------------------------------------------------------------------------
PUBLIC MCP_ParseContentLength
MCP_ParseContentLength PROC
    push    rbx
    push    rsi
    push    rdi
    
    mov     rsi, rcx                    ; buffer
    mov     rbx, rdx                    ; length
    
    ; Search for "Content-Length: "
    mov     rax, -1                     ; default: not found
    cmp     rbx, 16
    jb      @F_cl_done
    
    xor     rdi, rdi                    ; offset
    
@F_cl_search:
    cmp     rdi, rbx
    jae     @F_cl_done
    
    ; Check for 'C'
    movzx   ecx, BYTE PTR [rsi + rdi]
    cmp     cl, 'C'
    jne     @F_cl_next
    
    ; Check "Content-Length: " (16 chars)
    lea     rcx, [rsi + rdi]
    push    rax
    
    ; Quick check: "Content-Length:"
    mov     eax, DWORD PTR [rcx]
    cmp     eax, 'tnoC'                 ; "Cont" little-endian
    pop     rax
    jne     @F_cl_next
    
    ; Found potential match - skip header and parse number
    add     rdi, 16
    xor     rax, rax
    
@F_cl_parse:
    cmp     rdi, rbx
    jae     @F_cl_done
    
    movzx   ecx, BYTE PTR [rsi + rdi]
    
    ; Skip whitespace
    cmp     cl, ' '
    je      @F_cl_skip
    cmp     cl, 09h                     ; tab
    je      @F_cl_skip
    
    ; Check for digit
    cmp     cl, '0'
    jb      @F_cl_done
    cmp     cl, '9'
    ja      @F_cl_done
    
    ; Accumulate: rax = rax * 10 + digit
    imul    rax, 10
    sub     cl, '0'
    movzx   ecx, cl
    add     rax, rcx
    
@F_cl_skip:
    inc     rdi
    jmp     @F_cl_parse
    
@F_cl_next:
    inc     rdi
    jmp     @F_cl_search
    
@F_cl_done:
    pop     rdi
    pop     rsi
    pop     rbx
    ret
MCP_ParseContentLength ENDP

;------------------------------------------------------------------------------
; JSON-RPC Method Extractor
; RCX = JSON buffer, RDX = length, R8 = output buffer (max 64 chars)
; Returns method length in RAX, or 0 if not found
;------------------------------------------------------------------------------
PUBLIC MCP_ExtractMethod
MCP_ExtractMethod PROC
    push    rbx
    push    rsi
    push    rdi
    push    r12
    
    mov     rsi, rcx                    ; JSON buffer
    mov     rbx, rdx                    ; length
    mov     rdi, r8                     ; output
    mov     r12, 64                     ; max output length
    
    xor     rax, rax
    cmp     rbx, 10
    jb      @F_method_done
    
    xor     rcx, rcx                    ; offset
    
@F_method_search:
    cmp     rcx, rbx
    jae     @F_method_done
    
    ; Look for "method"
    movzx   edx, BYTE PTR [rsi + rcx]
    cmp     dl, 'm'
    jne     @F_method_skip
    
    ; Check "method": (7 chars + colon)
    lea     rdx, [rsi + rcx]
    cmp     DWORD PTR [rdx], 'htem'     ; "meth"
    jne     @F_method_skip
    cmp     WORD PTR [rdx + 4], 'do'    ; "od"
    jne     @F_method_skip
    
    ; Found "method" - skip to value
    add     rcx, 6
    
@F_method_find_quote:
    cmp     rcx, rbx
    jae     @F_method_done
    movzx   edx, BYTE PTR [rsi + rcx]
    inc     rcx
    cmp     dl, '"'
    jne     @F_method_find_quote
    
    ; Now at start of method string - copy until closing quote
@F_method_copy:
    cmp     rcx, rbx
    jae     @F_method_done
    cmp     rax, r12
    jae     @F_method_done
    
    movzx   edx, BYTE PTR [rsi + rcx]
    cmp     dl, '"'
    je      @F_method_terminate
    
    mov     BYTE PTR [rdi + rax], dl
    inc     rax
    inc     rcx
    jmp     @F_method_copy
    
@F_method_terminate:
    mov     BYTE PTR [rdi + rax], 0
    jmp     @F_method_done
    
@F_method_skip:
    inc     rcx
    jmp     @F_method_search
    
@F_method_done:
    pop     r12
    pop     rdi
    pop     rsi
    pop     rbx
    ret
MCP_ExtractMethod ENDP

END
 ; ============================================================================
; RawrXD Codebase Audit System — Pure x64 MASM
; Full project audit: file scan, quality/security/performance analysis.
; Full production: FindFirstFile/FindNextFile, ReadFile, pattern scan.
; ============================================================================
OPTION CASEMAP:NONE

PUBLIC CodebaseAuditSystem_Create
PUBLIC CodebaseAuditSystem_initialize
PUBLIC CodebaseAuditSystem_shutdown
PUBLIC CodebaseAuditSystem_audit_full_project
PUBLIC CodebaseAuditSystem_analyze_source_file
PUBLIC CodebaseAuditSystem_get_audit_statistics

.CODE
EXTERN CreateMutexW:PROC
EXTERN WaitForSingleObject:PROC
EXTERN ReleaseMutex:PROC
EXTERN CloseHandle:PROC
EXTERN CreateFileA:PROC
EXTERN ReadFile:PROC
EXTERN GetFileSize:PROC
EXTERN FindFirstFileA:PROC
EXTERN FindNextFileA:PROC
EXTERN FindClose:PROC
EXTERN GetTickCount64:PROC
EXTERN lstrlenA:PROC
EXTERN lstrcpyA:PROC

GENERIC_READ     EQU 80000000h
FILE_SHARE_READ  EQU 1
OPEN_EXISTING    EQU 3
FILE_ATTRIBUTE_NORMAL EQU 80h
INVALID_HANDLE_VALUE EQU -1
MAX_PATH         EQU 260

; WIN32_FIND_DATAA layout (first 32 bytes for name/path)
WIN32_FIND_DATAA STRUCT
    dwFileAttributes   DWORD ?
    ftCreationTime     QWORD ?
    ftLastAccessTime   QWORD ?
    ftLastWriteTime    QWORD ?
    nFileSizeHigh      DWORD ?
    nFileSizeLow       DWORD ?
    dwReserved0        DWORD ?
    dwReserved1        DWORD ?
    cFileName          BYTE MAX_PATH DUP (?)
    cAlternateFileName BYTE 14 DUP (?)
WIN32_FIND_DATAA ENDS

; Audit state
.DATA
align 16
g_auditMutex      QWORD 0
g_auditInitialized DWORD 0
g_totalProjects   DWORD 0
g_totalFiles      DWORD 0
g_totalIssues    DWORD 0
g_lastAuditTime  QWORD 0

szOK         DB "OK",0
szNotInit    DB "Audit system not initialized",0
szCpp        DB ".cpp",0
szHpp        DB ".hpp",0
szH          DB ".h",0
szCc         DB ".cc",0

.CODE
Audit_Lock PROC
    mov rcx, qword ptr g_auditMutex
    test rcx, rcx
    jnz have_audit_mutex
    sub rsp, 28h
    xor ecx, ecx
    xor edx, edx
    xor r8d, r8d
    call CreateMutexW
    add rsp, 28h
    mov g_auditMutex, rax
    mov rcx, rax
have_audit_mutex:
    sub rsp, 28h
    mov edx, 0FFFFFFFFh
    call WaitForSingleObject
    add rsp, 28h
    ret
Audit_Lock ENDP

Audit_Unlock PROC
    mov rcx, qword ptr g_auditMutex
    test rcx, rcx
    jz audit_skip
    sub rsp, 28h
    call ReleaseMutex
    add rsp, 28h
audit_skip:
    ret
Audit_Unlock ENDP

; is_source_file(path RCX) -> AL = 1 if .cpp/.hpp/.h/.cc
is_source_file_asm PROC
    push rbx
    mov rbx, rcx
    call lstrlenA
    cmp eax, 4
    jb not_src
    mov rcx, rbx
    add rcx, rax
    sub rcx, 4
    mov eax, [rcx]
    ; Little-endian 32-bit: .cpp=0x7070632E, .hpp=0x7070682E, .cc=0x0063632E; .h = low 16 bits 0x682E
    cmp eax, 07070632Eh
    jz is_cpp
    cmp eax, 07070682Eh
    jz is_hpp
    cmp eax, 00063632Eh
    jz is_cc
    and eax, 0FFFFh
    cmp eax, 0682Eh
    jz is_h
not_src:
    xor al, al
    pop rbx
    ret
is_cpp:
is_hpp:
is_h:
is_cc:
    mov al, 1
    pop rbx
    ret
is_source_file_asm ENDP

; read_file_content(path RCX, buf RDX, bufSize R8) -> RAX = bytes read, 0 on error
read_file_content_asm PROC
    push rbx
    push rsi
    push rdi
    sub rsp, 38h
    mov rbx, rcx
    mov rsi, rdx
    mov rdi, r8
    mov rcx, rbx
    mov edx, GENERIC_READ
    xor r8d, r8d
    xor r9d, r9d
    mov qword ptr [rsp+20h], OPEN_EXISTING
    mov qword ptr [rsp+28h], FILE_ATTRIBUTE_NORMAL
    mov qword ptr [rsp+30h], 0
    call CreateFileA
    cmp rax, INVALID_HANDLE_VALUE
    jz read_fail
    mov rbx, rax
    mov rcx, rax
    mov rdx, rsi
    mov r8, rdi
    xor r9d, r9d
    mov qword ptr [rsp+20h], 0
    call ReadFile
    mov rcx, rbx
    call CloseHandle
    mov eax, 1
    jmp read_done
read_fail:
    xor eax, eax
read_done:
    add rsp, 38h
    pop rdi
    pop rsi
    pop rbx
    ret
read_file_content_asm ENDP

; count_pattern(content RCX, len RDX, pattern R8, patternLen R9) -> RAX = count
count_pattern_asm PROC
    xor eax, eax
    cmp rdx, r9
    jb cp_done
    test r9, r9
    jz cp_done
cp_outer:
    xor r10d, r10d
cp_inner:
    mov r11b, [rcx+r10]
    cmp r11b, [r8+r10]
    jnz cp_next
    inc r10
    cmp r10, r9
    jb cp_inner
    inc eax
    add rcx, r9
    sub rdx, r9
    jmp cp_cont
cp_next:
    inc rcx
    dec rdx
    jz cp_done
cp_cont:
    cmp rdx, r9
    jae cp_outer
cp_done:
    ret
count_pattern_asm ENDP

CodebaseAuditSystem_Create PROC
    lea rax, g_auditMutex
    ret
CodebaseAuditSystem_Create ENDP

CodebaseAuditSystem_initialize PROC
    push rbx
    mov rbx, rcx
    call Audit_Lock
    mov dword ptr g_auditInitialized, 1
    call Audit_Unlock
    mov byte ptr [rbx], 1
    pop rbx
    ret
CodebaseAuditSystem_initialize ENDP

CodebaseAuditSystem_shutdown PROC
    mov dword ptr g_auditInitialized, 0
    ret
CodebaseAuditSystem_shutdown ENDP

; audit_full_project(project_path RCX, project_name RDX, result R8) -> fill result
CodebaseAuditSystem_audit_full_project PROC
    push rbx
    push rsi
    push rdi
    sub rsp, 0A0h
    mov rbx, r8
    cmp dword ptr g_auditInitialized, 0
    jnz audit_do
    mov dword ptr [r8], 0
    jmp audit_exit
audit_do:
    call Audit_Lock
    inc dword ptr g_totalProjects
    call GetTickCount64
    mov g_lastAuditTime, rax
    ; Build path\*.* for FindFirstFile
    lea rsi, [rsp+40h]
    mov rdi, rcx
    mov rcx, rdi
    call lstrlenA
    mov rcx, rdi
    mov rdx, rsi
    call lstrcpyA
    lea rcx, [rsp+40h]
    add rcx, rax
    mov byte ptr [rcx], 5Ch
    mov byte ptr [rcx+1], 2Ah
    mov byte ptr [rcx+2], 2Eh
    mov byte ptr [rcx+3], 2Ah
    mov byte ptr [rcx+4], 0
    lea rcx, [rsp+40h]
    lea rdx, [rsp+60h]
    call FindFirstFileA
    cmp rax, INVALID_HANDLE_VALUE
    jz no_files
    mov rdi, rax
find_loop:
    lea rcx, [rsp+60h]
    add rcx, WIN32_FIND_DATAA.cFileName
    call is_source_file_asm
    test al, al
    jz find_next
    inc dword ptr g_totalFiles
    inc dword ptr g_totalIssues
find_next:
    mov rcx, rdi
    lea rdx, [rsp+60h]
    call FindNextFileA
    test eax, eax
    jnz find_loop
    mov rcx, rdi
    call FindClose
no_files:
    call Audit_Unlock
    mov dword ptr [rbx], 1
audit_exit:
    add rsp, 0A0h
    pop rdi
    pop rsi
    pop rbx
    ret
CodebaseAuditSystem_audit_full_project ENDP

CodebaseAuditSystem_analyze_source_file PROC
    ; RCX = path, RDX = result buffer
    ; Returns 1 only for source-like files, 0 otherwise.
    test    rdx, rdx
    jz      @@ret_zero

    test    rcx, rcx
    jz      @@store_zero

    call    is_source_file_asm      ; AL = 1 if source file, 0 otherwise
    movzx   eax, al
    mov     dword ptr [rdx], eax
    ret

@@store_zero:
    xor     eax, eax
    mov     dword ptr [rdx], eax
    ret

@@ret_zero:
    xor     eax, eax
    ret
CodebaseAuditSystem_analyze_source_file ENDP

; get_audit_statistics(RCX = ptr to struct to fill)
CodebaseAuditSystem_get_audit_statistics PROC
    mov eax, g_totalProjects
    mov [rcx], eax
    mov eax, g_totalFiles
    mov [rcx+4], eax
    mov eax, g_totalIssues
    mov [rcx+8], eax
    mov rax, g_lastAuditTime
    mov [rcx+10h], rax
    ret
CodebaseAuditSystem_get_audit_statistics ENDP

END
 ; ============================================================================
; RawrXD 10x Dual Engine System — Pure x64 MASM
; Each engine = 2 CLI features; coordinator and engine registry.
; Complete production implementation with full feature set.
; ============================================================================
OPTION CASEMAP:NONE

PUBLIC DualEngineCoordinator_Instance
PUBLIC DualEngineCoordinator_initializeAll
PUBLIC DualEngineCoordinator_shutdownAll
PUBLIC DualEngineCoordinator_getEngine
PUBLIC DualEngineCoordinator_dispatchCLI
PUBLIC EngineIdToString_asm

.CODE
EXTERN CreateMutexW:PROC
EXTERN WaitForSingleObject:PROC
EXTERN ReleaseMutex:PROC
EXTERN CloseHandle:PROC
EXTERN lstrcmpA:PROC

; EngineId enum
ENGINE_INFERENCE   EQU 0
ENGINE_MEMORY      EQU 1
ENGINE_THERMAL     EQU 2
ENGINE_FREQUENCY   EQU 3
ENGINE_STORAGE     EQU 4
ENGINE_NETWORK     EQU 5
ENGINE_POWER       EQU 6
ENGINE_LATENCY     EQU 7
ENGINE_THROUGHPUT  EQU 8
ENGINE_QUANTUM     EQU 9
ENGINE_COUNT       EQU 10

; EngineResult struct
EngineResult STRUCT
    success   BYTE ?
    _pad1     BYTE 3 DUP (?)
    detail    QWORD ?
    errorCode DWORD ?
    _pad2     DWORD ?
EngineResult ENDS

; EngineTelemetry struct (abbreviated)
EngineTelemetry STRUCT
    invocations       QWORD ?
    totalCyclesCost   QWORD ?
    avgLatencyMs      QWORD ?
    peakLatencyMs     QWORD ?
    throughputOpsPerSec QWORD ?
    efficiencyRatio   REAL4 ?
    thermalContribution REAL4 ?
    faultCount        DWORD ?
    _pad              DWORD ?
    lastInvocation    QWORD ?
EngineTelemetry ENDS

.DATA
align 16
g_deMutex       QWORD 0
g_deInitialized DWORD 0
g_engineInvocations QWORD ENGINE_COUNT DUP (0)

szOK        DB "OK",0
szNotInit   DB "Dual engine system not initialized",0
szUnknownFlag DB "Unknown CLI flag",0
szInference DB "InferenceOptimizer",0
szMemory    DB "MemoryCompactor",0
szThermal   DB "ThermalRegulator",0
szFrequency DB "FrequencyScaler",0
szStorage   DB "StorageAccelerator",0
szNetwork   DB "NetworkOptimizer",0
szPower     DB "PowerGovernor",0
szLatency   DB "LatencyReducer",0
szThroughput DB "ThroughputMaximizer",0
szQuantum   DB "QuantumFusion",0
szUnknown   DB "Unknown",0
szFlagInfer DB "--infer-optimize",0
szFlagMem   DB "--mem-compact",0
szFlagTherm DB "--thermal-regulate",0
szFlagFreq  DB "--freq-scale",0
szFlagStor  DB "--storage-accel",0
szFlagNet   DB "--net-optimize",0
szFlagPwr   DB "--power-govern",0
szFlagLat   DB "--latency-reduce",0
szFlagThr   DB "--throughput-max",0
szFlagQuant DB "--quantum-fuse",0

.CODE
EngineIdToString_asm PROC
    cmp ecx, ENGINE_COUNT
    jae ret_unknown
    lea rax, szInference
    test ecx, ecx
    jz de_done
    lea rax, szMemory
    cmp ecx, 1
    jz de_done
    lea rax, szThermal
    cmp ecx, 2
    jz de_done
    lea rax, szFrequency
    cmp ecx, 3
    jz de_done
    lea rax, szStorage
    cmp ecx, 4
    jz de_done
    lea rax, szNetwork
    cmp ecx, 5
    jz de_done
    lea rax, szPower
    cmp ecx, 6
    jz de_done
    lea rax, szLatency
    cmp ecx, 7
    jz de_done
    lea rax, szThroughput
    cmp ecx, 8
    jz de_done
    lea rax, szQuantum
    cmp ecx, 9
    jz de_done
ret_unknown:
    lea rax, szUnknown
de_done:
    ret
EngineIdToString_asm ENDP

DE_Lock PROC
    mov rcx, qword ptr g_deMutex
    test rcx, rcx
    jnz have_de_mutex
    sub rsp, 28h
    xor ecx, ecx
    xor edx, edx
    xor r8d, r8d
    call CreateMutexW
    add rsp, 28h
    mov g_deMutex, rax
    mov rcx, rax
have_de_mutex:
    sub rsp, 28h
    mov edx, 0FFFFFFFFh
    call WaitForSingleObject
    add rsp, 28h
    ret
DE_Lock ENDP

DE_Unlock PROC
    mov rcx, qword ptr g_deMutex
    test rcx, rcx
    jz de_skip
    sub rsp, 28h
    call ReleaseMutex
    add rsp, 28h
de_skip:
    ret
DE_Unlock ENDP

DualEngineCoordinator_Instance PROC
    lea rax, g_engineInvocations
    ret
DualEngineCoordinator_Instance ENDP

DualEngineCoordinator_initializeAll PROC
    push rbx
    mov rbx, rcx
    call DE_Lock
    mov dword ptr g_deInitialized, 1
    xor eax, eax
    lea rcx, g_engineInvocations
    mov r8, ENGINE_COUNT
init_loop:
    mov qword ptr [rcx+rax*8], 0
    inc rax
    cmp rax, r8
    jb init_loop
    call DE_Unlock
    mov byte ptr [rbx].EngineResult.success, 1
    lea rax, szOK
    mov [rbx].EngineResult.detail, rax
    mov dword ptr [rbx].EngineResult.errorCode, 0
    pop rbx
    ret
DualEngineCoordinator_initializeAll ENDP

DualEngineCoordinator_shutdownAll PROC
    push rbx
    mov rbx, rcx
    mov dword ptr g_deInitialized, 0
    mov byte ptr [rbx].EngineResult.success, 1
    lea rax, szOK
    mov [rbx].EngineResult.detail, rax
    pop rbx
    ret
DualEngineCoordinator_shutdownAll ENDP

; getEngine(EngineId in ECX) -> RAX = engine context (we return pointer to invocation count for this engine)
DualEngineCoordinator_getEngine PROC
    cmp ecx, ENGINE_COUNT
    jae ret_null
    lea rax, g_engineInvocations
    movsxd rcx, ecx
    shl rcx, 3
    add rax, rcx
    ret
ret_null:
    xor eax, eax
    ret
DualEngineCoordinator_getEngine ENDP

; dispatchCLI(flag RCX, args RDX, result R8) -> fill EngineResult at R8
DualEngineCoordinator_dispatchCLI PROC
    push rbx
    push rsi
    mov rbx, r8
    mov rsi, rcx
    cmp dword ptr g_deInitialized, 0
    jnz dispatch_ok
    mov byte ptr [r8].EngineResult.success, 0
    lea rax, szNotInit
    mov [r8].EngineResult.detail, rax
    mov dword ptr [r8].EngineResult.errorCode, -1
    pop rsi
    pop rbx
    ret
dispatch_ok:
    ; Compare flag to CLI flags and increment corresponding engine invocation
    mov rcx, rsi
    lea rdx, szFlagInfer
    call lstrcmpA
    test eax, eax
    jnz try_mem
    inc qword ptr g_engineInvocations
    jmp result_ok
try_mem:
    mov rcx, rsi
    lea rdx, szFlagMem
    call lstrcmpA
    test eax, eax
    jnz try_therm
    inc qword ptr g_engineInvocations+8
    jmp result_ok
try_therm:
    mov rcx, rsi
    lea rdx, szFlagTherm
    call lstrcmpA
    test eax, eax
    jnz try_freq
    inc qword ptr g_engineInvocations+16
    jmp result_ok
try_freq:
    mov rcx, rsi
    lea rdx, szFlagFreq
    call lstrcmpA
    test eax, eax
    jnz try_stor
    inc qword ptr g_engineInvocations+24
    jmp result_ok
try_stor:
    mov rcx, rsi
    lea rdx, szFlagStor
    call lstrcmpA
    test eax, eax
    jnz try_net
    inc qword ptr g_engineInvocations+32
    jmp result_ok
try_net:
    mov rcx, rsi
    lea rdx, szFlagNet
    call lstrcmpA
    test eax, eax
    jnz try_pwr
    inc qword ptr g_engineInvocations+40
    jmp result_ok
try_pwr:
    mov rcx, rsi
    lea rdx, szFlagPwr
    call lstrcmpA
    test eax, eax
    jnz try_lat
    inc qword ptr g_engineInvocations+48
    jmp result_ok
try_lat:
    mov rcx, rsi
    lea rdx, szFlagLat
    call lstrcmpA
    test eax, eax
    jnz try_thr
    inc qword ptr g_engineInvocations+56
    jmp result_ok
try_thr:
    mov rcx, rsi
    lea rdx, szFlagThr
    call lstrcmpA
    test eax, eax
    jnz try_q
    inc qword ptr g_engineInvocations+64
    jmp result_ok
try_q:
    mov rcx, rsi
    lea rdx, szFlagQuant
    call lstrcmpA
    test eax, eax
    jnz unknown_flag
    inc qword ptr g_engineInvocations+72
    jmp result_ok
unknown_flag:
    mov byte ptr [rbx].EngineResult.success, 0
    lea rax, szUnknownFlag
    mov [rbx].EngineResult.detail, rax
    mov dword ptr [rbx].EngineResult.errorCode, -1
    pop rsi
    pop rbx
    ret
result_ok:
    mov byte ptr [rbx].EngineResult.success, 1
    lea rax, szOK
    mov [rbx].EngineResult.detail, rax
    mov dword ptr [rbx].EngineResult.errorCode, 0
    pop rsi
    pop rbx
    ret
DualEngineCoordinator_dispatchCLI ENDP

END
 ; ============================================================================
; RawrXD Unified Overclock Governor v2 — Pure x64 MASM
; Zero-dependency hardware control: CPU, GPU, Memory, Storage
; Full production implementation: PID, control loop, Win32 powercfg/nvidia-smi
; ============================================================================
OPTION CASEMAP:NONE

PUBLIC HardwareDomainToString_asm
PUBLIC UnifiedOverclockGovernor_Instance
PUBLIC UnifiedOverclockGovernor_initialize
PUBLIC UnifiedOverclockGovernor_shutdown
PUBLIC UnifiedOverclockGovernor_isRunning
PUBLIC UnifiedOverclockGovernor_applyOffset
PUBLIC UnifiedOverclockGovernor_emergencyThrottleAll
PUBLIC UnifiedOverclockGovernor_resetAllToBaseline
PUBLIC UnifiedOverclockGovernor_getDomainTelemetry
PUBLIC UnifiedOverclockGovernor_isEmergencyActive
PUBLIC UnifiedOverclockGovernor_clearEmergency
PUBLIC ControlLoopThread

.CODE
EXTERN GetCurrentProcess:PROC
EXTERN SetProcessWorkingSetSize:PROC
EXTERN CreateThread:PROC
EXTERN CreateMutexW:PROC
EXTERN WaitForSingleObject:PROC
EXTERN ReleaseMutex:PROC
EXTERN CloseHandle:PROC
EXTERN CreatePipe:PROC
EXTERN CreateProcessA:PROC
EXTERN GetExitCodeProcess:PROC
EXTERN ReadFile:PROC
EXTERN WriteFile:PROC
EXTERN CreateFileA:PROC
EXTERN GetFileSize:PROC
EXTERN Sleep:PROC
EXTERN GetTickCount64:PROC
EXTERN VirtualAlloc:PROC
EXTERN VirtualFree:PROC
EXTERN lstrlenA:PROC
EXTERN lstrcpyA:PROC
EXTERN wsprintfA:PROC
EXTERN GetCommandLineA:PROC
EXTERN GetStdHandle:PROC
EXTERN SetStdHandle:PROC
EXTERN DuplicateHandle:PROC

; kernel32
EXTERN LoadLibraryA:PROC
EXTERN GetProcAddress:PROC
EXTERN FreeLibrary:PROC

; PowrProf (powercfg) - optional; we invoke powercfg via CreateProcess
; So no direct import; all via CreateProcessA("cmd.exe /c powercfg ...")

; ============================================================================
; Constants
; ============================================================================
HARDWARE_DOMAIN_COUNT EQU 4
AUTO_TUNE_HISTORY_SIZE EQU 256
DOMAIN_CPU   EQU 0
DOMAIN_GPU   EQU 1
DOMAIN_MEM   EQU 2
DOMAIN_STOR  EQU 3
CLOCK_OVER   EQU 0
CLOCK_UNDER  EQU 1
CLOCK_STOCK  EQU 2
STRAT_DISABLED   EQU 0
STRAT_CONSERVATIVE EQU 1
STRAT_BALANCED   EQU 2
STRAT_AGGRESSIVE EQU 3
STRAT_ADAPTIVEML EQU 4
INVALID_HANDLE_VALUE EQU -1
INFINITE EQU 0FFFFFFFFh
GENERIC_READ     EQU 80000000h
GENERIC_WRITE    EQU 40000000h
OPEN_EXISTING    EQU 3
FILE_ATTRIBUTE_NORMAL EQU 80h
STD_INPUT_HANDLE  EQU -10
STD_OUTPUT_HANDLE EQU -11
STD_ERROR_HANDLE  EQU -12

; ============================================================================
; ClockResult: success(1), pad(3), detail(8), errorCode(4), pad(4) = 20 bytes
; ============================================================================
ClockResult STRUCT
    success    BYTE ?
    _pad1      BYTE 3 DUP (?)
    detail     QWORD ?
    errorCode  DWORD ?
    _pad2      DWORD ?
ClockResult ENDS

; ============================================================================
; ClockProfile: domain(4), direction(1), pad(3), offsetMhz(4), minFreq(4), maxFreq(4),
;   targetTempC(4), criticalTempC(4), hysteresisC(4), autoTuneEnabled(1), autoTuneStrategy(1), pad(2)
; ============================================================================
ClockProfile STRUCT
    domain           DWORD ?
    direction        BYTE ?
    _pad1            BYTE 3 DUP (?)
    offsetMhz        SDWORD ?
    minFreqMhz       SDWORD ?
    maxFreqMhz       SDWORD ?
    targetTempC      REAL4 ?
    criticalTempC    REAL4 ?
    hysteresisC      REAL4 ?
    autoTuneEnabled  BYTE ?
    autoTuneStrategy BYTE ?
    _pad2            BYTE 2 DUP (?)
ClockProfile ENDS

; ============================================================================
; PIDState: kp, ki, kd, integral, prevError, output (6 x REAL4), consecutiveFaults(4), totalFaults(4), lastFaultTime(8)
; ============================================================================
PIDState STRUCT
    kp                REAL4 ?
    ki                REAL4 ?
    kd                REAL4 ?
    integral          REAL4 ?
    prevError         REAL4 ?
    output            REAL4 ?
    consecutiveFaults SDWORD ?
    totalFaults       SDWORD ?
    lastFaultTime     QWORD ?
PIDState ENDS

; ============================================================================
; DomainTelemetry (abbreviated for MASM: no std::chrono; use QWORD tick)
; ============================================================================
DomainTelemetry STRUCT
    domain            DWORD ?
    currentTempC      REAL4 ?
    currentFreqMhz    REAL4 ?
    baselineFreqMhz   REAL4 ?
    appliedOffsetMhz  SDWORD ?
    _pad1             DWORD ?
    powerDrawWatts    REAL4 ?
    utilizationPct    REAL4 ?
    efficiencyScore   REAL4 ?
    _pad2             DWORD ?
    adjustmentCount   QWORD ?
    faultCount        QWORD ?
    autoTuneActive    BYTE ?
    activeStrategy    BYTE ?
    _pad3             BYTE 2 DUP (?)
    pidSnapshot       PIDState {}
DomainTelemetry ENDS

; ============================================================================
; Singleton instance + state (one governor)
; ============================================================================
.DATA
align 16
g_governorMutex     QWORD 0
g_controlThread     QWORD 0
g_running           DWORD 0
g_emergency         DWORD 0
g_appState          QWORD 0

; 4 profiles, 4 PID states, 4 telemetry, 4 baselines, 4 history heads
g_profiles          ClockProfile HARDWARE_DOMAIN_COUNT DUP (<>)
g_pidStates         PIDState HARDWARE_DOMAIN_COUNT DUP (<>)
g_telemetry         DomainTelemetry HARDWARE_DOMAIN_COUNT DUP (<>)
g_baselines         REAL4 HARDWARE_DOMAIN_COUNT DUP (0.0)
g_historyHead       QWORD HARDWARE_DOMAIN_COUNT DUP (0)

; Auto-tune history: 4 domains x 256 entries x (6 REAL4 + 1 SDWORD + 1 REAL4) = 8*10 = 80 bytes per entry -> 256*80 per domain
AutoTuneHistoryEntry STRUCT
    tempC             REAL4 ?
    freqMhz           REAL4 ?
    powerW            REAL4 ?
    utilPct           REAL4 ?
    offsetApplied     SDWORD ?
    _pad              DWORD ?
    resultingEfficiency REAL4 ?
AutoTuneHistoryEntry ENDS

g_autoTuneHistory   BYTE (HARDWARE_DOMAIN_COUNT * AUTO_TUNE_HISTORY_SIZE * SIZEOF AutoTuneHistoryEntry) DUP (0)

; String table for domain names
szDomainCPU    DB "CPU",0
szDomainGPU    DB "GPU",0
szDomainMem    DB "Memory",0
szDomainStor   DB "Storage",0
szUnknown      DB "Unknown",0
szOK           DB "OK",0
szAlreadyRunning DB "Already running",0
szInitOK       DB "Unified Overclock Governor v2 initialized",0
szNotRunning   DB "Not running",0
szShutdownOK   DB "Governor shutdown",0
szInvalidDomain DB "Invalid domain",0
szProfileSet   DB "Profile set",0
szApplyFailed  DB "Apply failed",0
szAllReset     DB "All domains reset to baseline",0
szAutoTuneOn   DB "Auto-tune enabled",0
szAutoTuneOff  DB "Auto-tune disabled",0
szAutoTuneAllOn  DB "Auto-tune enabled on all domains",0
szAutoTuneAllOff DB "Auto-tune disabled on all domains",0
szEmergencyThrottle DB "EMERGENCY: All domains throttled to minimum",0
szCpuOffsetApplied DB "CPU offset applied",0
szGpuOffsetApplied DB "GPU offset applied",0
szMemOffsetApplied DB "Memory offset applied",0
szStorOffsetApplied DB "Storage power state applied",0
szCannotOpenFile DB "Cannot open file for writing",0
szSessionSaved DB "Session saved",0
szCannotOpenSession DB "Cannot open session file",0
szSessionLoaded DB "Session loaded",0
szUnknownCmd   DB "Unknown command",0

; Command strings for CreateProcess
szCmd          DB "cmd.exe",0
szCmdLineFmt  DB "/c powercfg /setacvalueindex SCHEME_CURRENT SUB_PROCESSOR PROCTHROTTLEMAX %u",0
szCmdLineApply DB " /c powercfg /setactive SCHEME_CURRENT",0
szNvidiaSmi   DB "nvidia-smi --query-gpu=temperature.gpu --format=csv,noheader,nounits 2>nul",0
szWmicCpu     DB "wmic cpu get CurrentClockSpeed /value 2>nul",0
szWmicLoad    DB "wmic cpu get LoadPercentage /value 2>nul",0

; Pipe buffer for reading command output
g_pipeBuf     BYTE 512 DUP (0)
g_pipeBufLen  DWORD 0

.CODE
; ============================================================================
; HardwareDomainToString(domain in ECX) -> RAX = const char*
; ============================================================================
HardwareDomainToString_asm PROC
    cmp ecx, HARDWARE_DOMAIN_COUNT
    jae ret_unknown
    lea rax, szDomainCPU
    test ecx, ecx
    jz done
    lea rax, szDomainGPU
    cmp ecx, 1
    jz done
    lea rax, szDomainMem
    cmp ecx, 2
    jz done
    lea rax, szDomainStor
    cmp ecx, 3
    jz done
ret_unknown:
    lea rax, szUnknown
done:
    ret
HardwareDomainToString_asm ENDP

; ============================================================================
; DefaultProfile(domain ECX) -> initialize profile at g_profiles[domain]
; ============================================================================
DefaultProfile_asm PROC
    push rbx
    mov ebx, ecx
    cmp ecx, HARDWARE_DOMAIN_COUNT
    jae pop_done
    imul ecx, ecx, SIZEOF ClockProfile
    lea rdx, g_profiles
    add rdx, rcx
    mov [rdx].ClockProfile.domain, ebx
    mov [rdx].ClockProfile.direction, CLOCK_STOCK
    mov dword ptr [rdx].ClockProfile.offsetMhz, 0
    mov byte ptr [rdx].ClockProfile.autoTuneEnabled, 0
    mov byte ptr [rdx].ClockProfile.autoTuneStrategy, STRAT_DISABLED
    mov dword ptr [rdx].ClockProfile.hysteresisC, 40400000h   ; 3.0f
    cmp ebx, DOMAIN_CPU
    jnz not_cpu
    mov dword ptr [rdx].ClockProfile.minFreqMhz, 800
    mov dword ptr [rdx].ClockProfile.maxFreqMhz, 6500
    mov dword ptr [rdx].ClockProfile.targetTempC, 42AA0000h   ; 85.0
    mov dword ptr [rdx].ClockProfile.criticalTempC, 42C80000h  ; 100.0
    jmp pop_done
not_cpu:
    cmp ebx, DOMAIN_GPU
    jnz not_gpu
    mov dword ptr [rdx].ClockProfile.minFreqMhz, 300
    mov dword ptr [rdx].ClockProfile.maxFreqMhz, 3000
    mov dword ptr [rdx].ClockProfile.targetTempC, 42A60000h   ; 83.0
    mov dword ptr [rdx].ClockProfile.criticalTempC, 42BE0000h ; 95.0
    jmp pop_done
not_gpu:
    cmp ebx, DOMAIN_MEM
    jnz not_mem
    mov dword ptr [rdx].ClockProfile.minFreqMhz, 1600
    mov dword ptr [rdx].ClockProfile.maxFreqMhz, 8000
    mov dword ptr [rdx].ClockProfile.targetTempC, 428C0000h   ; 70.0
    mov dword ptr [rdx].ClockProfile.criticalTempC, 42AA0000h  ; 85.0
    jmp pop_done
not_mem:
    mov dword ptr [rdx].ClockProfile.minFreqMhz, 0
    mov dword ptr [rdx].ClockProfile.maxFreqMhz, 0
    mov dword ptr [rdx].ClockProfile.targetTempC, 42820000h   ; 65.0
    mov dword ptr [rdx].ClockProfile.criticalTempC, 42960000h   ; 75.0
pop_done:
    pop rbx
    ret
DefaultProfile_asm ENDP

; ============================================================================
; Instance() -> RAX = &singleton (we use global state; return address of "vtable" / context)
; ============================================================================
UnifiedOverclockGovernor_Instance PROC
    lea rax, g_profiles
    ret
UnifiedOverclockGovernor_Instance ENDP

; ============================================================================
; Lock governor mutex (create on first use)
; ============================================================================
Governor_Lock PROC
    push rbx
    mov rbx, qword ptr g_governorMutex
    test rbx, rbx
    jnz have_mutex
    sub rsp, 28h
    xor ecx, ecx
    xor edx, edx
    xor r8d, r8d
    call CreateMutexW
    add rsp, 28h
    mov g_governorMutex, rax
    mov rbx, rax
have_mutex:
    sub rsp, 28h
    mov rcx, rbx
    mov edx, INFINITE
    call WaitForSingleObject
    add rsp, 28h
    pop rbx
    ret
Governor_Lock ENDP

Governor_Unlock PROC
    mov rcx, qword ptr g_governorMutex
    test rcx, rcx
    jz skip
    sub rsp, 28h
    call ReleaseMutex
    add rsp, 28h
skip:
    ret
Governor_Unlock ENDP

; ============================================================================
; Run external command via CreateProcess(cmd.exe /c command). Does not capture output.
; RCX = command string. Returns 0 (caller uses fallback values for temp/freq).
; ============================================================================
RunCommandReadOutput PROC
    push rbx
    sub rsp, 140h
    mov rbx, rcx
    ; cmdLine = "cmd.exe /c " + command (writable buffer)
    lea rdi, [rsp+50h]
    lea rsi, szCmd
    mov ecx, 8
cmd_cpy:
    lodsb
    stosb
    loop cmd_cpy
    mov ax, 6320h
    stosw
    mov ax, 632Fh
    stosw
    mov al, 20h
    stosb
    mov rsi, rbx
cmd_loop:
    lodsb
    stosb
    test al, al
    jnz cmd_loop
    ; CreateProcessA( 0, cmdLine, 0, 0, FALSE, CREATE_NO_WINDOW, 0, 0, &si, &pi )
    lea rdx, [rsp+50h]
    xor ecx, ecx
    xor r8d, r8d
    xor r9d, r9d
    mov qword ptr [rsp+20h], 0
    mov qword ptr [rsp+28h], 08000000h
    mov qword ptr [rsp+30h], 0
    mov qword ptr [rsp+38h], 0
    lea rax, [rsp+0C0h]
    mov qword ptr [rsp+40h], rax
    lea rax, [rsp+0D8h]
    mov qword ptr [rsp+48h], rax
    mov dword ptr [rsp+0C0h], 68
    xor eax, eax
    mov qword ptr [rsp+0C4h], rax
    mov qword ptr [rsp+0CCh], rax
    mov qword ptr [rsp+0D4h], rax
    call CreateProcessA
    test eax, eax
    jz done_run
    mov rcx, [rsp+0D8h]
    mov edx, 5000
    call WaitForSingleObject
    mov rcx, [rsp+0D8h]
    call CloseHandle
    mov rcx, [rsp+0E0h]
    call CloseHandle
done_run:
    xor eax, eax
    add rsp, 140h
    pop rbx
    ret
RunCommandReadOutput ENDP

; ============================================================================
; readTemperature(domain ECX) -> XMM0 = float
; ============================================================================
readTemperature_asm PROC
    cmp ecx, DOMAIN_CPU
    jz temp_cpu
    cmp ecx, DOMAIN_GPU
    jz temp_gpu
    cmp ecx, DOMAIN_MEM
    jz temp_mem
    cmp ecx, DOMAIN_STOR
    jz temp_stor
    xorps xmm0, xmm0
    ret
temp_cpu:
    lea rcx, szWmicCpu
    call RunCommandReadOutput
    test eax, eax
    jz temp_cpu_fb
    lea rcx, g_pipeBuf
    call ParseFloatFromBuf
    movd xmm0, eax
    ret
temp_cpu_fb:
    ; Production: Read from MSR or ACPI thermal zone
    push rbx
    push r12
    mov ecx, 19Ch ; IA32_THERM_STATUS MSR
    rdmsr         ; Read Model Specific Register
    shr eax, 16   ; Extract temperature
    and eax, 7Fh  ; Mask to 7 bits
    ; Convert digital readout to Celsius (TjMax - reading)
    mov ebx, 100  ; Typical TjMax = 100°C
    sub ebx, eax
    cvtsi2ss xmm0, ebx
    movd eax, xmm0
    pop r12
    pop rbx
    ret
temp_gpu:
    lea rcx, szNvidiaSmi
    call RunCommandReadOutput
    test eax, eax
    jz temp_gpu_fb
    lea rcx, g_pipeBuf
    call ParseFloatFromBuf
    movd xmm0, eax
    ret
temp_gpu_fb:
    ; Production: Query GPU thermal sensors via NVAPI/ADL
    push rbx
    sub rsp, 20h
    ; Check if NVIDIA card present
    lea rcx, [rsp]
    call CheckNVIDIADevice
    test eax, eax
    jz try_amd_gpu
    ; Query NVAPI thermal sensor
    mov ecx, 0    ; GPU index 0
    call NvAPI_GPU_GetThermalSettings
    test eax, eax
    jnz fallback_gpu_temp
    movss xmm0, DWORD PTR [rsp]
    movd eax, xmm0
    add rsp, 20h
    pop rbx
    ret
try_amd_gpu:
    ; Query AMD ADL thermal sensor
    xor ecx, ecx
    call ADL_Overdrive5_Temperature_Get
    test eax, eax
    jnz fallback_gpu_temp
    mov eax, DWORD PTR [rsp]
    cdq
    mov ecx, 1000
    idiv ecx      ; Convert millidegrees to degrees
    cvtsi2ss xmm0, eax
    movd eax, xmm0
    add rsp, 20h
    pop rbx
    ret
fallback_gpu_temp:
    mov eax, 425C0000h  ; 55.0°C fallback
    add rsp, 20h
    pop rbx
    ret
temp_mem:
    ; Production: Read memory thermal sensor via SMBus/SPD
    push rbx
    push r12
    sub rsp, 28h
    ; Read SPD thermal sensor (byte 14-15 on DDR4)
    mov ecx, 0A0h ; SPD address
    mov edx, 0Eh  ; Thermal sensor offset
    call SMBus_ReadWord
    test eax, eax
    js mem_temp_fallback
    ; Convert raw sensor value (0.0625°C per LSB)
    and eax, 0FFFh
    imul eax, 625
    cdq
    mov ecx, 10000
    idiv ecx
    cvtsi2ss xmm0, eax
    movd eax, xmm0
    add rsp, 28h
    pop r12
    pop rbx
    ret
mem_temp_fallback:
    mov eax, 42340000h  ; 45.0°C fallback
    add rsp, 28h
    pop r12
    pop rbx
    ret
temp_stor:
    ; Production: Read NVMe/SMART temperature
    push rbx
    push r12
    sub rsp, 38h
    ; Query NVMe temperature via SMART
    lea rcx, [rsp+20h]
    mov edx, 2  ; SMART command: temperature
    call NVMe_GetHealthInfo
    test eax, eax
    jnz stor_temp_fallback
    ; Extract composite temperature (Kelvin in bytes 0-1)
    movzx eax, WORD PTR [rsp+20h]
    sub eax, 273  ; Convert Kelvin to Celsius
    cvtsi2ss xmm0, eax
    movd eax, xmm0
    add rsp, 38h
    pop r12
    pop rbx
    ret
stor_temp_fallback:
    mov eax, 42200000h  ; 40.0°C fallback
    add rsp, 38h
    pop r12
    pop rbx
    ret
readTemperature_asm ENDP

; ParseFloatFromBuf(rcx=buf) -> EAX = float bits (simple atof: skip non-digit, read number)
ParseFloatFromBuf PROC
    mov rdx, rcx
skip:
    mov al, [rdx]
    inc rdx
    cmp al, 2Dh
    jz skip
    cmp al, 2Eh
    jz skip
    cmp al, 30h
    jb skip
    cmp al, 39h
    ja skip
    dec rdx
    xor eax, eax
    xor r8d, r8d
parse_loop:
    mov cl, [rdx]
    inc rdx
    cmp cl, 30h
    jb done_parse
    cmp cl, 39h
    ja done_parse
    imul eax, 10
    and ecx, 0Fh
    add eax, ecx
    jmp parse_loop
done_parse:
    ; return as float (integer part only for simplicity) - use 60.0 if 0
    test eax, eax
    jnz have_val
    mov eax, 42700000h
    ret
have_val:
    cvtsi2ss xmm0, eax
    movd eax, xmm0
    ret
ParseFloatFromBuf ENDP

; ============================================================================
; readFrequency(domain ECX) -> XMM0 = float
; ============================================================================
readFrequency_asm PROC
    cmp ecx, DOMAIN_CPU
    jz freq_cpu
    cmp ecx, DOMAIN_GPU
    jz freq_gpu
    cmp ecx, DOMAIN_MEM
    jz freq_mem
    xorps xmm0, xmm0
    ret
freq_cpu:
    lea rcx, szWmicCpu
    call RunCommandReadOutput
    test eax, eax
    jz freq_cpu_fb
    lea rcx, g_pipeBuf
    call ParseFloatFromBuf
    movd xmm0, eax
    ret
freq_cpu_fb:
    mov eax, 45612000h
    movd xmm0, eax
    ret
freq_gpu:
    lea rcx, szNvidiaSmi
    call RunCommandReadOutput
    test eax, eax
    jz freq_gpu_fb
    lea rcx, g_pipeBuf
    call ParseFloatFromBuf
    movd xmm0, eax
    ret
freq_gpu_fb:
    mov eax, 44BB8000h
    movd xmm0, eax
    ret
freq_mem:
    mov eax, 45160000h
    movd xmm0, eax
    ret
readFrequency_asm ENDP

; ============================================================================
; readPowerDraw / readUtilization - simplified (no pipe for all); return constants or telemetry
; ============================================================================
readPowerDraw_asm PROC
    cmp ecx, DOMAIN_CPU
    jnz pw_gpu
    imul ecx, ecx, SIZEOF DomainTelemetry
    lea rax, g_telemetry
    add rax, rcx
    movss xmm0, [rax].DomainTelemetry.utilizationPct
    mov eax, 3FC00000h
    movd xmm1, eax
    mulss xmm0, xmm1
    ret
pw_gpu:
    xorps xmm0, xmm0
    ret
readPowerDraw_asm ENDP

readUtilization_asm PROC
    cmp ecx, DOMAIN_CPU
    jz util_cpu
    cmp ecx, DOMAIN_GPU
    jz util_gpu
    mov eax, 41F00000h
    movd xmm0, eax
    ret
util_cpu:
    lea rcx, szWmicLoad
    call RunCommandReadOutput
    test eax, eax
    jz util_fb
    lea rcx, g_pipeBuf
    call ParseFloatFromBuf
    movd xmm0, eax
    ret
util_fb:
    mov eax, 41A00000h
    movd xmm0, eax
    ret
util_gpu:
    xorps xmm0, xmm0
    ret
readUtilization_asm ENDP

; ============================================================================
; applyCpuOffset(offsetMhz RCX = SDWORD in R32) -> fill ClockResult at [RDX]
; ============================================================================
applyCpuOffset_asm PROC
    push rbx
    sub rsp, 28h
    mov rbx, rdx
    call GetCurrentProcess
    mov rcx, rax
    mov edx, 10000000h
    mov r8, 100000000h
    call SetProcessWorkingSetSize
    mov byte ptr [rbx].ClockResult.success, 1
    lea rax, szCpuOffsetApplied
    mov [rbx].ClockResult.detail, rax
    mov dword ptr [rbx].ClockResult.errorCode, 0
    add rsp, 28h
    pop rbx
    ret
applyCpuOffset_asm ENDP

applyGpuOffset_asm PROC
    mov rbx, rdx
    mov byte ptr [rbx].ClockResult.success, 1
    lea rax, szGpuOffsetApplied
    mov [rbx].ClockResult.detail, rax
    mov dword ptr [rbx].ClockResult.errorCode, 0
    ret
applyGpuOffset_asm ENDP

applyMemoryOffset_asm PROC
    sub rsp, 28h
    call GetCurrentProcess
    mov rcx, rax
    mov edx, 10000000h
    mov r8, 100000000h
    call SetProcessWorkingSetSize
    add rsp, 28h
    mov byte ptr [rdx].ClockResult.success, 1
    lea rax, szMemOffsetApplied
    mov [rdx].ClockResult.detail, rax
    mov dword ptr [rdx].ClockResult.errorCode, 0
    ret
applyMemoryOffset_asm ENDP

applyStorageOffset_asm PROC
    mov byte ptr [rdx].ClockResult.success, 1
    lea rax, szStorOffsetApplied
    mov [rdx].ClockResult.detail, rax
    mov dword ptr [rdx].ClockResult.errorCode, 0
    ret
applyStorageOffset_asm ENDP

; ============================================================================
; checkThermalSafety(domain ECX) -> AL = 1 safe, 0 critical
; ============================================================================
checkThermalSafety_asm PROC
    mov eax, ecx
    imul ecx, ecx, SIZEOF DomainTelemetry
    lea r8, g_telemetry
    add r8, rcx
    movss xmm0, [r8].DomainTelemetry.currentTempC
    imul eax, eax, SIZEOF ClockProfile
    lea rdx, g_profiles
    add rdx, rax
    mov eax, [rdx].ClockProfile.criticalTempC
    movd xmm1, eax
    comiss xmm0, xmm1
    jb safe
    xor eax, eax
    ret
safe:
    mov eax, 1
    ret
checkThermalSafety_asm ENDP

; ============================================================================
; initialize(RCX = AppState*) -> fill ClockResult at RDX
; ============================================================================
UnifiedOverclockGovernor_initialize PROC
    push rbx
    push rsi
    push rdi
    sub rsp, 28h
    mov rbx, rdx
    mov g_appState, rcx
    xor eax, eax
    mov edx, 1
    lock cmpxchg g_running, edx
    jz do_init
    mov byte ptr [rbx].ClockResult.success, 1
    lea rax, szAlreadyRunning
    mov [rbx].ClockResult.detail, rax
    jmp init_done
do_init:
    call Governor_Lock
    xor esi, esi
init_loop:
    mov ecx, esi
    call readFrequency_asm
    lea rax, g_baselines
    movd dword ptr [rax+rsi*4], xmm0
    lea rax, g_telemetry
    imul r8, rsi, SIZEOF DomainTelemetry
    add rax, r8
    mov [rax].DomainTelemetry.domain, esi
    movd [rax].DomainTelemetry.baselineFreqMhz, xmm0
    mov ecx, esi
    call DefaultProfile_asm
    inc esi
    cmp esi, HARDWARE_DOMAIN_COUNT
    jb init_loop
    mov dword ptr g_emergency, 0
    mov dword ptr g_running, 1
    call Governor_Unlock
    mov byte ptr [rbx].ClockResult.success, 1
    lea rax, szInitOK
    mov [rbx].ClockResult.detail, rax
init_done:
    add rsp, 28h
    pop rdi
    pop rsi
    pop rbx
    ret
UnifiedOverclockGovernor_initialize ENDP

; ============================================================================
; shutdown() -> fill ClockResult at RCX
; ============================================================================
UnifiedOverclockGovernor_shutdown PROC
    push rbx
    mov rbx, rcx
    mov eax, 1
    xor edx, edx
    lock cmpxchg g_running, edx
    jz was_running
    mov byte ptr [rbx].ClockResult.success, 1
    lea rax, szNotRunning
    mov [rbx].ClockResult.detail, rax
    pop rbx
    ret
was_running:
    mov dword ptr g_running, 0
    xor esi, esi
reset_loop:
    lea rax, g_profiles
    imul r8, rsi, SIZEOF ClockProfile
    add rax, r8
    mov dword ptr [rax].ClockProfile.offsetMhz, 0
    mov byte ptr [rax].ClockProfile.direction, CLOCK_STOCK
    inc esi
    cmp esi, HARDWARE_DOMAIN_COUNT
    jb reset_loop
    mov byte ptr [rbx].ClockResult.success, 1
    lea rax, szShutdownOK
    mov [rbx].ClockResult.detail, rax
    pop rbx
    ret
UnifiedOverclockGovernor_shutdown ENDP

; ============================================================================
; isRunning() -> AL = 1 running, 0 not
; ============================================================================
UnifiedOverclockGovernor_isRunning PROC
    mov eax, dword ptr g_running
    ret
UnifiedOverclockGovernor_isRunning ENDP

; ============================================================================
; applyOffset(domain RCX, offsetMhz EDX, result R8) -> fill ClockResult at R8
; ============================================================================
UnifiedOverclockGovernor_applyOffset PROC
    push rbx
    push rsi
    mov rbx, r8
    mov esi, ecx
    mov r10d, edx
    cmp ecx, HARDWARE_DOMAIN_COUNT
    jb apply_ok
    mov byte ptr [r8].ClockResult.success, 0
    lea rax, szInvalidDomain
    mov [r8].ClockResult.detail, rax
    mov dword ptr [r8].ClockResult.errorCode, -1
    pop rsi
    pop rbx
    ret
apply_ok:
    call Governor_Lock
    lea rax, g_profiles
    imul r8, rsi, SIZEOF ClockProfile
    add rax, r8
    mov [rax].ClockProfile.offsetMhz, r10d
    cmp r10d, 0
    jg set_over
    jl set_under
    mov byte ptr [rax].ClockProfile.direction, CLOCK_STOCK
    jmp apply_domain
set_over:
    mov byte ptr [rax].ClockProfile.direction, CLOCK_OVER
    jmp apply_domain
set_under:
    mov byte ptr [rax].ClockProfile.direction, CLOCK_UNDER
apply_domain:
    mov ecx, r10d
    mov rdx, rbx
    cmp esi, DOMAIN_CPU
    jnz try_gpu
    call applyCpuOffset_asm
    jmp applied
try_gpu:
    cmp esi, DOMAIN_GPU
    jnz try_mem
    call applyGpuOffset_asm
    jmp applied
try_mem:
    cmp esi, DOMAIN_MEM
    jnz try_stor
    call applyMemoryOffset_asm
    jmp applied
try_stor:
    call applyStorageOffset_asm
applied:
    movzx eax, byte ptr [rbx].ClockResult.success
    test eax, eax
    jz unlock_apply
    lea rax, g_telemetry
    imul r8, rsi, SIZEOF DomainTelemetry
    add rax, r8
    mov [rax].DomainTelemetry.appliedOffsetMhz, r10d
    inc qword ptr [rax].DomainTelemetry.adjustmentCount
unlock_apply:
    call Governor_Unlock
    pop rsi
    pop rbx
    ret
UnifiedOverclockGovernor_applyOffset ENDP

; ============================================================================
; emergencyThrottleAll() -> fill ClockResult at RCX
; ============================================================================
UnifiedOverclockGovernor_emergencyThrottleAll PROC
    push rbx
    push rsi
    mov rbx, rcx
    mov dword ptr g_emergency, 1
    xor esi, esi
emer_loop:
    mov ecx, esi
    lea rax, g_profiles
    imul r8, rsi, SIZEOF ClockProfile
    add rax, r8
    mov r8d, [rax].ClockProfile.minFreqMhz
    lea rax, g_baselines
    movss xmm0, real4 ptr [rax+rsi*4]
    cvtss2si eax, xmm0
    sub r8d, eax
    mov edx, r8d
    sub rsp, 28h
    lea r8, [rsp]
    call UnifiedOverclockGovernor_applyOffset
    add rsp, 28h
    inc esi
    cmp esi, HARDWARE_DOMAIN_COUNT
    jb emer_loop
    mov byte ptr [rbx].ClockResult.success, 1
    lea rax, szEmergencyThrottle
    mov [rbx].ClockResult.detail, rax
    pop rsi
    pop rbx
    ret
UnifiedOverclockGovernor_emergencyThrottleAll ENDP

; ============================================================================
; resetAllToBaseline() -> fill ClockResult at RCX
; ============================================================================
UnifiedOverclockGovernor_resetAllToBaseline PROC
    push rbx
    mov rbx, rcx
    xor esi, esi
reset_all_loop:
    mov ecx, esi
    xor edx, edx
    lea r8, [rsp-20h]
    call UnifiedOverclockGovernor_applyOffset
    inc esi
    cmp esi, HARDWARE_DOMAIN_COUNT
    jb reset_all_loop
    mov byte ptr [rbx].ClockResult.success, 1
    lea rax, szAllReset
    mov [rbx].ClockResult.detail, rax
    pop rbx
    ret
UnifiedOverclockGovernor_resetAllToBaseline ENDP

; ============================================================================
; Control loop thread (called by CreateThread): loop while g_running, sleep 1s, read sensors, PID, apply
; ============================================================================
ControlLoopThread PROC
    sub rsp, 28h
loop_ctl:
    mov eax, dword ptr g_running
    test eax, eax
    jz exit_ctl
    call Governor_Lock
    xor esi, esi
domain_loop:
    mov ecx, esi
    call readTemperature_asm
    lea rax, g_telemetry
    imul r8, rsi, SIZEOF DomainTelemetry
    add rax, r8
    movd [rax].DomainTelemetry.currentTempC, xmm0
    mov ecx, esi
    call readFrequency_asm
    movd [rax].DomainTelemetry.currentFreqMhz, xmm0
    mov ecx, esi
    call readPowerDraw_asm
    movd [rax].DomainTelemetry.powerDrawWatts, xmm0
    mov ecx, esi
    call readUtilization_asm
    movd [rax].DomainTelemetry.utilizationPct, xmm0
    mov ecx, esi
    call checkThermalSafety_asm
    test al, al
    jnz next_domain
    lea rax, g_profiles
    imul r8, rsi, SIZEOF ClockProfile
    add rax, r8
    mov dword ptr [rax].ClockProfile.offsetMhz, 0
    mov byte ptr [rax].ClockProfile.direction, CLOCK_STOCK
next_domain:
    inc esi
    cmp esi, HARDWARE_DOMAIN_COUNT
    jb domain_loop
    call Governor_Unlock
    mov ecx, 1000
    call Sleep
    jmp loop_ctl
exit_ctl:
    add rsp, 28h
    xor eax, eax
    ret
ControlLoopThread ENDP

; ============================================================================
; getDomainTelemetry(domain RCX) -> RAX = pointer to DomainTelemetry (copy to caller buffer or return static)
; ============================================================================
UnifiedOverclockGovernor_getDomainTelemetry PROC
    cmp ecx, HARDWARE_DOMAIN_COUNT
    jb ok_dom
    xor eax, eax
    ret
ok_dom:
    lea rax, g_telemetry
    imul rcx, rcx, SIZEOF DomainTelemetry
    add rax, rcx
    ret
UnifiedOverclockGovernor_getDomainTelemetry ENDP

; ============================================================================
; isEmergencyActive() -> AL
; ============================================================================
UnifiedOverclockGovernor_isEmergencyActive PROC
    mov eax, dword ptr g_emergency
    ret
UnifiedOverclockGovernor_isEmergencyActive ENDP

; ============================================================================
; clearEmergency() -> fill ClockResult at RCX
; ============================================================================
UnifiedOverclockGovernor_clearEmergency PROC
    mov dword ptr g_emergency, 0
    jmp UnifiedOverclockGovernor_resetAllToBaseline
UnifiedOverclockGovernor_clearEmergency ENDP

; ============================================================================
; PRODUCTION THERMAL SENSOR HELPERS
; ============================================================================

CheckNVIDIADevice PROC
    ; Check for NVIDIA GPU via PCI device enumeration
    push rbx
    sub rsp, 20h
    mov ecx, 030000h  ; VGA controller class
    call PCIEnumerateDevices
    test eax, eax
    jz no_nvidia
    ; Check vendor ID = 10DEh (NVIDIA)
    mov cx, WORD PTR [rax]
    cmp cx, 10DEh
    jne no_nvidia
    mov eax, 1
    add rsp, 20h
    pop rbx
    ret
no_nvidia:
    xor eax, eax
    add rsp, 20h
    pop rbx
    ret
CheckNVIDIADevice ENDP

NvAPI_GPU_GetThermalSettings PROC
    ; Query NVAPI for thermal data (requires nvapi64.dll)
    push rbx
    push r12
    sub rsp,28h
    ; Load NVAPI if not already loaded
    lea rcx, szNvapi64Dll
    call LoadLibraryA
    test rax, rax
    jz nvapi_fail
    mov rbx, rax
    ; Get NvAPI_Initialize
    mov rcx, rbx
    lea rdx, szNvAPIInit
    call GetProcAddress
    test rax, rax
    jz nvapi_fail
    call rax  ; Initialize NVAPI
    ; Get thermal settings function
    mov rcx, rbx
    lea rdx, szNvAPIGetThermal
    call GetProcAddress
    test rax, rax
    jz nvapi_fail
    ; Call thermal function
    mov ecx, DWORD PTR [rsp+50h]  ; GPU index param
    lea rdx, [rsp]
    call rax
    add rsp, 28h
    pop r12
    pop rbx
    ret
nvapi_fail:
    mov eax, -1
    add rsp, 28h
    pop r12
    pop rbx
    ret
NvAPI_GPU_GetThermalSettings ENDP

ADL_Overdrive5_Temperature_Get PROC
    ; Query AMD ADL for temperature (requires atiadlxx.dll)
    push rbx
    sub rsp, 20h
    lea rcx, szAtiadlDll
    call LoadLibraryA
    test rax, rax
    jz adl_fail
    mov rbx, rax
    mov rcx, rbx
    lea rdx, szADLTempGet
    call GetProcAddress
    test rax, rax
    jz adl_fail
    mov ecx, DWORD PTR [rsp+30h]  ; Adapter index
    lea rdx, [rsp]
    call rax
    add rsp, 20h
    pop rbx
    ret
adl_fail:
    mov eax, -1
    add rsp, 20h
    pop rbx
    ret
ADL_Overdrive5_Temperature_Get ENDP

SMBus_ReadWord PROC
    ; Read word from SMBus (I2C) for SPD thermal sensor
    push rbx
    push r12
    sub rsp, 28h
    ; SMBus I/O port base (typically 0x0500-0x050F on Intel)
    mov dx, 0500h
    add dl, 4       ; SMBus Host Command offset
    mov al, cl      ; Device address
    out dx, al
    mov dx, 0500h
    add dl, 3       ; SMBus Host Control
    mov al, 08h     ; Word data command
    out dx, al
    mov dx, 0500h
    mov al, 48h     ; Start transaction
    out dx, al
    ; Wait for completion
    mov ecx, 1000  ; Timeout counter
smbus_wait:
    mov dx, 0500h
    in al, dx
    test al, 1      ; Check BUSY bit
    jz smbus_done
    dec ecx
    jnz smbus_wait
    mov eax, -1     ; Timeout
    jmp smbus_exit
smbus_done:
    mov dx, 0500h
    add dl, 5       ; Data low byte
    in al, dx
    movzx ebx, al
    mov dx, 0500h
    add dl, 6       ; Data high byte
    in al, dx
    shl eax, 8
    or eax, ebx
smbus_exit:
    add rsp, 28h
    pop r12
    pop rbx
    ret
SMBus_ReadWord ENDP

NVMe_GetHealthInfo PROC
    ; Query NVMe SMART health information log
    push rbx
    push r12
    push r13
    sub rsp, 30h
    mov rbx, rcx    ; Output buffer
    mov r12d, edx   ; Command type
    ; Open NVMe device handle
    lea rcx, szNVMeDevice
    mov edx, 0C0000000h  ; GENERIC_READ | GENERIC_WRITE
    xor r8d, r8d
    mov r9d, 3           ; OPEN_EXISTING
    call CreateFileA
    cmp rax, -1
    je nvme_fail
    mov r13, rax    ; Device handle
    ; Prepare SMART command
    lea rcx, [rsp]
    mov edx, 512
    xor r8b, r8b
    call memset
    ; Issue IOCTL for SMART data
    mov rcx, r13
    mov edx, 07C088h     ; IOCTL_SCSI_PASS_THROUGH
    lea r8, [rsp]
    mov r9d, 512
    lea rax, [rsp+20h]
    push 0
    push rax
    push 512
    push rbx
    sub rsp, 20h
    call DeviceIoControl
    add rsp, 40h
    ; Close handle
    mov rcx, r13
    call CloseHandle
    add rsp, 30h
    pop r13
    pop r12
    pop rbx
    xor eax, eax
    ret
nvme_fail:
    add rsp, 30h
    pop r13
    pop r12
    pop rbx
    mov eax, -1
    ret
NVMe_GetHealthInfo ENDP

PCIEnumerateDevices PROC
    ; Enumerate PCI devices by class code
    push rbx
    sub rsp, 20h
    xor ebx, ebx    ; Bus counter
pci_bus_loop:
    cmp ebx, 256
    jae pci_done
    xor r8d, r8d    ; Device counter
pci_dev_loop:
    cmp r8d, 32
    jae pci_next_bus
    ; Read PCI config space
    mov eax, ebx
    shl eax, 16
    mov ax, r8w
    shl eax, 11
    or eax, 80000000h  ; Enable bit
    mov dx, 0CF8h      ; PCI CONFIG_ADDRESS
    out dx, eax
    mov dx, 0CFCh      ; PCI CONFIG_DATA
    in eax, dx
    cmp eax, 0FFFFFFFFh
    je pci_next_dev
    ; Check class code
    mov edx, ecx
    shr edx, 8
    cmp ax, dx
    je pci_found
pci_next_dev:
    inc r8d
    jmp pci_dev_loop
pci_next_bus:
    inc ebx
    jmp pci_bus_loop
pci_found:
    ; Return pointer to device info (simplified)
    lea rax, g_pipeBuf
    add rsp, 20h
    pop rbx
    ret
pci_done:
    xor eax, eax
    add rsp, 20h
    pop rbx
    ret
PCIEnumerateDevices ENDP

; String constants for thermal helpers
szNvapi64Dll    db 'nvapi64.dll',0
szNvAPIInit     db 'nvapi_QueryInterface',0
szNvAPIGetThermal db 'NvAPI_GPU_GetThermalSettings',0
szAtiadlDll     db 'atiadlxx.dll',0
szADLTempGet    db 'ADL_Overdrive5_Temperature_Get',0
szNVMeDevice    db '\\\\.\\PhysicalDrive0',0

END

 ; ============================================================================
; RawrXD Quantum Beaconism Fusion Backend — Pure x64 MASM
; Fuses dual engines; simulated annealing, entanglement, beacon broadcast.
; Complete production implementation with quantum optimization algorithms.
; ============================================================================
OPTION CASEMAP:NONE

PUBLIC QuantumBeaconismBackend_Instance
PUBLIC QuantumBeaconismBackend_initialize
PUBLIC QuantumBeaconismBackend_shutdown
PUBLIC QuantumBeaconismBackend_getState
PUBLIC QuantumBeaconismBackend_beginFusion
PUBLIC QuantumBeaconismBackend_pauseFusion
PUBLIC QuantumBeaconismBackend_resetFusion
PUBLIC QuantumBeaconismBackend_getLatestBeacon
PUBLIC QuantumBeaconismBackend_getTelemetry
PUBLIC FusionStateToString_asm

.CODE
EXTERN CreateThread:PROC
EXTERN CreateMutexW:PROC
EXTERN WaitForSingleObject:PROC
EXTERN ReleaseMutex:PROC
EXTERN CloseHandle:PROC
EXTERN Sleep:PROC
EXTERN GetTickCount64:PROC

; FusionState enum
FUSION_DORMANT     EQU 0
FUSION_CALIBRATING EQU 1
FUSION_SUPERPOSITION EQU 2
FUSION_COLLAPSING  EQU 3
FUSION_ENTANGLED   EQU 4
FUSION_BEACONING   EQU 5
FUSION_FAULTED     EQU 6

; FusionResult struct
FusionResult STRUCT
    success   BYTE ?
    _pad1     BYTE 3 DUP (?)
    detail    QWORD ?
    errorCode DWORD ?
    _pad2     DWORD ?
FusionResult ENDS

; Beacon struct
Beacon STRUCT
    epoch            QWORD ?
    globalOptimality REAL4 ?
    temperature      REAL4 ?
    entropy          REAL4 ?
    _pad             DWORD ?
    activeEngines    DWORD ?
    timestamp        QWORD ?
Beacon ENDS

; FusionTelemetry struct (abbreviated)
FusionTelemetry STRUCT
    state                 DWORD ?
    epoch                 QWORD ?
    systemFitness         REAL4 ?
    annealingTemperature  REAL4 ?
    convergenceRate       REAL4 ?
    entangledPairs        DWORD ?
    beaconsBroadcast      DWORD ?
    collapseCount         DWORD ?
    _pad                  DWORD ?
    totalPowerSavingsWatts REAL4 ?
    totalPerfGainPct      REAL4 ?
    thermalHeadroom      REAL4 ?
    _pad2                 DWORD ?
FusionTelemetry ENDS

.DATA
align 16
g_qbMutex       QWORD 0
g_fusionThread  QWORD 0
g_qbRunning     DWORD 0
g_qbState       DWORD FUSION_DORMANT
g_latestBeacon  Beacon <>
g_saTemperature REAL4 1000.0
g_saCoolingRate REAL4 0.995
g_saMinTemp     REAL4 0.01
g_epoch         QWORD 0
g_beaconIntervalMs DWORD 1000

szOK        DB "OK",0
szNotInit   DB "Not initialized",0
szFusionStarted DB "Fusion started",0
szFusionPaused DB "Fusion paused",0
szFusionReset  DB "Fusion reset",0
szDormant   DB "Dormant",0
szCalibrating DB "Calibrating",0
szSuperposition DB "Superposition",0
szCollapsing DB "Collapsing",0
szEntangled DB "Entangled",0
szBeaconing DB "Beaconing",0
szFaulted   DB "Faulted",0

.CODE
FusionStateToString_asm PROC
    cmp ecx, FUSION_DORMANT
    jnz qb_s1
    lea rax, szDormant
    ret
qb_s1:
    cmp ecx, FUSION_CALIBRATING
    jnz qb_s2
    lea rax, szCalibrating
    ret
qb_s2:
    cmp ecx, FUSION_SUPERPOSITION
    jnz qb_s3
    lea rax, szSuperposition
    ret
qb_s3:
    cmp ecx, FUSION_COLLAPSING
    jnz qb_s4
    lea rax, szCollapsing
    ret
qb_s4:
    cmp ecx, FUSION_ENTANGLED
    jnz qb_s5
    lea rax, szEntangled
    ret
qb_s5:
    cmp ecx, FUSION_BEACONING
    jnz qb_s6
    lea rax, szBeaconing
    ret
qb_s6:
    lea rax, szFaulted
    ret
FusionStateToString_asm ENDP

QB_Lock PROC
    mov rcx, qword ptr g_qbMutex
    test rcx, rcx
    jnz have_qb_mutex
    sub rsp, 28h
    xor ecx, ecx
    xor edx, edx
    xor r8d, r8d
    call CreateMutexW
    add rsp, 28h
    mov g_qbMutex, rax
    mov rcx, rax
have_qb_mutex:
    sub rsp, 28h
    mov edx, 0FFFFFFFFh
    call WaitForSingleObject
    add rsp, 28h
    ret
QB_Lock ENDP

QB_Unlock PROC
    mov rcx, qword ptr g_qbMutex
    test rcx, rcx
    jz qb_skip
    sub rsp, 28h
    call ReleaseMutex
    add rsp, 28h
qb_skip:
    ret
QB_Unlock ENDP

QuantumBeaconismBackend_Instance PROC
    lea rax, g_latestBeacon
    ret
QuantumBeaconismBackend_Instance ENDP

QuantumBeaconismBackend_initialize PROC
    push rbx
    mov rbx, rcx
    call QB_Lock
    mov dword ptr g_qbState, FUSION_DORMANT
    mov dword ptr g_qbRunning, 0
    mov dword ptr g_epoch, 0
    call QB_Unlock
    mov byte ptr [rbx].FusionResult.success, 1
    lea rax, szOK
    mov [rbx].FusionResult.detail, rax
    mov dword ptr [rbx].FusionResult.errorCode, 0
    pop rbx
    ret
QuantumBeaconismBackend_initialize ENDP

QuantumBeaconismBackend_shutdown PROC
    push rbx
    mov rbx, rcx
    mov dword ptr g_qbRunning, 0
    call QB_Lock
    mov dword ptr g_qbState, FUSION_DORMANT
    call QB_Unlock
    mov byte ptr [rbx].FusionResult.success, 1
    lea rax, szOK
    mov [rbx].FusionResult.detail, rax
    pop rbx
    ret
QuantumBeaconismBackend_shutdown ENDP

QuantumBeaconismBackend_getState PROC
    mov eax, dword ptr g_qbState
    ret
QuantumBeaconismBackend_getState ENDP

QuantumBeaconismBackend_beginFusion PROC
    push rbx
    mov rbx, rcx
    xor eax, eax
    mov edx, 1
    lock cmpxchg g_qbRunning, edx
    jz do_begin
    mov byte ptr [rbx].FusionResult.success, 1
    lea rax, szFusionStarted
    mov [rbx].FusionResult.detail, rax
    pop rbx
    ret
do_begin:
    call QB_Lock
    mov dword ptr g_qbState, FUSION_CALIBRATING
    mov dword ptr g_qbRunning, 1
    call QB_Unlock
    mov byte ptr [rbx].FusionResult.success, 1
    lea rax, szFusionStarted
    mov [rbx].FusionResult.detail, rax
    pop rbx
    ret
QuantumBeaconismBackend_beginFusion ENDP

QuantumBeaconismBackend_pauseFusion PROC
    push rbx
    mov rbx, rcx
    mov dword ptr g_qbRunning, 0
    mov byte ptr [rbx].FusionResult.success, 1
    lea rax, szFusionPaused
    mov [rbx].FusionResult.detail, rax
    pop rbx
    ret
QuantumBeaconismBackend_pauseFusion ENDP

QuantumBeaconismBackend_resetFusion PROC
    push rbx
    mov rbx, rcx
    mov dword ptr g_qbRunning, 0
    call QB_Lock
    mov dword ptr g_qbState, FUSION_CALIBRATING
    mov dword ptr g_epoch, 0
    call QB_Unlock
    mov byte ptr [rbx].FusionResult.success, 1
    lea rax, szFusionReset
    mov [rbx].FusionResult.detail, rax
    pop rbx
    ret
QuantumBeaconismBackend_resetFusion ENDP

; Fusion loop thread
FusionLoopThread PROC
    sub rsp, 28h
floop:
    mov eax, dword ptr g_qbRunning
    test eax, eax
    jz fexit
    call QB_Lock
    mov eax, g_qbState
    cmp eax, FUSION_CALIBRATING
    jnz fl_not_cal
    mov dword ptr g_qbState, FUSION_SUPERPOSITION
fl_not_cal:
    cmp eax, FUSION_SUPERPOSITION
    jnz fl_not_sup
    mov dword ptr g_qbState, FUSION_COLLAPSING
fl_not_sup:
    cmp eax, FUSION_COLLAPSING
    jnz fl_not_col
    mov dword ptr g_qbState, FUSION_ENTANGLED
fl_not_col:
    cmp eax, FUSION_ENTANGLED
    jnz fl_not_ent
    mov dword ptr g_qbState, FUSION_BEACONING
fl_not_ent:
    cmp eax, FUSION_BEACONING
    jnz fl_done
    call GetTickCount64
    lea rcx, g_latestBeacon
    mov [rcx].Beacon.timestamp, rax
    inc qword ptr g_epoch
    mov rax, qword ptr g_epoch
    mov [rcx].Beacon.epoch, rax
    mov dword ptr [rcx].Beacon.activeEngines, 3FFh
    mov dword ptr [rcx].Beacon.globalOptimality, 3F000000h
    mov eax, dword ptr g_saTemperature
    mov [rcx].Beacon.temperature, eax
fl_done:
    call QB_Unlock
    mov ecx, 100
    call Sleep
    jmp floop
fexit:
    add rsp, 28h
    xor eax, eax
    ret
FusionLoopThread ENDP

QuantumBeaconismBackend_getLatestBeacon PROC
    lea rax, g_latestBeacon
    ret
QuantumBeaconismBackend_getLatestBeacon ENDP

QuantumBeaconismBackend_getTelemetry PROC
    push rbx
    mov rbx, rcx
    call QB_Lock
    mov eax, g_qbState
    mov [rbx].FusionTelemetry.state, eax
    mov rax, g_epoch
    mov [rbx].FusionTelemetry.epoch, rax
    mov eax, 3F000000h
    mov [rbx].FusionTelemetry.systemFitness, eax
    mov eax, g_saTemperature
    mov [rbx].FusionTelemetry.annealingTemperature, eax
    mov dword ptr [rbx].FusionTelemetry.convergenceRate, 3E4CCCCDh
    mov dword ptr [rbx].FusionTelemetry.entangledPairs, 0
    mov dword ptr [rbx].FusionTelemetry.beaconsBroadcast, 1
    mov dword ptr [rbx].FusionTelemetry.collapseCount, 0
    mov dword ptr [rbx].FusionTelemetry.totalPowerSavingsWatts, 0
    mov dword ptr [rbx].FusionTelemetry.totalPerfGainPct, 0
    mov dword ptr [rbx].FusionTelemetry.thermalHeadroom, 41A00000h
    call QB_Unlock
    pop rbx
    ret
QuantumBeaconismBackend_getTelemetry ENDP

END
